const Ownership = @This();

pub const none: u32 = std.math.maxInt(u32);
/// An entry's derivation (`Entry.approx`) when no call put it there: a place
/// that stands for more than one: a level of a recursive value, which
/// folding merged with the levels below it (§16.7).
pub const approx_place: u32 = std.math.maxInt(u32);
/// §16.7 (e): a place that stands for several levels of one region of a
/// recursive value, where a projection took one level out of the marker
/// `⟨T⟩` that keeps them as one place. A holder found so is the cause
/// `level`: the checker cannot tell the levels apart.
pub const approx_level: u32 = std.math.maxInt(u32) - 1;

/// Depth of a walk over a type before it answers conservatively.
const type_depth: u32 = 16;
const debug_own = false;
/// §31.12's mutation controls (`zig build test-record-mutations`): the record
/// demand broken one way on purpose, chosen at build time. `none` in every
/// build but that step's: one `ownership_options` module is imported by
/// every build of the compiler (self-hosted, LLVM, wasm), the option defaults
/// to `none`, `gates` refuses it, a value it does not name is a compile error,
/// and the unit test below fails a `zig build test` given one.
const record_mutation: enum { none, hoist_whole, no_held_operand, no_disjoint, call_as_hoist, wrong_placement } = blk: {
    const m = @import("ownership_options").record_mutation;
    if (std.mem.eql(u8, m, "none")) break :blk .none;
    if (std.mem.eql(u8, m, "hoist-whole")) break :blk .hoist_whole;
    if (std.mem.eql(u8, m, "no-held-operand")) break :blk .no_held_operand;
    if (std.mem.eql(u8, m, "no-disjoint")) break :blk .no_disjoint;
    if (std.mem.eql(u8, m, "call-as-hoist")) break :blk .call_as_hoist;
    if (std.mem.eql(u8, m, "wrong-placement")) break :blk .wrong_placement;
    @compileError("-Downership-record-mutation: unknown mutation '" ++ m ++ "'");
};

test "the record demand is not mutated outside its mutation controls" {
    try std.testing.expectEqual(.none, record_mutation);
}

/// §30.9: a supply of at most this many cells is probed cell by cell.
const split_cap: usize = 8;
/// §16.7: the most entries a summary may hold at one path — `res`'s
/// provenances at one result path, `supply`'s at one `(j, k, q)`.
pub const path_entry_cap: usize = 4096;
/// §16.7: the most entries a summary may hold in all: `use`, `res` and
/// `supply` together.
pub const entry_cap: usize = 1 << 18;
/// §16.7: the most atoms a summary's conditions may hold in all.
pub const condition_cap: usize = 1 << 20;
/// §16.6: the backstop on a recursive group's rounds.
pub const round_cap: u32 = 32;
/// §16.7: the most distinct `returns owned` atoms a summary's `owned` bits
/// rest on.
pub const atom_cap: u32 = 8;
/// §20.4: a value this wide is indexed by its first step when projected.
const wide_index: usize = 256;
/// The thresholds below choose between two ways to one answer (#716): the
/// direct one, cheaper when small, and the one that stays linear when wide.
/// `-Downership-full-cross-check` takes the wide way everywhere, so that
/// its checks against the direct one run over the whole corpus.
const wide_ways = @import("ownership_options").full_cross_check;
/// A union of more than `union_merge_min` entries in more than
/// `union_merge_parts` parts merges them (`unionOf`).
const union_merge_min: usize = if (wide_ways) 0 else 64;
const union_merge_parts: usize = if (wide_ways) 1 else 8;
/// A record type wider than this has its closed updates' splits kept
/// (`Walker.split_memo`, `readOffFrame`).
const split_memo_min: usize = if (wide_ways) 0 else 8;
/// A declaration with more locals than this keeps the log its demands
/// look for holders in (`Walker.bound_log`).
const holder_scan_max: usize = if (wide_ways) 0 else 64;
/// A value at least this wide, and narrower than `wide_index`, is projected
/// through a `StepIndex` where its holder keeps one (`projArg`,
/// `projPathVia`).
const step_index_min: usize = if (wide_ways) 0 else 32;

/// §20.4 (#825): a value's entries by their first step, for a value its
/// holder keeps unchanged while it projects it again and again. It holds
/// positions in the value, in the value's order: those every step acts on
/// (ε, and `⋆`, a marker or a cast first) and those of each first step. A projection
/// through it acts on the entries the direct scan acts on, in the order the
/// scan acts on them, and skips only entries the scan does nothing with, so
/// it interns what the scan interns, in the same order.
const StepIndex = struct {
    av: []const Entry = &.{},
    built: bool = false,
    always: std.ArrayList(u32) = .empty,
    by: std.AutoHashMapUnmanaged([2]u32, std.ArrayList(u32)) = .empty,
};

/// The arguments of one instantiation of a summary (`InstCtx.args`), each
/// with its `StepIndex` once a provenance projects it.
const ArgIndex = struct {
    avs: []const []const Entry,
    of: []StepIndex = &.{},
};

const WideIndex = struct {
    roots: std.ArrayList(Entry) = .empty,
    any: std.ArrayList(Entry) = .empty,
    /// Entries under a marker first (§16.7), kept by `underMarker`.
    levels: std.ArrayList(Entry) = .empty,
    by: std.AutoHashMapUnmanaged([2]u32, std.ArrayList(Entry)) = .empty,
};

/// The retired value-cells limit, retained only for its diagnostic wire ordinal.
const retired_deep_cap: usize = 256;
/// How deep a callback's result is instantiated through another's (§16.7's
/// `callbacks` limit).
const inst_depth: u32 = 4;

pub const Position = struct { line: u32, col: u32 };

pub const Positions = struct {
    ctx: *const anyopaque,
    get: *const fn (ctx: *const anyopaque, module: u32, token: u32) Position,
};

pub const Input = struct {
    gpa: Allocator,
    /// DAG worker: only this module may be walked. Imports are immutable blocks.
    single_module: ?u32 = null,
    tid: u32 = 0,
    expected_sites: []const ?[]const [6]u64 = &.{},
    graph: *const Graph,
    /// Per module index.
    birs: []const *const Bir,
    provenance: []const Interface.Provenance,
    /// Per module index: its interface, for an imported schema constructor
    /// (`ext_schema_ctor`); shorter when none is known.
    interfaces: []const Interface = &.{},
    /// Per module index; shorter when a module was not checked.
    dispatch: []const Dispatch,
    /// Per module index: the kept check tables; shorter, or with an empty
    /// `inst_type`, when a module was not checked.
    modules: []Check.Module,
    types: *const Types,
    interner: *const InternPool.Global,
    /// Per module index.
    module_names: []const []const u8,
    packages: []const SourceStore.Package,
    /// Per module index: the file's token tags.
    spans: []const Token.Spans,
    /// Per module index: the file's bytes, for a message's places (§28.6);
    /// shorter when the caller has none.
    sources: []const []const u8 = &.{},
    positions: Positions,
    /// Per module index: the name of the platform package it belongs to
    /// (the chain layer's manifest `"name"`), empty for any other; what
    /// platform-qualified report names use. Shorter when no chain is known.
    platform_names: []const []const u8 = &.{},
    /// Per module index: the summary block (§28.4) of a module the run did
    /// not check, which the pass reads in place of a walk. Shorter, or null,
    /// for a module with none.
    blocks: []const ?[]const u8 = &.{},
    /// `--ownership-records-lost` (§31.4 item 6, hidden and test-only): every
    /// cell's record condition fails approximately, which no list's verdict
    /// may notice.
    records_lost: bool = false,
    /// Render source-position hoist lines for the ownership dump only.
    format_hoists: bool = false,
    /// Render each declaration's summary line, which only the ownership
    /// dump prints (#684): a build would render them for no reader.
    format_summaries: bool = false,
    /// §28.3: a checked module is read by another module through its block,
    /// written and read back, as an installed one is — so that the verdicts
    /// are the ones a build that installed it would give, and the block's
    /// format is exercised by every report.
    seal: bool = true,
    /// Where each reported module's walk and the blocks' reading are timed
    /// (`ownership_module`, `ownership_blocks`), on this module's worker.
    profile: ?*Profile = null,
    /// Test-only (`--ownership-flips`, §24.6): one declaration's words read
    /// with some flipped, to show that the fixture pinning them depends on
    /// them.
    flip: ?Flip = null,
    /// §16.7, *The canonical form*: false only for the expanded report a
    /// cross-check compares the canonical one with.
    canonical: bool = true,
};

/// §24.6: a declaration's ownership words with some changed, `Module.name`
/// and per edit a position (a parameter from 0, or `Bir.own_result`), the
/// word taken away and the word put there — either may be none.
pub const Flip = struct {
    module: []const u8,
    decl: []const u8,
    edits: []const Edit,

    pub const Edit = struct { slot: u32, from: ?Ast.OwnWord, to: ?Ast.OwnWord };

    /// `Module.name:<slot>:<from>><to>[+<slot>:<from>><to>…]`, a slot a
    /// parameter from 1 or `res`, a word or `-`; null when malformed.
    pub fn parse(gpa: Allocator, text: []const u8) Allocator.Error!?Flip {
        const colon = std.mem.indexOfScalar(u8, text, ':') orelse return null;
        const name = text[0..colon];
        const dot = std.mem.lastIndexOfScalar(u8, name, '.') orelse return null;
        var edits: std.ArrayList(Edit) = .empty;
        var parts = std.mem.splitScalar(u8, text[colon + 1 ..], '+');
        while (parts.next()) |part| {
            const c = std.mem.indexOfScalar(u8, part, ':') orelse return null;
            const gt = std.mem.indexOfScalar(u8, part, '>') orelse return null;
            if (gt < c) return null;
            const slot: u32 = if (std.mem.eql(u8, part[0..c], "res")) Bir.own_result else (std.fmt.parseUnsigned(u32, part[0..c], 10) catch return null) -% 1;
            const word = struct {
                fn f(t: []const u8) error{Bad}!?Ast.OwnWord {
                    if (std.mem.eql(u8, t, "-")) return null;
                    return std.meta.stringToEnum(Ast.OwnWord, t) orelse error.Bad;
                }
            }.f;
            const from = word(part[c + 1 .. gt]) catch return null;
            const to = word(part[gt + 1 ..]) catch return null;
            try edits.append(gpa, .{ .slot = slot, .from = from, .to = to });
        }
        return .{ .module = name[0..dot], .decl = name[dot + 1 ..], .edits = edits.items };
    }
};

/// §8.2; `entry` §20.6.
pub const Accept = enum { fresh, call, param, callback_param, once, entry };

/// §8.3, in its order, then §16.11's.
pub const Cause = enum {
    unknown,
    escaped,
    top_level,
    captured_edit,
    disjoint,
    held_operand,
    later_use,
    alias,
    captured,
    element,
    call,
    supply,
    need,
    limit,
    /// §18.4: a write that needs exclusive contents where they may share.
    exclusive,
    /// §18.8: a closure that writes what it captured may run more than once.
    once,
    /// §20.5: a message's payload may still be held by its sender.
    payload,
    /// §20.3: `view` and `subscriptions` receive the model to read only.
    read_only,
    /// §16.7 (e): a holder another level of the same region may be; the
    /// checker keeps one place for the levels of a recursive value.
    level,

    pub fn text(c: Cause) []const u8 {
        return switch (c) {
            .unknown => "unknown",
            .escaped => "escaped",
            .top_level => "top-level",
            .captured_edit => "captured-edit",
            .disjoint => "disjoint",
            .held_operand => "held-operand",
            .later_use => "later-use",
            .alias => "alias",
            .captured => "captured",
            .element => "element",
            .call => "call",
            .supply => "supply",
            .need => "need",
            .limit => "limit",
            .exclusive => "exclusive",
            .once => "once",
            .payload => "payload",
            .read_only => "read-only",
            .level => "level",
        };
    }

    /// The default derivation of a cause (thesis §8.4); `supply` is
    /// decided per rejection (§16.11).
    pub fn approximate(c: Cause) bool {
        return switch (c) {
            .unknown, .escaped, .captured_edit, .element, .call, .limit, .exclusive, .payload, .level => true,
            else => false,
        };
    }
};

pub const Verdict = union(enum) {
    accepted: Accept,
    /// An obligation slice 2 does not discharge (§16.5).
    pending,
    rejected: Cause,
};

/// One line of the report (§9.1, §16.11).
pub const Demand = struct {
    position: Position,
    /// `construction`, `++`, `List.<writer>`, `call M.f`, or `value`.
    op: []const u8,
    base: []const u8,
    verdict: Verdict,
    /// For a rejection or a pending line, the reason after the cause.
    detail: []const u8,
    /// The summary that decided it, printed in parentheses.
    note: []const u8 = "",
    /// An acceptance that rests on a callee with no summary (§15 decision 2).
    assumed: bool = false,
    /// A rejection's derivation.
    approx: bool = false,
    /// §28.6: the places a message names, as tokens of the module — `none`
    /// where there is none. The demand's own token; the first and last token
    /// of the edit, and of its base when the base is written in the source.
    token: u32 = none,
    span: [2]u32 = .{ none, none },
    base_span: [2]u32 = .{ none, none },
    /// The holder a Dead failure names (§8.3): its name, where it was bound,
    /// and the use after the demand that keeps it live.
    holder: []const u8 = "",
    keep_token: u32 = none,
    /// The read: the variable path as written, when it is one, else its
    /// consumer.
    read_span: [2]u32 = .{ none, none },
    /// The call an approximate holder holds it through, or the operand a
    /// `held-operand` failure waits on.
    via_token: u32 = none,
    /// `top-level`: the top-level value, `(module, declaration, 1 when the
    /// list is the value itself)`.
    top: ?[3]u32 = null,
    /// §31.3: a record update's demand, reported and never enforced until
    /// §31.9's codes land (#315, R4).
    record: bool = false,
    /// §31.12: what a record rejection's fix is: `copy` or `restructure`.
    fix: Fix = .none,
    /// §31.14: an accepted record demand's later reads of a written field,
    /// which the lowering reads first.
    hoists: u32 = 0,
};

/// §31.12: the fix a record rejection takes.
pub const Fix = enum {
    none,
    /// `{ Record.copy r | … }`: a whole use the copy answers.
    copy,
    /// A top-level base made a function, or the program reordered.
    restructure,

    pub fn text(f: Fix) []const u8 {
        return @tagName(f);
    }
};

/// One summary line (§16.11).
pub const SummaryLine = struct { text: []const u8 };

pub const ModuleReport = struct {
    module: u32,
    checked: bool,
    demands: []const Demand,
    summaries: []const SummaryLine = &.{},
    /// §16.7: the checker's limits its declarations reached, each an error.
    limits: []const LimitLine = &.{},
    /// §31.6: the captures of a record's field path its lambdas read when
    /// they are made, counted for report mode (§31.12).
    eager_reads: u32 = 0,
    hoist_table: Hoists.Table = .empty,
    hoist_lines: []const SummaryLine = &.{},
};

/// A limit a declaration of the module reached (§16.7): the declaration's
/// index and name, which limit, and what it measured.
pub const LimitLine = struct { decl: u32, name: []const u8, limit: Limit, at: u32 };

// ---------------------------------------------------------------------------
// Summaries (§16.2)
// ---------------------------------------------------------------------------

pub const bit_r: u16 = 1;
pub const bit_a: u16 = 2;
pub const bit_e: u16 = 4;
pub const bit_w: u16 = 8;
/// With `bit_w`: some demand writes the path through exact steps only; a
/// W without it was derived through an approximate one (thesis §8.4).
pub const bit_x: u16 = 16;
/// §18.6: escaped, and only by a function value handed to JavaScript that
/// captured it — Change 5's words would decide it; printed `J`.
pub const bit_j: u16 = 64;
/// With `bit_w`: §23.2, a send's write — every cell at or below the path is
/// given up, not only the one at it; printed `S` (`s` when approximate).
pub const bit_d: u16 = 128;
/// §31.7: a record update writes the record object at the path, the fields
/// `UseEntry.fields` names; printed `W{…}`. No list fact reads it.
pub const bit_f: u16 = 256;
/// §31.4 item 5: the body reads the record at the path, a field read a
/// caller's record demand reads through the summary; printed with `R`. No
/// list fact reads it.
pub const bit_q: u16 = 512;
/// §31.4 item 2: the body keeps the record object at the path; printed with
/// `E`. No list fact reads it.
pub const bit_k: u16 = 1024;
/// What the entry escapes for a use's bits: a list's facts. A record
/// object's (`bit_k`) is `escapeObjects`', which escapes the object
/// alone, so that no list below it moves.
fn entryBits(bits: u16) u8 {
    return @truncate(bits & list_bits);
}

/// The bits a list's facts read.
const list_bits: u16 = bit_r | bit_a | bit_e | bit_w | bit_x | bit_j | bit_d;

/// §32's dated write-extent amendment. Unclassified writes remain deep.
pub const WriteExtent = enum(u8) { storage, deep };

pub const UseEntry = struct {
    grown: Grown = 0,
    param: u32,
    path: u32,
    bits: u16,
    extent: WriteExtent = .deep,
    /// With `bit_f`: the fields a record update writes at the path, sorted
    /// (§31.7). Empty is every field (`unionFields`): a write a block could
    /// not name, an open type's, a callback's loan.
    fields: []const u32 = &.{},
};

fn useEql(a: UseEntry, b: UseEntry) bool {
    return a.param == b.param and a.path == b.path and a.bits == b.bits and a.extent == b.extent and a.grown == b.grown and std.mem.eql(u32, a.fields, b.fields);
}

pub const ProvKind = enum(u8) { param, fresh, esc, shared, top, cb, env, klass };

/// `top`'s `a` (a provenance's and a cell's): 0 a value from JavaScript, 1 a
/// pessimistic summary's (§16.7), 2 `input_marker` and `unfollowed` a
/// schema's (§30.10), and `top_call` the result of a call of a function the
/// checker cannot identify, printed `⊤call` (§30.11).
const top_call: u32 = 4;

/// `top`'s `a` for §6.1's call of a function value that may be one of
/// several classes the walk knows and does not join (#278), printed
/// `⊤call`. Not 5, which another open change takes.
const top_several: u32 = 6;

/// A provenance (thesis §3.7's `Prov`). `param`: `a` the parameter's index
/// from 0, `path` its path. `fresh`/`esc`: `a` the number, from 1 (0 in a
/// supply, where it is not compared). `shared`: `a` the module, `b` the
/// declaration, `path` the path in it. `cb`: `a` the function parameter's
/// index. `env` (a lambda's class only): `a` the captured local, `path`.
pub const Prov = struct {
    kind: ProvKind,
    a: u32 = 0,
    b: u32 = 0,
    path: u32 = 0,
    /// `param`, in a supply or the traversal primitive's result: an element
    /// taken out of its container by a destructive read (§18.5).
    taken: bool = false,
    /// §31.7: the record object alone, not what is below it — a record
    /// literal's, an update's, a record of numbers; printed with `◦`. No
    /// list's fact reads it.
    obj: bool = false,
    /// §16.7: a condition on this containing value, never an allocation.
    condition_only: bool = false,

    fn eql(x: Prov, y: Prov) bool {
        return x.kind == y.kind and x.a == y.a and x.b == y.b and x.path == y.path and x.taken == y.taken and x.obj == y.obj and x.condition_only == y.condition_only;
    }

    fn less(x: Prov, y: Prov) bool {
        if (x.kind != y.kind) return @backingInt(x.kind) < @backingInt(y.kind);
        if (x.a != y.a) return x.a < y.a;
        if (x.b != y.b) return x.b < y.b;
        if (x.path != y.path) return x.path < y.path;
        if (x.taken != y.taken) return @intFromBool(x.taken) < @intFromBool(y.taken);
        if (x.condition_only != y.condition_only) return @intFromBool(x.condition_only) < @intFromBool(y.condition_only);
        return @intFromBool(x.obj) < @intFromBool(y.obj);
    }
};

/// §18.2–§18.3: an atom of an exclusivity condition, over a summary's
/// parameters. `excl a`: `a` is deeply exclusive. `sep a b`: `a` and `b`
/// share no cell; `sep cb_j cb_j`: two calls of `π_j` return none in common.
/// `keep a b` (`focus`'s row only): the callback `a`, handed an element of
/// `b` destructively, returns what keeps `b` exclusive (the thesis's "keeps
/// shape").
/// `sep_root` separates one selected array from everything the other value
/// holds; on an annotation, only its selected side follows projection.
/// `spine`, `sep_spine` and `keep_spine` state the corresponding conditions
/// for the containers at the named paths, without owning their contents
/// (the dated fold-invariant amendment).
/// `apart G₁ … Gₙ` (§16.7, amended 2026-10-22, #693): no member of one group
/// shares a cell with a member of another — the conjunction of `sep a b` for
/// every two members of distinct groups, its *expansion*; `apart_spine` is
/// the same of `sep_spine`. Its groups are in `groups`, canonical
/// (`apartAtoms`), and `a` and `b` are unused.
pub const XAtom = struct {
    kind: enum(u8) { excl, sep, keep, spine, keep_spine, sep_spine, apart, apart_spine, sep_root },
    a: Prov = .{ .kind = .top, .a = 0 },
    b: Prov = .{ .kind = .top, .a = 0 },
    groups: []const []const Prov = &.{},

    pub fn isApart(x: XAtom) bool {
        return x.kind == .apart or x.kind == .apart_spine;
    }

    fn eql(x: XAtom, y: XAtom) bool {
        if (x.kind != y.kind or !x.a.eql(y.a) or !x.b.eql(y.b)) return false;
        if (x.groups.len != y.groups.len) return false;
        if (x.groups.ptr == y.groups.ptr) return true;
        for (x.groups, y.groups) |g, h| {
            if (g.len != h.len) return false;
            for (g, h) |p, q| if (!p.eql(q)) return false;
        }
        return true;
    }

    fn less(x: XAtom, y: XAtom) bool {
        if (x.kind != y.kind) return @backingInt(x.kind) < @backingInt(y.kind);
        if (x.isApart()) return groupsLess(x.groups, y.groups);
        if (!x.a.eql(y.a)) return x.a.less(y.a);
        return x.b.less(y.b);
    }

    /// The atoms this one stands for, in the condition's own measure: an
    /// apart's members (the `conditions` limit, §16.7).
    pub fn weight(x: XAtom) usize {
        var n: usize = 0;
        for (x.groups) |g| n += g.len;
        return if (x.isApart()) n else 1;
    }
};

fn provsLess(g: []const Prov, h: []const Prov) bool {
    if (g.ptr == h.ptr and g.len == h.len) return false;
    for (g[0..@min(g.len, h.len)], h[0..@min(g.len, h.len)]) |p, q| {
        if (!p.eql(q)) return p.less(q);
    }
    return g.len < h.len;
}

fn groupsLess(x: []const []const Prov, y: []const []const Prov) bool {
    if (x.ptr == y.ptr and x.len == y.len) return false;
    for (x[0..@min(x.len, y.len)], y[0..@min(x.len, y.len)]) |g, h| {
        if (provsLess(g, h)) return true;
        if (provsLess(h, g)) return false;
    }
    return x.len < y.len;
}

/// The number of pairs an apart over groups of these sizes expands to, and
/// its members.
fn apartCounts(sizes: anytype) struct { pairs: usize, members: usize } {
    var members: usize = 0;
    var pairs: usize = 0;
    for (sizes) |s| {
        pairs += members * s;
        members += s;
    }
    return .{ .pairs = pairs, .members = members };
}

/// §16.7 (#693): the atoms that say `groups` are pairwise apart, as `kind`
/// (`apart` or `apart_spine`), appended to `out`: each group's members in
/// order and distinct, empty groups dropped, the groups in order; one apart
/// when its expansion has more atoms than it has members, else the
/// expansion itself. `groups` and its slices may be reordered in place.
pub fn apartAtoms(a: Allocator, kind: @FieldType(XAtom, "kind"), groups_in: [][]Prov, out: *std.ArrayList(XAtom)) Allocator.Error!void {
    std.debug.assert(kind == .apart or kind == .apart_spine);
    var groups: std.ArrayList([]const Prov) = .empty;
    for (groups_in) |g| {
        std.mem.sort(Prov, g, {}, struct {
            fn lt(_: void, p: Prov, q: Prov) bool {
                return p.less(q);
            }
        }.lt);
        var n: usize = 0;
        for (g) |p| {
            if (n > 0 and g[n - 1].eql(p)) continue;
            g[n] = p;
            n += 1;
        }
        if (n > 0) try groups.append(a, g[0..n]);
    }
    if (groups.items.len < 2) return;
    std.mem.sort([]const Prov, groups.items, {}, struct {
        fn lt(_: void, g: []const Prov, h: []const Prov) bool {
            return provsLess(g, h);
        }
    }.lt);
    var sizes = try a.alloc(usize, groups.items.len);
    for (groups.items, 0..) |g, i| sizes[i] = g.len;
    const c = apartCounts(sizes);
    if (c.pairs > c.members) {
        try out.append(a, .{ .kind = kind, .groups = groups.items });
        return;
    }
    const pair_kind: @FieldType(XAtom, "kind") = if (kind == .apart) .sep else .sep_spine;
    for (groups.items, 0..) |g, i| for (groups.items[i + 1 ..]) |h| for (g) |p| for (h) |q| {
        var t = sepAtom(p, q);
        t.kind = pair_kind;
        try out.append(a, t);
    };
}

/// An apart's expansion (§16.7, #693), appended to `out`; any other atom
/// as it is.
pub fn expandAtom(a: Allocator, x: XAtom, out: *std.ArrayList(XAtom)) Allocator.Error!void {
    if (!x.isApart()) return out.append(a, x);
    const pair_kind: @FieldType(XAtom, "kind") = if (x.kind == .apart) .sep else .sep_spine;
    for (x.groups, 0..) |g, i| for (x.groups[i + 1 ..]) |h| for (g) |p| for (h) |q| {
        var t = sepAtom(p, q);
        t.kind = pair_kind;
        try out.append(a, t);
    };
}

/// `atoms` with every apart expanded, sorted and distinct.
pub fn expandAtoms(a: Allocator, atoms: []const XAtom) Allocator.Error![]const XAtom {
    var out: std.ArrayList(XAtom) = .empty;
    for (atoms) |x| try expandAtom(a, x, &out);
    return sortAtoms(out.items);
}

/// Atoms whose slices are `a`'s own, an apart's groups included.
pub fn dupeAtoms(a: Allocator, atoms: []const XAtom) Allocator.Error![]const XAtom {
    const out = try a.dupe(XAtom, atoms);
    for (out) |*x| if (x.isApart()) {
        const gs = try a.alloc([]const Prov, x.groups.len);
        for (gs, x.groups) |*d, g| d.* = try a.dupe(Prov, g);
        x.groups = gs;
    };
    return out;
}

/// The atoms of a condition, in the `conditions` limit's measure.
fn atomsWeight(atoms: []const XAtom) usize {
    var n: usize = 0;
    for (atoms) |x| n += x.weight();
    return n;
}

/// §18.2: an exclusivity condition, as a summary states it.
pub const XSum = struct {
    /// 0: holds, given `atoms`; 1: fails, approximately; 2: fails, exactly.
    no: u8 = 0,
    atoms: []const XAtom = &.{},

    fn eql(x: XSum, y: XSum) bool {
        if (x.no != y.no or x.atoms.len != y.atoms.len) return false;
        if (x.atoms.ptr == y.atoms.ptr) return true;
        for (x.atoms, y.atoms) |a, b| if (!a.eql(b)) return false;
        return true;
    }
};

/// §16.7's mark (F3, the owner's choice (a)), in memory while a group is
/// solved: bit 0 marks a path below a variable that a recursive call grew
/// at a structure; bits 1–30 hold 1 + a *pending* boundary, a path depth,
/// for a symbolic cell at such a variable: its places below that many
/// steps are below the variable. The annotation boundary is in the 33
/// bits above (`grown_guard`). Both hold any path depth: there is no path
/// cut (§16.7 (c)), and no path is deeper than 2³⁰ − 2 steps (`rawChild`
/// asserts it: its steps alone would fill memory). A group clears its
/// members' marks when it settles, so no settled summary carries one and
/// the summary block does not.
pub const Grown = u64;
/// The mark and the pending boundary.
const grown_low: Grown = (@as(Grown, 1) << grown_guard) - 1;
/// Where the annotation boundary begins.
const grown_guard = 31;
fn gMarked(g: Grown) bool {
    return g & 1 != 0;
}
fn gPending(g: Grown) ?usize {
    const x = (g & grown_low) >> 1;
    return if (x == 0) null else @intCast(x - 1);
}
fn gMake(marked: bool, pending: ?usize) Grown {
    const x: Grown = if (pending) |b| @as(Grown, @as(u30, @intCast(b))) + 1 else 0;
    return (x << 1) | @intFromBool(marked);
}
/// Two marks at one result path: keep either mark and the nearer pending
/// boundary. A larger guard distance means an earlier boundary above this
/// path, so folding there conservatively includes both sources' aliases.
fn gJoin(a: Grown, b: Grown) Grown {
    const pa = gPending(a);
    const pb = gPending(b);
    const pend: ?usize = if (pa) |x| (if (pb) |y| @min(x, y) else x) else pb;
    return gMake(gMarked(a) or gMarked(b), pend) | (@max(a >> grown_guard, b >> grown_guard) << grown_guard);
}
/// A symbolic cell's mark one step further down: the boundary is a step
/// nearer, and a cell already below stays below.
fn gStep(g: Grown) Grown {
    const pend = gPending(g) orelse return g;
    return gMake(gMarked(g), if (pend > 0) pend - 1 else 0) | (g & ~grown_low);
}

/// A projected annotation's boundary may lie above its current result path.
/// The upper bits hold one plus the number of path steps below that boundary;
/// they represent the full u32 path-depth range without truncation.
/// Like the ordinary growth mark, it is cleared when the group settles.
fn gGuard(g: Grown) ?u32 {
    const encoded = g >> grown_guard;
    return if (encoded == 0) null else @intCast(encoded - 1);
}
fn gGuardAt(g: Grown, distance: u32) Grown {
    return (g & grown_low) | ((@as(Grown, distance) + 1) << grown_guard);
}
fn gDropGuard(g: Grown, depth: u32) Grown {
    const distance = gGuard(g) orelse return g;
    return if (depth <= distance and distance > 0) gGuardAt(g, distance - 1) else g;
}

test "annotation growth preserves deep boundaries and joins at the earlier boundary" {
    const low = gMake(true, 7);
    for ([_]u32{ 254, 255, 65535, std.math.maxInt(u32) }) |distance| {
        const marked = gGuardAt(low, distance);
        try std.testing.expectEqual(@as(?u32, distance), gGuard(marked));
        try std.testing.expect(gMarked(marked));
        try std.testing.expectEqual(@as(?usize, 7), gPending(marked));
        const stepped = gStep(marked);
        try std.testing.expectEqual(@as(?u32, distance), gGuard(stepped));
        try std.testing.expectEqual(@as(?usize, 6), gPending(stepped));
    }
    const later = gGuardAt(gMake(false, 7), 2);
    const earlier = gGuardAt(gMake(true, 3), 5);
    const joined = gJoin(later, earlier);
    try std.testing.expectEqual(@as(?u32, 5), gGuard(joined));
    try std.testing.expectEqual(@as(?usize, 3), gPending(joined));
    try std.testing.expect(gMarked(joined));
    try std.testing.expectEqual(earlier, gJoin(0, earlier));
    try std.testing.expectEqual(earlier, gJoin(earlier, 0));
    // §16.7 (c): no path cut, so a pending boundary is any path depth.
    for ([_]usize{ 126, 127, 1000, std.math.maxInt(u30) - 1 }) |b| try std.testing.expectEqual(@as(?usize, b), gPending(gMake(true, b)));
}

/// `rxc`: the record condition (§31.4 item 6), failing approximately unless
/// a read-off or a row says otherwise.
pub const ResEntry = struct { path: u32, prov: Prov, approx: bool = false, xc: XSum = .{}, sc: XSum = .{}, grown: Grown = 0, rxc: XSum = .{ .no = 1 } };

/// A path's container condition, without a deep condition. Such an
/// annotation describes its value, not an alternative allocation. Its
/// record condition is not read: whether a path has several choices decides
/// how a list's entries are approximated, and a list's line reads no record
/// condition (§31.4 item 6, #773).
fn spineAnnotation(r: ResEntry) bool {
    return r.prov.condition_only and r.xc.no == 0 and r.xc.atoms.len == 0;
}

pub const SupplyEntry = struct {
    fun: u32,
    k: u32,
    path: u32,
    prov: Prov,
    owned: bool,
    /// When borrowed: whether only an approximate step made it so (an
    /// element, a level of a recursive value, a value from JavaScript).
    approx: bool = false,
    /// The condition of what is supplied (§18.3).
    xc: XSum = .{},
    /// Its container condition, including value-scoped path guards (#720).
    sc: XSum = .{},
    /// Its record condition (§31.4 item 6).
    rxc: XSum = .{ .no = 1 },
    /// §16.7's mark, as on `ResEntry`.
    grown: Grown = 0,
};

pub const Calls = enum(u8) { zero, once, many };

pub const FunFacts = struct {
    param: u32,
    /// Owned result required if any named callback may write a list.
    need_if: []const u32 = &.{},
    calls: Calls = .zero,
    need: bool = false,
    /// §31.5: what this parameter returns is a record the callee writes, so
    /// it must be one the caller owns (`need`'s record twin, printed
    /// `need owned record`).
    rneed: bool = false,
    seen: bool = true,
    /// §23.3: the callee hands this parameter, as its parameter `send`, a
    /// function that sends what it is given to `update`; `none` otherwise.
    send: u32 = none,
    /// §23.5, amended: `need` comes only from a send that gives up what it
    /// returns, so a `need` line says the callee sends it, not edits it.
    sends: bool = false,
};

/// §16.7: why a summary is the pessimistic one — a limit of the checker it
/// reached, which the run reports as one error at the declaration.
pub const Limit = enum(u8) {
    none,
    /// A recursive group, or a block's group of local functions, that did
    /// not settle within `round_cap` rounds.
    rounds,
    /// More than `entry_cap` entries in all.
    entries,
    /// More than `path_entry_cap` entries at one path.
    path_entries,
    /// More than `atom_cap` distinct `returns owned` atoms.
    owned_atoms,
    /// More than `condition_cap` atoms in its conditions in all.
    conditions,
    /// A value of more than `deep_cap` cells whose deep condition the walk
    /// needed (§18.2): its cells are compared pair by pair.
    value_cells,
    /// A fixpoint inside a walk that did not settle within `round_cap`
    /// rounds: the model at entry and its exclusivity invariant (§20.4), a
    /// callback's result and a fold's spine (§16.4 item 6). Their cells are
    /// finite, so their rounds are bounded by the program (#229).
    fixpoint,
    /// A chain of more than `inst_depth` callbacks, each instantiated
    /// inside the one before or handed the result of the one before
    /// (§16.4 items 5 and 6): past it a result was `⊤` with no alias, or a
    /// demand was dropped, silently, before 2026-10-16 (#271).
    callbacks,

    pub fn text(l: Limit) []const u8 {
        return switch (l) {
            .none => "",
            .rounds => "rounds",
            .entries => "entries",
            .path_entries => "path-entries",
            .owned_atoms => "owned-atoms",
            .conditions => "conditions",
            .value_cells => "value-cells",
            .fixpoint => "fixpoint",
            .callbacks => "callbacks",
        };
    }

    /// The limit in force.
    pub fn cap(l: Limit) usize {
        return switch (l) {
            .none => 0,
            .rounds => round_cap,
            .entries => entry_cap,
            .path_entries => path_entry_cap,
            .owned_atoms => atom_cap,
            .conditions => condition_cap,
            .value_cells => retired_deep_cap,
            .fixpoint => round_cap,
            .callbacks => inst_depth,
        };
    }
};

/// §24.9: a function value a summary's result carries — a lambda written in
/// the body — with its class, and what each of its captures held, in the
/// summary's vocabulary. Carried only when the class writes nothing,
/// escapes nothing and relies on nothing, so calling it where it arrives
/// needs only its result and its reads.
pub const Carried = struct {
    sum: *const Summary,
    /// Per capture `(local, path)` of the lambda: the provenances of what
    /// the local held there, each at its path below.
    binds: []const Bind,
    /// The declaration's function parameters the lambda calls (its class's
    /// `cb_j` with `b` 1, §18.9): called through what the caller passed.
    cb_js: []const u32 = &.{},

    pub const Bind = struct { local: u32, path: u32, provs: []const ResEntry };
};

pub const Summary = struct {
    params: u32,
    cast_signature: u32 = none,
    /// The full signature has crossed a growing call; transient like entry marks.
    cast_grown: Grown = 0,
    uses: []const UseEntry = &.{},
    res: []const ResEntry = &.{},
    /// §31.7: what the result holds of records — a record's object (`◦`),
    /// or a record of numbers whole — apart from `res`, which every list's
    /// fact reads, so that none of them sees it. Sorted as `res` is.
    objs: []const ResEntry = &.{},
    supply: []const SupplyEntry = &.{},
    /// §31.5: what a callee hands its function parameters of records — an
    /// object alone, or a record of numbers whole — apart from `supply`, which
    /// every list's fact reads, as `objs` is apart from `res`.
    rsupply: []const SupplyEntry = &.{},
    /// One per function-typed parameter, by parameter index.
    funs: []const FunFacts = &.{},
    limit: Limit = .none,
    /// With `limit`: what the summary measured — the entries, the rounds or
    /// the atoms it needed (§16.7).
    limit_at: u32 = 0,
    asserted: bool = false,
    /// §18.4: the exclusivity the body relied on, which callers discharge.
    xreq: []const XAtom = &.{},
    /// §31.4 item 6: the record atoms the body relied on, which every caller
    /// discharges.
    rxreq: []const XAtom = &.{},
    /// §18.8, a class only: it writes what it captured, so it runs once.
    once: bool = false,
    /// §24: read from the declaration's ownership words, not off a body.
    words: bool = false,
    /// §24.9: the function slots — a function stored at a path of a
    /// parameter, `(param, path)` — whose facts `funs`, `supply` and a
    /// `cb` provenance name by index `params + k`.
    slots: []const [2]u32 = &.{},
    /// §24.9: the function values the result carries with their classes,
    /// named by a `klass` provenance.
    klasses: []const Carried = &.{},

    fn funOf(s: *const Summary, j: u32) ?FunFacts {
        for (s.funs) |f| if (f.param == j) return f;
        return null;
    }

    fn writesAny(s: *const Summary) bool {
        if (s.once) return true;
        for (s.uses) |u| if (u.bits & bit_w != 0) return true;
        return false;
    }

    /// §31.5: whether it writes a record (`bit_f`), which only a record
    /// demand reads: a closure that does is decided by its consumers.
    fn writesRecord(s: *const Summary) bool {
        for (s.uses) |u| if (u.bits & bit_f != 0) return true;
        return false;
    }
};

const Slot = struct {
    state: enum { none, computing, done } = .none,
    sum: Summary = .{ .params = 0 },
    /// In a module the run reports on: the lines of the walk the summary was
    /// last read off, which ran against the final assumptions (§16.6's
    /// validation walk), so the report need not walk the body again.
    lines: ?[]const Demand = null,
    /// With `lines`: the walk's eager reads of captured field paths (§31.6).
    eager_reads: u32 = 0,
    hoist_table: Hoists.Table = .empty,
    /// Read back through its block once another module asked for it (§28.3).
    sealed: bool = false,
};

const Groups = struct {
    /// Per declaration: its group.
    of: []u32,
    order: []u32,
    starts: []u32,
    recursive: []bool,
};

in: Input,
/// Owns everything a report holds.
out: std.heap.ArenaAllocator,
/// Owns every summary.
keep: std.heap.ArenaAllocator,
paths: Paths,
opaque_slots: std.AutoHashMapUnmanaged(u64, []const OpaqueSlot) = .empty,
alias_summaries: std.AutoHashMapUnmanaged(u64, *const Summary) = .empty,
callable_aliases: std.AutoHashMapUnmanaged(u64, *const Summary) = .empty,
/// Per `TypeId`, a column: null until computed.
nominal: []?NominalFacts = &.{},
/// Per `TypeId`, `solveNominal`'s Tarjan columns: 0 for a type not on
/// the walk, else 1 + its visit order; its low link; whether it is on the
/// stack. Reset for every type a solve visits.
nominal_order: []u32 = &.{},
nominal_link: []u32 = &.{},
nominal_on: []bool = &.{},
/// Whether `solveNominal` is solving a group (its assertion).
nominal_solving: bool = false,
/// §30.9: the nominal types whose bodies `ownMayHold` is reading.
holding: std.ArrayList(TypeId) = .empty,
ctor_ids: std.HashMapUnmanaged(u64, u32, WordsKey(0), std.hash_map.default_max_load_percentage) = .empty,
/// Per module: the summary of each declaration, allocated on first use.
slots: []?[]Slot = &.{},
groups: []?Groups = &.{},
/// Saturated reference counts: inner counts allocated lazily for app modules only.
/// Ownership walks serially; parallel walkers would need to synchronize this memo.
private_reads: []?[]u8 = &.{},
/// Per module: whether the run reports on it.
report_for: []bool = &.{},
builder_id: ?TypeId = null,
/// §26.2: core `Result`'s type and its `Err` constructor's id, for `?`;
/// `ty` is `none` when the run has no core `Result`.
result_err: ?ResultErr = null,
/// Per constructor id: its type's `(module, declaration)`, or none.
ctor_type: std.ArrayList(u64) = .empty,
/// Per constructor id: its `(module, index)`, for printing.
ctor_key: std.ArrayList(u64) = .empty,
/// A constructor step's argument (§4.1): one id per `(constructor id,
/// field)` pair, so any field of any constructor is a step of its own
/// (issue #289; before, the step was `c * 64 + i`, and field 64 named field
/// 0 of the next constructor).
ctor_steps: std.HashMapUnmanaged([2]u32, u32, WordsKey(2), std.hash_map.default_max_load_percentage) = .empty,
/// Per constructor step: its constructor id and its field.
step_ctor: std.ArrayList([2]u32) = .empty,
/// Per module: where each declaration's schema constructors start
/// (`schemaCtorBases`), in `keep`.
schema_ctor_bases: []?[]const u32 = &.{},
/// Per type `(module, declaration)`: whether it is recursive.
recursive_types: std.HashMapUnmanaged(u64, bool, WordsKey(0), std.hash_map.default_max_load_percentage) = .empty,
/// Per constructor step argument (`step_ctor`'s index): where a value of the
/// step's own recursive type may sit below it (`levelOf`, §16.7's sound
/// projection); `.unknown` until asked.
level_of: std.ArrayList(Level) = .empty,
/// Per constructor step argument: its anchors (`anchorsOf`, §16.7, #820).
anchors_of: std.ArrayList(?Anchors) = .empty,
/// §16.7's level marker `⟨T⟩`: per marker step argument, its type
/// `(module, declaration)`, and back.
cast_types: std.ArrayList([]const u8) = .empty,
cast_ids: std.StringHashMapUnmanaged(u32) = .empty,
cast_parts: std.ArrayList(?[]const CastPart) = .empty,
cast_shapes: std.ArrayList(?Walker.TyShape) = .empty,
cast_open: std.ArrayList(bool) = .empty,
cast_wild: std.ArrayList(bool) = .empty,
cast_depth: std.ArrayList(u32) = .empty,
cast_texts: std.ArrayList(?[]const u8) = .empty,
cast_closed: []?[]u32 = &.{},
cast_scopes: std.AutoHashMapUnmanaged([2]u32, []const u32) = .empty,
cast_keys: std.HashMapUnmanaged([3]u32, u32, WordsKey(3), std.hash_map.default_max_load_percentage) = .empty,
cast_heads: std.StringHashMapUnmanaged(TypeId) = .empty,
cast_heads_ready: bool = false,

marker_types: std.ArrayList(u64) = .empty,
/// Per marker: where it stands (§16.7, *Where a marker stands*).
marker_kind: std.ArrayList(MarkerKind) = .empty,
marker_ids: std.AutoHashMapUnmanaged(struct { u64, MarkerKind }, u32) = .empty,
/// Per recursive type: its region steps (`regionSteps`).
region_steps: std.AutoHashMapUnmanaged([2]u64, []const u32) = .empty,
/// Per canonical place `(P, T, r, kind)`: the places it stands for.
member_paths: std.AutoHashMapUnmanaged([5]u64, []const u32) = .empty,
/// `child`'s answers, by `(parent, kind, arg)`.
child_memo: std.HashMapUnmanaged([3]u32, u32, StepKey, std.hash_map.default_max_load_percentage) = .empty,
match_cache: ?*MatchCache = null,
/// Per path: `canonicalSplit`'s and `canonicalPlaces`'s answers, as an
/// index into `canon_splits` plus 2, 1 for none, 0 not yet asked.
split_of: std.ArrayList(u32) = .empty,
places_of: std.ArrayList(u32) = .empty,
canon_splits: std.ArrayList(CanonicalSplit) = .empty,
/// Memos of path arithmetic, which the walk repeats (§18.11).
concat_memo: std.HashMapUnmanaged([2]u32, u32, WordsKey(2), std.hash_map.default_max_load_percentage) = .empty,
/// §16.6 as amended by §16.7 (d): a recursive member's fresh numbers, by
/// the declaration and the result paths a number names (with its escape
/// bit), so that a number names the same result paths in every round.
fresh_keys: std.HashMapUnmanaged([]const u32, u32, U32SliceContext, std.hash_map.default_max_load_percentage) = .empty,
/// Per declaration `(module, declaration)`: the fresh numbers it has.
fresh_count: std.AutoHashMapUnmanaged(u64, u32) = .empty,
suffix_memo: std.HashMapUnmanaged([2]u32, u32, WordsKey(2), std.hash_map.default_max_load_percentage) = .empty,
/// Per `(module, type variable)`: whether a value of the type may hold a cell.
tracked_memo: std.HashMapUnmanaged(u64, bool, WordsKey(0), std.hash_map.default_max_load_percentage) = .empty,
tracked_inner_memo: std.AutoHashMapUnmanaged(TrackedKey, bool) = .empty,
/// Per `(module, declaration)`: its qualified name.
names_memo: std.HashMapUnmanaged(u64, []const u8, WordsKey(0), std.hash_map.default_max_load_percentage) = .empty,
/// §30.10: per `(module, schema declaration)`, what its own conversions and
/// the declarations it names put in its slots (`schemaTaint`); `null` while
/// it is being derived.
schema_taints: std.AutoHashMapUnmanaged(u64, ?SchemaTaint) = .empty,
/// §30.10: per `(module, schema declaration, member, arity)`, the summary of a
/// call of that member (`schemaMemberRow`).
schema_members: std.AutoHashMapUnmanaged([4]u32, *const Summary) = .empty,
/// Per depth of nested walks: an arena reused from walk to walk, emptied
/// with `keep_all`, so a walk lands on the pages the walks before it
/// touched and maps none of its own (#606).
walk_arenas: [16]?Arena = @splat(null),
walk_depth: u32 = 0,
/// The summary `summaryText` prints, so that a slot's `cb` names its path.
text_sum: ?*const Summary = null,
/// `--ownership-flips` (§24.6): whether the flip met every word it takes away.
flip_applied: bool = false,
/// Per module: its block read (§28.4), or null; computed on first use.
decoded: []?summary_bytes.Block = &.{},
/// Per module: 0 untouched, 1 its block could not be read, 2 sealed (§28.3).
block_state: []u8 = &.{},
/// The module of the walk under way, outermost first: a summary another
/// module asks for is read through the block (§28.3).
walking: u32 = none,
/// Nanoseconds spent reading blocks, for `ownership_blocks`.
block_ns: u64 = 0,
/// `(package, dotted name)` → module index, for reading a block.
module_by_name: std.StringHashMapUnmanaged(u32) = .empty,
/// The declaration whose summary is being computed, `(module, decl)`, or
/// `none`: what a limit reached is reported against (§16.7).
cur_decl: [2]u32 = .{ none, none },
/// Every limit a walk reached (§16.7), in the order reached.
limit_hits: std.ArrayList(LimitHit) = .empty,

pub fn init(in: Input) Ownership {
    return .{ .in = in, .out = .init(in.gpa), .keep = .init(in.gpa), .paths = .{} };
}

pub fn deinit(o: *Ownership) void {
    o.out.deinit();
    o.keep.deinit();
    o.paths.deinit(o.in.gpa);
    o.opaque_slots.deinit(o.in.gpa);
    o.alias_summaries.deinit(o.in.gpa);
    o.callable_aliases.deinit(o.in.gpa);
    o.in.gpa.free(o.nominal);
    o.in.gpa.free(o.nominal_order);
    o.in.gpa.free(o.nominal_link);
    o.in.gpa.free(o.nominal_on);
    o.holding.deinit(o.in.gpa);
    o.cast_types.deinit(o.in.gpa);
    o.cast_ids.deinit(o.in.gpa);
    o.cast_parts.deinit(o.in.gpa);
    o.cast_open.deinit(o.in.gpa);
    o.cast_wild.deinit(o.in.gpa);
    o.cast_depth.deinit(o.in.gpa);
    o.cast_texts.deinit(o.in.gpa);
    for (o.cast_closed) |memo| if (memo) |items| o.in.gpa.free(items);
    o.in.gpa.free(o.cast_closed);
    o.cast_scopes.deinit(o.in.gpa);
    o.cast_keys.deinit(o.in.gpa);
    o.cast_heads.deinit(o.in.gpa);
    o.ctor_ids.deinit(o.in.gpa);
    o.ctor_type.deinit(o.in.gpa);
    o.ctor_key.deinit(o.in.gpa);
    o.ctor_steps.deinit(o.in.gpa);
    o.step_ctor.deinit(o.in.gpa);
    o.in.gpa.free(o.schema_ctor_bases);
    o.recursive_types.deinit(o.in.gpa);
    o.level_of.deinit(o.in.gpa);
    o.anchors_of.deinit(o.in.gpa);
    o.marker_types.deinit(o.in.gpa);
    o.marker_kind.deinit(o.in.gpa);
    o.marker_ids.deinit(o.in.gpa);
    o.region_steps.deinit(o.in.gpa);
    o.member_paths.deinit(o.in.gpa);
    o.child_memo.deinit(o.in.gpa);
    if (o.match_cache) |memo| {
        memo.deinit(o.in.gpa);
        o.in.gpa.destroy(memo);
    }
    o.split_of.deinit(o.in.gpa);
    o.places_of.deinit(o.in.gpa);
    o.canon_splits.deinit(o.in.gpa);
    o.concat_memo.deinit(o.in.gpa);
    o.fresh_keys.deinit(o.in.gpa);
    o.fresh_count.deinit(o.in.gpa);
    o.suffix_memo.deinit(o.in.gpa);
    o.tracked_memo.deinit(o.in.gpa);
    o.tracked_inner_memo.deinit(o.in.gpa);
    o.names_memo.deinit(o.in.gpa);
    o.schema_taints.deinit(o.in.gpa);
    o.schema_members.deinit(o.in.gpa);
    for (&o.walk_arenas) |*a| if (a.*) |*x| x.deinit();
    o.in.gpa.free(o.slots);
    o.in.gpa.free(o.groups);
    o.in.gpa.free(o.private_reads);
    o.in.gpa.free(o.report_for);
    o.in.gpa.free(o.decoded);
    o.in.gpa.free(o.block_state);
    o.module_by_name.deinit(o.in.gpa);
    o.limit_hits.deinit(o.in.gpa);
}

/// The report for `targets`, in their order.
pub fn run(o: *Ownership, targets: []const u32) Allocator.Error![]const ModuleReport {
    try o.seedPaths();
    o.private_reads = try o.in.gpa.alloc(?[]u8, o.in.birs.len);
    @memset(o.private_reads, null);
    const arena = o.out.allocator();
    o.report_for = try o.in.gpa.alloc(bool, o.in.birs.len);
    @memset(o.report_for, false);
    for (targets) |m| if (m < o.report_for.len) {
        o.report_for[m] = true;
    };
    const reports = try arena.alloc(ModuleReport, targets.len);
    defer if (o.in.profile) |p| p.record(o.in.tid, .ownership_blocks, if (o.in.single_module) |m| @backingInt(o.in.graph.moduleFile(@fromBackingInt(m))) else Profile.Event.no_file, 0, o.block_ns);
    for (targets, reports) |m, *r| {
        r.* = .{ .module = m, .checked = false, .demands = &.{} };
        if (!o.isChecked(m)) continue;
        r.checked = true;
        const token = if (o.in.profile) |p| p.begin() else null;
        defer if (o.in.profile) |p| p.end(o.in.tid, token.?, .ownership_module, @backingInt(o.in.graph.moduleFile(@fromBackingInt(m))), 0);
        const bir = o.in.birs[m];
        // Every summary first (§16.9): a report walk reads them all.
        for (bir.decls, 0..) |_, di| _ = try o.ensureSummary(m, @intCast(di));
        var demands: std.ArrayList(Demand) = .empty;
        var eager: u32 = 0;
        var hoists: Hoists.Builder = .{};
        const slots = try o.slotsOf(m);
        for (bir.decls, 0..) |d, di| {
            if (d.kind != .value) continue;
            const body = d.body.unwrap() orelse continue;
            if (slots[di].lines) |ls| {
                try demands.appendSlice(arena, ls);
                eager += slots[di].eager_reads;
                try hoists.append(arena, slots[di].hoist_table);
                continue;
            }
            var scratch: std.heap.ArenaAllocator = .init(o.in.gpa);
            defer scratch.deinit();
            o.walking = m;
            defer o.walking = none;
            o.cur_decl = .{ m, @intCast(di) };
            defer o.cur_decl = .{ none, none };
            var w = o.walker(m, @intCast(di), scratch.allocator(), .report);
            try w.walkDecl(body);
            try w.resolve(&demands);
            eager += w.eager_reads;
            try hoists.append(arena, w.hoist_table.table());
        }
        r.eager_reads = eager;
        r.hoist_table = hoists.table();
        var hoist_lines: std.ArrayList(SummaryLine) = .empty;
        if (o.in.format_hoists) for (r.hoist_table.reads) |h| {
            var text: std.Io.Writer.Allocating = .init(arena);
            const wr = &text.writer;
            const decl = bir.decls[h.decl];
            const name = bir.locals[decl.locals_start + h.holder].name.unwrap().?;
            wr.print("{s} {s}", .{ if (h.demand == none) "capture" else "hoist", o.in.interner.slice(bir.symbol(@fromBackingInt(name))) }) catch return error.OutOfMemory;
            for (r.hoist_table.paths[h.path_start..][0..h.prefix_len]) |step| {
                if (step.kind == 0) wr.print(".{s}", .{r.hoist_table.name(step.arg)}) catch return error.OutOfMemory else wr.print(".{d}", .{step.arg}) catch return error.OutOfMemory;
            }
            const rp = o.in.positions.get(o.in.positions.ctx, m, bir.insts.items(.main_token)[h.inst]);
            const pp = o.in.positions.get(o.in.positions.ctx, m, bir.insts.items(.main_token)[h.placement]);
            wr.print(": read {d}:{d}; {s} {d}:{d}", .{ rp.line, rp.col, if (h.phase == 1) "after operands" else "before", pp.line, pp.col }) catch return error.OutOfMemory;
            try hoist_lines.append(arena, .{ .text = try text.toOwnedSlice() });
        };
        r.hoist_lines = hoist_lines.items;
        // Source order: by position, which is a function of the text.
        std.mem.sort(Demand, demands.items, {}, struct {
            fn less(_: void, x: Demand, y: Demand) bool {
                if (x.position.line != y.position.line) return x.position.line < y.position.line;
                if (x.position.col != y.position.col) return x.position.col < y.position.col;
                if (!std.mem.eql(u8, x.op, y.op)) return std.mem.lessThan(u8, x.op, y.op);
                return std.mem.lessThan(u8, x.base, y.base);
            }
        }.less);
        r.demands = try dedupe(demands.items);
        var lines: std.ArrayList(SummaryLine) = .empty;
        for (bir.decls, 0..) |d, di| {
            // A `crossing foreign type` (§24.2), on the trusted surface.
            if (d.kind == .foreign_type) for (bir.ownSlots(d)) |s| if (s[0] == Bir.own_type) {
                try lines.append(arena, .{ .text = try std.fmt.allocPrint(arena, "crossing {s} (words)", .{o.in.interner.slice(bir.symbol(d.name))}) });
            };
            for (try o.flipped(m, @intCast(di), bir.ownSlots(d))) |slot| {
                if (slot[1] & @import("../parse/Ast.zig").OwnWord.entry.bit() == 0) continue;
                try lines.append(arena, .{ .text = try std.fmt.allocPrint(arena, "entry {s} (words)", .{o.in.interner.slice(bir.symbol(d.name))}) });
                break;
            }
            if (d.params == 0) continue;
            if (d.kind != .value and d.kind != .foreign_value) continue;
            if (!o.in.format_summaries) continue;
            const s = (try o.ensureSummary(m, @intCast(di))) orelse continue;
            try lines.append(arena, .{ .text = try o.summaryText(m, @intCast(di), s) });
        }
        r.summaries = try lines.toOwnedSlice(arena);
        // The limits its declarations reached (§16.7), by declaration.
        var hits: std.ArrayList(LimitLine) = .empty;
        for (o.limit_hits.items) |h| if (h.module == m) try hits.append(arena, .{
            .decl = h.decl,
            .name = o.in.interner.slice(bir.symbol(bir.decls[h.decl].name)),
            .limit = h.limit,
            .at = h.at,
        });
        std.mem.sort(LimitLine, hits.items, {}, struct {
            fn less(_: void, x: LimitLine, y: LimitLine) bool {
                if (x.decl != y.decl) return x.decl < y.decl;
                return @backingInt(x.limit) < @backingInt(y.limit);
            }
        }.less);
        r.limits = hits.items;
    }
    // §16.7, *The canonical form*: under `-Downership-full-cross-check`,
    // the same report from the expanded form, every site's verdict the same.
    if (@import("ownership_options").full_cross_check and o.in.canonical) {
        var in = o.in;
        in.canonical = false;
        in.profile = null;
        var shadow = Ownership.init(in);
        defer shadow.deinit();
        const expanded = try shadow.run(targets);
        for (reports, expanded) |a, b| try crossCheck(o.in.gpa, a, b);
        for (targets) |m| if (m < o.slots.len) try o.crossCheckSummaries(&shadow, m);
        for (targets) |m| try o.checkMatch(m);
    }
    return reports;
}

/// A site's verdict, as the cross-check compares it: the worst of its
/// lines (a write the canonical form names once may be several lines in
/// the expanded one). The causes are kept for the message; they may
/// differ, one form seeing two places where the other sees one.
const SiteVerdict = struct { worst: u8 = 0, causes: u64 = 0 };

comptime {
    // `SiteVerdict.causes` has a bit per cause.
    std.debug.assert(@typeInfo(Cause).@"enum".field_names.len <= 64);
}

fn siteVerdicts(gpa: Allocator, r: ModuleReport) Allocator.Error!std.AutoArrayHashMapUnmanaged([3]u64, SiteVerdict) {
    var out: std.AutoArrayHashMapUnmanaged([3]u64, SiteVerdict) = .empty;
    for (r.demands) |d| {
        const key: [3]u64 = .{ d.position.line, d.position.col, std.hash.Wyhash.hash(0, d.op) };
        const gop = try out.getOrPut(gpa, key);
        if (!gop.found_existing) gop.value_ptr.* = .{};
        const v = gop.value_ptr;
        switch (d.verdict) {
            .accepted => {},
            .pending => v.worst = @max(v.worst, 1),
            .rejected => |c| {
                v.worst = 2;
                v.causes |= @as(u64, 1) << @as(u6, @intCast(@backingInt(c)));
            },
        }
    }
    return out;
}

/// §16.7: a check of the marker's overlap and holding against concrete
/// places, run with the cross-check. For each recursive type with no type
/// parameter in a module the run reports on, every concrete path from a value
/// of it to `diff_depth` steps is folded (`child`) and compared, pair by pair,
/// with the concrete relation: a prefix either way must overlap, and a prefix
/// must hold. Each place a canonical `⟨T⟩r` or `⟨T⟩⁺r` stands for, written out
/// concretely, is compared so too. A miss panics.
fn checkMatch(o: *Ownership, m: u32) Allocator.Error!void {
    // The program's own types: core's and the platforms' are many and wide,
    // and the corpus's fixtures name the shapes the check is for.
    if (m >= o.in.packages.len or o.in.packages[m] != .app) return;
    const bir = o.in.birs[m];
    for (bir.decls, 0..) |decl, di| {
        if (decl.kind != .type or decl.type_params_start != decl.type_params_end) continue;
        const ty = (@as(u64, m) << 32) | di;
        if (!try o.typeRecursive(ty) or try o.dictTree(ty)) continue;
        var arena: std.heap.ArenaAllocator = .init(o.in.gpa);
        defer arena.deinit();
        const a = arena.allocator();
        var places: std.ArrayList(Concrete) = .empty;
        try o.concretePlaces(a, m, ty, &.{}, true, &places);
        for (places.items) |x| for (places.items) |y| {
            const px = try o.foldSteps(x.steps);
            const py = try o.foldSteps(y.steps);
            if (prefixOf(x.steps, y.steps) or prefixOf(y.steps, x.steps)) {
                if (!o.overlap(px, py)) o.matchMiss("overlap", px, py);
            }
            if (prefixOf(x.steps, y.steps) and !o.startsWith(py, px) and px != py and !o.levelHoldsPaths(px, py)) o.matchMiss("hold", px, py);
        };
        // The canonical places: `⟨T⟩r` is `r` at every `T` at or below the
        // root; `⟨T⟩⁺r` at every one strictly below.
        for (places.items) |r| {
            if (r.steps.len == 0 or r.levels != 0) continue;
            for ([_]MarkerKind{ .at, .under }) |kind| {
                var canon = try o.rawChild(eps, .level, try o.markerId(ty, kind));
                for (r.steps) |s| canon = try o.child(canon, s.kind, s.arg);
                for (places.items) |t| {
                    if (!t.at_t or (kind == .under and t.steps.len == 0)) continue;
                    const c = try std.mem.concat(a, Step, &.{ t.steps, r.steps });
                    for (places.items) |y| {
                        const py = try o.foldSteps(y.steps);
                        if ((prefixOf(c, y.steps) or prefixOf(y.steps, c)) and !o.overlap(canon, py)) o.matchMiss("canonical overlap", canon, py);
                        if (prefixOf(y.steps, c) and !o.startsWith(canon, py) and canon != py and !o.levelHoldsPaths(py, canon)) o.matchMiss("canonical hold", py, canon);
                        if (prefixOf(c, y.steps) and !o.startsWith(py, canon) and canon != py and !o.levelHoldsPaths(canon, py)) o.matchMiss("canonical held", canon, py);
                    }
                }
            }
        }
    }
}

const diff_depth = 7;
/// The most concrete places one type's check enumerates: the check is a
/// test, and its pairs are quadratic in them.
const diff_places = 600;

/// A concrete path from a value of the type checked: its steps, whether the
/// value it reaches is one of that type, and how many of its steps went into
/// one (0: within the root's own level).
const Concrete = struct { steps: []const Step, at_t: bool, levels: u32 };

fn prefixOf(p: []const Step, q: []const Step) bool {
    if (p.len > q.len) return false;
    for (p, q[0..p.len]) |x, y| if (x.kind != y.kind or x.arg != y.arg) return false;
    return true;
}

fn foldSteps(o: *Ownership, ss: []const Step) Allocator.Error!u32 {
    var at: u32 = eps;
    for (ss) |s| at = try o.child(at, s.kind, s.arg);
    return at;
}

fn matchMiss(o: *Ownership, what: []const u8, p: u32, q: u32) noreturn {
    std.debug.print("ownership marker check: {s} missed for `{s}` and `{s}`\n", .{ what, o.pathText(p) catch "", o.pathText(q) catch "" });
    @panic("ownership: the level marker's match misses a concrete relation (ownership-checker.md §16.7)");
}

/// Every concrete path from a value of type `ty` to `diff_depth` steps,
/// through constructors, records, tuples and lists, into `out`.
fn concretePlaces(o: *Ownership, a: Allocator, m: u32, ty: u64, prefix: []const Step, at_t: bool, out: *std.ArrayList(Concrete)) Allocator.Error!void {
    _ = m;
    try o.concreteAt(a, ty, prefix, .{ .nominal = ty }, 0, at_t, out);
}

const TyAt = union(enum) { nominal: u64, expr: struct { m: u32, inst: Inst.Index } };

fn concreteAt(o: *Ownership, a: Allocator, ty: u64, prefix: []const Step, at: TyAt, levels: u32, at_t: bool, out: *std.ArrayList(Concrete)) Allocator.Error!void {
    if (out.items.len >= diff_places) return;
    try out.append(a, .{ .steps = prefix, .at_t = at_t, .levels = levels });
    if (prefix.len >= diff_depth) return;
    switch (at) {
        .nominal => |key| {
            if (o.schemaKeyOf(key) != null) return;
            const nm: u32 = @intCast(key >> 32);
            const nd: u32 = @truncate(key);
            const bir = o.in.birs[nm];
            const decl = bir.decls[nd];
            if (decl.kind == .type_alias) {
                const body = decl.annotation.unwrap() orelse return;
                return o.concreteExpr(a, ty, prefix, nm, body, levels, out);
            }
            if (decl.kind != .type) return;
            for (bir.declCtors(decl), decl.ctors_start..) |ct, ci| {
                const args = bir.extraSlice(.{ .start = ct.args_start, .end = ct.args_end }, Inst.Index);
                for (args, 0..) |arg, k| {
                    const s: Step = .{ .kind = .ctor, .arg = try o.ctorStep(try o.ctorId(nm, @intCast(ci)), @intCast(k)) };
                    const next = try std.mem.concat(a, Step, &.{ prefix, &.{s} });
                    try o.concreteExpr(a, ty, next, nm, arg, levels + @intFromBool(key == ty and prefix.len > 0), out);
                }
            }
        },
        .expr => |e| try o.concreteExpr(a, ty, prefix, e.m, e.inst, levels, out),
    }
}

fn concreteExpr(o: *Ownership, a: Allocator, ty: u64, prefix: []const Step, m: u32, inst: Inst.Index, levels: u32, out: *std.ArrayList(Concrete)) Allocator.Error!void {
    const bir = o.in.birs[m];
    const tag = bir.instTag(inst);
    const data = bir.instData(inst);
    const graph_m: Graph.Index = @fromBackingInt(@intCast(m));
    switch (tag) {
        .type_tuple => {
            try out.append(a, .{ .steps = prefix, .at_t = false, .levels = levels });
            if (prefix.len >= diff_depth) return;
            for (bir.extraSlice(Bir.inlineRange(data), Inst.Index), 0..) |el, i| {
                try o.concreteExpr(a, ty, try std.mem.concat(a, Step, &.{ prefix, &.{.{ .kind = .tuple, .arg = @intCast(i) }} }), m, el, levels, out);
            }
        },
        .type_record => {
            try out.append(a, .{ .steps = prefix, .at_t = false, .levels = levels });
            if (prefix.len >= diff_depth) return;
            for (bir.extraSlice(Bir.inlineRange(data), Bir.Field)) |fl| {
                const sym = @backingInt(bir.symbol(fl.name));
                try o.concreteExpr(a, ty, try std.mem.concat(a, Step, &.{ prefix, &.{.{ .kind = .field, .arg = sym }} }), m, fl.value, levels, out);
            }
        },
        .type_top, .ext_type, .type_app => {
            const id = if (tag == .type_app) blk: {
                const head: Inst.Index = @fromBackingInt(@intCast(data.lhs));
                break :blk o.in.types.headId(graph_m, bir.instTag(head), bir.instData(head));
            } else o.in.types.headId(graph_m, tag, data);
            if (id == .none or id.int() >= o.in.types.entries.len) return out.append(a, .{ .steps = prefix, .at_t = false, .levels = levels });
            if (id == o.in.types.well_known.list) {
                try out.append(a, .{ .steps = prefix, .at_t = false, .levels = levels });
                if (prefix.len >= diff_depth or tag != .type_app) return;
                const args = bir.extraSlice(bir.subRange(@fromBackingInt(@intCast(data.rhs))), Inst.Index);
                if (args.len != 1) return;
                return o.concreteExpr(a, ty, try std.mem.concat(a, Step, &.{ prefix, &.{.{ .kind = .elem, .arg = 0 }} }), m, args[0], levels, out);
            }
            const e = o.in.types.entries[id.int()];
            const key = (@as(u64, e.module.int()) << 32) | e.decl.int();
            // Only the type checked and types with no parameters are walked
            // into: a parameter's argument is not followed.
            const nd = o.in.birs[e.module.int()].decls[e.decl.int()];
            if (e.kind == .foreign or (key != ty and nd.type_params_start != nd.type_params_end)) return out.append(a, .{ .steps = prefix, .at_t = false, .levels = levels });
            return o.concreteAt(a, ty, prefix, .{ .nominal = key }, levels, key == ty, out);
        },
        else => try out.append(a, .{ .steps = prefix, .at_t = false, .levels = levels }),
    }
}

/// §16.7: every place a path stands for, with each canonical marker in it
/// written out as its member places (`memberPaths`), innermost first.
fn expandedPlaces(o: *Ownership, p: u32, typed: bool, out: *std.ArrayList(u32)) Allocator.Error!void {
    // The path itself too: a marker at a place in no region is also what a
    // projection or a call makes, which the expanded run writes as it is.
    try out.append(o.in.gpa, p);
    const d = (try o.canonicalPlaces(p)) orelse return;
    var members: std.ArrayList(u32) = .empty;
    defer members.deinit(o.in.gpa);
    try o.memberPaths(d, d.kind, typed, &members);
    for (members.items) |q| try o.expandedPlaces(q, typed, out);
}

/// §16.7's cross-check of summaries: every fact the expanded run states is
/// one the canonical run states too, written out (`expandedPlaces`), and an
/// owned supply of the canonical run is owned in the expanded one. By text,
/// since the two runs number their paths apart.
fn crossCheckSummaries(o: *Ownership, sh: *Ownership, m: u32) Allocator.Error!void {
    const gpa = o.in.gpa;
    const a = o.out.allocator();
    const so = o.slots[m] orelse return;
    const ss = sh.slots[m] orelse return;
    var places: std.ArrayList(u32) = .empty;
    defer places.deinit(gpa);
    var provs: std.ArrayList(u32) = .empty;
    defer provs.deinit(gpa);
    for (so, ss, 0..) |x, y, d| {
        if (x.state != .done or y.state != .done) continue;
        const c = x.sum;
        const e = y.sum;
        if (c.limit != .none or e.limit != .none) continue;
        var bits: std.StringHashMapUnmanaged(u16) = .empty;
        for (c.uses) |u| {
            places.clearRetainingCapacity();
            try o.expandedPlaces(u.path, true, &places);
            for (places.items) |p| {
                const g = try bits.getOrPut(a, try std.fmt.allocPrint(a, "{d}{s}", .{ u.param, try o.pathText(p) }));
                if (!g.found_existing) g.value_ptr.* = 0;
                g.value_ptr.* |= u.bits;
            }
        }
        for (e.uses) |u| {
            const k = try std.fmt.allocPrint(a, "{d}{s}", .{ u.param, try sh.pathText(u.path) });
            const have = bits.get(k) orelse 0;
            if (u.bits & ~have != 0) return crossFail(o, m, @intCast(d), k);
        }
        var res: std.StringHashMapUnmanaged(void) = .empty;
        for (c.res) |r| {
            places.clearRetainingCapacity();
            try o.expandedPlaces(r.path, false, &places);
            provs.clearRetainingCapacity();
            try o.expandedPlaces(r.prov.path, false, &provs);
            for (places.items) |p| for (provs.items) |q| {
                var pv = r.prov;
                pv.path = q;
                try res.put(a, try std.fmt.allocPrint(a, "{s} {s}", .{ try o.pathText(p), try o.provText(pv) }), {});
            };
        }
        // A fresh number names the result paths that may hold one new cell
        // (§16.3), and each run numbers its cells in an order of its own:
        // the canonical run, coarser, may state a cell that the expanded
        // one does not, which moves every later number (#763). So a numbered
        // fresh provenance is compared by what it names. An allocation's
        // number says which paths may hold one cell: the cell the expanded
        // run numbers `n` is one the canonical run numbers alike at every
        // place where the expanded run puts it (`cands`, per expanded
        // number, the canonical numbers that are). An annotation's number
        // only says which entries instantiate as one cell, which shares
        // nothing (`sepCells`) and holds every condition its entries state:
        // each place the expanded run annotates, the canonical run annotates
        // too (`cnotes`).
        var cplaces: std.AutoHashMapUnmanaged(u64, std.StringHashMapUnmanaged(void)) = .empty;
        var cnotes: std.StringHashMapUnmanaged(void) = .empty;
        for (c.res) |r| {
            const n = freshLabel(r.prov) orelse continue;
            places.clearRetainingCapacity();
            try o.expandedPlaces(r.path, false, &places);
            if (r.prov.condition_only) {
                for (places.items) |p| try cnotes.put(a, try std.fmt.allocPrint(a, "{d} {s}", .{ n >> 32, try o.pathText(p) }), {});
                continue;
            }
            const g = try cplaces.getOrPut(a, n);
            if (!g.found_existing) g.value_ptr.* = .empty;
            for (places.items) |p| try g.value_ptr.put(a, try o.pathText(p), {});
        }
        var epaths: std.AutoArrayHashMapUnmanaged(u64, std.ArrayList([]const u8)) = .empty;
        for (e.res) |r| {
            const n = freshLabel(r.prov) orelse continue;
            if (r.prov.condition_only) {
                const t = try sh.pathText(r.path);
                if (!cnotes.contains(try std.fmt.allocPrint(a, "{d} {s}", .{ n >> 32, t }))) return crossFail(o, m, @intCast(d), try std.fmt.allocPrint(a, "{s} {s}", .{ t, try sh.provText(r.prov) }));
                continue;
            }
            const g = try epaths.getOrPut(a, n);
            if (!g.found_existing) g.value_ptr.* = .empty;
            try g.value_ptr.append(a, try sh.pathText(r.path));
        }
        var cands: std.AutoHashMapUnmanaged(u64, std.ArrayList(u32)) = .empty;
        {
            var it = epaths.iterator();
            while (it.next()) |en| {
                var found: std.ArrayList(u32) = .empty;
                var cit = cplaces.iterator();
                while (cit.next()) |cn| {
                    if (cn.key_ptr.* >> 32 != en.key_ptr.* >> 32) continue;
                    for (en.value_ptr.items) |t| {
                        if (!cn.value_ptr.contains(t)) break;
                    } else try found.append(a, @truncate(cn.key_ptr.*));
                }
                if (found.items.len == 0) {
                    var pv: Prov = undefined;
                    for (e.res) |r| if (freshLabel(r.prov) == en.key_ptr.*) {
                        pv = r.prov;
                        break;
                    };
                    return crossFail(o, m, @intCast(d), try std.fmt.allocPrint(a, "{s} at {s}", .{ try sh.provText(pv), try std.mem.join(a, ", ", en.value_ptr.items) }));
                }
                try cands.put(a, en.key_ptr.*, found);
            }
        }
        for (e.res) |r| {
            if (freshLabel(r.prov) != null) continue;
            const k = try std.fmt.allocPrint(a, "{s} {s}", .{ try sh.pathText(r.path), try sh.provText(r.prov) });
            if (!res.contains(k)) return crossFail(o, m, @intCast(d), k);
        }
        var sup: std.StringHashMapUnmanaged(bool) = .empty;
        for (c.supply) |r| {
            places.clearRetainingCapacity();
            try o.expandedPlaces(r.path, false, &places);
            for (places.items) |p| {
                const g = try sup.getOrPut(a, try std.fmt.allocPrint(a, "{d} {d} {s} {s}", .{ r.fun, r.k, try o.pathText(p), try supplyProvText(o, r.prov) }));
                g.value_ptr.* = if (g.found_existing) g.value_ptr.* or r.owned else r.owned;
            }
        }
        for (e.supply) |r| {
            const k = try std.fmt.allocPrint(a, "{d} {d} {s} {s}", .{ r.fun, r.k, try sh.pathText(r.path), try supplyProvText(sh, r.prov) });
            // A numbered cell: supplied under one of its canonical numbers;
            // an annotation, under any number (`supplyProvText`).
            if (freshLabel(r.prov)) |n| {
                if (!r.prov.condition_only) {
                    const ns = (cands.get(n) orelse return crossFail(o, m, @intCast(d), k)).items;
                    for (ns) |cn| {
                        var pv = r.prov;
                        pv.a = cn;
                        const owned = sup.get(try std.fmt.allocPrint(a, "{d} {d} {s} {s}", .{ r.fun, r.k, try sh.pathText(r.path), try o.provText(pv) })) orelse continue;
                        if (!owned or r.owned) break;
                    } else return crossFail(o, m, @intCast(d), k);
                    continue;
                }
            }
            const owned = sup.get(k) orelse return crossFail(o, m, @intCast(d), k);
            if (owned and !r.owned) return crossFail(o, m, @intCast(d), k);
        }
    }
}

/// A supply's provenance as `crossCheckSummaries` keys it: as printed,
/// but an annotation's fresh number left out (see `cnotes` there).
fn supplyProvText(o: *Ownership, p: Prov) Allocator.Error![]const u8 {
    if (p.condition_only and freshLabel(p) != null) return if (p.kind == .esc) "condition(esc)" else "condition(fresh)";
    return o.provText(p);
}

/// A numbered fresh provenance as `crossCheckSummaries` keys it: its kind
/// and whether it is an annotation above, its number below; null for one
/// with no number, or a record object's (§31.7), which is compared as text.
fn freshLabel(p: Prov) ?u64 {
    if (p.kind != .fresh and p.kind != .esc) return null;
    if (p.a == 0 or p.a >= Walker.obj_fresh_base or p.obj) return null;
    const class: u64 = @as(u64, @intFromBool(p.kind == .esc)) | @as(u64, @intFromBool(p.condition_only)) << 1;
    return class << 32 | p.a;
}

fn crossFail(o: *Ownership, m: u32, d: u32, what: []const u8) noreturn {
    const bir = o.in.birs[m];
    std.debug.print("ownership cross-check: {s}.{s}: the expanded summary states `{s}`, which the canonical one does not\n", .{ o.in.module_names[m], o.in.interner.slice(bir.symbol(bir.decls[d].name)), what });
    @panic("ownership: the canonical form and the expanded one disagree on a summary (ownership-checker.md §16.7)");
}

fn crossCheck(gpa: Allocator, a: ModuleReport, b: ModuleReport) Allocator.Error!void {
    var va = try siteVerdicts(gpa, a);
    defer va.deinit(gpa);
    var vb = try siteVerdicts(gpa, b);
    defer vb.deinit(gpa);
    var ok = va.count() == vb.count();
    var it = va.iterator();
    while (it.next()) |e| {
        const other = vb.get(e.key_ptr.*) orelse {
            ok = false;
            break;
        };
        if (other.worst != e.value_ptr.worst) ok = false;
    }
    if (!ok) {
        for (a.demands) |d| std.debug.print("canonical {d}:{d} {s} {s}: {s}\n", .{ d.position.line, d.position.col, d.op, d.base, @tagName(d.verdict) });
        for (b.demands) |d| std.debug.print("expanded  {d}:{d} {s} {s}: {s}\n", .{ d.position.line, d.position.col, d.op, d.base, @tagName(d.verdict) });
        @panic("ownership: the canonical form and the expanded one disagree on a verdict (ownership-checker.md §16.7)");
    }
}

/// Two lines the walk produced twice — a demand reached through two
/// classes — are one line.
fn dedupe(items: []Demand) Allocator.Error![]const Demand {
    var n: usize = 0;
    for (items) |d| {
        if (n > 0) {
            const p = items[n - 1];
            // `.record` too: a list writer may be named `update` as well.
            if (p.record == d.record and p.position.line == d.position.line and p.position.col == d.position.col and
                std.mem.eql(u8, p.op, d.op) and std.mem.eql(u8, p.base, d.base) and
                std.meta.eql(p.verdict, d.verdict) and std.mem.eql(u8, p.detail, d.detail)) continue;
        }
        items[n] = d;
        n += 1;
    }
    return items[0..n];
}

fn isChecked(o: *const Ownership, m: u32) bool {
    if (o.in.single_module) |own| if (m != own) return false;
    if (m >= o.in.modules.len) return false;
    const km = &o.in.modules[m];
    const bir = o.in.birs[m];
    return km.inst_type.len == bir.insts.len and km.local_type.len == bir.locals.len;
}

fn walker(o: *Ownership, m: u32, di: u32, a: Allocator, mode: Mode) Walker {
    const km = &o.in.modules[m];
    const bir = o.in.birs[m];
    const d = bir.decls[di];
    return .{
        .o = o,
        .m = m,
        .bir = bir,
        .decl = d,
        .decl_index = di,
        .store = &km.store,
        .inst_type = km.inst_type,
        .local_type = km.local_type[d.locals_start..d.locals_end],
        .a = a,
        .mode = mode,
    };
}

// ---------------------------------------------------------------------------
// Computing summaries (§16.6, §16.9)
// ---------------------------------------------------------------------------

/// The summary of declaration `d` of module `m`, computing its group first
/// when it has none yet; while its group is being solved, the group's
/// current assumption. Null for a declaration with no summary: not a
/// function, in a module the run did not check, or a `foreign` with no
/// asserted row.
fn ensureSummary(o: *Ownership, m: u32, d: u32) Allocator.Error!?*const Summary {
    // A module the run did not check is read from its block (§28.4).
    if (!o.isChecked(m)) {
        if (o.alias_summaries.get((@as(u64, m) << 32) | d)) |sum| return sum;
        return o.blockSummary(m, d);
    }
    const s = (try o.ensureWalked(m, d)) orelse return null;
    // Another module reads this one through its block (§28.3).
    if (o.in.seal and o.walking != none and o.walking != m) try o.sealSlot(m, d, &o.slots[m].?[d]);
    return s;
}

fn ensureWalked(o: *Ownership, m: u32, d: u32) Allocator.Error!?*const Summary {
    const bir = o.in.birs[m];
    if (d >= bir.decls.len) return null;
    const decl = bir.decls[d];
    // A top-level value with no parameters has one too: the cells its
    // definition makes, which are what is shared (thesis §3.10).
    if (decl.params == 0 and (decl.kind != .value or decl.body == .none)) return null;
    if (decl.kind != .value and decl.kind != .foreign_value) return null;
    const slots = try o.slotsOf(m);
    const slot = &slots[d];
    switch (slot.state) {
        .done, .computing => return &slot.sum,
        .none => {},
    }
    if (try o.assertedRow(m, d)) |row| {
        slot.sum = row;
        slot.state = .done;
        return &slot.sum;
    }
    // A `foreign` has its words' summary, or the thesis's row (§24.5).
    if (decl.kind == .foreign_value) {
        slot.sum = (try o.wordsRow(m, d)).?;
        slot.state = .done;
        return &slot.sum;
    }
    if (decl.kind != .value or decl.body == .none) return null;
    try o.computeGroup(m, d);
    return &slot.sum;
}

/// Whether `d`'s group is being solved: a call of it is a recursive call.
fn isComputing(o: *const Ownership, m: u32, d: u32) bool {
    if (m >= o.slots.len) return false;
    const slots = o.slots[m] orelse return false;
    return d < slots.len and slots[d].state == .computing;
}

fn slotsOf(o: *Ownership, m: u32) Allocator.Error![]Slot {
    if (o.slots.len == 0) {
        o.slots = try o.in.gpa.alloc(?[]Slot, o.in.birs.len);
        @memset(o.slots, null);
        o.groups = try o.in.gpa.alloc(?Groups, o.in.birs.len);
        @memset(o.groups, null);
    }
    if (o.slots[m]) |s| return s;
    const s = try o.keep.allocator().alloc(Slot, o.in.birs[m].decls.len);
    @memset(s, .{});
    o.slots[m] = s;
    return s;
}

// ---------------------------------------------------------------------------
// Summary blocks (§28.3, §28.4)
// ---------------------------------------------------------------------------

fn blockStates(o: *Ownership) Allocator.Error!void {
    if (o.block_state.len != 0) return;
    o.block_state = try o.in.gpa.alloc(u8, o.in.birs.len);
    @memset(o.block_state, 0);
    o.decoded = try o.in.gpa.alloc(?summary_bytes.Block, o.in.birs.len);
    @memset(o.decoded, null);
}

/// Module `m`'s block, read: the run's own for a module it sealed, else the
/// one the caller handed in for a module it did not check. Null when there
/// is none or it does not read — the module's functions are then callees
/// with no summary (§6.1), as they were before blocks existed.
fn blockOf(o: *Ownership, m: u32) Allocator.Error!?*summary_bytes.Block {
    try o.blockStates();
    if (o.decoded[m]) |*b| return b;
    if (o.block_state[m] == 1) return null;
    const bytes = (if (m < o.in.blocks.len) o.in.blocks[m] else null) orelse {
        o.block_state[m] = 1;
        return null;
    };
    try o.seedPaths();
    const token = if (o.in.profile) |p| p.begin() else null;
    defer if (o.in.profile) |p| {
        o.block_ns += p.since(token.?);
    };
    o.decoded[m] = summary_bytes.open(o, o.keep.allocator(), bytes, m) catch |err| switch (err) {
        error.OutOfMemory => return error.OutOfMemory,
        error.Bad => {
            o.block_state[m] = 1;
            return null;
        },
    };
    return &o.decoded[m].?;
}

fn blockSummary(o: *Ownership, m: u32, d: u32) Allocator.Error!?*const Summary {
    const b = (try o.blockOf(m)) orelse return null;
    // §28.4: a summary is read the first time the run asks for it.
    const token = if (o.in.profile) |p| p.begin() else null;
    defer if (o.in.profile) |p| {
        o.block_ns += p.since(token.?);
    };
    return summary_bytes.summary(o, o.keep.allocator(), b, d);
}

/// §28.3: the summary of declaration `d` of the checked module `m`, written
/// as a block and read back in place of the one its walk gave — what a run
/// that installed `m` reads. Under runtime safety the two must agree. Done
/// per declaration, as another module first asks for it, so that a report
/// summarises no more of the library than it did.
fn sealSlot(o: *Ownership, m: u32, d: u32, slot: *Slot) Allocator.Error!void {
    if (slot.sealed or slot.state != .done) return;
    slot.sealed = true;
    try o.seedPaths();
    const bytes = try summary_bytes.write(o, o.in.gpa, &.{.{ .decl = d, .sum = &slot.sum }});
    defer o.in.gpa.free(bytes);
    var block = summary_bytes.open(o, o.keep.allocator(), bytes, m) catch |err| switch (err) {
        error.OutOfMemory => return error.OutOfMemory,
        error.Bad => std.debug.panic("ownership: {s}'s summary block does not read back", .{try o.declName(m, d)}),
    };
    const s = ((try summary_bytes.summary(o, o.keep.allocator(), &block, d)) orelse
        std.debug.panic("ownership: {s}'s summary block does not read back", .{try o.declName(m, d)})).*;
    if (std.debug.runtime_safety and !try o.summaryDeepEql(slot.sum, s))
        std.debug.panic("ownership: {s}'s summary changes through its block", .{try o.declName(m, d)});
    slot.sum = s;
}

fn declName(o: *Ownership, m: u32, d: u32) Allocator.Error![]const u8 {
    const bir = o.in.birs[m];
    return std.fmt.allocPrint(o.keep.allocator(), "{s}.{s}", .{ o.in.module_names[m], o.in.interner.slice(bir.symbol(bir.decls[d].name)) });
}

/// Module `m`'s block (§28.4): every summary it has, computed now if it is
/// not yet, and whether each value with no parameters may hold a list. The
/// caller owns the bytes.
pub fn writeBlock(o: *Ownership, m: u32) Allocator.Error![]u8 {
    try o.seedPaths();
    const bir = o.in.birs[m];
    const saved = o.walking;
    o.walking = m;
    defer o.walking = saved;
    var rows: std.ArrayList(summary_bytes.Row) = .empty;
    defer rows.deinit(o.in.gpa);
    for (bir.decls, 0..) |decl, di| {
        const d: u32 = @intCast(di);
        const s = if (decl.kind == .schema) try o.schemaSummary(m, d) else try o.ensureSummary(m, d);
        const holds = decl.kind == .value and decl.params == 0 and decl.body != .none and try o.valueHoldsList(m, d);
        try rows.append(o.in.gpa, .{ .decl = d, .sum = s, .holds_list = holds });
    }
    return summary_bytes.write(o, o.in.gpa, rows.items);
}

/// A function-valued alias retains its callable summary, including a
/// private target's. Importers need neither its body nor on-demand recursion.
pub const Alias = struct { module: u32, decl: u32, hops: u32, callable: ?*const Summary = null };

fn resolveAlias(o: *Ownership, m0: u32, d0: u32) Allocator.Error!?Alias {
    var m = m0;
    var d = d0;
    var hops: u32 = 0;
    while (hops < 8) {
        const bir = o.in.birs[m];
        const decl = bir.decls[d];
        if (decl.kind != .value or decl.params != 0) return if (hops == 0) null else .{ .module = m, .decl = d, .hops = hops };
        if (o.in.single_module) |own| if (m != own) {
            const block = (try o.blockOf(m)) orelse return null;
            const token = if (o.in.profile) |profile| profile.begin() else null;
            defer if (o.in.profile) |profile| {
                o.block_ns += profile.since(token.?);
            };
            const entry = (try summary_bytes.aliasSummary(o, o.keep.allocator(), block, d)) orelse return null;
            const alias = entry.target;
            if (hops + alias.hops >= 8) return null;
            return .{ .module = alias.module, .decl = alias.decl, .hops = hops + alias.hops, .callable = alias.callable };
        };
        if (decl.where_end != decl.where_start) return null;
        const body = decl.body.unwrap() orelse return null;
        const data = bir.instData(body);
        switch (bir.instTag(body)) {
            .top => d = data.lhs,
            .ext_value => {
                if (data.lhs >= o.in.provenance.len) return null;
                const target = o.in.provenance[data.lhs].valueDecl(data.rhs) orelse return null;
                m = data.lhs;
                d = target.int();
            },
            else => return null,
        }
        hops += 1;
    }
    return null;
}

pub fn installAlias(o: *Ownership, alias: Alias, sum: *const Summary) Allocator.Error!void {
    if (alias.callable != null) {
        try o.callable_aliases.put(o.in.gpa, (@as(u64, alias.module) << 32) | alias.decl, sum);
        return;
    }
    try o.alias_summaries.put(o.in.gpa, (@as(u64, alias.module) << 32) | alias.decl, sum);
}

/// Publish ownership with the checked interface (§16.10). The internal block
/// keeps private rows for cache restoration; only observable rows enter the hash.
pub fn publish(o: *Ownership, m: u32, iface: *Interface) Allocator.Error!void {
    const bytes = try o.publicBlock(m, iface);
    o.in.gpa.free(iface.ownership);
    iface.ownership = bytes;
}

/// The observable demand verdicts, in source order independent of traversal.
pub fn observations(gpa: Allocator, report: ModuleReport) Allocator.Error![][6]u64 {
    const out = try gpa.alloc([6]u64, report.demands.len);
    for (report.demands, out) |d, *site| {
        const verdict: [2]u64 = switch (d.verdict) {
            .accepted => |kind| .{ 0, @backingInt(kind) },
            .pending => .{ 1, 0 },
            .rejected => |cause| .{ 2, @backingInt(cause) },
        };
        site.* = .{ d.position.line, d.position.col, @intFromBool(d.record), verdict[0], verdict[1], @as(u64, @intFromBool(d.approx)) * 2 + @intFromBool(d.assumed) };
    }
    std.mem.sort([6]u64, out, {}, struct {
        fn less(_: void, a: [6]u64, b: [6]u64) bool {
            for (a, b) |x, y| if (x != y) return x < y;
            return false;
        }
    }.less);
    return out;
}

/// The serial dump independently evaluates the program in its original order.
pub fn checkVerdicts(o: *Ownership, report: ModuleReport) Allocator.Error!void {
    if (report.module >= o.in.expected_sites.len) return;
    const expected = o.in.expected_sites[report.module] orelse return;
    const actual = try observations(o.in.gpa, report);
    defer o.in.gpa.free(actual);
    if (expected.len == actual.len) {
        for (expected, actual) |a, b| {
            if (!std.meta.eql(a, b)) break;
        } else return;
    }
    for (expected) |site| std.debug.print("DAG site {any}\n", .{site});
    for (actual) |site| std.debug.print("serial site {any}\n", .{site});
    std.debug.panic("ownership: {s}'s serial and DAG verdicts differ", .{o.in.module_names[report.module]});
}

// Asserted rows acquire their record twins when read from a block. Publish
// that same normal form even if no importer has sealed the local row yet.
fn publicationSummary(o: *Ownership, original: *const Summary) Allocator.Error!*const Summary {
    var out = original.*;
    if (out.asserted) out = try o.normalizeRead(out);
    if (out.klasses.len != 0) {
        const classes = try o.keep.allocator().dupe(Carried, out.klasses);
        for (classes) |*k| k.sum = try o.publicationSummary(k.sum);
        out.klasses = classes;
    }
    const saved = try o.keep.allocator().create(Summary);
    saved.* = out;
    return saved;
}

fn publicBlock(o: *Ownership, m: u32, iface: *const Interface) Allocator.Error![]u8 {
    var aliases: std.ArrayList(summary_bytes.AliasRow) = .empty;
    defer aliases.deinit(o.in.gpa);
    var rows: std.ArrayList(summary_bytes.Row) = .empty;
    defer rows.deinit(o.in.gpa);
    for (iface.values, 0..) |_, vi| {
        const d = o.in.provenance[m].valueDecl(vi) orelse continue;
        const decl = o.in.birs[m].decls[d.int()];
        const holds = decl.kind == .value and decl.params == 0 and decl.body != .none and try o.valueHoldsList(m, d.int());
        try rows.append(o.in.gpa, .{ .decl = d.int(), .sum = if (try o.ensureSummary(m, d.int())) |sum| try o.publicationSummary(sum) else null, .holds_list = holds });
        if (try o.resolveAlias(m, d.int())) |alias| {
            if (alias.callable orelse try o.ensureSummary(alias.module, alias.decl)) |sum| {
                var target = alias;
                // A private helper's name is not part of the public
                // contract. Carry its callable row under the alias itself.
                const target_bir = o.in.birs[alias.module];
                const name = target_bir.symbol(target_bir.decls[alias.decl].name);
                if (alias.callable != null or o.in.interfaces[alias.module].findValue(o.in.interner, name) == null)
                    target = .{ .module = m, .decl = d.int(), .hops = alias.hops, .callable = sum };
                try aliases.append(o.in.gpa, .{ .decl = d.int(), .target = target, .sum = try o.publicationSummary(sum) });
            }
        }
    }
    for (iface.schemas, 0..) |_, si| {
        const d = o.in.provenance[m].schemaDecl(si) orelse continue;
        try rows.append(o.in.gpa, .{ .decl = d.int(), .sum = try o.schemaSummary(m, d.int()) });
    }
    return summary_bytes.writePublic(o, o.in.gpa, m, rows.items, aliases.items);
}

pub fn publicSchemaCtor(o: *Ownership, m: u32, ci: u32) Allocator.Error!struct { name: []const u8, index: u32 } {
    const bir = o.in.birs[m];
    const bases = try o.schemaCtorBases(m);
    const k = ci - @as(u32, @intCast(bir.ctors.len));
    for (bir.decls, 0..) |d, di| {
        if (k < bases[di] or k >= bases[di + 1]) continue;
        return .{ .name = o.in.interner.slice(bir.symbol(d.name)), .index = k - bases[di] };
    }
    unreachable;
}

/// Change 9: folded tracked places in definition order. The public wire
/// vocabulary names these by type and slot, never by a hidden field.
pub const OpaqueSlot = struct { path: u32, container: bool, fields: ?[]const u32 = null };

pub fn opaqueSlots(o: *Ownership, m: u32, d: u32) Allocator.Error![]const OpaqueSlot {
    const key = (@as(u64, m) << 32) | d;
    if (o.opaque_slots.get(key)) |slots| return slots;
    var scratch: std.heap.ArenaAllocator = .init(o.in.gpa);
    defer scratch.deinit();
    const a = scratch.allocator();
    const bir = o.in.birs[m];
    var store: TypeStore = .init(std.heap.page_allocator);
    defer store.deinit();
    var w: Walker = .{
        .o = o,
        .m = m,
        .bir = bir,
        .decl = bir.decls[d],
        .decl_index = d,
        .store = &store,
        .inst_type = &.{},
        .local_type = &.{},
        .a = a,
        .mode = .summary,
    };
    var slots: std.ArrayList(OpaqueSlot) = .empty;
    var seen: std.AutoHashMapUnmanaged([2]u32, void) = .empty;
    try o.opaqueFields(&w, m, d, &.{}, eps, &slots, &seen);
    const out = try o.keep.allocator().dupe(OpaqueSlot, slots.items);
    for (out) |*slot| if (slot.fields) |fields| {
        slot.fields = try o.keep.allocator().dupe(u32, fields);
    };
    try o.opaque_slots.put(o.in.gpa, key, out);
    return out;
}

fn opaqueFields(o: *Ownership, w: *Walker, m: u32, di: u32, env: []const Walker.TyRef, path: u32, slots: *std.ArrayList(OpaqueSlot), seen: *std.AutoHashMapUnmanaged([2]u32, void)) Allocator.Error!void {
    const bir = o.in.birs[m];
    const d = bir.decls[di];
    for (bir.declCtors(d), d.ctors_start..) |c, ci| {
        const args = bir.extraSlice(.{ .start = c.args_start, .end = c.args_end }, Inst.Index);
        for (args, 0..) |arg, k| {
            const p = try o.child(path, .ctor, try o.ctorStep(try o.ctorId(m, @intCast(ci)), @intCast(k)));
            try o.opaqueShape(w, .{ .def = .{ .m = m, .inst = arg, .env = env } }, p, slots, seen);
        }
    }
}

fn opaqueShape(o: *Ownership, w: *Walker, ty: Walker.TyRef, path: u32, slots: *std.ArrayList(OpaqueSlot), seen: *std.AutoHashMapUnmanaged([2]u32, void)) Allocator.Error!void {
    const shape = try w.tyShape(ty);
    const container = shape == .app and shape.app.id == o.in.types.well_known.list;
    const tracked_here = switch (shape) {
        .variable, .func, .record => true,
        .app => |ap| container or (o.in.types.entries[ap.id.int()].kind == .foreign and !o.isPrimitive(ap.id) and (try o.nominalFacts(ap.id)).own),
        else => false,
    };
    if (tracked_here) {
        var found = false;
        for (slots.items) |slot| if (slot.path == path) {
            found = true;
            break;
        };
        if (!found) try slots.append(w.a, .{ .path = path, .container = container, .fields = if (shape == .record) shape.record.names else null });
    }
    switch (shape) {
        .tuple => |ts| for (ts, 0..) |t, i| try o.opaqueShape(w, t, try o.child(path, .tuple, @intCast(i)), slots, seen),
        .record => |rec| {
            for (rec.types, rec.names) |t, name| try o.opaqueShape(w, t, try o.child(path, .field, name), slots, seen);
        },
        .app => |ap| {
            if ((try seen.getOrPut(w.a, .{ ap.id.int(), path })).found_existing) return;
            if (container) {
                if (ap.args.len != 0) try o.opaqueShape(w, ap.args[0], try o.child(path, .elem, 0), slots, seen);
                return;
            }
            const e = o.in.types.entries[ap.id.int()];
            if (e.kind == .foreign or e.schema_endpoint) return;
            if (e.kind == .alias) {
                const body = o.in.birs[e.module.int()].decl(e.decl).annotation.unwrap() orelse return;
                try o.opaqueShape(w, .{ .def = .{ .m = e.module.int(), .inst = body, .env = ap.args } }, path, slots, seen);
            } else try o.opaqueFields(w, e.module.int(), e.decl.int(), ap.args, path, slots, seen);
        },
        else => {},
    }
}

/// A hidden prefix of a path, expressed as the longest matching slot.
pub const OpaquePrefix = struct { module: u32, decl: u32, slot: u32, len: usize };
pub fn opaquePrefix(o: *Ownership, steps_in: []const Step) Allocator.Error!?OpaquePrefix {
    if (steps_in.len == 0 or steps_in[0].kind != .ctor) return null;
    const key = o.ctorKey(o.stepCtor(steps_in[0].arg));
    const bir = o.in.birs[key.module];
    if (key.index >= bir.ctors.len) return null;
    const di = bir.ctors[key.index].decl.int();
    if (!bir.decls[di].is_opaque) return null;
    var best: ?OpaquePrefix = null;
    for (try o.opaqueSlots(key.module, di), 0..) |slot, si| {
        const ss = o.steps(slot.path);
        if (ss.len > steps_in.len or (best != null and ss.len <= best.?.len)) continue;
        var matches = true;
        for (ss, steps_in[0..ss.len]) |x, y| if (x.kind != y.kind or x.arg != y.arg) {
            matches = false;
            break;
        };
        if (matches) best = .{ .module = key.module, .decl = di, .slot = @intCast(si), .len = ss.len };
    }
    return best;
}

/// A record object's fields stay private too: the wire numbers its fields
/// within its opaque slot and reconstructs their names only inside analysis.
pub fn opaqueRecordFields(o: *Ownership, path: u32) Allocator.Error!?[]const u32 {
    const ss = o.steps(path);
    for (ss, 0..) |_, i| {
        const slot = (try o.opaquePrefix(ss[i..])) orelse continue;
        if (slot.len != ss.len - i) continue;
        return (try o.opaqueSlots(slot.module, slot.decl))[slot.slot].fields;
    }
    return null;
}

pub fn hiddenFields(o: *Ownership, path: u32, fields: []const u32) Allocator.Error!?[]const u32 {
    const declared = (try o.opaqueRecordFields(path)) orelse return null;
    for (fields) |f| if (std.mem.indexOfScalar(u32, declared, f) == null) return null;
    return declared;
}

pub fn declNamed(o: *const Ownership, m: u32, name: []const u8) ?u32 {
    if (m >= o.in.birs.len) return null;
    // Public rows use the interface's sorted name tables. The fallback is
    // only for a private shared initializer named by a public provenance.
    if (m < o.in.interfaces.len and m < o.in.provenance.len) {
        const iface = &o.in.interfaces[m];
        if (o.in.interner.find(name)) |sym| {
            if (iface.findValue(o.in.interner, sym)) |v| if (o.in.provenance[m].valueDecl(@backingInt(v))) |d| return d.int();
            if (iface.findType(o.in.interner, sym)) |t| if (o.in.provenance[m].typeDecl(@backingInt(t))) |d| return d.int();
            if (iface.findSchema(o.in.interner, sym)) |sc| if (o.in.provenance[m].schemaDecl(@backingInt(sc))) |d| return d.int();
        }
    }
    const bir = o.in.birs[m];
    for (bir.decls, 0..) |d, i| if (std.mem.eql(u8, name, o.in.interner.slice(bir.symbol(d.name)))) return @intCast(i);
    return null;
}

pub fn publicSchemaCtorIndex(o: *Ownership, m: u32, d: u32, relative: u32) Allocator.Error!?u32 {
    const bases = try o.schemaCtorBases(m);
    if (relative >= bases[d + 1] - bases[d]) return null;
    return @intCast(o.in.birs[m].ctors.len + bases[d] + relative);
}

/// Whether the top-level value `d` of module `m` may hold a list (§23.6),
/// from its solved type when the run checked `m`, else from its block.
fn valueHoldsList(o: *Ownership, m: u32, d: u32) Allocator.Error!bool {
    if (!o.isChecked(m)) {
        const b = (try o.blockOf(m)) orelse return true;
        return d >= b.holds_list.len or b.holds_list[d];
    }
    const km = &o.in.modules[m];
    const body = o.in.birs[m].decls[d].body.unwrap() orelse return true;
    if (body.int() >= km.inst_type.len) return true;
    const v = km.inst_type[body.int()].unwrap() orelse return true;
    return o.holdsList(&km.store, v, 0);
}

/// The module of `(package, name)`, for a block's module table.
pub fn moduleNamed(o: *Ownership, package: SourceStore.Package, name: []const u8) ?u32 {
    if (o.module_by_name.count() == 0) {
        const keep = o.keep.allocator();
        for (o.in.module_names, 0..) |n, i| {
            if (i >= o.in.packages.len) break;
            const key = std.fmt.allocPrint(keep, "{c}{s}", .{ @as(u8, @backingInt(o.in.packages[i])), n }) catch return null;
            o.module_by_name.put(o.in.gpa, key, @intCast(i)) catch return null;
        }
    }
    var buf: [512]u8 = undefined;
    const key = std.fmt.bufPrint(&buf, "{c}{s}", .{ @as(u8, @backingInt(package)), name }) catch return null;
    return o.module_by_name.get(key);
}

/// Whether module `m` has a constructor at index `i`: one of its BIR's
/// constructors, or one of its tagged schemas' (`schemaCtorIndex`).
pub fn hasCtor(o: *Ownership, m: u32, i: u32) Allocator.Error!bool {
    if (m >= o.in.birs.len) return false;
    const bases = try o.schemaCtorBases(m);
    return i < o.in.birs[m].ctors.len + bases[bases.len - 1];
}

/// How many fields constructor `i` of module `m` takes — a BIR
/// constructor's arguments, a tagged schema variant's payload — or null
/// when the module has no such constructor (`hasCtor`). A summary block
/// naming field `k ≥` this is not one (§28.4).
pub fn ctorArity(o: *Ownership, m: u32, i: u32) Allocator.Error!?u32 {
    if (!try o.hasCtor(m, i)) return null;
    const bir = o.in.birs[m];
    if (i < bir.ctors.len) {
        const c = bir.ctors[i];
        return @intCast(bir.extraSlice(.{ .start = c.args_start, .end = c.args_end }, Inst.Index).len);
    }
    const bases = try o.schemaCtorBases(m);
    const k = i - @as(u32, @intCast(bir.ctors.len));
    for (bir.decls, 0..) |d, di| {
        if (k < bases[di] or k >= bases[di + 1]) continue;
        const count = (bases[di + 1] - bases[di]) / 2;
        const variants = SchemaCtor.taggedVariants(bir, d) orelse return null;
        const variant = (k - bases[di]) % count;
        if (variant >= variants.len) return null;
        return @intFromBool(SchemaCtor.variantPayload(bir, variants[variant]));
    }
    return null;
}

/// A tagged schema's constructor in its module's constructor index space
/// (§28.4): after the BIR's own constructors, every tagged schema of the
/// module in declaration order, each with its `Type` family's variants and
/// then its `Encoded` family's. A function of the module's source, as a
/// BIR constructor's index is, so a block can name it. Null when the
/// declaration is no tagged schema of that many variants.
fn schemaCtorIndex(o: *Ownership, m: u32, decl: u32, encoded: bool, variant: u32) Allocator.Error!?u32 {
    if (m >= o.in.birs.len) return null;
    const bir = o.in.birs[m];
    if (decl >= bir.decls.len or bir.decls[decl].kind != .schema) return null;
    const bases = try o.schemaCtorBases(m);
    const count = (bases[decl + 1] - bases[decl]) / 2;
    if (variant >= count) return null;
    return @intCast(bir.ctors.len + bases[decl] + (if (encoded) count else 0) + variant);
}

/// `schemaCtorIndex` of module `m`'s interface schema constructor `i`, as
/// an `ext_schema_ctor` names it.
fn extSchemaCtorIndex(o: *Ownership, m: u32, i: u32) Allocator.Error!?u32 {
    // A caller that hands provenance but no interfaces would name no
    // imported schema constructor: safe, as the reader refuses the block,
    // but every block that names one would quietly never be read.
    if (std.debug.runtime_safety) std.debug.assert(o.in.interfaces.len >= o.in.provenance.len);
    if (m >= o.in.interfaces.len or m >= o.in.provenance.len) return null;
    const iface = &o.in.interfaces[m];
    if (i >= iface.schema_ctors.len) return null;
    const ctor = iface.schema_ctors[i];
    const si = @backingInt(ctor.schema);
    if (si >= iface.schemas.len) return null;
    const schema = iface.schemas[si];
    const from = switch (ctor.endpoint) {
        .type => schema.program_ctors_start,
        .encoded => schema.encoded_ctors_start,
    };
    if (i < from) return null;
    const decl = o.in.provenance[m].schemaDecl(si) orelse return null;
    return o.schemaCtorIndex(m, decl.int(), ctor.endpoint == .encoded, i - from);
}

/// Per declaration of module `m`, where its schema constructors start after
/// the BIR's own; one more entry holds the module's total.
fn schemaCtorBases(o: *Ownership, m: u32) Allocator.Error![]const u32 {
    std.debug.assert(m < o.in.birs.len);
    if (o.schema_ctor_bases.len == 0) {
        o.schema_ctor_bases = try o.in.gpa.alloc(?[]const u32, o.in.birs.len);
        @memset(o.schema_ctor_bases, null);
    }
    if (o.schema_ctor_bases[m]) |b| return b;
    const bir = o.in.birs[m];
    const bases = try o.keep.allocator().alloc(u32, bir.decls.len + 1);
    var at: u32 = 0;
    for (bir.decls, 0..) |d, i| {
        bases[i] = at;
        if (d.kind == .schema) if (SchemaCtor.taggedVariants(bir, d)) |v| {
            at += 2 * @as(u32, @intCast(v.len));
        };
    }
    bases[bir.decls.len] = at;
    o.schema_ctor_bases[m] = bases;
    return bases;
}

/// The name of constructor `i` of module `m`, for a printed path; empty
/// when it has none.
fn ctorName(o: *const Ownership, m: u32, i: u32) []const u8 {
    if (m >= o.in.birs.len or i == none) return "";
    const bir = o.in.birs[m];
    if (i < bir.ctors.len) return o.in.interner.slice(bir.symbol(bir.ctors[i].name));
    const bases = (if (m < o.schema_ctor_bases.len) o.schema_ctor_bases[m] else null) orelse return "";
    const k = i - @as(u32, @intCast(bir.ctors.len));
    for (bir.decls, 0..) |d, di| {
        if (k < bases[di] or k >= bases[di + 1]) continue;
        const count = (bases[di + 1] - bases[di]) / 2;
        const variant = (k - bases[di]) % count;
        const variants = SchemaCtor.taggedVariants(bir, d) orelse return "";
        if (variant >= variants.len) return "";
        return o.in.interner.slice(bir.symbol(@fromBackingInt(@intCast(bir.instData(variants[variant]).lhs))));
    }
    return "";
}

/// A constructor id's module and index in that module's table.
pub fn ctorKey(o: *const Ownership, c: u32) struct { module: u32, index: u32 } {
    const key = o.ctor_key.items[c];
    return .{ .module = @intCast(key >> 32), .index = @truncate(key) };
}

/// A summary read from a block, in this run's normal form: sorted by this
/// run's ids (§28.4).
pub fn normalizeRead(o: *Ownership, s: Summary) Allocator.Error!Summary {
    return o.normalizeRaw(s);
}

/// Whether two summaries say the same, field by field and entry by entry,
/// each first put in this run's normal form — the check that a block loses
/// nothing (§28.3).
fn summaryDeepEql(o: *Ownership, x_in: Summary, y_in: Summary) Allocator.Error!bool {
    const x = try o.normalizeRaw(x_in);
    const y = try o.normalizeRaw(y_in);
    if (x.cast_signature != y.cast_signature or x.cast_grown != y.cast_grown) return false;
    if (x.params != y.params or x.limit != y.limit or x.limit_at != y.limit_at or x.asserted != y.asserted or
        x.once != y.once or x.words != y.words) return false;
    if (x.uses.len != y.uses.len or x.res.len != y.res.len or x.supply.len != y.supply.len or
        x.funs.len != y.funs.len or x.xreq.len != y.xreq.len or x.slots.len != y.slots.len or
        x.klasses.len != y.klasses.len) return false;
    for (x.uses, y.uses) |a, b| if (!useEql(a, b)) return false;
    for (x.res, y.res) |a, b| if (!resEql(a, b)) return false;
    if (x.objs.len != y.objs.len) return false;
    for (x.objs, y.objs) |a, b| if (!resEql(a, b)) return false;
    for (x.supply, y.supply) |a, b| {
        if (a.fun != b.fun or a.k != b.k or a.path != b.path or !a.prov.eql(b.prov) or a.owned != b.owned or
            a.approx != b.approx or !a.xc.eql(b.xc) or !a.sc.eql(b.sc) or !a.rxc.eql(b.rxc) or a.grown != b.grown) return false;
    }
    if (x.rsupply.len != y.rsupply.len) return false;
    for (x.rsupply, y.rsupply) |a, b| {
        if (a.fun != b.fun or a.k != b.k or a.path != b.path or !a.prov.eql(b.prov) or a.owned != b.owned or
            a.approx != b.approx or !a.xc.eql(b.xc) or !a.sc.eql(b.sc) or !a.rxc.eql(b.rxc) or a.grown != b.grown) return false;
    }
    for (x.funs, y.funs) |a, b| {
        var aa = a;
        var bb = b;
        aa.need_if = &.{};
        bb.need_if = &.{};
        if (!std.meta.eql(aa, bb) or !std.mem.eql(u32, a.need_if, b.need_if)) return false;
    }
    for (x.xreq, y.xreq) |a, b| if (!a.eql(b)) return false;
    if (x.rxreq.len != y.rxreq.len) return false;
    for (x.rxreq, y.rxreq) |a, b| if (!a.eql(b)) return false;
    for (x.slots, y.slots) |a, b| if (a[0] != b[0] or a[1] != b[1]) return false;
    for (x.klasses, y.klasses) |a, b| {
        if (!try o.summaryDeepEql(a.sum.*, b.sum.*)) return false;
        if (a.binds.len != b.binds.len or a.cb_js.len != b.cb_js.len) return false;
        for (a.binds, b.binds) |p, q| {
            if (p.local != q.local or p.path != q.path or p.provs.len != q.provs.len) return false;
            for (p.provs, q.provs) |u, v| if (!resEql(u, v)) return false;
        }
        for (a.cb_js, b.cb_js) |p, q| if (p != q) return false;
    }
    return true;
}

fn resEql(a: ResEntry, b: ResEntry) bool {
    return a.path == b.path and a.prov.eql(b.prov) and a.approx == b.approx and a.xc.eql(b.xc) and a.sc.eql(b.sc) and a.rxc.eql(b.rxc) and a.grown == b.grown;
}

/// The module's top-level declarations as strongly connected groups by
/// their references to each other, dependencies first (§16.6).
fn groupsOf(o: *Ownership, m: u32) Allocator.Error!Groups {
    _ = try o.slotsOf(m);
    if (o.groups[m]) |g| return g;
    const keep = o.keep.allocator();
    const bir = o.in.birs[m];
    const n = bir.decls.len;
    var edges: std.ArrayList(u32) = .empty;
    const starts = try keep.alloc(u32, n + 1);
    const self_edge = try keep.alloc(bool, n);
    @memset(self_edge, false);
    const tags = bir.insts.items(.tag);
    const datas = bir.insts.items(.data);
    for (bir.decls, 0..) |d, di| {
        starts[di] = @intCast(edges.items.len);
        if (d.kind != .value) continue;
        var i = d.inst_start.int();
        while (i < d.inst_end.int()) : (i += 1) {
            const target: u32 = switch (tags[i]) {
                .top => datas[i].lhs,
                .method_call => blk: {
                    if (m >= o.in.dispatch.len) break :blk none;
                    const dt = &o.in.dispatch[m];
                    const site = dt.siteOf(@fromBackingInt(i)) orelse break :blk none;
                    const ci = site.callee.unwrap() orelse break :blk none;
                    break :blk switch (dt.term(ci)) {
                        .top => |t| t.decl.int(),
                        else => none,
                    };
                },
                else => none,
            };
            if (target == none or target >= n) continue;
            if (target == di) self_edge[di] = true;
            try edges.append(keep, target);
        }
    }
    starts[n] = @intCast(edges.items.len);
    const g = try Scc.sccGroups(keep, n, edges.items, starts);
    const count = g.starts.len - 1;
    const of = try keep.alloc(u32, n);
    const recursive = try keep.alloc(bool, count);
    for (0..count) |gi| {
        const members = g.order[g.starts[gi]..g.starts[gi + 1]];
        recursive[gi] = members.len > 1 or self_edge[members[0]];
        for (members) |x| of[x] = @intCast(gi);
    }
    const out: Groups = .{ .of = of, .order = g.order, .starts = g.starts, .recursive = recursive };
    o.groups[m] = out;
    return out;
}

fn computeGroup(o: *Ownership, m: u32, d: u32) Allocator.Error!void {
    const groups = try o.groupsOf(m);
    const gi = groups.of[d];
    const all = groups.order[groups.starts[gi]..groups.starts[gi + 1]];
    const bir = o.in.birs[m];
    const slots = o.slots[m].?;
    var members: std.ArrayList(u32) = .empty;
    defer members.deinit(o.in.gpa);
    for (all) |x| {
        const dx = bir.decls[x];
        if (dx.kind != .value or dx.body == .none) continue;
        if (slots[x].state != .none) continue;
        if (try o.assertedRow(m, x)) |row| {
            slots[x] = .{ .state = .done, .sum = row };
            continue;
        }
        // A beni declaration with words has their summary (§24.5); a report
        // walks its body for its lines alone (`run`).
        if (try o.wordsRow(m, x)) |row| {
            slots[x] = .{ .state = .done, .sum = row };
            continue;
        }
        try members.append(o.in.gpa, x);
    }
    std.mem.sort(u32, members.items, {}, std.sort.asc(u32));
    for (members.items) |x| slots[x] = .{ .state = .computing, .sum = .{ .params = bir.decls[x].params } };
    if (!groups.recursive[gi]) {
        for (members.items) |x| {
            // §18.11: a declaration whose parameters and result all cross
            // has the empty summary whatever its body does; a module the run
            // does not report on need not walk it.
            const report = m < o.report_for.len and o.report_for[m];
            slots[x].sum = if (!report and try o.crosses(m, x)) .{ .params = bir.decls[x].params } else try o.walkSummary(m, x, false);
            if (o.isDictFocus(m, x)) slots[x].sum = try o.assertDictFocus(slots[x].sum);
            slots[x].sum = try o.schemaMakerRow(m, x, slots[x].sum);
            if (o.hostedRow(m, x)) |row| slots[x].sum = try o.assertHosted(slots[x].sum, row);
            slots[x].sum = try o.clearMarks(slots[x].sum);
            slots[x].state = .done;
        }
        return;
    }
    // A recursive group whose members all cross is empty too (§18.11).
    if (!(m < o.report_for.len and o.report_for[m])) {
        var all_cross = true;
        for (members.items) |x| if (!try o.crosses(m, x)) {
            all_cross = false;
            break;
        };
        if (all_cross) {
            for (members.items) |x| slots[x] = .{ .state = .done, .sum = .{ .params = bir.decls[x].params } };
            return;
        }
    }
    // Optimistic, joined (§16.6): each round walks every member against
    // the current assumptions and joins what it reads off into them.
    const saved = o.cur_decl;
    defer o.cur_decl = saved;
    var round: u32 = 0;
    while (round < round_cap) : (round += 1) {
        var changed = false;
        for (members.items) |x| {
            const next = try o.walkSummary(m, x, true);
            o.cur_decl = .{ m, x };
            const joined = try o.join(slots[x].sum, next);
            if (!summaryEql(joined, slots[x].sum)) changed = true;
            slots[x].sum = joined;
        }
        if (!changed) break;
    }
    if (round == round_cap) {
        for (members.items) |x| {
            o.cur_decl = .{ m, x };
            slots[x].sum = try o.pessimistic(slots[x].sum, .rounds, round_cap);
            slots[x].lines = null;
        }
    }
    for (members.items) |x| {
        slots[x].sum = try o.schemaMakerRow(m, x, slots[x].sum);
        slots[x].sum = try o.clearMarks(slots[x].sum);
        slots[x].state = .done;
    }
}

/// §16.7 (F3, the owner's choice (a)): a settled summary carries no mark.
/// Only a group's own fixpoint composes its summaries with themselves, so
/// the marks end with it, and a summary made here equals one read back
/// from the summary block, which does not carry them.
fn summaryHasMarks(s: Summary) bool {
    if (s.cast_grown != 0) return true;
    for (s.uses) |u| if (u.grown != 0) return true;
    for ([_][]const ResEntry{ s.res, s.objs }) |entries| for (entries) |r| if (r.grown != 0) return true;
    for ([_][]const SupplyEntry{ s.supply, s.rsupply }) |entries| for (entries) |e| if (e.grown != 0) return true;
    for (s.klasses) |k| {
        if (summaryHasMarks(k.sum.*)) return true;
        for (k.binds) |b| for (b.provs) |r| if (r.grown != 0) return true;
    }
    return false;
}

fn clearMarks(o: *Ownership, s: Summary) Allocator.Error!Summary {
    if (!summaryHasMarks(s)) return s;
    const keep = o.keep.allocator();
    var t = s;
    t.cast_grown = 0;
    const uses = try keep.dupe(UseEntry, s.uses);
    for (uses) |*u| u.grown = 0;
    t.uses = uses;
    const res = try keep.dupe(ResEntry, s.res);

    for (res) |*r| r.grown = 0;
    const supply = try keep.dupe(SupplyEntry, s.supply);
    for (supply) |*e| e.grown = 0;
    t.res = res;
    const objs = try keep.dupe(ResEntry, s.objs);
    for (objs) |*r| r.grown = 0;
    t.objs = objs;
    const rsupply = try keep.dupe(SupplyEntry, s.rsupply);
    for (rsupply) |*e| e.grown = 0;
    t.rsupply = rsupply;
    t.supply = supply;
    const klasses = try keep.dupe(Carried, s.klasses);
    for (klasses) |*k| {
        const sum = try keep.create(Summary);
        sum.* = try o.clearMarks(k.sum.*);
        k.sum = sum;
        const binds = try keep.dupe(Carried.Bind, k.binds);
        for (binds) |*b| {
            const provs = try keep.dupe(ResEntry, b.provs);
            for (provs) |*r| r.grown = 0;
            b.provs = provs;
        }
        k.binds = binds;
    }
    t.klasses = klasses;
    return o.normalize(t);
}

/// Whether every parameter of the function `d` and its result cross
/// (§4.4): no cell goes in or comes out, so its summary is empty.
fn crosses(o: *Ownership, m: u32, d: u32) Allocator.Error!bool {
    const bir = o.in.birs[m];
    const decl = bir.decls[d];
    if (decl.params == 0) return false;
    const km = &o.in.modules[m];
    const local_type = km.local_type[decl.locals_start..decl.locals_end];
    for (bir.extraSlice(.{ .start = decl.params_start, .end = decl.params_end }, Inst.Index)) |p| {
        const l = switch (bir.instTag(p)) {
            .pat_var => bir.instData(p).lhs,
            else => return false,
        };
        if (l >= local_type.len) return false;
        const v = local_type[l].unwrap() orelse return false;
        if (try o.tracked(&km.store, v, 0)) return false;
    }
    const body = decl.body.unwrap() orelse return false;
    const v = km.inst_type[body.int()].unwrap() orelse return false;
    return !try o.tracked(&km.store, v, 0);
}

/// One walk of `d` and the summary read off it.
fn walkSummary(o: *Ownership, m: u32, d: u32, recursive: bool) Allocator.Error!Summary {
    // One arena per depth of nested walks (a call computes its callee's
    // summary mid-walk), kept across walks (§18.11).
    const depth = o.walk_depth;
    o.walk_depth += 1;
    defer o.walk_depth -= 1;
    const saved_walking = o.walking;
    o.walking = m;
    defer o.walking = saved_walking;
    const saved_decl = o.cur_decl;
    o.cur_decl = .{ m, d };
    defer o.cur_decl = saved_decl;
    var own: Arena = .init(o.in.gpa);
    defer own.deinit();
    const scratch = if (depth < o.walk_arenas.len) blk: {
        if (o.walk_arenas[depth] == null) o.walk_arenas[depth] = .init(o.in.gpa);
        break :blk &o.walk_arenas[depth].?;
    } else &own;
    defer scratch.reset(.keep_all);
    const report = m < o.report_for.len and o.report_for[m];
    var w = o.walker(m, d, scratch.allocator(), if (report) .report else .summary);
    w.recursive = recursive;
    try w.walkDecl(w.decl.body.unwrap().?);
    var lines: std.ArrayList(Demand) = .empty;
    try w.resolve(&lines);
    if (report) {
        o.slots[m].?[d].lines = try lines.toOwnedSlice(o.out.allocator());
        o.slots[m].?[d].eager_reads = w.eager_reads;
        o.slots[m].?[d].hoist_table = try w.hoist_table.table().clone(o.out.allocator());
    }
    const s = try w.readOff();
    // A limit the walk reached (a fixpoint, `value-cells`) makes the summary
    // the pessimistic one, as §16.7 says, so that what its callers reject
    // through it rests on the limit (`limit_callee`): a condition it lowered
    // reaches a caller only as a lost one, which says nothing of the limit.
    for (o.limit_hits.items) |h| if (h.module == m and h.decl == d) return o.pessimistic(s, h.limit, h.at);
    return s;
}

// ---------------------------------------------------------------------------
// The lattice (§16.2)
// ---------------------------------------------------------------------------

/// §30.9: a copy of `s` whose every slice is the run's own (`keep`), for a
/// summary that outlives the memory `s` was read into — a block's.
pub fn cloneSummary(o: *Ownership, s: *const Summary) Allocator.Error!*const Summary {
    const keep = o.keep.allocator();
    const xsum = struct {
        fn f(a: Allocator, x: XSum) Allocator.Error!XSum {
            return .{ .no = x.no, .atoms = try dupeAtoms(a, x.atoms) };
        }
    }.f;
    const res = try keep.alloc(ResEntry, s.res.len);
    for (res, s.res) |*d, r| d.* = .{ .path = r.path, .prov = r.prov, .approx = r.approx, .xc = try xsum(keep, r.xc), .sc = try xsum(keep, r.sc), .rxc = try xsum(keep, r.rxc), .grown = r.grown };
    const supply = try keep.alloc(SupplyEntry, s.supply.len);
    for (supply, s.supply) |*d, e| {
        d.* = e;
        d.xc = try xsum(keep, e.xc);
        d.sc = try xsum(keep, e.sc);
        d.rxc = try xsum(keep, e.rxc);
    }
    const objs = try keep.alloc(ResEntry, s.objs.len);
    for (objs, s.objs) |*d, r| d.* = .{ .path = r.path, .prov = r.prov, .approx = r.approx, .xc = try xsum(keep, r.xc), .sc = try xsum(keep, r.sc), .rxc = try xsum(keep, r.rxc), .grown = r.grown };
    const rsupply = try keep.alloc(SupplyEntry, s.rsupply.len);
    for (rsupply, s.rsupply) |*d, e| {
        d.* = e;
        d.xc = try xsum(keep, e.xc);
        d.sc = try xsum(keep, e.sc);
        d.rxc = try xsum(keep, e.rxc);
    }
    const klasses = try keep.alloc(Carried, s.klasses.len);
    for (klasses, s.klasses) |*d, k| {
        const binds = try keep.alloc(Carried.Bind, k.binds.len);
        for (binds, k.binds) |*b, kb| b.* = .{ .local = kb.local, .path = kb.path, .provs = try keep.dupe(ResEntry, kb.provs) };
        d.* = .{ .sum = try o.cloneSummary(k.sum), .binds = binds, .cb_js = try keep.dupe(u32, k.cb_js) };
    }
    const out = try keep.create(Summary);
    out.* = s.*;
    out.uses = try keep.dupe(UseEntry, s.uses);
    out.res = res;
    out.supply = supply;
    out.objs = objs;
    out.rsupply = rsupply;
    const funs = try keep.dupe(FunFacts, s.funs);
    for (funs) |*f| f.need_if = try keep.dupe(u32, f.need_if);
    out.funs = funs;
    out.xreq = try dupeAtoms(keep, s.xreq);
    out.rxreq = try dupeAtoms(keep, s.rxreq);
    out.slots = try keep.dupe([2]u32, s.slots);
    out.klasses = klasses;
    return out;
}

fn summaryEql(x: Summary, y: Summary) bool {
    if (x.cast_signature != y.cast_signature or x.cast_grown != y.cast_grown) return false;
    if (x.limit != y.limit or x.limit_at != y.limit_at or x.params != y.params or x.once != y.once) return false;
    if (x.uses.len != y.uses.len or x.res.len != y.res.len or x.supply.len != y.supply.len or x.funs.len != y.funs.len) return false;
    for (x.uses, y.uses) |a, b| if (!useEql(a, b)) return false;
    for (x.res, y.res) |a, b| if (!resEql(a, b)) return false;
    if (x.objs.len != y.objs.len) return false;
    for (x.objs, y.objs) |a, b| if (!resEql(a, b)) return false;
    for (x.supply, y.supply) |a, b| if (a.fun != b.fun or a.k != b.k or a.path != b.path or !a.prov.eql(b.prov) or a.owned != b.owned or a.approx != b.approx or !a.xc.eql(b.xc) or !a.sc.eql(b.sc) or !a.rxc.eql(b.rxc) or a.grown != b.grown) return false;
    if (x.rsupply.len != y.rsupply.len) return false;
    for (x.rsupply, y.rsupply) |a, b| if (a.fun != b.fun or a.k != b.k or a.path != b.path or !a.prov.eql(b.prov) or a.owned != b.owned or a.approx != b.approx or !a.xc.eql(b.xc) or !a.sc.eql(b.sc) or !a.rxc.eql(b.rxc) or a.grown != b.grown) return false;
    for (x.funs, y.funs) |a, b| {
        var aa = a;
        var bb = b;
        aa.need_if = &.{};
        bb.need_if = &.{};
        if (!std.meta.eql(aa, bb) or !std.mem.eql(u32, a.need_if, b.need_if)) return false;
    }
    if (x.xreq.len != y.xreq.len) return false;
    for (x.xreq, y.xreq) |a, b| if (!a.eql(b)) return false;
    if (x.rxreq.len != y.rxreq.len) return false;
    for (x.rxreq, y.rxreq) |a, b| if (!a.eql(b)) return false;
    if (x.slots.len != y.slots.len or x.klasses.len != y.klasses.len) return false;
    for (x.slots, y.slots) |a, b| if (a[0] != b[0] or a[1] != b[1]) return false;
    for (x.klasses, y.klasses) |a, b| {
        if (!summaryEql(a.sum.*, b.sum.*) or a.binds.len != b.binds.len or a.cb_js.len != b.cb_js.len) return false;
        for (a.binds, b.binds) |p, q| {
            if (p.local != q.local or p.path != q.path or p.provs.len != q.provs.len) return false;
            for (p.provs, q.provs) |u, v| if (!resEql(u, v)) return false;
        }
        if (!std.mem.eql(u32, a.cb_js, b.cb_js)) return false;
    }
    return true;
}

test "recursive summaries keep iterating when only container ownership changes" {
    const before: Summary = .{ .params = 0, .res = &.{.{ .path = eps, .prov = .{ .kind = .fresh, .a = 1 }, .xc = .{ .no = 1 } }} };
    const after: Summary = .{ .params = 0, .res = &.{.{ .path = eps, .prov = .{ .kind = .fresh, .a = 1 }, .xc = .{ .no = 1 }, .sc = .{ .no = 1 } }} };
    try std.testing.expect(!summaryEql(before, after));
    try std.testing.expect(!summaryEql(after, before));
    try std.testing.expect(summaryEql(after, after));
}

/// A pure summary-instantiation scenario supplementing the corpus: a fold
/// evaluated by the entry protocol receives an init cell numbered above 100000.
fn testFoldAtEntry(initial_sc: XSum) !struct { initial: u32, result: u32 } {
    const gpa = std.testing.allocator;
    var arena: std.heap.ArenaAllocator = .init(gpa);
    defer arena.deinit();
    const graph: Graph = .{ .modules = .empty, .deps = &.{}, .order = &.{}, .diagnostics = &.{}, .name_rows = &.{}, .rows = &.{}, .cycle_members = &.{} };
    const types = Types.empty;
    const interner: InternPool.Global = .{};
    var o: Ownership = .init(.{
        .gpa = gpa,
        .graph = &graph,
        .birs = &.{},
        .provenance = &.{},
        .dispatch = &.{},
        .modules = &.{},
        .types = &types,
        .interner = &interner,
        .module_names = &.{},
        .packages = &.{},
        .spans = &.{},
        .positions = .{ .ctx = &graph, .get = struct {
            fn get(_: *const anyopaque, _: u32, _: u32) Position {
                return .{ .line = 0, .col = 0 };
            }
        }.get },
    });
    defer o.deinit();
    try o.seedPaths();
    const bir: Bir = .{ .insts = .empty, .extra = &.{}, .string_bytes = &.{}, .symbols = &.{}, .decls = &.{}, .ctors = &.{}, .locals = &.{}, .refs = &.{}, .imports = &.{}, .exposed = &.{}, .interface = &.{}, .diagnostics = &.{}, .module_doc_start = 0, .module_doc_end = 0 };
    var store: TypeStore = .init(gpa);
    defer store.deinit();
    var w: Walker = .{ .o = &o, .m = 0, .bir = &bir, .decl = std.mem.zeroes(Bir.Decl), .decl_index = 0, .store = &store, .inst_type = &.{}, .local_type = &.{}, .a = arena.allocator(), .mode = .summary };
    try w.conds.appendSlice(w.a, &.{ .{ .atoms = &.{} }, .{ .atoms = &.{} }, .{ .atoms = &.{} }, .{ .atoms = &.{} } });
    const acc = Prov{ .kind = .param, .a = 1 };
    const condition: XSum = .{ .atoms = &.{.{ .kind = .spine, .a = acc }} };
    // A callback either transfers its accumulator or returns a new container
    // carrying the same exclusivity obligation; no supplied cell is an allocation.
    const callback: Summary = .{
        .params = 2,
        .uses = &.{.{ .param = 1, .path = eps, .bits = bit_w }},
        .res = &.{
            .{ .path = eps, .prov = acc, .xc = .{ .no = 1 }, .sc = condition },
            .{ .path = eps, .prov = .{ .kind = .fresh, .a = 1 }, .xc = .{ .no = 1 }, .sc = condition },
        },
    };
    try w.closures.append(w.a, .{ .captures = &.{}, .class = &callback });
    const actual = try w.single(.{ .kind = .closure, .a = 0 });
    const initial_summary: Summary = .{ .params = 0, .res = &.{.{ .path = eps, .prov = .{ .kind = .fresh, .a = 1 }, .xc = .{ .no = 1 }, .sc = initial_sc }} };
    const entry_class = [_]Walker.Class{.{ .closure = 0 }};
    const initial = try w.entryResMode(@fromBackingInt(0), .{ .classes = &entry_class, .sums = &.{&initial_summary} }, &.{}, Walker.entry_init_ns, true, false);
    try std.testing.expectEqual(@as(u32, 100001), w.cells.items[initial[0].cell].b);
    const fold: Summary = .{
        .params = 3,
        .funs = &.{.{ .param = 2, .calls = .many }},
        .supply = &.{
            .{ .fun = 2, .k = 1, .path = eps, .prov = acc, .owned = true },
            .{ .fun = 2, .k = 1, .path = eps, .prov = .{ .kind = .cb, .a = 2 }, .owned = true },
        },
        .res = &.{.{ .path = eps, .prov = .{ .kind = .cb, .a = 2 } }},
    };
    const result = try w.entryResMode(@fromBackingInt(0), .{ .classes = &entry_class, .sums = &.{&fold} }, &.{ &.{}, initial, actual }, Walker.entry_view_ns, true, false);
    return .{ .initial = try w.spineCond(initial), .result = try w.spineCond(result) };
}

test "a fold inside an entry instantiation does not seed its shared init cell" {
    const actual = try testFoldAtEntry(.{ .no = 2 });
    try std.testing.expectEqualDeep(@as(@TypeOf(actual), .{ .initial = cond_shared, .result = cond_shared }), actual);
}

test "a fold inside an entry instantiation preserves its fresh init cell" {
    const actual = try testFoldAtEntry(.{});
    try std.testing.expectEqualDeep(@as(@TypeOf(actual), .{ .initial = cond_yes, .result = cond_yes }), actual);
}

/// The conjunction of two conditions (§18.2): failing exactly beats failing
/// approximately, and a holding condition rests on both atom sets.
fn xsumAnd(a: Allocator, x: XSum, y: XSum) Allocator.Error!XSum {
    if (x.no != 0 or y.no != 0) return .{ .no = @max(x.no, y.no) };
    if (y.atoms.len == 0) return x;
    if (x.atoms.len == 0) return y;
    if (x.eql(y)) return x;
    const all = try a.alloc(XAtom, x.atoms.len + y.atoms.len);
    @memcpy(all[0..x.atoms.len], x.atoms);
    @memcpy(all[x.atoms.len..], y.atoms);
    return .{ .atoms = sortAtoms(all) };
}

pub fn sortAtoms(all: []XAtom) []const XAtom {
    std.mem.sort(XAtom, all, {}, struct {
        fn less(_: void, p: XAtom, q: XAtom) bool {
            return p.less(q);
        }
    }.less);
    var n: usize = 0;
    for (all) |t| {
        if (n > 0 and all[n - 1].eql(t)) continue;
        all[n] = t;
        n += 1;
    }
    return all[0..n];
}

/// Classes with different callback protocols remain alternatives.
fn carriedProtocol(a: Allocator, s: *const Summary) Allocator.Error![]const u32 {
    var key: std.ArrayList(u32) = .empty;
    try key.appendSlice(a, &.{ s.params, @intCast(s.slots.len) });
    for (s.slots) |slot| try key.appendSlice(a, &slot);
    for (s.funs) |f| if (f.send != none or f.rneed or f.need_if.len != 0) {
        try key.appendSlice(a, &.{ f.param, f.send, @intFromBool(f.rneed), @intCast(f.need_if.len) });
        try key.appendSlice(a, f.need_if);
    };
    return key.items;
}

fn joinCarried(o: *Ownership, x: Carried, y: Carried) Allocator.Error!Carried {
    const keep = o.keep.allocator();
    const sum = try keep.create(Summary);
    sum.* = try o.join(x.sum.*, y.sum.*);
    var binds: std.ArrayList(Carried.Bind) = .empty;
    try binds.appendSlice(keep, x.binds);
    try binds.appendSlice(keep, y.binds);
    std.mem.sort(Carried.Bind, binds.items, {}, struct {
        fn less(_: void, a: Carried.Bind, b: Carried.Bind) bool {
            return if (a.local != b.local) a.local < b.local else a.path < b.path;
        }
    }.less);
    var n: usize = 0;
    for (binds.items) |b| {
        if (n > 0 and binds.items[n - 1].local == b.local and binds.items[n - 1].path == b.path) {
            const before = binds.items[n - 1].provs;
            const both = try keep.alloc(ResEntry, before.len + b.provs.len);
            @memcpy(both[0..before.len], before);
            @memcpy(both[before.len..], b.provs);
            binds.items[n - 1].provs = try sortedRes(keep, both);
        } else {
            binds.items[n] = b;
            n += 1;
        }
    }
    var callbacks: std.ArrayList(u32) = .empty;
    try callbacks.appendSlice(keep, x.cb_js);
    for (y.cb_js) |j| if (std.mem.indexOfScalar(u32, callbacks.items, j) == null) try callbacks.append(keep, j);
    std.mem.sort(u32, callbacks.items, {}, std.sort.asc(u32));
    return .{ .sum = sum, .binds = binds.items[0..n], .cb_js = callbacks.items };
}

const JoinedCarried = struct { classes: []const Carried, x: []const u32, y: []const u32 };

/// Union the read-only function classes a recursive result may carry.
fn joinCarriers(o: *Ownership, x: []const Carried, y: []const Carried) Allocator.Error!JoinedCarried {
    const keep = o.keep.allocator();
    var classes: std.ArrayList(Carried) = .empty;
    var keys: std.HashMapUnmanaged([]const u32, u32, U32SliceContext, std.hash_map.default_max_load_percentage) = .empty;
    const maps = [2][]u32{ try keep.alloc(u32, x.len), try keep.alloc(u32, y.len) };
    for ([_][]const Carried{ x, y }, maps) |input, map| for (input, map) |c, *index| {
        const g = try keys.getOrPut(keep, try carriedProtocol(keep, c.sum));
        if (!g.found_existing) {
            g.value_ptr.* = @intCast(classes.items.len);
            try classes.append(keep, c);
        }
        index.* = g.value_ptr.*;
    };
    const initialized = try keep.alloc(bool, classes.items.len);
    @memset(initialized, false);
    for ([_][]const Carried{ x, y }, maps) |input, map| for (input, map) |c, index| {
        if (initialized[index]) {
            classes.items[index] = try o.joinCarried(classes.items[index], c);
        } else {
            classes.items[index] = c;
            initialized[index] = true;
        }
    };
    return .{ .classes = classes.items, .x = maps[0], .y = maps[1] };
}

fn joinedClass(p: Prov, map: []const u32) Prov {
    var out = p;
    // 'none' is an unknown function alternative, not a class index.
    if (out.kind == .klass and out.a < map.len) out.a = map[out.a];
    return out;
}

fn join(o: *Ownership, x: Summary, y: Summary) Allocator.Error!Summary {
    if (x.limit != .none) return x;
    if (y.limit != .none) return o.pessimistic(x, y.limit, y.limit_at);
    const keep = o.keep.allocator();
    const carried = try o.joinCarriers(x.klasses, y.klasses);
    std.debug.assert(x.slots.len <= y.slots.len);
    for (x.slots, y.slots[0..x.slots.len]) |a, b| std.debug.assert(a[0] == b[0] and a[1] == b[1]);
    var uses: std.ArrayList(UseEntry) = .empty;
    try uses.appendSlice(keep, x.uses);
    try uses.appendSlice(keep, y.uses);
    var res: std.ArrayList(ResEntry) = .empty;
    for (x.res) |r| {
        var next = r;
        next.prov = joinedClass(r.prov, carried.x);
        try res.append(keep, next);
    }
    for (y.res) |r| {
        var next = r;
        next.prov = joinedClass(r.prov, carried.y);
        try res.append(keep, next);
    }
    var supply: std.ArrayList(SupplyEntry) = .empty;
    try supply.appendSlice(keep, x.supply);
    try supply.appendSlice(keep, y.supply);
    // §31.7: the records the result holds and the callbacks are handed,
    // joined as `res` and `supply` are.
    var objs: std.ArrayList(ResEntry) = .empty;
    try objs.appendSlice(keep, x.objs);
    try objs.appendSlice(keep, y.objs);
    var rsupply: std.ArrayList(SupplyEntry) = .empty;
    try rsupply.appendSlice(keep, x.rsupply);
    try rsupply.appendSlice(keep, y.rsupply);
    var funs: std.ArrayList(FunFacts) = .empty;
    try funs.appendSlice(keep, x.funs);
    try funs.appendSlice(keep, y.funs);
    var xreq: std.ArrayList(XAtom) = .empty;
    try xreq.appendSlice(keep, x.xreq);
    try xreq.appendSlice(keep, y.xreq);
    var rxreq: std.ArrayList(XAtom) = .empty;
    try rxreq.appendSlice(keep, x.rxreq);
    try rxreq.appendSlice(keep, y.rxreq);
    return o.normalize(.{
        .params = @max(x.params, y.params),
        .cast_signature = if (y.cast_signature != none) y.cast_signature else x.cast_signature,
        .cast_grown = gJoin(x.cast_grown, y.cast_grown),
        .uses = uses.items,
        .res = res.items,
        .objs = objs.items,
        .supply = supply.items,
        .rsupply = rsupply.items,
        .funs = funs.items,
        .xreq = xreq.items,
        .rxreq = rxreq.items,
        .once = x.once or y.once,
        .slots = y.slots,
        .klasses = carried.classes,
    });
}

/// A finite set of possible writers. Unlike a field write set, its empty
/// set means no dependency, so joining it never discards another set.
fn unionGuards(a: Allocator, x: []const u32, y: []const u32) Allocator.Error![]const u32 {
    const out = try a.alloc(u32, x.len + y.len);
    @memcpy(out[0..x.len], x);
    @memcpy(out[x.len..], y);
    std.mem.sort(u32, out, {}, std.sort.asc(u32));
    var n: usize = 0;
    for (out) |writer| {
        if (n != 0 and out[n - 1] == writer) continue;
        out[n] = writer;
        n += 1;
    }
    return out[0..n];
}

/// Sorted, merged, and within the checker's limits (§16.7): a summary that
/// needs more entries than they allow is the pessimistic one, and the
/// declaration it belongs to is an error. Nothing is ever cut to fit.
fn normalize(o: *Ownership, s: Summary) Allocator.Error!Summary {
    const out = try o.normalizeRaw(s);
    if (out.limit != .none) return out;
    if (overLimit(out)) |over| return o.pessimistic(out, over.limit, over.at);
    return out;
}

const Over = struct { limit: Limit, at: u32 };

/// The first of §16.7's limits a normalized summary is past, with what it
/// measured: its entries in all, then its entries at one path.
fn overLimit(s: Summary) ?Over {
    var total = s.uses.len + s.res.len + s.objs.len + s.supply.len + s.rsupply.len;
    for (s.funs) |f| total += f.need_if.len;
    if (total > entry_cap) return .{ .limit = .entries, .at = @intCast(@min(total, std.math.maxInt(u32))) };
    var most: usize = 0;
    var streak: usize = 0;
    for (s.res, 0..) |r, i| {
        streak = if (i > 0 and s.res[i - 1].path == r.path) streak + 1 else 1;
        most = @max(most, streak);
    }
    streak = 0;
    for (s.objs, 0..) |r, i| {
        streak = if (i > 0 and s.objs[i - 1].path == r.path) streak + 1 else 1;
        most = @max(most, streak);
    }
    streak = 0;
    for (s.supply, 0..) |e, i| {
        const same = i > 0 and s.supply[i - 1].fun == e.fun and s.supply[i - 1].k == e.k and s.supply[i - 1].path == e.path;
        streak = if (same) streak + 1 else 1;
        most = @max(most, streak);
    }
    if (most > path_entry_cap) return .{ .limit = .path_entries, .at = @intCast(most) };
    var atoms: usize = atomsWeight(s.xreq);
    for (s.res) |r| atoms += atomsWeight(r.xc.atoms) + atomsWeight(r.sc.atoms);
    for (s.supply) |e| atoms += atomsWeight(e.xc.atoms) + atomsWeight(e.sc.atoms);
    if (atoms > condition_cap) return .{ .limit = .conditions, .at = @intCast(@min(atoms, std.math.maxInt(u32))) };
    return null;
}

test "a condition lowered at a limit is never read as one that holds" {
    var arena: std.heap.ArenaAllocator = .init(std.testing.allocator);
    defer arena.deinit();
    // `condSame` and `spineOfSep` read only `conds` and `a`.
    var w: Walker = .{ .o = undefined, .m = 0, .bir = undefined, .decl = std.mem.zeroes(Bir.Decl), .decl_index = 0, .store = undefined, .inst_type = &.{}, .local_type = &.{}, .a = arena.allocator(), .mode = .summary };
    try w.conds.appendSlice(w.a, &fixed_conds);
    try std.testing.expectEqual(cond_fixed_last + 1, w.conds.items.len);
    try std.testing.expect(!w.condSame(cond_limit, cond_yes));
    try std.testing.expect(!w.condSame(cond_yes, cond_limit));
    try std.testing.expect(!w.condSame(cond_limit, cond_lost));
    try std.testing.expect(w.condSame(cond_limit, cond_limit));
    // Two arrived cells for the atom (`mkCond` reads each through `listFacing`).
    try w.cells.appendSlice(w.a, &.{ .{ .kind = .param, .a = 0 }, .{ .kind = .param, .a = 1 } });
    const sep = try w.sepCond(0, 1);
    try std.testing.expect(!w.condSame(cond_limit, sep));
    try std.testing.expect(!w.condSame(sep, cond_limit));
    try std.testing.expectEqual(cond_limit, try w.spineOfSep(cond_limit));
    try std.testing.expectEqual(cond_lost, try w.spineOfSep(cond_lost));
}

test "a summary past a limit says which and what it measured" {
    const gpa = std.testing.allocator;
    const res = try gpa.alloc(ResEntry, path_entry_cap + 1);
    defer gpa.free(res);
    for (res, 0..) |*r, i| r.* = .{ .path = eps, .prov = .{ .kind = .param, .a = @intCast(i) } };
    try std.testing.expectEqual(Over{ .limit = .path_entries, .at = path_entry_cap + 1 }, overLimit(.{ .params = 0, .res = res }).?);
    try std.testing.expectEqual(@as(?Over, null), overLimit(.{ .params = 0, .res = res[0..path_entry_cap] }));
    const uses = try gpa.alloc(UseEntry, entry_cap + 1);
    defer gpa.free(uses);
    for (uses, 0..) |*u, i| u.* = .{ .param = 0, .path = @intCast(i), .bits = bit_r };
    try std.testing.expectEqual(Over{ .limit = .entries, .at = entry_cap + 1 }, overLimit(.{ .params = 1, .uses = uses }).?);
    const atoms = try gpa.alloc(XAtom, condition_cap + 1);
    defer gpa.free(atoms);
    @memset(atoms, .{ .kind = .excl, .a = .{ .kind = .param } });
    const one = [_]ResEntry{.{ .path = eps, .prov = .{ .kind = .param }, .sc = .{ .atoms = atoms } }};
    try std.testing.expectEqual(Over{ .limit = .conditions, .at = condition_cap + 1 }, overLimit(.{ .params = 1, .res = &one }).?);
}

/// Two written-field sets (§31.7), merged and sorted. The empty set is
/// every field — a write names at least one, so it never means none: a
/// write a block could not name, an open type's `allFields`, a callback's
/// loan. It absorbs: every field together with `a` is every field.
fn unionFields(a: Allocator, x: []const u32, y: []const u32) Allocator.Error![]const u32 {
    if (x.len == 0 or y.len == 0) return &.{};
    var out: std.ArrayList(u32) = .empty;
    var i: usize = 0;
    var j: usize = 0;
    while (i < x.len or j < y.len) {
        if (j == y.len or (i < x.len and x[i] < y[j])) {
            try out.append(a, x[i]);
            i += 1;
        } else if (i == x.len or y[j] < x[i]) {
            try out.append(a, y[j]);
            j += 1;
        } else {
            try out.append(a, x[i]);
            i += 1;
            j += 1;
        }
    }
    return out.items;
}

/// Whether `id` was marked in the column `marks` already; marks it.
fn markOnce(a: Allocator, marks: *std.ArrayList(bool), id: u32) Allocator.Error!bool {
    if (marks.items.len <= id) try marks.appendNTimes(a, false, id + 1 - marks.items.len);
    defer marks.items[id] = true;
    return marks.items[id];
}

/// The first of `range` (indices into `uses`, ascending, so by point) whose
/// use is at `point` or after.
fn firstAtLeast(range: []const u32, uses: []const Use, point: u32) usize {
    return std.sort.partitionPoint(u32, range, UsePoint{ .uses = uses, .point = point }, UsePoint.before);
}

const UsePoint = struct {
    uses: []const Use,
    point: u32,
    fn before(c: UsePoint, ui: u32) bool {
        return c.uses[ui].point < c.point;
    }
};

/// `unionFields` folded over `sets`, in one sort: the same answer, since
/// the empty set absorbs and two strictly ascending sets merge to their
/// sorted union. A set that is not strictly ascending is folded as before.
fn unionFieldSets(a: Allocator, sets: []const []const u32) Allocator.Error![]const u32 {
    var total: usize = 0;
    for (sets) |x| {
        if (x.len == 0) return &.{};
        for (x[1..], 0..) |f, i| if (f <= x[i]) {
            var acc = sets[0];
            for (sets[1..]) |y| acc = try unionFields(a, acc, y);
            return acc;
        };
        total += x.len;
    }
    const out = try a.alloc(u32, total);
    var k: usize = 0;
    for (sets) |x| {
        @memcpy(out[k..][0..x.len], x);
        k += x.len;
    }
    std.mem.sort(u32, out, {}, std.sort.asc(u32));
    var n: usize = 0;
    for (out) |f| {
        if (n > 0 and out[n - 1] == f) continue;
        out[n] = f;
        n += 1;
    }
    return out[0..n];
}

/// `entries` sorted by path and provenance, each pair at one path merged.
fn sortedRes(keep: Allocator, entries: []const ResEntry) Allocator.Error![]const ResEntry {
    const res = try keep.dupe(ResEntry, entries);
    std.mem.sort(ResEntry, res, {}, struct {
        fn less(_: void, x: ResEntry, y: ResEntry) bool {
            if (x.path != y.path) return x.path < y.path;
            return x.prov.less(y.prov);
        }
    }.less);
    var nr: usize = 0;
    for (res) |r| {
        if (nr > 0 and res[nr - 1].path == r.path and res[nr - 1].prov.eql(r.prov)) {
            res[nr - 1].approx = res[nr - 1].approx or r.approx;
            res[nr - 1].grown = gJoin(res[nr - 1].grown, r.grown);
            res[nr - 1].xc = try xsumAnd(keep, res[nr - 1].xc, r.xc);
            res[nr - 1].sc = try xsumAnd(keep, res[nr - 1].sc, r.sc);
            res[nr - 1].rxc = try xsumAnd(keep, res[nr - 1].rxc, r.rxc);
            continue;
        }
        res[nr] = r;
        nr += 1;
    }
    return res[0..nr];
}

/// `entries` sorted by function, parameter, path and provenance, each pair
/// that agrees on all four merged.
fn sortedSupply(keep: Allocator, entries: []const SupplyEntry) Allocator.Error![]const SupplyEntry {
    const supply = try keep.dupe(SupplyEntry, entries);
    std.mem.sort(SupplyEntry, supply, {}, struct {
        fn less(_: void, x: SupplyEntry, y: SupplyEntry) bool {
            if (x.fun != y.fun) return x.fun < y.fun;
            if (x.k != y.k) return x.k < y.k;
            if (x.path != y.path) return x.path < y.path;
            return x.prov.less(y.prov);
        }
    }.less);
    var ns: usize = 0;
    for (supply) |e| {
        if (ns > 0) {
            const p = &supply[ns - 1];
            if (p.fun == e.fun and p.k == e.k and p.path == e.path and p.prov.eql(e.prov)) {
                // A borrowed supply is exact when either side's reason is.
                const exact = (!p.owned and !p.approx) or (!e.owned and !e.approx);
                p.owned = p.owned and e.owned;
                p.approx = !p.owned and !exact;
                p.xc = try xsumAnd(keep, p.xc, e.xc);
                p.sc = try xsumAnd(keep, p.sc, e.sc);
                p.rxc = try xsumAnd(keep, p.rxc, e.rxc);
                p.grown = gJoin(p.grown, e.grown);
                continue;
            }
        }
        supply[ns] = e;
        ns += 1;
    }
    return supply[0..ns];
}

/// §31.4 item 6: a list condition's record twin — `excl`, `sep` and
/// `keep` as their record forms (`rkeepShape` for a keep); a spine's atoms
/// are a list's array, and dropped. Sound because an asserted row's
/// condition says where each element comes from — which argument's
/// positions, which callback's answers — whatever the element's type, so it
/// says the same of a record element as of a list element (core's rows are
/// polymorphic; `ownership/RecordContentsBuilt` drives `repeat`, `append`
/// and `concat` with records). A failure keeps its kind: `{shared}`, one
/// cell at two places, is one record at two places when the cell is a
/// record; it only labels a refusal exact.
fn recordTwin(o: *Ownership, x: XSum) Allocator.Error!XSum {
    if (x.no != 0) return x;
    var out: std.ArrayList(XAtom) = .empty;
    for (x.atoms) |t| switch (t.kind) {
        .excl, .sep, .keep, .apart => try out.append(o.keep.allocator(), t),
        .spine, .sep_spine, .keep_spine, .apart_spine, .sep_root => {},
    };
    return .{ .atoms = out.items };
}

/// `s` with each entry's record condition the twin of its list one.
fn recordTwins(o: *Ownership, s: Summary) Allocator.Error!Summary {
    const keep = o.keep.allocator();
    var out = s;
    const res = try keep.dupe(ResEntry, s.res);
    for (res) |*r| {
        // A row that states its record condition on its own keeps it
        // (`append`'s, #420): an entry's `rxc` starts lost, so one that
        // does not is the row's.
        if (r.rxc.no == 0) continue;
        r.rxc = try o.recordTwin(r.xc);
        // A `foreign`'s `exclusive` word speaks of its list's lists
        // (`boundary.md` §4), not of records it may hold twice.
        if (s.words and r.rxc.no == 0 and r.rxc.atoms.len == 0 and r.prov.kind != .param) r.rxc = .{ .no = 1 };
    }
    out.res = res;
    const objs = try keep.dupe(ResEntry, s.objs);
    for (objs) |*r| r.rxc = try o.recordTwin(r.xc);
    out.objs = objs;
    const supply = try keep.dupe(SupplyEntry, s.supply);
    for (supply) |*e| e.rxc = try o.recordTwin(e.xc);
    out.supply = supply;
    const rsupply = try keep.dupe(SupplyEntry, s.rsupply);
    for (rsupply) |*e| e.rxc = try o.recordTwin(e.xc);
    out.rsupply = rsupply;
    out.rxreq = (try o.recordTwin(.{ .atoms = s.xreq })).atoms;
    return out;
}

fn normalizeRaw(o: *Ownership, s_in: Summary) Allocator.Error!Summary {
    // §31.4 item 6: a row core asserts states its record conditions as its
    // list ones, by where each element comes from: the twin of each `xc`.
    const s = if (s_in.asserted) try o.recordTwins(s_in) else s_in;
    const keep = o.keep.allocator();
    const uses = try keep.dupe(UseEntry, s.uses);
    std.mem.sort(UseEntry, uses, {}, struct {
        fn less(_: void, x: UseEntry, y: UseEntry) bool {
            if (x.param != y.param) return x.param < y.param;
            return x.path < y.path;
        }
    }.less);
    var nu: usize = 0;
    // The field sets of one path's record writes, joined once the path's
    // run ends: a model's N writes at one path are not N merges (#716).
    var sets: std.ArrayList([]const u32) = .empty;
    defer if (sets.capacity > 0) sets.deinit(o.in.gpa);
    for (uses) |u| {
        if (u.bits == 0) continue;
        if (nu > 0 and uses[nu - 1].param == u.param and uses[nu - 1].path == u.path) {
            // §31.7: the fields two record writes write, together; a use
            // without `bit_f` names none and leaves the other's.
            const was = uses[nu - 1].bits & bit_f != 0;
            const is = u.bits & bit_f != 0;
            if (was and is) {
                if (sets.items.len == 0) try sets.append(o.in.gpa, uses[nu - 1].fields);
                try sets.append(o.in.gpa, u.fields);
            } else if (is) uses[nu - 1].fields = u.fields;
            if (u.bits & bit_w != 0) {
                if (uses[nu - 1].bits & bit_w == 0 or u.extent == .deep) uses[nu - 1].extent = u.extent;
            }
            uses[nu - 1].bits |= u.bits;
            uses[nu - 1].grown = gJoin(uses[nu - 1].grown, u.grown);
            continue;
        }
        if (sets.items.len > 0) {
            uses[nu - 1].fields = try unionFieldSets(keep, sets.items);
            sets.clearRetainingCapacity();
        }
        uses[nu] = u;
        if (u.bits & bit_w == 0) uses[nu].extent = .deep;
        nu += 1;
    }
    if (sets.items.len > 0) uses[nu - 1].fields = try unionFieldSets(keep, sets.items);
    const res = try sortedRes(keep, s.res);
    const objs = try sortedRes(keep, s.objs);
    const supply = try sortedSupply(keep, s.supply);
    const rsupply = try sortedSupply(keep, s.rsupply);
    const funs = try keep.dupe(FunFacts, s.funs);
    std.mem.sort(FunFacts, funs, {}, struct {
        fn less(_: void, x: FunFacts, y: FunFacts) bool {
            return x.param < y.param;
        }
    }.less);
    var nf: usize = 0;
    for (funs) |f| {
        if (nf > 0 and funs[nf - 1].param == f.param) {
            const p = &funs[nf - 1];
            p.calls = @fromBackingInt(@max(@backingInt(p.calls), @backingInt(f.calls)));
            p.sends = (p.need or f.need) and (!p.need or p.sends) and (!f.need or f.sends);
            p.need = p.need or f.need;
            p.need_if = try unionGuards(keep, p.need_if, f.need_if);
            p.seen = p.seen and f.seen;
            if (p.send == none) p.send = f.send;
            continue;
        }
        funs[nf] = f;
        funs[nf].need_if = try unionGuards(keep, f.need_if, &.{});
        nf += 1;
    }
    for (funs[0..nf]) |*f| if (f.need) {
        f.need_if = &.{};
    };
    const out: Summary = .{
        .params = s.params,
        .cast_signature = s.cast_signature,
        .cast_grown = s.cast_grown,
        .uses = uses[0..nu],
        .res = res,
        .objs = objs,
        .supply = supply,
        .rsupply = rsupply,
        .funs = funs[0..nf],
        .limit = s.limit,
        .limit_at = s.limit_at,
        .asserted = s.asserted,
        .xreq = o.pruneAtoms(try keep.dupe(XAtom, s.xreq)),
        .rxreq = o.pruneAtoms(try keep.dupe(XAtom, s.rxreq)),
        .once = s.once,
        .words = s.words,
        .slots = s.slots,
        .klasses = s.klasses,
    };
    if (o.in.canonical) if (try o.canonicalOf(out)) |c| return o.normalizeRaw(c);
    return out;
}

/// §16.7, *The canonical form*: a fact written at `P r` and at `P s⟨T⟩r` for
/// every region step `s` of `T` at `P` is written once, as `P⟨T⟩r`. Null
/// when the summary has no such set. Innermost marker first; the caller
/// normalizes again, and asks again, until nothing changes.
fn canonicalOf(o: *Ownership, s: Summary) Allocator.Error!?Summary {
    // §16.7 (c): a summary whose paths cross a cast is abbreviated too. F2
    // kept such a summary expanded because, with the path cut, inserting a
    // marker before a cast prefix could cut a path the expanded facts kept;
    // with no cut the two name the same places.
    // A use's bits written for more places only add reads and writes, so the
    // regions a use counts are the type's as written. A result's and a
    // supply's entries carry guarantees — its conditions, an owned supply —
    // which a place the summary never stated must not get: they count every
    // region a fold may take.
    const uses = try o.canonicalList(UseEntry, s.uses, struct {
        const typed = true;
        fn key(e: UseEntry) [4]u32 {
            return .{ e.param, 0, 0, 0 };
        }
        fn path(e: UseEntry) u32 {
            return e.path;
        }
        fn setPath(e: *UseEntry, p: u32) void {
            e.path = p;
        }
        fn same(x: UseEntry, y: UseEntry) bool {
            return x.bits == y.bits and x.extent == y.extent and x.grown == y.grown;
        }
        fn subsumes(y: UseEntry, x: UseEntry) bool {
            return x.grown == y.grown and x.bits | y.bits == y.bits and (x.bits & bit_w == 0 or y.extent == .deep or x.extent == .storage);
        }
    });
    const res = try o.canonicalList(ResEntry, s.res, struct {
        const typed = false;
        fn key(_: ResEntry) [4]u32 {
            return .{ 0, 0, 0, 0 };
        }
        fn path(e: ResEntry) u32 {
            return e.path;
        }
        fn setPath(e: *ResEntry, p: u32) void {
            e.path = p;
        }
        fn same(x: ResEntry, y: ResEntry) bool {
            return x.prov.eql(y.prov) and x.approx == y.approx and x.xc.eql(y.xc) and x.sc.eql(y.sc) and x.grown == y.grown;
        }
        fn subsumes(y: ResEntry, x: ResEntry) bool {
            return same(y, x);
        }
    });
    // A result path's provenances, the places of a parameter it may hold:
    // one canonical place for the root and every region.
    const res_prov = try o.canonicalList(ResEntry, res orelse s.res, struct {
        const typed = false;
        fn key(e: ResEntry) [4]u32 {
            return .{ e.path, @backingInt(e.prov.kind), e.prov.a, e.prov.b };
        }
        fn path(e: ResEntry) u32 {
            return e.prov.path;
        }
        fn setPath(e: *ResEntry, p: u32) void {
            e.prov.path = p;
        }
        fn same(x: ResEntry, y: ResEntry) bool {
            return x.prov.taken == y.prov.taken and x.approx == y.approx and x.xc.eql(y.xc) and x.sc.eql(y.sc) and x.grown == y.grown;
        }
        fn subsumes(y: ResEntry, x: ResEntry) bool {
            return same(y, x);
        }
    });
    const supply = try o.canonicalList(SupplyEntry, s.supply, struct {
        const typed = false;
        fn key(e: SupplyEntry) [4]u32 {
            return .{ e.fun, e.k, 0, 0 };
        }
        fn path(e: SupplyEntry) u32 {
            return e.path;
        }
        fn setPath(e: *SupplyEntry, p: u32) void {
            e.path = p;
        }
        fn same(x: SupplyEntry, y: SupplyEntry) bool {
            return x.prov.eql(y.prov) and x.owned == y.owned and x.approx == y.approx and x.xc.eql(y.xc) and x.sc.eql(y.sc) and x.grown == y.grown;
        }
        fn subsumes(y: SupplyEntry, x: SupplyEntry) bool {
            return same(y, x);
        }
    });
    if (uses == null and res == null and res_prov == null and supply == null) return null;
    var out = s;
    if (uses) |u| out.uses = u;
    if (res_prov orelse res) |r| out.res = r;
    if (supply) |e| out.supply = e;
    return out;
}

/// `canonicalOf` for one of a summary's lists: the entries at one key and
/// path (`F.key`, `F.path`) are the fact there. Any order.
fn canonicalList(o: *Ownership, comptime E: type, items_in: []const E, comptime F: type) Allocator.Error!?[]const E {
    const gpa = o.in.gpa;
    // Only a path with a marker (or `⋆`) can be one of a canonical set.
    for (items_in) |e| {
        if (o.paths.any.items[F.path(e)] and ((try o.canonicalSplit(F.path(e))) != null or (try o.canonicalPlaces(F.path(e))) != null)) break;
    } else return null;
    const items = try gpa.dupe(E, items_in);
    defer gpa.free(items);
    std.mem.sort(E, items, {}, struct {
        fn less(_: void, x: E, y: E) bool {
            const kx = F.key(x);
            const ky = F.key(y);
            for (kx, ky) |a, b| if (a != b) return a < b;
            return F.path(x) < F.path(y);
        }
    }.less);
    const Group = struct { start: u32, end: u32 };
    var order: std.ArrayList(Group) = .empty;
    defer order.deinit(gpa);
    var i: usize = 0;
    while (i < items.len) {
        var j = i + 1;
        const k = F.key(items[i]);
        while (j < items.len and std.meta.eql(F.key(items[j]), k) and F.path(items[j]) == F.path(items[i])) j += 1;
        try order.append(gpa, .{ .start = @intCast(i), .end = @intCast(j) });
        i = j;
    }
    const Find = struct {
        /// The group at `key` and `path`, by binary search: `items` is
        /// sorted by both.
        fn find(its: []const E, ord: []const Group, k: [4]u32, path: u32) ?Group {
            var lo: usize = 0;
            var hi: usize = ord.len;
            while (lo < hi) {
                const mid = (lo + hi) / 2;
                const e = its[ord[mid].start];
                const km = F.key(e);
                const order_ = for (km, k) |a, b| {
                    if (a != b) break std.math.order(a, b);
                } else std.math.order(F.path(e), path);
                switch (order_) {
                    .eq => return ord[mid],
                    .lt => lo = mid + 1,
                    .gt => hi = mid,
                }
            }
            return null;
        }
    };
    // By an entry's index: the group that begins there is dropped.
    const dropped = try gpa.alloc(bool, items.len);
    defer gpa.free(dropped);
    @memset(dropped, false);
    var added: std.ArrayList(E) = .empty;
    defer added.deinit(gpa);
    var targets: std.ArrayList(u32) = .empty;
    defer targets.deinit(gpa);
    for (order.items) |grp| {
        if (dropped[grp.start]) continue;
        const k = F.key(items[grp.start]);
        const d = (try o.canonicalSplit(F.path(items[grp.start]))) orelse continue;
        targets.clearRetainingCapacity();
        try o.memberPaths(d, .at, F.typed, &targets);
        // `targets[0]` is the root's place, the others the regions'.
        var with_root = true;
        const all = for (targets.items, 0..) |t, ti| {
            const other = Find.find(items, order.items, k, t) orelse if (ti == 0) {
                with_root = false;
                continue;
            } else break false;
            const same = !dropped[other.start] and other.end - other.start == grp.end - grp.start and for (items[grp.start..grp.end], items[other.start..other.end]) |x, y| {
                if (!F.same(x, y)) break false;
            } else true;
            if (same) continue;
            if (ti == 0) {
                with_root = false;
                continue;
            }
            break false;
        } else true;
        if (!all) continue;
        // Every region and the root: `P⟨T⟩r`; every region but not the
        // root: `P⟨T⟩⁺r`, the `T`s strictly below.
        const members = if (with_root) targets.items else targets.items[1..];
        if (std.mem.indexOfScalar(u32, members, F.path(items[grp.start])) == null) continue;
        const canonical = try o.concat(try o.rawChild(d.at, .level, try o.markerId(d.ty, if (with_root) .at else .under)), d.rest);
        for (members) |t| dropped[Find.find(items, order.items, k, t).?.start] = true;
        for (items[grp.start..grp.end]) |x| {
            var y = x;
            F.setPath(&y, canonical);
            try added.append(gpa, y);
        }
    }
    // A fact a canonical one already states, at one of its places, is
    // that fact again: an earlier round's, joined with this one's.
    var removed = false;
    for (order.items) |grp| {
        if (dropped[grp.start]) continue;
        const k = F.key(items[grp.start]);
        const d = (try o.canonicalPlaces(F.path(items[grp.start]))) orelse continue;
        targets.clearRetainingCapacity();
        try o.memberPaths(d, d.kind, F.typed, &targets);
        for (targets.items) |t| {
            const other = Find.find(items, order.items, k, t) orelse continue;
            if (dropped[other.start]) continue;
            const within = for (items[other.start..other.end]) |x| {
                const found = for (items[grp.start..grp.end]) |y| {
                    if (F.subsumes(y, x)) break true;
                } else false;
                if (!found) break false;
            } else true;
            if (!within) continue;
            dropped[other.start] = true;
            removed = true;
        }
    }
    if (added.items.len == 0 and !removed) return null;
    var out: std.ArrayList(E) = .empty;
    const keep = o.keep.allocator();
    for (order.items) |grp| {
        if (dropped[grp.start]) continue;
        try out.appendSlice(keep, items[grp.start..grp.end]);
    }
    try out.appendSlice(keep, added.items);
    return out.items;
}

/// `levelOf` of field `k` of constructor `ct` of the type `ty`, typed.
fn typedLevel(o: *Ownership, m: u32, bir: *const Bir, ct: Bir.Ctor, k: usize, ty: u64) Allocator.Error!Level {
    const args = bir.extraSlice(.{ .start = ct.args_start, .end = ct.args_end }, Inst.Index);
    var seen: std.AutoHashMapUnmanaged(u64, void) = .empty;
    defer seen.deinit(o.in.gpa);
    return o.exprLevel(m, bir, args[k], ty, &seen, true);
}

const CanonicalSplit = struct { at: u32, ty: u64, rest: u32, kind: MarkerKind = .at };

/// The places `P⟨T⟩r` is written for: `P r`, and `P s⟨T⟩r` for each
/// region step `s`; `P⟨T⟩⁺r` (`kind` `under`) the regions' only.
fn memberPaths(o: *Ownership, d: CanonicalSplit, kind: MarkerKind, typed: bool, out: *std.ArrayList(u32)) Allocator.Error!void {
    const key: [5]u64 = .{ d.at, d.ty, d.rest, @backingInt(kind), @intFromBool(typed) };
    if (o.member_paths.get(key)) |m| return out.appendSlice(o.in.gpa, m);
    const start = out.items.len;
    if (kind == .at) try out.append(o.in.gpa, try o.concat(d.at, d.rest));
    for (try o.regionSteps(d.ty, typed)) |step| {
        const into = try o.child(d.at, .ctor, step);
        // §16.7 (#820): a region whose first step leads to a `T` along a
        // written path has its marker there, at the `T` (`anchorsOf`).
        const a = try o.anchorsOf(step);
        for (a.paths) |q| {
            var at = into;
            for (q) |s| at = try o.child(at, s.kind, s.arg);
            const marker = try o.child(at, .level, try o.markerId(d.ty, .at));
            try out.append(o.in.gpa, try o.concat(marker, d.rest));
        }
        if (a.paths.len != 0 and !a.other) continue;
        const marker = try o.child(into, .level, try o.markerId(d.ty, if (try o.levelOf(step) == .here) .at else .below));
        try out.append(o.in.gpa, try o.concat(marker, d.rest));
    }
    try o.member_paths.put(o.in.gpa, key, try o.keep.allocator().dupe(u32, out.items[start..]));
}

/// A canonical path `P⟨T⟩r` (§16.7): its marker stands at `P`, a `T` in
/// no region of `T`, and `r` begins with a constructor step of `T`.
fn canonicalPlaces(o: *Ownership, p: u32) Allocator.Error!?CanonicalSplit {
    return o.memoSplit(&o.places_of, p, canonicalPlacesRaw);
}

fn memoSplit(o: *Ownership, col: *std.ArrayList(u32), p: u32, comptime f: fn (*Ownership, u32) Allocator.Error!?CanonicalSplit) Allocator.Error!?CanonicalSplit {
    if (p >= col.items.len) try col.appendNTimes(o.in.gpa, 0, p + 1 - col.items.len);
    switch (col.items[p]) {
        0 => {},
        1 => return null,
        else => |i| return o.canon_splits.items[i - 2],
    }
    const d = try f(o, p);
    if (d) |x| {
        try o.canon_splits.append(o.in.gpa, x);
        col.items[p] = @intCast(o.canon_splits.items.len + 1);
    } else col.items[p] = 1;
    return d;
}

fn canonicalPlacesRaw(o: *Ownership, p: u32) Allocator.Error!?CanonicalSplit {
    const ns = o.pathNodes(p);
    var i = ns.len;
    while (i > 1) {
        i -= 1;
        const m = ns[i - 1];
        if (o.paths.kind.items[m] != .level) continue;
        const kind = o.markerKind(o.paths.arg.items[m]);
        if (kind != .at and kind != .under) continue;
        const ty = o.markerType(o.paths.arg.items[m]);
        const at = o.paths.parent.items[m];
        if (at != eps and o.paths.kind.items[at] == .ctor and o.ctorType(o.stepCtor(o.paths.arg.items[at])) == ty) continue;
        const first = ns[i];
        if (o.paths.kind.items[first] != .ctor or o.ctorType(o.stepCtor(o.paths.arg.items[first])) != ty) continue;
        if (try o.regionOf(at, ty) != null) continue;
        var rest: u32 = eps;
        for (ns[i..]) |n| rest = try o.child(rest, o.paths.kind.items[n], o.paths.arg.items[n]);
        return .{ .at = at, .ty = ty, .rest = rest, .kind = kind };
    }
    return null;
}

/// A path `P s⟨T⟩r` whose region is the innermost one that begins at a
/// position in no region of `T`: `P`, `T` and `r` (as a path of its own).
fn canonicalSplit(o: *Ownership, p: u32) Allocator.Error!?CanonicalSplit {
    return o.memoSplit(&o.split_of, p, canonicalSplitRaw);
}

fn canonicalSplitRaw(o: *Ownership, p: u32) Allocator.Error!?CanonicalSplit {
    const ns = o.pathNodes(p);
    var i = ns.len;
    while (i > 2) {
        i -= 1;
        const m = ns[i - 1];
        if (o.paths.kind.items[m] != .level) continue;
        const ty = o.markerType(o.paths.arg.items[m]);
        // The region's first step: right before the marker, or before an
        // anchor of it, a path of fields, tuple slots and elements (§16.7, #820).
        var si = i - 2;
        while (si > 0 and (o.paths.kind.items[ns[si]] == .field or o.paths.kind.items[ns[si]] == .tuple or o.paths.kind.items[ns[si]] == .elem)) si -= 1;
        const s = ns[si];
        if (o.paths.kind.items[s] != .ctor) continue;
        if (o.ctorType(o.stepCtor(o.paths.arg.items[s])) != ty) continue;
        if (si != i - 2 and !try o.anchoredAt(s, o.paths.parent.items[m])) continue;
        const first = ns[i];
        if (o.paths.kind.items[first] != .ctor or o.ctorType(o.stepCtor(o.paths.arg.items[first])) != ty) continue;
        const at = o.paths.parent.items[s];
        if (try o.regionOf(at, ty) != null) continue;
        var rest: u32 = eps;
        for (ns[i..]) |n| rest = try o.child(rest, o.paths.kind.items[n], o.paths.arg.items[n]);
        return .{ .at = at, .ty = ty, .rest = rest };
    }
    return null;
}

/// The region steps of a recursive type: every constructor field that can
/// hold a value of the type, as a constructor step.
/// `typed`: counted from the type as written (`typedLevel`); else every
/// field `levelOf` takes for one, a closure's and a `foreign type`'s too.
fn regionSteps(o: *Ownership, ty: u64, typed: bool) Allocator.Error![]const u32 {
    const key: [2]u64 = .{ ty, @intFromBool(typed) };
    if (o.region_steps.get(key)) |r| return r;
    var out: std.ArrayList(u32) = .empty;
    // §16.7 (#820): a schema endpoint's constructors take their payload as
    // field 0, read off the plan.
    if (o.schemaKeyOf(ty)) |sk| {
        const bases = try o.schemaCtorBases(sk.m);
        const count = (bases[sk.decl + 1] - bases[sk.decl]) / 2;
        for (0..count) |v| {
            const index = (try o.schemaCtorIndex(sk.m, sk.decl, sk.encoded, @intCast(v))) orelse continue;
            const step = try o.ctorStep(try o.ctorId(sk.m, index), 0);
            const level = if (typed) try o.schemaCtorLevel(sk.m, index, 0, ty, true) else try o.levelOf(step);
            if (level != .none) try out.append(o.keep.allocator(), step);
        }
        try o.region_steps.put(o.in.gpa, key, out.items);
        return out.items;
    }
    const m: u32 = @intCast(ty >> 32);
    const d: u32 = @truncate(ty);
    const bir = o.in.birs[m];
    const decl = bir.decls[d];
    for (bir.declCtors(decl), decl.ctors_start..) |ct, ci| {
        const n = bir.extraSlice(.{ .start = ct.args_start, .end = ct.args_end }, Inst.Index).len;
        for (0..n) |k| {
            const step = try o.ctorStep(try o.ctorId(m, @intCast(ci)), @intCast(k));
            const level = if (typed) try o.typedLevel(m, bir, ct, k, ty) else try o.levelOf(step);
            if (level != .none) try out.append(o.keep.allocator(), step);
        }
    }
    try o.region_steps.put(o.in.gpa, key, out.items);
    return out.items;
}

/// The pessimistic summary of §16.2: every parameter written, kept and
/// returned whole, the result unknown, every callback out of sight. Only a
/// limit makes one (§16.7), and the limit is reported at the declaration
/// whose walk reached it.
fn pessimistic(o: *Ownership, s: Summary, why: Limit, at: u32) Allocator.Error!Summary {
    try o.hitLimit(why, at);
    const keep = o.keep.allocator();
    const uses = try keep.alloc(UseEntry, s.params);
    // §31.7: and every record of every parameter written, every field of it
    // (`bit_f`, the empty field set); a call applies it where the argument
    // is a record.
    for (uses, 0..) |*u, i| u.* = .{ .param = @intCast(i), .path = eps, .bits = bit_r | bit_a | bit_e | bit_w | bit_f };
    const res = try keep.dupe(ResEntry, &.{.{ .path = eps, .prov = .{ .kind = .top, .a = 0 }, .approx = true, .xc = .{ .no = 1 } }});
    const funs = try keep.alloc(FunFacts, s.funs.len);
    for (funs, s.funs) |*f, g| f.* = .{ .param = g.param, .calls = .many, .need = true, .rneed = true, .seen = false };
    return .{ .params = s.params, .uses = uses, .res = res, .funs = funs, .limit = why, .limit_at = at, .asserted = s.asserted, .once = s.once };
}

/// A limit reached (§16.7): one per declaration and limit, the largest
/// measure kept, for the error at the declaration.
pub const LimitHit = struct { module: u32, decl: u32, limit: Limit, at: u32 };

/// Records that the walk under way reached `why`, measuring `at`.
fn hitLimit(o: *Ownership, why: Limit, at: u32) Allocator.Error!void {
    const m = o.cur_decl[0];
    const d = o.cur_decl[1];
    // Every walk sets `cur_decl` (`run`, `walkSummary`), so a
    // limit is always some declaration's error, never dropped (#271).
    if (std.debug.runtime_safety) std.debug.assert(m != none);
    if (m == none) return;
    for (o.limit_hits.items) |*h| if (h.module == m and h.decl == d and h.limit == why) {
        h.at = @max(h.at, at);
        return;
    };
    try o.limit_hits.append(o.in.gpa, .{ .module = m, .decl = d, .limit = why, .at = at });
}

// ---------------------------------------------------------------------------
// The asserted rows (§16.8)
// ---------------------------------------------------------------------------

fn assertedRow(o: *Ownership, m: u32, d: u32) Allocator.Error!?Summary {
    if (o.in.packages[m] == .core and std.mem.eql(u8, o.in.module_names[m], "Schema")) return o.schemaRunRow(m, d);
    if (o.in.packages[m] == .core and std.mem.eql(u8, o.in.module_names[m], "Record")) return o.recordRow(m, d);
    if (o.in.packages[m] != .core or !std.mem.eql(u8, o.in.module_names[m], "List")) return null;
    const bir = o.in.birs[m];
    const name = o.in.interner.slice(bir.symbol(bir.decls[d].name));
    const R = bit_r;
    const A = bit_a;
    const W = bit_w | bit_x;
    const elem = try o.child(eps, .elem, 0);
    const p = struct {
        fn at(i: u32, path: u32) Prov {
            return .{ .kind = .param, .a = i, .path = path };
        }
    }.at;
    const fresh: Prov = .{ .kind = .fresh, .a = 1 };
    const keep = o.keep.allocator();
    const lost: XSum = .{ .no = 1 };
    var uses: []const UseEntry = &.{};
    var res: []const ResEntry = &.{};
    var supply: []const SupplyEntry = &.{};
    var funs: []const FunFacts = &.{};
    if (eqlAny(name, &.{ "set", "insertAt", "put" })) {
        // A writer whose base is π₁ and which stores π₃ (§18.3: the base
        // stays exclusive when π₃ is and shares nothing with its elements).
        uses = &.{ .{ .param = 0, .path = eps, .extent = .storage, .bits = R | A | W }, .{ .param = 2, .path = eps, .bits = A } };
        res = try keep.dupe(ResEntry, &.{ .{ .path = eps, .prov = p(0, eps), .xc = try o.stores(0, 2, elem) }, .{ .path = elem, .prov = p(0, elem) }, .{ .path = elem, .prov = p(2, eps) } });
    } else if (std.mem.eql(u8, name, "push")) {
        uses = &.{ .{ .param = 0, .path = eps, .extent = .storage, .bits = R | A | W }, .{ .param = 1, .path = eps, .bits = A } };
        res = try keep.dupe(ResEntry, &.{ .{ .path = eps, .prov = p(0, eps), .xc = try o.stores(0, 1, elem) }, .{ .path = elem, .prov = p(0, elem) }, .{ .path = elem, .prov = p(1, eps) } });
    } else if (eqlAny(name, &.{ "pop", "removeAt", "swap", "done" })) {
        // A writer that stores nothing new: it drops an element, or permutes
        // two (`swap`, §22.5), so the list stays exclusive when it was
        // (thesis §3.11's row: `excl if π₁ excl`).
        uses = &.{.{ .param = 0, .path = eps, .extent = .storage, .bits = R | A | W }};
        res = try keep.dupe(ResEntry, &.{ .{ .path = eps, .prov = p(0, eps) }, .{ .path = elem, .prov = p(0, elem) } });
    } else if (std.mem.eql(u8, name, "cons")) {
        // §3.1 as amended for slice 3f: a prepend copies, so it reads its
        // base and writes nothing. Its result is a new array, or — the
        // runtime's re-cons — a header over the base's own array, so it
        // aliases π₂ as well (thesis §3.8: "a prepend into a view returns a
        // new header over the same array").
        uses = &.{ .{ .param = 0, .path = eps, .bits = A }, .{ .param = 1, .path = eps, .bits = R | A }, .{ .param = 1, .path = elem, .bits = A } };
        const made = try keep.alloc(XAtom, 3);
        made[0] = .{ .kind = .excl, .a = p(0, eps) };
        made[1] = .{ .kind = .excl, .a = p(1, eps) };
        made[2] = sepAtom(p(0, eps), p(1, elem));
        res = try keep.dupe(ResEntry, &.{ .{ .path = eps, .prov = fresh, .xc = .{ .atoms = sortAtoms(made) } }, .{ .path = eps, .prov = p(1, eps) }, .{ .path = elem, .prov = p(1, elem) }, .{ .path = elem, .prov = p(0, eps) } });
    } else if (std.mem.eql(u8, name, "append")) {
        // Copying in the elements of a list that lives on (thesis §3.8).
        uses = &.{ .{ .param = 0, .path = eps, .extent = .storage, .bits = R | A | W }, .{ .param = 1, .path = eps, .bits = R }, .{ .param = 1, .path = elem, .bits = A } };
        // Its records (#420, §31.4 item 6): the answer's positions are
        // π₁'s and then π₂'s, so it holds no record twice when neither
        // argument does and the two share none. That π₂ lives on is a
        // holder of its elements, which a record demand's Dead reads.
        const rmade = try keep.alloc(XAtom, 3);
        rmade[0] = .{ .kind = .excl, .a = p(0, eps) };
        rmade[1] = .{ .kind = .excl, .a = p(1, eps) };
        rmade[2] = sepAtom(p(0, eps), p(1, eps));
        res = try keep.dupe(ResEntry, &.{ .{ .path = eps, .prov = p(0, eps), .xc = lost, .rxc = .{ .atoms = sortAtoms(rmade) } }, .{ .path = elem, .prov = p(0, elem) }, .{ .path = elem, .prov = p(1, elem) } });
    } else if (eqlAny(name, &.{ "copy", "sliceOf" })) {
        uses = &.{ .{ .param = 0, .path = eps, .bits = R }, .{ .param = 0, .path = elem, .bits = A } };
        // Its records (#420): each position is one of π₁'s, at most once.
        const rwhole = try keep.dupe(XAtom, &.{.{ .kind = .excl, .a = p(0, eps) }});
        res = try keep.dupe(ResEntry, &.{ .{ .path = eps, .prov = fresh, .xc = lost, .rxc = .{ .atoms = rwhole } }, .{ .path = elem, .prov = p(0, elem) } });
    } else if (eqlAny(name, &.{ "length", "offset" })) {
        uses = &.{.{ .param = 0, .path = eps, .bits = R }};
    } else if (eqlAny(name, &.{ "at", "unsafeGet" })) {
        uses = &.{ .{ .param = 0, .path = eps, .bits = R }, .{ .param = 0, .path = elem, .bits = A } };
        res = try keep.dupe(ResEntry, &.{.{ .path = eps, .prov = p(0, elem) }});
    } else if (std.mem.eql(u8, name, "traverseAt")) {
        // §18.5, the traversal primitive: the element, taken out.
        uses = &.{ .{ .param = 0, .path = eps, .bits = R }, .{ .param = 0, .path = elem, .bits = A } };
        res = try keep.dupe(ResEntry, &.{.{ .path = eps, .prov = .{ .kind = .param, .a = 0, .path = elem, .taken = true } }});
    } else if (std.mem.eql(u8, name, "focus")) {
        // §18.5, the focus primitive: the element taken out, handed to the
        // callback owned when the list is exclusive, and its result put
        // back; the list stays exclusive when the callback keeps shape.
        uses = &.{ .{ .param = 0, .path = eps, .extent = .storage, .bits = R | A | W }, .{ .param = 0, .path = elem, .bits = A } };
        const kept_shape = try keep.dupe(XAtom, &.{.{ .kind = .keep, .a = .{ .kind = .cb, .a = 2 }, .b = p(0, eps) }});
        res = try keep.dupe(ResEntry, &.{
            .{ .path = eps, .prov = p(0, eps), .xc = .{ .atoms = kept_shape }, .sc = .{ .atoms = try keep.dupe(XAtom, &.{.{ .kind = .spine, .a = p(0, eps) }}) } },
            .{ .path = elem, .prov = p(0, elem) },
            .{ .path = elem, .prov = .{ .kind = .cb, .a = 2 } },
        });
        const whole = try keep.dupe(XAtom, &.{.{ .kind = .excl, .a = p(0, eps) }});
        supply = try keep.dupe(SupplyEntry, &.{.{ .fun = 2, .k = 0, .path = eps, .prov = .{ .kind = .param, .a = 0, .path = elem, .taken = true }, .owned = true, .xc = .{ .atoms = whole } }});
        funs = try keep.dupe(FunFacts, &.{.{ .param = 2, .calls = .once }});
    } else if (std.mem.eql(u8, name, "view")) {
        // A view is its base's array: it is exclusive when the base is.
        uses = &.{.{ .param = 0, .path = eps, .bits = R | A }};
        const whole = try keep.dupe(XAtom, &.{.{ .kind = .excl, .a = p(0, eps) }});
        res = try keep.dupe(ResEntry, &.{ .{ .path = eps, .prov = p(0, eps) }, .{ .path = eps, .prov = fresh, .xc = .{ .atoms = whole } }, .{ .path = elem, .prov = p(0, elem) } });
    } else if (std.mem.eql(u8, name, "base")) {
        uses = &.{.{ .param = 0, .path = eps, .bits = R | A }};
        res = try keep.dupe(ResEntry, &.{ .{ .path = eps, .prov = p(0, eps) }, .{ .path = elem, .prov = p(0, elem) } });
    } else if (std.mem.eql(u8, name, "builder")) {
        res = try keep.dupe(ResEntry, &.{.{ .path = eps, .prov = fresh }});
    } else return null;
    return try o.normalize(.{
        .params = o.in.birs[m].decls[d].params,
        .uses = try keep.dupe(UseEntry, uses),
        .res = res,
        .supply = supply,
        .funs = funs,
        .asserted = true,
    });
}

/// `core/Record`'s row (§31.15): `copy r` reads `r` and aliases its
/// fields into the copy — π₁ `RA`, and every field the result has is π₁'s
/// at that field. It writes nothing and is not a demand.
fn recordRow(o: *Ownership, m: u32, d: u32) Allocator.Error!?Summary {
    const bir = o.in.birs[m];
    const name = o.in.interner.slice(bir.symbol(bir.decls[d].name));
    if (!std.mem.eql(u8, name, "copy")) return null;
    const keep = o.keep.allocator();
    // A record has no cell of its own yet (§26.8 question 2): what the
    // copy holds is what π₁ holds, at the same paths.
    const res = try keep.dupe(ResEntry, &.{.{ .path = eps, .prov = .{ .kind = .param, .a = 0, .path = eps } }});
    return try o.normalize(.{
        .params = bir.decls[d].params,
        .uses = try keep.dupe(UseEntry, &.{.{ .param = 0, .path = eps, .bits = bit_r | bit_a }}),
        .res = res,
        .asserted = true,
    });
}

/// `res ⋆ p` and `res ⋆ p⋆`, approximate: the answer may hold, anywhere,
/// what `p` is and any part of it — a list inside a record the slot holds,
/// which a list's demand would not take the record's own cell for.
fn anywhereIn(o: *Ownership, res: *std.ArrayList(ResEntry), p: Prov) Allocator.Error!void {
    const keep = o.keep.allocator();
    const any = try o.child(eps, .any, 0);
    try res.append(keep, .{ .path = any, .prov = p, .approx = true });
    var below = p;
    below.path = try o.child(p.path, .any, 0);
    if (below.path != p.path) try res.append(keep, .{ .path = any, .prov = below, .approx = true });
}

/// The path of a run's answer where its row sets its input aside: what the
/// answer holds of it only when the schema's slot holds `input_marker`
/// (`settleRun`).
fn inputPath(o: *Ownership) Allocator.Error!u32 {
    return o.child(eps, .schema_encoded, 0);
}

/// `res` at `inputPath` the input, `π_input` and any part of it.
fn inputAside(o: *Ownership, res: *std.ArrayList(ResEntry), input: u32) Allocator.Error!void {
    const keep = o.keep.allocator();
    const at = try o.inputPath();
    try res.append(keep, .{ .path = at, .prov = .{ .kind = .param, .a = input, .path = eps }, .approx = true });
    try res.append(keep, .{ .path = at, .prov = .{ .kind = .param, .a = input, .path = try o.child(eps, .any, 0) }, .approx = true });
}

/// §30.10: a run of a schema answers what it builds from its input, and
/// what its schema's slot of that direction holds — `⟨decoded⟩` for
/// `parse`, `decode` and `read`, `⟨encoded⟩` for `encode` and `write` —
/// and, where its input is a program's value (`decode`, `read`, `encode`,
/// `write`), the input set aside for `settleRun`. Null for every other
/// declaration of `core/Schema`.
fn schemaRunRow(o: *Ownership, m: u32, d: u32) Allocator.Error!?Summary {
    const bir = o.in.birs[m];
    const decl = bir.decls[d];
    const name = o.in.interner.slice(bir.symbol(decl.name));
    const decoding = eqlAny(name, &.{ "parse", "parseWith", "decode", "decodeWith", "read", "readWith" });
    const encoding = eqlAny(name, &.{ "encode", "encodeWith", "write", "writeWith" });
    if (!decoding and !encoding) return null;
    const n = decl.params;
    if (n < 2) return null;
    const keep = o.keep.allocator();
    const R = bit_r;
    const A = bit_a;
    const slot = try o.child(eps, if (decoding) .schema_decoded else .schema_encoded, 0);
    const input: u32 = n - 1;
    // `parse` reads a string; every other run is handed a program's value,
    // and a `Value` position of the schema answers the part of it there.
    const aliases_input = !std.mem.startsWith(u8, name, "parse");
    var uses: std.ArrayList(UseEntry) = .empty;
    try uses.append(keep, .{ .param = 0, .path = eps, .bits = R });
    try uses.append(keep, .{ .param = 0, .path = slot, .bits = R | A });
    for (1..input) |i| try uses.append(keep, .{ .param = @intCast(i), .path = eps, .bits = R });
    try uses.append(keep, .{ .param = input, .path = eps, .bits = if (aliases_input) R | A else R });
    var res: std.ArrayList(ResEntry) = .empty;
    try res.append(keep, .{ .path = eps, .prov = .{ .kind = .fresh, .a = 1 }, .xc = .{ .no = 1 } });
    try o.anywhereIn(&res, .{ .kind = .param, .a = 0, .path = slot });
    if (aliases_input) try o.inputAside(&res, input);
    return try o.normalize(.{
        .params = n,
        .uses = uses.items,
        .res = res.items,
        .asserted = true,
    });
}

/// §30.10: what `core/Schema`'s makers put in the slots of the schema they
/// return, added to the summary read off the body. `box` makes every
/// schema an interpreting builder answers, whose functions the checker
/// does not follow: both its slots hold `⊤`. `list`, `nullable` and
/// `erased` answer what their schema answers, and `converted` that and what
/// its conversion's functions answer (the conversion's slots, which a call
/// of `conversion` fills, `conversionSlots`).
fn schemaMakerRow(o: *Ownership, m: u32, d: u32, s: Summary) Allocator.Error!Summary {
    if (o.in.packages[m] != .core or !std.mem.eql(u8, o.in.module_names[m], "Schema")) return s;
    const bir = o.in.birs[m];
    const name = o.in.interner.slice(bir.symbol(bir.decls[d].name));
    const keep = o.keep.allocator();
    const slots = [_]u32{ try o.child(eps, .schema_decoded, 0), try o.child(eps, .schema_encoded, 0) };
    var extra: std.ArrayList(ResEntry) = .empty;
    // `list`, `nullable`, `erased` and `converted`: their slots are their
    // arguments' alone (below).
    var arguments_only = false;
    // `derived` and `structural` answer what their evidence answers, which
    // only a call knows (`codecRunRow`): from the body, anything.
    if (eqlAny(name, &.{ "box", "derived", "structural" })) {
        for (slots) |p| try extra.append(keep, .{ .path = p, .prov = .{ .kind = .top, .a = unfollowed } });
    } else if (std.mem.eql(u8, name, "value") and bir.decls[d].params == 0) {
        // A `Value` is answered as it was handed: the run's input.
        for (slots) |p| try extra.append(keep, .{ .path = p, .prov = input_marker });
    } else if (eqlAny(name, &.{ "list", "nullable", "erased", "converted" })) {
        const n: u32 = if (std.mem.eql(u8, name, "converted")) 2 else 1;
        arguments_only = true;
        if (bir.decls[d].params != n) return s;
        for (0..n) |i| for (slots) |p| {
            try extra.append(keep, .{ .path = p, .prov = .{ .kind = .param, .a = @intCast(i), .path = p } });
        };
    } else return s;
    var out = s;
    var res: std.ArrayList(ResEntry) = .empty;
    for (s.res) |r| {
        // `list`, `nullable`, `erased` and `converted` branch on their
        // argument's engine: the interpreting arm, whose `box` answers `⊤`,
        // runs only for a schema whose slots hold `⊤` already. Their slots
        // are their arguments', and nothing else.
        if (arguments_only) if (o.firstStep(r.path)) |st| {
            if (st.kind == .schema_decoded or st.kind == .schema_encoded) continue;
        };
        try res.append(keep, r);
    }
    try res.appendSlice(keep, extra.items);
    out.res = res.items;
    var uses: std.ArrayList(UseEntry) = .empty;
    try uses.appendSlice(keep, s.uses);
    for (extra.items) |e| if (e.prov.kind == .param) {
        try uses.append(keep, .{ .param = e.prov.a, .path = e.prov.path, .bits = bit_r | bit_a });
    };
    out.uses = uses.items;
    return o.normalize(out);
}

/// §30.10: what a `schema` declaration's own runs may answer beyond what
/// they build from their input, per direction, in a summary's vocabulary —
/// what its conversions' functions return that they did not build, through
/// every declaration and derived codec it names. Its schema parameters are
/// not here: they are the arguments a call of a member passes.
pub const SchemaTaint = struct {
    decoded: []const Prov = &.{},
    encoded: []const Prov = &.{},
};

/// §30.10: the mark a slot holds where a run answers part of what it was
/// handed — a `Value`, or what a conversion's `backward` returns of its
/// argument. A run of the schema puts its input there (`settleRun`);
/// anywhere else it is a `⊤`, as unknown as any.
const input_marker: Prov = .{ .kind = .top, .a = 2 };

/// §30.10: a `⊤` a schema's slot holds where the checker does not follow
/// what answered it — an interpreting builder's functions, a conversion
/// expression a declaration evaluates once, a function it cannot place.
/// Printed `⊤schema`; a cause like any `⊤`, named for what it is.
const unfollowed: u32 = 3;

/// §30.10, amended 2026-10-16 (#268): a `⊤` a schema's decoding slot holds
/// where a conversion's `forward` returns one cell at two places of its
/// result — a part of what it was handed, or a list it makes — so two
/// positions of a run's answer may be one list. Printed `⊤twice`. Not 4,
/// which `⊤call` (§30.11) takes.
const twice_named: u32 = 5;

comptime {
    // Each `top.a` names one flavour of ⊤ (`provText`, `bad_cause`): 0 is
    // JavaScript, 1 a limit, 2 an input.
    const flavours = [_]u32{ 0, 1, 2, unfollowed, top_call, twice_named, top_several };
    for (flavours, 0..) |x, i| for (flavours[i + 1 ..]) |y| if (x == y) @compileError("two flavours of ⊤ share a number");
}

/// Whether summary `s` returns one cell at two places of its result that
/// are not one placement of it: a part of its parameter 0, of type `arg`
/// (`( xs, xs )`, `{ all = xs, first = xs }`, `( xs, [ xs ] )`), or a list
/// it makes, whose fresh number names both places (`dup [ 1 ]`, `dup
/// (List.copy xs)`). `π1` at `.0` and `π1[*]` at `.0[*]` are one placement.
/// A part that holds no cell does not count: of the parameter, the `Int`s
/// of a `List Int` at `.0[*]` and in a reversed copy; of a list it makes,
/// the elements a recursive builder numbers as the list (`range n`), read
/// in the decoded type `target` below the result's `Ok`. A `⋆` that blurs
/// the alignment counts as two places.
fn returnsOneCellTwice(o: *Ownership, store: *TypeStore, s: *const Summary, arg: ?Var, target: ?Var) Allocator.Error!bool {
    for (s.res, 0..) |x, i| {
        const fresh = x.prov.kind == .fresh;
        if (!fresh and (x.prov.kind != .param or x.prov.a != 0)) continue;
        for (s.res[i + 1 ..]) |y| {
            if (y.prov.kind != x.prov.kind or y.prov.a != x.prov.a) continue;
            if (!o.overlap(x.prov.path, y.prov.path)) continue;
            const short, const long = if (o.paths.depth.items[x.prov.path] <= o.paths.depth.items[y.prov.path]) .{ x, y } else .{ y, x };
            if (!fresh) if (arg) |v| if (!try o.partTracked(store, v, long.prov.path)) continue;
            if (fresh) if (target) |v| if (o.isOkStep(o.firstStep(long.path))) {
                if (!try o.partTracked(store, v, try o.dropFirst(long.path))) continue;
            };
            const d = (try o.suffix(short.prov.path, long.prov.path)) orelse return true;
            if (try o.concat(short.path, d) != long.path) return true;
        }
    }
    return false;
}

/// Whether `step` is core `Result`'s `Ok` and its value: the step from a
/// conversion function's result to the value it converted.
fn isOkStep(o: *const Ownership, step: ?Step) bool {
    const st = step orelse return false;
    if (st.kind != .ctor or o.stepField(st.arg) != 0) return false;
    const c = o.stepCtor(st.arg);
    if (c >= o.ctor_key.items.len) return false;
    const key = o.ctor_key.items[c];
    const m: u32 = @intCast(key >> 32);
    if (m >= o.in.packages.len or o.in.packages[m] != .core or !std.mem.eql(u8, o.in.module_names[m], "Result")) return false;
    return std.mem.eql(u8, o.ctorName(m, @truncate(key)), "Ok");
}

/// Whether the part at `path` of a value of type `v` may hold a cell,
/// through the steps of lists, records and tuples; true where the type does
/// not say (a constructor's step, a `⋆`, a type variable).
fn partTracked(o: *Ownership, store: *TypeStore, v: Var, path: u32) Allocator.Error!bool {
    var t = v;
    for (o.steps(path)) |st| {
        const next: ?Var = switch (store.resolvedContent(t)) {
            .structure => |sc| switch (sc) {
                .app => |a| if (st.kind == .elem and a.type == o.in.types.well_known.list and store.vars(a.args).len == 1) store.vars(a.args)[0] else null,
                .record => |r| if (st.kind == .field) for (store.fields(r.fields)) |f| {
                    if (@backingInt(f.name) == st.arg) break f.value;
                } else null else null,
                .tuple => |r| if (st.kind == .tuple and st.arg < store.vars(r).len) store.vars(r)[st.arg] else null,
                else => null,
            },
            else => null,
        };
        t = next orelse return true;
    }
    return o.tracked(store, t, 0);
}

/// §30.10: `core/Schema`'s runs, whose rows are `schemaRunRow`'s.
const schema_runs = [_][]const u8{ "parse", "parseWith", "decode", "decodeWith", "read", "readWith", "encode", "encodeWith", "write", "writeWith" };

const top_taint: SchemaTaint = .{
    .decoded = &.{.{ .kind = .top, .a = unfollowed }},
    .encoded = &.{.{ .kind = .top, .a = unfollowed }},
};

fn schemaGraph(o: *const Ownership) SchemaGraph {
    return .{
        .graph = o.in.graph,
        .plans = o.in.types.plans,
        .birs = o.in.birs,
        .interfaces = o.in.interfaces,
        .provenance = o.in.provenance,
        .interner = o.in.interner,
    };
}

/// The derivation (§30.10): a closure over the plan. Each declaration or
/// derived codec reached contributes its `via`s, each a conversion value
/// (`viaTaint`), and its `codec_value` nodes, each a module's `codec`
/// (`codecValueTaint`). A plan the run does not have answers `⊤`, as does a
/// declaration met again while it is being derived (a `via` whose value
/// runs this very schema).
fn schemaSummary(o: *Ownership, m: u32, d: u32) Allocator.Error!*const Summary {
    const t = try o.schemaTaint(m, d);
    const a = o.keep.allocator();
    var res: std.ArrayList(ResEntry) = .empty;
    for (t.decoded) |p| try res.append(a, .{ .path = try o.child(eps, .schema_decoded, 0), .prov = p });
    for (t.encoded) |p| try res.append(a, .{ .path = try o.child(eps, .schema_encoded, 0), .prov = p });
    const s = try a.create(Summary);
    s.* = try o.normalize(.{ .params = 0, .res = res.items });
    return s;
}

fn schemaTaint(o: *Ownership, m: u32, decl: u32) Allocator.Error!SchemaTaint {
    if (o.in.single_module != null and !o.isChecked(m)) {
        const s = (try o.blockSummary(m, decl)) orelse return top_taint;
        var decoded: std.ArrayList(Prov) = .empty;
        var encoded: std.ArrayList(Prov) = .empty;
        const dp = try o.child(eps, .schema_decoded, 0);
        const ep = try o.child(eps, .schema_encoded, 0);
        for (s.res) |r| {
            if (r.path == dp) try decoded.append(o.keep.allocator(), r.prov);
            if (r.path == ep) try encoded.append(o.keep.allocator(), r.prov);
        }
        return .{ .decoded = decoded.items, .encoded = encoded.items };
    }
    const key = (@as(u64, m) << 32) | decl;
    if (o.schema_taints.get(key)) |t| return t orelse top_taint;
    try o.schema_taints.put(o.in.gpa, key, null);
    const t = try o.deriveTaint(m, decl);
    try o.schema_taints.put(o.in.gpa, key, t);
    return t;
}

fn deriveTaint(o: *Ownership, m0: u32, decl0: u32) Allocator.Error!SchemaTaint {
    const sg = o.schemaGraph();
    const keep = o.keep.allocator();
    var decoded: std.ArrayList(Prov) = .empty;
    var encoded: std.ArrayList(Prov) = .empty;
    var todo: std.ArrayList(SchemaGraph.Ref) = .empty;
    defer todo.deinit(o.in.gpa);
    var seen: std.AutoHashMapUnmanaged([2]u32, void) = .empty;
    defer seen.deinit(o.in.gpa);
    var nodes: std.ArrayList(SchemaPlan.NodeIndex) = .empty;
    defer nodes.deinit(o.in.gpa);
    try todo.append(o.in.gpa, .{ .module = @fromBackingInt(m0), .decl = decl0 });
    while (todo.pop()) |r| {
        if ((try seen.getOrPut(o.in.gpa, .{ r.module.int(), r.decl })).found_existing) continue;
        {
            const m = r.module.int();
            if (o.in.single_module != null and !o.isChecked(m)) {
                const t = try o.schemaTaint(m, r.decl);
                try decoded.appendSlice(keep, t.decoded);
                try encoded.appendSlice(keep, t.encoded);
                continue;
            }
            const def = sg.definition(r.module, r.decl) orelse return top_taint;
            const plan = sg.planOf(r.module);
            nodes.clearRetainingCapacity();
            try SchemaGraph.subtree(plan, o.in.gpa, def.root, &nodes);
            for (nodes.items) |n| switch (SchemaGraph.tag(plan, n)) {
                .conversion => {
                    const index = SchemaGraph.rhs(plan, n);
                    if (index >= plan.conversions.len) return top_taint;
                    const t = try o.viaTaint(m, plan.conversions[index].expr);
                    try decoded.appendSlice(keep, t.decoded);
                    try encoded.appendSlice(keep, t.encoded);
                },
                .reference => {
                    const target = sg.target(r.module, @fromBackingInt(SchemaGraph.lhs(plan, n))) orelse return top_taint;
                    try todo.append(o.in.gpa, target);
                },
                .codec_ref => try todo.append(o.in.gpa, sg.codecTarget(r.module, SchemaGraph.lhs(plan, n))),
                .codec_value => {
                    const t = try o.codecValueTaint(plan, SchemaGraph.lhs(plan, n));
                    try decoded.appendSlice(keep, t.decoded);
                    try encoded.appendSlice(keep, t.encoded);
                },
                // A `Value` is answered as it was handed: the run's input.
                .primitive => if (SchemaGraph.lhs(plan, n) == @backingInt(SchemaPlan.Primitive.value)) {
                    try decoded.append(keep, input_marker);
                    try encoded.append(keep, input_marker);
                },
                else => {},
            };
        }
    }
    return .{ .decoded = decoded.items, .encoded = encoded.items };
}

/// A `via`'s conversion value, `expr` an instruction of a schema
/// declaration of `m`: nothing in a direction whose end — the target `a`
/// decoding, the source `b` encoding — holds no list; else, for a
/// top-level value, the slots its summary names, and `⊤` for any other
/// expression, which the declaration evaluates once, where no walk sees it.
fn viaTaint(o: *Ownership, m: u32, expr: Inst.Index) Allocator.Error!SchemaTaint {
    var ends: [2]bool = .{ true, true };
    if (m < o.in.modules.len) {
        const km = &o.in.modules[m];
        if (expr.int() < km.inst_type.len) if (km.inst_type[expr.int()].unwrap()) |v| switch (km.store.resolvedContent(v)) {
            .structure => |st| switch (st) {
                .app => |app| {
                    const xs = km.store.vars(app.args);
                    if (xs.len == 2) ends = .{ try o.tracked(&km.store, xs[1], 0), try o.tracked(&km.store, xs[0], 0) };
                },
                else => {},
            },
            else => {},
        };
    }
    if (!ends[0] and !ends[1]) return .{};
    const bir = o.in.birs[m];
    const data = bir.instData(expr);
    const target: ?[2]u32 = switch (bir.instTag(expr)) {
        .top => .{ m, data.lhs },
        .ext_value => blk: {
            if (data.lhs >= o.in.provenance.len) break :blk null;
            const d = o.in.provenance[data.lhs].valueDecl(data.rhs) orelse break :blk null;
            break :blk .{ data.lhs, d.int() };
        },
        else => null,
    };
    const t = target orelse return .{
        .decoded = if (ends[0]) top_taint.decoded else &.{},
        .encoded = if (ends[1]) top_taint.encoded else &.{},
    };
    const s = (try o.ensureSummary(t[0], t[1])) orelse return top_taint;
    const both = try o.slotProvs(s, t, true);
    return .{
        .decoded = if (ends[0]) both.decoded else &.{},
        .encoded = if (ends[1]) both.encoded else &.{},
    };
}

/// A `codec_value` node: its type's module's `codec`, a function of `⊤`,
/// whose result's slots its summary names. Not the value its call makes
/// at each run: what it put in a slot is `⊤`.
fn codecValueTaint(o: *Ownership, plan: *const SchemaPlan, i: u32) Allocator.Error!SchemaTaint {
    if (i >= plan.value_targets.len) return top_taint;
    const target = plan.value_targets[i];
    const owner = o.in.graph.find(target.package, SchemaGraph.symbol(plan, target.module)) orelse return top_taint;
    const om = owner.int();
    const name = SchemaGraph.symbol(plan, target.name);
    const bir = o.in.birs[om];
    var decl: ?u32 = null;
    for (bir.decls, 0..) |d, k| {
        if (d.kind.isValue() and bir.symbol(d.name) == name) decl = @intCast(k);
    }
    const d = decl orelse return top_taint;
    const s = (try o.ensureSummary(om, d)) orelse return top_taint;
    return o.slotProvs(s, .{ om, d }, false);
}

/// The provenances a summary's result puts in each slot, as a caller of
/// the declaration `t` would see them: a cell a value's definition made is
/// that value's own (`sharedOf`) when `shared` holds, else `⊤`. A cell at
/// `⋆` is in both slots, and a `⊤` at the root covers them.
fn slotProvs(o: *Ownership, s: *const Summary, t: [2]u32, shared: bool) Allocator.Error!SchemaTaint {
    const keep = o.keep.allocator();
    var decoded: std.ArrayList(Prov) = .empty;
    var encoded: std.ArrayList(Prov) = .empty;
    for (s.res) |r| {
        const first = o.firstStep(r.path);
        const into_decoded, const into_encoded = if (first) |st| switch (st.kind) {
            .schema_decoded => .{ true, false },
            .schema_encoded => .{ false, true },
            .any => if (st.arg == 0) .{ true, true } else continue,
            else => continue,
        } else switch (r.prov.kind) {
            // The value itself, at the root. One its definition or call
            // made holds in its slots what the summary names there; one
            // that may be anything covers them; any other — another
            // top-level value, a parameter — is a value whose slots this
            // summary does not name.
            .fresh, .esc => continue,
            else => .{ true, true },
        };
        const p: Prov = if (first == null) .{ .kind = .top, .a = if (r.prov.kind == .top) r.prov.a else unfollowed } else switch (r.prov.kind) {
            .fresh, .esc => if (shared) .{ .kind = .shared, .a = t[0], .b = t[1], .path = r.path } else .{ .kind = .top, .a = unfollowed },
            .shared => r.prov,
            else => .{ .kind = .top, .a = if (r.prov.kind == .top) r.prov.a else unfollowed },
        };
        if (into_decoded) try decoded.append(keep, p);
        if (into_encoded) try encoded.append(keep, p);
    }
    return .{ .decoded = decoded.items, .encoded = encoded.items };
}

/// §30.10: the summary of a call of a schema declaration's member —
/// `S.schema`, `S.parse`, `S.parseWith`, `S.print`, `S.printWith` — whose
/// first `n` arguments are its schema arguments. `S.schema` makes a schema
/// whose slots hold its own (`schemaTaint`) and its arguments'; it keeps
/// its arguments. `S.parse` answers what it builds and its decoding slot;
/// `S.print` a string.
fn schemaMemberRow(o: *Ownership, m: u32, decl: u32, kind: Interface.SchemaMember.Kind, arity: u32) Allocator.Error!?*const Summary {
    const n = o.in.birs[m].decls[decl].params;
    const extra: u32 = switch (kind) {
        .schema => 0,
        .parse, .print => 1,
        .parse_with, .print_with => 2,
        .type, .encoded => return null,
    };
    // A nongeneric declaration's `S.schema` takes `⊤`.
    if (arity != n + extra and !(kind == .schema and n == 0 and arity == 1)) return null;
    // `m`, `decl`, the member and the arity: one row per call shape.
    const key: [4]u32 = .{ m, decl, @backingInt(kind), arity };
    if (o.schema_members.get(key)) |s| return s;
    const keep = o.keep.allocator();
    const taint = try o.schemaTaint(m, decl);
    const R = bit_r;
    const A = bit_a;
    const slots = [_]u32{ try o.child(eps, .schema_decoded, 0), try o.child(eps, .schema_encoded, 0) };
    const any = try o.child(eps, .any, 0);
    var uses: std.ArrayList(UseEntry) = .empty;
    var res: std.ArrayList(ResEntry) = .empty;
    try res.append(keep, .{ .path = eps, .prov = .{ .kind = .fresh, .a = 1 }, .xc = .{ .no = 1 } });
    switch (kind) {
        .schema => {
            // What the value keeps of its arguments: not a slot, so that a
            // run's answer holds only what their slots hold.
            const kept = if (o.in.interner.find("args")) |sym| try o.child(eps, .field, @backingInt(sym)) else any;
            for (0..n) |iu| {
                const i: u32 = @intCast(iu);
                try uses.append(keep, .{ .param = i, .path = eps, .bits = R | A });
                try res.append(keep, .{ .path = kept, .prov = .{ .kind = .param, .a = i, .path = eps }, .approx = true });
                for (slots) |p| try res.append(keep, .{ .path = p, .prov = .{ .kind = .param, .a = i, .path = p } });
            }
            for (taint.decoded) |p| try res.append(keep, .{ .path = slots[0], .prov = p });
            for (taint.encoded) |p| try res.append(keep, .{ .path = slots[1], .prov = p });
        },
        .parse, .parse_with => {
            for (0..n) |iu| {
                const i: u32 = @intCast(iu);
                try uses.append(keep, .{ .param = i, .path = eps, .bits = R });
                try uses.append(keep, .{ .param = i, .path = slots[0], .bits = R | A });
                try o.anywhereIn(&res, .{ .kind = .param, .a = i, .path = slots[0] });
            }
            for (n..arity) |i| try uses.append(keep, .{ .param = @intCast(i), .path = eps, .bits = R });
            for (taint.decoded) |p| try o.anywhereIn(&res, p);
        },
        .print, .print_with => {
            for (0..arity - 1) |i| try uses.append(keep, .{ .param = @intCast(i), .path = eps, .bits = R });
            // An issue holds the value it was handed (`Issue.input`).
            try uses.append(keep, .{ .param = arity - 1, .path = eps, .bits = R | A });
            try o.anywhereIn(&res, .{ .kind = .param, .a = arity - 1, .path = eps });
        },
        .type, .encoded => unreachable,
    }
    // As `codecRunRow`'s: a declaration's parse builds every record it
    // answers, when neither its own conversions nor its schema arguments
    // answer values the program made.
    if ((kind == .parse or kind == .parse_with) and n == 0 and taint.decoded.len == 0) res.items[0].rxc = .{};
    const s = try keep.create(Summary);
    s.* = try o.normalize(.{ .params = arity, .uses = uses.items, .res = res.items, .asserted = true });
    try o.schema_members.put(o.in.gpa, key, s);
    return s;
}

// ---------------------------------------------------------------------------
// Ownership words (§24)
// ---------------------------------------------------------------------------

/// The summary a declaration's ownership words give (§24.2), or the
/// thesis's row for a `foreign` that carries none (§24.5). Null for a beni
/// declaration with no words: its summary is read off its body.
fn wordsRow(o: *Ownership, m: u32, d: u32) Allocator.Error!?Summary {
    const bir = o.in.birs[m];
    const decl = bir.decls[d];
    const slots = try o.flipped(m, d, bir.ownSlots(decl));
    const entry_word = @import("../parse/Ast.zig").OwnWord.entry.bit();
    const ordinary = for (slots) |slot| {
        if (slot[1] & ~entry_word != 0) break true;
    } else false;
    if (decl.kind != .foreign_value and !ordinary) return null;
    if (slots.len == 0 and decl.kind != .foreign_value) return null;
    const n = decl.params;
    const keep = o.keep.allocator();
    const W = @import("../parse/Ast.zig").OwnWord;
    // The annotation's parameter types: which are functions written out,
    // and how many parameters each such function takes.
    var fn_arity = try keep.alloc(?u32, n);
    @memset(fn_arity, null);
    // §30.9: a `List` of functions written out: its words describe each
    // element, a function slot at the parameter's `[*]`.
    var elem_arity = try keep.alloc(?u32, n);
    @memset(elem_arity, null);
    if (decl.annotation.unwrap()) |ann| if (bir.instTag(ann) == .type_fn) {
        const ps = bir.extraSlice(bir.subRange(@fromBackingInt(@intCast(bir.instData(ann).lhs))), Inst.Index);
        const graph_m: Graph.Index = @fromBackingInt(@intCast(m));
        for (ps, 0..) |p, i| {
            if (i >= n) continue;
            if (bir.instTag(p) == .type_fn) {
                fn_arity[i] = @intCast(bir.extraSlice(bir.subRange(@fromBackingInt(@intCast(bir.instData(p).lhs))), Inst.Index).len);
                continue;
            }
            if (bir.instTag(p) != .type_app) continue;
            const head: Inst.Index = @fromBackingInt(@intCast(bir.instData(p).lhs));
            if (o.in.types.headId(graph_m, bir.instTag(head), bir.instData(head)) != o.in.types.well_known.list) continue;
            const args = bir.extraSlice(bir.subRange(@fromBackingInt(@intCast(bir.instData(p).rhs))), Inst.Index);
            if (args.len != 1 or bir.instTag(args[0]) != .type_fn) continue;
            elem_arity[i] = @intCast(bir.extraSlice(bir.subRange(@fromBackingInt(@intCast(bir.instData(args[0]).lhs))), Inst.Index).len);
        }
    };
    var slot_keys: std.ArrayList([2]u32) = .empty;
    var uses: std.ArrayList(UseEntry) = .empty;
    var res: std.ArrayList(ResEntry) = .empty;
    var supply: std.ArrayList(SupplyEntry) = .empty;
    var funs: std.ArrayList(FunFacts) = .empty;
    const any = try o.child(eps, .any, 0);
    var returned = false;
    var result_words: u32 = 0;
    for (slots) |s| if (s[0] == Bir.own_result) {
        result_words = s[1];
    };
    for (0..n) |iu| {
        const i: u32 = @intCast(iu);
        var words: u32 = 0;
        for (slots) |s| if (s[0] == i) {
            words = s[1];
        };
        const has = struct {
            fn f(x: u32, w: W) bool {
                return x & w.bit() != 0;
            }
        }.f;
        words &= ~entry_word;
        // What is not written is the worst case (§24.2).
        if (words == 0) words = W.escaped.bit();
        if (elem_arity[i]) |arity| if (words & (W.once.bit() | W.many.bit() | W.unused.bit()) != 0) {
            // §30.9: each element of the list is a function the call treats
            // as the words say: a slot at `[*]`, numbered after the
            // parameters. The list itself is read.
            const j: u32 = n + @as(u32, @intCast(slot_keys.items.len));
            try slot_keys.append(keep, .{ i, try o.child(eps, .elem, 0) });
            const kept = has(words, .escaped);
            const calls: Calls = if (has(words, .unused)) .zero else if (has(words, .once)) .once else .many;
            try funs.append(keep, .{ .param = j, .calls = calls, .seen = !kept });
            if (calls != .zero) {
                for (0..arity) |k| try supply.append(keep, if (has(words, .owned))
                    .{ .fun = j, .k = @intCast(k), .path = eps, .prov = .{ .kind = .fresh }, .owned = true }
                else
                    .{ .fun = j, .k = @intCast(k), .path = eps, .prov = .{ .kind = .top, .a = 0 }, .owned = false });
            }
            try uses.append(keep, .{ .param = i, .path = eps, .bits = bit_r | (if (kept) bit_j else 0) });
            if (has(words, .returned)) {
                returned = true;
                try res.append(keep, .{ .path = eps, .prov = .{ .kind = .cb, .a = j } });
            }
            if (has(words, .aliased)) try res.append(keep, .{ .path = any, .prov = .{ .kind = .cb, .a = j }, .approx = true });
            continue;
        };
        if (fn_arity[i]) |arity| {
            // A function parameter: how often it is called, what it is
            // handed, and whether JavaScript keeps it.
            const kept = has(words, .escaped);
            const calls: Calls = if (has(words, .unused)) .zero else if (has(words, .once)) .once else .many;
            try funs.append(keep, .{ .param = i, .calls = calls, .seen = !kept });
            if (calls != .zero) {
                for (0..arity) |k| try supply.append(keep, if (has(words, .owned))
                    .{ .fun = i, .k = @intCast(k), .path = eps, .prov = .{ .kind = .fresh }, .owned = true }
                else
                    .{ .fun = i, .k = @intCast(k), .path = eps, .prov = .{ .kind = .top, .a = 0 }, .owned = false });
            }
            // A function kept by JavaScript escapes what it captured (§18.6).
            if (kept) try uses.append(keep, .{ .param = i, .path = eps, .bits = bit_r | bit_j }) else if (calls != .zero) try uses.append(keep, .{ .param = i, .path = eps, .bits = bit_r });
            if (has(words, .returned)) {
                returned = true;
                try res.append(keep, .{ .path = eps, .prov = .{ .kind = .cb, .a = i } });
            }
            if (has(words, .aliased)) try res.append(keep, .{ .path = any, .prov = .{ .kind = .cb, .a = i }, .approx = true });
            continue;
        }
        var bits: u8 = 0;
        if (!has(words, .unused)) bits |= bit_r;
        if (has(words, .aliased) or has(words, .returned)) bits |= bit_a;
        if (has(words, .escaped)) bits |= bit_e;
        if (has(words, .consumed)) bits |= bit_w | bit_x | bit_d;
        if (bits != 0) try uses.append(keep, .{ .param = i, .path = eps, .bits = bits });
        const p: Prov = .{ .kind = .param, .a = i, .path = eps };
        if (has(words, .returned)) {
            returned = true;
            try res.append(keep, .{ .path = eps, .prov = p });
        }
        if (has(words, .aliased)) try res.append(keep, .{ .path = any, .prov = p, .approx = true });
    }
    const lost: XSum = .{ .no = 1 };
    if (result_words & W.fresh.bit() != 0) {
        try res.append(keep, .{ .path = eps, .prov = .{ .kind = .fresh, .a = 1 }, .xc = if (result_words & W.exclusive.bit() != 0) .{} else lost });
    } else if (result_words & W.escaped.bit() != 0) {
        try res.append(keep, .{ .path = eps, .prov = .{ .kind = .esc, .a = 1 }, .xc = lost });
    } else if (result_words & W.unknown.bit() != 0 or !returned) {
        try res.append(keep, .{ .path = eps, .prov = .{ .kind = .top, .a = 0 }, .xc = lost });
    }
    var out = try o.normalize(.{
        .params = n,
        .uses = uses.items,
        .res = res.items,
        .supply = supply.items,
        .funs = funs.items,
        .asserted = true,
        .slots = slot_keys.items,
    });
    out.words = ordinary;
    // The thesis's row for a `foreign` without words is a default, not an
    // assertion anyone made (§24.5).
    out.asserted = out.words;
    return out;
}

/// The words of declaration `d` of module `m`, with `--ownership-flips`'s
/// edits applied when it names the declaration (§24.6).
fn flipped(o: *Ownership, m: u32, d: u32, slots: []const [2]u32) Allocator.Error![]const [2]u32 {
    const flip = o.in.flip orelse return slots;
    const bir = o.in.birs[m];
    if (!std.mem.eql(u8, o.in.module_names[m], flip.module)) return slots;
    if (!std.mem.eql(u8, o.in.interner.slice(bir.symbol(bir.decls[d].name)), flip.decl)) return slots;
    var out: std.ArrayList([2]u32) = .empty;
    try out.appendSlice(o.keep.allocator(), slots);
    var met = true;
    for (flip.edits) |e| {
        const i = for (out.items, 0..) |s, i| {
            if (s[0] == e.slot) break i;
        } else blk: {
            try out.append(o.keep.allocator(), .{ e.slot, 0 });
            break :blk out.items.len - 1;
        };
        if (e.from) |w| {
            if (out.items[i][1] & w.bit() == 0) met = false;
            out.items[i][1] &= ~w.bit();
        }
        if (e.to) |w| out.items[i][1] |= w.bit();
    }
    o.flip_applied = met;
    return out.items;
}

/// core/Dict's `focus` (§20.8), whose row is its body's with one fact asserted.
fn isDictFocus(o: *const Ownership, m: u32, d: u32) bool {
    if (o.in.packages[m] != .core or !std.mem.eql(u8, o.in.module_names[m], "Dict")) return false;
    const bir = o.in.birs[m];
    return std.mem.eql(u8, o.in.interner.slice(bir.symbol(bir.decls[d].name)), "focus");
}

/// The dictionary's destructive read (§20.8, thesis §7 *A dictionary*): the
/// value handed to `alter` is taken out of the tree and owned, on condition
/// that the dictionary is exclusive — as `List.focus`'s supply is (§18.5).
fn assertDictFocus(o: *Ownership, s: Summary) Allocator.Error!Summary {
    if (s.limit != .none) return s;
    const keep = o.keep.allocator();
    const whole = try keep.dupe(XAtom, &.{.{ .kind = .excl, .a = .{ .kind = .param, .a = 0, .path = eps } }});
    // The asserted tree protocol replaces implementation-only construction
    // annotations; the real input's annotations still arrive through projection.
    var actual_supply: std.ArrayList(SupplyEntry) = .empty;
    for (s.supply) |e| if (!e.prov.condition_only) try actual_supply.append(keep, e);
    const supply = actual_supply.items;
    for (supply) |*e| {
        if (e.fun != 2 or e.prov.kind != .param or e.prov.a != 0) continue;
        e.owned = true;
        e.approx = false;
        e.prov.taken = true;
        e.xc = .{ .atoms = whole };
    }
    // What `alter` returns is put back where the value was taken from: the
    // dictionary stays exclusive when it keeps shape (thesis §7: "excl if π₁
    // excl and g keeps shape"), which states the body's `sep` of the value
    // put back from the rest in the focus's own terms.
    const keep_atom: XAtom = .{ .kind = .keep, .a = .{ .kind = .cb, .a = 2 }, .b = .{ .kind = .param, .a = 0, .path = eps } };
    var actual_res: std.ArrayList(ResEntry) = .empty;
    for (s.res) |r| if (!r.prov.condition_only) try actual_res.append(keep, r);
    const res = actual_res.items;
    for (res) |*r| {
        var atoms: std.ArrayList(XAtom) = .empty;
        var dropped = false;
        for (r.xc.atoms) |x| {
            // An apart drops the pairs that name a callback's result: its
            // members that are one (§16.7, #693).
            if (x.isApart()) {
                var named = false;
                for (x.groups) |g| for (g) |p| {
                    if (p.kind == .cb) named = true;
                };
                if (!named) {
                    try atoms.append(keep, x);
                    continue;
                }
                dropped = true;
                const gs = try keep.alloc([]Prov, x.groups.len);
                for (gs, x.groups) |*d, g| {
                    var kept: std.ArrayList(Prov) = .empty;
                    for (g) |p| if (p.kind != .cb) try kept.append(keep, p);
                    d.* = kept.items;
                }
                try apartAtoms(keep, x.kind, gs, &atoms);
                continue;
            }
            if (x.a.kind == .cb or x.b.kind == .cb) {
                dropped = true;
                continue;
            }
            try atoms.append(keep, x);
        }
        if (!dropped) continue;
        if (r.prov.kind == .param) try atoms.append(keep, keep_atom);
        r.xc = .{ .no = r.xc.no, .atoms = sortAtoms(atoms.items) };
    }
    for (res) |*r| {
        if (r.prov.kind != .param or r.prov.a != 0) continue;
        for (supply) |e| {
            if (e.fun != 2 or e.prov.kind != .param or !e.prov.taken or !o.isPrefix(e.prov.path, r.prov.path)) continue;
            const tail = (try o.suffix(e.prov.path, r.prov.path)) orelse continue;
            const selected = try o.concat(e.path, tail);
            r.sc = .{ .atoms = try keep.dupe(XAtom, &.{
                .{ .kind = .spine, .a = r.prov },
                .{ .kind = .keep_spine, .a = .{ .kind = .cb, .a = 2, .path = selected }, .b = r.prov },
            }) };
            break;
        }
    }
    var out = s;
    out.supply = supply;
    out.res = res;
    out.asserted = true;
    return o.normalize(out);
}

/// §23.3: the send positions — `browser`'s `Hosted` functions that hand a
/// body to the runtime, which calls it with a send, and the taggers the
/// runtime sends the results of.
const HostedRow = enum {
    /// `job`, `later`: π₁ is handed a send as its parameter 1.
    body,
    /// `tap`, `hook`: π₁ is handed a send of a raw value, and π₂ tags each
    /// value it sends, supplied borrowed — one value goes through the tagger
    /// of every current subscription of its key.
    sub,
    /// `mapJob`, `mapLater`: π₂ tags what the inner send gave up, owned.
    map_owned,
    /// `mapTap`: π₂ tags what a subscription's tagger made of a value that
    /// went to every tagger of its key: borrowed.
    map_borrowed,
    /// `runJob`, `callJob`: π₂ is a send the runtime forwards to a body whose
    /// sends were checked where it was made (`job`'s row).
    forward,
    /// `browser-inline`'s `Sub.on k start tag`: π₂ is handed a send of a raw
    /// value, and π₃ tags each value it sends, supplied borrowed — `tap`'s
    /// row one parameter along, past the key (#426).
    sub_keyed,

    /// The parameters whose facts the row asserts in place of the body's.
    fn owns(row: HostedRow, param: u32) bool {
        return switch (row) {
            .sub_keyed => param == 1 or param == 2,
            else => param <= 1,
        };
    }
};

fn hostedRow(o: *const Ownership, m: u32, d: u32) ?HostedRow {
    // `browser-inline`'s commands and subscriptions (#426): `Cmd.perform`
    // hands its body a send as `job` does, `Sub.on` its start one as `tap`
    // does, and `Sub.map` tags what a tagger made, as `mapTap`.
    if (m < o.in.platform_names.len and std.mem.eql(u8, o.in.platform_names[m], "browser-inline")) {
        const ib = o.in.birs[m];
        const iname = o.in.interner.slice(ib.symbol(ib.decls[d].name));
        const imod = o.in.module_names[m];
        if (std.mem.eql(u8, imod, "Cmd") and std.mem.eql(u8, iname, "perform")) return .body;
        if (std.mem.eql(u8, imod, "Sub") and std.mem.eql(u8, iname, "on")) return .sub_keyed;
        if (std.mem.eql(u8, imod, "Sub") and std.mem.eql(u8, iname, "map")) return .map_borrowed;
        return null;
    }
    if (m >= o.in.platform_names.len or !std.mem.eql(u8, o.in.platform_names[m], "browser")) return null;
    if (!std.mem.eql(u8, o.in.module_names[m], "Hosted")) return null;
    const bir = o.in.birs[m];
    const name = o.in.interner.slice(bir.symbol(bir.decls[d].name));
    if (eqlAny(name, &.{ "job", "later" })) return .body;
    if (eqlAny(name, &.{ "tap", "hook" })) return .sub;
    if (eqlAny(name, &.{ "mapJob", "mapLater" })) return .map_owned;
    if (std.mem.eql(u8, name, "mapTap")) return .map_borrowed;
    if (eqlAny(name, &.{ "runJob", "callJob" })) return .forward;
    return null;
}

/// The row of a send position (§23.3): the body's inferred summary — what
/// the value it makes holds — with the facts of the runtime it hands its
/// functions to asserted, which no beni body shows: the runtime calls them,
/// many times, a body with a send and a tagger with what is sent.
fn assertHosted(o: *Ownership, s: Summary, row: HostedRow) Allocator.Error!Summary {
    if (s.limit != .none) return s;
    const keep = o.keep.allocator();
    // π₁'s and π₂'s facts are the row's. In the `map…` and `forward`
    // rows π₁ is a `Job`, `Later` or `Tap` — a `foreign
    // type`, no function, with no facts to keep — checked where it was made.
    var funs: std.ArrayList(FunFacts) = .empty;
    var supply: std.ArrayList(SupplyEntry) = .empty;
    for (s.funs) |f| if (!row.owns(f.param)) try funs.append(keep, f);
    for (s.supply) |e| if (!row.owns(e.fun)) try supply.append(keep, e);
    const fresh: Prov = .{ .kind = .fresh };
    switch (row) {
        .body => try funs.append(keep, .{ .param = 0, .calls = .many, .send = 0 }),
        .sub => {
            try funs.append(keep, .{ .param = 0, .calls = .many, .send = 0 });
            try funs.append(keep, .{ .param = 1, .calls = .many, .need = true, .sends = true });
            try supply.append(keep, .{ .fun = 1, .k = 0, .path = eps, .prov = fresh, .owned = false });
        },
        .map_owned, .map_borrowed => {
            try funs.append(keep, .{ .param = 1, .calls = .many, .need = true, .sends = true });
            try supply.append(keep, .{ .fun = 1, .k = 0, .path = eps, .prov = fresh, .owned = row == .map_owned });
        },
        .sub_keyed => {
            try funs.append(keep, .{ .param = 1, .calls = .many, .send = 0 });
            try funs.append(keep, .{ .param = 2, .calls = .many, .need = true, .sends = true });
            try supply.append(keep, .{ .fun = 2, .k = 0, .path = eps, .prov = fresh, .owned = false });
        },
        // The job calls it; what it is handed was checked at the job's send
        // position, so the row supplies it nothing.
        .forward => try funs.append(keep, .{ .param = 1, .calls = .many }),
    }
    var out = s;
    out.funs = funs.items;
    out.supply = supply.items;
    out.asserted = true;
    return o.normalize(out);
}

/// §18.3: a writer that stores parameter `v` in its base `b` keeps the base
/// exclusive when `v` is, and shares no cell with the base's elements.
fn stores(o: *Ownership, b: u32, v: u32, elem: u32) Allocator.Error!XSum {
    const atoms = try o.keep.allocator().alloc(XAtom, 2);
    atoms[0] = .{ .kind = .excl, .a = .{ .kind = .param, .a = v, .path = eps } };
    atoms[1] = sepAtom(.{ .kind = .param, .a = v, .path = eps }, .{ .kind = .param, .a = b, .path = elem });
    return .{ .atoms = sortAtoms(atoms) };
}

/// Sorted, without an `excl` that another implies: a value's deep
/// exclusivity covers every path under it.
fn pruneAtoms(o: *const Ownership, all: []XAtom) []const XAtom {
    const sorted = sortAtoms(all);
    var n: usize = 0;
    var out = all[0..sorted.len];
    for (sorted, 0..) |t, i| {
        if (t.kind == .excl) {
            var implied = false;
            for (sorted, 0..) |u, j| {
                if (j == i or u.kind != .excl or u.a.kind != t.a.kind or u.a.a != t.a.a or u.a.path == t.a.path) continue;
                if (o.isPrefix(u.a.path, t.a.path)) {
                    implied = true;
                    break;
                }
            }
            if (implied) continue;
        }
        out[n] = t;
        n += 1;
    }
    return out[0..n];
}

/// `sep a b` with its two sides in order, so that one fact is one atom.
pub fn sepAtom(a: Prov, b: Prov) XAtom {
    return if (b.less(a)) .{ .kind = .sep, .a = b, .b = a } else .{ .kind = .sep, .a = a, .b = b };
}

fn eqlAny(name: []const u8, names: []const []const u8) bool {
    for (names) |n| if (std.mem.eql(u8, n, name)) return true;
    return false;
}

// ---------------------------------------------------------------------------
// Printing a summary (§16.11)
// ---------------------------------------------------------------------------

fn summaryText(o: *Ownership, m: u32, d: u32, s: *const Summary) Allocator.Error![]const u8 {
    const arena = o.out.allocator();
    const bir = o.in.birs[m];
    o.text_sum = s;
    defer o.text_sum = null;
    var parts: std.ArrayList([]const u8) = .empty;
    // Parameters' bits, in text order.
    var uses: std.ArrayList([]const u8) = .empty;
    for (s.uses) |u| {
        var buf: std.Io.Writer.Allocating = .init(arena);
        const wr = &buf.writer;
        wr.print("π{d}", .{u.param + 1}) catch return error.OutOfMemory;
        o.writePath(wr, u.path) catch return error.OutOfMemory;
        wr.writeByte(' ') catch return error.OutOfMemory;
        // A record's read and keep print as a list's (§31.7).
        inline for (.{ .{ bit_r | bit_q, "R" }, .{ bit_a, "A" }, .{ bit_e | bit_k, "E" }, .{ bit_j, "J" } }) |b| {
            if (u.bits & b[0] != 0) wr.writeAll(b[1]) catch return error.OutOfMemory;
        }
        // `w`: written only through an approximate step.
        // `S`: a send's write, of every cell below the path too (§23.2).
        if (u.bits & bit_w != 0) wr.writeAll(if (u.bits & bit_d != 0)
            (if (u.bits & bit_x != 0) "S" else "s")
        else if (u.bits & bit_x != 0) "W" else "w") catch return error.OutOfMemory;
        if (u.bits & bit_w != 0 and u.extent == .storage) wr.writeAll("[storage]") catch return error.OutOfMemory;
        // §31.7: a record's write, with the fields it writes; `W{}` when a
        // block read back could not say which.
        if (u.bits & bit_f != 0) {
            // In text order: a symbol's number is not the text's.
            const names = try arena.alloc([]const u8, u.fields.len);
            for (u.fields, names) |f, *n| n.* = if (f == none) "?" else o.in.interner.slice(@fromBackingInt(f));
            sortText(names);
            wr.print("W{{{s}}}", .{try std.mem.join(arena, ", ", names)}) catch return error.OutOfMemory;
        }
        try uses.append(arena, try buf.toOwnedSlice());
    }
    sortText(uses.items);
    if (uses.items.len > 0) try parts.append(arena, try std.mem.join(arena, ", ", uses.items));
    // The result, grouped by path in text order.
    var groups: std.ArrayList(struct { path: []const u8, provs: std.ArrayList([]const u8) }) = .empty;
    for ([_][]const ResEntry{ s.res, s.objs }) |entries| for (entries) |r| {
        const pt = try o.pathText(r.path);
        var found: ?usize = null;
        for (groups.items, 0..) |g, i| if (std.mem.eql(u8, g.path, pt)) {
            found = i;
        };
        const i = found orelse blk: {
            try groups.append(arena, .{ .path = pt, .provs = .empty });
            break :blk groups.items.len - 1;
        };
        const t = try std.fmt.allocPrint(arena, "{s}{s}{s}", .{ try o.provText(r.prov), try o.xsumText(r.xc), try o.rxsumText(r.rxc) });
        try groups.items[i].provs.append(arena, if (r.approx) try std.fmt.allocPrint(arena, "~{s}", .{t}) else t);
    };
    if (groups.items.len > 0) {
        var gtexts: std.ArrayList([]const u8) = .empty;
        for (groups.items) |*g| {
            sortText(g.provs.items);
            const provs = try std.mem.join(arena, " ", g.provs.items);
            try gtexts.append(arena, if (g.path.len == 0) provs else try std.fmt.allocPrint(arena, "{s} {s}", .{ g.path, provs }));
        }
        sortText(gtexts.items);
        try parts.append(arena, try std.fmt.allocPrint(arena, "res {s}", .{try std.mem.join(arena, ", ", gtexts.items)}));
    }
    // Function parameters.
    for (s.funs) |f| {
        var buf: std.Io.Writer.Allocating = .init(arena);
        const wr = &buf.writer;
        // A function slot (§24.9) is named by its parameter and path.
        const fname = if (f.param >= s.params and f.param - s.params < s.slots.len)
            try std.fmt.allocPrint(arena, "π{d}{s}", .{ s.slots[f.param - s.params][0] + 1, try o.pathText(s.slots[f.param - s.params][1]) })
        else
            try std.fmt.allocPrint(arena, "π{d}", .{f.param + 1});
        wr.print("{s} calls {s}", .{ fname, switch (f.calls) {
            .zero => "0",
            .once => "≤1",
            .many => "many",
        } }) catch return error.OutOfMemory;
        if (f.need) wr.writeAll(", need owned") catch return error.OutOfMemory;
        var guards: std.ArrayList([]const u8) = .empty;
        for (f.need_if) |writer| {
            const name = if (writer >= s.params and writer - s.params < s.slots.len)
                try std.fmt.allocPrint(arena, "π{d}{s}", .{ s.slots[writer - s.params][0] + 1, try o.pathText(s.slots[writer - s.params][1]) })
            else
                try std.fmt.allocPrint(arena, "π{d}", .{writer + 1});
            try guards.append(arena, name);
        }
        sortText(guards.items);
        for (guards.items) |name| wr.print(", need owned if {s} writes", .{name}) catch return error.OutOfMemory;
        if (f.rneed) wr.writeAll(", need owned record") catch return error.OutOfMemory;
        if (!f.seen) wr.writeAll(", unseen") catch return error.OutOfMemory;
        if (f.send != none) wr.print(", sends π{d}", .{f.send + 1}) catch return error.OutOfMemory;
        var sup: std.ArrayList([]const u8) = .empty;
        for ([_][]const SupplyEntry{ s.supply, s.rsupply }) |entries| for (entries) |e| {
            if (e.fun != f.param) continue;
            const pt = try o.pathText(e.path);
            try sup.append(arena, try std.fmt.allocPrint(arena, "supply {d}{s} {s} {s}{s}{s}{s}", .{ e.k + 1, pt, try o.provText(e.prov), if (e.owned) "owned" else "borrowed", if (e.prov.taken) " taken" else "", try o.xsumText(e.xc), try o.rxsumText(e.rxc) }));
        };
        sortText(sup.items);
        for (sup.items) |t| wr.print(", {s}", .{t}) catch return error.OutOfMemory;
        try parts.append(arena, try buf.toOwnedSlice());
    }
    if (s.xreq.len > 0) {
        var reqs: std.ArrayList([]const u8) = .empty;
        for (s.xreq) |x| try reqs.append(arena, try o.atomText(x));
        sortText(reqs.items);
        try parts.append(arena, try std.fmt.allocPrint(arena, "xreq {s}", .{try std.mem.join(arena, ", ", reqs.items)}));
    }
    if (s.rxreq.len > 0) {
        var reqs: std.ArrayList([]const u8) = .empty;
        for (s.rxreq) |x| try reqs.append(arena, try o.atomText(x));
        sortText(reqs.items);
        try parts.append(arena, try std.fmt.allocPrint(arena, "rxreq {s}", .{try std.mem.join(arena, ", ", reqs.items)}));
    }
    if (s.limit != .none) try parts.append(arena, try std.fmt.allocPrint(arena, "limit {s} {d}", .{ s.limit.text(), s.limit_at }));
    const facts = if (parts.items.len == 0) "unused" else try std.mem.join(arena, "; ", parts.items);
    const name = o.in.interner.slice(bir.symbol(bir.decls[d].name));
    return std.fmt.allocPrint(arena, "summary {s}: {s}{s}", .{ name, facts, if (s.words) " (words)" else if (s.asserted) " (asserted)" else "" });
}

/// A condition as a summary line prints it (§18.3): nothing when it holds
/// outright, `{excl π2, sep π1[*] π2}` when it rests on atoms, `{lost}` or
/// `{shared}` when it fails approximately or exactly.
fn xsumText(o: *Ownership, x: XSum) Allocator.Error![]const u8 {
    const arena = o.out.allocator();
    if (x.no == 1) return "{lost}";
    if (x.no == 2) return "{shared}";
    if (x.atoms.len == 0) return "";
    var parts: std.ArrayList([]const u8) = .empty;
    for (x.atoms) |t| try parts.append(arena, try o.atomText(t));
    sortText(parts.items);
    return std.fmt.allocPrint(arena, "{{{s}}}", .{try std.mem.join(arena, ", ", parts.items)});
}

/// A record condition as a summary line prints it (§31.4 item 6): `r{…}`
/// beside a list's, nothing when it holds outright.
fn rxsumText(o: *Ownership, x: XSum) Allocator.Error![]const u8 {
    if (x.no == 1) return "r{lost}";
    if (x.no == 2) return "r{shared}";
    if (x.atoms.len == 0) return "";
    return std.fmt.allocPrint(o.out.allocator(), "r{s}", .{try o.xsumText(x)});
}

fn atomText(o: *Ownership, x: XAtom) Allocator.Error![]const u8 {
    const arena = o.out.allocator();
    return switch (x.kind) {
        .excl => std.fmt.allocPrint(arena, "excl {s}", .{try o.provText(x.a)}),
        .spine => std.fmt.allocPrint(arena, "spine {s}", .{try o.provText(x.a)}),
        .sep_spine => std.fmt.allocPrint(arena, "sep-spine {s} {s}", .{ try o.provText(x.a), try o.provText(x.b) }),
        .sep_root => std.fmt.allocPrint(arena, "sep-root {s} {s}", .{ try o.provText(x.a), try o.provText(x.b) }),
        .keep_spine => std.fmt.allocPrint(arena, "keep-spine {s} {s}", .{ try o.provText(x.a), try o.provText(x.b) }),
        .sep => std.fmt.allocPrint(arena, "sep {s} {s}", .{ try o.provText(x.a), try o.provText(x.b) }),
        .keep => std.fmt.allocPrint(arena, "keep {s} {s}", .{ try o.provText(x.a), try o.provText(x.b) }),
        .apart, .apart_spine => blk: {
            // Members and groups by their text, as a condition's atoms are.
            const groups = try arena.alloc([]const u8, x.groups.len);
            for (groups, x.groups) |*t, g| {
                const members = try arena.alloc([]const u8, g.len);
                for (members, g) |*m, p| m.* = try o.provText(p);
                sortText(members);
                t.* = try std.fmt.allocPrint(arena, "[{s}]", .{try std.mem.join(arena, " ", members)});
            }
            sortText(groups);
            break :blk std.fmt.allocPrint(arena, "{s} {s}", .{ if (x.kind == .apart) "apart" else "apart-spine", try std.mem.join(arena, " ", groups) });
        },
    };
}

fn sortText(items: [][]const u8) void {
    std.mem.sort([]const u8, items, {}, struct {
        fn less(_: void, x: []const u8, y: []const u8) bool {
            return std.mem.lessThan(u8, x, y);
        }
    }.less);
}

fn pathText(o: *Ownership, p: u32) Allocator.Error![]const u8 {
    var buf: std.Io.Writer.Allocating = .init(o.out.allocator());
    o.writePath(&buf.writer, p) catch return error.OutOfMemory;
    return buf.toOwnedSlice();
}

fn provText(o: *Ownership, p: Prov) Allocator.Error![]const u8 {
    const arena = o.out.allocator();
    if (p.condition_only) {
        var q = p;
        q.condition_only = false;
        return std.fmt.allocPrint(arena, "condition({s})", .{try o.provText(q)});
    }
    if (p.obj) {
        var q = p;
        q.obj = false;
        return std.fmt.allocPrint(arena, "{s}◦", .{try o.provText(q)});
    }
    const pt = try o.pathText(p.path);
    return switch (p.kind) {
        .param => std.fmt.allocPrint(arena, "π{d}{s}", .{ p.a + 1, pt }),
        .fresh => if (p.a == 0) "fresh" else std.fmt.allocPrint(arena, "fresh{d}", .{p.a}),
        .esc => if (p.a == 0) "esc" else std.fmt.allocPrint(arena, "esc{d}", .{p.a}),
        .shared => blk: {
            const b = o.in.birs[p.a];
            break :blk std.fmt.allocPrint(arena, "shared({s}.{s}){s}", .{ o.in.module_names[p.a], o.in.interner.slice(b.symbol(b.decls[p.b].name)), pt });
        },
        .top => switch (p.a) {
            1 => "⊤limit",
            2 => "⊤input",
            unfollowed => "⊤schema",
            top_call, top_several => "⊤call",
            twice_named => "⊤twice",
            else => "⊤",
        },
        .cb => if (o.text_sum) |s| (if (p.b == 0 and p.a >= s.params and p.a - s.params < s.slots.len) blk: {
            const slot = s.slots[p.a - s.params];
            break :blk std.fmt.allocPrint(arena, "cb(π{d}{s}){s}", .{ slot[0] + 1, try o.pathText(slot[1]), pt });
        } else std.fmt.allocPrint(arena, "cb{d}{s}", .{ p.a + 1, pt })) else std.fmt.allocPrint(arena, "cb{d}{s}", .{ p.a + 1, pt }),
        .klass => if (p.a == none) "λ?" else "λ",
        .env => std.fmt.allocPrint(arena, "◇{d}{s}", .{ p.a, pt }),
    };
}

// ---------------------------------------------------------------------------
// Paths (§4.1)
// ---------------------------------------------------------------------------

/// `level` is §16.7's marker `⟨T⟩`, its argument a `markerId`.
pub const StepKind = enum(u8) { field, tuple, ctor, elem, env, any, markup_render, markup_event, schema_decoded, schema_encoded, level, cast, cast_level };

const Paths = struct {
    parent: std.ArrayList(u32) = .empty,
    kind: std.ArrayList(StepKind) = .empty,
    arg: std.ArrayList(u32) = .empty,
    depth: std.ArrayList(u32) = .empty,
    /// §16.7 (c): each path's nodes and steps, root first, kept for the
    /// run (`keep`): a path has no length limit, and a reader holds its
    /// steps while `child` makes more paths.
    nodes_of: std.ArrayList([]const u32) = .empty,
    steps_of: std.ArrayList([]const Step) = .empty,
    /// The path without its first step, once asked (§18.11).
    rest: std.ArrayList(u32) = .empty,
    /// Whether the path holds a `⋆` step: two paths with none overlap
    /// only when one is the other's ancestor in the trie.
    any: std.ArrayList(bool) = .empty,
    /// Exact cast boundaries need typed matching but stand for one place.
    casts: std.ArrayList(bool) = .empty,
    /// A constructor step whose field can hold a value of its own type
    /// (`levelOf` here or below): a step a marker of the type may begin with.
    holds: std.ArrayList(bool) = .empty,
    representative: std.ArrayList(bool) = .empty,
    map: std.HashMapUnmanaged([3]u32, u32, StepKey, std.hash_map.default_max_load_percentage) = .empty,

    fn deinit(p: *Paths, gpa: Allocator) void {
        p.holds.deinit(gpa);
        p.representative.deinit(gpa);
        p.parent.deinit(gpa);
        p.kind.deinit(gpa);
        p.arg.deinit(gpa);
        p.depth.deinit(gpa);
        p.nodes_of.deinit(gpa);
        p.steps_of.deinit(gpa);
        p.rest.deinit(gpa);
        p.any.deinit(gpa);
        p.casts.deinit(gpa);
        p.map.deinit(gpa);
    }
};

/// A key of `n` words (`n` 0: one `u64`) hashed by multiplication: the
/// walk's cell table and type memos, looked up on every cell and step.
fn WordsKey(comptime n: usize) type {
    const K = if (n == 0) u64 else [n]u32;
    return struct {
        pub fn hash(_: @This(), k: K) u64 {
            var h: u64 = 0x9E3779B97F4A7C15;
            if (n == 0) {
                h ^= k *% 0xC2B2AE3D27D4EB4F;
            } else for (k) |x| {
                h = (h ^ x) *% 0xC2B2AE3D27D4EB4F;
                h ^= h >> 31;
            }
            h ^= h >> 29;
            h *%= 0x165667B19E3779F9;
            return h ^ (h >> 32);
        }
        pub fn eql(_: @This(), a: K, b: K) bool {
            return std.meta.eql(a, b);
        }
    };
}

/// A path step `(parent, kind, arg)` as a hash key: three words mixed by
/// multiplication, which the path trie looks up on every step it takes.
const StepKey = struct {
    pub fn hash(_: StepKey, k: [3]u32) u64 {
        var h: u64 = @as(u64, k[0]) *% 0x9E3779B97F4A7C15;
        h ^= (@as(u64, k[1]) << 32 | k[2]) *% 0xC2B2AE3D27D4EB4F;
        h ^= h >> 29;
        h *%= 0x165667B19E3779F9;
        return h ^ (h >> 32);
    }
    pub fn eql(_: StepKey, a: [3]u32, b: [3]u32) bool {
        return a[0] == b[0] and a[1] == b[1] and a[2] == b[2];
    }
};

/// ε, the empty path. Its id is 0 once `Paths` has been seeded.
pub const eps: u32 = 0;

pub fn seedPaths(o: *Ownership) Allocator.Error!void {
    if (o.paths.parent.items.len != 0) return;
    o.match_cache = try o.in.gpa.create(MatchCache);
    o.match_cache.?.* = .empty;
    const gpa = o.in.gpa;
    try o.paths.parent.append(gpa, none);
    try o.paths.kind.append(gpa, .any);
    try o.paths.arg.append(gpa, 0);
    try o.paths.depth.append(gpa, 0);
    try o.paths.nodes_of.append(gpa, &.{});
    try o.paths.steps_of.append(gpa, &.{});
    try o.paths.rest.append(gpa, none);
    try o.paths.any.append(gpa, false);
    try o.paths.casts.append(gpa, false);
    try o.paths.holds.append(gpa, false);
    try o.paths.representative.append(gpa, false);
}

/// A cache key is a complete, finite type term, not arbitrary marker text.
/// Walk the encoded children iteratively so corrupt input cannot recurse.
pub fn readCastId(o: *Ownership, key: []const u8, refs: []const u32) (Allocator.Error || error{Bad})!u32 {
    try validateCastKeyRefs(o.in.gpa, key, refs.len);
    const parts = try castKeyParts(o.in.gpa, key);
    defer o.in.gpa.free(parts);
    const local = try remapCastKey(o.in.gpa, key, parts, refs);
    defer o.in.gpa.free(local);
    return o.castId(local);
}

fn validateCastKey(gpa: Allocator, key: []const u8) (Allocator.Error || error{Bad})!void {
    return validateCastKeyRefs(gpa, key, null);
}

fn validateCastKeyRefs(gpa: Allocator, key: []const u8, refs: ?usize) (Allocator.Error || error{Bad})!void {
    var work: std.ArrayList([]const u8) = .empty;
    defer work.deinit(gpa);
    if (refs != null and key.len > 0 and key[0] == '@') return error.Bad;
    try work.append(gpa, key);
    while (work.pop()) |term| {
        if (refs != null and term.len > 0 and term[0] == '@') {
            const id = std.fmt.parseInt(u32, term[1..], 10) catch return error.Bad;
            if (id >= refs.?) return error.Bad;
            continue;
        }
        if (std.mem.eql(u8, term, "⋆") or std.mem.eql(u8, term, "unit") or std.mem.eql(u8, term, "{}")) continue;
        if (std.mem.startsWith(u8, term, "var(")) {
            if (term.len < 6 or term[term.len - 1] != ')') return error.Bad;
            var parts = std.mem.splitScalar(u8, term[4 .. term.len - 1], ':');
            const pkg = std.fmt.parseInt(u8, parts.next() orelse return error.Bad, 10) catch return error.Bad;
            if (pkg > 2) return error.Bad;
            if ((parts.next() orelse return error.Bad).len == 0) return error.Bad;
            _ = std.fmt.parseInt(u32, parts.next() orelse return error.Bad, 10) catch return error.Bad;
            _ = std.fmt.parseInt(u32, parts.next() orelse return error.Bad, 10) catch return error.Bad;
            if (parts.next() != null) return error.Bad;
            continue;
        }
        const open = std.mem.indexOfScalar(u8, term, '(') orelse return error.Bad;
        if (term.len == 0 or term[term.len - 1] != ')') return error.Bad;
        const head = term[0..open];
        const record = std.mem.eql(u8, head, "record");
        const func = std.mem.eql(u8, head, "fn");
        if (!record and !func and !std.mem.eql(u8, head, "tuple")) {
            const colon = std.mem.indexOfScalar(u8, head, ':') orelse return error.Bad;
            const pkg = std.fmt.parseInt(u8, head[0..colon], 10) catch return error.Bad;
            if (pkg > 2) return error.Bad;
            const qualified = head[colon + 1 ..];
            const sep = std.mem.indexOf(u8, qualified, "::") orelse return error.Bad;
            if (sep == 0 or sep + 2 == qualified.len) return error.Bad;
            if (std.mem.indexOfScalar(u8, qualified[0..sep], ':') != null or std.mem.indexOfScalar(u8, qualified[sep + 2 ..], ':') != null) return error.Bad;
        }
        var i = open + 1;
        const end = term.len - 1;
        var separated = false;
        var after: usize = 0;
        var label = false;
        while (i < end) {
            if ((record and term[i] == '|') or (func and std.mem.startsWith(u8, term[i..end], "→"))) {
                if (separated or label) return error.Bad;
                separated = true;
                i += if (record) 1 else "→".len;
                continue;
            }
            const from = i;
            while (i < end and std.ascii.isDigit(term[i])) : (i += 1) {}
            if (i == from or i >= end or term[i] != ':') return error.Bad;
            const n = std.fmt.parseInt(usize, term[from..i], 10) catch return error.Bad;
            i += 1;
            if (n == 0 or n > end - i) return error.Bad;
            const nested_term = term[i..][0..n];
            i += n;
            if (record and !separated and !label) {
                if (i >= end or term[i] != '=') return error.Bad;
                i += 1;
                label = true;
            } else {
                if (refs != null and nested_term[0] != '@') return error.Bad;
                try work.append(gpa, nested_term);
                label = false;
                if (separated) after += 1;
            }
        }
        if (label or ((func or record) and (!separated or after != 1))) return error.Bad;
    }
    return;
}

pub const CastPart = struct { start: usize, end: usize, key: u32 };

/// Children are complete interned types. Their local numbers never leave
/// this session: the wire writer remaps them into its own type table.
fn castKeyParts(a: Allocator, key: []const u8) Allocator.Error![]const CastPart {
    if (std.mem.startsWith(u8, key, "var(")) return &.{};
    var i = if (std.mem.indexOfScalar(u8, key, '(')) |p| p + 1 else return &.{};
    var parts: std.ArrayList(CastPart) = .empty;
    while (i < key.len) {
        if (!std.ascii.isDigit(key[i])) {
            i += 1;
            continue;
        }
        const start = i;
        var len: usize = 0;
        while (i < key.len and std.ascii.isDigit(key[i])) : (i += 1) len = len * 10 + key[i] - '0';
        i += 1;
        const end = i + len;
        if (end == key.len or key[end] != '=') {
            std.debug.assert(key[i] == '@');
            const ref_id = std.fmt.parseInt(u32, key[i + 1 .. end], 10) catch unreachable;
            try parts.append(a, .{ .start = start, .end = end, .key = ref_id });
        }
        i = end;
    }
    return parts.toOwnedSlice(a);
}

pub fn castParts(o: *Ownership, id: u32) Allocator.Error![]const CastPart {
    if (o.cast_parts.items[id]) |parts| return parts;
    const parts = try castKeyParts(o.keep.allocator(), o.cast_types.items[id]);
    o.cast_parts.items[id] = parts;
    return parts;
}

fn writeCastRef(w: *std.Io.Writer, id: u32) std.Io.Writer.Error!void {
    var buf: [16]u8 = undefined;
    const text = std.fmt.bufPrint(&buf, "@{d}", .{id}) catch unreachable;
    try w.print("{d}:{s}", .{ text.len, text });
}

fn remapCastKey(a: Allocator, key: []const u8, parts: []const CastPart, refs: []const u32) Allocator.Error![]u8 {
    var b: std.Io.Writer.Allocating = .init(a);
    errdefer b.deinit();
    var at: usize = 0;
    for (parts) |part| {
        b.writer.writeAll(key[at..part.start]) catch return error.OutOfMemory;
        writeCastRef(&b.writer, refs[part.key]) catch return error.OutOfMemory;
        at = part.end;
    }
    b.writer.writeAll(key[at..]) catch return error.OutOfMemory;
    return b.toOwnedSlice();
}

pub fn castWireKey(o: *Ownership, a: Allocator, id: u32, refs: []const u32) Allocator.Error![]u8 {
    return remapCastKey(a, o.cast_types.items[id], try o.castParts(id), refs);
}

/// Expansion is for a requested human report only, never for interning or
/// comparing type identities. Keep it once when many paths print one type.
fn castText(o: *Ownership, id: u32) Allocator.Error![]const u8 {
    if (o.cast_texts.items[id]) |text| return text;
    const key = o.cast_types.items[id];
    const parts = try o.castParts(id);
    var b: std.Io.Writer.Allocating = .init(o.keep.allocator());
    var at: usize = 0;
    for (parts) |part| {
        b.writer.writeAll(key[at..part.start]) catch return error.OutOfMemory;
        const text = try o.castText(part.key);
        b.writer.print("{d}:{s}", .{ text.len, text }) catch return error.OutOfMemory;
        at = part.end;
    }
    b.writer.writeAll(key[at..]) catch return error.OutOfMemory;
    const text = try b.toOwnedSlice();
    o.cast_texts.items[id] = text;
    return text;
}

pub fn castId(o: *Ownership, key: []const u8) Allocator.Error!u32 {
    if (o.cast_ids.get(key)) |id| return id;
    const saved = try o.keep.allocator().dupe(u8, key);
    const id: u32 = @intCast(o.cast_types.items.len);
    try o.cast_types.append(o.in.gpa, saved);
    try o.cast_parts.append(o.in.gpa, null);
    var open = std.mem.startsWith(u8, saved, "var(");
    var wild = std.mem.eql(u8, saved, "⋆");
    var depth: u32 = 0;
    for (try o.castParts(id)) |part| {
        open = open or o.cast_open.items[part.key];
        wild = wild or o.cast_wild.items[part.key];
        depth = @max(depth, o.cast_depth.items[part.key] + 1);
    }
    try o.cast_open.append(o.in.gpa, open);
    try o.cast_wild.append(o.in.gpa, wild);
    try o.cast_depth.append(o.in.gpa, depth);
    try o.cast_texts.append(o.in.gpa, null);
    try o.cast_ids.put(o.in.gpa, saved, id);
    return id;
}

fn child(o: *Ownership, parent: u32, kind_in: StepKind, arg: u32) Allocator.Error!u32 {
    // Type uncertainty does not re-enter a physical level. Reads of a type
    // hole stay conservative, but only a repeated boundary is cast_level.
    const kind = kind_in;
    std.debug.assert(o.paths.parent.items.len != 0);
    const key: [3]u32 = .{ parent, @backingInt(kind), arg };
    if (o.child_memo.get(key)) |c| return c;
    const c = try o.childRaw(parent, kind, arg);
    try o.child_memo.put(o.in.gpa, key, c);
    return c;
}

/// `child`, computed: the fold of §16.7 needs the region the parent is in.
fn childRaw(o: *Ownership, parent: u32, kind: StepKind, arg: u32) Allocator.Error!u32 {
    // A `⋆` absorbs what is below it. There is no cut (§16.7 (c)): every
    // source of unbounded paths has a fold, below.
    if (parent != eps and o.paths.kind.items[parent] == .any) return parent;
    // A type the path is already inside is folded (thesis §3.1, §16.7's
    // level marker): a constructor step into it goes on from the region's
    // first step, under the marker `⟨T⟩`, so `t#Node.0#Node.1` is
    // `t#Node.0⟨Tree⟩#Node.1`, every list of the left subtree, and stays
    // apart from `t#Node.1`, the root's own. A marker added inside a region
    // folds onto the region's.
    switch (kind) {
        .cast, .cast_level => {
            if (parent != eps and o.paths.arg.items[parent] == arg) {
                if (o.paths.kind.items[parent] == .cast_level) return parent;
                if (kind == .cast and o.paths.kind.items[parent] == .cast) return parent;
            }
            var at = parent;
            var first: ?u32 = null;
            while (at != eps) : (at = o.paths.parent.items[at]) {
                if ((o.paths.kind.items[at] == .cast or o.paths.kind.items[at] == .cast_level) and o.paths.arg.items[at] == arg) first = at;
            }
            if (first) |f| return o.rawChild(f, .cast_level, arg);
        },
        .ctor => if (o.ctorType(o.stepCtor(arg))) |ty| if (try o.regionOf(parent, ty)) |r| {
            // Nonrecursive nesting has a finite shape: Maybe (Maybe a)
            // has two different constructor places. Cast cycles now fold
            // at complete-type boundaries instead of these type heads.
            if (!try o.typeRecursive(ty)) return o.rawChild(parent, kind, arg);
            // Core Dict's folded tree remains one place under its trusted
            // representation rule (§20.9).
            if (try o.dictTree(ty)) return o.rawChild(switch (r) {
                .first => |f| o.paths.parent.items[f],
                .marker => |m| m,
            }, kind, arg);
            return o.rawChild(try o.markerAt(r, ty, parent), kind, arg);
        },
        .level => if (try o.regionOf(parent, o.markerType(arg))) |r| return o.markerAt(r, o.markerType(arg), parent),
        // F1 (§16.7, as amended): a function type is a recursive type whose one
        // region step is `◇`, so a closure's environment inside another's
        // goes under the marker of the first: `◇p◇q` is `◇⟨◇⟩◇q`.
        .env => {
            std.debug.assert(arg == 0);
            if (try o.regionOf(parent, fn_type)) |r| return o.rawChild(try o.markerOf(r, fn_type), kind, arg);
        },
        else => {},
    }
    return o.rawChild(parent, kind, arg);
}

/// Where a path is inside a region of a type (§16.7): at its first step
/// into the type, or at its marker.
const Region = union(enum) { first: u32, marker: u32 };

/// The region of type `ty` that `parent` is inside, or null. A region ends
/// at a constructor step of a recursive type whose field holds the type
/// only through a type parameter (`Dict`'s values): below that is another
/// value of the type, `Dict String (Dict …)`'s inner dictionaries, not a
/// level of this one.
fn regionOf(o: *Ownership, parent: u32, ty: u64) Allocator.Error!?Region {
    // Root first.
    const chain: []const u32 = if (parent == none) &.{} else o.pathNodes(parent);
    var region: ?Region = null;
    for (chain) |node| {
        switch (o.paths.kind.items[node]) {
            .ctor => {
                const t = o.ctorType(o.stepCtor(o.paths.arg.items[node])) orelse continue;
                if (t != ty) continue;
                if (try o.typeRecursive(ty) and try o.levelOf(o.paths.arg.items[node]) == .none) {
                    region = null;
                } else if (region == null) region = .{ .first = node };
            },
            .level => if (o.markerType(o.paths.arg.items[node]) == ty) {
                region = .{ .marker = node };
            },
            .env => if (ty == fn_type and region == null) {
                region = .{ .first = node };
            },
            // §16.7 (c), the manager's decision on #853: a recursive type's
            // region goes on across a cast, so a `T` read through a cast below
            // a `T` folds into the region. A closure's region still ends there.
            .cast, .cast_level => if (ty == fn_type) {
                region = null;
            },
            else => {},
        }
    }
    return region;
}

/// The marker of a region: the one it has, or one under its first step.
/// A marker asked for where the region has one already folds onto that one,
/// whatever kind was asked for: the places it stands for only grow, which is
/// sound for every fact, if coarser (`child`'s `.level` case).
fn markerOf(o: *Ownership, r: Region, ty: u64) Allocator.Error!u32 {
    return switch (r) {
        .marker => |m| m,
        // An environment may be a closure (one captured directly: `◇◇q`)
        // or hold closures further down (`◇p◇q`), so F1's marker stands
        // where the value may be either.
        .first => |f| o.rawChild(f, .level, try o.markerId(ty, if (ty == fn_type) .maybe else if (try o.levelOf(o.paths.arg.items[f]) == .below) .below else .at)),
    };
}

/// §16.7 (#820): the marker a region takes at `parent`: its own, or a new
/// one at `parent` when `parent` is one of the first step's anchors, where
/// the value is a `T`; else one under the first step (`markerOf`).
fn markerAt(o: *Ownership, r: Region, ty: u64, parent: u32) Allocator.Error!u32 {
    switch (r) {
        .marker => |m| return m,
        .first => |f| if (ty != fn_type and try o.anchoredAt(f, parent)) return o.rawChild(parent, .level, try o.markerId(ty, .at)),
    }
    return o.markerOf(r, ty);
}

/// F1's recursive type: every function type, whose one region step is `◇`.
pub const fn_type: u64 = std.math.maxInt(u64);

/// Where a marker stands (§16.7): where the value is a `T`, where it is
/// not (a field whose `T`s are further down), or where a projection took
/// it and the value may be either; or, `under`, at a `T` and for the
/// `T`s strictly below it, the canonical form of every region but not the
/// root (§16.7).
pub const MarkerKind = enum(u8) { at, below, maybe, under };

/// The step argument of the marker `⟨T⟩` for the type `(module,
/// declaration)` and where it stands.
pub fn markerId(o: *Ownership, ty: u64, kind: MarkerKind) Allocator.Error!u32 {
    const gop = try o.marker_ids.getOrPut(o.in.gpa, .{ ty, kind });
    if (!gop.found_existing) {
        gop.value_ptr.* = @intCast(o.marker_types.items.len);
        try o.marker_types.append(o.in.gpa, ty);
        try o.marker_kind.append(o.in.gpa, kind);
    }
    return gop.value_ptr.*;
}

pub fn markerKind(o: *const Ownership, arg: u32) MarkerKind {
    return o.marker_kind.items[arg];
}

/// Whether a marker's expansion may begin with any step: it may stand
/// where the value is not a `T`.
fn markerAny(o: *const Ownership, arg: u32) bool {
    return switch (o.marker_kind.items[arg]) {
        .below, .maybe => true,
        .at, .under => false,
    };
}

/// Whether a marker's expansion may be empty: it may stand at a `T`.
fn markerEmpty(o: *const Ownership, arg: u32) bool {
    return switch (o.marker_kind.items[arg]) {
        .at, .maybe => true,
        .below, .under => false,
    };
}

/// The type a marker step names.
pub fn markerType(o: *const Ownership, arg: u32) u64 {
    return o.marker_types.items[arg];
}

/// Whether `p` names a representative place (thesis §3.1, §3.11): one that
/// stands for many run-time places — a list's elements, or the levels a
/// region's marker merged (§16.7). A demand there, or a holder there, is an
/// approximate fact. A level's own field (`#Node.1`) is one place.
fn representative(o: *Ownership, p: u32) Allocator.Error!bool {
    return o.paths.representative.items[p];
}

/// Whether a path goes through core Dict's recursive tree (§20.8).
fn dictTreePath(o: *Ownership, p: u32) Allocator.Error!bool {
    var at = p;
    while (at != eps and at != none) : (at = o.paths.parent.items[at]) {
        if (o.paths.kind.items[at] != .ctor) continue;
        const t = o.ctorType(o.stepCtor(o.paths.arg.items[at])) orelse continue;
        if (try o.dictTree(t)) return true;
    }
    return false;
}

/// Whether `t` is core Dict's recursive tree (§20.8).
fn dictTree(o: *Ownership, t: u64) Allocator.Error!bool {
    const m: u32 = @intCast(t >> 32);
    if (m >= o.in.packages.len or o.in.packages[m] != .core or !std.mem.eql(u8, o.in.module_names[m], "Dict")) return false;
    return o.typeRecursive(t);
}

/// Whether the type `(module, declaration)` reaches itself through its own
/// definition.
fn typeRecursive(o: *Ownership, key: u64) Allocator.Error!bool {
    if (o.recursive_types.get(key)) |r| return r;
    var seen: std.AutoHashMapUnmanaged(u64, void) = .empty;
    defer seen.deinit(o.in.gpa);
    var work: std.ArrayList(u64) = .empty;
    defer work.deinit(o.in.gpa);
    try o.typeHeads(key, &work);
    var found = false;
    while (work.pop()) |k| {
        if (k == key) {
            found = true;
            break;
        }
        const gop = try seen.getOrPut(o.in.gpa, k);
        if (gop.found_existing) continue;
        try o.typeHeads(k, &work);
    }
    try o.recursive_types.put(o.in.gpa, key, found);
    return found;
}

/// The types a type's definition names directly.
fn typeHeads(o: *Ownership, key: u64, out: *std.ArrayList(u64)) Allocator.Error!void {
    if (o.schemaKeyOf(key)) |sk| return o.schemaHeads(sk, out);
    const m: u32 = @intCast(key >> 32);
    const d: u32 = @truncate(key);
    if (m >= o.in.birs.len) return;
    const bir = o.in.birs[m];
    if (d >= bir.decls.len) return;
    const decl = bir.decls[d];
    switch (decl.kind) {
        .type => for (bir.declCtors(decl)) |c| {
            for (bir.extraSlice(.{ .start = c.args_start, .end = c.args_end }, Inst.Index)) |arg| try o.typeExprHeads(m, bir, arg, out, 0);
        },
        .type_alias => if (decl.annotation.unwrap()) |body| try o.typeExprHeads(m, bir, body, out, 0),
        else => {},
    }
}

fn typeExprHeads(o: *Ownership, m: u32, bir: *const Bir, inst: Inst.Index, out: *std.ArrayList(u64), depth: u32) Allocator.Error!void {
    if (depth > type_depth) return;
    const tag = bir.instTag(inst);
    const data = bir.instData(inst);
    const graph_m: Graph.Index = @fromBackingInt(@intCast(m));
    switch (tag) {
        .type_tuple => for (bir.extraSlice(Bir.inlineRange(data), Inst.Index)) |el| try o.typeExprHeads(m, bir, el, out, depth + 1),
        .type_record => for (bir.extraSlice(Bir.inlineRange(data), Bir.Field)) |fl| try o.typeExprHeads(m, bir, fl.value, out, depth + 1),
        .type_record_ext => for (bir.extraSlice(bir.subRange(@fromBackingInt(@intCast(data.rhs))), Bir.Field)) |fl| try o.typeExprHeads(m, bir, fl.value, out, depth + 1),
        .type_top, .ext_type, .schema_type_top, .ext_schema_type => try o.pushHead(o.in.types.headId(graph_m, tag, data), out),
        .type_app => {
            const head: Inst.Index = @fromBackingInt(@intCast(data.lhs));
            try o.pushHead(o.in.types.headId(graph_m, bir.instTag(head), bir.instData(head)), out);
            for (bir.extraSlice(bir.subRange(@fromBackingInt(@intCast(data.rhs))), Inst.Index)) |arg| try o.typeExprHeads(m, bir, arg, out, depth + 1);
        },
        else => {},
    }
}

fn pushHead(o: *Ownership, id: TypeId, out: *std.ArrayList(u64)) Allocator.Error!void {
    if (id == .none or id.int() >= o.in.types.entries.len) return;
    try out.append(o.in.gpa, o.entryKey(id));
}

/// §16.7 (#820): a type key's endpoint bit. A native schema declares two
/// types, its `Type` and its `Encoded` endpoint (`Types.zig`), each a type
/// of its own: `(module, declaration)` is the first, and the declaration
/// with this bit the second. No declaration index reaches the bit.
pub const encoded_bit: u32 = 1 << 31;

/// The type key of type `id`: its declaration, with the endpoint bit for a
/// schema's `Encoded`.
fn entryKey(o: *const Ownership, id: TypeId) u64 {
    const e = o.in.types.entries[id.int()];
    var d: u32 = e.decl.int();
    if (e.schema_endpoint and o.in.types.ofSchemaDecl(e.module, e.decl, .encoded) == id) d |= encoded_bit;
    return (@as(u64, e.module.int()) << 32) | d;
}

/// A schema endpoint's type key, taken apart.
pub const SchemaKey = struct { m: u32, decl: u32, encoded: bool };

/// The schema endpoint a type key names, or null for any other type.
pub fn schemaKeyOf(o: *const Ownership, key: u64) ?SchemaKey {
    if (key == fn_type) return null;
    const m: u32 = @intCast(key >> 32);
    const raw: u32 = @truncate(key);
    const d = raw & ~encoded_bit;
    if (m >= o.in.birs.len or d >= o.in.birs[m].decls.len) return null;
    if (o.in.birs[m].decls[d].kind != .schema) return null;
    return .{ .m = m, .decl = d, .encoded = raw & encoded_bit != 0 };
}

fn schemaKey(m: u32, d: u32, encoded: bool) u64 {
    return (@as(u64, m) << 32) | d | (if (encoded) encoded_bit else 0);
}

/// The schema declaration and endpoint a schema constructor index of module
/// `m` (after the BIR's own constructors, `schemaCtorBases`) belongs to,
/// and its variant.
fn schemaCtorOwner(o: *Ownership, m: u32, index: u32) Allocator.Error!?struct { decl: u32, encoded: bool, variant: u32 } {
    const bir = o.in.birs[m];
    if (index < bir.ctors.len) return null;
    const k = index - @as(u32, @intCast(bir.ctors.len));
    const bases = try o.schemaCtorBases(m);
    for (0..bir.decls.len) |di| {
        if (k < bases[di] or k >= bases[di + 1]) continue;
        const count = (bases[di + 1] - bases[di]) / 2;
        const at = k - bases[di];
        return .{ .decl = @intCast(di), .encoded = at >= count, .variant = at % count };
    }
    return null;
}

/// The plan node of a tagged schema's variants, below the annotations and
/// checks its root may carry.
fn taggedNode(plan: *const SchemaPlan, root: SchemaPlan.NodeIndex) ?SchemaPlan.NodeIndex {
    var at = root;
    var budget = plan.nodes.len + 1;
    while (budget > 0 and @backingInt(at) < plan.nodes.len) : (budget -= 1) switch (SchemaGraph.tag(plan, at)) {
        .tagged => return at,
        .annotation, .check => at = @fromBackingInt(@intCast(SchemaGraph.lhs(plan, at))),
        else => return null,
    };
    return null;
}

/// §16.7 (#820): the types a schema endpoint's definition names: the same
/// endpoint of every schema it references, the nominal types its derived
/// codecs build, and the types a conversion's target names. A reference
/// cycle stays inside one module and one endpoint (`SchemaGraph.inCycle`).
fn schemaHeads(o: *Ownership, sk: SchemaKey, out: *std.ArrayList(u64)) Allocator.Error!void {
    const sg = o.schemaGraph();
    const gm: Graph.Index = @fromBackingInt(@intCast(sk.m));
    const def = sg.definition(gm, sk.decl) orelse return;
    const plan = sg.planOf(gm);
    var nodes: std.ArrayList(SchemaPlan.NodeIndex) = .empty;
    defer nodes.deinit(o.in.gpa);
    try SchemaGraph.subtree(plan, o.in.gpa, def.root, &nodes);
    // The derived codecs walked: a module has few.
    var codecs: std.ArrayList(u32) = .empty;
    defer codecs.deinit(o.in.gpa);
    var i: usize = 0;
    while (i < nodes.items.len) : (i += 1) {
        const n = nodes.items[i];
        switch (SchemaGraph.tag(plan, n)) {
            .reference => if (sg.target(gm, @fromBackingInt(SchemaGraph.lhs(plan, n)))) |t| {
                try out.append(o.in.gpa, schemaKey(t.module.int(), t.decl, sk.encoded));
            },
            .constructors => {
                const ti = SchemaGraph.lhs(plan, n);
                if (ti < plan.type_targets.len) {
                    const tt = plan.type_targets[ti];
                    const id = o.in.types.find(o.in.graph, tt.package, SchemaGraph.symbol(plan, tt.module), SchemaGraph.symbol(plan, tt.name));
                    if (id != .none) try o.pushHead(id, out);
                }
            },
            .conversion => {
                const ci = SchemaGraph.rhs(plan, n);
                if (ci < plan.conversions.len) try o.termHeads(plan, plan.conversions[ci].target_term, out, 0);
            },
            // A derived codec of this module: its nodes are this walk's too.
            .codec_ref => {
                const t = sg.codecTarget(gm, SchemaGraph.lhs(plan, n));
                if (std.mem.indexOfScalar(u32, codecs.items, t.decl) != null) continue;
                try codecs.append(o.in.gpa, t.decl);
                const cd = sg.definition(gm, t.decl) orelse continue;
                try SchemaGraph.subtree(plan, o.in.gpa, cd.root, &nodes);
            },
            else => {},
        }
    }
}

/// The nominal types a plan's type term names.
fn termHeads(o: *Ownership, plan: *const SchemaPlan, ti: Interface.TermIndex, out: *std.ArrayList(u64), depth: u32) Allocator.Error!void {
    if (depth > type_depth or ti == .none or ti.int() >= plan.terms.len) return;
    var view = Interface.empty;
    view.terms = plan.terms;
    view.extra = plan.type_extra;
    view.type_refs = plan.type_refs;
    view.symbols = plan.symbols;
    const t = view.term(ti);
    switch (t.tag) {
        .app, .alias => {
            if (t.lhs >= view.type_refs.len) return;
            const ref = view.type_refs[t.lhs];
            for (view.range(t.rhs)) |word| try o.termHeads(plan, @fromBackingInt(word), out, depth + 1);
            if (t.tag == .alias) return o.termHeads(plan, ref.body, out, depth + 1);
            const id = o.in.types.find(o.in.graph, ref.package, view.symbol(ref.module), view.symbol(ref.name));
            if (id != .none) try o.pushHead(id, out);
        },
        .tuple, .func => {
            for (view.range(t.lhs)) |word| try o.termHeads(plan, @fromBackingInt(word), out, depth + 1);
            if (t.tag == .func) try o.termHeads(plan, @fromBackingInt(t.rhs), out, depth + 1);
        },
        .record => {
            const words = view.range(t.lhs);
            var k: usize = 1;
            while (k < words.len) : (k += 2) try o.termHeads(plan, @fromBackingInt(words[k]), out, depth + 1);
            try o.termHeads(plan, @fromBackingInt(t.rhs), out, depth + 1);
        },
        else => {},
    }
}

/// `levelOf` for a schema constructor: field 0, its payload, holds a value
/// of the endpoint type `t` at the field itself when the payload is a
/// reference to the schema, further down when its nodes reach it, and
/// nowhere when they do not. `typed`: only through what the plan writes
/// (records, lists, tuples, references), as `typedLevel` reads a type.
fn schemaCtorLevel(o: *Ownership, m: u32, index: u32, field: u32, t: u64, typed: bool) Allocator.Error!Level {
    const owner = (try o.schemaCtorOwner(m, index)) orelse return .below;
    if (field != 0) return .none;
    const sg = o.schemaGraph();
    const gm: Graph.Index = @fromBackingInt(@intCast(m));
    const def = sg.definition(gm, owner.decl) orelse return .below;
    const plan = sg.planOf(gm);
    const tagged = taggedNode(plan, def.root) orelse return .below;
    const vs = SchemaGraph.variants(plan, tagged);
    if (owner.variant >= vs.len or vs[owner.variant] >= plan.variants.len) return .below;
    const payload = plan.variants[vs[owner.variant]].payload.unwrap() orelse return .none;
    var seen: std.AutoHashMapUnmanaged(u64, void) = .empty;
    defer seen.deinit(o.in.gpa);
    return o.planLevel(gm, payload, t, owner.encoded, typed, &seen);
}

/// `exprLevel` for a schema plan's node of module `gm`, the endpoint
/// `encoded` read: a parameter is no level (folding never goes through
/// one), and what the walk cannot read (a conversion, a derived codec, a
/// module's `codec`) may hold `t` anywhere below, unless `typed`.
fn planLevel(o: *Ownership, gm: Graph.Index, n: SchemaPlan.NodeIndex, t: u64, encoded: bool, typed: bool, seen: *std.AutoHashMapUnmanaged(u64, void)) Allocator.Error!Level {
    const sg = o.schemaGraph();
    const plan = sg.planOf(gm);
    if (@backingInt(n) >= plan.nodes.len) return .below;
    const below = struct {
        fn f(oo: *Ownership, g: Graph.Index, kids: []const u32, tt: u64, enc: bool, ty: bool, s: *std.AutoHashMapUnmanaged(u64, void)) Allocator.Error!Level {
            for (kids) |kid| if (try oo.planLevel(g, @fromBackingInt(kid), tt, enc, ty, s) != .none) return .below;
            return .none;
        }
    }.f;
    switch (SchemaGraph.tag(plan, n)) {
        .parameter, .primitive => return .none,
        .reference => {
            const target = sg.target(gm, @fromBackingInt(SchemaGraph.lhs(plan, n))) orelse return if (typed) .none else .below;
            const key = schemaKey(target.module.int(), target.decl, encoded);
            if (key == t) return .here;
            if (try below(o, gm, SchemaGraph.args(plan, n), t, encoded, typed, seen) != .none) return .below;
            if ((try seen.getOrPut(o.in.gpa, key)).found_existing) return .none;
            const def = sg.definition(target.module, target.decl) orelse return if (typed) .none else .below;
            return if (try o.planLevel(target.module, def.root, t, encoded, typed, seen) != .none) .below else .none;
        },
        .record => {
            for (SchemaGraph.fields(plan, n)) |f| if (try o.planLevel(gm, f.child, t, encoded, typed, seen) != .none) return .below;
            return .none;
        },
        .tagged => {
            for (SchemaGraph.variants(plan, n)) |vi| {
                if (vi >= plan.variants.len) continue;
                const p = plan.variants[vi].payload.unwrap() orelse continue;
                if (try o.planLevel(gm, p, t, encoded, typed, seen) != .none) return .below;
            }
            return .none;
        },
        .list, .nullable, .maybe, .check, .annotation => {
            const inner: SchemaPlan.NodeIndex = @fromBackingInt(SchemaGraph.lhs(plan, n));
            return if (try o.planLevel(gm, inner, t, encoded, typed, seen) != .none) .below else .none;
        },
        .tuple => return below(o, gm, SchemaGraph.elements(plan, n), t, encoded, typed, seen),
        .conversion, .constructors, .codec_ref, .codec_value => return if (typed) .none else .below,
    }
}

/// Where, below a constructor step `#C.i` of a recursive type `T`, a value
/// of `T` may sit (§16.7, *Amended 2026-10-17: a projection keeps the levels
/// folding merged*): nowhere, at the field itself (`Node Tree …`'s
/// `#Node.0`), or somewhere further down (`List Tree`, `Maybe Tree`, a
/// function's captures, a `foreign type`). A field that holds `T` only
/// through a type parameter is nowhere: folding does not go through it.
const Level = enum { unknown, none, here, below };

fn levelOf(o: *Ownership, arg: u32) Allocator.Error!Level {
    if (arg < o.level_of.items.len and o.level_of.items[arg] != .unknown) return o.level_of.items[arg];
    const c = o.stepCtor(arg);
    const field = o.stepField(arg);
    const l: Level = blk: {
        const t = o.ctorType(c) orelse break :blk .none;
        if (!try o.typeRecursive(t)) break :blk .none;
        const key = o.ctorKey(c);
        const bir = o.in.birs[key.module];
        if (key.index >= bir.ctors.len) break :blk try o.schemaCtorLevel(key.module, key.index, field, t, false);
        const ct = bir.ctors[key.index];
        const args = bir.extraSlice(.{ .start = ct.args_start, .end = ct.args_end }, Inst.Index);
        if (field >= args.len) break :blk .below;
        var seen: std.AutoHashMapUnmanaged(u64, void) = .empty;
        defer seen.deinit(o.in.gpa);
        break :blk try o.exprLevel(key.module, bir, args[field], t, &seen, false);
    };
    if (arg >= o.level_of.items.len) try o.level_of.appendNTimes(o.in.gpa, .unknown, arg + 1 - o.level_of.items.len);
    o.level_of.items[arg] = l;
    return l;
}

/// `levelOf` for a type written in module `m`'s declarations. `typed`:
/// only where the type is written, not through a closure's captures, a
/// `foreign type` or a schema's slots, which a path reaches only by a cast.
fn exprLevel(o: *Ownership, m: u32, bir: *const Bir, inst: Inst.Index, t: u64, seen: *std.AutoHashMapUnmanaged(u64, void), typed: bool) Allocator.Error!Level {
    const tag = bir.instTag(inst);
    const data = bir.instData(inst);
    const graph_m: Graph.Index = @fromBackingInt(@intCast(m));
    switch (tag) {
        .type_unit => return .none,
        // What a closure's captures hold is not written here. A type
        // variable is no level: folding never goes through one (`foldAt`),
        // and one of a body read below is an argument, looked at where it
        // is written.
        .type_fn => return if (typed) .none else .below,
        .type_var => return .none,
        .type_tuple => {
            for (bir.extraSlice(Bir.inlineRange(data), Inst.Index)) |el| if (try o.exprLevel(m, bir, el, t, seen, typed) != .none) return .below;
            return .none;
        },
        .type_record => {
            for (bir.extraSlice(Bir.inlineRange(data), Bir.Field)) |fl| if (try o.exprLevel(m, bir, fl.value, t, seen, typed) != .none) return .below;
            return .none;
        },
        .type_top, .ext_type, .schema_type_top, .ext_schema_type, .type_app => {
            const id = if (tag == .type_app) blk: {
                const head: Inst.Index = @fromBackingInt(@intCast(data.lhs));
                break :blk o.in.types.headId(graph_m, bir.instTag(head), bir.instData(head));
            } else o.in.types.headId(graph_m, tag, data);
            if (id == .none or id.int() >= o.in.types.entries.len) return .below;
            const e = o.in.types.entries[id.int()];
            const key = o.entryKey(id);
            if (key == t) return .here;
            // A `foreign type`'s arguments are not where a path goes, but
            // a `List`'s elements are.
            if (typed and e.kind == .foreign and id != o.in.types.well_known.list) return .none;
            if (tag == .type_app) {
                for (bir.extraSlice(bir.subRange(@fromBackingInt(@intCast(data.rhs))), Inst.Index)) |arg| {
                    if (try o.exprLevel(m, bir, arg, t, seen, typed) != .none) return .below;
                }
            }
            if (id == o.in.types.well_known.list or o.isPrimitive(id)) return .none;
            // §16.7 (#820): a schema endpoint is read off its plan.
            if (e.schema_endpoint) {
                const sk = o.schemaKeyOf(key) orelse return if (typed) .none else .below;
                if ((try seen.getOrPut(o.in.gpa, key)).found_existing) return .none;
                const gm: Graph.Index = @fromBackingInt(@intCast(sk.m));
                const def = o.schemaGraph().definition(gm, sk.decl) orelse return if (typed) .none else .below;
                return if (try o.planLevel(gm, def.root, t, sk.encoded, typed, seen) != .none) .below else .none;
            }
            switch (e.kind) {
                .foreign => return if (!typed and (try o.nominalFacts(id)).own) .below else .none,
                .alias, .adt => {},
            }
            const gop = try seen.getOrPut(o.in.gpa, key);
            if (gop.found_existing) return .none;
            const dm = e.module.int();
            const dbir = o.in.birs[dm];
            const d = dbir.decl(e.decl);
            if (e.kind == .alias) {
                const body = d.annotation.unwrap() orelse return .below;
                return o.exprLevel(dm, dbir, body, t, seen, typed);
            }
            for (dbir.declCtors(d)) |ct| for (dbir.extraSlice(.{ .start = ct.args_start, .end = ct.args_end }, Inst.Index)) |arg| {
                if (try o.exprLevel(dm, dbir, arg, t, seen, typed) != .none) return .below;
            };
            return .none;
        },
        else => return .below,
    }
}

/// §16.7 (#820, *a marker stands where its type is*): the positions below a
/// constructor field step `arg` of a recursive type `T` where a value of `T`
/// sits at the end of a written path of record fields and tuple slots:
/// `.next` below `Link { next : Chain, tags : List Int }`'s payload. The
/// region's marker stands there, at a `T`, so `tags` is not one of the
/// places it stands for. `other`: the field may hold `T` some other way too
/// (a list's elements, another type's constructor, a closure, a type
/// argument), and a marker for those `T`s stands at the field, below it, as
/// before. A field that is a `T` itself has no anchor: its marker stands at
/// the field, which is a `T`.
pub const Anchors = struct { paths: []const []const Step = &.{}, other: bool = false };

fn anchorsOf(o: *Ownership, arg: u32) Allocator.Error!Anchors {
    if (arg < o.anchors_of.items.len) if (o.anchors_of.items[arg]) |a| return a;
    var out: std.ArrayList([]const Step) = .empty;
    var other = false;
    blk: {
        const c = o.stepCtor(arg);
        const t = o.ctorType(c) orelse break :blk;
        if (try o.levelOf(arg) != .below) break :blk;
        const key = o.ctorKey(c);
        const bir = o.in.birs[key.module];
        if (key.index >= bir.ctors.len) {
            try o.schemaAnchors(key.module, key.index, o.stepField(arg), t, &out, &other);
            break :blk;
        }
        const ct = bir.ctors[key.index];
        const args = bir.extraSlice(.{ .start = ct.args_start, .end = ct.args_end }, Inst.Index);
        const field = o.stepField(arg);
        if (field >= args.len) {
            other = true;
            break :blk;
        }
        try o.exprAnchors(key.module, bir, args[field], t, &.{}, &out, &other, 0);
        if (out.items.len == 0) other = true;
    }
    const a: Anchors = .{ .paths = out.items, .other = other };
    if (arg >= o.anchors_of.items.len) try o.anchors_of.appendNTimes(o.in.gpa, null, arg + 1 - o.anchors_of.items.len);
    o.anchors_of.items[arg] = a;
    return a;
}

/// `anchorsOf` for a type written in module `m`'s declarations, at `prefix`
/// below the field.
fn exprAnchors(o: *Ownership, m: u32, bir: *const Bir, inst: Inst.Index, t: u64, prefix: []const Step, out: *std.ArrayList([]const Step), other: *bool, depth: u32) Allocator.Error!void {
    if (depth > type_depth) {
        other.* = true;
        return;
    }
    const keep = o.keep.allocator();
    const tag = bir.instTag(inst);
    const data = bir.instData(inst);
    const graph_m: Graph.Index = @fromBackingInt(@intCast(m));
    switch (tag) {
        .type_unit, .type_var => {},
        .type_record => for (bir.extraSlice(Bir.inlineRange(data), Bir.Field)) |fl| {
            const s: Step = .{ .kind = .field, .arg = @backingInt(bir.symbol(fl.name)) };
            try o.exprAnchors(m, bir, fl.value, t, try std.mem.concat(keep, Step, &.{ prefix, &.{s} }), out, other, depth + 1);
        },
        .type_tuple => for (bir.extraSlice(Bir.inlineRange(data), Inst.Index), 0..) |el, i| {
            const s: Step = .{ .kind = .tuple, .arg = @intCast(i) };
            try o.exprAnchors(m, bir, el, t, try std.mem.concat(keep, Step, &.{ prefix, &.{s} }), out, other, depth + 1);
        },
        .type_top, .ext_type, .schema_type_top, .ext_schema_type, .type_app => {
            const id = if (tag == .type_app) blk: {
                const head: Inst.Index = @fromBackingInt(@intCast(data.lhs));
                break :blk o.in.types.headId(graph_m, bir.instTag(head), bir.instData(head));
            } else o.in.types.headId(graph_m, tag, data);
            if (id != .none and id.int() < o.in.types.entries.len) {
                const e = o.in.types.entries[id.int()];
                if (o.entryKey(id) == t) {
                    if (prefix.len > 0) try out.append(o.keep.allocator(), prefix) else other.* = true;
                    return;
                }
                // A list's elements are written: `[*]`.
                if (id == o.in.types.well_known.list and tag == .type_app) {
                    const xs = bir.extraSlice(bir.subRange(@fromBackingInt(@intCast(data.rhs))), Inst.Index);
                    if (xs.len == 1) return o.exprAnchors(m, bir, xs[0], t, try std.mem.concat(keep, Step, &.{ prefix, &.{.{ .kind = .elem, .arg = 0 }} }), out, other, depth + 1);
                }
                // An alias with no parameters is its body, written elsewhere.
                if (e.kind == .alias and !e.schema_endpoint and tag != .type_app) {
                    const dbir = o.in.birs[e.module.int()];
                    if (dbir.decl(e.decl).annotation.unwrap()) |body| return o.exprAnchors(e.module.int(), dbir, body, t, prefix, out, other, depth + 1);
                }
            }
            var seen: std.AutoHashMapUnmanaged(u64, void) = .empty;
            defer seen.deinit(o.in.gpa);
            if (try o.exprLevel(m, bir, inst, t, &seen, false) != .none) other.* = true;
        },
        else => {
            var seen: std.AutoHashMapUnmanaged(u64, void) = .empty;
            defer seen.deinit(o.in.gpa);
            if (try o.exprLevel(m, bir, inst, t, &seen, false) != .none) other.* = true;
        },
    }
}

/// `anchorsOf` for a native schema's constructor: its payload's record
/// fields and tuple slots, read off the plan.
fn schemaAnchors(o: *Ownership, m: u32, index: u32, field: u32, t: u64, out: *std.ArrayList([]const Step), other: *bool) Allocator.Error!void {
    const owner = (try o.schemaCtorOwner(m, index)) orelse {
        other.* = true;
        return;
    };
    if (field != 0) return;
    const sg = o.schemaGraph();
    const gm: Graph.Index = @fromBackingInt(@intCast(m));
    const def = sg.definition(gm, owner.decl) orelse {
        other.* = true;
        return;
    };
    const plan = sg.planOf(gm);
    const tagged = taggedNode(plan, def.root) orelse {
        other.* = true;
        return;
    };
    const vs = SchemaGraph.variants(plan, tagged);
    if (owner.variant >= vs.len or vs[owner.variant] >= plan.variants.len) {
        other.* = true;
        return;
    }
    const payload = plan.variants[vs[owner.variant]].payload.unwrap() orelse return;
    try o.planAnchors(gm, payload, t, owner.encoded, &.{}, out, other, 0);
    if (out.items.len == 0) other.* = true;
}

fn planAnchors(o: *Ownership, gm: Graph.Index, n: SchemaPlan.NodeIndex, t: u64, encoded: bool, prefix: []const Step, out: *std.ArrayList([]const Step), other: *bool, depth: u32) Allocator.Error!void {
    const sg = o.schemaGraph();
    const plan = sg.planOf(gm);
    if (depth > type_depth or @backingInt(n) >= plan.nodes.len) {
        other.* = true;
        return;
    }
    const keep = o.keep.allocator();
    switch (SchemaGraph.tag(plan, n)) {
        .record => for (SchemaGraph.fields(plan, n)) |f| {
            const s: Step = .{ .kind = .field, .arg = @backingInt(SchemaGraph.symbol(plan, f.name)) };
            try o.planAnchors(gm, f.child, t, encoded, try std.mem.concat(keep, Step, &.{ prefix, &.{s} }), out, other, depth + 1);
        },
        .tuple => for (SchemaGraph.elements(plan, n), 0..) |el, i| {
            const s: Step = .{ .kind = .tuple, .arg = @intCast(i) };
            try o.planAnchors(gm, @fromBackingInt(el), t, encoded, try std.mem.concat(keep, Step, &.{ prefix, &.{s} }), out, other, depth + 1);
        },
        .list => try o.planAnchors(gm, @fromBackingInt(SchemaGraph.lhs(plan, n)), t, encoded, try std.mem.concat(keep, Step, &.{ prefix, &.{.{ .kind = .elem, .arg = 0 }} }), out, other, depth + 1),
        // The same value, checked or annotated.
        .check, .annotation => try o.planAnchors(gm, @fromBackingInt(SchemaGraph.lhs(plan, n)), t, encoded, prefix, out, other, depth + 1),
        .reference => if (sg.target(gm, @fromBackingInt(SchemaGraph.lhs(plan, n)))) |target| {
            if (schemaKey(target.module.int(), target.decl, encoded) == t) {
                if (prefix.len > 0) try out.append(o.keep.allocator(), prefix) else other.* = true;
                return;
            }
            var seen: std.AutoHashMapUnmanaged(u64, void) = .empty;
            defer seen.deinit(o.in.gpa);
            if (try o.planLevel(gm, n, t, encoded, false, &seen) != .none) other.* = true;
        } else {
            other.* = true;
        },
        else => {
            var seen: std.AutoHashMapUnmanaged(u64, void) = .empty;
            defer seen.deinit(o.in.gpa);
            if (try o.planLevel(gm, n, t, encoded, false, &seen) != .none) other.* = true;
        },
    }
}

/// Whether `parent`, a position below the region's first step `f`, is one
/// of `f`'s anchors: the marker of the region then stands at `parent`.
fn anchoredAt(o: *Ownership, f: u32, parent: u32) Allocator.Error!bool {
    if (parent == f or o.paths.kind.items[f] != .ctor) return false;
    const fd = o.paths.depth.items[f];
    const pd = o.paths.depth.items[parent];
    if (pd <= fd) return false;
    const a = try o.anchorsOf(o.paths.arg.items[f]);
    if (a.paths.len == 0) return false;
    const st = o.steps(parent);
    const q = st[fd..];
    // `parent` is below `f` itself, not below another path of its depth.
    var at = parent;
    while (o.paths.depth.items[at] > fd) at = o.paths.parent.items[at];
    if (at != f) return false;
    for (a.paths) |p| {
        if (p.len != q.len) continue;
        for (p, q) |x, y| {
            if (x.kind != y.kind or x.arg != y.arg) break;
        } else return true;
    }
    return false;
}

fn ctorType(o: *const Ownership, c: u32) ?u64 {
    if (c >= o.ctor_type.items.len) return null;
    const t = o.ctor_type.items[c];
    return if (t == std.math.maxInt(u64)) null else t;
}

pub fn rawChild(o: *Ownership, parent: u32, kind: StepKind, arg: u32) Allocator.Error!u32 {
    const key: [3]u32 = .{ parent, @backingInt(kind), arg };
    const gop = try o.paths.map.getOrPut(o.in.gpa, key);
    if (gop.found_existing) return gop.value_ptr.*;
    const id: u32 = @intCast(o.paths.parent.items.len);
    gop.value_ptr.* = id;
    try o.paths.parent.append(o.in.gpa, parent);
    try o.paths.kind.append(o.in.gpa, kind);
    try o.paths.arg.append(o.in.gpa, arg);
    // §16.7 (c): no cut. A growth mark holds a depth in 30 bits; a path that
    // deep would hold 2³⁰ steps in `steps_of` alone, more than memory.
    std.debug.assert(o.paths.depth.items[parent] < std.math.maxInt(u30) - 1);
    try o.paths.depth.append(o.in.gpa, o.paths.depth.items[parent] + 1);
    {
        const keep = o.keep.allocator();
        const pd = o.paths.depth.items[parent];
        const ns = try keep.alloc(u32, pd + 1);
        @memcpy(ns[0..pd], o.paths.nodes_of.items[parent]);
        ns[pd] = id;
        const ss = try keep.alloc(Step, pd + 1);
        @memcpy(ss[0..pd], o.paths.steps_of.items[parent]);
        ss[pd] = .{ .kind = kind, .arg = arg };
        try o.paths.nodes_of.append(o.in.gpa, ns);
        try o.paths.steps_of.append(o.in.gpa, ss);
    }
    try o.paths.rest.append(o.in.gpa, none);
    // A marker is compared step by step (§16.7, *Overlap*).
    const uncertain = kind == .cast and o.cast_wild.items[arg];
    try o.paths.any.append(o.in.gpa, o.paths.any.items[parent] or kind == .any or kind == .level or kind == .cast_level or uncertain);
    try o.paths.casts.append(o.in.gpa, o.paths.casts.items[parent] or kind == .cast or kind == .cast_level);
    try o.paths.holds.append(o.in.gpa, kind == .ctor and try o.levelOf(arg) != .none);
    const dict = if (kind == .ctor) if (o.ctorType(o.stepCtor(arg))) |t| try o.dictTree(t) else false else false;
    try o.paths.representative.append(o.in.gpa, o.paths.representative.items[parent] or kind == .elem or kind == .level or kind == .cast_level or uncertain or dict);
    return id;
}

pub const Step = struct { kind: StepKind, arg: u32 };

/// The steps of `p`, root first: kept for the run, so they stay valid
/// while more paths are made.
pub fn steps(o: *const Ownership, p: u32) []const Step {
    return o.paths.steps_of.items[p];
}

/// `s` followed by `p`'s steps.
fn prepend(o: *Ownership, s: Step, p: u32) Allocator.Error!u32 {
    const rest = o.steps(p);
    var at = try o.child(eps, s.kind, s.arg);
    for (rest) |r| at = try o.child(at, r.kind, r.arg);
    return at;
}

/// §16.7 (d): the fresh number of declaration `(m, d)` for the result paths
/// `ps` (each `path * 2 + approx`, then the escape bit). Numbers are given in
/// the order the rounds first meet a set of paths, so they are a function of
/// the program, and one set has one number in every round.
fn freshKey(o: *Ownership, m: u32, d: u32, ps: []const u32) Allocator.Error!u32 {
    const keep = o.keep.allocator();
    const key = try keep.alloc(u32, ps.len + 2);
    key[0] = m;
    key[1] = d;
    @memcpy(key[2..], ps);
    const gop = try o.fresh_keys.getOrPut(o.in.gpa, key);
    if (gop.found_existing) {
        keep.free(key);
        return gop.value_ptr.*;
    }
    const count = try o.fresh_count.getOrPut(o.in.gpa, (@as(u64, m) << 32) | d);
    if (!count.found_existing) count.value_ptr.* = 0;
    count.value_ptr.* += 1;
    gop.value_ptr.* = count.value_ptr.*;
    return count.value_ptr.*;
}

/// `p`'s steps followed by `q`'s.
fn concat(o: *Ownership, p: u32, q: u32) Allocator.Error!u32 {
    if (q == eps) return p;
    if (p == eps) return q;
    if (o.concat_memo.get(.{ p, q })) |r| return r;
    var at = p;
    for (o.steps(q)) |r| at = try o.child(at, r.kind, r.arg);
    try o.concat_memo.put(o.in.gpa, .{ p, q }, at);
    return at;
}

/// Whether one path is a prefix of the other, step by step, with `⋆`
/// overlapping anything (§4.1).
const MatchCache = std.HashMapUnmanaged([3]u32, bool, WordsKey(3), std.hash_map.default_max_load_percentage);

fn overlap(o: *const Ownership, p: u32, q: u32) bool {
    // Through the trie: the longer path's ancestor at the shorter's depth
    // is the shorter one exactly when their common steps agree; only a `⋆`
    // among them needs the steps compared one by one.
    const short, const long = if (o.paths.depth.items[p] <= o.paths.depth.items[q]) .{ p, q } else .{ q, p };
    const at = o.ancestor(long, o.paths.depth.items[short]);
    if (at == short) return true;
    if (!o.paths.any.items[at] and !o.paths.any.items[short] and !o.paths.casts.items[at] and !o.paths.casts.items[short]) return false;
    const key: [3]u32 = .{ p, q, 0 };
    if (o.match_cache) |memo| if (memo.get(key)) |answer| return answer;
    const answer = o.overlapSteps(p, q);
    if (o.match_cache) |memo| memo.put(o.in.gpa, key, answer) catch {};
    return answer;
}

/// A storage write does not write a strict descendant value (§32 amendment).
/// Match the loan as ancestor of the written place, including marker expansions.
fn writeOverlap(o: *const Ownership, written: u32, loan: u32, extent: WriteExtent) bool {
    if (extent == .deep) return o.overlap(written, loan);
    return o.match(o.pathNodes(loan), o.pathNodes(written), .loan);
}

/// `overlap`, step by step.
fn overlapSteps(o: *const Ownership, p: u32, q: u32) bool {
    return o.overlapNodes(o.pathNodes(p), o.pathNodes(q));
}

/// The nodes of `p`, root first: `p`'s prefix at each depth.
fn pathNodes(o: *const Ownership, p: u32) []const u32 {
    return o.paths.nodes_of.items[p];
}

fn physicalPath(o: *const Ownership, p: u32) u32 {
    var at = p;
    while (at != eps and o.paths.kind.items[at] == .cast) at = o.paths.parent.items[at];
    return at;
}

fn exactRelatedPaths(o: *const Ownership, p: u32, q: u32) bool {
    const x = o.physicalPath(p);
    const y = o.physicalPath(q);
    return o.startsWith(x, y) or o.startsWith(y, x);
}

fn sameStep(o: *const Ownership, x: u32, y: u32) bool {
    return o.paths.kind.items[x] == o.paths.kind.items[y] and o.paths.arg.items[x] == o.paths.arg.items[y];
}

/// §16.7, *Overlap*: two paths' remaining nodes from one position.
fn overlapNodes(o: *const Ownership, a: []const u32, b: []const u32) bool {
    return o.match(a, b, .overlap);
}

/// What `match` asks of two sets of places: that one place of each is a
/// prefix of the other (`overlap`), or that one of `a`'s is a prefix of one
/// of `b`'s (`holds`).
const MatchMode = enum { overlap, holds, loan };

/// §16.7: two paths' remaining nodes, read as the sets of concrete places
/// they stand for, `⋆` any steps and a marker any steps of its expansion.
/// Exact for markers: each one is expanded only as far as the other path
/// asks, one step at a time.
fn match(o: *const Ownership, a: []const u32, b: []const u32, mode: MatchMode) bool {
    if (a.len == 0) return true;
    if (b.len == 0) {
        if (mode != .loan) return mode == .overlap;
        // A loan of an unknown suffix or a nullable level may be the
        // written storage itself. Keep the older holds relation unchanged.
        const k = o.paths.kind.items[a[0]];
        if (k == .any or k == .cast or k == .cast_level) return true;
        if (k == .level) return o.expand(o.markerKind(o.paths.arg.items[a[0]]), a[0], a[1..], b, mode, true);
        return false;
    }
    const x = a[0];
    const y = b[0];
    const kx = o.paths.kind.items[x];
    const ky = o.paths.kind.items[y];
    if (kx == .cast and ky == .cast and o.paths.arg.items[x] == o.paths.arg.items[y]) return o.match(a[1..], b[1..], mode);
    if (kx == .any or ky == .any or kx == .cast or ky == .cast or kx == .cast_level or ky == .cast_level) return true;
    if (kx == .level and ky == .level) {
        if (o.markerType(o.paths.arg.items[x]) != o.markerType(o.paths.arg.items[y])) return true;
        // Both end at a `T`; one expansion may be the other's and more,
        // and what is more starts at a `T`.
        return o.expand(.at, x, a[1..], b[1..], mode, true) or o.expand(.at, y, b[1..], a[1..], mode, false);
    }
    if (kx == .level) return o.expand(o.markerKind(o.paths.arg.items[x]), x, a[1..], b, mode, true);
    if (ky == .level) return o.expand(o.markerKind(o.paths.arg.items[y]), y, b[1..], a, mode, false);
    if (!o.sameStep(x, y)) return false;
    return o.match(a[1..], b[1..], mode);
}

/// The marker `m` of kind `kind`, followed by `r`, against `other`, which
/// is on the left of `match` when `left` is false.
fn expand(o: *const Ownership, kind: MarkerKind, m: u32, r: []const u32, other: []const u32, mode: MatchMode, left: bool) bool {
    // The empty expansion: where the marker stands at a `T`.
    if (kind == .at or kind == .maybe) {
        if (if (left) o.match(r, other, mode) else o.match(other, r, mode)) return true;
    }
    if (other.len == 0) return if (left) mode == .overlap else true;
    const y = other[0];
    switch (o.paths.kind.items[y]) {
        .any => return true,
        .level => {
            if (o.markerType(o.paths.arg.items[y]) != o.markerType(o.paths.arg.items[m])) return true;
            const ky = o.markerKind(o.paths.arg.items[y]);
            // `m` goes on through all `y` stands for (it then stands where a
            // `T` may or may not be), or `y` takes what is left of `m`.
            return o.expand(.maybe, m, r, other[1..], mode, left) or o.expand(ky, y, other[1..], r, mode, !left);
        },
        else => {},
    }
    const next = o.regionStepKind(kind, o.markerType(o.paths.arg.items[m]), y) orelse return false;
    return o.expand(next, m, r, other[1..], mode, left);
}

/// Where a marker of kind `kind` for type `t` stands after `step`, when its
/// expansion may begin with it: any step where the value may not be a `T`;
/// where it is, a constructor step of `T` whose field can hold a `T`.
fn regionStepKind(o: *const Ownership, kind: MarkerKind, t: u64, step: u32) ?MarkerKind {
    // A closure's environment: its `◇` is the region step, and below it are
    // the captures, any of which may be a closure itself.
    if (t == fn_type) return .maybe;
    const is_t = o.paths.kind.items[step] == .ctor and o.ctorType(o.stepCtor(o.paths.arg.items[step])) == t;
    if (is_t) {
        const strict = kind == .at or kind == .under;
        if (!o.paths.holds.items[step]) return if (strict) null else .maybe;
        // `level_of` is filled for this step: `rawChild` asked `levelOf`
        // for every constructor step when it computed `holds`.
        return if (o.level_of.items[o.paths.arg.items[step]] == .here) .at else .below;
    }
    return if (kind == .at or kind == .under) null else .maybe;
}

/// When `p` is a prefix of `q`, the rest of `q`; else null.
fn suffix(o: *Ownership, p: u32, q: u32) Allocator.Error!?u32 {
    if (!o.startsWith(q, p)) return null;
    if (p == q) return eps;
    const key: [2]u32 = .{ p, q };
    if (o.suffix_memo.get(key)) |cached| return cached;
    const sq = o.steps(q);
    var at: u32 = eps;
    for (sq[o.paths.depth.items[p]..]) |s| at = try o.child(at, s.kind, s.arg);
    try o.suffix_memo.put(o.in.gpa, key, at);
    return at;
}

/// `p`'s prefix of depth `d`, which is at most `p`'s.
fn ancestor(o: *const Ownership, p: u32, d: u32) u32 {
    var at = p;
    var n = o.paths.depth.items[p];
    while (n > d) : (n -= 1) at = o.paths.parent.items[at];
    return at;
}

/// Whether `p`'s steps begin with all of `q`'s, `⋆` matching only `⋆`.
fn startsWith(o: *const Ownership, p: u32, q: u32) bool {
    const d = o.paths.depth.items[q];
    return o.paths.depth.items[p] >= d and o.ancestor(p, d) == q;
}

/// §16.7, *Holding a symbolic cell*: whether one of the places at `p`
/// may be a prefix of one of the places at `q` through a marker (the
/// prefix step by step is the exact case of `coversAt`).
fn levelHoldsPaths(o: *const Ownership, p: u32, q: u32) bool {
    if (!o.paths.any.items[p] and !o.paths.any.items[q] and !o.paths.casts.items[p] and !o.paths.casts.items[q]) return false;
    const key: [3]u32 = .{ p, q, 1 };
    if (o.match_cache) |memo| if (memo.get(key)) |answer| return answer;
    const answer = o.match(o.pathNodes(p), o.pathNodes(q), .holds);
    if (o.match_cache) |memo| memo.put(o.in.gpa, key, answer) catch {};
    return answer;
}

/// Whether `p` is a prefix of `q`, `⋆` matching anything.
fn isPrefix(o: *const Ownership, p: u32, q: u32) bool {
    return o.paths.depth.items[p] <= o.paths.depth.items[q] and o.overlap(p, q);
}

fn hasStep(o: *const Ownership, p: u32, kind: StepKind) bool {
    var at = p;
    while (at != eps and at != none) : (at = o.paths.parent.items[at]) {
        if (o.paths.kind.items[at] == kind) return true;
    }
    return false;
}

/// §16.7 (e): whether `p` goes through the level marker `⟨T⟩` of a recursive
/// type (not F1's marker of closures), so that it names the places of
/// several levels of one region.
fn levelMarked(o: *const Ownership, p: u32) bool {
    var at = p;
    while (at != eps and at != none) : (at = o.paths.parent.items[at]) {
        if (o.paths.kind.items[at] == .level and o.markerType(o.paths.arg.items[at]) != fn_type) return true;
    }
    return false;
}

fn firstStep(o: *const Ownership, p: u32) ?Step {
    if (p == eps) return null;
    var at = p;
    while (o.paths.parent.items[at] != eps) at = o.paths.parent.items[at];
    return .{ .kind = o.paths.kind.items[at], .arg = o.paths.arg.items[at] };
}

/// `p` without its first step.
fn dropFirst(o: *Ownership, p: u32) Allocator.Error!u32 {
    if (o.paths.rest.items[p] != none) return o.paths.rest.items[p];
    const r = try o.dropFirstRaw(p);
    o.paths.rest.items[p] = r;
    return r;
}

fn dropFirstRaw(o: *Ownership, p: u32) Allocator.Error!u32 {
    const s = o.steps(p);
    var at: u32 = eps;
    for (s[1..]) |r| at = try o.child(at, r.kind, r.arg);
    return at;
}

fn writePath(o: *Ownership, w: *std.Io.Writer, p: u32) (Allocator.Error || std.Io.Writer.Error)!void {
    for (o.steps(p)) |s| switch (s.kind) {
        .field => try w.print(".{s}", .{o.in.interner.slice(@fromBackingInt(@intCast(s.arg)))}),
        .tuple => try w.print(".{d}", .{s.arg}),
        .ctor => {
            // `#Name.i`: the constructor and the argument.
            const c = o.stepCtor(s.arg);
            const name: []const u8 = blk: {
                if (c >= o.ctor_key.items.len) break :blk "";
                const key = o.ctor_key.items[c];
                break :blk o.ctorName(@intCast(key >> 32), @truncate(key));
            };
            try w.print("#{s}.{d}", .{ name, o.stepField(s.arg) });
        },
        .elem => try w.writeAll("[*]"),
        .cast => try w.print("⟨as {s}⟩", .{try o.castText(s.arg)}),
        .cast_level => try w.print("⟨as {s}⟩⁺", .{try o.castText(s.arg)}),
        .level => {
            const t = o.markerType(s.arg);
            if (t == fn_type) {
                try w.writeAll("⟨◇⟩");
                continue;
            }
            if (o.schemaKeyOf(t)) |sk| {
                const sb = o.in.birs[sk.m];
                try w.print("⟨{s}.{s}⟩{s}", .{ o.in.interner.slice(sb.symbol(sb.decls[sk.decl].name)), if (sk.encoded) "Encoded" else "Type", if (o.markerKind(s.arg) == .under) "⁺" else "" });
                continue;
            }
            const m: u32 = @intCast(t >> 32);
            const d: u32 = @truncate(t);
            const name = if (m < o.in.birs.len and d < o.in.birs[m].decls.len) o.in.interner.slice(o.in.birs[m].symbol(o.in.birs[m].decls[d].name)) else "";
            try w.print("⟨{s}⟩{s}", .{ name, if (o.markerKind(s.arg) == .under) "⁺" else "" });
        },
        .env => try w.writeAll("◇"),
        .markup_render => try w.writeAll("⟨render⟩"),
        .markup_event => try w.writeAll("⟨events⟩"),
        .schema_decoded => try w.writeAll("⟨decoded⟩"),
        .schema_encoded => try w.writeAll("⟨encoded⟩"),
        .any => try w.writeAll("⋆"),
    };
}

pub fn ctorId(o: *Ownership, module: u32, index: u32) Allocator.Error!u32 {
    const key = (@as(u64, module) << 32) | index;
    const gop = try o.ctor_ids.getOrPut(o.in.gpa, key);
    if (!gop.found_existing) {
        gop.value_ptr.* = @intCast(o.ctor_ids.count() - 1);
        // The type that declares it, for folding (§16.7).
        var ty: u64 = std.math.maxInt(u64);
        if (module < o.in.birs.len and index != none) {
            const bir = o.in.birs[module];
            if (index < bir.ctors.len) ty = (@as(u64, module) << 32) | bir.ctors[index].decl.int();
            // §16.7 (#820): a native schema's constructor, its endpoint's.
            if (try o.schemaCtorOwner(module, index)) |s| ty = schemaKey(module, s.decl, s.encoded);
        }
        try o.ctor_type.append(o.in.gpa, ty);
        try o.ctor_key.append(o.in.gpa, key);
    }
    return gop.value_ptr.*;
}

/// The step argument of field `i` of constructor id `c` (§4.1): exact for
/// every field of every constructor (issue #289).
pub fn ctorStep(o: *Ownership, c: u32, i: u32) Allocator.Error!u32 {
    const gop = try o.ctor_steps.getOrPut(o.in.gpa, .{ c, i });
    if (!gop.found_existing) {
        gop.value_ptr.* = @intCast(o.step_ctor.items.len);
        try o.step_ctor.append(o.in.gpa, .{ c, i });
    }
    return gop.value_ptr.*;
}

/// The constructor id a constructor step names.
pub fn stepCtor(o: *const Ownership, arg: u32) u32 {
    return o.step_ctor.items[arg][0];
}

/// The field a constructor step names.
pub fn stepField(o: *const Ownership, arg: u32) u32 {
    return o.step_ctor.items[arg][1];
}

// ---------------------------------------------------------------------------
// Crossing and sharing over types (§4.4, §6.1)
// ---------------------------------------------------------------------------

const NominalFacts = struct {
    /// A `List`, a function or a non-primitive `foreign type` is reachable
    /// in the body without going through a type parameter.
    own: bool = false,
    /// A type parameter is reachable in the body.
    params: bool = false,
    /// One constructor of one field: the release representation may make a
    /// value of it its field (thesis §3.1, A10).
    unboxed: bool = false,
    /// §23.4: a `List` is reachable in the body without going through a
    /// type parameter, a function or a `foreign type` other than `List`.
    list: bool = false,
    /// §31.2: a record is reachable in the body without going through a
    /// type parameter, so a value of the type carries a record cell.
    record: bool = false,
};

fn isPrimitive(o: *const Ownership, id: TypeId) bool {
    const wk = o.in.types.well_known;
    return id == wk.int or id == wk.float or id == wk.char or id == wk.string;
}

fn nominalFacts(o: *Ownership, id: TypeId) Allocator.Error!NominalFacts {
    if (id == .none or id.int() >= o.in.types.entries.len) return .{ .own = true };
    if (o.nominal.len == 0) {
        o.nominal = try o.in.gpa.alloc(?NominalFacts, o.in.types.entries.len);
        @memset(o.nominal, null);
    }
    if (o.nominal[id.int()]) |f| return f;
    // A group being solved reads only types solved before it and its own
    // members, which start from nothing: never one `solveNominal` would
    // have to walk again, over the columns the walk in progress is using.
    if (std.debug.runtime_safety) std.debug.assert(!o.nominal_solving);
    try o.solveNominal(id);
    return o.nominal[id.int()].?;
}

/// What every type `id` reaches holds (§4.4), remembered for each. The
/// types a definition names are a graph, and "holds a cell" is the least
/// fixpoint over it: each strongly connected group of mutually recursive
/// types is solved once, every member starting from nothing and read again
/// until none changes, after the groups it names (Tarjan's order). Before
/// 2026-10-17 a type was read with the ones in progress taken to hold
/// nothing and remembered so: `type B = B A`, read inside `type A = A B
/// (List Int)`, crossed. Its first fix remembered only a cycle's outermost
/// type, and read the others again on every path through the cycle, which
/// is exponential in the cycle (#341).
fn solveNominal(o: *Ownership, root: TypeId) Allocator.Error!void {
    const gpa = o.in.gpa;
    const n = o.in.types.entries.len;
    if (o.nominal_order.len == 0) {
        o.nominal_order = try gpa.alloc(u32, n);
        @memset(o.nominal_order, 0);
        o.nominal_link = try gpa.alloc(u32, n);
        o.nominal_on = try gpa.alloc(bool, n);
        @memset(o.nominal_on, false);
    }
    const TypeFrame = struct { id: u32, edges: []u32, next: usize };
    var frames: std.ArrayList(TypeFrame) = .empty;
    defer {
        for (frames.items) |fr| gpa.free(fr.edges);
        frames.deinit(gpa);
    }
    var stack: std.ArrayList(u32) = .empty;
    defer stack.deinit(gpa);
    var visited: std.ArrayList(u32) = .empty;
    defer {
        for (visited.items) |v| o.nominal_order[v] = 0;
        visited.deinit(gpa);
    }
    var order: u32 = 0;
    const enter = struct {
        fn f(ow: *Ownership, fs: *std.ArrayList(TypeFrame), st: *std.ArrayList(u32), vs: *std.ArrayList(u32), ord: *u32, v: u32) Allocator.Error!void {
            ord.* += 1;
            ow.nominal_order[v] = ord.*;
            ow.nominal_link[v] = ord.*;
            ow.nominal_on[v] = true;
            try st.append(ow.in.gpa, v);
            try vs.append(ow.in.gpa, v);
            var edges: std.ArrayList(u32) = .empty;
            try ow.nominalEdges(@fromBackingInt(v), &edges);
            try fs.append(ow.in.gpa, .{ .id = v, .edges = try edges.toOwnedSlice(ow.in.gpa), .next = 0 });
        }
    }.f;
    try enter(o, &frames, &stack, &visited, &order, root.int());
    while (frames.items.len > 0) {
        const top = &frames.items[frames.items.len - 1];
        if (top.next < top.edges.len) {
            const w = top.edges[top.next];
            top.next += 1;
            if (o.nominal[w] != null) continue;
            if (o.nominal_order[w] == 0) {
                try enter(o, &frames, &stack, &visited, &order, w);
            } else if (o.nominal_on[w]) {
                o.nominal_link[top.id] = @min(o.nominal_link[top.id], o.nominal_order[w]);
            }
            continue;
        }
        const fr = frames.pop().?;
        gpa.free(fr.edges);
        const v = fr.id;
        if (frames.items.len > 0) {
            const parent = frames.items[frames.items.len - 1].id;
            o.nominal_link[parent] = @min(o.nominal_link[parent], o.nominal_link[v]);
        }
        if (o.nominal_link[v] != o.nominal_order[v]) continue;
        // `v` roots a group: the stack down to it.
        var at = stack.items.len;
        while (true) {
            at -= 1;
            if (stack.items[at] == v) break;
        }
        const group = stack.items[at..];
        for (group) |x| {
            o.nominal_on[x] = false;
            o.nominal[x] = .{};
        }
        // A member reads the others as they stand: one whose list is
        // reached only through a member read after it is seen on a later
        // pass (`ownership/MutualCycles`'s three-type cycle).
        o.nominal_solving = true;
        defer o.nominal_solving = false;
        var changed = true;
        while (changed) {
            changed = false;
            for (group) |x| {
                const f = try o.nominalFactsOf(@fromBackingInt(x));
                if (!std.meta.eql(f, o.nominal[x].?)) {
                    o.nominal[x] = joinFacts(o.nominal[x].?, f);
                    o.nominal[x].?.unboxed = f.unboxed;
                    changed = true;
                }
            }
        }
        stack.shrinkRetainingCapacity(at);
    }
}

/// The nominal types `birTypeFacts` may read for type `id`'s definition: a
/// superset of them, or a group is solved before a type it reads. Edit it
/// with `nominalFactsOf` and `birTypeFacts`, case by case.
fn nominalEdges(o: *Ownership, id: TypeId, out: *std.ArrayList(u32)) Allocator.Error!void {
    if (id == .none or id.int() >= o.in.types.entries.len) return;
    const e = o.in.types.entries[id.int()];
    if (e.schema_endpoint or e.kind == .foreign) return;
    const m = e.module.int();
    const bir = o.in.birs[m];
    const d = bir.decl(e.decl);
    if (e.kind == .alias) {
        if (d.annotation.unwrap()) |body| try o.exprEdges(m, bir, body, out);
        return;
    }
    for (bir.declCtors(d)) |c| for (bir.extraSlice(.{ .start = c.args_start, .end = c.args_end }, Inst.Index)) |arg| try o.exprEdges(m, bir, arg, out);
}

/// `nominalEdges` for a type written in module `m`: every head
/// `birTypeFacts` may read for it, edited together with it.
fn exprEdges(o: *Ownership, m: u32, bir: *const Bir, inst: Inst.Index, out: *std.ArrayList(u32)) Allocator.Error!void {
    const tag = bir.instTag(inst);
    const data = bir.instData(inst);
    const graph_m: Graph.Index = @fromBackingInt(@intCast(m));
    const push = struct {
        fn f(ow: *Ownership, x: TypeId, list: *std.ArrayList(u32)) Allocator.Error!void {
            if (x == .none or x.int() >= ow.in.types.entries.len) return;
            try list.append(ow.in.gpa, x.int());
        }
    }.f;
    switch (tag) {
        .type_tuple => for (bir.extraSlice(Bir.inlineRange(data), Inst.Index)) |el| try o.exprEdges(m, bir, el, out),
        .type_record => for (bir.extraSlice(Bir.inlineRange(data), Bir.Field)) |fl| try o.exprEdges(m, bir, fl.value, out),
        .type_record_ext => for (bir.extraSlice(bir.subRange(@fromBackingInt(@intCast(data.rhs))), Bir.Field)) |fl| try o.exprEdges(m, bir, fl.value, out),
        .type_top, .ext_type, .schema_type_top, .ext_schema_type => try push(o, o.in.types.headId(graph_m, tag, data), out),
        .type_app => {
            const head: Inst.Index = @fromBackingInt(@intCast(data.lhs));
            try push(o, o.in.types.headId(graph_m, bir.instTag(head), bir.instData(head)), out);
            for (bir.extraSlice(bir.subRange(@fromBackingInt(@intCast(data.rhs))), Inst.Index)) |arg| try o.exprEdges(m, bir, arg, out);
        },
        else => {},
    }
}

fn nominalFactsOf(o: *Ownership, id: TypeId) Allocator.Error!NominalFacts {
    const e = o.in.types.entries[id.int()];
    var facts: NominalFacts = .{};
    if (e.schema_endpoint) {
        facts.own = true;
        facts.list = true;
    } else switch (e.kind) {
        .foreign => {
            facts.own = id == o.in.types.well_known.list or !o.isPrimitive(id);
            facts.list = id == o.in.types.well_known.list;
            // `crossing foreign type` (§24.2): it holds no cell.
            if (e.module.int() < o.in.birs.len) {
                const bir = o.in.birs[e.module.int()];
                for (bir.ownSlots(bir.decl(e.decl))) |s| if (s[0] == Bir.own_type) {
                    facts.own = false;
                };
            }
        },
        .alias, .adt => {
            const m = e.module.int();
            const bir = o.in.birs[m];
            const d = bir.decl(e.decl);
            if (e.kind == .alias) {
                if (d.annotation.unwrap()) |body| facts = try o.birTypeFacts(m, bir, body, 0);
            } else {
                const ctors = bir.declCtors(d);
                for (ctors) |c| {
                    const args = bir.extraSlice(.{ .start = c.args_start, .end = c.args_end }, Inst.Index);
                    for (args) |arg| {
                        const f = try o.birTypeFacts(m, bir, arg, 0);
                        facts.own = facts.own or f.own;
                        facts.params = facts.params or f.params;
                        facts.list = facts.list or f.list;
                        facts.record = facts.record or f.record;
                    }
                }
                if (ctors.len == 1) {
                    facts.unboxed = bir.extraSlice(.{ .start = ctors[0].args_start, .end = ctors[0].args_end }, Inst.Index).len == 1;
                }
            }
        },
    }
    return facts;
}

/// What a type written in module `m` holds. Every nominal type it reads
/// must be an edge of `nominalEdges`/`exprEdges` (`solveNominal`): edit
/// them together, case by case.
fn birTypeFacts(o: *Ownership, m: u32, bir: *const Bir, inst: Inst.Index, depth: u32) Allocator.Error!NominalFacts {
    if (depth > type_depth) return .{ .own = true, .list = true };
    const tag = bir.instTag(inst);
    const data = bir.instData(inst);
    const graph_m: Graph.Index = @fromBackingInt(@intCast(m));
    switch (tag) {
        .type_fn => return .{ .own = true },
        .type_var => return .{ .params = true },
        .type_unit => return .{},
        .type_tuple => {
            var f: NominalFacts = .{};
            for (bir.extraSlice(Bir.inlineRange(data), Inst.Index)) |el| f = joinFacts(f, try o.birTypeFacts(m, bir, el, depth + 1));
            return f;
        },
        // §31.2: a record is a cell, so a nominal type that reaches one does
        // not cross; the empty record has no field to write.
        .type_record => {
            var f: NominalFacts = .{ .record = data.lhs != data.rhs };
            for (bir.extraSlice(Bir.inlineRange(data), Bir.Field)) |fl| f = joinFacts(f, try o.birTypeFacts(m, bir, fl.value, depth + 1));
            return f;
        },
        .type_record_ext => {
            var f: NominalFacts = .{ .params = true, .record = true };
            for (bir.extraSlice(bir.subRange(@fromBackingInt(@intCast(data.rhs))), Bir.Field)) |fl| f = joinFacts(f, try o.birTypeFacts(m, bir, fl.value, depth + 1));
            return f;
        },
        .type_top, .ext_type, .schema_type_top, .ext_schema_type => {
            const nf = try o.nominalFacts(o.in.types.headId(graph_m, tag, data));
            return .{ .own = nf.own, .list = nf.list, .record = nf.record };
        },
        .type_app => {
            const head: Inst.Index = @fromBackingInt(@intCast(data.lhs));
            const nf = try o.nominalFacts(o.in.types.headId(graph_m, bir.instTag(head), bir.instData(head)));
            var f: NominalFacts = .{ .own = nf.own, .list = nf.list, .record = nf.record };
            if (nf.params) for (bir.extraSlice(bir.subRange(@fromBackingInt(@intCast(data.rhs))), Inst.Index)) |arg| {
                f = joinFacts(f, try o.birTypeFacts(m, bir, arg, depth + 1));
            };
            return f;
        },
        else => return .{ .own = true, .list = true },
    }
}

/// §31.2: whether the value at `steps` holds records and nothing a list's
/// facts read (`Walker.holdsOnlyRecords`), read off the declarations: the
/// first step is a constructor's field, and each later one goes into the
/// type the declaration writes there. A type parameter is the argument's,
/// which is not read here, so a path that reaches one answers no.
fn birHoldsOnlyRecords(o: *Ownership, path_steps: []const Step) Allocator.Error!bool {
    std.debug.assert(path_steps[0].kind == .ctor);
    const key = o.ctorKey(o.stepCtor(path_steps[0].arg));
    if (key.module >= o.in.birs.len or key.index == none) return false;
    var m = key.module;
    var bir = o.in.birs[m];
    if (key.index >= bir.ctors.len) return false;
    const ctor = bir.ctors[key.index];
    const first = bir.extraSlice(.{ .start = ctor.args_start, .end = ctor.args_end }, Inst.Index);
    const fi = o.stepField(path_steps[0].arg);
    if (fi >= first.len) return false;
    var at = first[fi];
    var depth: u32 = 0;
    for (path_steps[1..], 1..) |s, si| {
        // An alias written as a name: its body, in its module.
        while (true) {
            depth += 1;
            if (depth > type_depth) return false;
            const tag = bir.instTag(at);
            if (tag != .type_top and tag != .ext_type) break;
            const id = o.in.types.headId(@fromBackingInt(@intCast(m)), tag, bir.instData(at));
            if (id == .none or id.int() >= o.in.types.entries.len) return false;
            const e = o.in.types.entries[id.int()];
            if (e.kind != .alias or e.schema_endpoint) break;
            m = e.module.int();
            bir = o.in.birs[m];
            at = bir.decl(e.decl).annotation.unwrap() orelse return false;
        }
        const data = bir.instData(at);
        switch (s.kind) {
            .field => {
                const fields = switch (bir.instTag(at)) {
                    .type_record => bir.extraSlice(Bir.inlineRange(data), Bir.Field),
                    .type_record_ext => bir.extraSlice(bir.subRange(@fromBackingInt(@intCast(data.rhs))), Bir.Field),
                    else => return false,
                };
                for (fields) |f| {
                    if (@backingInt(bir.symbol(f.name)) == s.arg) {
                        at = f.value;
                        break;
                    }
                } else return false;
            },
            .tuple => {
                if (bir.instTag(at) != .type_tuple) return false;
                const els = bir.extraSlice(Bir.inlineRange(data), Inst.Index);
                if (s.arg >= els.len) return false;
                at = els[s.arg];
            },
            .elem => {
                if (bir.instTag(at) != .type_app) return false;
                const head: Inst.Index = @fromBackingInt(@intCast(data.lhs));
                if (o.in.types.headId(@fromBackingInt(@intCast(m)), bir.instTag(head), bir.instData(head)) != o.in.types.well_known.list) return false;
                const args = bir.extraSlice(bir.subRange(@fromBackingInt(@intCast(data.rhs))), Inst.Index);
                if (args.len != 1) return false;
                at = args[0];
            },
            // Another constructor's field: its own declaration's.
            .ctor => return o.birHoldsOnlyRecords(path_steps[si..]),
            else => return false,
        }
    }
    const f = try o.birTypeFacts(m, bir, at, 0);
    return f.record and !f.own and !f.params;
}
fn joinFacts(a: NominalFacts, b: NominalFacts) NominalFacts {
    return .{ .own = a.own or b.own, .params = a.params or b.params, .list = a.list or b.list, .record = a.record or b.record };
}

/// §23.4: whether a value of this type may hold a list that beni code can
/// reach without `Js`: what a send gives up that `update` could write in
/// place. A function's captures and a `foreign type`'s insides are not
/// such a list — §16.5's `pending` follows a writing closure, and a value
/// read out of JavaScript is `⊤` wherever it is read.
fn holdsList(o: *Ownership, store: *TypeStore, v: Var, depth: u32) Allocator.Error!bool {
    if (depth > type_depth) return true;
    const root, _ = store.resolved(v);
    const key: TrackedKey = .{ .store = @intFromPtr(store), .root = @backingInt(root), .depth = depth, .query = 2 };
    if (o.tracked_inner_memo.get(key)) |answer| return answer;
    const answer = try o.holdsListContent(store, v, depth);
    try o.tracked_inner_memo.put(o.in.gpa, key, answer);
    return answer;
}

fn holdsListContent(o: *Ownership, store: *TypeStore, v: Var, depth: u32) Allocator.Error!bool {
    switch (store.resolvedContent(v)) {
        // A type variable may be anything; an alias `resolvedContent` left
        // unexpanded is taken to hold one rather than walked.
        .flex, .rigid, .err, .alias => return true,
        .structure => |s| switch (s) {
            .unit, .empty_record, .func => return false,
            .tuple => |r| {
                for (store.vars(r)) |el| if (try o.holdsList(store, el, depth + 1)) return true;
                return false;
            },
            .record => |r| {
                for (store.fields(r.fields)) |f| if (try o.holdsList(store, f.value, depth + 1)) return true;
                return o.holdsList(store, r.ext, depth + 1);
            },
            .app => |a| {
                if (a.type == o.in.types.well_known.list) return true;
                const nf = try o.nominalFacts(a.type);
                if (nf.list) return true;
                if (nf.params) for (store.vars(a.args)) |arg| if (try o.holdsList(store, arg, depth + 1)) return true;
                return false;
            },
        },
    }
}

/// §31.4 item 6: whether a value of this type may be or hold a record's
/// object, which a record condition is about; a list of numbers holds none,
/// so two places that share it share no record.
fn holdsRecord(o: *Ownership, store: *TypeStore, v: Var, depth: u32) Allocator.Error!bool {
    if (depth > type_depth) return true;
    const root, _ = store.resolved(v);
    const key: TrackedKey = .{ .store = @intFromPtr(store), .root = @backingInt(root), .depth = depth, .query = 3 };
    if (o.tracked_inner_memo.get(key)) |answer| return answer;
    const answer = try o.holdsRecordContent(store, v, depth);
    try o.tracked_inner_memo.put(o.in.gpa, key, answer);
    return answer;
}

fn holdsRecordContent(o: *Ownership, store: *TypeStore, v: Var, depth: u32) Allocator.Error!bool {
    switch (store.resolvedContent(v)) {
        .flex, .rigid, .err, .alias => return true,
        .structure => |s| switch (s) {
            .unit, .empty_record, .func => return false,
            .record => return true,
            .tuple => |r| {
                for (store.vars(r)) |el| if (try o.holdsRecord(store, el, depth + 1)) return true;
                return false;
            },
            .app => |a| {
                if (a.type == o.in.types.well_known.list) {
                    for (store.vars(a.args)) |arg| if (try o.holdsRecord(store, arg, depth + 1)) return true;
                    return false;
                }
                if (o.isPrimitive(a.type)) return false;
                const nf = try o.nominalFacts(a.type);
                // A record, or what the checker cannot see into — a `foreign
                // type` (`Js.Value`, a program, a host's handle) or a list,
                // function or foreign type inside the declaration — may hold
                // one (#421): only a type whose body is seen to hold none
                // holds none.
                if (nf.record or nf.own) return true;
                if (nf.params) for (store.vars(a.args)) |arg| if (try o.holdsRecord(store, arg, depth + 1)) return true;
                return false;
            },
        },
    }
}

/// Whether a value of this type may hold a cell (§4.4: it does not cross).
fn tracked(o: *Ownership, store: *TypeStore, v: Var, depth: u32) Allocator.Error!bool {
    return o.trackedIn(store, v, depth, true);
}

/// Whether a value of this type may hold a cell that is not a record's
/// object: what crossed before §31.2's amendment, and what a list's facts
/// still read (`Cell.nonlist`) until the record demand reaches them.
fn listTracked(o: *Ownership, store: *TypeStore, v: Var, depth: u32) Allocator.Error!bool {
    return o.trackedIn(store, v, depth, false);
}

// Solved types are DAGs: visiting a shared tuple subtree once per edge is
// exponential. Include depth because the existing conservative cutoff is
// part of the result, and the store because the serial dump keeps several.
fn trackedIn(o: *Ownership, store: *TypeStore, v: Var, depth: u32, records: bool) Allocator.Error!bool {
    if (depth > type_depth) return true;
    const root, _ = store.resolved(v);
    const key: TrackedKey = .{ .store = @intFromPtr(store), .root = @backingInt(root), .depth = depth, .query = @intFromBool(records) };
    if (o.tracked_inner_memo.get(key)) |answer| return answer;
    const answer = try o.trackedContent(store, v, depth, records);
    try o.tracked_inner_memo.put(o.in.gpa, key, answer);
    return answer;
}

fn trackedContent(o: *Ownership, store: *TypeStore, v: Var, depth: u32, records: bool) Allocator.Error!bool {
    switch (store.resolvedContent(v)) {
        .flex, .rigid, .err => return true,
        .alias => return true,
        .structure => |s| switch (s) {
            .unit, .empty_record => return false,
            .func => return true,
            .tuple => |r| {
                for (store.vars(r)) |el| if (try o.trackedIn(store, el, depth + 1, records)) return true;
                return false;
            },
            // §31.2: a record is written in place, so a value of the type
            // carries its cell, whatever its fields are.
            .record => |r| {
                if (records) return true;
                for (store.fields(r.fields)) |f| if (try o.trackedIn(store, f.value, depth + 1, records)) return true;
                return o.trackedIn(store, r.ext, depth + 1, records);
            },
            .app => |a| {
                if (a.type == o.in.types.well_known.list) return true;
                const nf = try o.nominalFacts(a.type);
                if (nf.own or (records and nf.record)) return true;
                if (nf.params) for (store.vars(a.args)) |arg| if (try o.trackedIn(store, arg, depth + 1, records)) return true;
                return false;
            },
        },
    }
}

/// §23.6: the view-event rule's reason (P6).
const view_event_detail = "a message a view event builds may hold it — a list of the model, or one a handler keeps from one dispatch to the next — and the check does not tell update's arms apart (§20.5, §23.6, P6)";

/// §23.2: what a send does with what it is handed — every cell of it is
/// given up to `update`, which may write it in place.
const send_class: Summary = .{ .params = 1, .uses = &.{.{ .param = 0, .path = eps, .bits = bit_w | bit_x | bit_d }}, .asserted = true };

/// §30.3: the runtime as the callee of an entry's tagger (`onUrlRequest`,
/// `onUrlChange`): it hands crossing values, which carry no cell, so it
/// supplies nothing.
const runtime_row: Summary = .{ .params = 1, .funs = &.{.{ .param = 0, .calls = .many, .need = true, .seen = false }}, .asserted = true };

/// The `k`th parameter type of a function type, when `v` is one.
fn funcParam(store: *TypeStore, v: Var, k: u32) ?Var {
    switch (store.resolvedContent(v)) {
        .structure => |st| switch (st) {
            .func => |fun| {
                const ps = store.vars(fun.params);
                return if (k < ps.len) ps[k] else null;
            },
            else => return null,
        },
        else => return null,
    }
}

fn isFunc(store: *TypeStore, v: Var) bool {
    return switch (store.resolvedContent(v)) {
        .structure => |s| s == .func,
        else => false,
    };
}

fn unboxed(o: *Ownership, id: TypeId) Allocator.Error!bool {
    return (try o.nominalFacts(id)).unboxed;
}

/// Whether the type variable `v` occurs inside `t`, below its root: a value
/// of type `v` is then taken never to be a `t` — an element of a `List a`
/// is never the list. An unboxed recursive type (`One = One (List One)`)
/// is its list, so this rests on §30.9 rule 4's amendment: a summary names
/// `#One.0`, and an unknown callee's result is `⊤call` (§30.11). A value
/// of `v` may still hold a `t` (#270), so only `mayShare` asks this.
fn occursBelow(store: *TypeStore, v: Var, t: Var, depth: u32) bool {
    if (depth > type_depth) return false;
    const root, const c = store.resolved(t);
    if (depth > 0 and root == v) return true;
    return switch (c) {
        .structure => |s| switch (s) {
            .unit, .empty_record => false,
            .func => |f| blk: {
                for (store.vars(f.params)) |p| if (occursBelow(store, v, p, depth + 1)) break :blk true;
                break :blk occursBelow(store, v, f.result, depth + 1);
            },
            .tuple => |r| blk: {
                for (store.vars(r)) |el| if (occursBelow(store, v, el, depth + 1)) break :blk true;
                break :blk false;
            },
            .record => |r| blk: {
                for (store.fields(r.fields)) |f| if (occursBelow(store, v, f.value, depth + 1)) break :blk true;
                break :blk occursBelow(store, v, r.ext, depth + 1);
            },
            .app => |a| blk: {
                for (store.vars(a.args)) |arg| if (occursBelow(store, v, arg, depth + 1)) break :blk true;
                break :blk false;
            },
        },
        else => false,
    };
}

/// Whether `v` reaches itself through structure alone: a cycle of the
/// unifier's graph, which no type name stands for (checker-v2.md §7.3), as
/// `List (List …)`. A named recursive type reaches itself through its
/// declaration, not its graph, and is §16.7's regions'.
fn cyclicVar(a: Allocator, store: *TypeStore, v: Var) Allocator.Error!bool {
    // A type is small, so the walk keeps its roots in lists, not in a map
    // keyed by a dense id (fast-compiler.md §5 rule 5): `stack` is the
    // walk's path, `done` the roots it has finished.
    const WalkFrame = struct { v: Var, kids: std.ArrayList(Var) = .empty, next: usize = 0 };
    var stack: std.ArrayList(WalkFrame) = .empty;
    var done: std.ArrayList(Var) = .empty;
    try stack.append(a, .{ .v = store.resolved(v)[0] });
    try children(a, store, stack.items[0].v, &stack.items[0].kids);
    while (stack.items.len > 0) {
        const top = &stack.items[stack.items.len - 1];
        if (top.next == top.kids.items.len) {
            try done.append(a, top.v);
            _ = stack.pop();
            continue;
        }
        const k = store.resolved(top.kids.items[top.next])[0];
        top.next += 1;
        for (stack.items) |f| if (f.v == k) return true;
        if (std.mem.indexOfScalar(Var, done.items, k) != null) continue;
        try stack.append(a, .{ .v = k });
        const fresh = &stack.items[stack.items.len - 1];
        try children(a, store, k, &fresh.kids);
    }
    return false;
}

/// The variables a type's structure names, for `cyclicVar`.
fn children(a: Allocator, store: *TypeStore, v: Var, out: *std.ArrayList(Var)) Allocator.Error!void {
    _, const c = store.resolved(v);
    switch (c) {
        .structure => |s| switch (s) {
            .unit, .empty_record => {},
            .func => |f| {
                try out.appendSlice(a, store.vars(f.params));
                try out.append(a, f.result);
            },
            .tuple => |r| try out.appendSlice(a, store.vars(r)),
            .record => |r| {
                for (store.fields(r.fields)) |f| try out.append(a, f.value);
                try out.append(a, r.ext);
            },
            .app => |ap| try out.appendSlice(a, store.vars(ap.args)),
        },
        else => {},
    }
}

fn isVar(store: *TypeStore, v: Var) ?Var {
    const root, const c = store.resolved(v);
    return switch (c) {
        .flex, .rigid => root,
        else => null,
    };
}

/// `core/List`'s `Builder`, which `done` hands over as the list it is: the
/// two types are one run-time object (§16.8's `done` row).
fn builderId(o: *Ownership) TypeId {
    if (o.builder_id) |id| return id;
    var found: TypeId = .none;
    for (o.in.types.entries, 0..) |e, i| {
        if (e.package != .core or e.kind != .foreign) continue;
        if (!std.mem.eql(u8, o.in.interner.slice(e.module_name), "List")) continue;
        if (!std.mem.eql(u8, o.in.interner.slice(e.name), "Builder")) continue;
        found = @fromBackingInt(@intCast(i));
        break;
    }
    o.builder_id = found;
    return found;
}

const ResultErr = struct { ty: TypeId, ctor: u32 };

/// §26.2: core `Result`'s type id and the id of its `Err` constructor,
/// the payload a `?` returns from its definition.
fn resultErr(o: *Ownership) Allocator.Error!ResultErr {
    if (o.result_err) |r| return r;
    var ty: TypeId = .none;
    for (o.in.types.entries, 0..) |e, i| {
        if (e.package != .core) continue;
        if (!std.mem.eql(u8, o.in.interner.slice(e.module_name), "Result")) continue;
        if (!std.mem.eql(u8, o.in.interner.slice(e.name), "Result")) continue;
        ty = @fromBackingInt(@intCast(i));
        break;
    }
    var ctor: u32 = none;
    if (ty != .none) for (o.in.module_names, 0..) |name, m| {
        if (m >= o.in.packages.len or o.in.packages[m] != .core or !std.mem.eql(u8, name, "Result")) continue;
        const bir = o.in.birs[m];
        for (bir.ctors, 0..) |c, i| {
            if (!std.mem.eql(u8, o.in.interner.slice(bir.symbol(c.name)), "Err")) continue;
            ctor = try o.ctorId(@intCast(m), @intCast(i));
            break;
        }
        break;
    };
    if (ctor == none) ty = .none;
    o.result_err = .{ .ty = ty, .ctor = ctor };
    return o.result_err.?;
}

fn sameRepresentation(o: *Ownership, x: TypeId, y: TypeId) bool {
    if (x == y) return true;
    const list = o.in.types.well_known.list;
    const builder = o.builderId();
    if (builder == .none) return false;
    return (x == list or x == builder) and (y == list or y == builder);
}

/// Whether a value of type `a` may be the same run-time object as one of
/// type `b` (§6.1).
fn mayShare(o: *Ownership, store: *TypeStore, a: Var, b: Var, depth: u32) Allocator.Error!bool {
    if (depth > type_depth) return true;
    if (isVar(store, a)) |va| if (occursBelow(store, va, b, 0)) return false;
    if (isVar(store, b)) |vb| if (occursBelow(store, vb, a, 0)) return false;
    const ca = store.resolvedContent(a);
    const cb = store.resolvedContent(b);
    const sa = switch (ca) {
        .structure => |s| s,
        else => return true,
    };
    const sb = switch (cb) {
        .structure => |s| s,
        else => return true,
    };
    switch (sa) {
        .app => |x| {
            if (try o.unboxed(x.type)) return true;
            switch (sb) {
                .app => |y| {
                    if (try o.unboxed(y.type)) return true;
                    if (!o.sameRepresentation(x.type, y.type)) return false;
                    const xs = store.vars(x.args);
                    const ys = store.vars(y.args);
                    if (xs.len != ys.len) return true;
                    for (xs, ys) |p, q| if (!try o.mayShare(store, p, q, depth + 1)) return false;
                    return true;
                },
                else => return false,
            }
        },
        .func => return sb == .func or (sb == .app and try o.unboxed(sb.app.type)),
        // Slice 3f's rule that two closed records with different fields
        // are never one object served only `map`'s identity promise, and
        // went with it (§27.4).
        .record => return sb == .record or (sb == .app and try o.unboxed(sb.app.type)),
        .tuple => return sb == .tuple or (sb == .app and try o.unboxed(sb.app.type)),
        .unit, .empty_record => return false,
    }
}

/// Whether a value of type `r`, or a part of it, may be the same object
/// as a value of type `t` (§6.1). Unlike `mayShare`, it takes no
/// `occursBelow` shortcut: a value of a type variable `a` may hold a
/// `List a` where `a` is a recursive type (`type Tree = Node (List Tree) |
/// Leaf`, issue #270).
fn mayHold(o: *Ownership, store: *TypeStore, r: Var, t: Var, depth: u32) Allocator.Error!bool {
    if (depth > type_depth) return true;
    if (try o.mayShare(store, r, t, depth)) return true;
    switch (store.resolvedContent(r)) {
        .flex, .rigid, .err, .alias => return true,
        .structure => |s| switch (s) {
            .unit, .empty_record => return false,
            .func => return true,
            .tuple => |rg| {
                for (store.vars(rg)) |el| if (try o.mayHold(store, el, t, depth + 1)) return true;
                return false;
            },
            .record => |rc| {
                for (store.fields(rc.fields)) |f| if (try o.mayHold(store, f.value, t, depth + 1)) return true;
                return o.tracked(store, rc.ext, depth + 1);
            },
            .app => |a| {
                if (a.type == o.in.types.well_known.list) {
                    for (store.vars(a.args)) |arg| if (try o.mayHold(store, arg, t, depth + 1)) return true;
                    return false;
                }
                const nf = try o.nominalFacts(a.type);
                // What its body holds without going through a type parameter:
                // its constructors' fields, read as written (§30.9); a
                // parameter is one of the arguments, below.
                if (nf.own and try o.ownMayHold(store, a.type, t, depth + 1)) return true;
                if (nf.params) for (store.vars(a.args)) |arg| if (try o.mayHold(store, arg, t, depth + 1)) return true;
                return false;
            },
        },
    }
}

/// §30.9: whether a value of the nominal type `id` may hold, in its own
/// body — its constructors' fields, or an alias's body, as written — an
/// object of type `t`. A type parameter there is an argument, which the
/// caller looks at; a body being read already holds nothing more through
/// its own recursion (the least fixpoint of "holds").
fn ownMayHold(o: *Ownership, store: *TypeStore, id: TypeId, t: Var, depth: u32) Allocator.Error!bool {
    if (depth > type_depth or id == .none or id.int() >= o.in.types.entries.len) return true;
    for (o.holding.items) |x| if (x == id) return false;
    const e = o.in.types.entries[id.int()];
    if (e.schema_endpoint) return true;
    switch (e.kind) {
        // A `foreign type`'s insides are not beni's to read.
        .foreign => return true,
        .alias, .adt => {},
    }
    try o.holding.append(o.in.gpa, id);
    defer _ = o.holding.pop();
    const m = e.module.int();
    const bir = o.in.birs[m];
    const d = bir.decl(e.decl);
    if (e.kind == .alias) {
        const body = d.annotation.unwrap() orelse return true;
        return o.birMayHold(store, m, bir, body, t, depth + 1);
    }
    for (bir.declCtors(d)) |c| {
        for (bir.extraSlice(.{ .start = c.args_start, .end = c.args_end }, Inst.Index)) |arg| {
            if (try o.birMayHold(store, m, bir, arg, t, depth + 1)) return true;
        }
    }
    return false;
}

/// `mayHold` for a type written in a declaration's body (§30.9): whether a
/// value of it may be, or hold, an object of type `t`. A type parameter is
/// the caller's to look at, through the arguments.
fn birMayHold(o: *Ownership, store: *TypeStore, m: u32, bir: *const Bir, inst: Inst.Index, t: Var, depth: u32) Allocator.Error!bool {
    if (depth > type_depth) return true;
    const tag = bir.instTag(inst);
    const data = bir.instData(inst);
    // A type parameter is an argument, which the caller looks at.
    if (tag == .type_var) return false;
    if (try o.birMayShare(store, m, bir, inst, t, depth)) return true;
    const graph_m: Graph.Index = @fromBackingInt(@intCast(m));
    switch (tag) {
        .type_var, .type_unit => return false,
        // A closure may hold anything it captured.
        .type_fn => return true,
        .type_tuple => {
            for (bir.extraSlice(Bir.inlineRange(data), Inst.Index)) |el| if (try o.birMayHold(store, m, bir, el, t, depth + 1)) return true;
            return false;
        },
        .type_record => {
            for (bir.extraSlice(Bir.inlineRange(data), Bir.Field)) |fl| if (try o.birMayHold(store, m, bir, fl.value, t, depth + 1)) return true;
            return false;
        },
        .type_top, .ext_type, .schema_type_top, .ext_schema_type => {
            const id = o.in.types.headId(graph_m, tag, data);
            if (id == o.in.types.well_known.list) return true;
            const nf = try o.nominalFacts(id);
            return nf.own and try o.ownMayHold(store, id, t, depth + 1);
        },
        .type_app => {
            const head: Inst.Index = @fromBackingInt(@intCast(data.lhs));
            const id = o.in.types.headId(graph_m, bir.instTag(head), bir.instData(head));
            const args = bir.extraSlice(bir.subRange(@fromBackingInt(@intCast(data.rhs))), Inst.Index);
            if (id == o.in.types.well_known.list) {
                for (args) |arg| if (try o.birMayHold(store, m, bir, arg, t, depth + 1)) return true;
                return false;
            }
            const nf = try o.nominalFacts(id);
            if (nf.own and try o.ownMayHold(store, id, t, depth + 1)) return true;
            // The arguments, as written here, are what its parameters hold.
            if (nf.params) for (args) |arg| if (try o.birMayHold(store, m, bir, arg, t, depth + 1)) return true;
            return false;
        },
        else => return true,
    }
}

/// `mayShare` for a type written in a declaration's body (§30.9): whether a
/// value of it may be the same object as a value of type `t`.
fn birMayShare(o: *Ownership, store: *TypeStore, m: u32, bir: *const Bir, inst: Inst.Index, t: Var, depth: u32) Allocator.Error!bool {
    if (depth > type_depth) return true;
    const st = switch (store.resolvedContent(t)) {
        .structure => |s| s,
        else => return true,
    };
    if (st == .app) if (try o.unboxed(st.app.type)) return true;
    const tag = bir.instTag(inst);
    const data = bir.instData(inst);
    const graph_m: Graph.Index = @fromBackingInt(@intCast(m));
    switch (tag) {
        .type_var => return true,
        .type_unit => return false,
        .type_fn => return st == .func,
        .type_tuple => return st == .tuple,
        .type_record, .type_record_ext => return st == .record,
        .type_top, .ext_type, .schema_type_top, .ext_schema_type, .type_app => {
            const id = if (tag == .type_app) blk: {
                const head: Inst.Index = @fromBackingInt(@intCast(data.lhs));
                break :blk o.in.types.headId(graph_m, bir.instTag(head), bir.instData(head));
            } else o.in.types.headId(graph_m, tag, data);
            if (try o.unboxed(id)) return true;
            if (st != .app) return false;
            if (!o.sameRepresentation(id, st.app.type)) return false;
            if (tag != .type_app) return true;
            const args = bir.extraSlice(bir.subRange(@fromBackingInt(@intCast(data.rhs))), Inst.Index);
            const ys = store.vars(st.app.args);
            if (args.len != ys.len) return true;
            for (args, ys) |p, q| if (!try o.birMayShare(store, m, bir, p, q, depth + 1)) return false;
            return true;
        },
        else => return true,
    }
}

// ---------------------------------------------------------------------------
// One declaration
// ---------------------------------------------------------------------------

const Mode = enum { summary, report };

/// `except`: §31.2's `(ε, c ∖ F)`, the record object `c` after an update
/// that wrote the fields `F` — the same object, whose projection at a field
/// of `F` is no longer `c`'s. With `F` every field (`except_all`), the
/// object alone: what a closed record's update leaves at ε beside its other
/// fields, each split out.
const CellKind = enum(u8) { site, param, result, env, shared, top, closure, func, cbres, taken, payload, except };

/// An exception set of every field (§31.2).
const except_all: u32 = std.math.maxInt(u32);

const Cell = struct {
    kind: CellKind,
    /// The frame whose function parameter a callback result names.
    scope: u32 = 0,
    /// site/result: the instruction; param: the parameter pattern
    /// instruction; env: the captured local; shared: the module; closure:
    /// its index; func: the module; cbres: the function parameter's index;
    /// taken: the element cell it was taken from (§18.5); payload: the
    /// program constructor's call (§20.5); except: the record cell it is
    /// written over (§31.2).
    a: u32,
    /// shared/func: the declaration; param: 1 for a lambda's or local
    /// function's parameter, 0 for the declaration's own; result: 0 for a
    /// call with no summary (§6.1), else the callee's fresh number; cbres:
    /// the call's instruction; taken: the instruction that took it; except:
    /// the exception set, `except_all` or an index into `Walker.exsets`.
    b: u32 = 0,
    /// taken: the path below the element.
    path: u32 = eps,
    ty: Var.Optional = .none,
    /// shared: a cell the definition made at `path` (§16.3), whose own
    /// elements, when it has any, are cells of their own — not one cell
    /// that stands for everything below, as a value with no summary is.
    made: bool = false,
    /// §31.2: a record's object and nothing a list's facts read — a record
    /// literal's object, an update's (`except`), or a cell whose value, by
    /// its type, holds no cell but records' (`listTracked`). Not part of
    /// the cell's key: it is set when the cell is first made, and a cell
    /// projected from one inherits it.
    nonlist: bool = false,
    /// §16.7: value-scoped condition transported by the level marker.
    condition_only: bool = false,
};

/// §18.2: an atom of a condition in the walk's vocabulary — cells that
/// arrived from outside. `excl`: `a` is a cell; `sep`: `a` and `b` are
/// cells, `a ≤ b`, and `sep c c` of a callback's result is "fresh across
/// calls"; `keep`: `a` the declaration's function parameter, `b` a cell.
const WAtom = struct {
    kind: @FieldType(XAtom, "kind"),
    a: u32,
    b: u32 = none,
    path: u32 = eps,

    fn less(x: WAtom, y: WAtom) bool {
        if (x.kind != y.kind) return @backingInt(x.kind) < @backingInt(y.kind);
        if (x.a != y.a) return x.a < y.a;
        if (x.b != y.b) return x.b < y.b;
        return x.path < y.path;
    }
};

const CondKey = struct {
    pub fn hash(_: CondKey, atoms: []const WAtom) u64 {
        var h = std.hash.Wyhash.init(0);
        for (atoms) |t| std.hash.autoHash(&h, t);
        return h.final();
    }
    pub fn eql(_: CondKey, xs: []const WAtom, ys: []const WAtom) bool {
        if (xs.len != ys.len) return false;
        for (xs, ys) |x, y| if (!std.meta.eql(x, y)) return false;
        return true;
    }
};
/// §18.2: a condition, as the walk keeps it.
const WCond = struct {
    /// 0: holds, given `atoms`; 1: fails, approximately; 2: fails, exactly.
    no: u8 = 0,
    atoms: []const WAtom = &.{},
};

/// The conditions every walk starts with, at `cond_yes` .. `cond_fixed_last`.
const fixed_conds = [_]WCond{ .{}, .{ .no = 1 }, .{ .no = 2 }, .{ .no = 1 } };

/// The conditions every walk starts with.
const cond_yes: u32 = 0;
const cond_lost: u32 = 1;
const cond_shared: u32 = 2;
/// Lost because the walk reached a limit (§16.7): a fixpoint's seeds
/// lowered, a value past `value-cells`, a class whose summary is the
/// pessimistic one. It fails as `cond_lost` does, and a rejection that rests
/// on it takes the `limit` cause, so it is no second error beside the
/// limit's (#233).
const cond_limit: u32 = 3;
/// The last of the conditions every walk starts with, which hold no atoms:
/// a condition above it is a set of atoms (`mkCond`).
const cond_fixed_last: u32 = cond_limit;

/// What relying on a condition came to (§18.4); `limit` for `cond_limit`.
/// The order is the order of `worse`: a later value is the worse failure.
const Rely = enum {
    ok,
    approx,
    limit,
    exact,

    /// The worse of two failures: exact, then a limit, then approximate.
    fn worse(old: ?Rely, new: Rely) Rely {
        const o = old orelse return new;
        return if (@backingInt(new) > @backingInt(o)) new else o;
    }
};

/// An atom relied on, and the frame that relied on it (§18.4).
const Req = struct { frame: u32, atom: WAtom };

/// The earliest points a cell escaped: for a reason of its own (`gen`), and
/// by §18.6's rule only (`js`, with the call as `why`).
const EscAt = struct { gen: u32 = none, js: u32 = none, why: u32 = 0 };

const Escape = struct { grown: Grown = 0, cell: u32, point: u32, why: u32, ctx: u32, prev: u32 };

const Entry = struct {
    path: u32,
    cell: u32,
    /// 0 when exact; else 1 + the instruction of the call whose
    /// conservative aliasing or identity promise put the entry here (§8.4).
    approx: u32 = 0,
    /// §16.7 (F3, the owner's choice (a)): the path went below a variable
    /// that a call inside the group being solved grew; a later such
    /// composition goes to `⋆`.
    grown: Grown = 0,
};

const AV = []const Entry;

/// The cells a read-off numbers fresh (§16.3), in their order, and each
/// cell's position among them.
const Fresh = struct {
    cells: []const u32 = &.{},
    /// `(cell, position)`, sorted by cell.
    by_cell: []const [2]u32 = &.{},

    fn indexOf(f: Fresh, cell: u32) ?usize {
        const i = std.sort.binarySearch([2]u32, f.by_cell, cell, orderFirst) orelse return null;
        return f.by_cell[i][1];
    }
};

/// Orders a key against a pair by the pair's first member.
fn orderFirst(key: u32, x: [2]u32) std.math.Order {
    return std.math.order(key, x[0]);
}

fn orderU32(key: u32, x: u32) std.math.Order {
    return std.math.order(key, x);
}

fn lessPair(_: void, x: [2]u32, y: [2]u32) bool {
    if (x[0] != y[0]) return x[0] < y[0];
    return x[1] < y[1];
}

/// A hash map context over a `[]const u32`, by its contents.
const U32SliceContext = struct {
    pub fn hash(_: U32SliceContext, k: []const u32) u64 {
        return std.hash.Wyhash.hash(0, std.mem.sliceAsBytes(k));
    }
    pub fn eql(_: U32SliceContext, x: []const u32, y: []const u32) bool {
        return std.mem.eql(u32, x, y);
    }
};

/// `deep`: in a closure's `env_writes`, a send gives up every cell at or
/// below the path (§23.2).
/// `fields`: a record write of the capture, with the fields it writes
/// (§31.4 item 4); null for a list's.
const Capture = struct { local: u32, path: u32, read_inst: u32 = none, deep: bool = false, extent: WriteExtent = .deep, fields: ?[]const u32 = null };

/// How a lambda was consumed: what decides its demands on its own
/// parameters (§16.5).
const Consumption = struct {
    kind: enum { supply, local, no_summary, pending },
    /// supply: per parameter of the lambda, a borrowed supply's reason, or
    /// null when every supply it writes is owned.
    bad: []const ?[]const u8 = &.{},
    /// supply: whether the reason is a limit (an element).
    bad_approx: []const bool = &.{},
    /// supply: the cause each reason is, `supply` or `exclusive` (§18.4).
    bad_cause: []const Cause = &.{},
    /// supply: per parameter, a borrowed supply's reason for a record the
    /// lambda writes (§31.5), which only a record demand reads.
    rbad: []const ?[]const u8 = &.{},
    rbad_approx: []const bool = &.{},
    rbad_cause: []const Cause = &.{},
    /// The summary or callee that decided it, for the note.
    name: []const u8 = "",
    /// pending: why.
    why: []const u8 = "",
    /// pending: it follows from a callee's pessimistic summary (§16.7).
    limit: bool = false,
};

/// Where a carried lambda is made (§20.4, amended 2026-10-16): the call, the
/// callee's summary, its lambda, the callback depth, the entry's namespace,
/// and whether the call is in the recursive group being solved.
const CarrySite = struct { inst: u32, sum: usize, klass: u32, depth: u32, ns: u32, merge: bool };

const Closure = struct {
    captures: []const Capture,
    params: []const Inst.Index = &.{},
    /// §28.6: where the lambda or local function is written, or where the
    /// call or value that carried it here is; `none` for a test's.
    token: u32 = none,
    frame: u32 = 0,
    class: ?*const Summary = null,
    /// The captured cells the lambda's body escaped (§16.4 item 4).
    env_escapes: []const Capture = &.{},
    consumed: std.ArrayList(Consumption) = .empty,
    /// §18.8: the captures its body writes; non-empty makes it once.
    env_writes: []const Capture = &.{},
    /// A local function's: its captures are read when it runs, so its
    /// creation demand is made at each call.
    local: bool = false,
    /// §18.8: the probes a once closure's creation and calls made.
    once_probes: std.ArrayList(u32) = .empty,
    /// §18.8: the probes its calls made, on its own cell.
    call_probes: std.ArrayList(u32) = .empty,
    /// §18.8: why it may run more than once, when it may.
    once_bad: ?[]const u8 = null,
    once_bad_approx: bool = false,
    /// §24.9: a lambda a callee's result carried here (`Carried`): what
    /// each of its captures held, as this body holds it, in place of locals
    /// of this body; and the function values its calls of the callee's
    /// function parameters go to.
    binds: []const SynBind = &.{},
    cb_avs: []const SynCall = &.{},
    carried: bool = false,

    const SynBind = struct { local: u32, path: u32, av: AV };
    const SynCall = struct { j: u32, av: AV };
};

const Use = struct {
    grown: Grown = 0,
    read_inst: u32 = none,
    binding: u32 = none,
    pattern_field: u32 = none,
    capture: u32 = none,
    local: u32,
    path: u32,
    /// A record update's base is used at every path but these fields.
    except: []const u32 = &.{},
    point: u32,
    frame: u32,
    ctx: u32,
    token: u32,
    /// A use a closure's consumption makes of what it captured: the
    /// closure, which its once creation allows to stay live (§18.8).
    via: u32 = none,
    /// §28.6: the variable path read, as written, when the use is one.
    at: [2]u32 = .{ none, none },
    /// §31.4 item 5: a read a call makes in the callee's body — 1 through
    /// its summary, 2 by a call with no summary (§6.1) — where no temporary
    /// of the caller can stand in for a written field.
    call: u8 = 0,
    /// With `call`: the argument's own variable path, which the caller
    /// reads before the call; the rest of `path` the callee reads.
    call_at: u32 = eps,
    /// §31.14: the evaluation of a field path, which reads it whether or
    /// not a consumer uses the value: what a record demand's hoists are made
    /// of. No list's fact reads it.
    record_read: bool = false,
    /// §31.4 item 5: the scrutinee of a record pattern, whose fields it
    /// reads one by one (`record_read` uses of their own); no use of the
    /// record whole to a record demand.
    destructure: bool = false,
    /// §31.4 item 5: an update's base use that replaces every field of a
    /// closed record type, and so reads none of them.
    reads_none: bool = false,
};

const Holder = struct {
    local: u32,
    path: u32,
    approx: u32,
    /// Found through a split element's list (§18.4 item 4): the element itself.
    split: bool = false,
    /// §16.7 (e): it holds the written cell itself, a cell that stands for
    /// the lists of several levels of one region: it may be another level.
    level: bool = false,
};

/// `creation`: a once closure's creation, or a local function's call, demanding
/// the captures it writes (§18.8) — resolved first, like a probe, and a write.
const DemandKind = enum { report, callsite, probe, value, creation };

const DemandRec = struct {
    inst: u32 = none,
    kind: DemandKind = .report,
    token: u32,
    op: []const u8,
    base: []const u8,
    /// The root local of the base when it is a variable path.
    base_local: u32,
    base_path: u32,
    point: u32,
    frame: u32,
    ctx: u32,
    element: bool,
    accept: Accept,
    /// The callee with no summary an acceptance rests on (§15 decision 2).
    assumed: []const u8 = "",
    prelim: ?struct { cause: Cause, detail: []const u8, approx: ?bool = null } = null,
    /// A value line's own verdict (§16.5).
    fixed: ?struct { verdict: Verdict, detail: []const u8, assumed: bool = false } = null,
    holders: []const Holder,
    /// The base's cells: what read-off makes W of (§16.3).
    cells: []const Entry = &.{},
    note: []const u8 = "",
    /// A probe's slot in `probe_ok`.
    probe: u32 = none,
    /// Where a call-site demand's W came from.
    origin: Origin = .exact,
    /// §18.4: the write needs exclusive contents that may share; decided
    /// after Dead, which names a live holder first.
    xfail: ?Rely = null,
    xdetail: []const u8 = "the elements of the list it was taken from may share one list",
    /// §18.8: a write of a capture, decided by the once closure `once_ci`.
    once_ci: u32 = none,
    /// §18.8: a once closure's creation demand: its own uses of what it
    /// captured are no later use.
    creation_ci: u32 = none,
    /// §20.6: a demand at a program constructor's entry, by its row.
    entry: bool = false,
    /// §23.2: a send's demand, on every cell of its base; read off as `S`.
    deep: bool = false,
    extent: WriteExtent = .deep,
    /// §28.6: the edit's and the base's tokens, the top-level value a
    /// `top-level` rejection names, the call or operand a `call` or
    /// `held-operand` one does, and the function a `need` one names.
    span: [2]u32 = .{ none, none },
    base_span: [2]u32 = .{ none, none },
    top: ?[3]u32 = null,
    via: u32 = none,
    /// §31.3: a record update's demand, and the fields it writes.
    fields: ?[]const u32 = null,
    /// `uses.items.len` when the demand was made: every use at or after
    /// it was recorded later (`resolveRaw`). The largest value claims none.
    use_mark: u32 = std.math.maxInt(u32),
};

/// Where a call-site demand's W came from: a summary's exact write, one
/// derived through an approximate step (a rejection is then the `call`
/// cause), or a pessimistic summary (the `limit` cause, §16.7).
const Origin = enum { exact, approx, limit };

const Pending = struct {
    av: AV,
    frame: u32,
    token: u32,
    is_ref: bool,
    by_call: bool,
    /// The summary of the call this operand waits for, and its index:
    /// it holds a cell only at paths that call touches (§16.4 item 2).
    consumer: ?*const Summary = null,
    arg: u32 = 0,
};

const CtxNode = struct { parent: u32, case_id: u32, arm: u32, depth: u32 };

/// One field of a closed update's split (`Walker.split_memo`): `.unknown`
/// until an update first needs it.
const SplitField = struct {
    state: enum(u8) { unknown, none, cell } = .unknown,
    cell: u32 = none,
    path: u32 = eps,
};

/// A closed update's split of one base cell: its fields, how many are not
/// known yet, and once all are, those with a cell in `norm`'s order.
const SplitMemo = struct {
    fields: []SplitField,
    unknown: usize,
    sorted: ?[]const u32 = null,
    /// Once `sorted` is known: the split as entries, one run per base
    /// entry's `approx` and `grown` (#825).
    runs: std.ArrayList(*const SplitRun) = .empty,
};

/// A closed update's split of one base entry, whole (#825): every field
/// with a cell, in `norm`'s order, each field's position in it (`none` for
/// a field with no cell), and the positions whose cell a list's facts read
/// (`spineValue`).
const SplitRun = struct {
    entries: []const Entry,
    at: []const u32,
    facing: []const u32,
    approx: u32,
    grown: Grown,
};

/// A value made of a split and a few entries more (#825): `run`'s entries
/// but those at `removed` (ascending), and `rest`, in `norm`'s form; the
/// value is `norm` of both. `len` is the value's length, checked with its
/// address before the value is read this way.
const SplitValue = struct {
    len: usize,
    run: *const SplitRun,
    removed: []const u32,
    rest: []const Entry,
};

/// A `Maybe.withDefault (Maybe.map m f) d` (§7.2 as amended for slice 3f):
/// the call, and the branch contexts of its `Just` and `Nothing` outcomes.
const MaybeJoin = struct { call: Inst.Index, just: u32, nothing: u32 };

const Frame = struct {
    /// The enclosing frame, or `none` for the declaration's.
    parent: u32,
    captures: std.ArrayList(Capture) = .empty,
    pending_base: usize,
    /// §26.2: what the `?`s of this frame return from it — each `Err`
    /// payload, under `Err` — joined into the frame's result.
    early: std.ArrayList(Entry) = .empty,
    /// §31.6: the field paths of outer locals this frame's body reads,
    /// which the closure reads when it is made.
    eager: std.ArrayList(Capture) = .empty,
};

const PatSite = struct { list: Inst.Index, index: u32, spread: bool, scrut: AV = &.{} };

/// What the walk learns about a function-typed parameter (§16.2).
const FnState = struct {
    need_if: std.ArrayList(u32) = .empty,
    is_fn: bool = false,
    calls: Calls = .zero,
    need: bool = false,
    /// §31.5: what it returns is a record something writes (`FunFacts.rneed`).
    rneed: bool = false,
    seen: bool = true,
    /// §23.3: handed on to a send position.
    send: u32 = none,
    /// §23.5, amended: `need` came from somewhere other than a send.
    need_edit: bool = false,
};

/// A supply to a function parameter, read off once its probe is resolved.
const SupplyRec = struct {
    frame: u32 = 0,
    fun: u32,
    k: u32,
    path: u32,
    av: AV,
    probe: u32,
    /// The callee's own `owned`, for a supply passed on (§16.4 item 4).
    owned: bool = true,
    /// The callee's own `approx`, when it supplies borrowed.
    approx: bool = false,
    /// The condition of what is supplied (§18.3).
    cond: u32 = cond_yes,
    /// Its record condition (§31.4 item 6).
    rcond: u32 = cond_yes,
    /// A destructive supply, passed on (§18.5).
    taken: bool = false,
    /// A call inside a lambda (§18.9): the probe where the lambda made the
    /// call, beside `probe`, where the lambda was handed on.
    probe2: u32 = none,
    /// §30.9: a call inside a lambda nested in others, the probes where
    /// each enclosing lambda was handed on, outermost last.
    more: []const u32 = &.{},
    /// §31.5: the probe of the records it supplies (`recordProbe`), which
    /// `probe`, a list's, does not read; none when a record supply is not
    /// owned or there is none.
    rprobe: u32 = none,
};

/// §18.9: a call of the declaration's function parameter made inside a
/// lambda, in the lambda's vocabulary, which becomes a call of the
/// parameter wherever the lambda is checked.
const EnvCall = struct {
    closure: u32,
    j: u32,
    inst: Inst.Index,
    args: []const AV,
    probes: []const u32,
    /// §30.9: a call a lambda nested in this one made, handed on here. Per
    /// argument, the probes where the inner lambdas were handed on, and
    /// whether every supply it rests on was owned or taken; and whether
    /// some lambda on the way is called more than once.
    more: []const []const u32 = &.{},
    owned: []const bool = &.{},
    taken: []const bool = &.{},
    many: bool = false,
};

/// §30.9: a callee relies on what a function it is handed returns being
/// owned (`need`, or an owned `cb` supply), and the function is the
/// enclosing lambda's own parameter, at `path`: what that is, is known only
/// where the lambda is handed on or called. The obligation waits for it.
const LambdaNeed = struct {
    closure: u32,
    k: u32,
    path: u32,
    /// The callee that relies on it, its function parameter, and the call.
    s: *const Summary,
    j: u32,
    avs: []const AV,
    inst: Inst.Index,
    callee: []const u8,
    point: u32,
    frame: u32,
    ctx: u32,
    /// Reported already: one line however many places fail it.
    failed: bool = false,
    /// How many times it was decided where the lambda was handed on or
    /// called: each of the lambda's consumers must decide it.
    discharges: u32 = 0,
};

/// A summary or class being applied at a call.
const Callee = struct {
    entry_target: ?Walker.Target = null,
    sum: *const Summary,
    /// For notes: `Main.f`, `List.update`, `<lambda>`.
    name: []const u8,
    /// The operation of a call-site demand line.
    op: []const u8,
    /// A lambda's class: its closure, whose captures `◇` names.
    closure: u32 = none,
    /// A member of the recursive group being solved (§16.6).
    merge_fresh: bool = false,
    /// §16.7: the declared types of a member's parameters, when the call is
    /// inside the group being solved; empty otherwise.
    poly: []const ?Var = &.{},
};

const Walker = struct {
    o: *Ownership,
    m: u32,
    bir: *const Bir,
    decl: Bir.Decl,
    decl_index: u32,
    store: *TypeStore,
    inst_type: []const Var.Optional,
    local_type: []const Var.Optional,
    a: Allocator,
    mode: Mode,
    /// The declaration is in a recursive group (§16.6).
    recursive: bool = false,

    point: u32 = 0,
    cast_open_used: bool = false,
    cast_ordinals: []const u32 = &.{},
    cast_vars: []u32 = &.{},
    cast_seen: []bool = &.{},
    cast_next: u32 = 0,
    cast_seeded: bool = false,
    // Exact specialization and the alternative composed-type fold for this
    // call. Nested evaluations save and restore the call's alternatives.
    // A nested call has its own sparse set of paths. Share the table across
    // calls, keyed by both the call scope and the session path identity.
    cast_fold_paths: std.AutoHashMapUnmanaged(CastFoldKey, u32) = .empty,
    cast_fold_types: std.AutoHashMapUnmanaged(CastFoldKey, u32) = .empty,
    cast_fold_scope: u32 = 0,
    cast_fold_next: u32 = 0,

    cast_crossings: std.AutoHashMapUnmanaged(CastCross, void) = .empty,
    cast_growing: []const u32 = &.{},
    cast_fold_mode: bool = false,
    cast_defs: std.AutoHashMapUnmanaged([4]usize, u32) = .empty,
    cast_plan_types: std.AutoHashMapUnmanaged([4]usize, u32) = .empty,
    cast_envs: std.HashMapUnmanaged([]const u32, []const TyRef, U32SliceContext, std.hash_map.default_max_load_percentage) = .empty,

    cast_subst_types: std.ArrayList(u32) = .empty,
    cast_subst_paths: std.ArrayList(u32) = .empty,
    cast_subst_touched_types: std.ArrayList(u32) = .empty,
    cast_subst_touched_paths: std.ArrayList(u32) = .empty,
    cells: std.ArrayList(Cell) = .empty,
    cell_map: std.HashMapUnmanaged([5]u32, u32, WordsKey(5), std.hash_map.default_max_load_percentage) = .empty,
    cover_memo: std.HashMapUnmanaged([2]u32, ?Cover, WordsKey(2), std.hash_map.default_max_load_percentage) = .empty,
    /// §20.4, amended 2026-10-16 (#229): a lambda a callee's result carries
    /// is one closure per place it is made — the call, the callee's summary,
    /// the lambda, the callback depth and the entry's namespace — whatever
    /// round made it, its captures the union of every instantiation's.
    carry_sites: std.AutoHashMapUnmanaged(CarrySite, u32) = .empty,
    /// Bumped whenever a carried closure's captures grow: a fixpoint over
    /// cells has not settled while it moves.
    carry_grew: u32 = 0,
    local_av: []?AV = &.{},
    local_frame: []u32 = &.{},
    local_ctx: []u32 = &.{},
    pat_site: []?PatSite = &.{},
    frames: std.ArrayList(Frame) = .empty,
    frame: u32 = 0,
    ctx_nodes: std.ArrayList(CtxNode) = .empty,
    ctx: u32 = 0,
    cases: u32 = 0,
    /// §7.2 as amended for slice 3f: the `Maybe.withDefault (Maybe.map m f) d`
    /// being walked, and the context of each of its two outcomes.
    maybe_join: ?MaybeJoin = null,
    pending: std.ArrayList(Pending) = .empty,
    uses: std.ArrayList(Use) = .empty,
    demands: std.ArrayList(DemandRec) = .empty,
    escaped: std.ArrayList(Escape) = .empty,
    /// Esc by cell: the earliest point each cell escaped (§18.11).
    esc_index: std.AutoHashMapUnmanaged([4]u32, EscAt) = .empty,
    esc_heads: std.AutoHashMapUnmanaged([4]u32, u32) = .empty,
    closures: std.ArrayList(Closure) = .empty,
    /// Per instruction of the declaration: a lambda parameter's pattern's
    /// closure and position, `none` elsewhere.
    pat_closure: [][2]u32 = &.{},
    /// The declaration's parameters.
    params: []const Inst.Index = &.{},
    /// Per function parameter, then per function slot (§24.9): a function
    /// stored at a path of a parameter, `slot_keys[j - params.len]`.
    fn_state: std.ArrayList(FnState) = .empty,
    slot_keys: std.ArrayList([2]u32) = .empty,
    supplies: std.ArrayList(SupplyRec) = .empty,
    probe_ok: std.ArrayList(bool) = .empty,
    /// Per probe: a record's (§31.4 item 4), which a list's once closure's
    /// decision does not read.
    probe_record: std.ArrayList(bool) = .empty,
    /// Per probe: failed for an approximate reason only.
    probe_approx: std.ArrayList(bool) = .empty,
    /// Per probe: its resolved line, for a once closure's report (§18.8).
    probe_info: std.ArrayList(?Demand) = .empty,
    result_av: AV = &.{},
    /// Per local: 1 for a local function of the `let` being created, 2 once
    /// it is named before its class exists (§16.5); 0 otherwise.
    early: []u8 = &.{},
    /// The writing top-level functions already reported out of sight: one
    /// line where each first leaves it (§16.5).
    unseen_funcs: std.AutoHashMapUnmanaged(u64, void) = .empty,
    /// §23.4: per instruction, whether it is the parameter pattern of a lambda
    /// written at a send position: a send value.
    send_params: []bool = &.{},
    /// `returnsOwned` reads only exact result entries: whether a failure was
    /// an approximate step's alone.
    ro_exact: bool = false,
    /// §30.9: the closure of the class `returnsOwned` is reading, when it
    /// is a lambda: what its calls of a carried function value return.
    ro_closure: u32 = none,
    /// §30.9: the path of the class's result that is handed on, when only a
    /// part of it is (`cb_j.q`): its other paths are not looked at.
    ro_within: u32 = eps,
    /// §18.2: the conditions, by index (`cond_yes`, `cond_lost` and
    /// `cond_shared` first), and the condition of each list cell that has
    /// one other than its kind's.
    conds: std.ArrayList(WCond) = .empty,
    cell_cond: std.ArrayList(u32) = .empty,
    /// Immutable atom sequences share an identity; joining the same facts
    /// must not count as a write that invalidates result-condition memos.
    cond_map: std.HashMapUnmanaged([]const WAtom, u32, CondKey, std.hash_map.default_max_load_percentage) = .empty,

    /// §31.4 item 6: the record conditions, a table of their own that no
    /// list's fact reads, and each cell's; what frames relied on of them.
    rconds: std.ArrayList(WCond) = .empty,
    cell_rcond: std.ArrayList(u32) = .empty,
    /// §16.7 (#693): the groups of each `apart` atom, by its `a`, interned
    /// so that one fact is one atom. Never shrunk: an index stays valid.
    aparts: std.ArrayList([]const []const u32) = .empty,
    apart_map: std.StringHashMapUnmanaged(u32) = .empty,
    rreqs: std.ArrayList(Req) = .empty,
    /// Per cell, whether it may hold a record (`mayHoldRecord`): 0 not yet
    /// asked, 1 no, 2 yes. A cell's type does not change.
    cell_rec: std.ArrayList(u8) = .empty,
    /// Per cell, its `rbase` once asked (#684), or `none`: the cell it
    /// names depends only on cells, which never change once made.
    cell_rbase: std.ArrayList(u32) = .empty,
    cell_spine: std.ArrayList(u32) = .empty,
    /// §31.2: the exception sets of `except` cells, each sorted, by index.
    exsets: std.ArrayList([]const u32) = .empty,
    /// Interns `exsets` by content: each key is the bytes of the very slice
    /// `exsets` holds, owned by the walk's arena `a`, so a key lives as long
    /// as its set and is never freed apart from it.
    exset_map: std.StringHashMapUnmanaged(u32) = .empty,
    /// §18.4: every atom relied on.
    reqs: std.ArrayList(Req) = .empty,
    /// Per call of a function parameter: its arguments, so that a cell made
    /// here and passed to the call is known to be what it may return.
    cb_args: []?AV = &.{},
    /// While a call is applied a pessimistic summary (§16.7): what it
    /// rejects follows from the limit, so it takes the `limit` cause and is
    /// not a second error beside the limit's (#272).
    limit_callee: bool = false,
    /// The uses of the summary whose call-site demands `applySummary` is
    /// making (§16.7): the callee's other places of a written argument.
    call_uses: []const UseEntry = &.{},
    /// The closures of the local groups being solved (§18.7), for §16.7's
    /// polymorphic-recursion fold.
    solving_locals: std.ArrayList([2]u32) = .empty,
    /// The call `applySummary` is making, when its callee is a member of a
    /// group being solved: its declared parameter types and the arguments'
    /// types (§16.7, F3 as amended).
    call_poly: ?struct { inst: Inst.Index, s: *const Summary, poly: []const ?Var, arg_types: []const ?Var } = null,
    /// How many times a condition table changed (`noteWrite`), by table:
    /// the cells' deep conditions, their spines, and anything else a kept
    /// instantiation may read (a callback, a restore). An `instRes` keeps a
    /// deep condition it instantiated while the counts it reads stay as
    /// they were (`instXSumOnce`).
    cond_writes: u64 = 0,
    spine_writes: u64 = 0,
    other_writes: u64 = 0,
    /// The call whose summary `instRes` is instantiating: a change to one
    /// of its own result cells is not counted, since what an argument is
    /// cannot read it (`instXSumOnce`).
    writes_inst: u32 = none,
    /// §18.4 item 4: per list-pattern element, its pattern — the scope of
    /// the split's taken cells.
    split_list: []u32 = &.{},
    split_scrut: []?AV = &.{},
    /// §18.9: calls of the declaration's function parameters inside lambdas.
    env_calls: std.ArrayList(EnvCall) = .empty,
    /// §30.9: the declaration's function parameters and slots a lambda
    /// hands on to a callee, as `(closure, j)`, for each lambda the pass is
    /// inside: a carried lambda's calls of them go to what the caller passed.
    env_passes: std.ArrayList([2]u32) = .empty,
    /// §30.9: what callees rely on of the enclosing lambdas' own parameters.
    lambda_needs: std.ArrayList(LambdaNeed) = .empty,
    /// The record a program constructor with an entry row is handed: its
    /// functions are in sight there (§20.6), so storing them in it is not
    /// leaving the walk's sight.
    entry_arg: u32 = none,
    /// The uses by local, for `resolve` (§18.11).
    use_start: []u32 = &.{},
    use_order: []u32 = &.{},
    /// Per position of `use_order`: the end of its run of one call's uses.
    use_run_end: []u32 = &.{},
    /// §20.4: wide values indexed by first step, by their slice.
    wide: std.AutoHashMapUnmanaged([2]usize, WideIndex) = .empty,
    /// §20.4: `projPath`'s answers for a wide value with no type, by
    /// `(slice, length, path)`.
    projected: std.AutoHashMapUnmanaged([3]usize, AV) = .empty,
    spine_indexes: std.AutoHashMapUnmanaged([2]usize, SpineIndex) = .empty,
    record_shapes: std.AutoHashMapUnmanaged([2]usize, AV) = .empty,
    /// §28.6, a report walk only: the first and last token of what is being
    /// evaluated, and of each instruction evaluated so far — what a message
    /// underlines.
    span: [2]u32 = .{ none, 0 },
    inst_span: [][2]u32 = &.{},
    /// The variable path a use being recorded reads, as written.
    use_at: [2]u32 = .{ none, none },
    /// What `Use.call` the next uses take (§31.4 item 5).
    use_call: u8 = 0,
    use_grown: Grown = 0,
    use_call_at: u32 = eps,
    /// The use being recorded is a record pattern's scrutinee (`Use.destructure`).
    use_destructure: bool = false,
    /// The use being recorded reads no field (`Use.reads_none`).
    use_reads_none: bool = false,
    /// §31.6: captures of a record's field path read when a lambda is made.
    eager_reads: u32 = 0,
    hoist_table: Hoists.Builder = .{},
    hoist_uses: std.ArrayList(struct { use: Use, prefix: u32 }) = .empty,
    hoist_read_index: std.AutoHashMapUnmanaged([4]u32, u32) = .empty,
    current_inst: u32 = none,
    inst_parent: []u32 = &.{},

    eager_seen: std.AutoHashMapUnmanaged([3]u32, void) = .empty,
    /// §31.3: a closed update's split of one base cell, per field of
    /// its record type, by `(cell, fields)`: whether the field is tracked,
    /// and the cell and path it projects to. Each field is computed the
    /// first time an update needs it, so cells and paths are interned in
    /// the order the unshared walk interns them (#716).
    split_memo: std.AutoHashMapUnmanaged([3]usize, *SplitMemo) = .empty,
    /// §31.3 (#825): the values an update or a join made of a split, by
    /// address, so that a join of them merges what they do not share
    /// rather than every entry of each (`unionOf`).
    split_values: std.AutoHashMapUnmanaged(usize, SplitValue) = .empty,
    /// The locals bound so far, in binding order, without those bound in
    /// an earlier arm of a `case` whose later arm is being walked: those
    /// are never compatible with where the walk is (`compatible`), so a
    /// demand's holders are looked for among the rest (#716). Superset of
    /// the bound locals compatible with `ctx`; a restore leaves stale and
    /// repeated entries, which the readers filter.
    bound_log: std.ArrayList(u32) = .empty,
    /// Whether `bound_log` is kept: in a declaration with more locals
    /// than `holder_scan_max`; a scan of every local costs less below.
    logs_bindings: bool = false,
    holder_buf: std.ArrayList(u32) = .empty,
    /// Per cell, the read-off (`obj_gen`) that numbered it as a record
    /// object, and its number (`objectNumber`): a column, not a list to scan.
    obj_number: std.ArrayList([2]u32) = .empty,
    obj_gen: u32 = 0,
    /// `uses.items.len` when each `case` (by `case_id`) finished: a use
    /// recorded after a demand, in an arm of a case other than the
    /// demand's, and every use until the case ends, are in the case's
    /// other arms (`resolveRaw`, #716).
    case_end: std.ArrayList(u32) = .empty,

    // ---- setup -------------------------------------------------------------

    fn walkDecl(w: *Walker, body: Inst.Index) Allocator.Error!void {
        try w.o.seedPaths();
        const n = w.decl.locals_end - w.decl.locals_start;
        w.local_av = try w.a.alloc(?AV, n);
        w.logs_bindings = n > holder_scan_max;
        @memset(w.local_av, null);
        w.local_frame = try w.a.alloc(u32, n);
        @memset(w.local_frame, 0);
        w.local_ctx = try w.a.alloc(u32, n);
        @memset(w.local_ctx, 0);
        w.pat_site = try w.a.alloc(?PatSite, n);
        @memset(w.pat_site, null);
        w.early = try w.a.alloc(u8, n);
        @memset(w.early, 0);
        const insts = w.decl.inst_end.int() - w.decl.inst_start.int();
        w.pat_closure = try w.a.alloc([2]u32, insts);
        w.cb_args = try w.a.alloc(?AV, insts);
        @memset(w.cb_args, null);
        w.split_list = try w.a.alloc(u32, insts);
        @memset(w.split_list, none);
        w.split_scrut = try w.a.alloc(?AV, insts);
        @memset(w.split_scrut, null);
        @memset(w.pat_closure, .{ none, none });
        w.send_params = try w.a.alloc(bool, insts);
        @memset(w.send_params, false);
        if (w.mode == .report) {
            w.inst_parent = try w.a.alloc(u32, insts);
            @memset(w.inst_parent, none);
            w.inst_span = try w.a.alloc([2]u32, insts);
            @memset(w.inst_span, .{ none, none });
        }
        try w.ctx_nodes.append(w.a, .{ .parent = none, .case_id = none, .arm = 0, .depth = 0 });
        try w.frames.append(w.a, .{ .parent = none, .pending_base = 0 });
        try w.conds.appendSlice(w.a, &fixed_conds);
        try w.rconds.appendSlice(w.a, &fixed_conds);
        w.params = w.bir.extraSlice(.{ .start = w.decl.params_start, .end = w.decl.params_end }, Inst.Index);
        try w.fn_state.appendNTimes(w.a, .{}, w.params.len);
        for (w.params, 0..) |p, i| {
            if (w.patternType(p)) |v| w.fn_state.items[i].is_fn = isFunc(w.store, v);
            try w.bindParam(p, 0);
        }
        if (w.recursive) {
            const previous = w.o.slots[w.m].?[w.decl_index].sum.slots;
            try w.slot_keys.appendSlice(w.a, previous);
            try w.fn_state.appendNTimes(w.a, .{ .is_fn = true }, previous.len);
        }
        const result = try w.withEarly(0, try w.eval(body));
        try w.consume(&.{body}, w.bir.insts.items(.main_token)[body.int()]);
        try w.sight(result, .{ .pending = "it is returned" }, w.token(body));
        w.result_av = result;
    }

    fn bindParam(w: *Walker, pat: Inst.Index, lambda: u32) Allocator.Error!void {
        const ty = w.patternType(pat);
        if (ty) |v| if (!try w.trackedVar(v)) return w.bindPattern(pat, &.{});
        const c = try w.cell(.{ .kind = .param, .a = pat.int(), .b = lambda, .ty = if (ty) |v| v.toOptional() else .none });
        const av = try w.a.dupe(Entry, &.{.{ .path = eps, .cell = c }});
        try w.bindPattern(pat, av);
    }

    fn patternType(w: *const Walker, pat: Inst.Index) ?Var {
        return switch (w.bir.instTag(pat)) {
            .pat_var => w.localType(w.bir.instData(pat).lhs),
            .pat_as => w.localType(w.bir.instData(pat).rhs),
            else => null,
        };
    }

    fn localType(w: *const Walker, l: u32) ?Var {
        if (l >= w.local_type.len) return null;
        return w.local_type[l].unwrap();
    }

    fn instType(w: *const Walker, inst: Inst.Index) ?Var {
        if (inst.int() >= w.inst_type.len) return null;
        return w.inst_type[inst.int()].unwrap();
    }

    /// A column over the declaration's instructions, at instruction `i`.
    fn instCol(w: *const Walker, comptime T: type, col: []const T, i: u32, default: T) T {
        const at = i -% w.decl.inst_start.int();
        return if (at < col.len) col[at] else default;
    }

    fn cell(w: *Walker, c: Cell) Allocator.Error!u32 {
        // `nonlist` is in the key: a record object a definition names on
        // purpose (a top-level record's, `Record.copy`'s) is never the cell
        // a summary's result made at the same place, whichever comes first.
        const key: [5]u32 = .{ @as(u32, @backingInt(c.kind)) | (@as(u32, @intFromBool(c.made)) << 8) | (@as(u32, @intFromBool(c.nonlist)) << 9) | (@as(u32, @intFromBool(c.condition_only)) << 10), c.a, c.b, c.path, c.scope };
        const gop = try w.cell_map.getOrPut(w.a, key);
        if (gop.found_existing) return gop.value_ptr.*;
        const id: u32 = @intCast(w.cells.items.len);
        gop.value_ptr.* = id;
        var made = c;
        made.nonlist = !c.condition_only and (c.nonlist or c.kind == .except or w.isRecordCell(c) or try w.holdsOnlyRecords(c));
        try w.cells.append(w.a, made);
        try w.cell_cond.append(w.a, none);
        try w.cell_rcond.append(w.a, none);
        try w.cell_rec.append(w.a, 0);
        try w.cell_rbase.append(w.a, none);
        try w.cell_spine.append(w.a, none);
        return id;
    }

    /// §31.2: whether `c` stands only for what §31.2's amendment made a cell:
    /// a value whose type holds records and, by the crossing rule before it,
    /// nothing else — no list, function or JavaScript value. Read at the
    /// cell's path from its root's type, so that a record object is a
    /// list's nothing at ε and below alike: through a field, a tuple's
    /// part, a list's element, and a constructor's field as its declaration
    /// writes it (one that names a type parameter is a list's, since the
    /// argument decides). A taken element is the element it was taken from.
    ///
    /// The type is one the cell's key decides, since `nonlist` is set once
    /// for the key: a parameter's pattern's, a site's or a call result's
    /// instruction's, at the root; a capture's local's. A top-level value's
    /// cell is made at the type of the read that names it, which a
    /// polymorphic value varies, so it stays a list's.
    fn holdsOnlyRecords(w: *Walker, c: Cell) Allocator.Error!bool {
        if (c.kind == .taken) return w.cells.items[c.a].nonlist;
        var from: usize = 0;
        var v: Var = switch (c.kind) {
            .param, .site, .result, .cbres => blk: {
                // A type the cell was made with is its path's own: these
                // roots' types are their keys'.
                if (c.ty.unwrap()) |t| return try w.trackedVar(t) and !try w.listTrackedVar(t);
                if (c.path == eps) return false;
                // The nearest cell above it that was made with a type: a
                // pattern's variable binds the cell at its path with its own.
                var up = w.o.paths.parent.items[c.path];
                while (true) {
                    const key: [5]u32 = .{ @as(u32, @backingInt(c.kind)) | (@as(u32, @intFromBool(c.made)) << 8), c.a, c.b, up, c.scope };
                    if (w.cell_map.get(key)) |id| {
                        if (w.cells.items[id].nonlist) return true;
                        if (w.cells.items[id].ty.unwrap()) |t| {
                            from = w.o.paths.depth.items[up];
                            break :blk t;
                        }
                    }
                    if (up == eps) break;
                    up = w.o.paths.parent.items[up];
                }
                // A parameter's pattern, or a site's or a call's instruction,
                // has its own type when its root cell was made without one.
                if (c.kind != .cbres) if (w.instType(@fromBackingInt(c.a))) |t| break :blk t;
                return false;
            },
            .env => w.localType(c.a) orelse return false,
            .shared, .top, .closure, .func, .payload, .except, .taken => return false,
        };
        const path_steps = w.o.steps(c.path);
        for (path_steps[from..], from..) |s, si| {
            // A constructor's field, and what is below it, as its declaration
            // writes them (`birHoldsOnlyRecords`), whatever the root's type
            // resolves to.
            if (s.kind == .ctor) return w.o.birHoldsOnlyRecords(path_steps[si..]);
            const st = switch (w.store.resolvedContent(v)) {
                .structure => |x| x,
                else => return false,
            };
            switch (s.kind) {
                .field => v = w.fieldVar(v, s.arg) orelse return false,
                .tuple => switch (st) {
                    .tuple => |r| {
                        const els = w.store.vars(r);
                        if (s.arg >= els.len) return false;
                        v = els[s.arg];
                    },
                    else => return false,
                },
                .elem => switch (st) {
                    .app => |a| {
                        if (a.type != w.o.in.types.well_known.list) return false;
                        const args = w.store.vars(a.args);
                        if (args.len != 1) return false;
                        v = args[0];
                    },
                    else => return false,
                },
                else => return false,
            }
        }
        return try w.trackedVar(v) and !try w.listTrackedVar(v);
    }

    fn token(w: *const Walker, inst: Inst.Index) u32 {
        return w.bir.insts.items(.main_token)[inst.int()];
    }

    fn pos(w: *const Walker, tok: u32) Position {
        return w.o.in.positions.get(w.o.in.positions.ctx, w.m, tok);
    }

    // ---- abstract values ---------------------------------------------------

    /// Sorted and deduplicated, in place: every caller hands over an array
    /// of its own.
    fn norm(w: *Walker, items: []Entry) Allocator.Error!AV {
        _ = w;
        if (items.len <= 1) return items;
        std.mem.sort(Entry, items, {}, struct {
            fn less(_: void, x: Entry, y: Entry) bool {
                if (x.path != y.path) return x.path < y.path;
                if (x.cell != y.cell) return x.cell < y.cell;
                return x.approx < y.approx;
            }
        }.less);
        var n: usize = 1;
        for (items[1..]) |e| {
            const last = items[n - 1];
            if (last.path == e.path and last.cell == e.cell) {
                // §16.7: one entry per place and cell; a mark on either is kept.
                items[n - 1].grown = gJoin(last.grown, e.grown);
                continue;
            }
            items[n] = e;
            n += 1;
        }
        return items[0..n];
    }

    fn unionOf(w: *Walker, parts: []const AV) Allocator.Error!AV {
        if (parts.len >= 2 and w.split_values.count() != 0) if (try w.unionSplit(parts)) |got| return got;
        var total: usize = 0;
        for (parts) |p| total += p.len;
        if (total <= union_merge_min or parts.len <= union_merge_parts) {
            var all: std.ArrayList(Entry) = .empty;
            for (parts) |p| try all.appendSlice(w.a, p);
            return w.norm(all.items);
        }
        // `norm`'s answer — one entry per path and cell, its least `approx`
        // and every `grown` joined, by path and cell — by merging the parts,
        // each in that form already or put in it, two by two: a `case` over
        // a wide model joins its arms' wide values, which are mostly the
        // same entries, and a sort of all of them costs a log more (#716).
        var runs: std.ArrayList(AV) = .empty;
        for (parts) |p| {
            if (p.len == 0) continue;
            try runs.append(w.a, if (isNormal(p)) p else try w.norm(try w.a.dupe(Entry, p)));
        }
        while (runs.items.len > 1) {
            var n: usize = 0;
            var i: usize = 0;
            while (i < runs.items.len) : (i += 2) {
                runs.items[n] = if (i + 1 < runs.items.len) try w.mergeNormal(runs.items[i], runs.items[i + 1]) else runs.items[i];
                n += 1;
            }
            runs.items.len = n;
        }
        // An array of its own, as `norm`'s is.
        const got: AV = if (runs.items.len == 0) &.{} else try w.a.dupe(Entry, runs.items[0]);
        if (std.debug.runtime_safety and @import("ownership_options").full_cross_check) {
            var all: std.ArrayList(Entry) = .empty;
            for (parts) |p| try all.appendSlice(w.a, p);
            const want = try w.norm(all.items);
            std.debug.assert(want.len == got.len);
            for (want, got) |x, y| std.debug.assert(std.meta.eql(x, y));
        }
        return got;
    }

    /// Whether `av` is in `norm`'s form: strictly ascending by path and cell.
    fn isNormal(av: AV) bool {
        if (av.len < 2) return true;
        for (av[1..], 0..) |e, i| {
            const d = av[i];
            if (d.path > e.path or (d.path == e.path and d.cell >= e.cell)) return false;
        }
        return true;
    }

    /// Two values in `norm`'s form, as one: an entry in both keeps the
    /// lesser `approx` and both `grown` marks.
    fn mergeNormal(w: *Walker, x: AV, y: AV) Allocator.Error!AV {
        const out = try w.a.alloc(Entry, x.len + y.len);
        var i: usize = 0;
        var j: usize = 0;
        var n: usize = 0;
        while (i < x.len and j < y.len) {
            const a = x[i];
            const b = y[j];
            if (a.path < b.path or (a.path == b.path and a.cell < b.cell)) {
                out[n] = a;
                i += 1;
            } else if (b.path < a.path or (b.path == a.path and b.cell < a.cell)) {
                out[n] = b;
                j += 1;
            } else {
                out[n] = .{ .path = a.path, .cell = a.cell, .approx = @min(a.approx, b.approx), .grown = gJoin(a.grown, b.grown) };
                i += 1;
                j += 1;
            }
            n += 1;
        }
        @memcpy(out[n..][0 .. x.len - i], x[i..]);
        n += x.len - i;
        @memcpy(out[n..][0 .. y.len - j], y[j..]);
        n += y.len - j;
        return out[0..n];
    }

    fn shift(w: *Walker, av: AV, s: Step) Allocator.Error!AV {
        const out = try w.a.alloc(Entry, av.len);
        for (av, out) |e, *x| x.* = .{ .path = try w.o.prepend(s, e.path), .cell = e.cell, .approx = e.approx, .grown = e.grown };
        try w.foldedBeside(av, out);
        return w.norm(out);
    }

    /// §16.7: a value placed one step down, where a fold put two of its
    /// places at one marked path: the path stands for both, and no later
    /// deep condition sees them apart. So their cells' conditions say it
    /// now, as `storedBeside` does for a construction's arguments: two
    /// cells there are separate, and one cell at both is one list at two
    /// places, exactly when both entries are, else approximately.
    fn foldedBeside(w: *Walker, before: AV, after: []const Entry) Allocator.Error!void {
        // Two places become one only where the fold shortened a path: a
        // step prepended adds one to every path it does not fold.
        const folded = for (before, after) |b, x| {
            if (w.o.paths.depth.items[x.path] != w.o.paths.depth.items[b.path] + 1) break true;
        } else false;
        if (!folded) return;
        return w.foldedPairs(before, after);
    }

    /// `foldedBeside`'s pairs: two entries `after` puts at one marked
    /// path from two paths `before`, as a fold of instantiation does too
    /// (§16.7, F3 as amended).
    fn foldedPairs(w: *Walker, before: AV, after: []const Entry) Allocator.Error!void {
        // Only equal destination paths can merge. Keep source order inside
        // each bucket, so lowering the cells' conditions has the same order
        // as the pairwise walk, without comparing unrelated destinations.
        const order = try w.a.alloc(u32, after.len);
        for (order, 0..) |*x, i| x.* = @intCast(i);
        std.mem.sort(u32, order, after, struct {
            fn less(items: []const Entry, i: u32, j: u32) bool {
                return items[i].path < items[j].path or (items[i].path == items[j].path and i < j);
            }
        }.less);
        const ends = try w.a.alloc([2]usize, after.len);
        var start: usize = 0;
        while (start < order.len) {
            var end = start + 1;
            while (end < order.len and after[order[end]].path == after[order[start]].path) : (end += 1) {}
            const different = for (order[start + 1 .. end]) |j| {
                if (before[j].path != before[order[start]].path) break true;
            } else false;
            for (order[start..end], start..) |i, at| ends[i] = if (different) .{ at + 1, end } else .{ end, end };
            start = end;
        }
        for (after, 0..) |e, i| {
            if (!w.o.paths.any.items[e.path]) continue;
            for (order[ends[i][0]..ends[i][1]]) |j| {
                const f = after[j];
                if (before[i].path == before[j].path) continue;

                // What the value's deep condition says of the pair before the
                // fold, which no deep condition can say after it.
                if (try w.nested(before[i], before[j])) continue;
                if (w.cells.items[e.cell].condition_only or w.cells.items[f.cell].condition_only) continue;
                const ke = w.cells.items[e.cell].kind;
                const kf = w.cells.items[f.cell].kind;
                if (ke == .closure or ke == .func or kf == .closure or kf == .func) continue;
                if (e.cell == f.cell) {
                    // A symbolic cell that stands for several places is two
                    // of them when its argument is exclusive there; any other
                    // cell at both is one list at two places.
                    const k: u32 = (try w.apartCond(e.cell)) orelse try w.sepCells(e.cell, f.cell, e.approx == 0 and f.approx == 0);
                    try w.lowerCond(e.cell, k);
                    try w.lowerSpine(e.cell, k);
                    // §31.4 item 6: one record at two places, folded to one.
                    try w.rlowerCond(e.cell, try w.rsepCells(e.cell, f.cell, e.approx == 0 and f.approx == 0));
                    continue;
                }
                const k = try w.sepCells(e.cell, f.cell, e.approx == 0 and f.approx == 0);
                try w.lowerCond(e.cell, k);
                try w.lowerCond(f.cell, k);
                const rk = try w.rsepCells(e.cell, f.cell, e.approx == 0 and f.approx == 0);
                try w.rlowerCond(e.cell, rk);
                try w.rlowerCond(f.cell, rk);
                const sk = try w.sepSpines(e.cell, f.cell, e.approx == 0 and f.approx == 0);
                try w.lowerSpine(e.cell, sk);
                try w.lowerSpine(f.cell, sk);
            }
        }
    }

    /// `av` placed under the path `p`.
    fn under(w: *Walker, av: AV, p: u32) Allocator.Error!AV {
        if (p == eps) return av;
        const out = try w.a.alloc(Entry, av.len);
        for (av, out) |e, *x| x.* = .{ .path = try w.o.concat(p, e.path), .cell = e.cell, .approx = e.approx, .grown = e.grown };
        return w.norm(out);
    }

    fn approxAll(w: *Walker, av: AV, inst: Inst.Index) Allocator.Error!AV {
        const out = try w.a.alloc(Entry, av.len);
        for (av, out) |e, *x| x.* = .{ .path = e.path, .cell = e.cell, .approx = if (e.approx != 0) e.approx else inst.int() + 1, .grown = e.grown };
        return out;
    }

    /// A symbolic cell one step further down (§4.3).
    fn projCell(w: *Walker, c: u32, s: Step, ty: ?Var) Allocator.Error!?u32 {
        const x = w.cells.items[c];
        if (x.condition_only) return w.projectSpineGuard(c, s, ty);
        // §30.10: a schema's slot. A callee with a summary named every cell
        // it put there; a call with none may have put anything.
        if (s.kind == .schema_decoded or s.kind == .schema_encoded) if (x.kind == .result) {
            return if (x.b == 0) try w.cell(.{ .kind = .top, .a = unfollowed }) else null;
        };
        switch (x.kind) {
            .site, .closure, .func => return null,
            .top => return c,
            // §31.2: a field the update wrote is no longer the base's.
            .except => {
                if (x.b == except_all) return null;
                if (s.kind == .field and std.mem.indexOfScalar(u32, w.exsets.items[x.b], s.arg) != null) return null;
                return w.projCell(x.a, s, ty);
            },
            // What a definition made holds nothing its summary does not name.
            .shared => if (x.made) return null else {
                var y = x;
                y.path = try w.o.child(x.path, s.kind, s.arg);
                y.ty = if (ty) |v| v.toOptional() else .none;
                return try w.cell(y);
            },
            .param, .result, .env, .cbres, .taken, .payload => {
                var y = x;
                y.path = try w.o.child(x.path, s.kind, s.arg);
                y.ty = if (ty) |v| v.toOptional() else .none;
                return try w.cell(y);
            },
        }
    }

    fn proj(w: *Walker, av: AV, s: Step, ty: ?Var) Allocator.Error!AV {
        if (s.kind == .cast) return w.readCast(av, s.arg);
        if (s.kind == .cast_level) return w.readCastLevel(av, s.arg);
        if (ty) |v| if (!try w.trackedVar(v)) return &.{};
        // A type that folds with no marker (core Dict's tree) keeps what
        // folding put at its levels below, as #341 did: at the same path
        // when the field is a value of the type itself, anywhere when it is
        // further down (§16.7).
        const unmarked: ?u64 = if (s.kind == .ctor) if (w.o.ctorType(w.o.stepCtor(s.arg))) |t| (if (try w.o.dictTree(t) and try w.o.levelOf(s.arg) != .none) t else null) else null else null;
        const here = unmarked != null and try w.o.levelOf(s.arg) == .here;
        const any = if (unmarked != null and !here) try w.o.child(eps, .any, 0) else eps;
        var out: std.ArrayList(Entry) = .empty;
        for (av) |e| try w.projEntry(&out, e, s, ty, unmarked, here, any);
        return w.norm(out.items);
    }

    /// `proj`'s work on one entry `e` of the value.
    inline fn projEntry(w: *Walker, out: *std.ArrayList(Entry), e: Entry, s: Step, ty: ?Var, unmarked: ?u64, here: bool, any: u32) Allocator.Error!void {
        if (e.path == eps) {
            if (try w.projCell(e.cell, s, ty)) |c| try out.append(w.a, .{ .path = eps, .cell = c, .approx = e.approx, .grown = gStep(e.grown) });
            return;
        }
        const first = w.o.firstStep(e.path).?;
        if (analysisStep(s.kind) and (first.kind == .cast or first.kind == .cast_level)) return;
        if (first.kind == .cast) {
            var kept = e;
            kept.path = try w.o.child(eps, .any, 1);
            if (kept.approx == 0) kept.approx = approx_place;
            try out.append(w.a, kept);
            return;
        }
        if (first.kind == .cast_level) {
            var kept = e;
            kept.approx = if (e.approx != 0) e.approx else approx_place;
            try out.append(w.a, kept);
            return;
        }
        if (first.kind == .any) {
            if (first.arg == 1 and analysisStep(s.kind)) return;
            try out.append(w.a, e);
            return;
        }
        if (first.kind == s.kind and first.arg == s.arg) {
            try out.append(w.a, .{ .path = try w.o.dropFirst(e.path), .cell = e.cell, .approx = e.approx, .grown = gDropGuard(e.grown, w.o.paths.depth.items[e.path]) });
        }
        if (unmarked) |t| if (first.kind == .ctor and w.o.ctorType(w.o.stepCtor(first.arg)) == t) {
            try out.append(w.a, .{ .path = if (here) e.path else any, .cell = e.cell, .approx = if (e.approx != 0) e.approx else approx_place, .grown = e.grown });
            return;
        };
        if (first.kind == s.kind and first.arg == s.arg) return;
        if (first.kind == .level) {
            try w.underMarker(out, e, first, s);
        } else if (s.kind == .level) {
            try w.alongMarker(out, e, s.arg);
        }
    }

    /// `proj(idx.av, s, null)`, through the index (#825). A marker step, or
    /// a constructor step of a type that folds, reads every entry, and is
    /// the scan.
    fn projIndexed(w: *Walker, idx: *StepIndex, s: Step) Allocator.Error!AV {
        if (analysisStep(s.kind) or s.kind == .cast or s.kind == .cast_level or s.kind == .level or (s.kind == .ctor and try w.o.levelOf(s.arg) != .none)) return w.proj(idx.av, s, null);
        if (!idx.built) {
            idx.built = true;
            for (idx.av, 0..) |e, i| {
                if (e.path != eps) {
                    const first = w.o.firstStep(e.path).?;
                    if (first.kind != .any and first.kind != .level and first.kind != .cast and first.kind != .cast_level) {
                        const g = try idx.by.getOrPut(w.a, .{ @backingInt(first.kind), first.arg });
                        if (!g.found_existing) g.value_ptr.* = .empty;
                        try g.value_ptr.append(w.a, @intCast(i));
                        continue;
                    }
                }
                try idx.always.append(w.a, @intCast(i));
            }
        }
        const keyed: []const u32 = if (idx.by.getPtr(.{ @backingInt(s.kind), s.arg })) |l| l.items else &.{};
        const always = idx.always.items;
        var out: std.ArrayList(Entry) = .empty;
        // The two runs of positions, merged: the scan's order.
        var i: usize = 0;
        var j: usize = 0;
        while (i < always.len or j < keyed.len) {
            const at = if (j == keyed.len or (i < always.len and always[i] < keyed[j])) blk: {
                i += 1;
                break :blk always[i - 1];
            } else blk: {
                j += 1;
                break :blk keyed[j - 1];
            };
            try w.projEntry(&out, idx.av[at], s, null, null, false, eps);
        }
        if (wide_ways) {
            // What the merge skipped is what the scan does nothing with.
            const visited = try w.a.alloc(bool, idx.av.len);
            @memset(visited, false);
            for (always) |at| visited[at] = true;
            for (keyed) |at| visited[at] = true;
            for (idx.av, visited) |e, v| if (!v) {
                const first = w.o.firstStep(e.path).?;
                std.debug.assert(first.kind != .any and first.kind != .level and first.kind != .cast and first.kind != .cast_level and !(first.kind == s.kind and first.arg == s.arg));
            };
        }
        return w.norm(out.items);
    }

    /// `projPath(idx.av, p, null)` through the index, for a value at least
    /// `step_index_min` wide and narrower than `wide_index`; any other the
    /// way `projPath` takes it.
    fn projPathVia(w: *Walker, idx: *StepIndex, p: u32) Allocator.Error!AV {
        const av = idx.av;
        if (p == eps or av.len < step_index_min or av.len >= wide_index) return w.projPath(av, p, null);
        const st = w.o.steps(p);
        var at = try w.projIndexed(idx, st[0]);
        for (st[1..]) |x| at = try w.proj(at, x, null);
        return at;
    }

    /// Argument `a` of the instantiation `ctx` projected along `p`: through
    /// its `StepIndex` when the instantiation's maker keeps one.
    fn projArg(w: *Walker, ctx: InstCtx, a: u32, p: u32) Allocator.Error!AV {
        const av = ctx.avs[a];
        const ai = ctx.args orelse return w.projPath(av, p, null);
        if (ai.avs.ptr != ctx.avs.ptr or ai.avs.len != ctx.avs.len) return w.projPath(av, p, null);
        if (p == eps or av.len < step_index_min or av.len >= wide_index) return w.projPath(av, p, null);
        if (ai.of.len == 0) {
            ai.of = try w.a.alloc(StepIndex, ai.avs.len);
            for (ai.of, ai.avs) |*x, v| x.* = .{ .av = v };
        }
        return w.projPathVia(&ai.of[a], p);
    }

    /// §16.7: an entry `⟨T⟩r` stands for the places `r` of every `T` at
    /// or below the value's root. Along a step `s` it is kept whole when
    /// the field `s` reaches may hold a `T`, and at the rest of `r` when
    /// `r` begins with `s` (the root is one of the `T`s); both
    /// approximately.
    fn underMarker(w: *Walker, out: *std.ArrayList(Entry), e: Entry, first: Step, s: Step) Allocator.Error!void {
        const t = w.o.markerType(first.arg);
        // §16.7 (e): a level taken out of a recursive type's marker is one
        // the checker cannot tell from the region's other levels, however the
        // entry got there: that is what a holder found so may be.
        const ap = if (t != fn_type) approx_level else if (e.approx != 0) e.approx else approx_place;
        const r = try w.o.dropFirst(e.path);
        // Kept whole when the step may lead into the region, under a marker
        // that says where the step went: to a `T`, to a field whose `T`s
        // are further down, or, for any other step, to either.
        const t_step = if (t == fn_type) s.kind == .env else s.kind == .ctor and w.o.ctorType(w.o.stepCtor(s.arg)) == t;
        const level: Level = if (!t_step or t == fn_type) .none else try w.o.levelOf(s.arg);
        if (w.o.markerAny(first.arg) or level != .none) {
            // F1's marker is always `.maybe`: below an `◇` may be a closure.
            const kind: MarkerKind = if (t == fn_type) .maybe else if (level == .here) .at else if (level == .below) .below else .maybe;
            const kept = try w.o.concat(try w.o.child(eps, .level, try w.o.markerId(t, kind)), r);
            try out.append(w.a, .{ .path = kept, .cell = e.cell, .approx = ap, .grown = e.grown });
        }
        if (!w.o.markerEmpty(first.arg)) return;
        if (w.o.firstStep(r)) |rs| if (rs.kind == s.kind and rs.arg == s.arg) {
            try out.append(w.a, .{ .path = try w.o.dropFirst(r), .cell = e.cell, .approx = ap, .grown = e.grown });
        };
    }

    /// §16.7: a value projected along its own marker `⟨T⟩`, the `T`s at or
    /// below its root: the root may be one of them, so an entry is kept,
    /// and what a marker of `T` in its path names is at the rest after it;
    /// both approximately.
    fn alongMarker(w: *Walker, out: *std.ArrayList(Entry), e: Entry, arg: u32) Allocator.Error!void {
        const ap = if (w.o.markerType(arg) != fn_type) approx_level else if (e.approx != 0) e.approx else approx_place;
        // The root's own places, as the expansion that is empty reads them.
        if (w.o.markerEmpty(arg)) try out.append(w.a, e);
        // Where the root may not be a `T`, a place inside it may be one, at
        // a path the entry does not show.
        if (w.o.markerAny(arg)) try out.append(w.a, .{ .path = try w.o.child(eps, .any, 0), .cell = e.cell, .approx = ap, .grown = e.grown });
        const st = w.o.steps(e.path);
        for (st, 0..) |x, i| if (x.kind == .level and w.o.markerType(x.arg) == w.o.markerType(arg)) {
            var at: u32 = eps;
            for (st[i + 1 ..]) |y| at = try w.o.child(at, y.kind, y.arg);
            try out.append(w.a, .{ .path = at, .cell = e.cell, .approx = e.approx, .grown = e.grown });
            break;
        };
    }

    /// Every entry of `av` with closures expanded into what they capture,
    /// under `◇` (§4.2).
    fn expand(w: *Walker, av: AV) Allocator.Error!AV {
        return (try w.expandCond(av, false)).av;
    }

    const Expanded = struct { av: AV, k: u32 = cond_yes };

    /// `expand`, and with `judge`, the condition of what the expansion
    /// merged (§16.7, F1): the environments of closures inside closures fold
    /// onto one marked place, so two captures from two environments can land
    /// at one path, where no deep condition sees them as two. Their pair is
    /// judged here, as the deep condition would have judged it before the
    /// fold: two cells are separate, and one cell captured twice is one list
    /// at two places (or, a symbolic cell that stands for several, two of
    /// them when its argument is exclusive).
    fn expandCond(w: *Walker, av: AV, judge: bool) Allocator.Error!Expanded {
        // A value that holds no closure is its own expansion.
        for (av) |e| {
            if (w.cells.items[e.cell].kind == .closure) break;
        } else return .{ .av = av };
        var out: std.ArrayList(Entry) = .empty;
        var frames: std.ArrayList(u32) = .empty;
        var seen: std.ArrayList(u32) = .empty;
        var next_frame: u32 = 1;
        try w.expandInto(av, eps, 0, &out, &seen, if (judge) &frames else null, 0, &next_frame);
        if (!judge) return .{ .av = try w.norm(out.items) };
        // `norm` sorts in place, and `frames` follows `out`'s order.
        const normed = try w.norm(try w.a.dupe(Entry, out.items));
        // Only entries at one path can be a merged pair: sort by path and
        // look within each run.
        const order = try w.a.alloc(u32, out.items.len);
        for (order, 0..) |*o, i| o.* = @intCast(i);
        std.mem.sort(u32, order, out.items, struct {
            fn lt(items: []const Entry, x: u32, y: u32) bool {
                return items[x].path < items[y].path or (items[x].path == items[y].path and x < y);
            }
        }.lt);
        var acc: CondAcc = .{};
        for (order, 0..) |i, oi| {
            const e = out.items[i];
            if (!w.o.paths.any.items[e.path]) continue;
            for (order[oi + 1 ..]) |j| {
                const f = out.items[j];
                if (f.path != e.path) break;
                const ke = w.cells.items[e.cell].kind;
                const kf = w.cells.items[f.cell].kind;
                if (ke == .closure or ke == .func or kf == .closure or kf == .func) continue;
                if (e.cell == f.cell) {
                    if (frames.items[i] == frames.items[j]) continue;
                    if (e.approx != 0 and f.approx != 0) continue;
                    try acc.add(w, (try w.apartCond(e.cell)) orelse try w.sepCells(e.cell, f.cell, e.approx == 0 and f.approx == 0));
                    continue;
                }
                if ((try w.covers(e.cell, f.cell)) != null or (try w.covers(f.cell, e.cell)) != null) continue;
                try acc.add(w, try w.sepCells(e.cell, f.cell, e.approx == 0 and f.approx == 0));
            }
        }
        return .{ .av = normed, .k = try w.condAndAll(&acc) };
    }

    fn expandInto(w: *Walker, av: AV, prefix: u32, approx: u32, out: *std.ArrayList(Entry), seen: *std.ArrayList(u32), frames: ?*std.ArrayList(u32), frame: u32, next_frame: *u32) Allocator.Error!void {
        for (av) |e| {
            const path = try w.o.concat(prefix, e.path);
            const ap = if (approx != 0) approx else e.approx;
            try out.append(w.a, .{ .path = path, .cell = e.cell, .approx = ap, .grown = e.grown });
            if (frames) |fr| try fr.append(w.a, frame);
            const c = w.cells.items[e.cell];
            if (c.kind != .closure) continue;
            if (std.mem.indexOfScalar(u32, seen.items, c.a) != null) continue;
            try seen.append(w.a, c.a);
            const at = try w.o.child(path, .env, 0);
            for (w.closures.items[c.a].captures) |cap| {
                const held = w.local_av[cap.local] orelse continue;
                const sub = try w.projPath(held, cap.path, null);
                const f = next_frame.*;
                next_frame.* += 1;
                try w.expandInto(sub, at, ap, out, seen, frames, f, next_frame);
            }
        }
    }

    /// `av` projected along every step of `p`.
    fn projPath(w: *Walker, av: AV, p: u32, ty: ?Var) Allocator.Error!AV {
        // A value is never changed once made, and a projection only reads
        // it and interns cells: one projection of a slice along a path
        // serves every later one. A summary's conditions instantiate the
        // same argument paths once per pair of result positions (§16.3).
        // Only a wide value is keyed by its slice, as `wide` is: a narrow
        // scratch slice's memory may be reused by the arena.
        if (ty != null or p == eps or av.len < wide_index) return w.projPathRaw(av, p, ty);
        const g = try w.projected.getOrPut(w.a, .{ @intFromPtr(av.ptr), av.len, p });
        if (!g.found_existing) g.value_ptr.* = try w.projPathRaw(av, p, null);
        return g.value_ptr.*;
    }

    fn projPathRaw(w: *Walker, av: AV, p: u32, ty: ?Var) Allocator.Error!AV {
        var at = av;
        const s = w.o.steps(p);
        var from: usize = 0;
        // A wide value projected again and again — an entry model (§20.4) —
        // is indexed by its first step once.
        if (s.len > 0 and av.len >= wide_index) {
            if (s.len == 1) if (ty) |v| if (!try w.trackedVar(v)) return &.{};
            at = try w.projFirst(av, s[0]);
            from = 1;
        }
        for (s[from..], from..) |st, i| at = try w.proj(at, st, if (i + 1 == s.len) ty else null);
        return at;
    }

    /// `proj(av, s)` for a wide value, through an index by first step that
    /// is built once per value: the same answer, without the scan.
    fn projFirst(w: *Walker, av: AV, s: Step) Allocator.Error!AV {
        if (analysisStep(s.kind) or s.kind == .cast or s.kind == .cast_level or s.kind == .level or (s.kind == .ctor and try w.o.levelOf(s.arg) != .none)) return w.proj(av, s, null);
        // Decide fallback before inserting: an abandoned index must never
        // leave an uninitialized cache entry for a later projection.
        for (av) |e| if (w.o.firstStep(e.path)) |first| {
            if (first.kind == .cast or first.kind == .cast_level) return w.proj(av, s, null);
        };
        const key: [2]usize = .{ @intFromPtr(av.ptr), av.len };
        const gop = try w.wide.getOrPut(w.a, key);
        if (!gop.found_existing) {
            var idx: WideIndex = .{};
            for (av) |e| {
                if (e.path == eps) {
                    try idx.roots.append(w.a, e);
                    continue;
                }
                const first = w.o.firstStep(e.path).?;
                if (first.kind == .any) {
                    try idx.any.append(w.a, e);
                    continue;
                }
                if (first.kind == .level) {
                    try idx.levels.append(w.a, e);
                    continue;
                }
                const g = try idx.by.getOrPut(w.a, .{ @backingInt(first.kind), first.arg });
                if (!g.found_existing) g.value_ptr.* = .empty;
                try g.value_ptr.append(w.a, .{ .path = try w.o.dropFirst(e.path), .cell = e.cell, .approx = e.approx, .grown = gDropGuard(e.grown, w.o.paths.depth.items[e.path]) });
            }
            gop.value_ptr.* = idx;
        }
        const idx = gop.value_ptr;
        var out: std.ArrayList(Entry) = .empty;
        for (idx.roots.items) |e| {
            if (try w.projCell(e.cell, s, null)) |c| try out.append(w.a, .{ .path = eps, .cell = c, .approx = e.approx, .grown = gStep(e.grown) });
        }
        try out.appendSlice(w.a, idx.any.items);
        if (idx.by.get(.{ @backingInt(s.kind), s.arg })) |list| try out.appendSlice(w.a, list.items);
        for (idx.levels.items) |e| try w.underMarker(&out, e, w.o.firstStep(e.path).?, s);
        return w.norm(out.items);
    }

    // ---- exclusive contents (§18.2–§18.4) ---------------------------------

    fn mkCond(w: *Walker, atoms_in: []const WAtom) Allocator.Error!u32 {
        // §31.2: an atom over a record's object says nothing of a list until
        // the record demand reads it (§31.4 item 6); one over an `except`
        // cell is over the record cell it was written over.
        var atoms = atoms_in;
        for (atoms_in, 0..) |t, i| {
            if (try w.atomFacing(t)) |f| if (std.meta.eql(f, t)) continue;
            var kept: std.ArrayList(WAtom) = .empty;
            try kept.appendSlice(w.a, atoms_in[0..i]);
            for (atoms_in[i..]) |u| if (try w.atomFacing(u)) |f| try kept.append(w.a, f);
            kept.items.len = sortWAtoms(kept.items);
            atoms = kept.items;
            break;
        }
        return w.mkFacedCond(atoms);
    }

    /// Intern atoms already in the list-facing vocabulary. A union of two
    /// conditions is still facing: cells and their types are immutable.
    fn mkFacedCond(w: *Walker, atoms: []const WAtom) Allocator.Error!u32 {
        if (atoms.len == 0) return cond_yes;
        const gop = try w.cond_map.getOrPut(w.a, atoms);
        if (gop.found_existing) return gop.value_ptr.*;
        const k: u32 = @intCast(w.conds.items.len);
        try w.conds.append(w.a, .{ .atoms = atoms });
        gop.value_ptr.* = k;
        return k;
    }

    /// An atom as a list's facts read it (`listFacing`), or null when it is
    /// over a record's object alone, or over a value whose type, by the
    /// crossing rule before §31.2, holds no cell.
    fn atomFacing(w: *Walker, t: WAtom) Allocator.Error!?WAtom {
        var out = t;
        switch (t.kind) {
            // Made of cells already facing (`apartCells`).
            .apart, .apart_spine => {},
            // `a` is a function parameter's index, not a cell.
            .keep, .keep_spine => out.b = (try w.atomCell(t.b)) orelse return null,
            .excl, .spine => out.a = (try w.atomCell(t.a)) orelse return null,
            .sep_root => {
                out.a = (try w.atomCell(t.a)) orelse return null;
                out.b = (try w.atomCell(t.b)) orelse return null;
            },
            .sep, .sep_spine => {
                const a = (try w.atomCell(t.a)) orelse return null;
                const b = (try w.atomCell(t.b)) orelse return null;
                out.a = @min(a, b);
                out.b = @max(a, b);
            },
        }
        return out;
    }

    fn atomCond(w: *Walker, t: WAtom) Allocator.Error!u32 {
        return w.mkCond(try w.a.dupe(WAtom, &.{t}));
    }

    fn sepCond(w: *Walker, x: u32, y: u32) Allocator.Error!u32 {
        return w.atomCond(if (x <= y) .{ .kind = .sep, .a = x, .b = y } else .{ .kind = .sep, .a = y, .b = x });
    }

    /// The conjunction of two conditions: failing exactly beats failing
    /// approximately, and a holding one rests on both atom sets.
    fn condAnd(w: *Walker, x: u32, y: u32) Allocator.Error!u32 {
        if (x == y or y == cond_yes) return x;
        if (x == cond_yes) return y;
        if (x == cond_shared or y == cond_shared) return cond_shared;
        if (x == cond_limit or y == cond_limit) return cond_limit;
        if (x == cond_lost or y == cond_lost) return cond_lost;
        const xs = w.conds.items[x].atoms;
        const ys = w.conds.items[y].atoms;
        // Two conditions whose atoms are each in order, with no repeat — as
        // `condAndAll` and this function leave them — are merged in one pass,
        // to the very atoms sorting their union gives: `WAtom.less` orders
        // every field `std.meta.eql` compares (#754).
        if (strictlyOrdered(xs) and strictlyOrdered(ys)) {
            var i: usize = 0;
            var j: usize = 0;
            var n: usize = 0;
            while (i < xs.len and j < ys.len) : (n += 1) {
                if (xs[i].less(ys[j])) {
                    i += 1;
                } else if (ys[j].less(xs[i])) {
                    j += 1;
                } else {
                    i += 1;
                    j += 1;
                }
            }
            n += (xs.len - i) + (ys.len - j);
            if (n == xs.len) return x;
            if (n == ys.len) return y;
            const all = try w.a.alloc(WAtom, n);
            i = 0;
            j = 0;
            for (all) |*t| {
                if (j == ys.len or (i < xs.len and xs[i].less(ys[j]))) {
                    t.* = xs[i];
                    i += 1;
                } else if (i == xs.len or ys[j].less(xs[i])) {
                    t.* = ys[j];
                    j += 1;
                } else {
                    t.* = xs[i];
                    i += 1;
                    j += 1;
                }
            }
            return w.mkFacedCond(all);
        }
        const all = try w.a.alloc(WAtom, xs.len + ys.len);
        @memcpy(all[0..xs.len], xs);
        @memcpy(all[xs.len..], ys);
        std.mem.sort(WAtom, all, {}, struct {
            fn less(_: void, p: WAtom, q: WAtom) bool {
                return p.less(q);
            }
        }.less);
        var n: usize = 0;
        for (all) |t| {
            if (n > 0 and std.meta.eql(all[n - 1], t)) continue;
            all[n] = t;
            n += 1;
        }
        if (n == xs.len) return x;
        if (n == ys.len) return y;
        return w.mkFacedCond(all[0..n]);
    }

    /// The condition of a cell (§18.2): its table's, or its kind's — a cell
    /// that arrived from outside is as exclusive as its arrival is.
    fn cellCond(w: *Walker, c: u32) Allocator.Error!u32 {
        if (w.cell_cond.items[c] != none) return w.cell_cond.items[c];
        const x = w.cells.items[c];
        const k: u32 = switch (x.kind) {
            .site, .shared, .closure, .func => cond_yes,
            // A message: what its sender built, which the entry does not see (§20.5).
            .top, .payload => cond_lost,
            // A call's result: what instantiation set at its root; a result
            // no summary made has none, and is lost.
            .result => if (x.path != eps) blk: {
                var root = x;
                root.path = eps;
                root.ty = .none;
                break :blk try w.cellCond(try w.cell(root));
            } else cond_lost,
            // §31.2: the record cell it was written over; the object alone
            // is no list's.
            .except => if (x.b == except_all) cond_yes else try w.cellCond(x.a),
            .param, .env, .cbres => try w.atomCond(.{ .kind = .excl, .a = c }),
            // A taken element is as exclusive as its container (§18.5).
            // (a split element: as its scrutinee, §18.4 item 4).
            .taken => if (w.instCol(?AV, w.split_scrut, x.b, null)) |scrut| blk: {
                var acc: CondAcc = .{};
                for (scrut) |e| if (e.path == eps) {
                    try acc.add(w, try w.cellCond(e.cell));
                };
                break :blk try w.condAndAll(&acc);
            } else try w.atomCond(.{ .kind = .excl, .a = try w.containerOf(c) }),
        };
        w.cell_cond.items[c] = k;
        return k;
    }

    /// Lower a cell's condition, as a write in place does (§18.2).
    fn lowerCond(w: *Walker, c: u32, k: u32) Allocator.Error!void {
        if (k == cond_yes) return;
        const now = try w.condAnd(try w.cellCond(c), k);
        w.noteWrite(.cond, c, w.cell_cond.items[c], now);
        w.cell_cond.items[c] = now;
    }

    /// Counts a change of a cell's entry in a condition table (§16.3's
    /// instantiation, #754): one that changes nothing, or one to a result
    /// cell of the call being instantiated, is not counted.
    fn noteWrite(w: *Walker, table: enum { cond, spine, rcond }, c: u32, before: u32, after: u32) void {
        if (before == after) return;
        const x = w.cells.items[c];
        if (x.kind == .result and x.a == w.writes_inst) return;
        switch (table) {
            .cond => w.cond_writes += 1,
            .spine => w.spine_writes += 1,
            // A list's condition reads no record condition (§31.4 item 6).
            .rcond => {},
        }
    }

    /// The condition of a cell this walk made, which starts at `k`.
    fn initCond(w: *Walker, c: u32, k: u32) Allocator.Error!void {
        const cur = w.cell_cond.items[c];
        const now = if (cur != none) try w.condAnd(cur, k) else k;
        w.noteWrite(.cond, c, cur, now);
        w.cell_cond.items[c] = now;
    }

    /// Exclusivity of the represented containers, not of their contents.
    /// A list may hold shared read-only values without sharing its own array.
    fn cellSpine(w: *Walker, c: u32) Allocator.Error!u32 {
        if (w.cell_spine.items[c] != none) return w.cell_spine.items[c];
        if (w.cells.items[c].condition_only) return cond_yes;
        const x = w.cells.items[c];
        const k: u32 = switch (x.kind) {
            .site, .closure, .func => cond_yes,
            .top, .payload, .shared => cond_lost,
            .result => if (x.path != eps) blk: {
                var root = x;
                root.path = eps;
                root.ty = .none;
                break :blk try w.cellSpine(try w.cell(root));
            } else cond_lost,
            .param, .env, .cbres => try w.atomCond(.{ .kind = .spine, .a = c }),
            .taken => try w.cellSpine(try w.takenBase(c)),
            .except => if (x.b == except_all) cond_yes else try w.cellSpine(x.a),
        };
        w.cell_spine.items[c] = k;
        return k;
    }

    fn initSpine(w: *Walker, c: u32, k: u32) Allocator.Error!void {
        const cur = w.cell_spine.items[c];
        const now = if (cur == none) k else try w.condAnd(cur, k);
        w.noteWrite(.spine, c, cur, now);
        w.cell_spine.items[c] = now;
    }

    fn lowerSpine(w: *Walker, c: u32, k: u32) Allocator.Error!void {
        if (k == cond_yes) return;
        const now = try w.condAnd(try w.cellSpine(c), k);
        w.noteWrite(.spine, c, w.cell_spine.items[c], now);
        w.cell_spine.items[c] = now;
    }

    fn spineCond(w: *Walker, av: AV) Allocator.Error!u32 {
        var acc: CondAcc = .{};
        const any = try w.o.child(eps, .any, 0);
        const runtime = try w.o.child(eps, .any, 1);
        for (av) |e| if (e.path == eps or e.path == any or e.path == runtime) {
            var k = try w.cellSpine(e.cell);
            const c = w.cells.items[e.cell];
            // An annotation on an opaque top-level value has no exact
            // allocation witness, just as that value's own spine does not.
            // Keep a known failure on a concrete allocation exact, however.
            if (c.condition_only and (c.kind == .shared or c.kind == .top or c.kind == .payload) and k == cond_shared) k = cond_lost;
            try acc.add(w, try w.rootSpineFact(k, e.approx == 0));
        };
        return w.condAndAll(&acc);
    }

    /// At the selected array, an impossible separation is already false,
    /// not an unsatisfiable requirement to pass on to a caller. Keep the
    /// original annotation projectable for a different selected path.
    fn rootSpineFact(w: *Walker, k: u32, exact: bool) Allocator.Error!u32 {
        if (k <= cond_fixed_last) return k;
        for (w.conds.items[k].atoms) |t| {
            if (t.kind == .sep_root) break;
        } else return k;
        var acc: CondAcc = .{};
        for (w.conds.items[k].atoms) |t| {
            if (t.kind == .sep_root) {
                const pair = try w.sepSpines(t.a, t.b, exact);
                try acc.add(w, if (pair <= cond_fixed_last) pair else try w.rootSeparation(t.a, t.b));
            } else {
                try acc.add(w, try w.atomCond(t));
            }
        }
        return w.condAndAll(&acc);
    }

    /// A returned container cannot also appear at another result position:
    /// the definition, pair by pair, which `spineAt` computes through an
    /// index. Kept to check it under runtime safety.
    fn spineAtPairwise(w: *Walker, av: AV, target: Entry) Allocator.Error!u32 {
        if (w.cells.items[target.cell].condition_only) return w.cellSpine(target.cell);
        var k = try w.cellSpine(target.cell);
        for (av) |other| {
            if (other.path == target.path) continue;
            if (other.cell == target.cell) return cond_lost;
            if (try w.nested(other, target)) continue;
            k = try w.condAnd(k, try w.sepSpines(target.cell, other.cell, target.approx == 0 and other.approx == 0));
        }
        return k;
    }

    /// §16.3: a value's entries sorted by what `sepCells` can say of a pair
    /// of them, built once per read-off so that `spineAt` reads, for each
    /// entry, only the others whose pair is not `yes` by its kinds alone —
    /// a pair of a cell made here and a parameter's, say. Near-linear in
    /// the value's entries, where the pairwise definition is quadratic in
    /// them and cubic in its conditions.
    const SpineIndex = struct {
        physical: *PhysicalIndex,
        av: AV,
        /// The cells found at two paths or more: every entry of one is
        /// `lost`, as the pairwise definition returns at the first such pair.
        /// Sorted.
        multi: []const u32 = &.{},
        /// A taken element, `⊤` or a message: compared with every cell.
        odd: std.ArrayList(Entry) = .empty,
        /// A parameter's, a capture's or a callback result's cell.
        arrived: std.ArrayList(Entry) = .empty,
        /// A callback result's cell (also in `arrived`).
        cbres: std.ArrayList(Entry) = .empty,
        /// A cell made here: a site's or a call result's.
        made: std.ArrayList(Entry) = .empty,
        /// A call result's or a top-level value's cell by `(kind, a, b)`:
        /// the only cells of those kinds `covers` can relate.
        family: std.AutoHashMapUnmanaged([3]u32, std.ArrayList(Entry)) = .empty,
    };

    fn spineIndex(w: *Walker, av: AV) Allocator.Error!SpineIndex {
        if (av.len < wide_index) return w.spineIndexRaw(av);
        const key: [2]usize = .{ @intFromPtr(av.ptr), av.len };
        if (w.spine_indexes.get(key)) |idx| return idx;
        const idx = try w.spineIndexRaw(av);
        try w.spine_indexes.put(w.a, key, idx);
        return idx;
    }

    fn spineIndexRaw(w: *Walker, av: AV) Allocator.Error!SpineIndex {
        var idx: SpineIndex = .{ .av = av, .physical = try w.a.create(PhysicalIndex) };
        idx.physical.* = .{};
        // `(cell, path)` sorted: a cell at two paths or more is two runs.
        const at = try w.a.alloc([2]u32, av.len);
        for (av, at) |e, *p| p.* = .{ e.cell, e.path };
        std.mem.sort([2]u32, at, {}, lessPair);
        var multi: std.ArrayList(u32) = .empty;
        for (at, 0..) |p, i| {
            if (i == 0 or at[i - 1][0] != p[0] or at[i - 1][1] == p[1]) continue;
            if (multi.items.len == 0 or multi.items[multi.items.len - 1] != p[0]) try multi.append(w.a, p[0]);
        }
        idx.multi = multi.items;
        for (av) |e| {
            const c = w.cells.items[e.cell];
            if (c.condition_only) continue;
            switch (c.kind) {
                // Compared with every cell, as `spineAt` does (§31.2).
                .taken, .top, .payload, .except => try idx.odd.append(w.a, e),
                .param, .env => try idx.arrived.append(w.a, e),
                .cbres => {
                    try idx.arrived.append(w.a, e);
                    try idx.cbres.append(w.a, e);
                },
                .site => {
                    try idx.made.append(w.a, e);
                    try w.familyAdd(&idx, c, e);
                },
                .result => {
                    try idx.made.append(w.a, e);
                    try w.familyAdd(&idx, c, e);
                },
                .shared => try w.familyAdd(&idx, c, e),
                .closure, .func => {},
            }
        }
        return idx;
    }

    const PhysicalIndex = struct {
        ready: bool = false,
        here: std.HashMapUnmanaged([4]u32, std.ArrayList(Entry), WordsKey(4), std.hash_map.default_max_load_percentage) = .empty,
        below: std.HashMapUnmanaged([4]u32, std.ArrayList(Entry), WordsKey(4), std.hash_map.default_max_load_percentage) = .empty,
        wrappers: std.ArrayList(Entry) = .empty,
    };

    fn physicalIndex(w: *Walker, idx: *const SpineIndex) Allocator.Error!*PhysicalIndex {
        const out = idx.physical;
        if (out.ready) return out;
        out.ready = true;
        for (idx.av) |e| {
            const c = w.cells.items[e.cell];
            if (c.condition_only or c.kind == .closure or c.kind == .func) continue;
            if (c.kind == .taken or c.kind == .except) {
                try out.wrappers.append(w.a, e);
                continue;
            }
            if (e.approx != 0 or try w.o.representative(c.path)) continue;
            const physical = w.o.physicalPath(c.path);
            const key: [4]u32 = .{ @backingInt(c.kind), c.a, c.b, physical };
            const here = try out.here.getOrPut(w.a, key);
            if (!here.found_existing) here.value_ptr.* = .empty;
            try here.value_ptr.append(w.a, e);
            var at = physical;
            var previous: u32 = none;
            while (true) {
                const prefix = w.o.physicalPath(at);
                if (prefix != previous) {
                    const pk: [4]u32 = .{ key[0], key[1], key[2], prefix };
                    const below = try out.below.getOrPut(w.a, pk);
                    if (!below.found_existing) below.value_ptr.* = .empty;
                    try below.value_ptr.append(w.a, e);
                    previous = prefix;
                }
                if (at == eps) break;
                at = w.o.paths.parent.items[at];
            }
        }
        return out;
    }

    /// After an approximate failure, exact failure is still sought. The
    /// ordinary-cell candidates are precisely physical ancestors/descendants
    /// in one provenance family; wrappers keep the general relation.
    const FailureDomain = enum { list, spine, record };

    fn failedAt(w: *Walker, idx: *const SpineIndex, target: Entry, limited: bool, comptime domain: FailureDomain, comptime places: bool) Allocator.Error!u32 {
        const physical = try w.physicalIndex(idx);
        const tc = w.cells.items[target.cell];
        if (tc.kind == .taken or tc.kind == .except) {
            if (try w.failedPairs(idx.av, target, domain, places)) return cond_shared;
        } else {
            if (try w.failedPairs(physical.wrappers.items, target, domain, places)) return cond_shared;
            if (target.approx == 0 and !try w.o.representative(tc.path)) {
                const path = w.o.physicalPath(tc.path);
                const key: [4]u32 = .{ @backingInt(tc.kind), tc.a, tc.b, path };
                if (physical.below.get(key)) |items| if (try w.failedPairs(items.items, target, domain, places)) return cond_shared;
                var at = path;
                var previous = path;
                while (at != eps) {
                    at = w.o.paths.parent.items[at];
                    const prefix = w.o.physicalPath(at);
                    if (prefix == previous) continue;
                    const pk: [4]u32 = .{ key[0], key[1], key[2], prefix };
                    if (physical.here.get(pk)) |items| if (try w.failedPairs(items.items, target, domain, places)) return cond_shared;
                    previous = prefix;
                }
            }
        }
        return if (limited) cond_limit else cond_lost;
    }

    fn failedPairs(w: *Walker, others: AV, target: Entry, comptime domain: FailureDomain, comptime places: bool) Allocator.Error!bool {
        for (others) |other| {
            if (other.path == target.path or (places and try w.nested(other, target))) continue;
            const exact = target.approx == 0 and other.approx == 0;
            if (places and domain == .record and target.cell == other.cell and (try w.o.representative(target.path) or try w.o.representative(other.path))) continue;
            const k = switch (domain) {
                .list => try w.sepCells(target.cell, other.cell, exact),
                .spine => try w.sepSpines(target.cell, other.cell, exact),
                .record => try w.rsepCells(target.cell, other.cell, exact),
            };
            if (k == cond_shared) return true;
        }
        return false;
    }

    fn familyAdd(w: *Walker, idx: *SpineIndex, c: Cell, e: Entry) Allocator.Error!void {
        const g = try idx.family.getOrPut(w.a, .{ @backingInt(c.kind), c.a, c.b });
        if (!g.found_existing) g.value_ptr.* = .empty;
        try g.value_ptr.append(w.a, e);
    }

    /// `spineAtPairwise`, through `idx`. Which pairs can be other than `yes`
    /// follows `sepCells`: a closure or a function shares nothing; a taken
    /// element, `⊤` and a message are compared with everything; a top-level
    /// value's cell only with its own value's (`covers`); a cell made here
    /// only with those, with its own call's results and with a callback's
    /// result; an arrived cell with every arrived cell, and a callback's
    /// result with the cells made here too.
    fn spineAt(w: *Walker, idx: *const SpineIndex, target: Entry) Allocator.Error!u32 {
        if (w.cells.items[target.cell].condition_only) return w.cellSpine(target.cell);
        if (std.sort.binarySearch(u32, idx.multi, target.cell, orderU32) != null) return cond_lost;
        var acc: CondAcc = .{};
        try acc.add(w, try w.cellSpine(target.cell));
        const c = w.cells.items[target.cell];
        switch (c.kind) {
            .closure, .func => {},
            .taken, .top, .payload, .except => try w.spinePairs(&acc, idx.av, target),
            .shared => {
                try w.spinePairs(&acc, idx.odd.items, target);
                if (idx.family.get(.{ @backingInt(c.kind), c.a, c.b })) |f| try w.spinePairs(&acc, f.items, target);
            },
            .site, .result => {
                try w.spinePairs(&acc, idx.odd.items, target);
                try w.spinePairs(&acc, idx.cbres.items, target);
                if (idx.family.get(.{ @backingInt(c.kind), c.a, c.b })) |f| try w.spinePairs(&acc, f.items, target);
            },
            .param, .env, .cbres => {
                try w.spinePairs(&acc, idx.odd.items, target);
                try w.spinePairs(&acc, idx.arrived.items, target);
                if (c.kind == .cbres) try w.spinePairs(&acc, idx.made.items, target);
            },
        }
        const k = if (acc.lost or acc.limit) try w.failedAt(idx, target, acc.limit, .spine, true) else try w.condAndAll(&acc);
        // Values of eight entries or fewer in every safety build; every value
        // with `-Downership-full-cross-check` (#272).
        if (std.debug.runtime_safety and (idx.av.len <= 8 or @import("ownership_options").full_cross_check)) {
            const want = try w.spineAtPairwise(idx.av, target);
            if (!w.condSame(k, want)) std.debug.panic("ownership: the indexed spine condition differs from the pairwise one", .{});
        }
        return k;
    }

    /// A conjunction of many conditions: its verdict so far and its atoms,
    /// sorted and deduplicated once at the end (`condAndAll`). `condAnd`
    /// folded over n conditions re-sorts every atom gathered so far at each
    /// one, which a list literal of n list parameters made O(n⁴) in time and
    /// memory (issue #293); `spineAt` met the same (§16.3's amendment).
    const CondAcc = struct {
        last: u32 = none,
        shared: bool = false,
        lost: bool = false,
        limit: bool = false,
        atoms: std.ArrayList(WAtom) = .empty,

        fn add(acc: *CondAcc, w: *Walker, k: u32) Allocator.Error!void {
            if (acc.last == k) return;
            acc.last = k;
            switch (k) {
                cond_yes => {},
                cond_shared => acc.shared = true,
                cond_lost => acc.lost = true,
                cond_limit => acc.limit = true,
                else => if (!acc.shared and !acc.lost and !acc.limit) {
                    try acc.atoms.appendSlice(w.a, w.conds.items[k].atoms);
                },
            }
            // Kept within the `conditions` limit as it grows (§16.7):
            // duplicates folded, and past the limit nothing more is kept.
            if (acc.atoms.items.len > 2 * condition_cap) {
                acc.atoms.items.len = sortWAtoms(acc.atoms.items);
                const weight = w.atomsWeightW(acc.atoms.items);
                if (weight > condition_cap) {
                    try w.o.hitLimit(.conditions, @intCast(@min(weight, std.math.maxInt(u32))));
                    acc.limit = true;
                    acc.atoms.clearRetainingCapacity();
                }
            }
        }
    };

    fn spinePairs(w: *Walker, acc: *CondAcc, others: AV, target: Entry) Allocator.Error!void {
        const tc = w.cells.items[target.cell];
        const t_arrived = tc.kind == .param or tc.kind == .env or tc.kind == .cbres;
        for (others) |other| {
            if (acc.lost or acc.limit) return;
            if (w.cells.items[other.cell].condition_only) continue;
            if (acc.shared) return;
            if (other.path == target.path) continue;
            if (try w.nested(other, target)) continue;
            const exact = target.approx == 0 and other.approx == 0;
            const oc = w.cells.items[other.cell];
            // Two arrived cells, which `sepCells` relates by `covers` or
            // else separates by an atom: that atom, made here, as
            // `sepSpines` makes it of `sepCond`'s (no condition stored).
            if (t_arrived and (oc.kind == .param or oc.kind == .env or oc.kind == .cbres) and target.cell != other.cell) {
                // `covers` either way, without building the path between.
                const related = tc.kind == oc.kind and tc.a == oc.a and tc.b == oc.b and tc.scope == oc.scope and
                    (w.o.startsWith(tc.path, oc.path) or w.o.startsWith(oc.path, tc.path) or
                        w.o.levelHoldsPaths(tc.path, oc.path) or w.o.levelHoldsPaths(oc.path, tc.path));
                if (related) {
                    const one = !(try w.o.representative(tc.path)) and !(try w.o.representative(oc.path)) and w.o.exactRelatedPaths(tc.path, oc.path);
                    if (exact and one) acc.shared = true else acc.lost = true;
                    continue;
                }
                const x = @min(target.cell, other.cell);
                const y = @max(target.cell, other.cell);
                try acc.atoms.append(w.a, .{ .kind = .sep_spine, .a = x, .b = y });
                continue;
            }
            try acc.add(w, try w.sepSpines(target.cell, other.cell, exact));
        }
    }

    /// Atoms in the `conditions` limit's measure: an apart counts its
    /// members (§16.7, #693).
    fn atomsWeightW(w: *const Walker, atoms: []const WAtom) usize {
        var n: usize = 0;
        for (atoms) |t| switch (t.kind) {
            .apart, .apart_spine => for (w.aparts.items[t.a]) |g| {
                n += g.len;
            },
            else => n += 1,
        };
        return n;
    }

    /// Whether `atoms` is in `WAtom.less` order with no atom twice.
    fn strictlyOrdered(atoms: []const WAtom) bool {
        if (atoms.len < 2) return true;
        for (atoms[0 .. atoms.len - 1], atoms[1..]) |p, q| {
            if (!p.less(q)) return false;
        }
        return true;
    }

    /// Sorts `all` and moves its distinct atoms to the front; their count.
    fn sortWAtoms(all: []WAtom) usize {
        std.mem.sort(WAtom, all, {}, struct {
            fn less(_: void, p: WAtom, q: WAtom) bool {
                return p.less(q);
            }
        }.less);
        var m: usize = 0;
        for (all) |t| {
            if (m > 0 and std.meta.eql(all[m - 1], t)) continue;
            all[m] = t;
            m += 1;
        }
        return m;
    }

    /// `condAnd` folded over what `acc` gathered, with the atoms sorted once.
    fn condAndAll(w: *Walker, acc: *CondAcc) Allocator.Error!u32 {
        if (acc.shared) return cond_shared;
        if (acc.limit) return cond_limit;
        if (acc.lost) return cond_lost;
        if (acc.atoms.items.len == 0) return cond_yes;
        const all = acc.atoms.items;
        const m = sortWAtoms(all);
        const weight = w.atomsWeightW(all[0..m]);
        if (weight > condition_cap) {
            try w.o.hitLimit(.conditions, @intCast(@min(weight, std.math.maxInt(u32))));
            return cond_limit;
        }
        return w.mkCond(all[0..m]);
    }

    /// Whether two conditions say the same: the same verdict, or the same
    /// atoms.
    fn condSame(w: *Walker, x: u32, y: u32) bool {
        if (x <= cond_fixed_last or y <= cond_fixed_last) return x == y;
        const xs = w.conds.items[x].atoms;
        const ys = w.conds.items[y].atoms;
        for (xs) |t| {
            for (ys) |u| {
                if (std.meta.eql(t, u)) break;
            } else return false;
        }
        for (ys) |t| {
            for (xs) |u| {
                if (std.meta.eql(t, u)) break;
            } else return false;
        }
        return true;
    }

    fn sepSpines(w: *Walker, x: u32, y: u32, exact: bool) Allocator.Error!u32 {
        if (w.cells.items[x].condition_only or w.cells.items[y].condition_only) return cond_yes;
        const cx = w.cells.items[x];
        if (x == y and w.inCoreDict()) switch (cx.kind) {
            .param, .env, .cbres => if (try w.o.dictTreePath(cx.path)) return w.cellSpine(x),
            .site, .result, .shared, .top, .closure, .func, .taken, .payload, .except => {},
        };
        return w.spineOfSep(try w.sepCells(x, y, exact));
    }

    /// `k`, a separation condition, as one on the spines: its atoms made
    /// spine atoms, and a fixed condition kept as it is.
    fn spineOfSep(w: *Walker, k: u32) Allocator.Error!u32 {
        if (k <= cond_fixed_last) return k;
        const atoms = try w.a.dupe(WAtom, w.conds.items[k].atoms);
        for (atoms) |*a| switch (a.kind) {
            .sep => a.kind = .sep_spine,
            .excl => a.kind = .spine,
            .apart => a.kind = .apart_spine,
            else => {},
        };
        return w.mkCond(atoms);
    }

    fn sepSpineValues(w: *Walker, x: AV, y: AV) Allocator.Error!u32 {
        var acc: CondAcc = .{};
        for (x) |e| {
            if (e.path != eps) continue;
            for (y) |f| if (f.path == eps) {
                try acc.add(w, try w.sepSpines(e.cell, f.cell, e.approx == 0 and f.approx == 0));
            };
        }
        return w.condAndAll(&acc);
    }

    /// §31.2: the cell `(ε, c ∖ F)` for the record cell `c` after an update
    /// that wrote `fields`: one exception set, the union of `c`'s own and
    /// `fields`, over the record cell the first update wrote. A site's
    /// object projects nothing, so its update is the site itself.
    fn exceptCell(w: *Walker, c: u32, fields: []const u32, all: bool) Allocator.Error!u32 {
        const x = w.cells.items[c];
        switch (x.kind) {
            .site, .top, .closure, .func => return c,
            .param, .result, .env, .shared, .cbres, .taken, .payload, .except => {},
        }
        var base = c;
        var set: std.ArrayList(u32) = .empty;
        var every = all;
        if (x.kind == .except) {
            base = x.a;
            if (x.b == except_all) every = true else try set.appendSlice(w.a, w.exsets.items[x.b]);
        }
        var b: u32 = except_all;
        if (!every) {
            for (fields) |f| if (std.mem.indexOfScalar(u32, set.items, f) == null) try set.append(w.a, f);
            std.mem.sort(u32, set.items, {}, std.sort.asc(u32));
            const key = std.mem.sliceAsBytes(set.items);
            const gop = try w.exset_map.getOrPut(w.a, key);
            if (!gop.found_existing) {
                gop.value_ptr.* = @intCast(w.exsets.items.len);
                try w.exsets.append(w.a, set.items);
            }
            b = gop.value_ptr.*;
        }
        return w.cell(.{ .kind = .except, .a = base, .b = b, .ty = w.cells.items[base].ty });
    }

    /// The element an `except` cell with fields stands for when a list
    /// pattern or a traversal takes it out (§18.5): the record cell it was
    /// written over, when that is one a taken cell may stand for.
    fn takeable(w: *Walker, c: u32) Allocator.Error!?u32 {
        const x = w.cells.items[c];
        return switch (x.kind) {
            .param, .result, .env, .cbres => c,
            .except => if (x.b == except_all) null else try w.takeable(x.a),
            .site, .shared, .top, .closure, .func, .taken, .payload => null,
        };
    }

    /// The cell a list's facts read for `c` (§31.2): an `except` cell with
    /// fields is the record cell it was written over, as the update's whole
    /// base was before; a record's object alone, and a cell whose value
    /// holds only records, are none.
    /// The record object a record demand reads for `c` (§31.3): an `except`
    /// cell is the object it was written over.
    fn recordObject(w: *const Walker, c: u32) ?u32 {
        if (w.cells.items[c].condition_only) return null;
        const x = w.cells.items[c];
        return if (x.kind == .except) x.a else c;
    }

    fn listFacing(w: *const Walker, c: u32) ?u32 {
        const x = w.cells.items[c];
        if (x.kind == .except) return if (x.b == except_all) null else w.listFacing(x.a);
        if (x.kind == .taken and w.listFacing(x.a) == null) return null;
        return if (x.nonlist) null else c;
    }

    fn atomCell(w: *Walker, c_in: u32) Allocator.Error!?u32 {
        if (w.cells.items[c_in].condition_only) return null;
        const c = w.listFacing(c_in) orelse return null;
        if (w.cells.items[c].ty.unwrap()) |v| if (!try w.listTrackedVar(v)) return null;
        return c;
    }

    /// A value as a summary reads it until record cells reach summaries
    /// (§31.7): each cell as `listFacing` reads it, and none where it reads
    /// none.
    fn listView(w: *Walker, av: AV) Allocator.Error!AV {
        for (av) |e| {
            if (w.listFacing(e.cell) != e.cell) break;
        } else return av;
        var out: std.ArrayList(Entry) = .empty;
        for (av) |e| {
            const c = w.listFacing(e.cell) orelse continue;
            try out.append(w.a, .{ .path = e.path, .cell = c, .approx = e.approx, .grown = gStep(e.grown) });
        }
        return w.norm(out.items);
    }

    /// Whether a site is a record literal's object (§31.2).
    fn isRecordCell(w: *Walker, x: Cell) bool {
        return x.kind == .site and w.bir.instTag(@fromBackingInt(x.a)) == .record;
    }

    /// The element cell a taken cell stands for, at its path; and the record
    /// cell an `except` cell with fields was written over (`listView`).
    fn takenBase(w: *Walker, c_in: u32) Allocator.Error!u32 {
        var c = c_in;
        var t = w.cells.items[c];
        // An `except` over a taken element is that element, taken.
        if (t.kind == .except) {
            if (t.b == except_all) return c;
            c = t.a;
            t = w.cells.items[c];
        }
        if (t.kind != .taken) return c;
        if (t.path == eps) return t.a;
        var b = w.cells.items[t.a];
        b.path = try w.o.concat(b.path, t.path);
        b.ty = .none;
        return w.cell(b);
    }

    /// The container a taken element came out of: its base without the
    /// last `[*]`.
    fn containerOf(w: *Walker, c: u32) Allocator.Error!u32 {
        const t = w.cells.items[c];
        var b = w.cells.items[t.a];
        const s = w.o.steps(b.path);
        if (s.len == 0 or s[s.len - 1].kind != .elem) return t.a;
        var at: u32 = eps;
        for (s[0 .. s.len - 1]) |st| at = try w.o.child(at, st.kind, st.arg);
        b.path = at;
        b.ty = .none;
        return w.cell(b);
    }

    fn inCoreDict(w: *const Walker) bool {
        return w.o.in.packages[w.m] == .core and std.mem.eql(u8, w.o.in.module_names[w.m], "Dict");
    }

    fn madeHere(k: CellKind) bool {
        return k == .site or k == .result;
    }

    /// Whether two cells share no cell (§18.2).
    fn sepCells(w: *Walker, x: u32, y: u32, exact: bool) Allocator.Error!u32 {
        if (w.cells.items[x].condition_only or w.cells.items[y].condition_only) return cond_yes;
        const cx = w.cells.items[x];
        const cy = w.cells.items[y];
        if (cx.kind == .closure or cx.kind == .func or cy.kind == .closure or cy.kind == .func) return cond_yes;
        // §20.8: inside core/Dict, one cell that arrived from outside at a
        // folded path of its tree stands for distinct positions, which the
        // module never makes share (the trusted surface, §20.9).
        if (x == y and w.inCoreDict()) switch (cx.kind) {
            .param, .env, .cbres => if (try w.o.dictTreePath(cx.path)) return w.cellCond(x),
            .site, .result, .shared, .top, .closure, .func, .taken, .payload, .except => {},
        };
        if (x == y or (try w.covers(x, y)) != null or (try w.covers(y, x)) != null) {
            // Exact only when the text shows it: one place, not a list's
            // elements or a folded level standing for many (§8.4).
            const one = !(try w.o.representative(cx.path)) and !(try w.o.representative(cy.path)) and w.o.exactRelatedPaths(cx.path, cy.path);
            return if (exact and one) cond_shared else cond_lost;
        }
        if (cx.kind == .top or cy.kind == .top or cx.kind == .payload or cy.kind == .payload) return cond_lost;
        // A taken element and its container's other positions share no cell
        // when the container is exclusive (§18.5).
        if (cx.kind == .taken or cy.kind == .taken) {
            const t = if (cx.kind == .taken) x else y;
            const other = if (cx.kind == .taken) y else x;
            const base = try w.takenBase(t);
            // The container itself holds the taken element still.
            if (other != base and (try w.covers(other, base)) != null) return cond_lost;
            if (other == base or (try w.covers(base, other)) != null) return w.cellCond(t);
        }
        if (cx.kind == .shared or cy.kind == .shared) return cond_yes;
        if (madeHere(cx.kind) or madeHere(cy.kind)) {
            const made = if (madeHere(cx.kind)) x else y;
            const other = if (madeHere(cx.kind)) cy else cx;
            // A callback may return what it was handed.
            if (other.kind == .cbres) if (w.instCol(?AV, w.cb_args, other.b, null)) |args| {
                if ((try w.reaches(args, &.{.{ .path = eps, .cell = made }})) != null) return cond_lost;
            };
            return cond_yes;
        }
        return w.sepCond(x, y);
    }

    /// Whether two values share no cell.
    fn sepValues(w: *Walker, x: AV, y: AV) Allocator.Error!u32 {
        if (x.len == 0 or y.len == 0) return cond_yes;
        return w.sepOfCells(try w.sepCellList(x), try w.sepCellList(y));
    }

    /// The cells `sepValues` compares for `x`. Only the cells matter, and
    /// whether each is reached exactly: a value holding one cell at many
    /// paths is compared once (§20.4).
    fn sepCellList(w: *Walker, x: AV) Allocator.Error!AV {
        return w.cellsOf(try w.expand(x));
    }

    /// `sepValues` over two values' `sepCellList`.
    fn sepFailed(w: *Walker, ex: AV, ey: AV, fl: Fl, limited: bool) Allocator.Error!u32 {
        const Ent = struct { e: Entry, g: u32 };
        const items = try w.a.alloc(Ent, ex.len + ey.len);
        for (items[0..ex.len], ex) |*item, e| item.* = .{ .e = e, .g = 0 };
        for (items[ex.len..], ey) |*item, e| item.* = .{ .e = e, .g = 1 };
        return w.failedGroups(items, fl, limited);
    }

    fn sepOfCells(w: *Walker, ex: AV, ey: AV) Allocator.Error!u32 {
        var acc: CondAcc = .{};
        for (ex) |a| for (ey) |b| {
            try acc.add(w, try w.sepCells(a.cell, b.cell, a.approx == 0 and b.approx == 0));
            if (acc.shared) return cond_shared;
            if (acc.lost or acc.limit) return w.sepFailed(ex, ey, .list, acc.limit);
        };
        return w.condAndAll(&acc);
    }

    // ---- pairwise apart (§16.7, amended 2026-10-22, #693) -----------------

    /// Which table a pairwise-apart condition is for: a list's (`sepCells`,
    /// `conds`) or a record's (`rsepCells`, `rconds`).
    const Fl = enum { list, record };

    /// A conjunction in either table.
    const FlAcc = struct {
        fl: Fl,
        l: CondAcc = .{},
        r: RAcc = .{},

        fn add(acc: *FlAcc, w: *Walker, k: u32) Allocator.Error!void {
            switch (acc.fl) {
                .list => try acc.l.add(w, k),
                .record => try acc.r.add(w, k),
            }
        }

        fn shared(acc: *const FlAcc) bool {
            return switch (acc.fl) {
                .list => acc.l.shared,
                .record => acc.r.shared,
            };
        }

        fn failed(acc: *const FlAcc) bool {
            return switch (acc.fl) {
                .list => acc.l.lost or acc.l.limit,
                .record => acc.r.lost or acc.r.limit,
            };
        }

        fn limited(acc: *const FlAcc) bool {
            return switch (acc.fl) {
                .list => acc.l.limit,
                .record => acc.r.limit,
            };
        }

        /// Atoms already in the table's vocabulary (facing, for a list's).
        fn addAtoms(acc: *FlAcc, w: *Walker, atoms: []const WAtom) Allocator.Error!void {
            if (atoms.len == 0) return;
            switch (acc.fl) {
                .list => try acc.l.atoms.appendSlice(w.a, atoms),
                .record => {
                    if (!acc.r.many) {
                        acc.r.many = true;
                        if (acc.r.one != cond_yes) try acc.r.atoms.appendSlice(w.a, w.rconds.items[acc.r.one].atoms);
                    }
                    try acc.r.atoms.appendSlice(w.a, atoms);
                },
            }
        }

        fn done(acc: *FlAcc, w: *Walker) Allocator.Error!u32 {
            return switch (acc.fl) {
                .list => w.condAndAll(&acc.l),
                .record => acc.r.done(w),
            };
        }
    };

    fn lessU32s(_: void, x: []const u32, y: []const u32) bool {
        return std.mem.order(u32, x, y) == .lt;
    }

    /// `apartAtoms` over the walk's cells: the atoms that say `groups_in` are
    /// pairwise apart, appended to `out` — one interned `apart` (or
    /// `apart_spine`) when its expansion is longer than its members, else
    /// the expansion. Each group is reordered in place.
    fn pairwiseApartAtoms(w: *Walker, kind: @FieldType(XAtom, "kind"), groups_in: [][]u32, out: *std.ArrayList(WAtom)) Allocator.Error!void {
        var groups: std.ArrayList([]const u32) = .empty;
        for (groups_in) |g| {
            std.mem.sort(u32, g, {}, std.sort.asc(u32));
            var n: usize = 0;
            for (g) |c| {
                if (n > 0 and g[n - 1] == c) continue;
                g[n] = c;
                n += 1;
            }
            if (n > 0) try groups.append(w.a, g[0..n]);
        }
        if (groups.items.len < 2) return;
        std.mem.sort([]const u32, groups.items, {}, lessU32s);
        const sizes = try w.a.alloc(usize, groups.items.len);
        for (sizes, groups.items) |*s, g| s.* = g.len;
        const c = apartCounts(sizes);
        if (c.pairs <= c.members) {
            const pk: @FieldType(XAtom, "kind") = if (kind == .apart) .sep else .sep_spine;
            for (groups.items, 0..) |g, i| for (groups.items[i + 1 ..]) |h| for (g) |x| for (h) |y| {
                try out.append(w.a, .{ .kind = pk, .a = @min(x, y), .b = @max(x, y) });
            };
            return;
        }
        var key: std.ArrayList(u32) = .empty;
        for (groups.items) |g| {
            try key.append(w.a, @intCast(g.len));
            try key.appendSlice(w.a, g);
        }
        const gop = try w.apart_map.getOrPut(w.a, std.mem.sliceAsBytes(key.items));
        if (!gop.found_existing) {
            gop.value_ptr.* = @intCast(w.aparts.items.len);
            try w.aparts.append(w.a, groups.items);
        }
        try out.append(w.a, .{ .kind = kind, .a = gop.value_ptr.* });
    }

    /// A walk atom's expansion, appended to `out` (an apart's pairs; any
    /// other atom as it is).
    fn expandWAtom(w: *Walker, t: WAtom, out: *std.ArrayList(WAtom)) Allocator.Error!void {
        if (t.kind != .apart and t.kind != .apart_spine) return out.append(w.a, t);
        const pk: @FieldType(XAtom, "kind") = if (t.kind == .apart) .sep else .sep_spine;
        const gs = w.aparts.items[t.a];
        for (gs, 0..) |g, i| for (gs[i + 1 ..]) |h| for (g) |x| for (h) |y| {
            try out.append(w.a, .{ .kind = pk, .a = @min(x, y), .b = @max(x, y) });
        };
    }

    /// Whether two conditions of one table say the same: one verdict, or,
    /// with every apart expanded, the same atoms.
    fn condSameExpanded(w: *Walker, x: u32, y: u32, fl: Fl) Allocator.Error!bool {
        if (x <= cond_fixed_last or y <= cond_fixed_last) return x == y;
        const table = if (fl == .list) w.conds.items else w.rconds.items;
        var xs: std.ArrayList(WAtom) = .empty;
        var ys: std.ArrayList(WAtom) = .empty;
        for (table[x].atoms) |t| try w.expandWAtom(t, &xs);
        for (table[y].atoms) |t| try w.expandWAtom(t, &ys);
        const n = sortWAtoms(xs.items);
        const m = sortWAtoms(ys.items);
        if (n != m) return false;
        for (xs.items[0..n], ys.items[0..m]) |t, u| if (!std.meta.eql(t, u)) return false;
        return true;
    }

    /// Whether a safety build compares a pairwise-apart condition over
    /// groups of these sizes with its expansion (§16.7, #693): one whose
    /// expansion has at most 64 pairs, or every one under
    /// `-Downership-full-cross-check`.
    fn checksApart(sizes: anytype) bool {
        if (!std.debug.runtime_safety) return false;
        if (@import("ownership_options").full_cross_check) return true;
        return apartCounts(sizes).pairs <= 64;
    }

    /// One pair's separation, in the table's terms.
    fn sepCellsFl(w: *Walker, x: u32, y: u32, exact: bool, fl: Fl) Allocator.Error!u32 {
        return switch (fl) {
            .list => w.sepCells(x, y, exact),
            .record => w.rsepCells(x, y, exact),
        };
    }

    /// The definition, pair by pair: `sepOfCells` (or `rsepOfCells`) of
    /// every two groups.
    fn pairwiseApartByPairs(w: *Walker, groups: []const AV, fl: Fl) Allocator.Error!u32 {
        var acc: FlAcc = .{ .fl = fl };
        for (groups, 0..) |g, i| for (groups[i + 1 ..]) |h| {
            if (g.len == 0 or h.len == 0) continue;
            try acc.add(w, switch (fl) {
                .list => try w.sepOfCells(g, h),
                .record => try w.rsepOfCells(g, h),
            });
            if (acc.shared()) return cond_shared;
        };
        return acc.done(w);
    }

    /// §16.7 (#693): that no cell of one group shares a cell (a record
    /// object, for a record's) with a cell of another — the conjunction of
    /// `sepCells` (`rsepCells`) over every such pair — in one pass. Each
    /// group is a cell list (`sepCellList`, `rsepCellList`). Pairs that
    /// their kinds settle are not formed; two cells are related only inside
    /// one family, through a table of its paths; `⊤`, a message, a taken
    /// element and an `except` cell are compared pair by pair; the arrivals
    /// left are one apart. Inside core `Dict`, where one arrival at a folded
    /// path is several places, the whole condition is pair by pair.
    fn pairwiseApart(w: *Walker, groups: []const AV, fl: Fl) Allocator.Error!u32 {
        const sizes = try w.a.alloc(usize, groups.len);
        for (sizes, groups) |*s, g| s.* = g.len;
        // No longer than its members: the condition is its expansion
        // (`pairwiseApartAtoms`), and the pairs are the cheaper way to it.
        const c = apartCounts(sizes);
        if (c.pairs <= c.members) return w.pairwiseApartByPairs(groups, fl);
        const k = try w.pairwiseApartOnce(groups, fl);
        if (checksApart(sizes)) {
            const want = try w.pairwiseApartByPairs(groups, fl);
            if (!try w.condSameExpanded(k, want, fl)) std.debug.panic("ownership: a pairwise-apart condition differs from its expansion", .{});
        }
        return k;
    }

    /// A false construction condition still checks every potential exact
    /// alias across groups. Entry.path is a group number here, never a
    /// place: the physical index reads each cell's own path instead.
    fn failedGroups(w: *Walker, items: anytype, fl: Fl, limited: bool) Allocator.Error!u32 {
        const av = try w.a.alloc(Entry, items.len);
        for (av, items) |*e, x| {
            e.* = x.e;
            e.path = x.g;
        }
        const physical = try w.a.create(PhysicalIndex);
        physical.* = .{};
        const idx: SpineIndex = .{ .av = av, .physical = physical };
        for (av) |e| {
            const k = switch (fl) {
                .list => try w.failedAt(&idx, e, limited, .list, false),
                .record => try w.failedAt(&idx, e, limited, .record, false),
            };
            if (k == cond_shared) return k;
        }
        return if (limited) cond_limit else cond_lost;
    }

    fn pairwiseApartOnce(w: *Walker, groups: []const AV, fl: Fl) Allocator.Error!u32 {
        if (fl == .list and w.inCoreDict()) return w.pairwiseApartByPairs(groups, fl);
        const Ent = struct { e: Entry, g: u32 };
        var ents: std.ArrayList(Ent) = .empty;
        const per = try w.a.alloc(u32, groups.len);
        @memset(per, 0);
        for (groups, 0..) |g, gi| for (g) |e_in| {
            var e = e_in;
            const raw = w.cells.items[e.cell];
            if (raw.condition_only or raw.kind == .closure or raw.kind == .func) continue;
            if (fl == .record) {
                e.cell = try w.rbase(e.cell);
                const x = w.cells.items[e.cell];
                if (x.kind == .closure or x.kind == .func) continue;
                if (!try w.mayHoldRecord(e.cell)) continue;
            }
            try ents.append(w.a, .{ .e = e, .g = @intCast(gi) });
            per[gi] += 1;
        };
        var filled: usize = 0;
        for (per) |n| {
            if (n > 0) filled += 1;
        }
        if (filled < 2) return cond_yes;
        var acc: FlAcc = .{ .fl = fl };
        const items = ents.items;
        // Related pairs (`covers`, either way, or one cell): only in one
        // family — a cell kind that `covers` relates by `(kind, a, b)` and
        // a path prefix, or a site's or `⊤`'s cell, which only it is.
        var families: std.AutoArrayHashMapUnmanaged([4]u32, std.ArrayList(u32)) = .empty;
        for (items, 0..) |x, i| {
            const c = w.cells.items[x.e.cell];
            const key: [4]u32 = switch (c.kind) {
                .param, .result, .env, .shared, .cbres, .payload => .{ @backingInt(c.kind), c.a, c.b, 0 },
                .site, .top => .{ @backingInt(c.kind), x.e.cell, 0, 1 },
                .taken, .except, .closure, .func => continue,
            };
            const gop = try families.getOrPut(w.a, key);
            if (!gop.found_existing) gop.value_ptr.* = .empty;
            try gop.value_ptr.append(w.a, @intCast(i));
        }
        for (families.keys(), families.values()) |key, fam| {
            if (fam.items.len < 2) continue;
            const g0 = items[fam.items[0]].g;
            for (fam.items) |i| {
                if (items[i].g != g0) break;
            } else continue;
            var star = key[3] == 1;
            for (fam.items) |i| {
                if (w.o.paths.any.items[w.cells.items[items[i].e.cell].path] or w.o.paths.casts.items[w.cells.items[items[i].e.cell].path]) star = true;
            }
            if (star) {
                // A `⋆` path, where a marker may hold a place, or one cell:
                // pair by pair.
                for (fam.items, 0..) |i, n| for (fam.items[n + 1 ..]) |j| {
                    const x = items[i];
                    const y = items[j];
                    if (x.g == y.g) continue;
                    if (x.e.cell != y.e.cell and (try w.covers(x.e.cell, y.e.cell)) == null and (try w.covers(y.e.cell, x.e.cell)) == null) continue;
                    try acc.add(w, try w.sepCellsFl(x.e.cell, y.e.cell, x.e.approx == 0 and y.e.approx == 0, fl));
                    if (acc.shared()) return cond_shared;
                    if (acc.failed()) return w.failedGroups(items, fl, acc.limited());
                };
                continue;
            }
            // One path is the other's step-by-step prefix: each cell's
            // ancestors, looked up.
            // `(path, entry)`, sorted: the entries at one path are a run.
            const by_path = try w.a.alloc([2]u32, fam.items.len);
            for (by_path, fam.items) |*p, i| p.* = .{ w.cells.items[items[i].e.cell].path, i };
            std.mem.sort([2]u32, by_path, {}, lessPair);
            for (fam.items) |i| {
                const x = items[i];
                const own = w.cells.items[x.e.cell].path;
                var at = own;
                while (true) {
                    const lo = std.sort.lowerBound([2]u32, by_path, at, struct {
                        fn order(want: u32, p: [2]u32) std.math.Order {
                            return std.math.order(want, p[0]);
                        }
                    }.order);
                    for (by_path[lo..]) |p| {
                        if (p[0] != at) break;
                        const j = p[1];
                        const y = items[j];
                        if (y.g == x.g) continue;
                        // One path: the pair once.
                        if (at == own and j >= i) continue;
                        try acc.add(w, try w.sepCellsFl(x.e.cell, y.e.cell, x.e.approx == 0 and y.e.approx == 0, fl));
                        if (acc.shared()) return cond_shared;
                        if (acc.failed()) return w.failedGroups(items, fl, acc.limited());
                    }
                    if (at == eps or at == none) break;
                    at = w.o.paths.parent.items[at];
                }
            }
        }
        // `⊤` and a message against any cell of another group: lost, when
        // the two are not one (above).
        for (items) |x| switch (w.cells.items[x.e.cell].kind) {
            .top, .payload => if (items.len - per[x.g] > 0) {
                try acc.add(w, cond_lost);
                break;
            },
            else => {},
        };
        // A taken element and an `except` cell: pair by pair, as before.
        // An `except` cell no list faces (a record's object, written) is,
        // in a list's table, `yes` against every cell it is not related to
        // that is not `⊤`, a message or a taken element, and the pair
        // touches nothing: only those pairs are formed, in their order, so
        // a wide record's written fields cost their number (#716).
        var by_key: std.AutoHashMapUnmanaged([3]u32, std.ArrayList(u32)) = .empty;
        var special: std.ArrayList(u32) = .empty;
        var indexed = false;
        for (items, 0..) |x, i| {
            const kx = w.cells.items[x.e.cell].kind;
            if (kx != .taken and kx != .except) continue;
            if (kx == .except and fl == .list and (try w.atomCell(x.e.cell)) == null) {
                if (!indexed) {
                    indexed = true;
                    for (items, 0..) |y, j| {
                        switch (w.cells.items[y.e.cell].kind) {
                            .top, .payload, .taken => try special.append(w.a, @intCast(j)),
                            else => {},
                        }
                        const g = try by_key.getOrPut(w.a, w.coverKey(y.e.cell));
                        if (!g.found_existing) g.value_ptr.* = .empty;
                        try g.value_ptr.append(w.a, @intCast(j));
                    }
                }
                var cand: std.ArrayList(u32) = .empty;
                try cand.appendSlice(w.a, special.items);
                if (by_key.get(w.coverKey(x.e.cell))) |l| try cand.appendSlice(w.a, l.items);
                std.mem.sort(u32, cand.items, {}, std.sort.asc(u32));
                var last: u32 = none;
                for (cand.items) |j| {
                    if (j == last) continue;
                    last = j;
                    const y = items[j];
                    if (y.g == x.g) continue;
                    const ky = w.cells.items[y.e.cell].kind;
                    if ((ky == .taken or ky == .except) and j < i) continue;
                    try acc.add(w, try w.sepCellsFl(x.e.cell, y.e.cell, x.e.approx == 0 and y.e.approx == 0, fl));
                    if (acc.shared()) return cond_shared;
                }
                if (std.debug.runtime_safety and @import("ownership_options").full_cross_check) {
                    // Every pair left out is `yes`, and makes no condition.
                    for (items, 0..) |y, j| {
                        if (y.g == x.g) continue;
                        const ky = w.cells.items[y.e.cell].kind;
                        if ((ky == .taken or ky == .except) and j < i) continue;
                        if (std.mem.indexOfScalar(u32, cand.items, @intCast(j)) != null) continue;
                        const n0 = w.conds.items.len;
                        std.debug.assert(try w.sepCellsFl(x.e.cell, y.e.cell, x.e.approx == 0 and y.e.approx == 0, fl) == cond_yes);
                        std.debug.assert(w.conds.items.len == n0);
                    }
                }
                continue;
            }
            for (items, 0..) |y, j| {
                if (y.g == x.g) continue;
                const ky = w.cells.items[y.e.cell].kind;
                if ((ky == .taken or ky == .except) and j < i) continue;
                try acc.add(w, try w.sepCellsFl(x.e.cell, y.e.cell, x.e.approx == 0 and y.e.approx == 0, fl));
                if (acc.shared()) return cond_shared;
                if (acc.failed()) return w.failedGroups(items, fl, acc.limited());
            }
        }
        // A callback's result against what the body made: lost when what
        // it was handed reaches one of them.
        var made: std.ArrayList(Entry) = .empty;
        for (items) |x| {
            const c = w.cells.items[x.e.cell];
            if (c.kind != .cbres) continue;
            const args = w.instCol(?AV, w.cb_args, c.b, null) orelse continue;
            made.clearRetainingCapacity();
            for (items) |y| {
                if (y.g == x.g or !madeHere(w.cells.items[y.e.cell].kind)) continue;
                try made.append(w.a, .{ .path = eps, .cell = y.e.cell });
            }
            if (made.items.len == 0) continue;
            if ((try w.reaches(args, made.items)) != null) {
                try acc.add(w, cond_lost);
                break;
            }
        }
        // The arrivals: one apart.
        const gs = try w.a.alloc([]u32, groups.len);
        for (gs) |*g| g.* = &.{};
        {
            var lists = try w.a.alloc(std.ArrayList(u32), groups.len);
            for (lists) |*l| l.* = .empty;
            for (items) |x| {
                if (!arrived(w.cells.items[x.e.cell].kind)) continue;
                const c = switch (fl) {
                    .list => (try w.atomCell(x.e.cell)) orelse continue,
                    .record => x.e.cell,
                };
                try lists[x.g].append(w.a, c);
            }
            for (gs, lists) |*g, l| g.* = l.items;
        }
        var atoms: std.ArrayList(WAtom) = .empty;
        try w.pairwiseApartAtoms(.apart, gs, &atoms);
        try acc.addAtoms(w, atoms.items);
        return acc.done(w);
    }

    /// `av`'s distinct cells, each at ε, exact when any entry reaches it exactly.
    fn cellsOf(w: *Walker, av: AV) Allocator.Error!AV {
        if (av.len <= 1) return av;
        const out = try w.a.alloc(Entry, av.len);
        for (av, out) |e, *o| o.* = .{ .path = eps, .cell = e.cell, .approx = e.approx, .grown = e.grown };
        std.mem.sort(Entry, out, {}, struct {
            fn less(_: void, p: Entry, q: Entry) bool {
                if (p.cell != q.cell) return p.cell < q.cell;
                return p.approx < q.approx;
            }
        }.less);
        var n: usize = 1;
        for (out[1..]) |e| {
            if (e.cell == out[n - 1].cell) continue;
            out[n] = e;
            n += 1;
        }
        return out[0..n];
    }

    /// A value's deep condition (§18.2): every cell it holds, and no cell at
    /// two of its paths neither of which is a prefix of the other.
    fn deepCond(w: *Walker, av: AV) Allocator.Error!u32 {
        if (av.len == 0) return cond_yes;
        const xc = try w.expandCond(av, true);
        const ex = xc.av;
        if (ex.len > 8) return w.deepIndexed(ex, xc.k);
        var acc: CondAcc = .{};
        try acc.add(w, xc.k);
        for (ex) |e| try acc.add(w, try w.cellCond(e.cell));
        for (ex, 0..) |e, i| for (ex[i + 1 ..]) |f| {
            if (!try w.nested(e, f)) try acc.add(w, try w.sepCells(e.cell, f.cell, e.approx == 0 and f.approx == 0));
        };
        const k = try w.condAndAll(&acc);
        if (std.debug.runtime_safety and ex.len > 1 and !w.condSame(k, try w.deepIndexed(ex, xc.k))) std.debug.panic("ownership: indexed deep condition differs from pairwise", .{});
        return k;
    }

    /// The pairwise deep condition, omitting only pairs sepCells proves yes
    /// from their kinds alone. The index is shared with spine read-off.
    fn deepIndexed(w: *Walker, ex_in: AV, expansion: u32) Allocator.Error!u32 {
        const ex = for (ex_in[1..], 0..) |e, i| {
            if (ex_in[i].path > e.path) break try w.norm(try w.a.dupe(Entry, ex_in));
        } else ex_in;
        const idx = try w.spineIndex(ex);
        var acc: CondAcc = .{};
        try acc.add(w, expansion);
        for (ex) |e| try acc.add(w, try w.cellCond(e.cell));
        for (ex) |e| {
            if (acc.shared or acc.lost or acc.limit) break;
            const c = w.cells.items[e.cell];
            switch (c.kind) {
                .closure, .func => {},
                .taken, .top, .payload, .except => try w.deepPairs(&acc, ex, e),
                .shared => {
                    try w.deepPairs(&acc, idx.odd.items, e);
                    if (idx.family.get(.{ @backingInt(c.kind), c.a, c.b })) |f| try w.deepPairs(&acc, f.items, e);
                },
                .site, .result => {
                    try w.deepPairs(&acc, idx.odd.items, e);
                    try w.deepPairs(&acc, idx.cbres.items, e);
                    if (idx.family.get(.{ @backingInt(c.kind), c.a, c.b })) |f| try w.deepPairs(&acc, f.items, e);
                },
                .param, .env, .cbres => {
                    try w.deepPairs(&acc, idx.odd.items, e);
                    try w.deepPairs(&acc, idx.arrived.items, e);
                    if (c.kind == .cbres) try w.deepPairs(&acc, idx.made.items, e);
                },
            }
        }
        if (!acc.shared and (acc.lost or acc.limit)) for (ex) |e| {
            if (try w.failedAt(&idx, e, acc.limit, .list, true) == cond_shared) {
                acc.shared = true;
                break;
            }
        };
        const k = try w.condAndAll(&acc);
        if (std.debug.runtime_safety and ex.len > 8 and @import("ownership_options").full_cross_check) {
            var want: CondAcc = .{};
            try want.add(w, expansion);
            for (ex) |e| try want.add(w, try w.cellCond(e.cell));
            for (ex, 0..) |e, i| for (ex[i + 1 ..]) |f| {
                if (!try w.nested(e, f)) try want.add(w, try w.sepCells(e.cell, f.cell, e.approx == 0 and f.approx == 0));
            };
            if (!w.condSame(k, try w.condAndAll(&want))) std.debug.panic("ownership: indexed deep condition differs from pairwise", .{});
        }
        return k;
    }

    fn deepPairs(w: *Walker, acc: *CondAcc, others: AV, e: Entry) Allocator.Error!void {
        // The index retains the value’s path order. Entries at one path
        // are alternative provenances, never two coexisting positions.
        var lo: usize = 0;
        var hi = others.len;
        while (lo < hi) {
            const mid = lo + (hi - lo) / 2;
            if (others[mid].path <= e.path) lo = mid + 1 else hi = mid;
        }
        for (others[lo..]) |f| {
            if (acc.shared or acc.lost or acc.limit) return;
            // Both candidate lists offer the pair: form it once, in value order.
            if (try w.nested(e, f)) continue;
            try acc.add(w, try w.sepCells(e.cell, f.cell, e.approx == 0 and f.approx == 0));
        }
    }

    /// Whether a deep condition may omit separation of two entries (§16.7).
    /// Different cells under a step-by-step prefix are a container and its
    /// contents. One cell at both is acyclic only if the shorter path names
    /// one place. Approximate views are not compared here; value-scoped
    /// construction conditions still separate coexisting stored operands.
    fn nested(w: *Walker, e: Entry, f: Entry) Allocator.Error!bool {
        const x = if (w.o.startsWith(e.path, f.path)) f.path else if (w.o.startsWith(f.path, e.path)) e.path else null;
        if (x) |prefix| {
            if (e.cell != f.cell) return true;
            if (!try w.o.representative(prefix) and !w.o.paths.any.items[prefix]) return true;
            return e.approx != 0 or f.approx != 0;
        }
        if (!w.o.overlap(e.path, f.path)) return false;
        // Both exact: one cell at two overlapping places is sharing
        // (`EnvPrefix`). Approximate views are not separated here; the
        // containing value still carries its construction conditions.
        if (e.cell == f.cell) return e.approx != 0 or f.approx != 0;
        return (try w.covers(e.cell, f.cell)) != null or (try w.covers(f.cell, e.cell)) != null;
    }

    /// The condition of stored items, pairwise and against what the list
    /// already holds (§18.2's table).
    fn storedCond(w: *Walker, items: []const AV, elements: AV) Allocator.Error!u32 {
        // The items and what the list holds are pairwise apart (§16.7,
        // #693), their cells read in the order the pairs read them: the
        // first nonempty item meets what the list holds and every later
        // item before the next item's deep condition.
        var acc: CondAcc = .{};
        const groups = try w.a.alloc(AV, items.len + 1);
        @memset(groups, &.{});
        var met = false;
        for (items, 0..) |v, i| {
            try acc.add(w, try w.deepCond(v));
            if (met or v.len == 0) continue;
            if (elements.len > 0) {
                groups[i] = try w.sepCellList(v);
                groups[items.len] = try w.sepCellList(elements);
                met = true;
            }
            for (items[i + 1 ..], i + 1..) |u, j| {
                if (u.len == 0) continue;
                if (groups[i].len == 0) groups[i] = try w.sepCellList(v);
                groups[j] = try w.sepCellList(u);
                met = true;
            }
        }
        try acc.add(w, try w.pairwiseApart(groups, .list));
        return w.condAndAll(&acc);
    }

    // ---- records' exclusive contents (§31.4 item 6) ------------------------
    //
    // A record condition is a list's in a table of its own (`rconds`,
    // `cell_rcond`), over record objects: `excl c` is `rexcl c`, `sep c d` is
    // `rsep c d`. No list's fact reads the table, and it has no cap.

    /// A record condition holding on `atoms`.
    fn rmkCond(w: *Walker, atoms: []const WAtom) Allocator.Error!u32 {
        if (atoms.len == 0) return cond_yes;
        var own = try w.a.dupe(WAtom, atoms);
        own.len = sortWAtoms(own);
        try w.rconds.append(w.a, .{ .atoms = own });
        return @intCast(w.rconds.items.len - 1);
    }

    /// A record condition's conjunction, gathered: failing exactly beats
    /// failing approximately, and a holding one rests on every atom.
    const RAcc = struct {
        shared: bool = false,
        lost: bool = false,
        limit: bool = false,
        /// The one condition added so far, while every condition added is
        /// that one (the common case: a container's `rexcl`, again and
        /// again), so that no new condition is made for it.
        one: u32 = cond_yes,
        many: bool = false,
        atoms: std.ArrayList(WAtom) = .empty,

        fn add(acc: *RAcc, w: *Walker, k: u32) Allocator.Error!void {
            switch (k) {
                cond_yes => {},
                cond_shared => acc.shared = true,
                cond_lost => acc.lost = true,
                cond_limit => acc.limit = true,
                else => {
                    if (acc.shared or acc.lost or acc.limit) return;
                    if (!acc.many and (acc.one == cond_yes or acc.one == k)) {
                        acc.one = k;
                        return;
                    }
                    if (!acc.many) {
                        acc.many = true;
                        try acc.atoms.appendSlice(w.a, w.rconds.items[acc.one].atoms);
                    }
                    try acc.atoms.appendSlice(w.a, w.rconds.items[k].atoms);
                },
            }
        }

        fn done(acc: *RAcc, w: *Walker) Allocator.Error!u32 {
            if (acc.shared) return cond_shared;
            if (acc.limit) return cond_limit;
            if (acc.lost) return cond_lost;
            if (!acc.many) return acc.one;
            return w.rmkCond(acc.atoms.items);
        }
    };

    /// Two record conditions' conjunction; one of them when the other adds
    /// no atom, so that a round that lowers nothing moves no index.
    fn rcondAnd(w: *Walker, x: u32, y: u32) Allocator.Error!u32 {
        if (x == y or y == cond_yes) return x;
        if (x == cond_yes) return y;
        if (x == cond_shared or y == cond_shared) return cond_shared;
        if (x == cond_limit or y == cond_limit) return cond_limit;
        if (x == cond_lost or y == cond_lost) return cond_lost;
        const xs = w.rconds.items[x].atoms;
        const ys = w.rconds.items[y].atoms;
        const all = try w.a.alloc(WAtom, xs.len + ys.len);
        @memcpy(all[0..xs.len], xs);
        @memcpy(all[xs.len..], ys);
        const n = sortWAtoms(all);
        if (n == xs.len) return x;
        if (n == ys.len) return y;
        return w.rmkCond(all[0..n]);
    }

    /// The cell a record condition names for `c`: the record an `except`
    /// cell was written over, a taken element's own. And one id per object:
    /// a result's record that may hold lists is a list-facing cell in `res`
    /// and its `nonlistOf` copy in `objs` (§31.7), two ids for one record,
    /// so a copy is named by the cell it copies, where that cell exists
    /// (`cell` interns: a record whose cell is always `nonlist` names
    /// itself).
    fn rbase(w: *Walker, c_in: u32) Allocator.Error!u32 {
        if (w.cell_rbase.items[c_in] != none) return w.cell_rbase.items[c_in];
        const b = try w.rbaseOnce(c_in);
        w.cell_rbase.items[c_in] = b;
        return b;
    }

    fn rbaseOnce(w: *Walker, c_in: u32) Allocator.Error!u32 {
        var c = c_in;
        while (w.cells.items[c].kind == .except) c = w.cells.items[c].a;
        const x = w.cells.items[c];
        if (!x.nonlist) return c;
        var y = x;
        y.nonlist = false;
        return w.cell(y);
    }

    /// A cell's record condition (§31.4 item 6): its table's, or its kind's —
    /// an arrival is `rexcl` of itself.
    fn rcellCond(w: *Walker, c_in: u32) Allocator.Error!u32 {
        const c = try w.rbase(c_in);
        if (w.o.in.records_lost) return cond_lost;
        if (w.cell_rcond.items[c] != none) return w.cell_rcond.items[c];
        const x = w.cells.items[c];
        if (!try w.mayHoldRecord(c)) return cond_yes;
        const k: u32 = switch (x.kind) {
            .site, .shared, .closure, .func => cond_yes,
            .top, .payload => cond_lost,
            .result => if (x.path != eps) blk: {
                var root = x;
                root.path = eps;
                root.ty = .none;
                root.nonlist = false;
                break :blk try w.rcellCond(try w.cell(root));
            } else cond_lost,
            .except => unreachable,
            .param, .env, .cbres => try w.rmkCond(&.{.{ .kind = .excl, .a = c }}),
            .taken => if (w.instCol(?AV, w.split_scrut, x.b, null)) |scrut| blk: {
                var acc: RAcc = .{};
                for (scrut) |e| if (e.path == eps) {
                    try acc.add(w, try w.rcellCond(e.cell));
                };
                break :blk try acc.done(w);
            } else try w.rmkCond(&.{.{ .kind = .excl, .a = try w.containerOf(c) }}),
        };
        w.cell_rcond.items[c] = k;
        return k;
    }

    /// The record condition of a cell this walk made, which starts at `k`.
    fn rinitCond(w: *Walker, c_in: u32, k: u32) Allocator.Error!void {
        const c = try w.rbase(c_in);
        const cur = w.cell_rcond.items[c];
        const now = if (cur != none) try w.rcondAnd(cur, k) else k;
        w.noteWrite(.rcond, c, cur, now);
        w.cell_rcond.items[c] = now;
    }

    /// Lower a cell's record condition, as a store into it does.
    fn rlowerCond(w: *Walker, c: u32, k: u32) Allocator.Error!void {
        if (k == cond_yes) return;
        const b = try w.rbase(c);
        const now = try w.rcondAnd(try w.rcellCond(b), k);
        w.noteWrite(.rcond, b, w.cell_rcond.items[b], now);
        w.cell_rcond.items[b] = now;
    }

    fn arrived(k: CellKind) bool {
        return k == .param or k == .env or k == .cbres;
    }

    /// Whether two cells share no record object.
    fn rsepCells(w: *Walker, x_in: u32, y_in: u32, exact: bool) Allocator.Error!u32 {
        if (w.cells.items[x_in].condition_only or w.cells.items[y_in].condition_only) return cond_yes;
        const x = try w.rbase(x_in);
        const y = try w.rbase(y_in);
        const cx = w.cells.items[x];
        const cy = w.cells.items[y];
        if (cx.kind == .closure or cx.kind == .func or cy.kind == .closure or cy.kind == .func) return cond_yes;
        if (!try w.mayHoldRecord(x) or !try w.mayHoldRecord(y)) return cond_yes;
        if (x == y or (try w.covers(x, y)) != null or (try w.covers(y, x)) != null) {
            const one = !(try w.o.representative(cx.path)) and !(try w.o.representative(cy.path)) and w.o.exactRelatedPaths(cx.path, cy.path);
            return if (exact and one) cond_shared else cond_lost;
        }
        if (cx.kind == .top or cy.kind == .top or cx.kind == .payload or cy.kind == .payload) return cond_lost;
        if (cx.kind == .taken or cy.kind == .taken) {
            const t = if (cx.kind == .taken) x else y;
            const other = if (cx.kind == .taken) y else x;
            const base = try w.takenBase(t);
            if (other != base and (try w.covers(other, base)) != null) return cond_lost;
            if (other == base or (try w.covers(base, other)) != null) return w.rcellCond(t);
        }
        if (cx.kind == .shared or cy.kind == .shared) return cond_yes;
        if (madeHere(cx.kind) or madeHere(cy.kind)) {
            const made = if (madeHere(cx.kind)) x else y;
            const other = if (madeHere(cx.kind)) cy else cx;
            // A callback may return what it was handed.
            if (other.kind == .cbres) if (w.instCol(?AV, w.cb_args, other.b, null)) |args| {
                if ((try w.reaches(args, &.{.{ .path = eps, .cell = made }})) != null) return cond_lost;
            };
            return cond_yes;
        }
        return w.rmkCond(&.{if (x <= y) .{ .kind = .sep, .a = x, .b = y } else .{ .kind = .sep, .a = y, .b = x }});
    }

    /// Whether a cell may be or hold a record's object: an `except` cell is
    /// one; a cell of a known type is when the type may hold one.
    fn mayHoldRecord(w: *Walker, c: u32) Allocator.Error!bool {
        if (w.cell_rec.items[c] != 0) return w.cell_rec.items[c] == 2;
        const x = w.cells.items[c];
        const yes = x.kind == .except or if (x.ty.unwrap()) |v| try w.o.holdsRecord(w.store, v, 0) else true;
        w.cell_rec.items[c] = if (yes) 2 else 1;
        return yes;
    }

    /// The record cells a value holds, closures expanded, each once: exact
    /// when any entry reaches it exactly. A cell that holds no record is no
    /// place of one (`mayHoldRecord`).
    fn rcellsOf(w: *Walker, av: AV) Allocator.Error!AV {
        if (av.len < wide_index) return w.rcellsOfRaw(av);
        for (av) |e| if (w.cells.items[e.cell].kind == .closure) return w.rcellsOfRaw(av);
        const key: [2]usize = .{ @intFromPtr(av.ptr), av.len };
        if (w.record_shapes.get(key)) |shape| return shape;
        const shape = try w.rcellsOfRaw(av);
        try w.record_shapes.put(w.a, key, shape);
        return shape;
    }

    fn rcellsOfRaw(w: *Walker, av: AV) Allocator.Error!AV {
        var out: std.ArrayList(Entry) = .empty;
        for (try w.expand(av)) |e| {
            const k = w.cells.items[e.cell].kind;
            if (k == .closure or k == .func) continue;
            if (!try w.mayHoldRecord(e.cell)) continue;
            try out.append(w.a, .{ .path = e.path, .cell = try w.rbase(e.cell), .approx = e.approx });
        }
        return out.items;
    }

    /// Whether two values share no record object.
    fn rsepValues(w: *Walker, x: AV, y: AV) Allocator.Error!u32 {
        if (x.len == 0 or y.len == 0) return cond_yes;
        return w.rsepOfCells(try w.rsepCellList(x), try w.rsepCellList(y));
    }

    /// The record cells `rsepValues` compares for `x`.
    fn rsepCellList(w: *Walker, x: AV) Allocator.Error!AV {
        return w.cellsOf(try w.rcellsOf(x));
    }

    /// `rsepValues` over two values' `rsepCellList`.
    fn rsepOfCells(w: *Walker, ex: AV, ey: AV) Allocator.Error!u32 {
        var acc: RAcc = .{};
        for (ex) |a| for (ey) |b| {
            try acc.add(w, try w.rsepCells(a.cell, b.cell, a.approx == 0 and b.approx == 0));
            if (acc.shared) return cond_shared;
            if (acc.lost or acc.limit) return w.sepFailed(ex, ey, .record, acc.limit);
        };
        return acc.done(w);
    }

    /// A value's deep record condition: its cells' record conditions, and no
    /// record object at two of its paths neither of which is a prefix of the
    /// other. Built without pairing every two cells (§31.4 item 6, no cap):
    /// one cell at two such paths is found by a sort, and a pair is formed
    /// only where neither cell is one the body made.
    fn rdeepCond(w: *Walker, av: AV) Allocator.Error!u32 {
        if (av.len == 0) return cond_yes;
        const ex = try w.rcellsOf(av);
        if (ex.len == 0) return cond_yes;
        if (ex.len == 1) return w.rcellCond(ex[0].cell);
        var acc: RAcc = .{};
        for (ex) |e| try acc.add(w, try w.rcellCond(e.cell));
        // One cell at two places that do not nest: pairwise for a few
        // entries, sorted by cell for more.
        if (ex.len <= 16) {
            for (ex, 0..) |e, a| for (ex[a + 1 ..]) |f| {
                if (e.cell != f.cell or try w.nested(e, f)) continue;
                const one = !(try w.o.representative(e.path)) and !(try w.o.representative(f.path));
                try acc.add(w, if (e.approx == 0 and f.approx == 0 and one) cond_shared else cond_lost);
            };
        } else try w.rduplicates(ex, &acc);
        if (acc.shared) return cond_shared;
        // Two distinct cells: what the body made shares nothing with another
        // cell but a callback's answer it was handed (`rsepCells`), so only
        // those pairs and the pairs of arrivals are formed.
        // A container and what it holds are not two places (`nested`).
        // A pair of cells is asked once, however many paths hold them: an
        // expanded value names one parameter at many paths.
        var seen: std.HashMapUnmanaged([3]u32, void, WordsKey(3), std.hash_map.default_max_load_percentage) = .empty;
        var after_path: usize = 0;
        for (ex, 0..) |e, a| {
            if (acc.shared or acc.lost or acc.limit) break;
            if (after_path <= a) {
                after_path = a + 1;
                while (after_path < ex.len and ex[after_path].path == e.path) : (after_path += 1) {}
            }
            const ke = w.cells.items[e.cell].kind;
            if (!arrived(ke) and ke != .taken and ke != .top and ke != .payload and ke != .except) continue;
            for (ex[after_path..]) |f| {
                if (acc.shared or acc.lost or acc.limit) break;
                const kf = w.cells.items[f.cell].kind;
                // Two arrivals, or a callback's answer and what the body made.
                const pair = if (madeHere(kf)) ke == .cbres else kf != .site and kf != .shared;
                if (!pair or e.cell == f.cell) continue;
                try w.rpairOnce(&seen, e, f, &acc);
            }
            // What the body made before it, against a callback's answer.
            if (ke == .cbres) for (ex[0..a]) |f| {
                if (acc.shared or acc.lost or acc.limit) break;
                if (e.path == f.path) continue;
                if (!madeHere(w.cells.items[f.cell].kind)) continue;
                try w.rpairOnce(&seen, e, f, &acc);
            };
        }
        if (!acc.shared and (acc.lost or acc.limit)) {
            const idx = try w.spineIndex(ex);
            for (ex) |e| {
                if (try w.failedAt(&idx, e, acc.limit, .record, true) == cond_shared) {
                    acc.shared = true;
                    break;
                }
            }
        }
        return acc.done(w);
    }

    /// `rsepCells` of two entries' cells into `acc`, unless the pair was
    /// asked already, or the entries nest.
    fn rpairOnce(w: *Walker, seen: *std.HashMapUnmanaged([3]u32, void, WordsKey(3), std.hash_map.default_max_load_percentage), e: Entry, f: Entry, acc: *RAcc) Allocator.Error!void {
        const exact: u32 = @intFromBool(e.approx == 0 and f.approx == 0);
        const key: [3]u32 = if (e.cell < f.cell) .{ e.cell, f.cell, exact } else .{ f.cell, e.cell, exact };
        if (seen.contains(key)) return;
        if (try w.nested(e, f)) return;
        try seen.put(w.a, key, {});
        try acc.add(w, try w.rsepCells(e.cell, f.cell, exact == 1));
    }

    /// `rdeepCond`'s one cell at two places that do not nest, found by a
    /// sort.
    fn rduplicates(w: *Walker, ex: AV, acc: *RAcc) Allocator.Error!void {
        if (acc.shared or acc.lost or acc.limit) return;
        const by_cell = try w.a.dupe(Entry, ex);
        std.mem.sort(Entry, by_cell, {}, struct {
            fn less(_: void, p: Entry, q: Entry) bool {
                if (p.cell != q.cell) return p.cell < q.cell;
                return p.path < q.path;
            }
        }.less);
        var i: usize = 0;
        while (i < by_cell.len) {
            var j = i + 1;
            while (j < by_cell.len and by_cell[j].cell == by_cell[i].cell) : (j += 1) {}
            for (by_cell[i..j], i..) |e, a| for (by_cell[a + 1 .. j]) |f| {
                if (try w.nested(e, f)) continue;
                const one = !(try w.o.representative(e.path)) and !(try w.o.representative(f.path));
                try acc.add(w, if (e.approx == 0 and f.approx == 0 and one) cond_shared else cond_lost);
                if (acc.shared or acc.lost or acc.limit) return;
            };
            i = j;
        }
    }

    /// The record condition of stored items, pairwise and against what the
    /// list already holds.
    fn rstoredCond(w: *Walker, items: []const AV, elements: AV) Allocator.Error!u32 {
        var acc: RAcc = .{};
        // Each value's record cells once, not once per pair.
        const cells = try w.a.alloc(AV, items.len);
        for (items, cells) |v, *c| c.* = try w.cellsOf(try w.rcellsOf(v));
        const ecells = try w.cellsOf(try w.rcellsOf(elements));
        for (items, cells) |v, cv| {
            if (cv.len == 0) continue;
            try acc.add(w, try w.rdeepCond(v));
            if (acc.shared) return cond_shared;
        }
        // The items and what the list holds, pairwise apart (§16.7, #693).
        const groups = try w.a.alloc(AV, items.len + 1);
        @memcpy(groups[0..items.len], cells);
        groups[items.len] = ecells;
        try acc.add(w, try w.pairwiseApart(groups, .record));
        return acc.done(w);
    }

    /// `rsepValues` over two values' record cells, gathered in `acc`.
    fn rsepCellsOf(w: *Walker, ex: AV, ey: AV, acc: *RAcc) Allocator.Error!void {
        for (ex) |a| for (ey) |b| {
            try acc.add(w, try w.rsepCells(a.cell, b.cell, a.approx == 0 and b.approx == 0));
        };
    }

    /// Relying on a record condition: its atoms become requirements of
    /// `frame` (`rxreq`), or it fails.
    fn rrely(w: *Walker, k: u32, frame: u32) Allocator.Error!Rely {
        if (k == cond_lost) return .approx;
        if (k == cond_limit) return .limit;
        if (k == cond_shared) return .exact;
        const atoms = w.rconds.items[k].atoms;
        for (atoms) |t| if (!w.ownedBy(t, frame)) return .approx;
        for (atoms) |t| try w.rreqs.append(w.a, .{ .frame = frame, .atom = t });
        return .ok;
    }

    /// A record condition in a summary's vocabulary.
    fn rxsumOf(w: *Walker, k: u32, frame: u32, params: []const Inst.Index, self: u32) Allocator.Error!XSum {
        if (k == cond_lost or k == cond_limit) return .{ .no = 1 };
        if (k == cond_shared) return .{ .no = 2 };
        var out: std.ArrayList(XAtom) = .empty;
        for (w.rconds.items[k].atoms) |t| {
            if (self != none and t.kind == .excl and t.a == (try w.rbase(self))) continue;
            if (!try w.xatomsOf(t, frame, params, false, &out)) return .{ .no = 1 };
        }
        return .{ .atoms = w.o.pruneAtoms(out.items) };
    }

    /// One condition's provenances at a call, each instantiated once
    /// (#684). A construction's condition (§16.7, *as amended 2026-10-22*)
    /// names every pair of its operands, so one parameter's projection is
    /// named by as many atoms as the construction has operands, and was
    /// projected again at each. A parameter's provenance is a projection of
    /// what the call is handed: it reads nothing an atom's instantiation
    /// changes, and the cells it reaches are interned, so the first atom
    /// that names it makes every cell, in the order it always did, and a
    /// later one would only find them. Its cells as `sepValues` and
    /// `rsepValues` read them are kept too, for a value that holds no
    /// closure, where they are its own entries; a closure's expansion reads
    /// the locals it captured, which an atom that walks a callback may
    /// bind. Every other provenance kind may act (escape, carry, iterate a
    /// callback) and is instantiated at every atom, as before.
    const ProvMemo = struct {
        const Known = struct { av: AV, has_closure: bool, cells: ?AV = null, rcells: ?AV = null };
        map: std.HashMapUnmanaged([4]u32, Known, WordsKey(4), std.hash_map.default_max_load_percentage) = .empty,
        /// The condition's atom count: room for both provenances of each.
        atoms: usize,

        /// A parameter's provenance as a key: its kind is implied.
        fn key(p: Prov) [4]u32 {
            const flags = @as(u32, @intFromBool(p.taken)) | (@as(u32, @intFromBool(p.obj)) << 1) | (@as(u32, @intFromBool(p.condition_only)) << 2);
            return .{ flags, p.a, p.b, p.path };
        }

        fn get(m: *ProvMemo, w: *Walker, p: Prov, ctx: InstCtx) Allocator.Error!AV {
            if (p.kind != .param) return w.instProv(p, ctx);
            if (m.map.capacity() == 0) try m.map.ensureTotalCapacity(w.a, @intCast(2 * m.atoms));
            const g = try m.map.getOrPut(w.a, key(p));
            // `instProv` never reads or grows this map.
            if (!g.found_existing) {
                const av = try w.instProv(p, ctx);
                const has_closure = for (av) |e| {
                    if (w.cells.items[e.cell].kind == .closure) break true;
                } else false;
                g.value_ptr.* = .{ .av = av, .has_closure = has_closure };
            }
            return g.value_ptr.av;
        }

        /// The entry for `p` whose cells may be kept, or null.
        fn keeps(m: *ProvMemo, p: Prov) ?*Known {
            if (p.kind != .param) return null;
            const known = m.map.getPtr(key(p)).?;
            return if (known.has_closure) null else known;
        }

        fn cells(m: *ProvMemo, w: *Walker, p: Prov, av: AV) Allocator.Error!AV {
            const known = m.keeps(p) orelse return w.sepCellList(av);
            if (known.cells == null) known.cells = try w.sepCellList(av);
            return known.cells.?;
        }

        fn rcells(m: *ProvMemo, w: *Walker, p: Prov, av: AV) Allocator.Error!AV {
            const known = m.keeps(p) orelse return w.rsepCellList(av);
            if (known.rcells == null) known.rcells = try w.rsepCellList(av);
            return known.rcells.?;
        }

        /// `sepValues(instProv(a), instProv(b))`.
        fn sep(m: *ProvMemo, w: *Walker, a: Prov, b: Prov, ctx: InstCtx) Allocator.Error!u32 {
            const x = try m.get(w, a, ctx);
            const y = try m.get(w, b, ctx);
            if (x.len == 0 or y.len == 0) return cond_yes;
            const ex = try m.cells(w, a, x);
            return w.sepOfCells(ex, try m.cells(w, b, y));
        }

        /// `rsepValues(instProv(a), instProv(b))`.
        fn rsep(m: *ProvMemo, w: *Walker, a: Prov, b: Prov, ctx: InstCtx) Allocator.Error!u32 {
            const x = try m.get(w, a, ctx);
            const y = try m.get(w, b, ctx);
            if (x.len == 0 or y.len == 0) return cond_yes;
            const ex = try m.rcells(w, a, x);
            return w.rsepOfCells(ex, try m.rcells(w, b, y));
        }
    };

    /// A summary's record condition, instantiated at a call.
    fn rinstXSum(w: *Walker, x: XSum, ctx: InstCtx) Allocator.Error!u32 {
        if (x.no == 1) return cond_lost;
        if (x.no == 2) return cond_shared;
        var acc: RAcc = .{};
        var memo: ProvMemo = .{ .atoms = atomsWeight(x.atoms) };
        for (x.atoms) |t| {
            const c = switch (t.kind) {
                .excl => try w.rdeepCond(try memo.get(w, t.a, ctx)),
                .sep => if (t.a.eql(t.b) and t.a.kind == .cb)
                    try w.rfreshAcross(t.a.a, ctx)
                else
                    try memo.rsep(w, t.a, t.b, ctx),
                .keep => try w.rkeepShape(t.a.a, t.b, ctx),
                .apart => try w.instPairwiseApart(t, ctx, &memo, .record),
                // A spine is a list's array.
                .spine, .sep_spine, .keep_spine, .apart_spine, .sep_root => cond_yes,
            };
            if (c == cond_shared) return cond_shared;
            try acc.add(w, c);
        }
        return acc.done(w);
    }

    /// A summary's `apart` at a call (§16.7, #693): each group's provenances
    /// instantiated once and joined, their cells read once, and
    /// `pairwiseApart` over them. A callback's result that two groups name
    /// is `sep cb_j cb_j`, fresh across calls, which is not the separation
    /// of its two instantiations: that apart instantiates its expansion.
    fn instPairwiseApart(w: *Walker, t: XAtom, ctx: InstCtx, memo: *ProvMemo, fl: Fl) Allocator.Error!u32 {
        if (repeatsCallback(t)) return w.instExpanded(t, ctx, memo, fl);
        const groups = try w.a.alloc(AV, t.groups.len);
        for (groups, t.groups) |*g, provs| {
            var cells: std.ArrayList(Entry) = .empty;
            for (provs) |p| {
                const av = try memo.get(w, p, ctx);
                if (av.len == 0) continue;
                try cells.appendSlice(w.a, switch (fl) {
                    .list => try memo.cells(w, p, av),
                    .record => try memo.rcells(w, p, av),
                });
            }
            g.* = try w.cellsOf(cells.items);
        }
        const k = try w.pairwiseApartOnce(groups, fl);
        const sizes = try w.a.alloc(usize, t.groups.len);
        for (sizes, t.groups) |*s, g| s.* = g.len;
        if (checksApart(sizes)) {
            const want = try w.instExpanded(t, ctx, memo, fl);
            if (!try w.condSameExpanded(k, want, fl)) std.debug.panic("ownership: an instantiated pairwise-apart condition differs from its expansion's", .{});
        }
        return k;
    }

    /// Whether a callback's result is a member of two groups.
    fn repeatsCallback(t: XAtom) bool {
        for (t.groups, 0..) |g, i| for (g) |p| {
            if (p.kind != .cb) continue;
            for (t.groups[i + 1 ..]) |h| for (h) |q| {
                if (p.eql(q)) return true;
            };
        };
        return false;
    }

    /// An apart's expansion instantiated pair by pair, as `instXSum` and
    /// `rinstXSum` instantiate a `sep` and a `sep_spine`.
    fn instExpanded(w: *Walker, t: XAtom, ctx: InstCtx, memo: *ProvMemo, fl: Fl) Allocator.Error!u32 {
        var pairs: std.ArrayList(XAtom) = .empty;
        try expandAtom(w.a, t, &pairs);
        var acc: FlAcc = .{ .fl = fl };
        for (sortAtoms(pairs.items)) |p| {
            const c = switch (fl) {
                .list => switch (p.kind) {
                    .sep => if (p.a.eql(p.b) and p.a.kind == .cb) try w.freshAcross(p.a.a, ctx) else try memo.sep(w, p.a, p.b, ctx),
                    .sep_spine => try w.sepSpineValues(try memo.get(w, p.a, ctx), try memo.get(w, p.b, ctx)),
                    else => unreachable,
                },
                .record => switch (p.kind) {
                    .sep => if (p.a.eql(p.b) and p.a.kind == .cb) try w.rfreshAcross(p.a.a, ctx) else try memo.rsep(w, p.a, p.b, ctx),
                    .sep_spine => cond_yes,
                    else => unreachable,
                },
            };
            if (c == cond_shared) return cond_shared;
            try acc.add(w, c);
        }
        return acc.done(w);
    }

    /// Relying on a condition (§18.4): its atoms become requirements of
    /// `frame`, or it fails.
    fn rely(w: *Walker, k: u32, frame: u32) Allocator.Error!Rely {
        return w.relyAs(k, frame, true);
    }

    /// `rely`, the requirements kept only when `keep`.
    fn relyAs(w: *Walker, k: u32, frame: u32, keep: bool) Allocator.Error!Rely {
        if (k == cond_lost) return .approx;
        if (k == cond_limit) return .limit;
        if (k == cond_shared) return .exact;
        const atoms = w.conds.items[k].atoms;
        for (atoms) |t| if (!w.ownedBy(t, frame)) return .approx;
        if (keep) for (atoms) |t| try w.reqs.append(w.a, .{ .frame = frame, .atom = t });
        return .ok;
    }

    fn ownedBy(w: *Walker, t: WAtom, frame: u32) bool {
        return switch (t.kind) {
            .excl, .spine => w.atomCellIn(t.a, frame),
            .sep, .sep_spine, .sep_root => w.atomCellIn(t.a, frame) and w.atomCellIn(t.b, frame),
            .keep, .keep_spine => frame == 0 and w.atomCellIn(t.b, frame),
            // Every member is in some pair of its expansion.
            .apart, .apart_spine => w.apartOwnedBy(t.a, frame),
        };
    }

    fn apartOwnedBy(w: *Walker, idx: u32, frame: u32) bool {
        for (w.aparts.items[idx]) |g| for (g) |c| {
            if (!w.atomCellIn(c, frame)) return false;
        };
        return true;
    }

    /// Whether `frame` can state an atom about cell `c`: one of its own
    /// parameters, one of its captures, or the declaration's callback result.
    fn atomCellIn(w: *Walker, c: u32, frame: u32) bool {
        const x = w.cells.items[c];
        return switch (x.kind) {
            .param => if (x.b == 0) frame == 0 else if (w.lambdaParam(x)) |lp| w.closures.items[lp[0]].frame == frame else false,
            .cbres => frame == w.callbackFrame(x),
            .env => frame != 0,
            .taken => w.atomCellIn(x.a, frame),
            .except => x.b != except_all and w.atomCellIn(x.a, frame),
            .site, .result, .shared, .top, .closure, .func, .payload => false,
        };
    }

    /// A condition in a summary's vocabulary (§18.3), for the frame whose
    /// parameters are `params`; `self`'s own `excl` is left to
    /// instantiation.
    fn xsumOf(w: *Walker, k: u32, frame: u32, params: []const Inst.Index, self: u32) Allocator.Error!XSum {
        if (k == cond_lost or k == cond_limit) return .{ .no = 1 };
        if (k == cond_shared) return .{ .no = 2 };
        var out: std.ArrayList(XAtom) = .empty;
        for (w.conds.items[k].atoms) |t| {
            if ((t.kind == .excl or t.kind == .spine) and t.a == self) continue;
            if (!try w.xatomsOf(t, frame, params, false, &out)) return .{ .no = 1 };
        }
        return .{ .atoms = w.o.pruneAtoms(out.items) };
    }

    fn xatomOf(w: *Walker, t: WAtom, frame: u32, params: []const Inst.Index) Allocator.Error!?XAtom {
        if (t.kind == .keep or t.kind == .keep_spine) {
            if (frame != 0) return null;
            return .{ .kind = t.kind, .a = .{ .kind = .cb, .a = t.a, .path = t.path }, .b = (try w.atomProv(t.b, frame, params)) orelse return null };
        }
        const a = (try w.atomProv(t.a, frame, params)) orelse return null;
        return switch (t.kind) {
            .excl, .spine => .{ .kind = t.kind, .a = a },
            .sep_root => .{ .kind = .sep_root, .a = a, .b = (try w.atomProv(t.b, frame, params)) orelse return null },
            .sep, .sep_spine => blk: {
                var atom = sepAtom(a, (try w.atomProv(t.b, frame, params)) orelse return null);
                atom.kind = t.kind;
                break :blk atom;
            },
            .keep, .keep_spine, .apart, .apart_spine => unreachable,
        };
    }

    /// `t` in a summary's vocabulary, appended to `out`; false when a cell
    /// it names has no provenance here. An apart (§16.7, #693) maps each
    /// member; with `drop`, a member with none leaves its group, which
    /// removes exactly the pairs of its expansion that `xatomOf` would have
    /// dropped one by one; without, the atom has none, as one of its pairs
    /// would.
    fn xatomsOf(w: *Walker, t: WAtom, frame: u32, params: []const Inst.Index, drop: bool, out: *std.ArrayList(XAtom)) Allocator.Error!bool {
        const keep = w.o.keep.allocator();
        if (t.kind != .apart and t.kind != .apart_spine) {
            const x = (try w.xatomOf(t, frame, params)) orelse return false;
            try out.append(keep, x);
            return true;
        }
        const src = w.aparts.items[t.a];
        const gs = try keep.alloc([]Prov, src.len);
        for (gs, src) |*d, g| {
            var ps: std.ArrayList(Prov) = .empty;
            for (g) |c| {
                if (try w.atomProv(c, frame, params)) |p| {
                    try ps.append(keep, p);
                } else if (!drop) return false;
            }
            d.* = ps.items;
        }
        try apartAtoms(keep, t.kind, gs, out);
        return true;
    }

    fn atomProv(w: *Walker, c: u32, frame: u32, params: []const Inst.Index) Allocator.Error!?Prov {
        const x = w.cells.items[c];
        return switch (x.kind) {
            .param => if (w.paramIndex(x, frame, params)) |i| .{ .kind = .param, .a = i, .path = x.path } else null,
            .cbres => if (frame == w.callbackFrame(x)) .{ .kind = .cb, .a = x.a, .path = x.path } else null,
            .env => if (frame != 0) .{ .kind = .env, .a = x.a, .path = x.path } else null,
            .taken, .except => if (try w.takenBase(c) == c) null else w.atomProv(try w.takenBase(c), frame, params),
            .site, .result, .shared, .top, .closure, .func, .payload => null,
        };
    }

    /// A summary's condition, instantiated at a call (§18.4).
    fn instXSum(w: *Walker, x: XSum, ctx: InstCtx) Allocator.Error!u32 {
        if (x.no == 1) return cond_lost;
        if (x.no == 2) return cond_shared;
        // The conjunction gathered and sorted once (§16.3's amendment): a
        // fold of `condAnd` re-sorts what it holds at every atom.
        var acc: CondAcc = .{};
        var memo: ProvMemo = .{ .atoms = atomsWeight(x.atoms) };
        for (x.atoms) |t| {
            const c = switch (t.kind) {
                .excl => try w.deepCond(try memo.get(w, t.a, ctx)),
                .spine => try w.spineCond(try memo.get(w, t.a, ctx)),
                .sep_spine => try w.sepSpineValues(try memo.get(w, t.a, ctx), try memo.get(w, t.b, ctx)),
                .sep_root => try w.sepRootValues(try memo.get(w, t.a, ctx), try memo.get(w, t.b, ctx)),
                .keep_spine => try w.keepSpine(t.a.a, t.a.path, t.b, ctx),
                .sep => if (t.a.eql(t.b) and t.a.kind == .cb)
                    try w.freshAcross(t.a.a, ctx)
                else
                    try memo.sep(w, t.a, t.b, ctx),
                .keep => try w.keepShape(t.a.a, t.b, ctx),
                .apart => try w.instPairwiseApart(t, ctx, &memo, .list),
                .apart_spine => try w.instExpanded(t, ctx, &memo, .list),
            };
            if (c == cond_shared) return cond_shared;
            try acc.add(w, c);
        }
        return w.condAndAll(&acc);
    }

    /// `sep cb_j cb_j` at a call: two calls of the actual for `π_j` return no
    /// cell in common — every provenance of its result is made during the
    /// call, or the element the callee hands it destructively (§18.4).
    fn freshAcross(w: *Walker, j: u32, ctx: InstCtx) Allocator.Error!u32 {
        if (j >= ctx.avs.len) return cond_lost;
        const actual = ctx.avs[j];
        if (w.fnParamOf(actual)) |jj| {
            if (w.frame != 0) return cond_lost;
            const c = try w.cell(.{ .kind = .cbres, .a = jj, .b = ctx.inst.int() });
            return w.atomCond(.{ .kind = .sep, .a = c, .b = c });
        }
        const classes = try w.classesOf(actual);
        if (classes.len == 0) return cond_lost;
        var acc: CondAcc = .{};
        for (classes) |cls| {
            const c = (try w.callbackSummary(cls, j, ctx)) orelse return cond_lost;
            if (c.limit != .none) return cond_limit;
            for (c.res) |r| switch (r.prov.kind) {
                .fresh, .esc => {},
                .param => try acc.add(w, try w.takenSupply(j, r.prov, ctx)),
                else => return cond_lost,
            };
        }
        return w.condAndAll(&acc);
    }

    /// `rsep cb_j cb_j` at a call: two calls of the actual for `π_j` return no
    /// record object in common — each answer's object made during the call,
    /// or the element the callee hands it destructively.
    fn rfreshAcross(w: *Walker, j: u32, ctx: InstCtx) Allocator.Error!u32 {
        if (j >= ctx.avs.len) return cond_lost;
        const actual = ctx.avs[j];
        if (w.fnParamOf(actual)) |jj| {
            if (w.frame != 0) return cond_lost;
            const c = try w.cell(.{ .kind = .cbres, .a = jj, .b = ctx.inst.int() });
            return w.rmkCond(&.{.{ .kind = .sep, .a = c, .b = c }});
        }
        const classes = try w.classesOf(actual);
        if (classes.len == 0) return cond_lost;
        var acc: RAcc = .{};
        for (classes) |cls| {
            const c = (try w.callbackSummary(cls, j, ctx)) orelse return cond_lost;
            if (c.limit != .none) return cond_limit;
            // What the declaration's own function parameters answer inside
            // the lambda (`cb` with `b` 1, §18.9; #868): two calls of the
            // lambda make two calls of each, so their answers are apart when
            // the parameter's are, `sep cb cb` of the declaration, which its
            // caller discharges with the actual's summary.
            var answered: std.ArrayList(u32) = .empty;
            for ([_][]const ResEntry{ c.objs, c.res }) |entries| for (entries) |r| {
                switch (r.prov.kind) {
                    .fresh, .esc => {},
                    .param => try acc.add(w, try w.rtakenSupply(j, r.prov, ctx)),
                    .cb => {
                        if (r.prov.b != 1 or w.frame != 0) return cond_lost;
                        const cb = try w.cell(.{ .kind = .cbres, .a = r.prov.a, .b = ctx.inst.int(), .path = r.prov.path });
                        try acc.add(w, try w.rmkCond(&.{.{ .kind = .sep, .a = cb, .b = cb }}));
                        try answered.append(w.a, cb);
                    },
                    else => return cond_lost,
                }
            };
            // An answer of a parameter at one call and the element the
            // callee hands the lambda at another: the parameter must answer
            // only records it makes or the element it is handed, `keep cb c`
            // of the declaration over the element's container, which its
            // caller discharges with the actual's summary (`rkeepShape`).
            if (answered.items.len != 0) for ([_][]const ResEntry{ c.objs, c.res }) |entries| for (entries) |r| {
                if (r.prov.kind != .param) continue;
                for ([_][]const SupplyEntry{ ctx.s.supply, ctx.s.rsupply }) |sup| for (sup) |e| {
                    if (e.prov.condition_only or e.fun != j or e.k != r.prov.a or !w.o.overlap(e.path, r.prov.path)) continue;
                    const at = w.o.steps(e.prov.path);
                    if (at.len == 0 or at[at.len - 1].kind != .elem) return cond_lost;
                    var container = e.prov;
                    container.taken = false;
                    container.path = eps;
                    for (at[0 .. at.len - 1]) |st| container.path = try w.o.child(container.path, st.kind, st.arg);
                    for (try w.instProv(container, ctx)) |held| {
                        if (held.path != eps) continue;
                        for (answered.items) |cb| {
                            const k = w.cells.items[cb].a;
                            try acc.add(w, try w.rmkCond(&.{.{ .kind = .keep, .a = k, .b = try w.rbase(held.cell) }}));
                        }
                    }
                };
            };
        }
        return acc.done(w);
    }

    /// `takenSupply` for records: what `ctx.s` supplies the actual for
    /// `π_j` at `p`, list or record supply, is only ever an element taken
    /// destructively, its container's record condition holding.
    fn rtakenSupply(w: *Walker, j: u32, p: Prov, ctx: InstCtx) Allocator.Error!u32 {
        var acc: RAcc = .{};
        var any = false;
        for ([_][]const SupplyEntry{ ctx.s.supply, ctx.s.rsupply }) |sup| for (sup) |e| {
            if (e.prov.condition_only or e.fun != j or e.k != p.a or !w.o.overlap(e.path, p.path)) continue;
            if (!e.prov.taken) return cond_lost;
            any = true;
            try acc.add(w, try w.rinstXSum(e.rxc, ctx));
        };
        return if (any) acc.done(w) else cond_lost;
    }

    /// `keepShape` for records (`keep cb_j c`): the actual for `π_j`,
    /// handed an element of `c` destructively, puts back records made
    /// during the call or the element's own at the same path, and holds no
    /// record at two places — so the container keeps no record twice.
    fn rkeepShape(w: *Walker, j: u32, container: Prov, ctx: InstCtx) Allocator.Error!u32 {
        if (j >= ctx.avs.len) return cond_lost;
        const actual = ctx.avs[j];
        if (w.fnParamOf(actual)) |jj| {
            if (w.frame != 0) return cond_lost;
            var acc: RAcc = .{};
            for (try w.instProv(container, ctx)) |e| {
                if (e.path != eps) continue;
                try acc.add(w, try w.rmkCond(&.{.{ .kind = .keep, .a = jj, .b = try w.rbase(e.cell) }}));
            }
            return acc.done(w);
        }
        const classes = try w.classesOf(actual);
        if (classes.len == 0) return cond_lost;
        var acc: RAcc = .{};
        for (classes) |cls| {
            const c = (try w.callbackSummary(cls, j, ctx)) orelse return cond_lost;
            if (c.limit != .none) return cond_limit;
            for ([_][]const ResEntry{ c.res, c.objs }) |entries| for (entries) |r| switch (r.prov.kind) {
                .fresh => {},
                .param => {
                    if (r.path != r.prov.path) return cond_lost;
                    try acc.add(w, try w.rtakenSupply(j, r.prov, ctx));
                },
                else => return cond_lost,
            };
        }
        try acc.add(w, try w.rdeepCond(try w.instProv(.{ .kind = .cb, .a = j }, ctx)));
        return acc.done(w);
    }

    /// Whether what callee `ctx.s` supplies the actual for `π_j` at the
    /// class's parameter `p` is only ever an element taken destructively:
    /// a different one at every call, as exclusive as its container.
    fn takenSupply(w: *Walker, j: u32, p: Prov, ctx: InstCtx) Allocator.Error!u32 {
        var acc: CondAcc = .{};
        var any = false;
        for (ctx.s.supply) |e| {
            if (e.prov.condition_only or e.fun != j or e.k != p.a or !w.o.overlap(e.path, p.path)) continue;
            if (!e.prov.taken) return cond_lost;
            any = true;
            try acc.add(w, try w.instXSum(e.xc, ctx));
        }
        return if (any) w.condAndAll(&acc) else cond_lost;
    }

    /// `keep cb_j c` at a call (the thesis's "keeps shape", §18.5): the
    /// actual for `π_j`, handed an element of `container` destructively,
    /// returns cells made during the call, or the element's own at the same
    /// path, and is exclusive inside.
    fn keepShape(w: *Walker, j: u32, container: Prov, ctx: InstCtx) Allocator.Error!u32 {
        if (j >= ctx.avs.len) return cond_lost;
        const actual = ctx.avs[j];
        if (w.fnParamOf(actual)) |jj| {
            if (w.frame != 0) return cond_lost;
            var acc: CondAcc = .{};
            for (try w.instProv(container, ctx)) |e| {
                if (e.path != eps) continue;
                try acc.add(w, try w.atomCond(.{ .kind = .keep, .a = jj, .b = e.cell }));
            }
            return w.condAndAll(&acc);
        }
        const classes = try w.classesOf(actual);
        if (classes.len == 0) return cond_lost;
        var acc: CondAcc = .{};
        for (classes) |cls| {
            const c = (try w.callbackSummary(cls, j, ctx)) orelse return cond_lost;
            if (c.limit != .none) return cond_limit;
            for (c.res) |r| switch (r.prov.kind) {
                .fresh => {},
                .param => {
                    if (r.path != r.prov.path) return cond_lost;
                    try acc.add(w, try w.takenSupply(j, r.prov, ctx));
                },
                else => return cond_lost,
            };
        }
        // And exclusive inside: the result as the call instantiates it.
        return w.condAnd(try w.condAndAll(&acc), try w.deepCond(try w.instProv(.{ .kind = .cb, .a = j }, ctx)));
    }

    /// Focus restores one selected container. Its contents need not be owned,
    /// but its root must be fresh or the root taken at that same result path.
    fn keepSpine(w: *Walker, j: u32, path: u32, container: Prov, ctx: InstCtx) Allocator.Error!u32 {
        const actual = (try w.actualOf(ctx.s, ctx.avs, j)) orelse return cond_lost;
        if (w.fnParamOf(actual)) |jj| {
            if (w.frame != 0) return cond_lost;
            var acc: CondAcc = .{};
            for (try w.instProv(container, ctx)) |e| if (e.path == eps) {
                try acc.add(w, try w.atomCond(.{ .kind = .keep_spine, .a = jj, .b = e.cell, .path = path }));
            };
            return w.condAndAll(&acc);
        }
        const classes = try w.classesOf(actual);
        if (classes.len == 0) return cond_lost;
        var acc: CondAcc = .{};
        for (classes) |cls| {
            const c = (try w.callbackSummary(cls, j, ctx)) orelse return cond_lost;
            if (c.limit != .none) return cond_limit;
            for (c.res) |r| {
                if (r.path != path) {
                    if (w.o.isPrefix(r.path, path)) return cond_lost;
                    continue;
                }
                switch (r.prov.kind) {
                    .fresh => {},
                    .param => {
                        if (r.prov.path != path) return cond_lost;
                        for (c.uses) |u| if (u.param == r.prov.a and u.bits & (bit_e | bit_j) != 0 and w.o.overlap(u.path, r.prov.path)) return cond_lost;
                        var found = false;
                        for (ctx.s.supply) |e| {
                            if (e.fun != j or e.k != r.prov.a or !e.owned or !e.prov.taken or !w.o.isPrefix(e.path, path)) continue;
                            found = true;
                            const tail = (try w.o.suffix(e.path, path)) orelse return cond_lost;
                            var p = e.prov;
                            p.path = try w.o.concat(p.path, tail);
                            try acc.add(w, try w.spineCond(try w.instProv(p, ctx)));
                        }
                        if (!found) return cond_lost;
                    },
                    else => return cond_lost,
                }
                // A replacement also stored at another position is not a transfer.
                for (c.res) |other| if (other.path != path and other.prov.eql(r.prov)) return cond_lost;
            }
        }
        const cb = Prov{ .kind = .cb, .a = j, .path = path };
        return w.condAnd(try w.condAndAll(&acc), try w.spineCond(try w.instProv(cb, ctx)));
    }

    // ---- uses, pending, escape -------------------------------------------

    /// The local and path an expression names, when it is a variable or a
    /// field path of one (§7.1).
    fn refPath(w: *Walker, inst: Inst.Index) Allocator.Error!?Capture {
        const tag = w.bir.instTag(inst);
        const data = w.bir.instData(inst);
        switch (tag) {
            .local => return .{ .local = data.lhs, .path = eps },
            .field_access => {
                const base = (try w.refPath(@fromBackingInt(@intCast(data.lhs)))) orelse return null;
                const sym = w.bir.symbol(@fromBackingInt(@intCast(data.rhs)));
                return .{ .local = base.local, .path = try w.o.child(base.path, .field, @backingInt(sym)) };
            },
            .tuple_index => {
                const base = (try w.refPath(@fromBackingInt(@intCast(data.lhs)))) orelse return null;
                return .{ .local = base.local, .path = try w.o.child(base.path, .tuple, data.rhs) };
            },
            else => return null,
        }
    }

    /// Record the uses a consumer makes of its operands, at a new point.
    /// `consume` of `value` matched by `pat`: when `pat` is a record pattern
    /// and `value` a variable path, a record demand reads the fields it
    /// binds, each a field read of its own (§31.4 item 5); a list's use is the
    /// whole value's, as before.
    fn consumeDestructured(w: *Walker, value: Inst.Index, pat: Inst.Index, tok: u32) Allocator.Error!void {
        const r = (try w.refPath(value)) orelse return w.consume(&.{value}, tok);
        if (w.bir.instTag(pat) != .pat_record or w.mode != .report) return w.consume(&.{value}, tok);
        w.use_destructure = true;
        try w.consume(&.{value}, tok);
        w.use_destructure = false;
        const b = w.bir;
        for (b.extraSlice(Bir.inlineRange(b.instData(pat)), u32)) |l| {
            const name = b.locals[w.decl.locals_start + l].name;
            const sym = if (name.unwrap()) |s| @backingInt(b.symbols[s]) else continue;
            try w.recordRead(.{ .local = r.local, .path = try w.o.child(r.path, .field, sym) }, tok, value.int(), l, sym);
        }
    }

    fn consume(w: *Walker, operands: []const Inst.Index, tok: u32) Allocator.Error!void {
        w.point += 1;
        for (operands) |op| try w.useOperand(op, tok, &.{});
    }

    fn useOperand(w: *Walker, op: Inst.Index, tok: u32, except: []const u32) Allocator.Error!void {
        if (try w.refPath(op)) |r| {
            // §28.6: the path as written, for a message.
            w.use_at = .{ w.rootToken(op), w.token(op) };
            defer w.use_at = .{ none, none };
            try w.useAt(r.local, r.path, tok, except);
        }
    }

    /// The callee of a call: the instruction that evaluated it, and for
    /// `r.load a` the field of the receiver `inst` whose value is called
    /// (§30.11), so that the call reads `r.load` and not all of `r`;
    /// `none` for any other call (no symbol index is `none`).
    const CalleeRef = struct { inst: Inst.Index, field: u32 = none };

    fn useCallee(w: *Walker, c: CalleeRef, tok: u32) Allocator.Error!void {
        if (c.field == none) return w.useOperand(c.inst, tok, &.{});
        if (try w.refPath(c.inst)) |r| {
            w.use_at = .{ w.rootToken(c.inst), w.token(c.inst) };
            defer w.use_at = .{ none, none };
            try w.useAt(r.local, try w.o.child(r.path, .field, c.field), tok, &.{});
        }
    }

    /// §31.14: a field path read where it is evaluated, for the record
    /// demand's per-field liveness.
    fn recordRead(w: *Walker, r: Capture, tok: u32, read_inst: u32, binding: u32, pattern_field: u32) Allocator.Error!void {
        if (r.local >= w.local_frame.len) return;
        if (w.local_frame[r.local] != w.frame and (w.local_av[r.local] == null or !w.inFrameOf(w.local_frame[r.local]))) return;
        try w.uses.append(w.a, .{ .local = r.local, .path = r.path, .point = w.point, .frame = w.frame, .ctx = w.ctx, .token = tok, .record_read = true, .read_inst = read_inst, .binding = binding, .pattern_field = pattern_field, .grown = w.use_grown });
    }

    fn useAt(w: *Walker, l: u32, path: u32, tok: u32, except: []const u32) Allocator.Error!void {
        // A local of this frame, or one this frame captured from an
        // enclosing one: a closure that gave up what it captured must not
        // read it again (§18.8, §23.7).
        if (l >= w.local_frame.len) return;
        if (w.local_frame[l] != w.frame and (w.local_av[l] == null or !w.inFrameOf(w.local_frame[l]))) return;
        try w.uses.append(w.a, .{ .local = l, .path = path, .except = except, .point = w.point, .frame = w.frame, .ctx = w.ctx, .token = tok, .at = w.use_at, .call = w.use_call, .call_at = w.use_call_at, .destructure = w.use_destructure, .reads_none = w.use_reads_none, .grown = w.use_grown });
    }

    /// The first token of a variable path: its root local's.
    fn rootToken(w: *const Walker, inst: Inst.Index) u32 {
        var at = inst;
        var depth: u32 = 0;
        while (depth < 64) : (depth += 1) switch (w.bir.instTag(at)) {
            .field_access, .tuple_index => at = @fromBackingInt(@intCast(w.bir.instData(at).lhs)),
            else => break,
        };
        return w.token(at);
    }

    /// Record, at the current point, a use of everything a closure value
    /// in `av` captured (§6.1 item 1): a temporary closure consumed by a call.
    fn useCaptures(w: *Walker, av: AV, tok: u32) Allocator.Error!void {
        for (av) |e| {
            const c = w.cells.items[e.cell];
            if (c.kind != .closure) continue;
            for (w.closures.items[c.a].captures) |cap| {
                if (cap.local >= w.local_frame.len or w.local_frame[cap.local] != w.frame) continue;
                try w.uses.append(w.a, .{ .local = cap.local, .path = cap.path, .point = w.point, .frame = w.frame, .ctx = w.ctx, .token = tok, .via = c.a });
            }
        }
    }

    /// `useCaptures` for each operand that is not a variable path: a
    /// variable holding a closure is a holder of its own, used at the call.
    fn useTemporaries(w: *Walker, insts: []const Inst.Index, avs: []const AV, tok: u32) Allocator.Error!void {
        for (insts, avs) |inst, av| {
            if ((try w.refPath(inst)) != null) continue;
            try w.useCaptures(av, tok);
        }
    }

    fn pushPending(w: *Walker, av: AV, inst: Inst.Index, by_call: bool) Allocator.Error!void {
        const is_ref = (try w.refPath(inst)) != null;
        try w.pending.append(w.a, .{ .av = av, .frame = w.frame, .token = w.token(inst), .is_ref = is_ref, .by_call = by_call });
    }

    fn popPending(w: *Walker, n: usize) void {
        w.pending.shrinkRetainingCapacity(w.pending.items.len - n);
    }

    /// Evaluate operands left to right; each is pending until the consumer
    /// runs (§7.4). The caller pops them.
    fn evalOperands(w: *Walker, insts: []const Inst.Index, by_call: bool) Allocator.Error![]AV {
        const out = try w.a.alloc(AV, insts.len);
        for (insts, out) |inst, *v| {
            v.* = try w.eval(inst);
            try w.pushPending(v.*, inst, by_call);
        }
        return out;
    }

    fn escape(w: *Walker, av: AV, at: u32) Allocator.Error!void {
        for (try w.expand(av)) |e| {
            const k = w.cells.items[e.cell].kind;
            if (k == .closure or k == .func) continue;
            try w.noteEscape(e.cell, at, 0, e.grown);
        }
    }

    /// §18.6: a function value handed to a `foreign` with no summary escapes
    /// what it captured — the foreign may keep it and call it later. Marked
    /// with the call, so that a rejection through it says so.
    fn escapeCapturesOf(w: *Walker, av: AV, at: u32, call: Inst.Index) Allocator.Error!void {
        for (try w.expand(av)) |e| {
            const k = w.cells.items[e.cell].kind;
            if (k == .closure or k == .func) continue;
            if (!w.o.hasStep(e.path, .env)) continue;
            try w.noteEscape(e.cell, at, call.int() + 1, e.grown);
        }
    }

    /// The escape of §18.6, through a callee's summary (its `J`).
    fn escapeWhy(w: *Walker, av: AV, at: u32, call: Inst.Index) Allocator.Error!void {
        for (try w.expand(av)) |e| {
            const k = w.cells.items[e.cell].kind;
            if (k == .closure or k == .func) continue;
            try w.noteEscape(e.cell, at, call.int() + 1, e.grown);
        }
    }

    fn escKey(x: Cell, path: u32) [4]u32 {
        return .{ @backingInt(x.kind), x.a, x.b, path };
    }

    /// Join `c` to Esc at `at` (§4.3), in the list and in the index by cell
    /// that `escapedBefore` reads.
    fn noteEscape(w: *Walker, c: u32, at: u32, why: u32, grown: Grown) Allocator.Error!void {
        if (w.cells.items[c].condition_only) return;
        // §31.2: an `except` cell with fields escapes the record cell it was
        // written over, which is what a list's facts look it up by.
        const x = w.cells.items[c];
        if (x.kind == .except and x.b != except_all) try w.noteEscape(x.a, at, why, grown);
        const key = escKey(w.cells.items[c], w.cells.items[c].path);
        const head = try w.esc_heads.getOrPut(w.a, key);
        const previous = if (head.found_existing) head.value_ptr.* else none;
        const event: u32 = @intCast(w.escaped.items.len);
        try w.escaped.append(w.a, .{ .cell = c, .point = at, .why = why, .ctx = w.ctx, .prev = previous, .grown = gJoin(grown, w.use_grown) });
        head.value_ptr.* = event;
        const gop = try w.esc_index.getOrPut(w.a, escKey(w.cells.items[c], w.cells.items[c].path));
        if (!gop.found_existing) gop.value_ptr.* = .{};
        const e = gop.value_ptr;
        if (why == 0) {
            e.gen = @min(e.gen, at);
        } else if (at < e.js) {
            e.js = at;
            e.why = why;
        }
    }

    /// The earliest escapes of `c` — of it, or of a cell that stands for it
    /// (§4.3: a symbolic cell stands for everything under it).
    fn escapeOf(w: *Walker, c: u32) Allocator.Error!EscAt {
        if (w.cells.items[c].condition_only) return .{};
        var out: EscAt = .{};
        for ([_]u32{ c, try w.takenBase(c) }) |cc| {
            const x = w.cells.items[cc];
            const symbolic = switch (x.kind) {
                .param, .result, .env, .shared, .cbres, .taken, .payload => true,
                .site, .top, .closure, .func, .except => false,
            };
            var at = x.path;
            while (true) {
                if (w.esc_index.get(escKey(x, at))) |e| {
                    out.gen = @min(out.gen, e.gen);
                    if (e.js < out.js) {
                        out.js = e.js;
                        out.why = e.why;
                    }
                }
                if (!symbolic or at == eps) break;
                at = w.o.paths.parent.items[at];
            }
        }
        return out;
    }

    /// Unescaped at a demand: an alternative arm cannot retain its cell.
    /// Summary read-off deliberately keeps escapeOf's union of every arm.
    fn escapeBefore(w: *Walker, c: u32) Allocator.Error!EscAt {
        var out: EscAt = .{};
        for ([_]u32{ c, try w.takenBase(c) }) |cc| {
            const x = w.cells.items[cc];
            const symbolic = switch (x.kind) {
                .param, .result, .env, .shared, .cbres, .taken, .payload => true,
                .site, .top, .closure, .func, .except => false,
            };
            var path = x.path;
            while (true) {
                var event = w.esc_heads.get(escKey(x, path)) orelse none;
                while (event != none) {
                    const e = w.escaped.items[event];
                    if (e.point < w.point and w.compatible(e.ctx, w.ctx)) {
                        if (e.why == 0) {
                            out.gen = @min(out.gen, e.point);
                        } else if (e.point < out.js) {
                            out.js = e.point;
                            out.why = e.why;
                        }
                    }
                    event = e.prev;
                }
                if (!symbolic or path == eps) break;
                path = w.o.paths.parent.items[path];
            }
        }
        return out;
    }

    fn isEscaped(w: *Walker, c: u32) Allocator.Error!bool {
        const e = try w.escapeOf(c);
        return e.gen != none or e.js != none;
    }

    // ---- branch contexts ---------------------------------------------------

    fn compatible(w: *const Walker, x: u32, y: u32) bool {
        var a = x;
        var b = y;
        var prev_a: u32 = none;
        var prev_b: u32 = none;
        while (w.ctx_nodes.items[a].depth > w.ctx_nodes.items[b].depth) {
            prev_a = a;
            a = w.ctx_nodes.items[a].parent;
        }
        while (w.ctx_nodes.items[b].depth > w.ctx_nodes.items[a].depth) {
            prev_b = b;
            b = w.ctx_nodes.items[b].parent;
        }
        while (a != b) {
            prev_a = a;
            prev_b = b;
            a = w.ctx_nodes.items[a].parent;
            b = w.ctx_nodes.items[b].parent;
        }
        if (prev_a == none or prev_b == none) return true;
        const na = w.ctx_nodes.items[prev_a];
        const nb = w.ctx_nodes.items[prev_b];
        return !(na.case_id == nb.case_id and na.arm != nb.arm);
    }

    /// The case two contexts are in different arms of, when `compatible`
    /// says they are not; null when they are.
    fn divergentCase(w: *const Walker, x: u32, y: u32) ?u32 {
        if (w.compatible(x, y)) return null;
        var a = x;
        var b = y;
        var prev_a: u32 = none;
        while (w.ctx_nodes.items[a].depth > w.ctx_nodes.items[b].depth) a = w.ctx_nodes.items[a].parent;
        while (w.ctx_nodes.items[b].depth > w.ctx_nodes.items[a].depth) b = w.ctx_nodes.items[b].parent;
        // Neither is above the other, or they would be compatible: the
        // children of their common ancestor are two arms of one case.
        std.debug.assert(a != b);
        while (a != b) {
            prev_a = a;
            a = w.ctx_nodes.items[a].parent;
            b = w.ctx_nodes.items[b].parent;
        }
        return w.ctx_nodes.items[prev_a].case_id;
    }

    // ---- binding -------------------------------------------------------------

    fn bindLocal(w: *Walker, l: u32, av: AV) Allocator.Error!void {
        if (l >= w.local_av.len) return;
        // §26.1: a local index is bound once per walk. Lowering gives every
        // binder — written or compiler-made — an index of its own, and BIR
        // is a tree, so no binder is walked twice; a local function group's
        // rounds restore `local_av` before walking again (`restore`). Were
        // one bound twice, a holder found through the first binding could
        // have its later reads resolved against the second.
        if (std.debug.runtime_safety) std.debug.assert(w.local_av[l] == null);
        w.local_av[l] = av;
        w.local_frame[l] = w.frame;
        w.local_ctx[l] = w.ctx;
        if (w.logs_bindings) try w.bound_log.append(w.a, l);
    }

    fn bindPattern(w: *Walker, pat: Inst.Index, av: AV) Allocator.Error!void {
        const b = w.bir;
        const data = b.instData(pat);
        switch (b.instTag(pat)) {
            .pat_var => try w.bindLocal(data.lhs, av),
            .pat_as => {
                try w.bindLocal(data.rhs, av);
                try w.bindPattern(@fromBackingInt(@intCast(data.lhs)), av);
            },
            .pat_tuple => for (b.extraSlice(Bir.inlineRange(data), Inst.Index), 0..) |el, i| {
                try w.bindPattern(el, try w.proj(av, .{ .kind = .tuple, .arg = @intCast(i) }, w.patternType(el)));
            },
            .pat_record => for (b.extraSlice(Bir.inlineRange(data), u32)) |l| {
                const name = b.locals[w.decl.locals_start + l].name;
                const sym = if (name.unwrap()) |s| @backingInt(b.symbols[s]) else 0;
                try w.bindLocal(l, try w.proj(av, .{ .kind = .field, .arg = sym }, w.localType(l)));
            },
            .pat_ctor => {
                const c = try w.ctorOf(@fromBackingInt(@intCast(data.lhs)));
                for (b.extraSlice(b.subRange(@fromBackingInt(@intCast(data.rhs))), Inst.Index), 0..) |arg, i| {
                    try w.bindPattern(arg, try w.proj(av, .{ .kind = .ctor, .arg = try w.o.ctorStep(c, @intCast(i)) }, w.patternType(arg)));
                }
            },
            .pat_list => {
                const items = b.extraSlice(Bir.inlineRange(data), Inst.Index);
                for (items, 0..) |item, i| {
                    if (b.instTag(item) == .pat_spread) {
                        // A spread binds a view of the scrutinee: the same cells.
                        const inner: Inst.Index = @fromBackingInt(@intCast(b.instData(item).lhs));
                        try w.bindPattern(inner, av);
                        if (b.instTag(inner) == .pat_var) w.notePat(b.instData(inner).lhs, pat, i, true, av);
                    } else {
                        // §18.4 item 4, the split: an element a list pattern
                        // binds is that position, taken — apart from the
                        // pattern's other bindings when the scrutinee is
                        // exclusive, and held by every other holder of it.
                        const el = try w.proj(av, .{ .kind = .elem, .arg = 0 }, w.patternType(item));
                        const out = try w.a.alloc(Entry, el.len);
                        for (el, out) |e, *x| {
                            x.* = e;
                            if (e.path != eps or w.cells.items[e.cell].condition_only) continue;
                            switch (w.cells.items[e.cell].kind) {
                                .param, .result, .env, .cbres => x.cell = try w.cell(.{ .kind = .taken, .a = e.cell, .b = item.int() }),
                                // An update's object with fields is taken as the record it
                                // was written over is (§31.2, as the whole base was).
                                .except => if (try w.takeable(e.cell)) |t| {
                                    x.cell = try w.cell(.{ .kind = .taken, .a = t, .b = item.int() });
                                },
                                .site, .shared, .top, .closure, .func, .taken, .payload => {},
                            }
                        }
                        w.split_list[item.int() - w.decl.inst_start.int()] = pat.int();
                        w.split_scrut[item.int() - w.decl.inst_start.int()] = av;
                        try w.bindPattern(item, try w.norm(out));
                        if (b.instTag(item) == .pat_var) w.notePat(b.instData(item).lhs, pat, i, false, av);
                    }
                }
            },
            .pat_spread => try w.bindPattern(@fromBackingInt(@intCast(data.lhs)), av),
            else => {},
        }
    }

    fn notePat(w: *Walker, l: u32, list: Inst.Index, index: usize, spread: bool, scrut: AV) void {
        if (l < w.pat_site.len) w.pat_site[l] = .{ .list = list, .index = @intCast(index), .spread = spread, .scrut = scrut };
    }

    /// A small id for a constructor reference, for its path step.
    fn ctorOf(w: *Walker, ref: Inst.Index) Allocator.Error!u32 {
        const data = w.bir.instData(ref);
        switch (w.bir.instTag(ref)) {
            .ctor => return w.o.ctorId(w.m, data.lhs),
            .ext_ctor => {
                if (data.lhs >= w.o.in.provenance.len) return w.o.ctorId(data.lhs, none);
                const i = w.o.in.provenance[data.lhs].ctorIndex(data.rhs) orelse none;
                return w.o.ctorId(data.lhs, i);
            },
            // A tagged schema's constructor, named as its declaring module
            // names it (`schemaCtorIndex`), so a block can carry its paths
            // and an imported use is the same constructor as a local one.
            .schema_ctor_top => {
                const r = Bir.SchemaCtorRef.unpack(data.rhs);
                const i = try w.o.schemaCtorIndex(w.m, data.lhs, r.encoded, r.variant) orelse none;
                return w.o.ctorId(w.m, i);
            },
            .ext_schema_ctor => {
                const m = data.lhs;
                return w.o.ctorId(m, try w.o.extSchemaCtorIndex(m, data.rhs) orelse none);
            },
            // Unreachable in a program the check accepted, which is the only
            // one the pass walks: a resolved constructor reference is one of
            // the four above. Its id has a module, so a block that meets it
            // stays well formed; the index names no constructor, so the
            // reader refuses that block (§28.4's last paragraph).
            else => return w.o.ctorId(w.m, none),
        }
    }

    // ---- callees ---------------------------------------------------------

    const Target = struct { m: u32, d: u32 };

    fn valueTarget(w: *const Walker, inst: Inst.Index) ?Target {
        const data = w.bir.instData(inst);
        switch (w.bir.instTag(inst)) {
            .top => return .{ .m = w.m, .d = data.lhs },
            .ext_value => {
                if (data.lhs >= w.o.in.provenance.len) return null;
                const d = w.o.in.provenance[data.lhs].valueDecl(data.rhs) orelse return null;
                return .{ .m = data.lhs, .d = d.int() };
            },
            else => return null,
        }
    }

    const SchemaMemberRef = struct { m: u32, decl: u32, kind: Interface.SchemaMember.Kind };

    /// The schema declaration and member a `schema_member_top` or
    /// `ext_schema_member` names.
    fn schemaMemberOf(w: *const Walker, inst: Inst.Index) ?SchemaMemberRef {
        const data = w.bir.instData(inst);
        switch (w.bir.instTag(inst)) {
            .schema_member_top => {
                if (data.lhs >= w.bir.decls.len or w.bir.decls[data.lhs].kind != .schema) return null;
                const kind = std.enums.fromInt(Interface.SchemaMember.Kind, data.rhs) orelse return null;
                return .{ .m = w.m, .decl = data.lhs, .kind = kind };
            },
            .ext_schema_member => {
                const m = data.lhs;
                if (m >= w.o.in.interfaces.len or m >= w.o.in.provenance.len) return null;
                const iface = &w.o.in.interfaces[m];
                if (data.rhs >= iface.schema_members.len) return null;
                const member = iface.schema_members[data.rhs];
                const decl = w.o.in.provenance[m].schemaDecl(@backingInt(member.schema)) orelse return null;
                return .{ .m = m, .decl = decl.int(), .kind = member.kind };
            },
            else => return null,
        }
    }

    /// §30.9: the function a top-level value with no parameters names, when
    /// its definition is nothing but a reference to another top-level value
    /// that takes parameters (`list = Pcg.list`), through such names.
    fn aliasTarget(w: *Walker, t: Target) Allocator.Error!?Target {
        const alias = (try w.o.resolveAlias(t.m, t.d)) orelse return null;
        return .{ .m = alias.module, .d = alias.decl };
    }

    fn termTarget(w: *const Walker, t: Dispatch.Term) ?Target {
        switch (t) {
            .top => |x| return .{ .m = w.m, .d = x.decl.int() },
            .ext => |x| {
                const m2 = x.module.int();
                if (m2 >= w.o.in.provenance.len) return null;
                const d = w.o.in.provenance[m2].valueDecl(@backingInt(x.value)) orelse return null;
                return .{ .m = m2, .d = d.int() };
            },
            else => return null,
        }
    }

    fn methodTarget(w: *const Walker, inst: Inst.Index) ?Target {
        if (w.m >= w.o.in.dispatch.len) return null;
        const dt = &w.o.in.dispatch[w.m];
        const site = dt.siteOf(inst) orelse return null;
        const ci = site.callee.unwrap() orelse return null;
        return w.termTarget(dt.term(ci));
    }

    fn targetName(w: *const Walker, t: Target) []const u8 {
        const b = w.o.in.birs[t.m];
        return w.o.in.interner.slice(b.symbol(b.decls[t.d].name));
    }

    // ---- polymorphic recursion (§16.7, F3 as amended) ---------------------

    /// A type at a place: the store's, or as a definition writes it, its
    /// parameters standing for `env`.
    const TyRef = union(enum) {
        cast: u32,
        store: Var,
        def: struct { m: u32, inst: Inst.Index, env: []const TyRef },
    };

    const TyShape = union(enum) {
        variable,
        other,
        app: struct { id: TypeId, args: []const TyRef },
        tuple: []const TyRef,
        record: struct { names: []const u32, types: []const TyRef, ext: ?TyRef },
        func: []const TyRef,
    };

    fn callArgRef(w: *Walker, ctx: InstCtx, i: u32) ?TyRef {
        if (i < ctx.arg_refs.len) return ctx.arg_refs[i];
        if (i < ctx.arg_types.len) if (ctx.arg_types[i]) |v| return .{ .store = v };
        if (w.call_poly) |cp| if (cp.inst == ctx.inst and cp.s == ctx.s and i < cp.arg_types.len) {
            if (cp.arg_types[i]) |v| return .{ .store = v };
        };
        return null;
    }

    /// Follow the checked callback type through the same function slot that
    /// supplies its value. Definition references retain their type arguments;
    /// they never allocate or unify a variable in the checker's store.
    fn callbackType(w: *Walker, j: u32, ctx: InstCtx) Allocator.Error!?TyRef {
        if (j < ctx.s.params) return w.callArgRef(ctx, j);
        const si = j - ctx.s.params;
        if (si >= ctx.s.slots.len) return null;
        const slot = ctx.s.slots[si];
        var ty = w.callArgRef(ctx, slot[0]) orelse return null;
        for (w.o.steps(slot[1])) |step| {
            if (step.kind == .cast or step.kind == .cast_level) {
                ty = .{ .cast = step.arg };
                continue;
            }
            const shape = try w.tyShape(ty);
            ty = switch (step.kind) {
                .elem => if (shape == .app and shape.app.id == w.o.in.types.well_known.list and shape.app.args.len == 1) shape.app.args[0] else return null,
                .tuple => if (shape == .tuple and step.arg < shape.tuple.len) shape.tuple[step.arg] else return null,
                .field => blk: {
                    var rec = shape;
                    while (rec == .record) {
                        for (rec.record.names, rec.record.types) |name, t| if (name == step.arg) break :blk t;
                        rec = if (rec.record.ext) |ext| try w.tyShape(ext) else return null;
                    }
                    return null;
                },
                .ctor => if (shape == .app) (try w.ctorFieldTy(shape.app.id, shape.app.args, w.o.stepCtor(step.arg), w.o.stepField(step.arg))) orelse return null else return null,
                else => return null,
            };
        }
        return ty;
    }

    fn castVariable(w: *Walker, id: u32) bool {
        const key = w.o.cast_types.items[id];
        return std.mem.startsWith(u8, key, "var(") or std.mem.eql(u8, key, "⋆");
    }

    fn castNominal(w: *Walker, id: u32) Allocator.Error!?TypeId {
        const key = w.o.cast_types.items[id];
        const end = std.mem.indexOfScalar(u8, key, '(') orelse return null;
        if (!w.o.cast_heads_ready) {
            for (w.o.in.types.entries, 0..) |entry, i| {
                var b: std.Io.Writer.Allocating = .init(w.a);
                b.writer.print("{d}:{s}::{s}", .{ @backingInt(entry.package), try w.castNamespace(entry.module.int(), w.o.in.interner.slice(entry.module_name)), w.o.in.interner.slice(entry.name) }) catch return error.OutOfMemory;
                const head = try w.o.keep.allocator().dupe(u8, b.written());
                try w.o.cast_heads.put(w.o.in.gpa, head, @fromBackingInt(@intCast(i)));
            }
            w.o.cast_heads_ready = true;
        }
        return w.o.cast_heads.get(key[0..end]);
    }

    fn opaqueCastKey(w: *Walker, id: u32) Allocator.Error!bool {
        const nominal = (try w.castNominal(id)) orelse return false;
        return nominal != w.o.in.types.well_known.list and nominal != w.o.builderId() and w.o.in.types.entries[nominal.int()].kind == .foreign;
    }

    /// Structural views of interned full types, shared across callback slots.
    fn castShape(w: *Walker, id: u32) Allocator.Error!TyShape {
        if (id < w.o.cast_shapes.items.len) if (w.o.cast_shapes.items[id]) |shape| return shape;
        const a = w.o.keep.allocator();

        const key = w.o.cast_types.items[id];
        const shape: TyShape = blk: {
            if (w.castVariable(id)) break :blk .variable;
            if (std.mem.startsWith(u8, key, "record(")) {
                const fields = try w.castFields(key);
                const names = try a.alloc(u32, fields.len);
                const types = try a.alloc(TyRef, fields.len);
                for (fields, names, types) |field, *name, *ty| {
                    name.* = if (w.o.in.interner.find(field.name)) |sym| @backingInt(sym) else none;
                    ty.* = .{ .cast = field.key };
                }
                const parts = try w.o.castParts(id);
                break :blk .{ .record = .{ .names = names, .types = types, .ext = .{ .cast = parts[parts.len - 1].key } } };
            }
            const parts = try w.o.castParts(id);
            const refs = try a.alloc(TyRef, parts.len);
            for (parts, refs) |part, *ref| ref.* = .{ .cast = part.key };
            if (std.mem.startsWith(u8, key, "fn(")) break :blk .{ .func = refs };
            if (std.mem.startsWith(u8, key, "tuple(")) break :blk .{ .tuple = refs };
            if (try w.castNominal(id)) |nominal| break :blk .{ .app = .{ .id = nominal, .args = refs } };
            break :blk .other;
        };
        const old_len = w.o.cast_shapes.items.len;
        if (id >= old_len) {
            try w.o.cast_shapes.resize(a, @as(usize, id) + 1);
            @memset(w.o.cast_shapes.items[old_len..], null);
        }
        w.o.cast_shapes.items[id] = shape;
        return shape;
    }

    fn castEnv(w: *Walker, args: []const TyRef) Allocator.Error![]const TyRef {
        const keys = try w.a.alloc(u32, args.len);
        for (args, keys) |arg, *key| key.* = try w.castTypeRef(arg);
        if (w.cast_envs.get(keys)) |env| return env;
        const env = try w.a.alloc(TyRef, keys.len);
        for (keys, env) |key, *ref| ref.* = .{ .cast = key };
        try w.cast_envs.put(w.a, keys, env);
        return env;
    }

    /// The same immutable endpoint term the checker uses when expanding a
    /// native record schema. Tagged endpoints retain their nominal key.
    fn castSchemaEndpoint(w: *Walker, id: TypeId, args: []const TyRef) Allocator.Error!u32 {
        const e = w.o.in.types.entries[id.int()];
        if (e.module.int() >= w.o.in.types.plans.len) return w.o.castId("⋆");
        const plan = &w.o.in.types.plans[e.module.int()];
        const Ctx = struct {
            fn order(want: Bir.DeclIndex, def: SchemaPlan.Definition) std.math.Order {
                return std.math.order(want.int(), def.decl.int());
            }
        };
        const at = std.sort.lowerBound(SchemaPlan.Definition, plan.definitions, e.decl, Ctx.order);
        if (at >= plan.definitions.len or plan.definitions[at].decl != e.decl) return w.o.castId("⋆");
        const def = plan.definitions[at];
        const root = if (w.o.in.types.ofSchemaDecl(e.module, e.decl, .type) == id) def.program_term else def.encoded_term;
        return w.castPlanType(e.module.int(), root, try w.castEnv(args));
    }

    fn castPlanType(w: *Walker, m: u32, ti: Interface.TermIndex, env: []const TyRef) Allocator.Error!u32 {
        const plan = &w.o.in.types.plans[m];
        if (ti == .none or ti.int() >= plan.terms.len) return w.o.castId("⋆");
        const memo: [4]usize = .{ m, ti.int(), @intFromPtr(env.ptr), env.len };
        if (w.cast_plan_types.get(memo)) |id| return id;
        var view = Interface.empty;
        view.terms = plan.terms;
        view.extra = plan.type_extra;
        view.type_refs = plan.type_refs;
        view.symbols = plan.symbols;
        const t = view.term(ti);
        var b: std.Io.Writer.Allocating = .init(w.a);
        const writer = &b.writer;
        const id = switch (t.tag) {
            .err => try w.o.castId("⋆"),
            .@"var" => if (t.lhs < env.len) try w.castTypeRef(env[t.lhs]) else try w.o.castId("⋆"),
            .unit => try w.o.castId("unit"),
            .empty_record => try w.o.castId("{}"),
            .app, .alias => blk: {
                if (t.lhs >= view.type_refs.len) break :blk try w.o.castId("⋆");
                const ref = view.type_refs[t.lhs];
                const words = view.range(t.rhs);
                const args = try w.a.alloc(TyRef, words.len);
                for (words, args) |word, *arg| arg.* = .{ .cast = try w.castPlanType(m, @fromBackingInt(word), env) };
                if (t.tag == .alias) break :blk try w.castPlanType(m, ref.body, try w.castEnv(args));
                const nominal = w.o.in.types.find(w.o.in.graph, ref.package, view.symbol(ref.module), view.symbol(ref.name));
                if (nominal == .none) break :blk try w.o.castId("⋆");
                const e = w.o.in.types.entries[nominal.int()];
                writer.print("{d}:{s}::{s}(", .{ @backingInt(e.package), try w.castNamespace(e.module.int(), w.o.in.interner.slice(e.module_name)), w.o.in.interner.slice(e.name) }) catch return error.OutOfMemory;
                for (args) |arg| writeCastRef(writer, arg.cast) catch return error.OutOfMemory;
                writer.writeByte(')') catch return error.OutOfMemory;
                break :blk try w.o.castId(b.written());
            },
            .tuple, .func => blk: {
                writer.writeAll(if (t.tag == .func) "fn(" else "tuple(") catch return error.OutOfMemory;
                for (view.range(t.lhs)) |word| writeCastRef(writer, try w.castPlanType(m, @fromBackingInt(word), env)) catch return error.OutOfMemory;
                if (t.tag == .func) {
                    writer.writeAll("→") catch return error.OutOfMemory;
                    writeCastRef(writer, try w.castPlanType(m, @fromBackingInt(t.rhs), env)) catch return error.OutOfMemory;
                }
                writer.writeByte(')') catch return error.OutOfMemory;
                break :blk try w.o.castId(b.written());
            },
            .record => blk: {
                const words = view.range(t.lhs);
                const fields = try w.a.alloc(CastField, words.len / 2);
                for (fields, 0..) |*field, i| field.* = .{
                    .name = w.o.in.interner.slice(view.symbol(@fromBackingInt(words[i * 2]))),
                    .key = try w.castPlanType(m, @fromBackingInt(words[i * 2 + 1]), env),
                };
                break :blk try w.castRecord(fields, try w.castPlanType(m, @fromBackingInt(t.rhs), env));
            },
        };
        try w.cast_plan_types.put(w.a, memo, id);
        return id;
    }

    fn castTypeRef(w: *Walker, ref: TyRef) Allocator.Error!u32 {
        if (ref == .store) return w.castType(ref.store);
        if (ref == .cast) return ref.cast;
        const d = ref.def;
        const bir = w.o.in.birs[d.m];
        const tag = bir.instTag(d.inst);
        if (tag == .type_var) {
            const info: Bir.TypeVarInfo = @bitCast(bir.instData(d.inst).rhs);
            if (info.param != Bir.TypeVarInfo.param_none and info.param < d.env.len) return w.castTypeRef(d.env[info.param]);
            return w.o.castId("⋆");
        }
        const memo: [4]usize = .{ d.m, d.inst.int(), @intFromPtr(d.env.ptr), d.env.len };
        if (w.cast_defs.get(memo)) |id| return id;
        const shape = try w.tyShape(ref);
        var b: std.Io.Writer.Allocating = .init(w.a);
        const writer = &b.writer;
        const id = switch (shape) {
            .app => |ap| blk: {
                const entry = w.o.in.types.entries[ap.id.int()];
                if (entry.kind == .alias) {
                    const body = w.o.in.birs[entry.module.int()].decl(entry.decl).annotation.unwrap() orelse break :blk try w.o.castId("⋆");
                    break :blk try w.castTypeRef(.{ .def = .{ .m = entry.module.int(), .inst = body, .env = try w.castEnv(ap.args) } });
                }
                writer.print("{d}:{s}::{s}(", .{ @backingInt(entry.package), try w.castNamespace(entry.module.int(), w.o.in.interner.slice(entry.module_name)), w.o.in.interner.slice(entry.name) }) catch return error.OutOfMemory;
                for (ap.args) |arg| writeCastRef(writer, try w.castTypeRef(arg)) catch return error.OutOfMemory;
                writer.writeByte(')') catch return error.OutOfMemory;
                break :blk try w.o.castId(b.written());
            },
            .func, .tuple => blk: {
                const refs = if (shape == .func) shape.func else shape.tuple;
                writer.writeAll(if (shape == .func) "fn(" else "tuple(") catch return error.OutOfMemory;
                for (refs, 0..) |arg, i| {
                    if (shape == .func and i + 1 == refs.len) writer.writeAll("→") catch return error.OutOfMemory;
                    writeCastRef(writer, try w.castTypeRef(arg)) catch return error.OutOfMemory;
                }
                writer.writeByte(')') catch return error.OutOfMemory;
                break :blk try w.o.castId(b.written());
            },
            .record => |rec| blk: {
                const fields = try w.a.alloc(CastField, rec.names.len);
                for (rec.names, rec.types, fields) |name, ty, *field| field.* = .{ .name = w.o.in.interner.slice(@fromBackingInt(name)), .key = try w.castTypeRef(ty) };
                break :blk try w.castRecord(fields, if (rec.ext) |ext| try w.castTypeRef(ext) else try w.o.castId("{}"));
            },
            .other, .variable => try w.o.castId(if (tag == .type_unit) "unit" else "⋆"),
        };
        try w.cast_defs.put(w.a, memo, id);
        return id;
    }

    fn tyShape(w: *Walker, r: TyRef) Allocator.Error!TyShape {
        switch (r) {
            .cast => |id| return w.castShape(id),

            .store => |v| return switch (w.store.resolvedContent(v)) {
                .flex, .rigid => .variable,
                .err => .other,
                .alias => |al| w.tyShape(.{ .store = al.actual }),
                .structure => |sc| switch (sc) {
                    .unit, .empty_record => .other,
                    .func => |f| blk: {
                        const ps = w.store.vars(f.params);
                        const all = try w.a.alloc(TyRef, ps.len + 1);
                        for (ps, all[0..ps.len]) |p, *x| x.* = .{ .store = p };
                        all[ps.len] = .{ .store = f.result };
                        break :blk .{ .func = all };
                    },
                    .app => |ap| blk: {
                        const vs = w.store.vars(ap.args);
                        const args = try w.a.alloc(TyRef, vs.len);
                        for (vs, args) |x, *y| y.* = .{ .store = x };
                        break :blk .{ .app = .{ .id = ap.type, .args = args } };
                    },
                    .tuple => |t| blk: {
                        const vs = w.store.vars(t);
                        const els = try w.a.alloc(TyRef, vs.len);
                        for (vs, els) |x, *y| y.* = .{ .store = x };
                        break :blk .{ .tuple = els };
                    },
                    .record => |rec| blk: {
                        const fs = w.store.fields(rec.fields);
                        const names = try w.a.alloc(u32, fs.len);
                        const types = try w.a.alloc(TyRef, fs.len);
                        for (fs, names, types) |f, *n, *t| {
                            n.* = @backingInt(f.name);
                            t.* = .{ .store = f.value };
                        }
                        break :blk .{ .record = .{ .names = names, .types = types, .ext = .{ .store = rec.ext } } };
                    },
                },
            },
            .def => |d| {
                const bir = w.o.in.birs[d.m];
                const tag = bir.instTag(d.inst);
                const data = bir.instData(d.inst);
                const graph_m: Graph.Index = @fromBackingInt(@intCast(d.m));
                switch (tag) {
                    .type_var => {
                        const info: Bir.TypeVarInfo = @bitCast(data.rhs);
                        if (info.param == Bir.TypeVarInfo.param_none or info.param >= d.env.len) return .variable;
                        return w.tyShape(d.env[info.param]);
                    },
                    .type_tuple => {
                        const xs = bir.extraSlice(Bir.inlineRange(data), Inst.Index);
                        const els = try w.a.alloc(TyRef, xs.len);
                        for (xs, els) |x, *y| y.* = .{ .def = .{ .m = d.m, .inst = x, .env = d.env } };
                        return .{ .tuple = els };
                    },
                    .type_record, .type_record_ext => {
                        const fs = if (tag == .type_record) bir.extraSlice(Bir.inlineRange(data), Bir.Field) else bir.extraSlice(bir.subRange(@fromBackingInt(@intCast(data.rhs))), Bir.Field);
                        const names = try w.a.alloc(u32, fs.len);
                        const types = try w.a.alloc(TyRef, fs.len);
                        for (fs, names, types) |f, *n, *t| {
                            n.* = @backingInt(bir.symbol(f.name));
                            t.* = .{ .def = .{ .m = d.m, .inst = f.value, .env = d.env } };
                        }
                        const ext: ?TyRef = if (tag == .type_record_ext) .{ .def = .{ .m = d.m, .inst = @fromBackingInt(@intCast(data.lhs)), .env = d.env } } else null;
                        return .{ .record = .{ .names = names, .types = types, .ext = ext } };
                    },
                    .type_fn => {
                        const ps = bir.extraSlice(bir.subRange(@fromBackingInt(@intCast(data.lhs))), Inst.Index);
                        const all = try w.a.alloc(TyRef, ps.len + 1);
                        for (ps, all[0..ps.len]) |p, *x| x.* = .{ .def = .{ .m = d.m, .inst = p, .env = d.env } };
                        all[ps.len] = .{ .def = .{ .m = d.m, .inst = @fromBackingInt(@intCast(data.rhs)), .env = d.env } };
                        return .{ .func = all };
                    },
                    .type_top, .ext_type, .schema_type_top, .ext_schema_type, .type_app => {
                        const id = if (tag == .type_app) blk: {
                            const head: Inst.Index = @fromBackingInt(@intCast(data.lhs));
                            break :blk w.o.in.types.headId(graph_m, bir.instTag(head), bir.instData(head));
                        } else w.o.in.types.headId(graph_m, tag, data);
                        if (id == .none or id.int() >= w.o.in.types.entries.len) return .other;
                        const xs: []const Inst.Index = if (tag == .type_app) bir.extraSlice(bir.subRange(@fromBackingInt(@intCast(data.rhs))), Inst.Index) else &.{};
                        const args = try w.a.alloc(TyRef, xs.len);
                        for (xs, args) |x, *y| y.* = .{ .def = .{ .m = d.m, .inst = x, .env = d.env } };
                        const e = w.o.in.types.entries[id.int()];
                        if (e.kind == .alias) {
                            if (e.schema_endpoint) return w.castShape(try w.castSchemaEndpoint(id, args));
                            const body = w.o.in.birs[e.module.int()].decl(e.decl).annotation.unwrap() orelse return .variable;
                            return w.tyShape(.{ .def = .{ .m = e.module.int(), .inst = body, .env = try w.castEnv(args) } });
                        }
                        return .{ .app = .{ .id = id, .args = args } };
                    },
                    else => return .other,
                }
            },
        }
    }

    /// The type of field `field` of constructor `c` of the applied type `app`,
    /// an alias expanded; null when `c` is not one of its constructors.
    fn ctorFieldTy(w: *Walker, id: TypeId, args: []const TyRef, c: u32, field: u32) Allocator.Error!?TyRef {
        const e = w.o.in.types.entries[id.int()];
        const dm = e.module.int();
        const dbir = w.o.in.birs[dm];
        const d = dbir.decl(e.decl);
        if (e.kind == .alias) {
            const body = d.annotation.unwrap() orelse return null;
            return switch (try w.tyShape(.{ .def = .{ .m = dm, .inst = body, .env = args } })) {
                .app => |ap| w.ctorFieldTy(ap.id, ap.args, c, field),
                else => null,
            };
        }
        if (e.kind != .adt) return null;
        const key = w.o.ctorKey(c);
        if (key.module != dm) return null;
        const start = d.ctors_start;
        if (key.index < start or key.index >= d.ctors_end) return null;
        const ct = dbir.ctors[key.index];
        const fs = dbir.extraSlice(.{ .start = ct.args_start, .end = ct.args_end }, Inst.Index);
        if (field >= fs.len) return null;
        return .{ .def = .{ .m = dm, .inst = fs[field], .env = args } };
    }

    /// Whether `a` instantiates a variable of `g` at a structure anywhere in
    /// the type: the argument's type is the declared one's, grown.
    fn grownIn(w: *Walker, g: TyRef, a: TyRef, depth: u32) Allocator.Error!bool {
        if (depth > 64) return true;
        const sg = try w.tyShape(g);
        const sa = try w.tyShape(a);
        switch (sg) {
            .variable => return switch (sa) {
                .variable, .other => false,
                else => true,
            },
            .other => return false,
            .app => |x| {
                const y = switch (sa) {
                    .app => |y| y,
                    else => return false,
                };
                if (x.args.len != y.args.len) return false;
                for (x.args, y.args) |p, q| if (try w.grownIn(p, q, depth + 1)) return true;
                return false;
            },
            .tuple => |x| {
                const y = switch (sa) {
                    .tuple => |y| y,
                    else => return false,
                };
                if (x.len != y.len) return false;
                for (x, y) |p, q| if (try w.grownIn(p, q, depth + 1)) return true;
                return false;
            },
            .func => |x| {
                const y = switch (sa) {
                    .func => |y| y,
                    else => return false,
                };
                if (x.len != y.len) return false;
                for (x, y) |p, q| if (try w.grownIn(p, q, depth + 1)) return true;
                return false;
            },
            .record => |x| {
                const y = switch (sa) {
                    .record => |y| y,
                    else => return false,
                };
                for (x.names, x.types) |n, t| for (y.names, y.types) |m, u| if (n == m and try w.grownIn(t, u, depth + 1)) return true;
                if (x.ext) |xe| if (y.ext) |ye| return w.grownIn(xe, ye, depth + 1);
                return false;
            },
        }
    }

    /// §16.7 (F3, the owner's choice (a)): the boundary of `p`, an entry's
    /// path in an argument of declared type `g` and type `a` at a call inside
    /// the group being solved: how many of its steps are above the first
    /// variable `a` instantiates at a structure, or null when none is.
    fn polyBound(w: *Walker, p: u32, g0: TyRef, a0: TyRef) Allocator.Error!?usize {
        const st = w.o.steps(p);
        var g = g0;
        var a = a0;
        for (st, 0..) |s, k| {
            const sg = try w.tyShape(g);
            const sa = try w.tyShape(a);
            switch (sg) {
                .variable => switch (sa) {
                    .variable, .other => return null,
                    else => return k,
                },
                .app => |x| if (x.id != w.o.in.types.well_known.list and w.o.in.types.entries[x.id.int()].kind == .foreign and try w.grownIn(g, a, 0)) return k,
                else => {},
            }
            const next: ?[2]TyRef = switch (s.kind) {
                .ctor => blk: {
                    const x = switch (sg) {
                        .app => |x| x,
                        else => break :blk null,
                    };
                    const y = switch (sa) {
                        .app => |y| y,
                        else => break :blk null,
                    };
                    const c = w.o.stepCtor(s.arg);
                    const f = w.o.stepField(s.arg);
                    const gn = (try w.ctorFieldTy(x.id, x.args, c, f)) orelse break :blk null;
                    const an = (try w.ctorFieldTy(y.id, y.args, c, f)) orelse break :blk null;
                    break :blk .{ gn, an };
                },
                .field => blk: {
                    const x = switch (sg) {
                        .record => |x| x,
                        else => break :blk null,
                    };
                    const y = switch (sa) {
                        .record => |y| y,
                        else => break :blk null,
                    };
                    const gi = std.mem.indexOfScalar(u32, x.names, s.arg) orelse break :blk null;
                    const ai = std.mem.indexOfScalar(u32, y.names, s.arg) orelse break :blk null;
                    break :blk .{ x.types[gi], y.types[ai] };
                },
                .tuple => blk: {
                    const x = switch (sg) {
                        .tuple => |x| x,
                        else => break :blk null,
                    };
                    const y = switch (sa) {
                        .tuple => |y| y,
                        else => break :blk null,
                    };
                    if (s.arg >= x.len or s.arg >= y.len) break :blk null;
                    break :blk .{ x[s.arg], y[s.arg] };
                },
                .elem => blk: {
                    const x = switch (sg) {
                        .app => |x| x,
                        else => break :blk null,
                    };
                    const y = switch (sa) {
                        .app => |y| y,
                        else => break :blk null,
                    };
                    if (x.args.len != 1 or y.args.len != 1) break :blk null;
                    break :blk .{ x.args[0], y.args[0] };
                },
                // What a closure captured is not written in its type: below
                // its `◇`, a grown type is a grown place.
                .env => {
                    if (sg == .func and try w.grownIn(g, a, 0)) return k + 1;
                    return null;
                },
                // A step that stands for places it does not name: where the
                // types differ, what is below may be below the variable.
                .any, .level, .cast, .cast_level => return if (try w.grownIn(g, a, 0)) k else null,
                else => null,
            };
            const n = next orelse return null;
            g = n[0];
            a = n[1];
        }
        // The path ends at the variable: what is below it is below.
        const sg = try w.tyShape(g);
        const sa = try w.tyShape(a);
        if (sg == .variable and sa != .variable and sa != .other) return st.len;
        return null;
    }

    /// `p`'s first `k` steps followed by `⋆`.
    fn cutAt(w: *Walker, p: u32, k: usize) Allocator.Error!u32 {
        const st = w.o.steps(p);
        var at: u32 = eps;
        for (st[0..@min(k, st.len)]) |x| at = try w.o.child(at, x.kind, x.arg);
        return w.o.child(at, .any, 0);
    }

    /// The declared types of a callee's parameters, for the fold: a top-level
    /// member of the group being solved, in this module.
    fn memberParamTypes(w: *Walker, t: Target) Allocator.Error![]const ?Var {
        if (t.m != w.m or !w.o.isComputing(t.m, t.d)) return &.{};
        const d = w.bir.decls[t.d];
        const km = &w.o.in.modules[t.m];
        const lt = km.local_type[d.locals_start..d.locals_end];
        const ps = w.bir.extraSlice(.{ .start = d.params_start, .end = d.params_end }, Inst.Index);
        const out = try w.a.alloc(?Var, ps.len);
        for (ps, out) |p, *x| x.* = switch (w.bir.instTag(p)) {
            .pat_var => if (w.bir.instData(p).lhs < lt.len) lt[w.bir.instData(p).lhs].unwrap() else null,
            .pat_as => if (w.bir.instData(p).rhs < lt.len) lt[w.bir.instData(p).rhs].unwrap() else null,
            else => null,
        };
        // A destructured parameter: the declaration's own type's, the rigid
        // reading its body was checked against. Groups never span modules
        // (the module graph is acyclic), so `t.m` is this walker's module and
        // its store is `w.store`.
        for (out, 0..) |*x, i| if (x.* == null) {
            x.* = if (t.d < km.decl_display.len) (if (km.decl_display[t.d].unwrap()) |ft| funcParam(w.store, ft, @intCast(i)) else null) else null;
        };
        return out;
    }

    /// The declared types of a local function's parameters, for the fold,
    /// when its group is being solved (§18.7).
    fn localParamTypes(w: *Walker, ci: u32) Allocator.Error![]const ?Var {
        // A member of a local group being solved; or, while any recursive
        // group is, a closure a body calls: a let-bound lambda is
        // generalised, so a call of it may grow its own variable
        // (`k = λy → g (n - 1) y`, then `k [ x ]`) where the call inside it
        // grows nothing.
        const local = for (w.solving_locals.items) |g| {
            if (g[1] == ci) break g[0];
        } else if (w.recursive or w.solving_locals.items.len != 0) none else return &.{};
        const ps = w.closures.items[ci].params;
        const out = try w.a.alloc(?Var, ps.len);
        // A destructured parameter: the function's own type's.
        for (ps, out, 0..) |p, *x, i| x.* = w.patternType(p) orelse if (local == none) null else if (w.localType(local)) |ft| funcParam(w.store, ft, @intCast(i)) else null;
        return out;
    }

    fn qualified(w: *Walker, t: Target) Allocator.Error![]const u8 {
        const key = (@as(u64, t.m) << 32) | t.d;
        if (w.o.names_memo.get(key)) |n| return n;
        const n = try w.qualifiedRaw(t);
        try w.o.names_memo.put(w.o.in.gpa, key, n);
        return n;
    }

    fn qualifiedRaw(w: *Walker, t: Target) Allocator.Error![]const u8 {
        return std.fmt.allocPrint(w.o.out.allocator(), "{s}.{s}", .{ w.o.in.module_names[t.m], w.targetName(t) });
    }

    fn isCore(w: *const Walker, t: Target, module: []const u8) bool {
        return w.o.in.packages[t.m] == .core and std.mem.eql(u8, w.o.in.module_names[t.m], module);
    }

    /// The named writers of §3.1, whose call-site demands keep their
    /// slice-1 operation, `List.<name>`.
    fn writerName(w: *const Walker, t: Target) ?[]const u8 {
        if (!w.isCore(t, "List")) return null;
        const name = w.targetName(t);
        // Not `cons`: a prepend copies its base and writes nothing (§3.1,
        // amended for slice 3f).
        const writers = [_][]const u8{ "set", "update", "push", "pop", "swap", "insertAt", "removeAt", "append" };
        for (writers) |x| if (std.mem.eql(u8, x, name)) return x;
        return null;
    }

    /// A `foreign` whose rung is `impure` or `suspends` (§6.1 item 2). A
    /// `foreign pure` promises it changes and keeps nothing, so it is a
    /// conservative call: it can only return what it was given.
    fn escapes(w: *const Walker, t: Target) bool {
        const d = w.o.in.birs[t.m].decls[t.d];
        return d.kind == .foreign_value and d.rung != .pure;
    }

    fn isSpreadCall(w: *const Walker, inst: Inst.Index) bool {
        if (w.bir.instTag(inst) != .call) return false;
        const tags = w.o.in.spans[w.m].tags;
        const tok = w.token(inst);
        if (tok >= tags.len or tags[tok] != .ellipsis) return false;
        const t = w.valueTarget(@fromBackingInt(@intCast(w.bir.instData(inst).lhs))) orelse return false;
        if (!w.isCore(t, "List")) return false;
        const name = w.targetName(t);
        return std.mem.eql(u8, name, "cons") or std.mem.eql(u8, name, "append");
    }

    fn isSpreadAppend(w: *const Walker, inst: Inst.Index) bool {
        const t = w.valueTarget(@fromBackingInt(@intCast(w.bir.instData(inst).lhs))) orelse return false;
        return std.mem.eql(u8, w.targetName(t), "append");
    }

    fn isListAppend(w: *const Walker, inst: Inst.Index) bool {
        if (w.bir.instTag(inst) != .call) return false;
        if (w.m >= w.o.in.dispatch.len) return false;
        const dt = &w.o.in.dispatch[w.m];
        if (dt.isListAppend(inst) or dt.isListAppend(@fromBackingInt(@intCast(w.bir.instData(inst).lhs)))) {
            return w.callArgs(inst).len == 2;
        }
        return false;
    }

    fn callArgs(w: *const Walker, inst: Inst.Index) []const Inst.Index {
        return w.bir.extraSlice(w.bir.subRange(@fromBackingInt(@intCast(w.bir.instData(inst).rhs))), Inst.Index);
    }

    /// Whether the tokens strictly between `a` and `b` are balanced brackets.
    fn balanced(w: *const Walker, a: u32, b: u32) bool {
        const tags = w.o.in.spans[w.m].tags;
        var depth: i32 = 0;
        var i = a + 1;
        while (i < b and i < tags.len) : (i += 1) {
            switch (tags[i]) {
                .l_bracket, .l_paren, .l_brace => depth += 1,
                .r_bracket, .r_paren, .r_brace => {
                    depth -= 1;
                    if (depth < 0) return false;
                },
                else => {},
            }
        }
        return depth == 0;
    }

    // ---- evaluation (§5) -------------------------------------------------

    fn eval(w: *Walker, inst: Inst.Index) Allocator.Error!AV {
        if (w.mode != .report) return w.evalRaw(inst);
        const parent = w.current_inst;
        w.inst_parent[inst.int() - w.decl.inst_start.int()] = parent;
        w.current_inst = inst.int();
        defer w.current_inst = parent;
        // §28.6: the tokens each instruction spans, for the messages.
        const tok = w.token(inst);
        const outer = w.span;
        w.span = .{ tok, tok };
        const out = try w.evalRaw(inst);
        // A variable path is read without its root being evaluated.
        switch (w.bir.instTag(inst)) {
            .field_access, .tuple_index => w.span[0] = @min(w.span[0], w.rootToken(inst)),
            else => {},
        }
        const mine = w.span;
        w.setSpan(inst, mine);
        w.span = .{ @min(outer[0], mine[0]), if (outer[0] == none) mine[1] else @max(outer[1], mine[1]) };
        return out;
    }

    fn setSpan(w: *Walker, inst: Inst.Index, s: [2]u32) void {
        const i = inst.int() -% w.decl.inst_start.int();
        if (i < w.inst_span.len) w.inst_span[i] = s;
    }

    /// The tokens instruction `inst` spans, once a report walk evaluated it.
    fn spanOf(w: *const Walker, inst: Inst.Index) ?[2]u32 {
        const i = inst.int() -% w.decl.inst_start.int();
        if (i >= w.inst_span.len or w.inst_span[i][0] == none) return null;
        return w.inst_span[i];
    }

    // Keep the common recursive paths out of the larger dispatch frame.
    fn evalRaw(w: *Walker, inst: Inst.Index) Allocator.Error!AV {
        return switch (w.bir.instTag(inst)) {
            .call => blk: {
                const av = try w.evalCall(inst);
                break :blk if (w.isRecordCopyCall(inst)) w.copiedRecord(av, inst) else av;
            },
            .method_call => w.evalMethod(inst),
            .record => w.evalRecord(inst),
            else => w.evalOther(inst),
        };
    }

    fn evalOther(w: *Walker, inst: Inst.Index) Allocator.Error!AV {
        const b = w.bir;
        const data = b.instData(inst);
        switch (b.instTag(inst)) {
            .local => return w.evalLocal(data.lhs, eps, inst),
            .field_access, .tuple_index => {
                if (try w.refPath(inst)) |r| {
                    if (w.mode == .report) try w.recordRead(r, w.token(inst), inst.int(), none, none);
                    return w.evalLocal(r.local, r.path, inst);
                }
                const target = try w.eval(@fromBackingInt(@intCast(data.lhs)));
                const s: Step = if (b.instTag(inst) == .field_access)
                    .{ .kind = .field, .arg = @backingInt(b.symbol(@fromBackingInt(@intCast(data.rhs)))) }
                else
                    .{ .kind = .tuple, .arg = data.rhs };
                return w.proj(target, s, w.instType(inst));
            },
            .top, .ext_value => {
                // A reference the provenance does not resolve: unknown, not
                // empty, so that what it holds is never taken for nothing.
                const t = w.valueTarget(inst) orelse return if (try w.isTracked(inst)) w.single(.{ .kind = .top, .a = 0 }) else &.{};
                const decl = w.o.in.birs[t.m].decls[t.d];
                // A function: a value with no cell of its own, which carries
                // its summary to where it is called (§16.5).
                if (decl.params > 0) return w.single(.{ .kind = .func, .a = t.m, .b = t.d });
                if (!try w.isTracked(inst)) return &.{};
                if (decl.kind == .foreign_value) return w.single(.{ .kind = .top, .a = 0 });
                // What is shared is the cells the definition makes, and
                // nothing else (thesis §3.10): `Dict.empty` makes none (T51).
                if (try w.o.ensureSummary(t.m, t.d)) |s| {
                    if (try w.initializationTransfer(t, s)) return w.instRes(s, .{ .inst = inst, .s = s, .avs = &.{}, .depth = 0 });
                    return w.sharedOf(s, t, inst);
                }
                return w.single(.{ .kind = .shared, .a = t.m, .b = t.d, .ty = w.instTypeOpt(inst) });
            },
            .ctor, .ext_ctor, .schema_ctor_top, .ext_schema_ctor => return (try w.constructorValue(inst)) orelse &.{},
            .schema_member_top, .ext_schema_member => return (try w.memberValue(inst)) orelse &.{},
            .int, .float, .char, .string, .chunk, .unit, .@"error" => return &.{},
            .interp => {
                const parts = b.extraSlice(Bir.inlineRange(data), Inst.Index);
                const avs = try w.evalOperands(parts, false);
                w.popPending(avs.len);
                try w.consume(parts, w.token(inst));
                return &.{};
            },
            .tuple => {
                const items = b.extraSlice(Bir.inlineRange(data), Inst.Index);
                const avs = try w.evalOperands(items, false);
                w.popPending(avs.len);
                try w.consume(items, w.token(inst));
                var parts = try w.a.alloc(AV, avs.len + 1);
                parts[avs.len] = try w.containingCondition(inst, avs);
                for (avs, 0..) |av, i| parts[i] = try w.shift(av, .{ .kind = .tuple, .arg = @intCast(i) });
                const out = try w.spineValue(inst, parts);
                try w.sight(out, .{ .pending = "it is stored in a tuple" }, w.token(inst));
                return out;
            },
            .list => {
                const items = b.extraSlice(Bir.inlineRange(data), Inst.Index);
                const avs = try w.evalOperands(items, false);
                w.popPending(avs.len);
                try w.consume(items, w.token(inst));
                var parts = try w.a.alloc(AV, avs.len + 1);
                parts[0] = try w.single(.{ .kind = .site, .a = inst.int(), .ty = w.instTypeOpt(inst) });
                // §18.2: a literal's items, each exclusive and pairwise apart.
                try w.initCond(parts[0][0].cell, try w.storedCond(avs, &.{}));
                // §31.4 item 6: and no record object at two of its positions.
                try w.rinitCond(parts[0][0].cell, try w.rstoredCond(avs, &.{}));
                for (avs, 0..) |av, i| parts[i + 1] = try w.shift(av, .{ .kind = .elem, .arg = 0 });
                const out = try w.spineValue(inst, parts);
                try w.sight(out, .{ .pending = "it is stored in a list" }, w.token(inst));
                return out;
            },
            .record_update => return w.evalRecordUpdate(inst),
            .type_dispatch => {
                const md = b.extraData(@fromBackingInt(@intCast(data.rhs)), Bir.TypeDispatch);
                const args = b.extraSlice(.{ .start = md.args_start, .end = md.args_end }, Inst.Index);
                return w.conservative(inst, args, &.{}, null, "", false, .unknown);
            },
            .lambda => {
                const params = b.extraSlice(b.subRange(@fromBackingInt(@intCast(data.lhs))), Inst.Index);
                return w.closure(params, @fromBackingInt(@intCast(data.rhs)), null, w.token(inst), w.instType(inst));
            },
            .let => return w.evalLet(inst),
            .case => return w.evalCase(inst),
            .@"try" => {
                const s = try w.eval(@fromBackingInt(@intCast(data.lhs)));
                try w.consume(&.{@fromBackingInt(@intCast(data.lhs))}, w.token(inst));
                try w.earlyReturn(@fromBackingInt(@intCast(data.lhs)), s);
                if (!try w.isTracked(inst)) return &.{};
                const any = try w.o.child(eps, .any, 0);
                const out = try w.a.alloc(Entry, s.len);
                for (s, out) |e, *x| x.* = .{ .path = any, .cell = e.cell, .approx = e.approx, .grown = e.grown };
                return w.norm(out);
            },
            .markup => {
                var values: std.ArrayList(Inst.Index) = .empty;
                try b.markupValues(w.a, @fromBackingInt(@intCast(data.lhs)), &values);
                const avs = try w.evalOperands(values.items, true);
                w.popPending(avs.len);
                const retained = try w.conservativeAV(inst, values.items, avs, &.{}, null, "", false, .made);
                const events = try w.markupTreeEvents(inst, @fromBackingInt(@intCast(data.lhs)), try MarkupValues.init(w.a, values.items, avs));
                return w.unionOf(&.{ try w.shift(retained, .{ .kind = .markup_render, .arg = 0 }), try w.shift(events, .{ .kind = .markup_event, .arg = 0 }) });
            },
            else => return &.{},
        }
    }

    fn evalRecord(w: *Walker, inst: Inst.Index) Allocator.Error!AV {
        const b = w.bir;
        const data = b.instData(inst);
        const fields = b.extraSlice(Bir.inlineRange(data), Bir.Field);
        const insts = try w.a.alloc(Inst.Index, fields.len);
        for (fields, insts) |f, *x| x.* = f.value;
        const avs = try w.evalOperands(insts, false);
        w.popPending(avs.len);
        try w.consume(insts, w.token(inst));
        // §31.2: the literal's object is a cell of its own, `site(ι)`.
        // Its fields being a stored construction's (§18.2), each
        // exclusive and pairwise apart, is the record demand's condition
        // (§31.4 item 6); a list's reads the fields themselves.
        var parts = try w.a.alloc(AV, avs.len + 2);
        parts[0] = try w.single(.{ .kind = .site, .a = inst.int(), .ty = w.instTypeOpt(inst) });
        // A field of a crossing type holds no cell (§4.4), whatever
        // its value's abstract value says — a `Js.to` answers `⊤` at
        // any type — now that the record around it is tracked.
        for (fields, avs, 0..) |f, av, i| {
            const crossing = if (w.instType(f.value)) |v| !try w.trackedVar(v) else false;
            parts[i + 1] = if (crossing) &.{} else try w.shift(av, .{ .kind = .field, .arg = @backingInt(b.symbol(f.name)) });
        }
        parts[avs.len + 1] = try w.containingCondition(inst, parts[1 .. avs.len + 1]);
        const out = try w.spineValue(inst, parts);
        if (inst.int() != w.entry_arg) try w.sight(out, .{ .pending = "it is stored in a record" }, w.token(inst));
        return out;
    }

    /// Change 9's opaque markup slots. Unknown types/paths keep §6.1's aliases.
    fn markupEvents(w: *Walker, av: AV, ty: ?Var, inst: Inst.Index, depth: u32) Allocator.Error!AV {
        const v = ty orelse return av;
        switch (w.store.resolvedContent(v)) {
            .structure => |st| switch (st) {
                .app => |app| {
                    const gm = w.o.in.graph.markup;
                    if (gm.type_module.unwrap()) |m| if (gm.type_name.unwrap()) |n| {
                        const id = w.o.in.types.find(w.o.in.graph, .platform, m, n);
                        if (app.type == id and id != .none) return w.proj(av, .{ .kind = .markup_event, .arg = 0 }, null);
                    };
                    const args = w.store.vars(app.args);
                    if (args.len == 1 and app.type == w.o.in.types.well_known.list)
                        return w.markupEvents(try w.proj(av, .{ .kind = .elem, .arg = 0 }, args[0]), args[0], inst, depth + 1);
                    if (args.len == 1 and app.type == w.o.in.types.well_known.maybe) {
                        const e = w.o.in.types.entries[app.type.int()];
                        const b = w.o.in.birs[e.module.int()];
                        for (b.declCtors(b.decls[e.decl.int()])) |c| {
                            if (!std.mem.eql(u8, w.o.in.interner.slice(b.symbol(c.name)), "Just")) continue;
                            for (b.ctors, 0..) |cc, ci| if (cc.name == c.name) {
                                const ctor = try w.o.ctorId(e.module.int(), @intCast(ci));
                                return w.markupEvents(try w.proj(av, .{ .kind = .ctor, .arg = try w.o.ctorStep(ctor, 0) }, args[0]), args[0], inst, depth + 1);
                            };
                        }
                    }
                    // Missing Maybe metadata also falls through here: keep
                    // the whole tracked arrival, never infer an empty slot.
                    if (!try w.trackedVar(v)) return &.{};
                    return av;
                },
                .record => |record| {
                    var parts: std.ArrayList(AV) = .empty;
                    for (w.store.fields(record.fields)) |f| try parts.append(w.a, try w.markupEvents(try w.proj(av, .{ .kind = .field, .arg = @backingInt(f.name) }, f.value), f.value, inst, depth + 1));
                    if (try w.trackedVar(record.ext)) try parts.append(w.a, av);
                    return w.unionOf(parts.items);
                },
                .unit, .empty_record => return &.{},
                else => return av,
            },
            else => return av,
        }
    }

    fn viewResultType(w: *Walker, arg: Inst.Index) ?Var {
        if (w.bir.instTag(arg) != .record) return null;
        for (w.bir.extraSlice(Bir.inlineRange(w.bir.instData(arg)), Bir.Field)) |f| {
            if (!std.mem.eql(u8, w.o.in.interner.slice(w.bir.symbol(f.name)), "view")) continue;
            const v = w.instType(f.value) orelse return null;
            return switch (w.store.resolvedContent(v)) {
                .structure => |st| if (st == .func) st.func.result else null,
                else => null,
            };
        }
        return null;
    }

    fn constructorValue(w: *Walker, inst: Inst.Index) Allocator.Error!?AV {
        return try w.rowValue((try w.ctorClass(inst)) orelse return null);
    }

    /// §30.11: a member of a schema declaration handed on as a value. Its
    /// class is the row a call of it is applied (`schemaMemberRow`), at the
    /// arity its type gives, so a callee that calls it answers what that
    /// row names. A run there is not seen as one: its input mark stays a
    /// `⊤` (§30.10).
    fn memberValue(w: *Walker, inst: Inst.Index) Allocator.Error!?AV {
        const sm = w.schemaMemberOf(inst) orelse return null;
        const ty = w.instType(inst) orelse return null;
        const arity = switch (w.store.resolvedContent(ty)) {
            .structure => |st| switch (st) {
                .func => |fun| w.store.vars(fun.params).len,
                else => return null,
            },
            else => return null,
        };
        return try w.rowValue((try w.o.schemaMemberRow(sm.m, sm.decl, sm.kind, @intCast(arity))) orelse return null);
    }

    /// A function value with no captures whose class is `sum`.
    fn rowValue(w: *Walker, sum: *const Summary) Allocator.Error!AV {
        const ci: u32 = @intCast(w.closures.items.len);
        try w.closures.append(w.a, .{ .captures = &.{}, .class = sum, .carried = true, .frame = none });
        return w.single(.{ .kind = .closure, .a = ci });
    }

    fn markupCallback(w: *Walker, inst: Inst.Index, function: Inst.Index, f: AV, avs: []const AV) Allocator.Error!AV {
        if (try w.ctorClass(function)) |sum| {
            if (sum.params != avs.len) return w.single(.{ .kind = .top, .a = 0 });
            return w.instRes(sum, .{ .inst = inst, .s = sum, .avs = avs, .depth = 1 });
        }
        if (w.fnParamOf(f) orelse try w.slotOf(f)) |j| {
            if (w.frame != 0) return w.single(.{ .kind = .top, .a = 0 });
            w.fn_state.items[j].calls = .many;
            w.cb_args[function.int() - w.decl.inst_start.int()] = try w.unionOf(avs);
            for (avs, 0..) |av, k| if (av.len != 0) {
                try w.supplies.append(w.a, .{ .fun = j, .k = @intCast(k), .path = eps, .av = av, .probe = none, .owned = false, .cond = try w.deepCond(av), .rcond = try w.rdeepCond(av) });
            };
            return w.single(.{ .kind = .cbres, .a = j, .b = function.int() });
        }
        const classes = try w.classesOf(f);
        if (classes.len == 0) return w.unionOf(&.{ try w.anywhere(try w.unionOf(&.{ f, try w.unionOf(avs) }), inst), try w.single(.{ .kind = .top, .a = 0 }) });
        var out: std.ArrayList(AV) = .empty;
        for (classes) |cls| {
            const sum = (try w.classSummary(cls)) orelse return w.single(.{ .kind = .top, .a = 0 });
            if (sum.params != avs.len) return w.single(.{ .kind = .top, .a = 0 });
            try out.append(w.a, try w.instRes(sum, .{ .inst = inst, .s = sum, .avs = avs, .closure = if (cls == .closure) cls.closure else none, .depth = 1 }));
        }
        return w.unionOf(out.items);
    }

    /// Keep outer captures symbolic while reading a row's nested handlers.
    /// Expanding them to the enclosing declaration's parameters would read
    /// those parameters off in the row's frame, losing them to top.
    fn markupHeld(w: *Walker, av: AV, inst: Inst.Index) Allocator.Error!AV {
        var out: std.ArrayList(AV) = .empty;
        var seen: std.ArrayList(u32) = .empty;
        try w.markupHeldInto(av, &out, &seen);
        return w.anywhere(try w.unionOf(out.items), inst);
    }

    fn markupHeldInto(w: *Walker, av: AV, out: *std.ArrayList(AV), seen: *std.ArrayList(u32)) Allocator.Error!void {
        for (av) |e| {
            const c = w.cells.items[e.cell];
            if (c.kind == .func) continue;
            if (c.kind != .closure) {
                try out.append(w.a, try w.a.dupe(Entry, &.{e}));
                continue;
            }
            if (std.mem.indexOfScalar(u32, seen.items, c.a) != null) continue;
            try seen.append(w.a, c.a);
            for (w.closures.items[c.a].captures) |cap| {
                if (w.frame != 0 and w.local_frame[cap.local] != w.frame) {
                    try out.append(w.a, try w.single(.{ .kind = .env, .a = cap.local, .path = cap.path }));
                } else if (w.local_av[cap.local]) |held| {
                    try w.markupHeldInto(try w.projPath(held, cap.path, null), out, seen);
                } else try out.append(w.a, try w.single(.{ .kind = .top, .a = 0 }));
            }
        }
    }

    const MarkupValues = struct {
        const Value = struct { inst: Inst.Index, av: AV };
        entries: []const Value,

        fn init(a: Allocator, insts: []const Inst.Index, avs: []const AV) Allocator.Error!MarkupValues {
            const entries = try a.alloc(Value, insts.len);
            for (entries, insts, avs) |*entry, inst, av| entry.* = .{ .inst = inst, .av = av };
            std.mem.sort(Value, entries, {}, struct {
                fn less(_: void, x: Value, y: Value) bool {
                    return x.inst.int() < y.inst.int();
                }
            }.less);
            return .{ .entries = entries };
        }

        fn get(v: MarkupValues, inst: Inst.Index) AV {
            var lo: usize = 0;
            var hi = v.entries.len;
            while (lo < hi) {
                const mid = lo + (hi - lo) / 2;
                if (v.entries[mid].inst.int() < inst.int()) lo = mid + 1 else hi = mid;
            }
            // Both walks cover the same operands; every get in the full
            // markup corpus exercises this invariant under runtime safety.
            std.debug.assert(lo < v.entries.len and v.entries[lo].inst == inst);
            return v.entries[lo].av;
        }
    };

    fn markupTreeEvents(w: *Walker, inst: Inst.Index, root: Bir.ExtraIndex, vals: MarkupValues) Allocator.Error!AV {
        const b = w.bir;
        var parts: std.ArrayList(AV) = .empty;
        switch (b.markupKind(root)) {
            .text => {},
            .hole => {
                const value = b.extraData(root, Bir.MarkupHole).value;
                try parts.append(w.a, try w.markupEvents(vals.get(value), w.instType(value), inst, 0));
            },
            .element => {
                const e = b.extraData(root, Bir.MarkupElement);
                for (b.extraSlice(.{ .start = e.items_start, .end = e.items_end }, Bir.ExtraIndex)) |at| {
                    const item = b.extraData(at, Bir.MarkupItem);
                    const value = item.value.unwrap() orelse continue;
                    var known = false;
                    if (w.m < w.o.in.dispatch.len) for (w.o.in.dispatch[w.m].markup) |fact| {
                        if (fact.node != @backingInt(at)) continue;
                        known = true;
                        if (fact.kind == .event) try parts.append(w.a, try w.markupHeld(vals.get(value), inst));
                    };
                    if (!known) try parts.append(w.a, try w.markupHeld(vals.get(value), inst));
                }
                for (b.extraSlice(.{ .start = e.children_start, .end = e.children_end }, Bir.ExtraIndex)) |node| try parts.append(w.a, try w.markupTreeEvents(inst, node, vals));
            },
            .fragment => {
                const f = b.extraData(root, Bir.MarkupFragment);
                for (b.extraSlice(.{ .start = f.children_start, .end = f.children_end }, Bir.ExtraIndex)) |node| try parts.append(w.a, try w.markupTreeEvents(inst, node, vals));
            },
            .@"for", .show => {
                const form = b.extraData(root, Bir.MarkupForm);
                if (form.fallback.unwrap()) |fallback| try parts.append(w.a, try w.markupEvents(vals.get(fallback), w.instType(fallback), inst, 0));
                if (form.row != Bir.none_extra) {
                    const row = b.extraData(@fromBackingInt(form.row), Bir.MarkupRow);
                    const list = if (form.list.unwrap()) |value| vals.get(value) else &.{};
                    // Unknown Show rows keep their input; For only hands over elements.
                    const element = if (b.markupKind(root) == .@"for") try w.proj(list, .{ .kind = .elem, .arg = 0 }, null) else try w.anywhere(list, inst);
                    var arity: u8 = 1;
                    if (w.m < w.o.in.dispatch.len) for (w.o.in.dispatch[w.m].markup) |fact| {
                        if (fact.node == @backingInt(root)) arity = fact.arity;
                    };
                    const result = try w.markupCallback(inst, row.function, vals.get(row.function), if (arity == 2) &.{ element, &.{} } else &.{element});
                    // The row's result type belongs to this module's store.
                    const ft = w.instType(row.function);
                    const rt: ?Var = if (ft) |v| switch (w.store.resolvedContent(v)) {
                        .structure => |st| if (st == .func) st.func.result else null,
                        else => null,
                    } else null;
                    try parts.append(w.a, try w.markupEvents(result, rt, inst, 0));
                }
            },
            .component => {
                var values: std.ArrayList(Inst.Index) = .empty;
                try b.markupValues(w.a, root, &values);
                for (values.items) |value| try parts.append(w.a, try w.markupHeld(vals.get(value), inst));
                try parts.append(w.a, try w.single(.{ .kind = .top, .a = 0 }));
            },
        }
        return w.anywhere(try w.unionOf(parts.items), inst);
    }

    /// §26.2: `e?` on a `Result` returns `Err x` from the definition it
    /// targets — the frame being walked, since a `?` under a lambda is
    /// refused (`language.md` §6.6) — so `e`'s `Err` payload is part of that
    /// frame's result, exactly. A `Maybe`'s `Nothing` holds nothing.
    fn earlyReturn(w: *Walker, operand: Inst.Index, s: AV) Allocator.Error!void {
        const v = w.instType(operand) orelse return;
        const re = try w.o.resultErr();
        if (re.ty == .none) return;
        const app = switch (w.store.resolvedContent(v)) {
            .structure => |st| switch (st) {
                .app => |x| x,
                else => return,
            },
            else => return,
        };
        if (app.type != re.ty) return;
        const args = w.store.vars(app.args);
        if (args.len == 0) return;
        const step: Step = .{ .kind = .ctor, .arg = try w.o.ctorStep(re.ctor, 0) };
        const payload = try w.proj(s, step, args[0]);
        if (payload.len == 0) return;
        try w.frames.items[w.frame].early.appendSlice(w.a, try w.shift(payload, step));
    }

    /// The frame's result: its body's value and what its `?`s return (§26.2).
    fn withEarly(w: *Walker, frame: u32, result: AV) Allocator.Error!AV {
        const early = w.frames.items[frame].early.items;
        if (early.len == 0) return result;
        return w.unionOf(&.{ result, early });
    }

    /// `tracked`, remembered per type variable (§18.11).
    fn trackedVar(w: *Walker, v: Var) Allocator.Error!bool {
        const root, _ = w.store.resolved(v);
        const key = (@as(u64, w.m) << 32) | @backingInt(root);
        if (w.o.tracked_memo.get(key)) |t| return t;
        const t = try w.o.tracked(w.store, v, 0);
        try w.o.tracked_memo.put(w.o.in.gpa, key, t);
        return t;
    }

    /// `listTracked`, remembered per type as `trackedVar` is.
    fn listTrackedVar(w: *Walker, v: Var) Allocator.Error!bool {
        const root, _ = w.store.resolved(v);
        const key = (@as(u64, w.m) << 32) | @backingInt(root) | (@as(u64, 1) << 63);
        if (w.o.tracked_memo.get(key)) |t| return t;
        const t = try w.o.listTracked(w.store, v, 0);
        try w.o.tracked_memo.put(w.o.in.gpa, key, t);
        return t;
    }

    fn instTypeOpt(w: *const Walker, inst: Inst.Index) Var.Optional {
        return if (w.instType(inst)) |v| v.toOptional() else .none;
    }

    fn isTracked(w: *Walker, inst: Inst.Index) Allocator.Error!bool {
        const v = w.instType(inst) orelse return true;
        return w.trackedVar(v);
    }

    fn single(w: *Walker, c: Cell) Allocator.Error!AV {
        const id = try w.cell(c);
        return w.a.dupe(Entry, &.{.{ .path = eps, .cell = id }});
    }

    /// A local, or a field path of one; inside a lambda, a local of an
    /// enclosing frame is a capture (§5, §7.3).
    fn evalLocal(w: *Walker, l: u32, path: u32, inst: Inst.Index) Allocator.Error!AV {
        if (l >= w.local_av.len) return &.{};
        // §31.6: a lambda's read of a record's field path that it captured,
        // which it reads when it is made; report mode counts them, once per
        // lambda, local and path, whatever the field's type.
        if (w.mode == .report and w.frame != 0 and l < w.local_frame.len and w.local_frame[l] != w.frame) {
            if (w.o.firstStep(path)) |first| if (first.kind == .field) {
                const g = try w.eager_seen.getOrPut(w.a, .{ w.frame, l, path });
                if (!g.found_existing) w.eager_reads += 1;
                try w.frames.items[w.frame].eager.append(w.a, .{ .local = l, .path = path, .read_inst = inst.int() });
            };
        }
        const ty = w.instType(inst);
        if (ty) |v| if (!try w.trackedVar(v)) return &.{};
        const bound = w.local_av[l] != null;
        if (w.early[l] == 1) w.early[l] = 2;
        if (bound and w.local_frame[l] == w.frame) return w.typeFilter(try w.projPath(w.local_av[l].?, path, ty), ty);
        // Not bound yet in the declaration's own frame: nothing is known.
        if (w.frame == 0) return &.{};
        // A capture, recorded in every frame between the local's and this
        // one, so an enclosing lambda holds what its inner lambda reads. A
        // local not bound yet (one a local function names above its line)
        // is this frame's capture, looked up when needed.
        var f = w.frame;
        while (f != none) : (f = w.frames.items[f].parent) {
            if (bound and f == w.local_frame[l]) break;
            try w.frames.items[f].captures.append(w.a, .{ .local = l, .path = path });
            if (!bound) break;
        }
        return w.single(.{ .kind = .env, .a = l, .path = path, .ty = if (ty) |v| v.toOptional() else .none });
    }

    /// `av` read at type `ty`: a `⊤` at a path whose type crosses (§4.4) is
    /// no cell. A `Js.to` answers `⊤` at any type, and a local bound at a
    /// type variable keeps what it answered; inside a record that crossed
    /// before §31.2 nothing read it.
    /// Only record, tuple and list steps are followed; any other keeps the
    /// entry.
    fn typeFilter(w: *Walker, av: AV, ty: ?Var) Allocator.Error!AV {
        const t = ty orelse return av;
        var out: ?std.ArrayList(Entry) = null;
        for (av, 0..) |e, i| {
            const crossing = e.path != eps and w.cells.items[e.cell].kind == .top and try w.crossesAt(t, e.path);
            if (crossing and out == null) {
                out = .empty;
                try out.?.appendSlice(w.a, av[0..i]);
            }
            if (!crossing) if (out) |*o| try o.append(w.a, e);
        }
        return if (out) |o| o.items else av;
    }

    /// Whether the value at `path` below a value of type `t` crosses.
    fn crossesAt(w: *Walker, t: Var, path: u32) Allocator.Error!bool {
        var v = t;
        for (w.o.steps(path)) |s| {
            const st = switch (w.store.resolvedContent(v)) {
                .structure => |x| x,
                else => return false,
            };
            switch (s.kind) {
                .field => v = w.fieldVar(v, s.arg) orelse return false,
                .tuple => switch (st) {
                    .tuple => |r| {
                        const els = w.store.vars(r);
                        if (s.arg >= els.len) return false;
                        v = els[s.arg];
                    },
                    else => return false,
                },
                .elem => switch (st) {
                    .app => |a| {
                        if (a.type != w.o.in.types.well_known.list) return false;
                        const args = w.store.vars(a.args);
                        if (args.len != 1) return false;
                        v = args[0];
                    },
                    else => return false,
                },
                else => return false,
            }
        }
        return !try w.trackedVar(v);
    }

    /// The type of field `name` of a record type, through its extensions.
    fn fieldVar(w: *Walker, v_in: Var, name: u32) ?Var {
        var v = v_in;
        while (true) {
            switch (w.store.resolvedContent(v)) {
                .structure => |st| switch (st) {
                    .record => |r| {
                        for (w.store.fields(r.fields)) |f| if (@backingInt(f.name) == name) return f.value;
                        v = r.ext;
                    },
                    else => return null,
                },
                else => return null,
            }
        }
    }

    /// Whether `inst` calls `core/Record.copy`, the fix §31.12 names. Its
    /// row aliases π₁ at ε (`recordRow`), which is right for the fields the
    /// copy shares and wrong for its object, which is new and held by
    /// nobody (§31.15). Until a summary's results name a record's object
    /// (§31.7), an update whose base is the copy itself demands that new
    /// object.
    fn isRecordCopyCall(w: *const Walker, inst: Inst.Index) bool {
        const b = w.bir;
        if (b.instTag(inst) != .call) return false;
        const t = w.valueTarget(@fromBackingInt(@intCast(b.instData(inst).lhs))) orelse return false;
        if (w.o.in.packages[t.m] != .core or !std.mem.eql(u8, w.o.in.module_names[t.m], "Record")) return false;
        const cb = w.o.in.birs[t.m];
        return std.mem.eql(u8, w.o.in.interner.slice(cb.symbol(cb.decls[t.d].name)), "copy");
    }

    /// §31.15: `Record.copy r`'s value. Its fields are `r`'s, which the row
    /// says (π₁ at ε); its object is new, which a row cannot say of a whole
    /// provenance. A closed record type is split field by field, as an
    /// update's unwritten fields are, and the object is a site of its own.
    /// An open type keeps the row's value, the original's object with it:
    /// a later update of the copy then writes the original, which refuses
    /// more and never less.
    fn copiedRecord(w: *Walker, av: AV, inst: Inst.Index) Allocator.Error!AV {
        const fields = w.recordFields(w.instType(inst)) orelse return av;
        var out: std.ArrayList(Entry) = .empty;
        for (av) |e| {
            if (e.path != eps) {
                try out.append(w.a, e);
                continue;
            }
            switch (w.cells.items[e.cell].kind) {
                .closure, .func => try out.append(w.a, e),
                // An object alone, whose fields are entries of their own: a
                // literal's, an updated record's of a closed type.
                .site => if (!w.cells.items[e.cell].nonlist) try out.append(w.a, e),
                .except => if (w.cells.items[e.cell].b != except_all) try w.splitFields(&out, e, fields),
                else => try w.splitFields(&out, e, fields),
            }
        }
        try out.append(w.a, .{ .path = eps, .cell = try w.cell(.{ .kind = .site, .a = inst.int(), .made = true, .nonlist = true, .ty = w.instTypeOpt(inst) }) });
        return w.norm(out.items);
    }

    /// Entry `e` at ε, a symbolic record, as one entry per field of `fields`
    /// that a list's demand may reach.
    fn splitFields(w: *Walker, out: *std.ArrayList(Entry), e: Entry, fields: []const TypeStore.Field) Allocator.Error!void {
        for (fields) |fl| {
            if (!try w.trackedVar(fl.value)) continue;
            const s: Step = .{ .kind = .field, .arg = @backingInt(fl.name) };
            if (try w.projCell(e.cell, s, fl.value)) |c| {
                try out.append(w.a, .{ .path = try w.o.child(eps, .field, s.arg), .cell = c, .approx = e.approx, .grown = gStep(e.grown) });
            }
        }
    }

    fn evalRecordUpdate(w: *Walker, inst: Inst.Index) Allocator.Error!AV {
        const b = w.bir;
        const data = b.instData(inst);
        const base_inst: Inst.Index = @fromBackingInt(@intCast(data.lhs));
        const fields = b.extraSlice(b.subRange(@fromBackingInt(@intCast(data.rhs))), Bir.Field);
        const base = try w.eval(base_inst);
        try w.pushPending(base, base_inst, false);
        const insts = try w.a.alloc(Inst.Index, fields.len);
        for (fields, insts) |f, *x| x.* = f.value;
        const avs = try w.evalOperands(insts, false);
        w.popPending(avs.len + 1);
        const names = try w.a.alloc(u32, fields.len);
        for (fields, names) |f, *n| n.* = @backingInt(b.symbol(f.name));
        w.point += 1;
        // §31.4 item 5: a base whose every field is replaced is read at none,
        // whatever stands below it — a marker's levels included.
        w.use_reads_none = if (w.recordFields(w.instType(base_inst))) |fs| for (fs) |fl| {
            if (std.mem.indexOfScalar(u32, names, @backingInt(fl.name)) == null) break false;
        } else true else false;
        try w.useOperand(base_inst, w.token(inst), names);
        w.use_reads_none = false;
        for (insts) |x| try w.useOperand(x, w.token(inst), &.{});
        // §31.3: the update is a demand on its base's object, after every
        // new value, in every walk: a summary reads its write off (§31.7);
        // nothing enforces it yet (R4).
        {
            const written = try w.a.dupe(u32, names);
            std.mem.sort(u32, written, {}, std.sort.asc(u32));
            const ref = try w.refPath(base_inst);
            try w.demandOn(.{
                .kind = .report,
                .inst = inst.int(),
                .token = w.token(inst),
                .op = "update",
                .base_text = if (w.mode == .report) try w.baseText(base_inst) else "",
                .base_ref = if (ref) |r| .{ .local = r.local, .path = r.path } else null,
                .base_ty = w.instType(base_inst),
                .base = if (w.isRecordCopyCall(base_inst)) try w.single(.{ .kind = .site, .a = base_inst.int(), .made = true, .nonlist = true, .ty = w.instTypeOpt(base_inst) }) else base,
                .others = avs,
                .base_inst = base_inst,
                .fields = written,
            });
        }
        // §31.3: the result is the base's object, written — `(ε, c ∖ F)` for
        // each record cell `c` at ε. A symbolic entry is split into its
        // record type's other fields when the type is closed, and the object
        // stays beside them, alone (`except_all`); an open type's keeps
        // every field it did not write, through its exception set.
        var out: std.ArrayList(Entry) = .empty;
        const all_fields = w.recordFields(w.instType(base_inst));
        // One base entry whose split is known whole, merged in its order
        // rather than sorted again with the rest (#716).
        var whole: ?struct { e: Entry, memo: *SplitMemo } = null;
        for (base) |e| {
            const k = w.cells.items[e.cell].kind;
            if (e.path == eps and k != .top and k != .site and k != .closure and k != .func) {
                try out.append(w.a, .{ .path = eps, .cell = try w.exceptCell(e.cell, names, all_fields != null), .approx = e.approx, .grown = e.grown });
                if (all_fields) |fs| {
                    if (fs.len <= split_memo_min) {
                        for (fs) |fl| {
                            if (std.mem.indexOfScalar(u32, names, @backingInt(fl.name)) != null) continue;
                            if (!try w.trackedVar(fl.value)) continue;
                            const s: Step = .{ .kind = .field, .arg = @backingInt(fl.name) };
                            if (try w.projCell(e.cell, s, fl.value)) |c| {
                                try out.append(w.a, .{ .path = try w.o.child(eps, .field, s.arg), .cell = c, .approx = e.approx, .grown = gStep(e.grown) });
                            }
                        }
                        continue;
                    }
                    // Every arm of a `case` over a wide model splits the same
                    // base: each field's projection is computed once (#716).
                    const gop = try w.split_memo.getOrPut(w.a, .{ e.cell, @intFromPtr(fs.ptr), fs.len });
                    if (!gop.found_existing) {
                        const fresh = try w.a.create(SplitMemo);
                        fresh.* = .{ .fields = try w.a.alloc(SplitField, fs.len), .unknown = fs.len };
                        @memset(fresh.fields, .{});
                        gop.value_ptr.* = fresh;
                    }
                    const memo = gop.value_ptr.*;
                    if (memo.sorted != null and whole == null) {
                        whole = .{ .e = e, .memo = memo };
                        continue;
                    }
                    for (fs, memo.fields) |fl, *m| {
                        if (std.mem.indexOfScalar(u32, names, @backingInt(fl.name)) != null) continue;
                        if (m.state == .unknown) {
                            memo.unknown -= 1;
                            m.state = .none;
                            if (try w.trackedVar(fl.value)) {
                                const s: Step = .{ .kind = .field, .arg = @backingInt(fl.name) };
                                if (try w.projCell(e.cell, s, fl.value)) |c| {
                                    m.* = .{ .state = .cell, .cell = c, .path = try w.o.child(eps, .field, s.arg) };
                                }
                            }
                        }
                        if (m.state == .cell) try out.append(w.a, .{ .path = m.path, .cell = m.cell, .approx = e.approx, .grown = gStep(e.grown) });
                    }
                    if (memo.unknown == 0 and memo.sorted == null) {
                        var order: std.ArrayList(u32) = .empty;
                        for (memo.fields, 0..) |m, i| if (m.state == .cell) try order.append(w.a, @intCast(i));
                        std.mem.sort(u32, order.items, memo.fields, struct {
                            fn less(ms: []const SplitField, x: u32, y: u32) bool {
                                if (ms[x].path != ms[y].path) return ms[x].path < ms[y].path;
                                return ms[x].cell < ms[y].cell;
                            }
                        }.less);
                        memo.sorted = order.items;
                    }
                    continue;
                }
                // An open type: its fields are reached through the exception set.
                continue;
            }
            if (w.o.firstStep(e.path)) |first| {
                if (first.kind == .field and std.mem.indexOfScalar(u32, names, first.arg) != null) continue;
            }
            try out.append(w.a, e);
        }
        if (whole) |x| return w.splitUpdate(inst, x.e, x.memo, all_fields.?, names, out.items, fields, avs);
        var parts: std.ArrayList(AV) = .empty;
        try parts.append(w.a, base: {
            const x = whole orelse break :base try w.norm(out.items);
            const fs = all_fields.?;
            var split: std.ArrayList(Entry) = .empty;
            for (x.memo.sorted.?) |i| {
                if (std.mem.indexOfScalar(u32, names, @backingInt(fs[i].name)) != null) continue;
                const m = x.memo.fields[i];
                try split.append(w.a, .{ .path = m.path, .cell = m.cell, .approx = x.e.approx, .grown = gStep(x.e.grown) });
            }
            if (std.debug.runtime_safety and @import("ownership_options").full_cross_check) {
                var all: std.ArrayList(Entry) = .empty;
                try all.appendSlice(w.a, out.items);
                try all.appendSlice(w.a, split.items);
                const want = try w.norm(all.items);
                const got = try w.mergeNormal(split.items, try w.norm(try w.a.dupe(Entry, out.items)));
                std.debug.assert(want.len == got.len);
                for (want, got) |p, q| std.debug.assert(std.meta.eql(p, q));
            }
            break :base try w.mergeNormal(split.items, try w.norm(out.items));
        });
        for (fields, avs) |f, av| {
            const shifted = try w.shift(av, .{ .kind = .field, .arg = @backingInt(b.symbol(f.name)) });
            try w.sight(shifted, .{ .pending = "it is stored in a record" }, w.token(inst));
            try parts.append(w.a, shifted);
        }
        return w.spineValue(inst, parts.items);
    }

    /// `evalRecordUpdate`'s value for a base entry `e` whose split is known
    /// whole (#825): the same value, made from the split's run without
    /// copying it entry by entry, and kept with what it is made of
    /// (`split_values`). `out` holds the base's other entries, and `avs` the
    /// new fields' values, of `fields`.
    fn splitUpdate(w: *Walker, inst: Inst.Index, e: Entry, memo: *SplitMemo, fs: []const TypeStore.Field, names: []const u32, out: []Entry, fields: []const Bir.Field, avs: []const AV) Allocator.Error!AV {
        const b = w.bir;
        const sr = try w.splitRun(memo, e.approx, gStep(e.grown));
        // The written fields' places in the run, ascending.
        var removed: std.ArrayList(u32) = .empty;
        for (names) |n| if (fieldIndex(fs, n)) |i| if (sr.at[i] != none) try removed.append(w.a, sr.at[i]);
        std.mem.sort(u32, removed.items, {}, std.sort.asc(u32));
        const rest0 = try w.norm(out);
        if (std.debug.runtime_safety and @import("ownership_options").full_cross_check) {
            // The base part is the split without the written fields, and
            // the base's other entries, as the entry by entry way makes it.
            var split: std.ArrayList(Entry) = .empty;
            for (memo.sorted.?) |i| {
                if (std.mem.indexOfScalar(u32, names, @backingInt(fs[i].name)) != null) continue;
                const m = memo.fields[i];
                try split.append(w.a, .{ .path = m.path, .cell = m.cell, .approx = e.approx, .grown = gStep(e.grown) });
            }
            const want = try w.mergeNormal(split.items, rest0);
            const got = try w.mergeSplit(sr.entries, removed.items, rest0);
            std.debug.assert(want.len == got.len);
            for (want, got) |x, y| std.debug.assert(std.meta.eql(x, y));
        }
        const others = try w.a.alloc(AV, fields.len);
        for (fields, avs, others) |f, av, *o| {
            const shifted = try w.shift(av, .{ .kind = .field, .arg = @backingInt(b.symbol(f.name)) });
            try w.sight(shifted, .{ .pending = "it is stored in a record" }, w.token(inst));
            o.* = shifted;
        }
        return w.splitSpineValue(inst, sr, removed.items, rest0, others);
    }

    /// The index of the field `name` in `fs`, which the type store keeps
    /// sorted by symbol id; null when it has none.
    fn fieldIndex(fs: []const TypeStore.Field, name: u32) ?u32 {
        var lo: usize = 0;
        var hi = fs.len;
        while (lo < hi) {
            const mid = lo + (hi - lo) / 2;
            const at = @backingInt(fs[mid].name);
            if (at == name) return @intCast(mid);
            if (at < name) lo = mid + 1 else hi = mid;
        }
        return null;
    }

    /// `memo`'s run for a base entry of this `approx` and `grown`, made the
    /// first time it is asked for (#825).
    fn splitRun(w: *Walker, memo: *SplitMemo, approx: u32, grown: Grown) Allocator.Error!*const SplitRun {
        for (memo.runs.items) |r| if (r.approx == approx and r.grown == grown) return r;
        const sorted = memo.sorted.?;
        const entries = try w.a.alloc(Entry, sorted.len);
        const at = try w.a.alloc(u32, memo.fields.len);
        @memset(at, none);
        var facing: std.ArrayList(u32) = .empty;
        for (sorted, entries, 0..) |i, *x, k| {
            const m = memo.fields[i];
            x.* = .{ .path = m.path, .cell = m.cell, .approx = approx, .grown = grown };
            at[i] = @intCast(k);
            if (!w.cells.items[m.cell].condition_only and w.listFacing(m.cell) != null) try facing.append(w.a, @intCast(k));
        }
        const sr = try w.a.create(SplitRun);
        sr.* = .{ .entries = entries, .at = at, .facing = facing.items, .approx = approx, .grown = grown };
        try memo.runs.append(w.a, sr);
        return sr;
    }

    /// `big` without the entries at `removed` (ascending), merged with
    /// `small`, both in `norm`'s form, as `mergeNormal` merges them: a
    /// binary search per entry of `small`, and the runs of `big` between
    /// them copied whole (#825).
    fn mergeSplit(w: *Walker, big: []const Entry, removed: []const u32, small: AV) Allocator.Error!AV {
        const out = try w.a.alloc(Entry, big.len - removed.len + small.len);
        var n: usize = 0;
        var bi: usize = 0;
        var ri: usize = 0;
        for (small) |e| {
            // The first entry of `big` from `bi` not before `e`.
            var lo = bi;
            var hi = big.len;
            while (lo < hi) {
                const mid = lo + (hi - lo) / 2;
                const m = big[mid];
                if (m.path < e.path or (m.path == e.path and m.cell < e.cell)) lo = mid + 1 else hi = mid;
            }
            n = copyKept(out, n, big, bi, lo, removed, &ri);
            bi = lo;
            const kept = bi < big.len and !(ri < removed.len and removed[ri] == bi);
            if (bi < big.len and big[bi].path == e.path and big[bi].cell == e.cell) {
                if (kept) {
                    out[n] = .{ .path = e.path, .cell = e.cell, .approx = @min(big[bi].approx, e.approx), .grown = gJoin(big[bi].grown, e.grown) };
                } else {
                    out[n] = e;
                    ri += 1;
                }
                bi += 1;
            } else out[n] = e;
            n += 1;
        }
        n = copyKept(out, n, big, bi, big.len, removed, &ri);
        return out[0..n];
    }

    /// `big[from..to]` into `out` at `n`, but the positions of `removed`
    /// from `ri.*` on; the new `n`.
    fn copyKept(out: []Entry, n_in: usize, big: []const Entry, from: usize, to: usize, removed: []const u32, ri: *usize) usize {
        var n = n_in;
        var at = from;
        while (at < to) {
            const stop = if (ri.* < removed.len and removed[ri.*] < to) removed[ri.*] else to;
            @memcpy(out[n..][0 .. stop - at], big[at..stop]);
            n += stop - at;
            at = stop;
            if (at < to) {
                at += 1;
                ri.* += 1;
            }
        }
        return n;
    }

    /// `spineValue(inst, parts)` for `parts` = the split `run` without
    /// `removed` merged with `rest0`, then `others` (#825): the same guards
    /// made in the same order, from the entries a list's facts read, and
    /// the same value, kept with what it is made of (`split_values`).
    fn splitSpineValue(w: *Walker, inst: Inst.Index, sr: *const SplitRun, removed: []const u32, rest0: AV, others: []const AV) Allocator.Error!AV {
        const lfs = try w.a.alloc([]const Entry, others.len + 1);
        // Part 0's entries that a list's facts read, in its order: the
        // run's facing ones that stay, merged with `rest0`'s.
        {
            var lf: std.ArrayList(Entry) = .empty;
            var fi: usize = 0;
            var ri: usize = 0;
            var rest_lf: std.ArrayList(Entry) = .empty;
            for (rest0) |e| if (!w.cells.items[e.cell].condition_only and w.listFacing(e.cell) != null) try rest_lf.append(w.a, e);
            var ki: usize = 0;
            while (true) {
                // The next facing position of the run that is not removed.
                while (fi < sr.facing.len) {
                    while (ri < removed.len and removed[ri] < sr.facing[fi]) ri += 1;
                    if (ri < removed.len and removed[ri] == sr.facing[fi]) {
                        fi += 1;
                        continue;
                    }
                    break;
                }
                const have_run = fi < sr.facing.len;
                const have_rest = ki < rest_lf.items.len;
                if (!have_run and !have_rest) break;
                if (have_run and have_rest) {
                    const a = sr.entries[sr.facing[fi]];
                    const r = rest_lf.items[ki];
                    if (a.path == r.path and a.cell == r.cell) {
                        try lf.append(w.a, .{ .path = a.path, .cell = a.cell, .approx = @min(a.approx, r.approx), .grown = gJoin(a.grown, r.grown) });
                        fi += 1;
                        ki += 1;
                    } else if (a.path < r.path or (a.path == r.path and a.cell < r.cell)) {
                        try lf.append(w.a, a);
                        fi += 1;
                    } else {
                        try lf.append(w.a, r);
                        ki += 1;
                    }
                } else if (have_run) {
                    try lf.append(w.a, sr.entries[sr.facing[fi]]);
                    fi += 1;
                } else {
                    try lf.append(w.a, rest_lf.items[ki]);
                    ki += 1;
                }
            }
            lfs[0] = lf.items;
        }
        for (others, lfs[1..]) |o, *l| {
            var lf: std.ArrayList(Entry) = .empty;
            for (o) |e| if (!w.cells.items[e.cell].condition_only and w.listFacing(e.cell) != null) try lf.append(w.a, e);
            l.* = lf.items;
        }
        var small: std.ArrayList(Entry) = .empty;
        try small.appendSlice(w.a, rest0);
        for (others) |o| try small.appendSlice(w.a, o);
        for (lfs, 0..) |part, i| for (part) |e| {
            var acc: CondAcc = .{};
            var approximate = e.approx;
            for (lfs, 0..) |other, j| {
                if (i == j) continue;
                for (other) |f| {
                    if (f.approx != 0) approximate = f.approx;
                    const g = (try w.besideCell(e, f)) orelse continue;
                    const separation = try w.sepSpines(e.cell, g, e.approx == 0 and f.approx == 0);
                    if (separation == cond_yes) continue;
                    try acc.add(w, if (w.symbolicSpine(e.cell)) try w.rootSeparation(e.cell, g) else separation);
                }
            }
            const k = try w.condAndAll(&acc);
            if (k == cond_yes) continue;
            const guard = try w.cell(.{ .kind = .site, .a = inst.int(), .b = 1, .path = e.path, .condition_only = true });
            try w.initCond(guard, cond_yes);
            try w.initSpine(guard, k);
            try small.append(w.a, .{ .path = e.path, .cell = guard, .approx = approximate, .grown = e.grown });
        };
        const rest = try w.norm(small.items);
        const got = try w.mergeSplit(sr.entries, removed, rest);
        if (got.len != 0) try w.split_values.put(w.a, @intFromPtr(got.ptr), .{ .len = got.len, .run = sr, .removed = removed, .rest = rest });
        return got;
    }

    /// `parts` joined through what they share (#825): when two or more of
    /// them are values `split_values` keeps over one run, their join is the
    /// run without the positions every one of them removed, merged with
    /// everything else, so no entry of the run is merged more than once.
    /// Null when no two parts share a run.
    fn unionSplit(w: *Walker, parts: []const AV) Allocator.Error!?AV {
        var sr: ?*const SplitRun = null;
        var shared: usize = 0;
        for (parts) |p| {
            if (p.len == 0) continue;
            const v = w.split_values.get(@intFromPtr(p.ptr)) orelse continue;
            if (v.len != p.len) continue;
            if (sr == null) sr = v.run;
            if (v.run == sr.?) shared += 1;
        }
        if (shared < 2) return null;
        var removed: ?[]const u32 = null;
        var small: std.ArrayList(Entry) = .empty;
        for (parts) |p| {
            if (p.len == 0) continue;
            if (w.split_values.get(@intFromPtr(p.ptr))) |v| if (v.len == p.len and v.run == sr.?) {
                try small.appendSlice(w.a, v.rest);
                // The positions every part removed: both lists ascending.
                if (removed) |r| {
                    var both: std.ArrayList(u32) = .empty;
                    var i: usize = 0;
                    var j: usize = 0;
                    while (i < r.len and j < v.removed.len) {
                        if (r[i] == v.removed[j]) {
                            try both.append(w.a, r[i]);
                            i += 1;
                            j += 1;
                        } else if (r[i] < v.removed[j]) i += 1 else j += 1;
                    }
                    removed = both.items;
                } else removed = v.removed;
                continue;
            };
            try small.appendSlice(w.a, p);
        }
        const rest = try w.norm(small.items);
        const got = try w.mergeSplit(sr.?.entries, removed.?, rest);
        if (std.debug.runtime_safety and @import("ownership_options").full_cross_check) {
            var all: std.ArrayList(Entry) = .empty;
            for (parts) |p| try all.appendSlice(w.a, p);
            const want = try w.norm(all.items);
            std.debug.assert(want.len == got.len);
            for (want, got) |x, y| std.debug.assert(std.meta.eql(x, y));
        }
        if (got.len != 0) try w.split_values.put(w.a, @intFromPtr(got.ptr), .{ .len = got.len, .run = sr.?, .removed = removed.?, .rest = rest });
        return got;
    }

    /// The fields of a closed record type, or null.
    fn recordFields(w: *Walker, ty: ?Var) ?[]const TypeStore.Field {
        const v = ty orelse return null;
        switch (w.store.resolvedContent(v)) {
            .structure => |s| switch (s) {
                .record => |r| {
                    switch (w.store.resolvedContent(r.ext)) {
                        .structure => |e| if (e == .empty_record) return w.store.fields(r.fields),
                        else => {},
                    }
                    return null;
                },
                else => return null,
            },
            else => return null,
        }
    }

    /// A lambda or local function: its body walked as a frame of its own,
    /// and its class read off it (§16.5).
    fn closure(w: *Walker, params: []const Inst.Index, body: Inst.Index, ci_in: ?u32, tok: u32, fn_ty: ?Var) Allocator.Error!AV {
        const creation = w.current_inst;
        const saved_frame = w.frame;
        const saved_ctx = w.ctx;
        const id: u32 = @intCast(w.frames.items.len);
        try w.frames.append(w.a, .{ .parent = saved_frame, .pending_base = w.pending.items.len });
        const ci: u32 = ci_in orelse blk: {
            try w.closures.append(w.a, .{ .captures = &.{} });
            break :blk @intCast(w.closures.items.len - 1);
        };
        w.closures.items[ci].params = params;
        w.closures.items[ci].token = tok;
        w.closures.items[ci].frame = id;
        for (params, 0..) |p, k| {
            const at = p.int() -% w.decl.inst_start.int();
            if (at < w.pat_closure.len) w.pat_closure[at] = .{ ci, @intCast(k) };
        }
        w.frame = id;
        const escapes_from = w.escaped.items.len;
        const demands_from = w.demands.items.len;
        for (params) |p| try w.bindParam(p, 1);
        const result = try w.withEarly(id, try w.eval(body));
        try w.consume(&.{body}, w.token(body));
        try w.sight(result, .{ .pending = "it is returned by a function value" }, w.token(body));
        // Captures of locals of this frame only: an inner capture of an
        // outer-outer local was recorded in the frames between.
        var caps: std.ArrayList(Capture) = .empty;
        for (w.frames.items[id].captures.items) |cap| {
            if (cap.local < w.local_frame.len and w.local_frame[cap.local] == id and w.local_av[cap.local] != null) continue;
            try caps.append(w.a, cap);
        }
        w.closures.items[ci].captures = try caps.toOwnedSlice(w.a);
        var env_escapes: std.ArrayList(Capture) = .empty;
        for (w.escaped.items[escapes_from..]) |x| {
            const c = w.cells.items[x.cell];
            if (c.kind != .env or c.a >= w.local_frame.len) continue;
            if (w.local_av[c.a] != null and w.local_frame[c.a] == id) continue;
            try env_escapes.append(w.a, .{ .local = c.a, .path = c.path });
        }
        w.closures.items[ci].env_escapes = try env_escapes.toOwnedSlice(w.a);
        // §18.8: the captures its own body writes make it once; a record's
        // write of a capture too, with the fields it writes (§31.4 item 4).
        // One capture written twice — a list's write and a record's at one
        // path, or two records' writes with different fields — is two
        // entries and so two creation demands, each checked on its own and
        // each a probe (`decideOnce`: a list's write reads the list's, a
        // record's both): redundant, never weaker, so they are not merged.
        var env_writes: std.ArrayList(Capture) = .empty;
        for (w.demands.items[demands_from..]) |rec| {
            if (rec.kind == .probe or rec.kind == .value or rec.frame != id) continue;
            for (rec.cells) |e| {
                const c = w.cells.items[try w.takenBase(e.cell)];
                if (c.kind != .env) continue;
                if (c.a < w.local_frame.len and w.local_av[c.a] != null and w.local_frame[c.a] == id) continue;
                try env_writes.append(w.a, .{ .local = c.a, .path = c.path, .deep = rec.deep, .extent = rec.extent, .fields = if (rec.fields) |fs| try w.a.dupe(u32, fs) else null });
            }
        }
        w.closures.items[ci].env_writes = try env_writes.toOwnedSlice(w.a);
        const cls = try w.a.create(Summary);
        cls.* = try w.readOffFrame(id, params, result);
        if (w.hasOpenCast(Summary, cls.*)) cls.cast_signature = try w.castClosureSignature(params, body, fn_ty);

        cls.once = w.closures.items[ci].env_writes.len > 0;
        w.closures.items[ci].class = cls;
        w.frame = saved_frame;
        w.ctx = saved_ctx;
        // A lambda's creation demands what it writes of its captures, in the
        // body that creates it; a local function's, at each call, since its
        // captures are read when it runs (§18.8).
        if (!w.closures.items[ci].local) {
            w.point += 1;
            const value = try w.single(.{ .kind = .closure, .a = ci });
            try w.useCaptures(value, w.token(body));
            // §31.6: its reads of outer field paths happen here, where it is
            // made: reads of the version the creation sees.
            for (w.frames.items[id].eager.items) |cap| {
                if (cap.read_inst != none) try w.publishRead(.{ .local = cap.local, .path = cap.path, .point = w.point, .frame = w.frame, .ctx = w.ctx, .token = tok, .read_inst = cap.read_inst, .capture = creation }, none, creation, 0, none);
                if (cap.local < w.local_frame.len and w.local_frame[cap.local] == w.frame) {
                    try w.uses.append(w.a, .{ .local = cap.local, .path = cap.path, .point = w.point, .frame = w.frame, .ctx = w.ctx, .token = w.token(body), .record_read = true, .read_inst = cap.read_inst, .capture = creation });
                } else if (w.frame != 0) try w.frames.items[w.frame].eager.append(w.a, cap);
            }
            if (cls.once) try w.onceCreation(ci, w.token(body));
        }
        return w.single(.{ .kind = .closure, .a = ci });
    }

    /// §18.8: the creation of a once closure (or a call of a once local
    /// function) demands the captures it writes, in the current body; the
    /// closure is the one holder allowed to stay live.
    fn onceCreation(w: *Walker, ci: u32, tok: u32) Allocator.Error!void {
        for (w.closures.items[ci].env_writes) |cap| {
            const av = if (cap.local < w.local_frame.len and w.local_frame[cap.local] == w.frame)
                (if (w.local_av[cap.local]) |held| try w.projPath(held, cap.path, null) else continue)
            else
                try w.single(.{ .kind = .env, .a = cap.local, .path = cap.path });
            // §31.4 item 4: a record's write of the capture, at its fields.
            const p = try w.onceDemandFields(.creation, tok, if (cap.deep) try w.flat(av) else av, .{ .local = cap.local, .path = cap.path }, ci, cap.deep, cap.extent, cap.fields);
            try w.closures.items[ci].once_probes.append(w.a, p);
        }
    }

    /// §18.8: a call of a once closure is a demand on its own cell, so a
    /// second call — or a holder read after this one — fails Dead.
    fn onceCall(w: *Walker, ci: u32, f: AV, tok: u32) Allocator.Error!void {
        const cl = &w.closures.items[ci];
        // Its recursion is a second call while the first runs.
        if (w.inFrameOf(cl.frame)) {
            if (cl.once_bad == null) cl.once_bad = "it calls itself, a second call while the first runs";
            return;
        }
        var cells: std.ArrayList(Entry) = .empty;
        for (f) |e| if (e.path == eps) try cells.append(w.a, e);
        if (cells.items.len == 0) try cells.append(w.a, .{ .path = eps, .cell = try w.cell(.{ .kind = .closure, .a = ci }) });
        const p = try w.onceDemand(.probe, tok, cells.items, null, ci);
        try w.closures.items[ci].call_probes.append(w.a, p);
        if (w.closures.items[ci].local) try w.onceCreation(ci, tok);
    }

    /// Whether the walk is inside frame `f` or a frame it encloses.
    fn inFrameOf(w: *const Walker, f: u32) bool {
        var at = w.frame;
        while (at != none) : (at = w.frames.items[at].parent) {
            if (at == f) return true;
        }
        return false;
    }

    fn evalLet(w: *Walker, inst: Inst.Index) Allocator.Error!AV {
        const b = w.bir;
        const data = b.instData(inst);
        const items = b.extraSlice(b.subRange(@fromBackingInt(@intCast(data.lhs))), Inst.Index);
        // Local functions first: their closures exist from the block's
        // entry (thesis §3.6, *Local functions*), and their captures are
        // looked up when needed, so a later local is found. One named
        // before its class exists — by itself or by a sibling walked first
        // — was called out of the walk's sight (§16.5).
        var group: std.ArrayList([2]u32) = .empty;
        for (items) |item| {
            if (b.instTag(item) != .let_def) continue;
            const ld = b.extraData(@fromBackingInt(@intCast(b.instData(item).lhs)), Bir.LetDef);
            if (ld.params_start == ld.params_end) continue;
            try w.closures.append(w.a, .{ .captures = &.{}, .local = true });
            const ci: u32 = @intCast(w.closures.items.len - 1);
            try group.append(w.a, .{ ld.local, ci });
            if (ld.local < w.early.len) w.early[ld.local] = 1;
        }
        if (group.items.len > 0) try w.walkGroup(items, group.items);
        for (group.items) |g| if (g[0] < w.early.len) {
            w.early[g[0]] = 0;
        };
        for (items) |item| {
            const saved_inst = w.current_inst;
            if (w.mode == .report) w.inst_parent[item.int() - w.decl.inst_start.int()] = saved_inst;
            w.current_inst = item.int();
            defer w.current_inst = saved_inst;
            const idata = b.instData(item);
            switch (b.instTag(item)) {
                .let_def => {
                    const ld = b.extraData(@fromBackingInt(@intCast(idata.lhs)), Bir.LetDef);
                    if (ld.params_start != ld.params_end) continue;
                    const value: Inst.Index = @fromBackingInt(@intCast(idata.rhs));
                    const av = try w.eval(value);
                    try w.consume(&.{value}, w.token(item));
                    try w.bindLocal(ld.local, av);
                },
                .let_pattern => {
                    const value: Inst.Index = @fromBackingInt(@intCast(idata.rhs));
                    const av = try w.eval(value);
                    try w.consumeDestructured(value, @fromBackingInt(@intCast(idata.lhs)), w.token(item));
                    try w.bindPattern(@fromBackingInt(@intCast(idata.lhs)), av);
                },
                .let_stmt => {
                    const value: Inst.Index = @fromBackingInt(@intCast(idata.rhs));
                    _ = try w.eval(value);
                    try w.consume(&.{value}, w.token(item));
                },
                else => {},
            }
        }
        const body: Inst.Index = @fromBackingInt(@intCast(data.rhs));
        const result = try w.eval(body);
        try w.consume(&.{body}, w.token(body));
        return result;
    }

    /// §18.7: a block's local functions are one group. Their closures exist
    /// from the block's entry, each with the bottom class; when a member
    /// names a member, the group is solved like a recursive top-level group
    /// (§16.6): each round walks every member and joins what it reads off,
    /// and a round's demands and uses are discarded before the next, so the
    /// walk that validates the classes is the one that stays.
    fn walkGroup(w: *Walker, items: []const Inst.Index, group: []const [2]u32) Allocator.Error!void {
        const b = w.bir;
        const solving = w.solving_locals.items.len;
        for (group) |g| try w.solving_locals.append(w.a, g);
        defer w.solving_locals.shrinkRetainingCapacity(solving);
        var gi0: usize = 0;
        for (items) |item| {
            if (b.instTag(item) != .let_def) continue;
            const ld = b.extraData(@fromBackingInt(@intCast(b.instData(item).lhs)), Bir.LetDef);
            if (ld.params_start == ld.params_end) continue;
            const g = group[gi0];
            gi0 += 1;
            const bottom = try w.a.create(Summary);
            bottom.* = .{ .params = @intCast(b.extraSlice(.{ .start = ld.params_start, .end = ld.params_end }, Inst.Index).len) };
            w.closures.items[g[1]].class = bottom;
            try w.bindLocal(g[0], try w.single(.{ .kind = .closure, .a = g[1] }));
        }
        const snap = try w.snapshot();
        const assume = try w.a.alloc(*const Summary, group.len);
        for (group, assume) |g, *x| x.* = w.closures.items[g[1]].class.?;
        var round: u32 = 0;
        while (true) : (round += 1) {
            var gi: usize = 0;
            for (items) |item| {
                if (b.instTag(item) != .let_def) continue;
                const ld = b.extraData(@fromBackingInt(@intCast(b.instData(item).lhs)), Bir.LetDef);
                if (ld.params_start == ld.params_end) continue;
                const params = b.extraSlice(.{ .start = ld.params_start, .end = ld.params_end }, Inst.Index);
                _ = try w.closure(params, @fromBackingInt(@intCast(b.instData(item).rhs)), group[gi][1], w.token(item), w.localType(ld.local));
                gi += 1;
            }
            var named = false;
            for (group) |g| if (g[0] < w.early.len and w.early[g[0]] == 2) {
                named = true;
            };
            if (!named) return;
            var changed = false;
            for (group, assume) |g, *x| {
                const joined = try w.o.join(x.*.*, w.closures.items[g[1]].class.?.*);
                if (!summaryEql(joined, x.*.*)) changed = true;
                const p = try w.a.create(Summary);
                p.* = joined;
                x.* = p;
            }
            if (!changed) return;
            try w.restore(snap);
            for (group, assume) |g, *x| {
                if (round + 1 >= round_cap) {
                    const p = try w.a.create(Summary);
                    p.* = try w.o.pessimistic(x.*.*, .rounds, round_cap);
                    x.* = p;
                }
                w.closures.items[g[1]].class = x.*;
                if (g[0] < w.early.len) w.early[g[0]] = 1;
            }
            if (round + 1 >= round_cap) {
                // The backstop: one walk against the pessimistic classes,
                // which stay.
                gi = 0;
                for (items) |item| {
                    if (b.instTag(item) != .let_def) continue;
                    const ld = b.extraData(@fromBackingInt(@intCast(b.instData(item).lhs)), Bir.LetDef);
                    if (ld.params_start == ld.params_end) continue;
                    const params = b.extraSlice(.{ .start = ld.params_start, .end = ld.params_end }, Inst.Index);
                    _ = try w.closure(params, @fromBackingInt(@intCast(b.instData(item).rhs)), group[gi][1], w.token(item), w.localType(ld.local));
                    gi += 1;
                }
                for (group, assume) |g, x| w.closures.items[g[1]].class = x;
                return;
            }
        }
    }

    const Snapshot = struct {
        demands: usize,
        uses: usize,
        escaped: usize,
        supplies: usize,
        probes: usize,
        reqs: usize,
        rreqs: usize,
        env_calls: usize,
        env_passes: usize,
        lambda_needs: []const LambdaNeed,
        frames: usize,
        closures: usize,
        conds: usize,
        rconds: usize,
        captures: []const usize,
        consumed: []const usize,
        once_probes: []const [2]usize,
        once_bad: []const ?[]const u8,
        /// A carried closure's captures grow in place (§20.4).
        carried: []const Closure,
        carry_sites: std.AutoHashMapUnmanaged(CarrySite, u32),
        fn_state: []const FnState,
        unseen: std.AutoHashMapUnmanaged(u64, void),
        cell_cond: []const u32,
        cell_rcond: []const u32,
        cell_spine: []const u32,
        esc_index: std.AutoHashMapUnmanaged([4]u32, EscAt),
        esc_heads: std.AutoHashMapUnmanaged([4]u32, u32),
        local_av: []const ?AV,
        local_frame: []const u32,
        local_ctx: []const u32,
    };

    fn snapshot(w: *Walker) Allocator.Error!Snapshot {
        const n = w.closures.items.len;
        const consumed = try w.a.alloc(usize, n);
        const once_probes = try w.a.alloc([2]usize, n);
        const once_bad = try w.a.alloc(?[]const u8, n);
        const kept_binds = try w.a.alloc(Closure, n);
        for (w.closures.items, consumed, once_probes, once_bad, kept_binds) |c, *x, *y, *z, *v| {
            x.* = c.consumed.items.len;
            y.* = .{ c.once_probes.items.len, c.call_probes.items.len };
            z.* = c.once_bad;
            v.* = .{ .captures = &.{}, .binds = c.binds, .cb_avs = c.cb_avs };
        }
        const captures = try w.a.alloc(usize, w.frames.items.len);
        for (w.frames.items, captures) |f, *x| x.* = f.captures.items.len;
        return .{
            .demands = w.demands.items.len,
            .uses = w.uses.items.len,
            .escaped = w.escaped.items.len,
            .supplies = w.supplies.items.len,
            .probes = w.probe_ok.items.len,
            .reqs = w.reqs.items.len,
            .rreqs = w.rreqs.items.len,
            .env_calls = w.env_calls.items.len,
            .env_passes = w.env_passes.items.len,
            .lambda_needs = try w.a.dupe(LambdaNeed, w.lambda_needs.items),
            .frames = w.frames.items.len,
            .closures = n,
            .conds = w.conds.items.len,
            .rconds = w.rconds.items.len,
            .captures = captures,
            .consumed = consumed,
            .once_probes = once_probes,
            .once_bad = once_bad,
            .carried = kept_binds,
            .carry_sites = try w.carry_sites.clone(w.a),
            .fn_state = try w.a.dupe(FnState, w.fn_state.items),
            .unseen = try w.unseen_funcs.clone(w.a),
            .cell_cond = try w.a.dupe(u32, w.cell_cond.items),
            .cell_rcond = try w.a.dupe(u32, w.cell_rcond.items),
            .cell_spine = try w.a.dupe(u32, w.cell_spine.items),
            .esc_index = try w.esc_index.clone(w.a),
            .esc_heads = try w.esc_heads.clone(w.a),
            .local_av = try w.a.dupe(?AV, w.local_av),
            .local_frame = try w.a.dupe(u32, w.local_frame),
            .local_ctx = try w.a.dupe(u32, w.local_ctx),
        };
    }

    fn restore(w: *Walker, s: Snapshot) Allocator.Error!void {
        w.other_writes += 1;
        w.demands.shrinkRetainingCapacity(s.demands);
        w.uses.shrinkRetainingCapacity(s.uses);
        w.escaped.shrinkRetainingCapacity(s.escaped);
        w.supplies.shrinkRetainingCapacity(s.supplies);
        w.probe_ok.shrinkRetainingCapacity(s.probes);
        w.probe_record.shrinkRetainingCapacity(s.probes);
        w.probe_approx.shrinkRetainingCapacity(s.probes);
        w.probe_info.shrinkRetainingCapacity(s.probes);
        w.reqs.shrinkRetainingCapacity(s.reqs);
        w.rreqs.shrinkRetainingCapacity(s.rreqs);
        w.env_calls.shrinkRetainingCapacity(s.env_calls);
        w.env_passes.shrinkRetainingCapacity(s.env_passes);
        w.lambda_needs.shrinkRetainingCapacity(s.lambda_needs.len);
        @memcpy(w.lambda_needs.items, s.lambda_needs);
        w.frames.shrinkRetainingCapacity(s.frames);
        w.closures.shrinkRetainingCapacity(s.closures);
        w.conds.shrinkRetainingCapacity(s.conds);
        w.cond_map.clearRetainingCapacity();
        w.rconds.shrinkRetainingCapacity(s.rconds);
        for (w.frames.items, s.captures) |*f, n| f.captures.shrinkRetainingCapacity(n);
        for (w.closures.items, s.consumed, s.once_probes, s.once_bad, s.carried) |*c, x, y, z, v| {
            c.consumed.shrinkRetainingCapacity(x);
            c.once_probes.shrinkRetainingCapacity(y[0]);
            c.call_probes.shrinkRetainingCapacity(y[1]);
            c.once_bad = z;
            c.binds = v.binds;
            c.cb_avs = v.cb_avs;
        }
        // `carry_grew` is not restored: fixpoints compare it only before
        // and after a round, so growth a restore undoes costs at most one
        // more round, never an answer.
        w.carry_sites = try s.carry_sites.clone(w.a);
        w.fn_state.shrinkRetainingCapacity(s.fn_state.len);
        w.slot_keys.shrinkRetainingCapacity(s.fn_state.len - w.params.len);
        @memcpy(w.fn_state.items, s.fn_state);
        w.unseen_funcs = try s.unseen.clone(w.a);
        @memcpy(w.cell_cond.items[0..s.cell_cond.len], s.cell_cond);
        @memset(w.cell_cond.items[s.cell_cond.len..], none);
        @memcpy(w.cell_rcond.items[0..s.cell_rcond.len], s.cell_rcond);
        @memset(w.cell_rcond.items[s.cell_rcond.len..], none);
        @memcpy(w.cell_spine.items[0..s.cell_spine.len], s.cell_spine);
        @memset(w.cell_spine.items[s.cell_spine.len..], none);
        w.esc_index = try s.esc_index.clone(w.a);
        w.esc_heads = try s.esc_heads.clone(w.a);
        @memcpy(w.local_av, s.local_av);
        @memcpy(w.local_frame, s.local_frame);
        @memcpy(w.local_ctx, s.local_ctx);
    }

    fn evalCase(w: *Walker, inst: Inst.Index) Allocator.Error!AV {
        const b = w.bir;
        const data = b.instData(inst);
        const scrutinee: Inst.Index = @fromBackingInt(@intCast(data.lhs));
        const s = try w.eval(scrutinee);
        const branches = b.extraSlice(b.subRange(@fromBackingInt(@intCast(data.rhs))), Inst.Index);
        // One arm of a record pattern reads the scrutinee field by field.
        const one_pattern: ?Inst.Index = if (branches.len == 1) @fromBackingInt(@intCast(b.instData(branches[0]).lhs)) else null;
        if (one_pattern) |p| try w.consumeDestructured(scrutinee, p, w.token(inst)) else try w.consume(&.{scrutinee}, w.token(inst));
        const case_id = w.cases;
        w.cases += 1;
        const saved = w.ctx;
        var results: std.ArrayList(AV) = .empty;
        // The locals each arm binds are out of sight of the arms after it,
        // and back in sight after the case (`bound_log`).
        const log_mark = w.bound_log.items.len;
        var parked: std.ArrayList(u32) = .empty;
        for (branches, 0..) |br, arm| {
            const node: u32 = @intCast(w.ctx_nodes.items.len);
            try w.ctx_nodes.append(w.a, .{ .parent = saved, .case_id = case_id, .arm = @intCast(arm), .depth = w.ctx_nodes.items[saved].depth + 1 });
            w.ctx = node;
            try w.bindPattern(@fromBackingInt(@intCast(b.instData(br).lhs)), s);
            const body: Inst.Index = @fromBackingInt(@intCast(b.instData(br).rhs));
            try results.append(w.a, try w.eval(body));
            try w.consume(&.{body}, w.token(body));
            if (w.logs_bindings) try parked.appendSlice(w.a, w.bound_log.items[@min(log_mark, w.bound_log.items.len)..]);
            if (w.logs_bindings) w.bound_log.shrinkRetainingCapacity(@min(log_mark, w.bound_log.items.len));
        }
        if (w.logs_bindings) try w.bound_log.appendSlice(w.a, parked.items);
        if (w.case_end.items.len <= case_id) try w.case_end.appendNTimes(w.a, none, case_id + 1 - w.case_end.items.len);
        w.case_end.items[case_id] = @intCast(w.uses.items.len);
        w.ctx = saved;
        return w.unionOf(results.items);
    }

    // ---- calls (§6, §16.4) -----------------------------------------------

    fn evalCall(w: *Walker, inst: Inst.Index) Allocator.Error!AV {
        const b = w.bir;
        const data = b.instData(inst);
        const callee: Inst.Index = @fromBackingInt(@intCast(data.lhs));
        const args = w.callArgs(inst);
        if (w.isSpreadCall(inst)) return w.construction(inst);
        if (w.isListAppend(inst)) return w.appendChain(inst);
        switch (b.instTag(callee)) {
            // A tagged schema's constructor builds its value as any
            // constructor does (§30.11).
            .ctor, .ext_ctor, .schema_ctor_top, .ext_schema_ctor => {
                const c = try w.ctorOf(callee);
                const avs = try w.evalOperands(args, false);
                w.popPending(avs.len);
                try w.consume(args, w.token(inst));
                var parts = try w.a.alloc(AV, avs.len + 1);
                parts[avs.len] = try w.containingCondition(inst, avs);
                for (avs, 0..) |av, i| parts[i] = try w.shift(av, .{ .kind = .ctor, .arg = try w.o.ctorStep(c, @intCast(i)) });
                try w.storedBeside(parts);
                const out = try w.spineValue(inst, parts);
                try w.sight(out, .{ .pending = "it is stored in a constructor" }, w.token(inst));
                return out;
            },
            else => {},
        }
        // §30.10: a member of a schema declaration's namespace.
        if (w.schemaMemberOf(callee)) |sm| if (try w.o.schemaMemberRow(sm.m, sm.decl, sm.kind, @intCast(args.len))) |s| {
            const name = try std.fmt.allocPrint(w.o.out.allocator(), "{s}.{s}.{s}", .{ w.o.in.module_names[sm.m], w.o.in.interner.slice(w.o.in.birs[sm.m].symbol(w.o.in.birs[sm.m].decls[sm.decl].name)), @tagName(sm.kind) });
            const out = try w.applySummary(inst, .{ .sum = s, .name = name, .op = if (w.mode == .report) try std.fmt.allocPrint(w.o.out.allocator(), "call {s}", .{name}) else "call" }, args, &.{}, null);
            return if (sm.kind == .parse or sm.kind == .parse_with) w.settleRun(out) else out;
        };
        if (w.valueTarget(callee)) |t| {
            try w.evidenceSight(callee);
            try w.evidenceSight(inst);
            if (args.len == 1 and try w.hasEntry(t, 0)) return w.entryCall(inst, t, args[0]);
            // §30.11: a top-level value with no parameters that names no
            // function (§30.9 rule 9) is called as the function value it
            // is: the class its definition carries (§30.9 rule 8), else
            // §6.1's call (`mkBox = Box`, `parser = Sentence.parse`).
            const decl = w.o.in.birs[t.m].decls[t.d];
            if (decl.kind == .value and decl.params == 0 and (try w.aliasTarget(t)) == null) {
                return w.callValue(inst, args, try w.eval(callee), .{ .inst = callee });
            }
            return w.callTarget(inst, t, args);
        }
        // A function value: its classes, when the walk knows where it came
        // from (§16.5); else a conservative call that reads its captures.
        const f = try w.eval(callee);
        return w.callValue(inst, args, f, .{ .inst = callee });
    }

    /// A call of the function value `f`, which `callee` evaluated: a
    /// function parameter or slot of the declaration, a value whose class
    /// the walk knows, or §6.1's call of a function it cannot identify.
    fn callValue(w: *Walker, inst: Inst.Index, args: []const Inst.Index, f: AV, callee: CalleeRef) Allocator.Error!AV {
        try w.pushPending(f, callee.inst, true);
        defer w.popPending(1);
        // A call of a function parameter of the declaration (§16.4 item 4).
        if (w.fnParamOf(f)) |j| {
            if (w.frame == 0) return w.callbackCall(inst, j, args, callee);
            // Inside a lambda: a call made wherever the lambda runs (§18.9).
            if (w.frameClosure(w.frame)) |ci| return w.envCall(inst, ci, j, args, callee);
            w.fn_state.items[j].seen = false;
        }
        // A function stored at a path of a parameter (§24.9): a slot, called
        // in a lambda wherever the lambda runs, as a parameter is (§30.9).
        if (try w.slotOf(f)) |j| {
            if (w.frame == 0) return w.callbackCall(inst, j, args, callee);
            if (w.frameClosure(w.frame)) |ci| return w.envCall(inst, ci, j, args, callee);
            w.fn_state.items[j].seen = false;
        }
        // A lambda's own function parameter. Its result stays symbolic in
        // this body and is followed through the consumer's supplies.
        if (f.len == 1 and f[0].path == eps) {
            const c = w.cells.items[f[0].cell];
            if (c.kind == .param and c.b == 1 and c.path == eps and !w.isSend(c)) if (w.lambdaParam(c)) |lp| {
                if (w.closures.items[lp[0]].frame == w.frame) return w.lambdaCallbackCall(inst, lp[1], args, callee);
            };
        }
        const classes = try w.classesOf(f);
        if (classes.len == 1) {
            switch (classes[0]) {
                .closure => |ci| if (w.closures.items[ci].class) |cls| {
                    try w.closures.items[ci].consumed.append(w.a, .{ .kind = .local });
                    try w.escapeCaptures(ci, w.point);
                    const out = try w.applySummary(inst, .{ .sum = cls, .name = "<lambda>", .op = "call <lambda>", .closure = ci, .poly = try w.localParamTypes(ci) }, args, f, callee);
                    if (cls.once) try w.onceCall(ci, f, w.token(inst));
                    return out;
                },
                .func => |t| if (try w.o.ensureSummary(t.m, t.d)) |s| {
                    return w.applySummary(inst, .{ .entry_target = t, .sum = s, .name = try w.qualified(t), .op = try w.callOp(t), .merge_fresh = w.o.isComputing(t.m, t.d), .poly = try w.memberParamTypes(t) }, args, f, callee);
                },
                // §23.2: a send gives up every cell of its payload.
                .send => return w.applySummary(inst, .{ .sum = &send_class, .name = "send", .op = "send" }, args, f, callee),
            }
        }
        try w.sight(f, .{ .pending = "it is called where the checker does not know which function runs" }, w.token(inst));
        // Two or more classes the walk knows are not joined (issue #278):
        // the call is §6.1's, named for that.
        return w.conservative(inst, args, f, callee, "", false, if (classes.len > 1) .several else .unknown);
    }

    /// A private binding's only read, executed once during module init
    /// (ownership-checker.md, initialization-transfer amendment).
    fn initializationTransfer(w: *Walker, t: Target, s: *const Summary) Allocator.Error!bool {
        if (t.m != w.m or w.o.in.packages[w.m] != .app or w.recursive or w.frame != 0 or
            w.decl.params != 0 or w.decl.kind != .value or
            s.limit != .none) return false;
        if (w.m >= w.o.private_reads.len or t.d >= w.bir.decls.len) return false;
        const dispatch = &w.o.in.dispatch[w.m];
        // Evidence-polymorphic values run at their uses, not once at load.
        for ([_]u32{ w.decl_index, t.d }) |di| {
            if (dispatch.declIdentities(di).len != 0 or dispatch.declRequirements(di).len != 0) return false;
        }
        const source = w.bir.decls[t.d];
        if (source.is_pub or source.params != 0 or source.kind != .value) return false;
        for (s.res) |r| switch (r.prov.kind) {
            .fresh, .esc, .shared, .klass => {},
            else => return false,
        };
        for (s.objs) |r| switch (r.prov.kind) {
            .fresh, .esc, .shared, .klass => {},
            else => return false,
        };
        if (w.o.private_reads[w.m] == null) {
            const counts = try w.o.keep.allocator().alloc(u8, w.bir.decls.len);
            @memset(counts, 0);
            for (w.bir.insts.items(.tag), w.bir.insts.items(.data)) |tag, data| {
                if (tag == .top and data.lhs < counts.len) counts[data.lhs] = @min(counts[data.lhs] + 1, 2);
            }
            w.o.private_reads[w.m] = counts;
        }
        const counts = w.o.private_reads[w.m].?;
        return t.d < counts.len and counts[t.d] == 1;
    }

    /// A top-level value's cells, from its definition's summary: each cell
    /// it makes is shared at the path it makes it at (thesis §3.10).
    fn sharedOf(w: *Walker, s: *const Summary, t: Target, inst: Inst.Index) Allocator.Error!AV {
        var out: std.ArrayList(Entry) = .empty;
        for (s.res) |r| {
            // A lambda the value holds (§24.9), when it captured nothing: a
            // capture the definition made would be a shared cell, which a
            // carried binding cannot say. Dropped otherwise: a call of the
            // value then finds no class and is §6.1's, as it was before.
            if (r.prov.kind == .klass) {
                if (r.prov.a == none) {
                    try out.appendSlice(w.a, try w.under(try w.carry(r.prov, .{ .inst = inst, .s = s, .avs = &.{}, .depth = 0 }), r.path));
                    continue;
                }
                // A capture that holds no cell (a number) is no capture.
                const holds_nothing = r.prov.a < s.klasses.len and for (s.klasses[r.prov.a].binds) |b| {
                    if (b.provs.len != 0) break false;
                } else true;
                if (holds_nothing and s.klasses[r.prov.a].cb_js.len == 0) {
                    const av = try w.carry(r.prov, .{ .inst = inst, .s = s, .avs = &.{}, .depth = 0 });
                    try out.appendSlice(w.a, try w.under(av, r.path));
                }
                continue;
            }
            var c: Cell = switch (r.prov.kind) {
                .fresh, .esc => .{ .kind = .shared, .a = t.m, .b = t.d, .path = r.path, .made = true, .ty = if (r.path == eps) w.instTypeOpt(inst) else .none },
                .shared => .{ .kind = .shared, .a = r.prov.a, .b = r.prov.b, .path = r.prov.path },
                else => .{ .kind = .top, .a = if (s.limit != .none or r.prov.a == 1) 1 else if (r.prov.kind == .top) r.prov.a else 0 },
            };
            c.condition_only = r.prov.condition_only;
            const cell_id = try w.cell(c);
            if (r.prov.condition_only) {
                const ctx: InstCtx = .{ .inst = inst, .s = s, .avs = &.{}, .depth = 0 };
                try w.initCond(cell_id, try w.instXSum(r.xc, ctx));
                try w.rinitCond(cell_id, try w.rinstXSum(r.rxc, ctx));
                const annotated = try w.annotationSpines(&.{.{ .path = eps, .cell = cell_id }}, r.sc, ctx, r.grown, null, null);
                for (try w.under(annotated, r.path)) |e| try out.append(w.a, .{ .path = e.path, .cell = e.cell, .approx = if (r.approx) inst.int() + 1 else e.approx });
            } else {
                try out.append(w.a, .{ .path = r.path, .cell = cell_id, .approx = if (r.approx) inst.int() + 1 else 0 });
            }
        }
        // §31.7: the records it holds, as cells no list's fact reads: what
        // the definition made is shared, what another top-level value holds
        // is that value's.
        for (s.objs) |r| {
            const c: Cell = switch (r.prov.kind) {
                .fresh, .esc => .{ .kind = .shared, .a = t.m, .b = t.d, .path = r.path, .made = true, .nonlist = true },
                .shared => .{ .kind = .shared, .a = r.prov.a, .b = r.prov.b, .path = r.prov.path, .made = true, .nonlist = true },
                else => .{ .kind = .top, .a = if (s.limit != .none or r.prov.a == 1) 1 else if (r.prov.kind == .top) r.prov.a else 0, .nonlist = true },
            };
            try out.append(w.a, .{ .path = r.path, .cell = try w.cell(c), .approx = if (r.approx) inst.int() + 1 else 0 });
        }
        // §31.2: a top-level record's object, the record demand's, a list's
        // nothing (§31.4 item 2).
        if (w.isRecordType(w.instType(inst))) {
            try out.append(w.a, .{ .path = eps, .cell = try w.cell(.{ .kind = .shared, .a = t.m, .b = t.d, .made = true, .nonlist = true, .ty = w.instTypeOpt(inst) }) });
        }
        return w.norm(out.items);
    }

    /// Whether `ty` is a record type, closed or open.
    fn isRecordType(w: *Walker, ty: ?Var) bool {
        const v = ty orelse return false;
        return switch (w.store.resolvedContent(v)) {
            .structure => |s| s == .record,
            else => false,
        };
    }

    /// §30.10: a run's answer, settled. Where the slot it read held
    /// `input_marker`, the input its row set aside (`inputPath`) may be
    /// anywhere in it; elsewhere the input is not in it. The marks go.
    fn settleRun(w: *Walker, out: AV) Allocator.Error!AV {
        const any = try w.o.child(eps, .any, 0);
        var marked = false;
        for (out) |e| {
            const c = w.cells.items[e.cell];
            if (c.kind == .top and c.a == 2) marked = true;
        }
        var kept: std.ArrayList(Entry) = .empty;
        for (out) |e| {
            const c = w.cells.items[e.cell];
            if (c.kind == .top and c.a == 2) continue;
            if (w.o.firstStep(e.path)) |st| if (st.kind == .schema_encoded) {
                if (marked) try kept.append(w.a, .{ .path = any, .cell = e.cell, .approx = e.approx, .grown = e.grown });
                continue;
            };
            try kept.append(w.a, e);
        }
        return w.norm(kept.items);
    }

    /// §30.10: the summary of a call of a function of core's whose schema is
    /// its `where a.codec` evidence — `Json.decode`, `decodeWith`,
    /// `decodeValue`, `encodeValue`, `Schema.derived`, `structural` — at
    /// this call, where the evidence is known: a run answers what it builds
    /// and what the codec's slot of its direction holds (`codecTaint`), and
    /// `derived` makes a schema whose slots hold that. Null for any other
    /// callee, whose summary is its own.
    fn codecRunRow(w: *Walker, inst: Inst.Index, t: Target, arity: usize) Allocator.Error!?*const Summary {
        const name = w.targetName(t);
        const Kind = enum { decode, decode_value, encode_value, schema };
        const kind: Kind = if (w.isCore(t, "Json")) blk: {
            if (eqlAny(name, &.{ "decode", "decodeWith" })) break :blk .decode;
            if (std.mem.eql(u8, name, "decodeValue")) break :blk .decode_value;
            if (std.mem.eql(u8, name, "encodeValue")) break :blk .encode_value;
            return null;
        } else if (w.isCore(t, "Schema") and eqlAny(name, &.{ "derived", "structural" })) .schema else return null;
        const taint = try w.codecTaint(inst);
        const o = w.o;
        const keep = o.keep.allocator();
        const slots = [_]u32{ try o.child(eps, .schema_decoded, 0), try o.child(eps, .schema_encoded, 0) };
        var uses: std.ArrayList(UseEntry) = .empty;
        var res: std.ArrayList(ResEntry) = .empty;
        try res.append(keep, .{ .path = eps, .prov = .{ .kind = .fresh, .a = 1 }, .xc = .{ .no = 1 } });
        for (0..arity) |i| try uses.append(keep, .{ .param = @intCast(i), .path = eps, .bits = bit_r });
        switch (kind) {
            .schema => {
                for (taint.decoded) |p| try res.append(keep, .{ .path = slots[0], .prov = p });
                for (taint.encoded) |p| try res.append(keep, .{ .path = slots[1], .prov = p });
            },
            .decode => for (taint.decoded) |p| try o.anywhereIn(&res, p),
            .decode_value, .encode_value => {
                for (if (kind == .decode_value) taint.decoded else taint.encoded) |p| try o.anywhereIn(&res, p);
                const input: u32 = @intCast(arity - 1);
                uses.items[input].bits |= bit_a;
                try o.inputAside(&res, input);
            },
        }
        // A decoder's records are its own (#420, §31.4 item 6): the
        // specialised read builds a new object for every record it answers,
        // so a decoded value holds no record at two places unless its
        // codec's slot answers values the program made (a conversion's,
        // `taint.decoded`). A `Value` position holds the host's value, in
        // which no record a program can write is reached.
        if ((kind == .decode or kind == .decode_value) and taint.decoded.len == 0) res.items[0].rxc = .{};
        const s = try w.a.create(Summary);
        s.* = try o.normalize(.{ .params = @intCast(arity), .uses = uses.items, .res = res.items, .asserted = true });
        return s;
    }

    /// The slots of the schema a call's `a.codec` evidence answers: a
    /// derived codec's (`schemaTaint` of its definition, with each of its
    /// slots' evidence), or a type's module's `codec`'s, which its summary
    /// names. `⊤` for an evidence parameter or anything else.
    fn codecTaint(w: *Walker, inst: Inst.Index) Allocator.Error!SchemaTaint {
        if (w.m >= w.o.in.dispatch.len) return top_taint;
        const dt = &w.o.in.dispatch[w.m];
        const callee: Inst.Index = @fromBackingInt(@intCast(w.bir.instData(inst).lhs));
        const site = dt.siteOf(callee) orelse dt.siteOf(inst) orelse return top_taint;
        const roots = dt.argsAt(site.evidence);
        if (roots.len != 1) return top_taint;
        return w.termTaint(dt, roots[0], 0);
    }

    fn termTaint(w: *Walker, dt: *const Dispatch, ti: Dispatch.TermIndex, depth: u32) Allocator.Error!SchemaTaint {
        if (depth > 8) return top_taint;
        const o = w.o;
        switch (dt.term(ti)) {
            .codec => |u| {
                var t = try o.schemaTaint(w.m, @intCast(w.bir.decls.len + u.index));
                for (dt.argsAt(u.args)) |a| {
                    const x = try w.termTaint(dt, a, depth + 1);
                    t = .{
                        .decoded = try std.mem.concat(o.keep.allocator(), Prov, &.{ t.decoded, x.decoded }),
                        .encoded = try std.mem.concat(o.keep.allocator(), Prov, &.{ t.encoded, x.encoded }),
                    };
                }
                return t;
            },
            .top, .ext => {
                const target = w.termTarget(dt.term(ti)) orelse return top_taint;
                const s = (try o.ensureSummary(target.m, target.d)) orelse return top_taint;
                return o.slotProvs(s, .{ target.m, target.d }, false);
            },
            else => return top_taint,
        }
    }

    /// §30.10: the slots of the conversion `Schema.conversion forward
    /// backward` made at `inst`, whose value `made` holds the two functions
    /// at `.there` and `.back` (`core/Schema`'s `Pair`). Decoding hands
    /// `forward` a value built from the input and answers what it returns;
    /// encoding hands `backward` the program's value. So `⟨decoded⟩` holds
    /// what `forward` may return that is neither built by its call nor its
    /// argument, and `⟨encoded⟩` the same of `backward` — nothing at all
    /// when the end it returns, `a` or `b`, holds no list.
    fn conversionSlots(w: *Walker, inst: Inst.Index, made: AV) Allocator.Error!AV {
        var ends: [2]?Var = .{ null, null };
        if (w.instType(inst)) |v| switch (w.store.resolvedContent(v)) {
            .structure => |st| switch (st) {
                .app => |app| {
                    const xs = w.store.vars(app.args);
                    if (xs.len == 2) ends = .{ xs[1], xs[0] };
                },
                else => {},
            },
            else => {},
        };
        // The engine-owned Pair representation (§30.10), read at its full
        // type before asking which function each field holds.
        const pair_view = try w.readCast(made, try w.castRecord(&.{ .{ .name = "back", .key = try w.o.castId("1:Js::Value()") }, .{ .name = "there", .key = try w.o.castId("1:Js::Value()") } }, try w.o.castId("{}")));
        const fields = [_][]const u8{ "there", "back" };
        const kinds = [_]StepKind{ .schema_decoded, .schema_encoded };
        var parts: [2]AV = .{ &.{}, &.{} };
        for (fields, kinds, ends, &parts) |field, kind, end, *part| {
            if (end) |v| if (!try w.trackedVar(v)) continue;
            const answer = if (w.o.in.interner.find(field)) |sym|
                try w.functionAnswer(try w.proj(pair_view, .{ .kind = .field, .arg = @backingInt(sym) }, null), inst, kind == .schema_encoded, ends[1], ends[0])
            else
                try w.single(.{ .kind = .top, .a = unfollowed });
            part.* = try w.under(answer, try w.o.child(eps, kind, 0));
        }
        return w.unionOf(&parts);
    }

    /// §30.10: what a call of the function value `f` may return that
    /// outlives the call: not a cell the call makes, not its argument or a
    /// part of it, but what it captured, a top-level value, or anything
    /// from where the checker cannot see. `⊤` when `f`'s classes are not
    /// known. `source` is the type `forward` is handed and `target` the one
    /// it converts to (`returnsOneCellTwice`).
    fn functionAnswer(w: *Walker, f: AV, inst: Inst.Index, argument_is_input: bool, source: ?Var, target: ?Var) Allocator.Error!AV {
        const classes = try w.classesOf(f);
        if (classes.len == 0) return w.single(.{ .kind = .top, .a = unfollowed });
        var out: std.ArrayList(Entry) = .empty;
        for (classes) |cls| {
            const s = (try w.classSummary(cls)) orelse return w.single(.{ .kind = .top, .a = unfollowed });
            const ci: u32 = if (cls == .closure) cls.closure else none;
            // `forward`'s argument is what the run built, no holder, and a
            // list it makes is new — but either, returned at two places,
            // puts one list at two positions of the answer (#268).
            if (!argument_is_input and try w.o.returnsOneCellTwice(w.store, s, source, target)) try out.appendSlice(w.a, try w.single(.{ .kind = .top, .a = twice_named }));
            for (s.res) |r| switch (r.prov.kind) {
                .fresh => {},
                // `backward` is handed the program's value: what it returns of
                // it is the run's input (`input_marker`). `forward` is handed
                // what the run built.
                .param => if (argument_is_input) try out.appendSlice(w.a, try w.single(.{ .kind = .top, .a = 2 })),
                .esc => try out.appendSlice(w.a, try w.single(.{ .kind = .top, .a = unfollowed })),
                .env => if (ci == none)
                    try out.appendSlice(w.a, try w.single(.{ .kind = .top, .a = unfollowed }))
                else
                    try out.appendSlice(w.a, try w.instProv(r.prov, .{ .inst = inst, .s = s, .avs = &.{}, .closure = ci, .depth = 1, .effects = false })),
                .shared, .top => try out.appendSlice(w.a, try w.instProv(r.prov, .{ .inst = inst, .s = s, .avs = &.{}, .depth = 1, .effects = false })),
                .cb, .klass => try out.appendSlice(w.a, try w.single(.{ .kind = .top, .a = unfollowed })),
            };
        }
        return w.norm(out.items);
    }

    fn callOp(w: *Walker, t: Target) Allocator.Error![]const u8 {
        if (w.writerName(t)) |n| return if (w.mode == .report) std.fmt.allocPrint(w.o.out.allocator(), "List.{s}", .{n}) else "List.";
        if (w.mode != .report) return "call";
        return std.fmt.allocPrint(w.o.out.allocator(), "call {s}", .{try w.qualified(t)});
    }

    /// A call of a top-level value (§16.4), or §6.1 when it has no summary.
    fn callTarget(w: *Walker, inst: Inst.Index, t: Target, args: []const Inst.Index) Allocator.Error!AV {
        if (w.o.callable_aliases.get((@as(u64, t.m) << 32) | t.d)) |sum| return w.applyTargetSummary(inst, t, args, sum);
        const d = w.o.in.birs[t.m].decls[t.d];
        if (d.params > 0 and d.kind != .vocab_markup and !w.isCore(t, "Js") and !w.isCore(t, "Schema") and !w.isCore(t, "Json")) {
            if (try w.o.ensureSummary(t.m, t.d)) |sum| return w.applyTargetSummary(inst, t, args, sum);
            if (w.escapes(t)) return w.escapeCall(inst, args, try w.qualified(t));
            return w.conservative(inst, args, &.{}, null, try w.qualified(t), d.kind == .foreign_value, .unknown);
        }
        return w.callSpecialTarget(inst, t, args);
    }

    fn applyTargetSummary(w: *Walker, inst: Inst.Index, t: Target, args: []const Inst.Index, s: *const Summary) Allocator.Error!AV {
        const saved = w.maybe_join;
        defer w.maybe_join = saved;
        if (try w.isMaybeJoin(t, args)) w.maybe_join = try w.openMaybeJoin(inst);
        return w.applySummary(inst, .{ .entry_target = t, .sum = s, .name = try w.qualified(t), .op = try w.callOp(t), .merge_fresh = w.o.isComputing(t.m, t.d), .poly = try w.memberParamTypes(t) }, args, &.{}, null);
    }

    fn callSpecialTarget(w: *Walker, inst: Inst.Index, t: Target, args: []const Inst.Index) Allocator.Error!AV {
        // A top-level value whose value is a function has no parameters to
        // apply a summary to: its call is §6.1's.
        if (w.o.in.birs[t.m].decls[t.d].kind == .vocab_markup) {
            const name = w.targetName(t);
            if (std.mem.eql(u8, name, "text") and args.len == 1) {
                const retained = try w.conservative(inst, args, &.{}, null, "", false, .made);
                return w.shift(retained, .{ .kind = .markup_render, .arg = 0 });
            }
            if (std.mem.eql(u8, name, "map") and args.len == 2) {
                const avs = try w.evalOperands(args, true);
                w.popPending(avs.len);
                const retained = try w.conservativeAV(inst, args, avs, &.{}, null, "", false, .made);
                const child_events = try w.markupEvents(avs[0], w.instType(args[0]), inst, 0);
                const mapper = avs[1];
                const mapped = try w.markupCallback(inst, args[1], mapper, &.{child_events});
                const events = try w.anywhere(try w.unionOf(&.{ child_events, mapped, try w.markupHeld(mapper, inst) }), inst);
                return w.unionOf(&.{ try w.shift(retained, .{ .kind = .markup_render, .arg = 0 }), try w.shift(events, .{ .kind = .markup_event, .arg = 0 }) });
            }
        }
        // §30.9: a top-level value that names another (`list = Pcg.list`)
        // is called as the function it names.
        if (w.o.in.birs[t.m].decls[t.d].params == 0) if (try w.aliasTarget(t)) |named| {
            if (w.o.callable_aliases.contains((@as(u64, named.m) << 32) | named.d) or w.o.in.birs[named.m].decls[named.d].params == args.len) return w.callTarget(inst, named, args);
        };
        const has_params = w.o.in.birs[t.m].decls[t.d].params > 0;
        // `Js.maySuspend f` reads the static bit the checker inferred for
        // `f` and nothing of its value: no use, and `f` stays in sight
        // (§23.3), so `Cmd.perform`'s body keeps its send position.
        if (w.isCore(t, "Js") and std.mem.eql(u8, w.targetName(t), "maySuspend")) {
            const avs = try w.evalOperands(args, false);
            w.popPending(avs.len);
            return &.{};
        }
        // §30.10: a run of a derived codec, or the codec itself, whose
        // schema is the call's evidence.
        if (has_params) if (try w.codecRunRow(inst, t, args.len)) |s| {
            const out = try w.applySummary(inst, .{ .sum = s, .name = try w.qualified(t), .op = try w.callOp(t) }, args, &.{}, null);
            return if (w.isCore(t, "Json")) w.settleRun(out) else out;
        };
        // §30.10: a run's answer holds its input only where its schema's
        // slot says so.
        if (has_params and w.isCore(t, "Schema") and eqlAny(w.targetName(t), &schema_runs)) if (try w.o.ensureSummary(t.m, t.d)) |s| {
            return w.settleRun(try w.applySummary(inst, .{ .sum = s, .name = try w.qualified(t), .op = try w.callOp(t) }, args, &.{}, null));
        };
        // §30.10: a conversion's slots hold what its functions answer.
        if (has_params and args.len == 2 and w.isCore(t, "Schema") and std.mem.eql(u8, w.targetName(t), "conversion")) {
            if (try w.o.ensureSummary(t.m, t.d)) |s| {
                const made = try w.applySummary(inst, .{ .sum = s, .name = try w.qualified(t), .op = try w.callOp(t) }, args, &.{}, null);
                return w.unionOf(&.{ made, try w.conversionSlots(inst, made) });
            }
        }
        if (if (has_params) try w.o.ensureSummary(t.m, t.d) else null) |s| {
            const saved = w.maybe_join;
            defer w.maybe_join = saved;
            if (try w.isMaybeJoin(t, args)) w.maybe_join = try w.openMaybeJoin(inst);
            return w.applySummary(inst, .{ .entry_target = t, .sum = s, .name = try w.qualified(t), .op = try w.callOp(t), .merge_fresh = w.o.isComputing(t.m, t.d), .poly = try w.memberParamTypes(t) }, args, &.{}, null);
        }
        if (w.escapes(t)) return w.escapeCall(inst, args, try w.qualified(t));
        return w.conservative(inst, args, &.{}, null, try w.qualified(t), w.o.in.birs[t.m].decls[t.d].kind == .foreign_value, .unknown);
    }

    /// §7.2 as amended for slice 3f: `Maybe.withDefault (Maybe.map m f) d`,
    /// both core's, where `m` and `d` are variable paths and `f` a lambda or
    /// a top-level value. `Maybe.map` calls `f` exactly when `m` is `Just`,
    /// and `withDefault` returns `d` exactly when `map` answered `Nothing`,
    /// so what `f`'s call writes and what `d` is read for are on two paths
    /// no run takes both of. `m`, `f` and `d` evaluate nothing but reads, so
    /// the arms hold only the call of `f` and the read of `d`.
    ///
    /// §26.4: `Result.withDefault (Result.map m f) d` is the same shape —
    /// `Result.map` calls `f` exactly when `m` is `Ok`, and `withDefault`
    /// answers `d` exactly when `map` answered `Err`. Not `andThen`, of
    /// either module: its `f` may answer `Nothing` or `Err`, and then `d` is
    /// read after `f` ran.
    fn isMaybeJoin(w: *Walker, t: Target, args: []const Inst.Index) Allocator.Error!bool {
        if (args.len != 2 or !std.mem.eql(u8, w.targetName(t), "withDefault")) return false;
        const module: []const u8 = if (w.isCore(t, "Maybe")) "Maybe" else if (w.isCore(t, "Result")) "Result" else return false;
        if ((try w.refPath(args[1])) == null) return false;
        const inner = args[0];
        if (w.bir.instTag(inner) != .call) return false;
        const it = w.valueTarget(@fromBackingInt(@intCast(w.bir.instData(inner).lhs))) orelse return false;
        if (!w.isCore(it, module) or !std.mem.eql(u8, w.targetName(it), "map")) return false;
        const ia = w.callArgs(inner);
        if (ia.len != 2 or (try w.refPath(ia[0])) == null) return false;
        return switch (w.bir.instTag(ia[1])) {
            .lambda, .top, .ext_value => true,
            else => false,
        };
    }

    /// The two arms of a `MaybeJoin`, as a `case` of its own (§7.2).
    fn openMaybeJoin(w: *Walker, inst: Inst.Index) Allocator.Error!MaybeJoin {
        const case_id = w.cases;
        w.cases += 1;
        const depth = w.ctx_nodes.items[w.ctx].depth + 1;
        const just: u32 = @intCast(w.ctx_nodes.items.len);
        try w.ctx_nodes.append(w.a, .{ .parent = w.ctx, .case_id = case_id, .arm = 0, .depth = depth });
        try w.ctx_nodes.append(w.a, .{ .parent = w.ctx, .case_id = case_id, .arm = 1, .depth = depth });
        return .{ .call = inst, .just = just, .nothing = just + 1 };
    }

    /// The branch context argument `i` of the call at `inst` is walked in.
    fn joinArm(w: *const Walker, inst: Inst.Index, i: usize) ?u32 {
        const j = w.maybe_join orelse return null;
        if (j.call != inst) return null;
        return if (i == 0) j.just else j.nothing;
    }

    // ---- the entry protocol (§20) -----------------------------------------

    /// Whether the constructor parameter declares the entry protocol (§20.2).
    fn hasEntry(w: *const Walker, t: Target, param: u32) Allocator.Error!bool {
        const bir = w.o.in.birs[t.m];
        const entry_word = @import("../parse/Ast.zig").OwnWord.entry.bit();
        for (try w.o.flipped(t.m, t.d, bir.ownSlots(bir.decls[t.d]))) |slot| {
            if (slot[0] == param and slot[1] & entry_word != 0) {
                return true;
            }
        }
        return false;
    }

    /// A record value's field, by name.
    fn fieldOf(w: *Walker, av: AV, name: []const u8) Allocator.Error!AV {
        const sym = w.o.in.interner.find(name) orelse return &.{};
        return w.proj(av, .{ .kind = .field, .arg = @backingInt(sym) }, null);
    }

    /// One of a record's functions, with its class summaries.
    const EntryFn = struct {
        classes: []const Class = &.{},
        sums: []const *const Summary = &.{},
        protocol: enum { plain, hosted_update, hosted_settle } = .plain,
    };

    fn entryFn(w: *Walker, av: AV) Allocator.Error!?EntryFn {
        if (av.len == 0) return .{};
        const classes = try w.classesOf(av);
        if (classes.len == 0) return null;
        const sums = try w.a.alloc(*const Summary, classes.len);
        for (classes, sums) |cls, *s| s.* = (try w.classSummary(cls)) orelse return null;
        // The runtime calls it: a lambda's demands on its own parameters are
        // the entry's (§20.6), and a once closure runs at every message.
        for (classes, sums) |cls, s| if (cls == .closure) {
            const cl = &w.closures.items[cls.closure];
            try cl.consumed.append(w.a, .{ .kind = .local });
            if (s.once and cl.once_bad == null) cl.once_bad = "the platform's runtime calls it at every message";
        };
        return .{ .classes = classes, .sums = sums };
    }

    /// Normalize callback roles to the ordinary (message, state) entry row.
    fn entryArgs(w: *Walker, f: EntryFn, args: []const AV) Allocator.Error![]const AV {
        return switch (f.protocol) {
            .plain => args,
            .hosted_update => w.a.dupe(AV, &.{ &.{}, args[0], args[1] }),
            .hosted_settle => w.a.dupe(AV, &.{ &.{}, args[1] }),
        };
    }

    fn entryParam(f: EntryFn, p: u32) ?u32 {
        return switch (f.protocol) {
            .plain => p,
            .hosted_update => if (p == 0) null else p - 1,
            .hosted_settle => if (p == 1) 1 else null,
        };
    }

    fn entryFieldType(w: *Walker, arg: Inst.Index, name: []const u8) ?Var {
        const fields = w.recordFields(w.instType(arg)) orelse return null;
        for (fields) |field| {
            if (std.mem.eql(u8, w.o.in.interner.slice(field.name), name)) return field.value;
        }
        return null;
    }

    const entry_init_ns: u32 = 100_000;
    const entry_view_ns: u32 = 200_000;
    const entry_subs_ns: u32 = 300_000;
    const entry_settle_ns: u32 = 400_000;

    /// `f`'s result for these arguments: each class's `res`, instantiated
    /// at the constructor's call (§16.4 item 6).
    fn entryRes(w: *Walker, inst: Inst.Index, f: EntryFn, avs: []const AV, ns: u32) Allocator.Error!AV {
        return w.entryResWith(inst, f, avs, ns, true);
    }

    fn entryResWith(w: *Walker, inst: Inst.Index, f: EntryFn, avs: []const AV, ns: u32, conds: bool) Allocator.Error!AV {
        return w.entryResMode(inst, f, avs, ns, conds, true);
    }

    fn entryResMode(w: *Walker, inst: Inst.Index, f: EntryFn, avs: []const AV, ns: u32, conds: bool, effects: bool) Allocator.Error!AV {
        const actual = try w.entryArgs(f, avs);
        var arg_index: ArgIndex = .{ .avs = actual };
        var parts: std.ArrayList(AV) = .empty;
        for (f.classes, f.sums) |cls, s| {
            const ci: u32 = if (cls == .closure) cls.closure else none;
            try parts.append(w.a, try w.instRes(s, .{ .inst = inst, .s = s, .avs = actual, .closure = ci, .depth = 0, .fresh_ns = ns, .conds = conds, .effects = effects, .args = &arg_index }));
        }
        return w.unionOf(parts.items);
    }

    fn entryConditions(w: *Walker, inst: Inst.Index, update: EntryFn, settle: ?EntryFn, payload: AV, initial: AV, model: AV) Allocator.Error!void {
        var fresh: std.ArrayList(u32) = .empty;
        const made_initially = try w.expand(initial);
        // What init made, by the key a cover needs (`coverKey`): a model as
        // wide as init's record asks each of its cells once (#716).
        var init_by: std.AutoHashMapUnmanaged([3]u32, std.ArrayList(u32)) = .empty;
        for (made_initially, 0..) |i, k| {
            const g = try init_by.getOrPut(w.a, w.coverKey(i.cell));
            if (!g.found_existing) g.value_ptr.* = .empty;
            try g.value_ptr.append(w.a, @intCast(k));
        }
        var seen: std.ArrayList(bool) = .empty;
        for (model) |e| {
            const c = w.cells.items[e.cell];
            // The entry namespaces update below 100000, init from 100000,
            // view from 200000, subscriptions from 300000 and settle from 400000 (§20.4).
            if (c.kind != .result or c.a != inst.int() or c.b == 0 or (c.b >= entry_init_ns and c.b < entry_settle_ns) or try w.isEscaped(e.cell)) continue;
            // A callback's cells may use the lower namespace too. Anything
            // present at init keeps its established condition, never a guess.
            if (try w.coveredBy(made_initially, &init_by, e.cell)) continue;
            if (try markOnce(w.a, &seen, e.cell)) continue;
            try fresh.append(w.a, e.cell);
            w.cond_writes += 1;
            w.cell_cond.items[e.cell] = cond_yes;
        }
        // §31.4 item 6: the records of the model, the same invariant, on the
        // record cell an update's object was written over too.
        var rfresh: std.ArrayList(u32) = .empty;
        var rseen: std.ArrayList(bool) = .empty;
        for (model) |e| {
            const b = try w.rbase(e.cell);
            const c = w.cells.items[b];
            if (c.kind != .result or c.a != inst.int() or c.b == 0 or (c.b >= entry_init_ns and c.b < entry_settle_ns)) continue;
            if (try w.isEscaped(b) or try w.isEscaped(e.cell) or try w.isEscaped(try w.exceptCell(b, &.{}, true))) continue;
            if (try w.coveredBy(made_initially, &init_by, b)) continue;
            if (try markOnce(w.a, &rseen, b)) continue;
            try rfresh.append(w.a, b);
            w.cell_rcond.items[b] = cond_yes;
        }
        if (fresh.items.len == 0 and rfresh.items.len == 0) return;
        // §20.4, amended 2026-10-16 (#229): the rounds run over a finite
        // domain — every cell is named by where it is made, a carried lambda
        // too — so a round that makes no cell, grows no carried lambda and
        // moves no condition is the fixpoint. Conditions only go down a chain
        // of finite height, so it is reached in a bounded number of rounds.
        // The list table and the record table settle apart (§31.4 item 6):
        // one that does not is lowered to the limit alone, so that a record
        // condition never moves a list's verdict, and only a list's that
        // does not settle makes the declaration an error.
        var lists_settled = false;
        var records_settled = false;
        for (0..round_cap) |_| {
            const before = try w.a.dupe(u32, w.cell_cond.items);
            const rbefore = try w.a.dupe(u32, w.cell_rcond.items);
            const grew = w.carry_grew;
            const demands_before = w.demands.items.len;
            const uses_before = w.uses.items.len;
            const escapes_before = w.escaped.items.len;
            _ = try w.entryResMode(inst, update, &.{ payload, model }, 0, true, false);
            if (settle) |f| _ = try w.entryResMode(inst, f, &.{ payload, model }, entry_settle_ns, true, false);
            if (std.debug.runtime_safety) {
                std.debug.assert(w.demands.items.len == demands_before);
                std.debug.assert(w.uses.items.len == uses_before);
                std.debug.assert(w.escaped.items.len == escapes_before);
            }
            // A cell made in the round grows both tables: neither settled.
            lists_settled = w.carry_grew == grew and std.mem.eql(u32, before, w.cell_cond.items);
            records_settled = std.mem.eql(u32, rbefore, w.cell_rcond.items);
            if (lists_settled and records_settled) return;
        }
        // Never use an unfinished proof, and never lose it silently: the
        // declaration is an error (§16.7).
        if (!lists_settled) {
            try w.o.hitLimit(.fixpoint, round_cap);
            for (fresh.items) |c| try w.lowerCond(c, cond_limit);
        }
        if (!records_settled) for (rfresh.items) |c| try w.rlowerCond(c, cond_limit);
    }

    /// Every cell of `av`, closures expanded, at `⋆`: what a value built
    /// from them may hold anywhere. A closure's own cell is no list; what it
    /// captured is expanded into the result, so a message holding a handler
    /// that captured a model list still names that list.
    fn anywhere(w: *Walker, av: AV, inst: Inst.Index) Allocator.Error!AV {
        const any = try w.o.child(eps, .any, 0);
        var out: std.ArrayList(Entry) = .empty;
        for (try w.expand(av)) |e| {
            const k = w.cells.items[e.cell].kind;
            if (k == .closure or k == .func) continue;
            try out.append(w.a, .{ .path = any, .cell = e.cell, .approx = inst.int() + 1, .grown = e.grown });
        }
        return w.norm(out.items);
    }

    /// What the entry keeps outside init, including environments of closures
    /// returned by helpers. `expand` follows ordinary local captures; carried
    /// closures instead need the instantiated bindings and callbacks below.
    fn retainedEntryFields(w: *Walker, fields: AV) Allocator.Error!AV {
        var held: std.ArrayList(Entry) = .empty;
        try held.appendSlice(w.a, try w.expand(fields));
        var seen: std.ArrayList(u32) = .empty;
        var i: usize = 0;
        while (i < held.items.len) : (i += 1) {
            const c = w.cells.items[held.items[i].cell];
            if (c.kind != .closure or !w.closures.items[c.a].carried) continue;
            if (std.mem.indexOfScalar(u32, seen.items, c.a) != null) continue;
            try seen.append(w.a, c.a);
            for (w.closures.items[c.a].binds) |b| try held.appendSlice(w.a, try w.expand(b.av));
            for (w.closures.items[c.a].cb_avs) |cb| try held.appendSlice(w.a, try w.expand(cb.av));
        }
        return w.norm(held.items);
    }

    /// A call of a program constructor with an entry row (§20.2–§20.6): the
    /// model at entry as the fixpoint of `init` and `update`, what the
    /// runtime's calls escape, and a demand for each path `update` writes.
    fn entryCall(w: *Walker, inst: Inst.Index, t: Target, arg: Inst.Index) Allocator.Error!AV {
        const saved = w.entry_arg;
        w.entry_arg = arg.int();
        const app = try w.eval(arg);
        w.entry_arg = saved;
        w.point += 1;
        const tok = w.token(inst);
        try w.useOperand(arg, tok, &.{});
        try w.useTemporaries(&.{arg}, &.{app}, tok);
        _ = t;
        const hosted = w.entryFieldType(arg, "settle") != null;
        const update_ty = w.entryFieldType(arg, "update") orelse {
            try w.sight(app, .{ .pending = "its entry record has no update callback" }, tok);
            return w.entryResult(inst);
        };
        const model_ty = funcParam(w.store, update_ty, if (hosted) 2 else 1) orelse {
            try w.sight(app, .{ .pending = "its entry update has no state parameter" }, tok);
            return w.entryResult(inst);
        };
        const whole = switch (w.store.resolvedContent(update_ty)) {
            .structure => |st| if (st == .func) blk: {
                const result_root, _ = w.store.resolved(st.func.result);
                const model_root, _ = w.store.resolved(model_ty);
                break :blk result_root == model_root;
            } else false,
            else => false,
        };
        // A privileged declaration must still have the callback shape its
        // row models. Otherwise no supplies or state writes may be dropped.
        const update_arity: u32 = if (hosted) 3 else 2;
        const settle_ty = w.entryFieldType(arg, "settle");
        const valid_settle = if (settle_ty) |ty| whole and
            funcParam(w.store, ty, 1) != null and funcParam(w.store, ty, 2) == null else true;
        if (funcParam(w.store, update_ty, update_arity) != null or !valid_settle) {
            try w.sight(app, .{ .pending = "its entry callbacks do not have the update/settle state protocol" }, tok);
            return w.entryResult(inst);
        }
        const tuple0: Step = .{ .kind = .tuple, .arg = 0 };
        const tuple1: Step = .{ .kind = .tuple, .arg = 1 };
        var upd = (try w.entryFn(try w.fieldOf(app, "update"))) orelse {
            // The runtime calls a function the walk cannot place.
            try w.sight(app, .{ .pending = "it is handed to a program whose update the checker cannot place" }, tok);
            return w.entryResult(inst);
        };
        if (hosted) upd.protocol = .hosted_update;
        var settle: EntryFn = .{};
        if (hosted) {
            settle = (try w.entryFn(try w.fieldOf(app, "settle"))) orelse {
                try w.sight(app, .{ .pending = "it is handed to a program whose settle the checker cannot place" }, tok);
                return w.entryResult(inst);
            };
            settle.protocol = .hosted_settle;
        }
        const writers = [_]EntryFn{ upd, settle };
        const transitions = writers[0..@as(usize, if (hosted) 2 else 1)];
        // §22.2: init's captures arrive from outside its body. Other entry
        // callbacks keep their environments across messages and renders.
        const init_sym = w.o.in.interner.find("init");
        var retained_fields: std.ArrayList(Entry) = .empty;
        for (app) |e| {
            // Exclude only a known init subtree. A root or wildcard may hold
            // other callbacks too; symmetric overlap would discard those.
            if (init_sym) |sym| if (w.o.firstStep(e.path)) |step| {
                if (step.kind == .field and step.arg == @backingInt(sym)) continue;
            };
            try retained_fields.append(w.a, e);
        }
        const retained = try w.retainedEntryFields(retained_fields.items);
        const view = (try w.entryFn(try w.fieldOf(app, "view"))) orelse EntryFn{};
        const subs = (try w.entryFn(try w.fieldOf(app, "subscriptions"))) orelse EntryFn{};
        // `init` is a function the runtime calls once per mount (§22.2): of
        // `⊤`, which holds no cell, or for an application of the address,
        // which crosses, and the navigation key, a foreign type (§20.3).
        // A function the walk cannot place makes a model it cannot know.
        var init_args: []const AV = &.{&.{}};
        if (w.entryFieldType(arg, "init")) |ty| switch (w.store.resolvedContent(ty)) {
            .structure => |st| if (st == .func) {
                const ps = w.store.vars(st.func.params);
                const values = try w.a.alloc(AV, ps.len);
                for (ps, values) |p, *av| av.* = if (hosted or !try w.trackedVar(p))
                    &.{}
                else
                    try w.single(.{ .kind = .top, .a = 0 });
                init_args = values;
            },
            else => {},
        };

        const init_av = if (init_sym == null)
            try w.single(.{ .kind = .top, .a = 0 })
        else if (try w.entryFn(try w.fieldOf(app, "init"))) |f|
            try w.entryRes(inst, f, init_args, entry_init_ns)
        else
            try w.single(.{ .kind = .top, .a = 0 });
        const m0 = if (whole) init_av else try w.proj(init_av, tuple0, null);
        // A message type that holds no cell brings none (§20.5).
        const msg_tracked = try w.messageTracked(arg, if (hosted) 1 else 0);
        const payload: AV = if (msg_tracked) try w.single(.{ .kind = .payload, .a = inst.int() }) else &.{};
        // The fixpoint (§20.4): update's fresh cells are one per number and its
        // carried lambdas one per place in every round, so it settles; §16.7's
        // `fixpoint` limit bounds its rounds. Its rounds
        // compute cells only; the round that settles lowers their conditions.
        // §23.6: what a send gave up is owned; a view event's message is
        // not, and may hold the lists the view's messages carry. They are not
        // carried round the loop: they reach the model only where an arm
        // stores a payload, which the cell `msg` marks, so a demand that
        // reaches `msg` while the view's messages may hold a list is the
        // view-event rule's (P6). So the view is read once, on the settled
        // model.
        var model = m0;
        var res: AV = &.{};
        var round: u32 = 0;
        while (true) : (round += 1) {
            const grew = w.carry_grew;
            res = try w.entryResWith(inst, upd, &.{ payload, model }, 0, false);
            const half = if (whole) res else try w.proj(res, tuple0, null);
            const settled = if (hosted) try w.entryResWith(inst, settle, &.{ payload, model }, entry_settle_ns, false) else &.{};
            // The union is sorted and deduplicated, and contains `model`: the
            // same length is the same set, so it has settled — unless a
            // lambda the model carries captured more this round.
            const next = try w.unionOf(&.{ model, half, settled });
            if (next.len == model.len and w.carry_grew == grew) break;
            model = next;
            if (round + 1 >= round_cap) {
                // Its cells are finite (§20.4), so this is the compiler's
                // limit, and an error at the declaration (§16.7).
                try w.o.hitLimit(.fixpoint, round_cap);
                model = try w.unionOf(&.{ model, try w.single(.{ .kind = .top, .a = 1 }) });
                break;
            }
        }
        // Fresh update results participate in the model's inductive
        // exclusivity invariant. Init's conditions are never reseeded.
        try w.entryConditions(inst, upd, if (hosted) settle else null, payload, m0, model);
        const view_msgs = try w.viewMessages(inst, view, model, true, w.viewResultType(arg));
        const msg = try w.unionOf(&.{ payload, view_msgs });
        // What a list's demand reads of them: no record's object (§31.7).
        const view_lists = try w.listView(view_msgs);
        res = try w.entryRes(inst, upd, &.{ msg, model }, 0);
        // (a) What every call the runtime makes escapes.
        // The settled model, projected at every path update writes or the
        // view reads (#825).
        var model_steps: StepIndex = .{ .av = model };
        for (transitions, 0..) |callback, wi| {
            if (wi != 0) _ = try w.entryRes(inst, callback, &.{ msg, model }, entry_settle_ns);
            for (callback.sums) |s| for (s.uses) |u| {
                if (entryParam(callback, u.param) == 1) {
                    const at = try w.projPathVia(&model_steps, u.path);
                    try w.entryEscape(inst, at, entryBits(u.bits));
                    if (u.bits & bit_k != 0) try w.escapeObjects(at, w.point);
                }
            };
        }
        if (!whole) {
            try w.escape(try w.proj(res, tuple1, null), w.point);
            try w.escape(try w.proj(init_av, tuple1, null), w.point);
        }
        for ([_]EntryFn{ view, subs }) |f| for (f.sums) |s| for (s.uses) |u| {
            if (u.param == 0) {
                const at = try w.projPathVia(&model_steps, u.path);
                try w.entryEscape(inst, at, entryBits(u.bits));
                if (u.bits & bit_k != 0) try w.escapeObjects(at, w.point);
            }
        };
        try w.escape(try w.entryRes(inst, subs, &.{model}, entry_subs_ns), w.point);
        w.point += 1;
        // (b) The demands.
        const arena = w.o.out.allocator();
        // Preserve the shared entry reach indexes for both state writers.
        const model_idx = try w.reachIndex(model);
        const lists_idx = if (view_lists.len > 0) try w.reachIndex(view_lists) else null;
        const msgs_idx = if (view_msgs.len > 0) try w.reachIndex(view_msgs) else null;
        for (transitions, 0..) |callback, wi| {
            const op = if (w.mode == .report) try std.fmt.allocPrint(arena, "entry {s}", .{try w.entryName(callback, if (wi == 0) "update" else "settle")}) else "entry";
            // One demand per path written, its derivation and exclusivity the
            // worst any of update's classes gives (an exact write beats an
            // approximate one, a failed `xreq` beats a held one).
            const Written = struct { param: u32, path: u32, origin: Origin, xfail: ?Rely, deep: bool, extent: WriteExtent };
            var written: std.ArrayList(Written) = .empty;
            for (callback.classes, callback.sums) |cls, s| for (s.uses) |u| {
                const param = entryParam(callback, u.param) orelse continue;
                if (u.bits & bit_w == 0 or param > 1) continue;
                const origin: Origin = if (s.limit != .none) .limit else if (u.bits & bit_x == 0) .approx else .exact;
                // update's xreq on the model, or on its message (§23.6), at
                // this path (§18.4 item 3).
                var xfail: ?Rely = null;
                {
                    const ci: u32 = if (cls == .closure) cls.closure else none;
                    // Pair by pair: the report takes each pair where it was (§16.7, #693).
                    for (try expandAtoms(w.a, s.xreq)) |x| {
                        const p = xreqParam(x) orelse continue;
                        if (p != u.param) continue;
                        const k = try w.instXSum(.{ .atoms = &.{x} }, .{ .inst = inst, .s = s, .avs = try w.entryArgs(callback, &.{ msg, model }), .closure = ci, .depth = 0 });
                        const r = try w.rely(k, w.frame);
                        if (r == .ok) continue;
                        xfail = Rely.worse(xfail, r);
                    }
                }
                var found = false;
                const deep = u.bits & bit_d != 0;
                for (written.items) |*x| {
                    if (x.param != param or x.path != u.path) continue;
                    found = true;
                    x.deep = x.deep or deep;
                    if (u.extent == .deep) x.extent = .deep;
                    if (origin == .exact or (origin == .approx and x.origin == .limit)) x.origin = origin;
                    if (xfail) |r| x.xfail = Rely.worse(x.xfail, r);
                }
                if (!found) try written.append(w.a, .{ .param = param, .path = u.path, .origin = origin, .xfail = xfail, .deep = deep, .extent = u.extent });
            };
            for (written.items) |x| {
                if (x.param == 0) {
                    // §20.5, §23.6: update writes its message in place — what a
                    // send gave up, or what a view event built from the model.
                    const at = try w.projPath(msg, x.path, null);
                    try w.entryDemandDeep(tok, op, try w.pathName("msg", x.path), if (x.deep) try w.flat(at) else at, &.{retained}, view_lists, x.origin, x.xfail, x.deep, x.extent, null, none, lists_idx);
                    continue;
                }
                var rest: std.ArrayList(Entry) = .empty;
                if (model_idx == null) for (model) |e| if (!w.o.overlap(e.path, x.path)) try rest.append(w.a, e);
                const at = try w.projPathVia(&model_steps, x.path);
                // Not Disjoint against this message: what a send put in the
                // model was another send's, given up there (§23.6).
                try w.entryDemandDeep(tok, op, try w.pathName("model", x.path), if (x.deep) try w.flat(at) else at, if (model_idx != null) &.{retained} else &.{ rest.items, retained }, view_lists, x.origin, x.xfail, x.deep, x.extent, model_idx, x.path, lists_idx);
            }
            // §31.8: each record update writes is an `update` demand at the entry,
            // with the fields written; reported, not enforced (R4).
            {
                const RecordWrite = struct { param: u32, path: u32, fields: []const u32, origin: Origin, xfail: ?Rely };
                var rw: std.ArrayList(RecordWrite) = .empty;
                for (callback.classes, callback.sums) |cls, s| for (s.uses) |u| {
                    const param = entryParam(callback, u.param) orelse continue;
                    if (u.bits & bit_f == 0 or param > 1) continue;
                    const origin: Origin = if (s.limit != .none) .limit else .exact;
                    // §31.4 item 6: update's `rxreq` on the model or the
                    // message, as its `xreq` above.
                    var xfail: ?Rely = null;
                    {
                        const ci: u32 = if (cls == .closure) cls.closure else none;
                        for (try expandAtoms(w.a, s.rxreq)) |x| {
                            const p = xreqParam(x) orelse continue;
                            if (p != u.param) continue;
                            const k = try w.rinstXSum(.{ .atoms = &.{x} }, .{ .inst = inst, .s = s, .avs = try w.entryArgs(callback, &.{ msg, model }), .closure = ci, .depth = 0 });
                            const r = try w.rrely(k, w.frame);
                            if (r == .ok) continue;
                            xfail = Rely.worse(xfail, r);
                        }
                    }
                    for (rw.items) |*x| {
                        if (x.param != param or x.path != u.path) continue;
                        x.fields = try unionFields(w.a, x.fields, u.fields);
                        if (origin == .exact) x.origin = origin;
                        if (xfail) |r| x.xfail = Rely.worse(x.xfail, r);
                        break;
                    } else try rw.append(w.a, .{ .param = param, .path = u.path, .fields = u.fields, .origin = origin, .xfail = xfail });
                };
                const rop = try std.fmt.allocPrint(arena, "update {s}", .{op});
                for (rw.items) |x| {
                    const src = if (x.param == 0) msg else model;
                    var rest: std.ArrayList(Entry) = .empty;
                    if (x.param == 1 and model_idx == null) for (model) |e| if (!w.o.overlap(e.path, x.path)) try rest.append(w.a, e);
                    const base = if (x.param == 0) try w.projPath(src, x.path, null) else try w.projPathVia(&model_steps, x.path);
                    try w.demandOn(.{
                        .kind = .callsite,
                        .token = tok,
                        .op = rop,
                        .base_text = try w.pathName(if (x.param == 0) "msg" else "model", x.path),
                        .base_ref = null,
                        .base_ty = null,
                        .base = base,
                        .others = if (x.param == 0 or model_idx != null) &.{retained} else &.{ rest.items, retained },
                        .rest_index = if (x.param == 1) model_idx else null,
                        .rest_except = x.path,
                        .payload_index = msgs_idx,
                        .origin = x.origin,
                        .entry = true,
                        .payload_from = view_msgs,
                        .fields = if (x.fields.len != 0) x.fields else try w.allFields(base),
                        .xfail = x.xfail,
                    });
                }
            }
        }
        // §30.3, §30.9: the runtime calls `onUrlRequest` and `onUrlChange`
        // with crossing arguments and sends what they return, so each must
        // return owned — a message is owned at `update` (§23.6) only because
        // every send was checked where it was made.
        for ([_][]const u8{ "onUrlRequest", "onUrlChange" }) |field| {
            const sym = w.o.in.interner.find(field) orelse continue;
            if (!w.recordHasField(w.instType(arg), @backingInt(sym))) continue;
            try w.entryTagger(inst, field, try w.fieldOf(app, field));
        }
        // §20.3: view and subscriptions receive the model to read only.
        for ([_]struct { f: EntryFn, n: []const u8 }{ .{ .f = view, .n = "view" }, .{ .f = subs, .n = "subscriptions" } }) |x| {
            const vop = if (w.mode == .report) try std.fmt.allocPrint(arena, "entry {s}", .{try w.entryName(x.f, x.n)}) else "entry";
            const rvop = if (w.mode == .report) try std.fmt.allocPrint(arena, "update {s}", .{vop}) else "entry";
            for (x.f.sums) |s| for (s.uses) |u| {
                if (u.bits & (bit_w | bit_f) == 0 or u.param != 0) continue;
                // §31.8: a record's write is a record line, reported (R4).
                if (u.bits & bit_w == 0 and w.mode != .report) continue;
                try w.demands.append(w.a, .{
                    .kind = .value,
                    .token = tok,
                    .op = if (u.bits & bit_w == 0) rvop else vop,
                    .base = try w.pathName("model", u.path),
                    .base_local = none,
                    .base_path = eps,
                    .point = w.point,
                    .frame = w.frame,
                    .ctx = w.ctx,
                    .element = false,
                    .accept = .param,
                    .holders = &.{},
                    .fixed = .{ .verdict = .{ .rejected = .read_only }, .detail = try std.fmt.allocPrint(arena, "the runtime hands {s} the model to read only (§20.3)", .{x.n}) },
                    .fields = if (u.bits & bit_w == 0) u.fields else null,
                });
            };
        }
        return w.entryResult(inst);
    }

    /// Whether `update`'s message type may hold a cell: the type of the
    /// record literal's `update` field, when the walk has it.
    fn messageTracked(w: *Walker, arg: Inst.Index, message_index: usize) Allocator.Error!bool {
        if (w.bir.instTag(arg) != .record) return true;
        const sym = w.o.in.interner.find("update") orelse return true;
        for (w.bir.extraSlice(Bir.inlineRange(w.bir.instData(arg)), Bir.Field)) |fl| {
            if (w.bir.symbol(fl.name) != sym) continue;
            const v = w.instType(fl.value) orelse return true;
            switch (w.store.resolvedContent(v)) {
                .structure => |st| switch (st) {
                    .func => |fun| {
                        const ps = w.store.vars(fun.params);
                        if (ps.len <= message_index) return true;
                        return w.trackedVar(ps[message_index]);
                    },
                    else => return true,
                },
                else => return true,
            }
        }
        return true;
    }

    /// §31.4 item 2: the record objects at the root of `av` escape at `at`,
    /// and nothing below them: a record's object holds no list. What a
    /// summary's `bit_k` keeps, at a call, at the entry, and through a
    /// callback.
    fn escapeObjects(w: *Walker, av: AV, at: u32) Allocator.Error!void {
        for (av) |e| {
            if (e.path != eps) continue;
            const x = w.cells.items[e.cell];
            switch (x.kind) {
                .closure, .func, .top => continue,
                .site => if (!x.nonlist) continue,
                .param, .result, .env, .shared, .cbres, .taken, .payload, .except => {},
            }
            try w.noteEscape(try w.exceptCell(e.cell, &.{}, true), at, 0, e.grown);
        }
    }

    fn entryEscape(w: *Walker, inst: Inst.Index, av: AV, bits: u8) Allocator.Error!void {
        if (bits & bit_e != 0) return w.escape(av, w.point);
        if (bits & bit_j != 0) try w.escapeWhy(av, w.point, inst);
    }

    /// §20.5, §23.6: the cells the messages `view` builds may carry, anywhere
    /// in a message: its result's cells, closures expanded, but its own root.
    fn viewMessages(w: *Walker, inst: Inst.Index, view: EntryFn, model: AV, conds: bool, result_ty: ?Var) Allocator.Error!AV {
        if (view.sums.len == 0) return &.{};
        // The model's own cells, and every list the view made: a markup value
        // keeps its handlers from one dispatch to the next (P3), so a list a
        // handler's message holds may be handed over twice. The markup's own
        // node — what the view returns at its root — is no message.
        var held: std.ArrayList(Entry) = .empty;
        const result = try w.entryResWith(inst, view, &.{model}, entry_view_ns, conds);
        for (try w.markupEvents(result, result_ty, inst, 0)) |e| {
            // A precise slot projection contains messages, never the markup
            // root. Unknown projected arrivals must remain borrowed too.
            if (result_ty == null and e.path == eps and (try w.reaches(model, &.{e})) == null) continue;
            try held.append(w.a, e);
        }
        // A top-level value whose type can hold no list — a footer, an icon
        // — is markup the view includes, not a message.
        var out: std.ArrayList(Entry) = .empty;
        for (try w.anywhere(try w.norm(held.items), inst)) |e| {
            const c = w.cells.items[e.cell];
            if (c.kind == .shared and c.path == eps and !try w.sharedHoldsList(c.a, c.b)) continue;
            try out.append(w.a, e);
        }
        return w.norm(out.items);
    }

    /// Whether the top-level value `d` of module `m` may hold a list.
    fn sharedHoldsList(w: *Walker, m: u32, d: u32) Allocator.Error!bool {
        if (m >= w.o.in.birs.len) return true;
        return w.o.valueHoldsList(m, d);
    }

    /// A program value: the runtime's, which nothing in the program reads.
    fn entryResult(w: *Walker, inst: Inst.Index) Allocator.Error!AV {
        if (!try w.isTracked(inst)) return &.{};
        return w.single(.{ .kind = .top, .a = 0 });
    }

    /// How an entry line names the function: `Main.update`, or `<lambda>`.
    fn entryName(w: *Walker, f: EntryFn, field: []const u8) Allocator.Error![]const u8 {
        for (f.classes) |cls| switch (cls) {
            .func => |t| return w.qualified(t),
            .closure, .send => {},
        };
        return std.fmt.allocPrint(w.o.out.allocator(), "<{s}>", .{field});
    }

    /// `model.todos`: a root's name with a path.
    fn pathName(w: *Walker, root: []const u8, p: u32) Allocator.Error![]const u8 {
        if (w.mode != .report) return root;
        return std.fmt.allocPrint(w.o.out.allocator(), "{s}{s}", .{ root, try w.o.pathText(p) });
    }

    /// A demand at the entry (§20.6): a call-site demand on the entry model
    /// at one path, or on the message.
    fn entryDemandDeep(w: *Walker, tok: u32, op: []const u8, text: []const u8, base: AV, others: []const AV, payload_from: AV, origin: Origin, xfail: ?Rely, deep: bool, extent: WriteExtent, rest_index: ?*const ReachIndex, rest_except: u32, payload_index: ?*const ReachIndex) Allocator.Error!void {
        try w.demandOn(.{
            .rest_index = rest_index,
            .rest_except = rest_except,
            .payload_index = payload_index,
            .kind = .callsite,
            .token = tok,
            .op = op,
            .base_text = text,
            .base_ref = null,
            .base_ty = null,
            .base = base,
            .others = others,
            .origin = origin,
            .xfail = xfail,
            .entry = true,
            .payload_from = payload_from,
            .deep = deep,
            .extent = extent,
        });
    }

    fn evalMethod(w: *Walker, inst: Inst.Index) Allocator.Error!AV {
        const b = w.bir;
        const data = b.instData(inst);
        const mc = b.extraData(@fromBackingInt(@intCast(data.rhs)), Bir.MethodCall);
        const rest = b.extraSlice(.{ .start = mc.args_start, .end = mc.args_end }, Inst.Index);
        const all = try w.a.alloc(Inst.Index, rest.len + 1);
        all[0] = @fromBackingInt(@intCast(data.lhs));
        @memcpy(all[1..], rest);
        try w.evidenceSight(inst);
        if (w.methodTarget(inst)) |t| return w.callTarget(inst, t, all);
        // `r.load a` on a record field that holds a function is a call of
        // the field's value, as `(r.load) a` is: a slot of a parameter, a
        // class the walk knows, or a function it cannot identify (§30.11).
        if (try w.fieldFunction(all[0], mc.name)) |f| return w.callValue(inst, rest, f, .{ .inst = all[0], .field = @backingInt(w.bir.symbol(mc.name)) });
        return w.conservative(inst, all, &.{}, null, "", false, .unknown);
    }

    /// The function value a record receiver holds at its field `name`, when
    /// the receiver's type is a record that lists the field: closed, or
    /// extensible (`{ r | load : … }`), through its extension chain.
    fn fieldFunction(w: *Walker, receiver: Inst.Index, name: Bir.SymbolIndex) Allocator.Error!?AV {
        const sym = w.bir.symbol(name);
        var t = w.instType(receiver) orelse return null;
        var depth: u32 = 0;
        const value: Var = found: while (depth <= type_depth) : (depth += 1) {
            const rc = switch (w.store.resolvedContent(t)) {
                .structure => |st| switch (st) {
                    .record => |rc| rc,
                    else => return null,
                },
                else => return null,
            };
            for (w.store.fields(rc.fields)) |f| if (f.name == sym) break :found f.value;
            t = rc.ext;
        } else return null;
        const r = try w.eval(receiver);
        return try w.proj(r, .{ .kind = .field, .arg = @backingInt(sym) }, value);
    }

    /// Where a function the dispatch table passes as evidence writes a
    /// parameter: its calls are not seen (§16.5).
    fn evidenceSight(w: *Walker, inst: Inst.Index) Allocator.Error!void {
        if (w.m >= w.o.in.dispatch.len) return;
        const dt = &w.o.in.dispatch[w.m];
        const site = dt.siteOf(inst) orelse return;
        // Every term, however deep the evidence nests: they are finite, and
        // each is looked at once per site, so a writing function that occurs
        // twice gives one line. Before 2026-10-16 the walk stopped 8 levels
        // deep and a writing function below went unreported (#271).
        const tok = w.token(inst);
        var todo: std.ArrayList(Dispatch.TermIndex) = .empty;
        // A site's evidence is a small tree of terms: a list, not a map.
        var seen: std.ArrayList(Dispatch.TermIndex) = .empty;
        const top = dt.argsAt(site.evidence);
        var i = top.len;
        while (i > 0) : (i -= 1) try todo.append(w.a, top[i - 1]);
        while (todo.pop()) |ti| {
            if (std.mem.indexOfScalar(Dispatch.TermIndex, seen.items, ti) != null) continue;
            try seen.append(w.a, ti);
            const t = dt.term(ti);
            if (w.termTarget(t)) |target| {
                if (try w.o.ensureSummary(target.m, target.d)) |s| if (s.writesAny()) {
                    try w.valueLine(tok, try w.qualified(target), .pending, "it is passed as evidence, whose calls the checker does not see", "", false);
                };
            }
            const args = dt.argsOfTerm(ti);
            var k = args.len;
            while (k > 0) : (k -= 1) try todo.append(w.a, args[k - 1]);
        }
    }

    /// Condition annotations describe the value, not another alternative
    /// allocation or function class that value might be.
    fn onlyValue(w: *const Walker, av: AV) ?Entry {
        var found: ?Entry = null;
        for (av) |e| {
            if (w.cells.items[e.cell].condition_only) continue;
            if (found != null) return null;
            found = e;
        }
        return found;
    }

    /// The function parameter of the declaration an abstract value is,
    /// when it is exactly one.
    fn fnParamOf(w: *Walker, av: AV) ?u32 {
        const value = w.onlyValue(av) orelse return null;
        if (value.path != eps) return null;
        var c = w.cells.items[value.cell];
        if (c.kind == .env) {
            const held = w.local_av[c.a] orelse return null;
            const value_held = w.onlyValue(held) orelse return null;
            if (value_held.path != eps or c.path != eps) return null;
            c = w.cells.items[value_held.cell];
        }
        if (c.kind != .param or c.b != 0 or c.path != eps) return null;
        for (w.params, 0..) |p, i| if (p.int() == c.a and w.fn_state.items[i].is_fn) return @intCast(i);
        return null;
    }

    /// `send`: a send value (§23.2), whose class gives up everything it is
    /// handed.
    const Class = union(enum) { closure: u32, func: Target, send };

    /// Whether a cell is the parameter of a lambda written at a send
    /// position (§23.4).
    fn isSend(w: *const Walker, c: Cell) bool {
        return c.kind == .param and c.b == 1 and c.path == eps and w.instCol(bool, w.send_params, c.a, false);
    }

    /// The classes a function value may have: the lambdas, local functions
    /// and top-level functions it may be (§16.5). Empty when any part of it
    /// is something else.
    fn classesOf(w: *Walker, av: AV) Allocator.Error![]const Class {
        var out: std.ArrayList(Class) = .empty;
        for (av) |e| {
            if (w.cells.items[e.cell].condition_only) continue;
            // What a closure a callee's result carried holds sits beside
            // it, under `◇` (§24.9): its captures, not another function.
            if (w.o.firstStep(e.path)) |s| if (s.kind == .env) continue;
            if (e.path != eps) return &.{};
            const c = w.cells.items[e.cell];
            if (w.isSend(c)) {
                try out.append(w.a, .send);
                continue;
            }
            switch (c.kind) {
                .closure => try out.append(w.a, .{ .closure = c.a }),
                .func => try out.append(w.a, .{ .func = .{ .m = c.a, .d = c.b } }),
                .env => {
                    const held = w.local_av[c.a] orelse return &.{};
                    if (c.path != eps) return &.{};
                    for (held) |h| {
                        if (w.cells.items[h.cell].condition_only) continue;
                        if (h.path != eps) return &.{};
                        const hc = w.cells.items[h.cell];
                        if (w.isSend(hc)) {
                            try out.append(w.a, .send);
                            continue;
                        }
                        switch (hc.kind) {
                            .closure => try out.append(w.a, .{ .closure = hc.a }),
                            .func => try out.append(w.a, .{ .func = .{ .m = hc.a, .d = hc.b } }),
                            .site, .param, .result, .env, .shared, .top, .cbres, .taken, .payload, .except => return &.{},
                        }
                    }
                },
                .site, .param, .result, .shared, .top, .cbres, .taken, .payload, .except => return &.{},
            }
        }
        return out.items;
    }

    /// What §6.1's call answers at `ε` (§30.11): `made`, a node a markup
    /// construction makes; else `⊤call`, never a cell the call made, for a
    /// function the checker cannot identify (`unknown`) or one of several
    /// classes it does not join (`several`), either of which may return a
    /// list something else holds.
    const CallResult = enum { made, unknown, several };

    /// §6.1.
    fn conservative(w: *Walker, inst: Inst.Index, args: []const Inst.Index, callee_av: AV, callee: ?CalleeRef, name: []const u8, foreign: bool, result: CallResult) Allocator.Error!AV {
        const avs = try w.evalOperands(args, true);
        w.popPending(avs.len);
        return w.conservativeAV(inst, args, avs, callee_av, callee, name, foreign, result);
    }

    fn conservativeAV(w: *Walker, inst: Inst.Index, args: []const Inst.Index, avs: []const AV, callee_av: AV, callee: ?CalleeRef, name: []const u8, foreign: bool, result: CallResult) Allocator.Error!AV {
        w.point += 1;
        const tok = w.token(inst);
        // A call with no summary reads its arguments whole (§31.4 item 5):
        // an argument's own path is the caller's read, the rest the call's.
        w.use_call = 2;
        defer w.use_call = 0;
        defer w.use_call_at = eps;
        for (args) |x| {
            w.use_call_at = if (try w.refPath(x)) |r| r.path else eps;
            try w.useOperand(x, tok, &.{});
        }
        w.use_call_at = eps;
        if (callee) |c| try w.useCallee(c, tok);
        try w.useTemporaries(args, avs, tok);
        if (callee) |c| try w.useTemporaries(&.{c.inst}, &.{callee_av}, tok);
        for (avs) |av| try w.sight(av, if (name.len > 0) .{ .no_summary = name } else .{ .pending = "it is passed where the checker cannot see its calls" }, tok);
        if (foreign) for (avs) |av| try w.escapeCapturesOf(av, w.point, inst);
        const ty = w.instType(inst);
        if (ty) |v| if (!try w.trackedVar(v)) return &.{};
        var out: std.ArrayList(Entry) = .empty;
        const own = try w.cell(switch (result) {
            .made => .{ .kind = .result, .a = inst.int(), .ty = w.instTypeOpt(inst) },
            .unknown => .{ .kind = .top, .a = top_call },
            .several => .{ .kind = .top, .a = top_several },
        });
        try out.append(w.a, .{ .path = eps, .cell = own });
        const any = try w.o.child(eps, .any, 0);
        var from: std.ArrayList(AV) = .empty;
        try from.appendSlice(w.a, avs);
        try from.append(w.a, callee_av);
        for (from.items) |av| {
            for (try w.expand(av)) |e| {
                const c = w.cells.items[e.cell];
                if (c.kind == .closure or c.kind == .func) continue;
                if (ty) |r| if (c.ty.unwrap()) |ct| if (!try w.o.mayHold(w.store, r, ct, 0)) continue;
                try out.append(w.a, .{ .path = any, .cell = e.cell, .approx = inst.int() + 1, .grown = e.grown });
            }
        }
        return w.norm(out.items);
    }

    /// A `foreign` or `Js` call: its arguments escape, its result is ⊤
    /// (§6.1 item 2).
    fn escapeCall(w: *Walker, inst: Inst.Index, args: []const Inst.Index, name: []const u8) Allocator.Error!AV {
        const avs = try w.evalOperands(args, false);
        w.popPending(avs.len);
        w.use_call = 2;
        defer w.use_call = 0;
        defer w.use_call_at = eps;
        w.point += 1;
        for (args) |x| {
            w.use_call_at = if (try w.refPath(x)) |r| r.path else eps;
            try w.useOperand(x, w.token(inst), &.{});
        }
        w.use_call_at = eps;
        try w.useTemporaries(args, avs, w.token(inst));
        for (avs) |av| {
            try w.sight(av, .{ .no_summary = name }, w.token(inst));
            try w.escape(av, w.point);
        }
        if (!try w.isTracked(inst)) return &.{};
        return w.single(.{ .kind = .top, .a = 0 });
    }

    /// A call of the declaration's own function parameter `j` (§16.4 item
    /// 4): each argument is a supply, owned when it passes the four
    /// conditions at the call, and the result is that parameter's result.
    fn callbackCall(w: *Walker, inst: Inst.Index, j: u32, args: []const Inst.Index, callee: CalleeRef) Allocator.Error!AV {
        const avs = try w.evalOperands(args, true);
        w.popPending(avs.len);
        w.point += 1;
        const tok = w.token(inst);
        for (args) |x| try w.useOperand(x, tok, &.{});
        try w.useCallee(callee, tok);
        try w.useTemporaries(args, avs, tok);
        for (avs) |av| try w.sight(av, .{ .pending = "it is passed to a function parameter, whose class is not known here" }, tok);
        const st = &w.fn_state.items[j];
        st.calls = if (w.recursive or st.calls != .zero) .many else .once;
        w.cb_args[inst.int() - w.decl.inst_start.int()] = try w.unionOf(avs);
        for (avs, 0..) |av, k| {
            if (av.len == 0) continue;
            var others: std.ArrayList(AV) = .empty;
            for (avs, 0..) |x, i| if (i != k) try others.append(w.a, x);
            const probe = try w.probeDemand(inst, av, others.items);
            try w.supplies.append(w.a, .{ .fun = j, .k = @intCast(k), .path = eps, .av = av, .probe = probe, .cond = try w.deepCond(av), .rcond = try w.rdeepCond(av), .rprobe = try w.recordProbe(inst, av, others.items) });
        }
        if (!try w.isTracked(inst)) return &.{};
        return w.single(.{ .kind = .cbres, .a = j, .b = inst.int(), .ty = w.instTypeOpt(inst) });
    }

    /// Keep a lambda parameter's result and borrowed argument supplies.
    fn lambdaCallbackCall(w: *Walker, inst: Inst.Index, j: u32, args: []const Inst.Index, callee: CalleeRef) Allocator.Error!AV {
        const avs = try w.evalOperands(args, true);
        w.popPending(avs.len);
        w.point += 1;
        const tok = w.token(inst);
        for (args) |x| try w.useOperand(x, tok, &.{});
        try w.useCallee(callee, tok);
        try w.useTemporaries(args, avs, tok);
        for (avs) |av| try w.sight(av, .{ .pending = "it is passed to a function parameter, whose class is not known here" }, tok);
        w.cb_args[inst.int() - w.decl.inst_start.int()] = try w.unionOf(avs);
        for (avs, 0..) |av, k| {
            if (av.len == 0) continue;
            try w.supplies.append(w.a, .{ .frame = w.frame, .fun = j, .owned = false, .approx = true, .k = @intCast(k), .path = eps, .av = av, .probe = none, .cond = try w.deepCond(av), .rcond = try w.rdeepCond(av), .rprobe = none });
        }
        if (!try w.isTracked(inst)) return &.{};
        return w.single(.{ .kind = .cbres, .a = j, .b = inst.int(), .scope = w.frame, .ty = w.instTypeOpt(inst) });
    }

    fn callbackFrame(_: *const Walker, c: Cell) u32 {
        return c.scope;
    }

    /// The closure whose body frame `frame` is.
    fn frameClosure(w: *const Walker, frame: u32) ?u32 {
        if (frame == 0) return null;
        var ci = w.closures.items.len;
        while (ci > 0) {
            ci -= 1;
            if (w.closures.items[ci].frame == frame and w.closures.items[ci].params.len > 0) return @intCast(ci);
        }
        return null;
    }

    /// §18.9: a call of the declaration's function parameter `j` inside the
    /// lambda `ci`. Its arguments are probed here, in the lambda; the call
    /// itself is made wherever the lambda runs, where `applyEnvCalls` makes
    /// it a call of `π_j`. The result is that parameter's result.
    fn envCall(w: *Walker, inst: Inst.Index, ci: u32, j: u32, args: []const Inst.Index, callee: CalleeRef) Allocator.Error!AV {
        const avs = try w.evalOperands(args, true);
        w.popPending(avs.len);
        w.point += 1;
        const tok = w.token(inst);
        for (args) |x| try w.useOperand(x, tok, &.{});
        try w.useCallee(callee, tok);
        try w.useTemporaries(args, avs, tok);
        for (avs) |av| try w.sight(av, .{ .pending = "it is passed to a function parameter, whose class is not known here" }, tok);
        w.cb_args[inst.int() - w.decl.inst_start.int()] = try w.unionOf(avs);
        const probes = try w.a.alloc(u32, avs.len);
        for (avs, probes, 0..) |av, *p, k| {
            p.* = none;
            if (av.len == 0) continue;
            var others: std.ArrayList(AV) = .empty;
            for (avs, 0..) |x, i| if (i != k) try others.append(w.a, x);
            p.* = try w.probeDemand(inst, av, others.items);
        }
        try w.env_calls.append(w.a, .{ .closure = ci, .j = j, .inst = inst, .args = avs, .probes = probes });
        if (!try w.isTracked(inst)) return &.{};
        return w.single(.{ .kind = .cbres, .a = j, .b = inst.int(), .ty = w.instTypeOpt(inst) });
    }

    /// Where the lambda `ci` is checked: by callee `s`, handed it as its
    /// parameter `jj` at the call `ctx.inst`, or (`s` null) called here
    /// with `ctx.avs`. Each call it makes of a function parameter of the
    /// declaration becomes a call here, its arguments what the callee
    /// supplies the lambda (§18.9).
    fn applyEnvCalls(w: *Walker, ci: u32, s: ?*const Summary, jj: u32, ctx: InstCtx) Allocator.Error!void {
        // Appending below re-registers a call under an enclosing lambda,
        // which is never `ci`: only the calls present now are this lambda's.
        const n = w.env_calls.items.len;
        for (0..n) |ei| {
            const ec = w.env_calls.items[ei];
            if (ec.closure != ci) continue;
            const st = &w.fn_state.items[ec.j];
            const calls: Calls = if (s) |cs| (if (cs.funOf(jj)) |f| f.calls else .many) else .once;
            if (calls == .zero) continue;
            if (s) |cs| if (cs.funOf(jj)) |f| {
                st.seen = st.seen and f.seen;
            };
            const many = ec.many or calls == .many;
            // §30.9: checked inside another lambda, the call is that lambda's,
            // made wherever it is checked in turn, in its vocabulary.
            const outer: ?u32 = if (w.frame != 0) w.frameClosure(w.frame) else null;
            if (w.frame != 0 and outer == null) {
                st.seen = false;
                continue;
            }
            const args = try w.a.alloc(AV, ec.args.len);
            const probes = try w.a.alloc(u32, ec.args.len);
            const more = try w.a.alloc([]const u32, ec.args.len);
            const owneds = try w.a.alloc(bool, ec.args.len);
            const takens = try w.a.alloc(bool, ec.args.len);
            for (ec.args, ec.probes, 0..) |av, probe, k| {
                args[k] = &.{};
                probes[k] = none;
                more[k] = if (k < ec.more.len) ec.more[k] else &.{};
                owneds[k] = k >= ec.owned.len or ec.owned[k];
                takens[k] = k < ec.taken.len and ec.taken[k];
                if (av.len == 0) continue;
                var owned = owneds[k];
                var taken = takens[k];
                var from: std.ArrayList(u32) = .empty;
                const cells = try w.fromLambda(av, ci, s, jj, ctx, &owned, &taken, &from);
                // Disjoint against every argument but the lambda and the
                // ones the supplied cells come from.
                var others: std.ArrayList(AV) = .empty;
                for (ctx.avs, 0..) |x, i| {
                    if (i == jj or std.mem.indexOfScalar(u32, from.items, @intCast(i)) != null) continue;
                    try others.append(w.a, x);
                }
                const probe2 = if (owned and cells.len > 0) try w.probeDemand(ctx.inst, cells, others.items) else none;
                if (outer != null) {
                    args[k] = cells;
                    probes[k] = probe2;
                    var all: std.ArrayList(u32) = .empty;
                    try all.appendSlice(w.a, more[k]);
                    if (probe != none) try all.append(w.a, probe);
                    more[k] = all.items;
                    owneds[k] = owned;
                    takens[k] = taken;
                    continue;
                }
                const rprobe2 = if (owned and cells.len > 0) try w.recordProbe(ctx.inst, cells, others.items) else none;
                try w.supplies.append(w.a, .{ .fun = ec.j, .k = @intCast(k), .path = eps, .av = cells, .probe = probe, .probe2 = probe2, .more = more[k], .owned = owned, .cond = try w.deepCond(cells), .rcond = try w.rdeepCond(cells), .taken = taken, .rprobe = rprobe2 });
            }
            if (outer) |oc| {
                try w.env_calls.append(w.a, .{ .closure = oc, .j = ec.j, .inst = ec.inst, .args = args, .probes = probes, .more = more, .owned = owneds, .taken = takens, .many = many });
                continue;
            }
            st.calls = if (w.recursive or st.calls != .zero or many) .many else .once;
        }
    }

    /// §30.9: inside a lambda, `av` with each capture of a local of the
    /// declaration's own frame replaced by what that frame holds there, so
    /// that a supply read off at the declaration names its parameters
    /// rather than `⊤`. Elsewhere `av` itself.
    fn declView(w: *Walker, av: AV) Allocator.Error!AV {
        if (w.frame == 0) return av;
        var changed = false;
        var out: std.ArrayList(Entry) = .empty;
        for (av) |e| {
            const c = w.cells.items[e.cell];
            if (c.kind == .env and c.a < w.local_frame.len and w.local_frame[c.a] == 0) if (w.local_av[c.a]) |held| {
                changed = true;
                for (try w.projPath(held, c.path, null)) |h| {
                    try out.append(w.a, .{ .path = try w.o.concat(e.path, h.path), .cell = h.cell, .approx = if (e.approx != 0) e.approx else h.approx, .grown = gJoin(e.grown, h.grown) });
                }
                continue;
            };
            try out.append(w.a, e);
        }
        return if (changed) w.norm(out.items) else av;
    }

    /// A value in lambda `ci`'s vocabulary, in the enclosing body's: its
    /// parameters as the callee supplies them (or as the call passes them),
    /// its captures as the body holds them. `owned` falls when a supply it
    /// rests on is borrowed; `taken` rises when one is destructive.
    fn fromLambda(w: *Walker, av: AV, ci: u32, s: ?*const Summary, jj: u32, ctx: InstCtx, owned: *bool, taken: *bool, from: *std.ArrayList(u32)) Allocator.Error!AV {
        var out: std.ArrayList(Entry) = .empty;
        for (av) |e| {
            const c = w.cells.items[e.cell];
            if (w.lambdaParam(c)) |lp| if (lp[0] == ci) {
                var parts: std.ArrayList(AV) = .empty;
                if (s) |cs| {
                    for (cs.supply) |sp| {
                        if (sp.fun != jj or sp.k != lp[1]) continue;
                        if (!sp.owned) owned.* = false;
                        if (sp.prov.taken) taken.* = true;
                        if (sp.prov.kind == .param) try from.append(w.a, sp.prov.a);
                        const at = try w.composeSupply(sp, try w.instProv(sp.prov, ctx), ctx);
                        try parts.append(w.a, try w.projPath(at, c.path, null));
                    }
                } else if (lp[1] < ctx.avs.len) {
                    try from.append(w.a, lp[1]);
                    try parts.append(w.a, try w.projPath(ctx.avs[lp[1]], c.path, null));
                }
                try out.appendSlice(w.a, try w.under(try w.unionOf(parts.items), e.path));
                continue;
            };
            if (c.kind == .env) {
                const held = w.local_av[c.a] orelse continue;
                try out.appendSlice(w.a, try w.under(try w.projPath(held, c.path, null), e.path));
                continue;
            }
            try out.append(w.a, e);
        }
        return w.norm(out.items);
    }

    /// Whether `s` reads, keeps, returns or writes its parameter `i` at a
    /// path overlapping `q`.
    fn touches(w: *const Walker, s: *const Summary, i: u32, q: u32) bool {
        for (s.uses) |u| {
            if (u.param != i or noUse(u.bits)) continue;
            if (w.o.overlap(u.path, q)) return true;
        }
        return false;
    }

    /// No bits: no use at the call.
    /// No list fact in `bits`: the record bits (`bit_f`, `bit_q`, `bit_k`)
    /// are the record demand's alone.
    fn noUse(bits: u16) bool {
        return bits & list_bits == 0;
    }

    /// §16.4: a call whose callee has a summary.
    fn applySummary(w: *Walker, inst: Inst.Index, callee_in: Callee, args: []const Inst.Index, callee_av: AV, callee_inst: ?CalleeRef) Allocator.Error!AV {
        var callee = callee_in;
        const saved_cast_crossings = w.cast_crossings;
        defer w.cast_crossings = saved_cast_crossings;
        w.cast_crossings = .empty;
        const saved_cast_fold = w.cast_fold_scope;
        defer w.cast_fold_scope = saved_cast_fold;
        w.cast_fold_next += 1;
        w.cast_fold_scope = w.cast_fold_next;
        callee.sum = try w.castSummary(callee.sum, args, inst, callee.poly.len != 0);
        const s = callee.sum;
        // §16.7 (F3, the owner's choice (a)): what the fold reads of this
        // call wherever its summary is instantiated, a callback's supply
        // included.
        const saved_poly = w.call_poly;
        defer w.call_poly = saved_poly;
        const arg_types = try w.a.alloc(?Var, args.len);
        for (args, arg_types) |arg, *t| t.* = w.instType(arg);
        w.call_poly = .{ .inst = inst, .s = s, .poly = callee.poly, .arg_types = arg_types };
        // §23.4: a lambda written at a send position: its parameter there
        // is a send, known before its body is walked.
        for (s.funs) |f| {
            if (f.send == none or f.param >= args.len) continue;
            const arg = args[f.param];
            if (w.bir.instTag(arg) != .lambda) continue;
            const ps = w.bir.extraSlice(w.bir.subRange(@fromBackingInt(@intCast(w.bir.instData(arg).lhs))), Inst.Index);
            if (f.send < ps.len) {
                const at = ps[f.send].int() -% w.decl.inst_start.int();
                if (at < w.send_params.len) w.send_params[at] = true;
            }
        }
        const avs = try w.a.alloc(AV, args.len);
        for (args, avs, 0..) |arg, *v, i| {
            const outer = w.ctx;
            // §25.4: `Maybe.map m f` is walked whole in arm `Just`, `m`
            // included, which is sound only because `isMaybeJoin` keeps `m`
            // and `d` variable paths and `f` a lambda or top-level value —
            // operands whose evaluation writes nothing. Widening any of
            // them must move its evaluation out of the arm.
            if (w.joinArm(inst, i)) |arm| w.ctx = arm;
            if (callee.entry_target) |target| {
                if (try w.hasEntry(target, @intCast(i))) {
                    _ = try w.entryCall(inst, target, arg);
                    v.* = &.{};
                } else v.* = try w.eval(arg);
            } else v.* = try w.eval(arg);
            w.ctx = outer;
            const is_ref = (try w.refPath(arg)) != null;
            try w.pending.append(w.a, .{ .av = v.*, .frame = w.frame, .token = w.token(arg), .is_ref = is_ref, .by_call = true, .consumer = s, .arg = @intCast(i) });
        }
        return w.applySummaryAV(inst, callee, args, avs, callee_av, callee_inst, arg_types);
    }

    // Keep operand recursion out of the frame that discharges a summary's
    // facts. Deep saturated calls need only the small evaluation frame.
    fn applySummaryAV(w: *Walker, inst: Inst.Index, callee: Callee, args: []const Inst.Index, avs: []const AV, callee_av: AV, callee_inst: ?CalleeRef, arg_types: []const ?Var) Allocator.Error!AV {
        const s = callee.sum;
        w.popPending(args.len);
        // The arguments, indexed as the summary's provenances project them
        // (#825); `avs` is not changed below.
        var arg_index: ArgIndex = .{ .avs = avs };
        w.point += 1;
        const tok = w.token(inst);
        const saved_limit_callee = w.limit_callee;
        w.limit_callee = saved_limit_callee or s.limit != .none;
        defer w.limit_callee = saved_limit_callee;
        // 1. Uses, at the paths the callee touches.
        for (args, avs, 0..) |arg, av, i| {
            const pi: u32 = @intCast(i);
            if (try w.refPath(arg)) |r| {
                const outer = w.ctx;
                defer w.ctx = outer;
                if (w.joinArm(inst, i)) |arm| w.ctx = arm;
                w.use_at = .{ w.rootToken(arg), w.token(arg) };
                defer w.use_at = .{ none, none };
                // The callee reads the argument in its own body (§31.4 item 5).
                w.use_call = 1;
                defer w.use_call = 0;
                w.use_call_at = r.path;
                defer w.use_call_at = eps;
                for (s.uses) |u| {
                    if (u.param != pi) continue;
                    const saved_use_grown = w.use_grown;
                    defer w.use_grown = saved_use_grown;
                    w.use_grown = u.grown;
                    // §31.4 item 5: a record the callee reads, for the record
                    // demand alone.
                    // A write alone (`W{F}` with no `R` or `E`) replaces the
                    // fields it names and reads none of them, as an update's
                    // base use does (#405): a holder below a written field
                    // is not used by it, and one below another field is
                    // untouched. Its own demand is the call-site `update`
                    // below (§31.7).
                    if (u.bits & (bit_q | bit_k | bit_f) != 0) {
                        // `W{}` (every field, or fields a block could not
                        // name) stays a use whole.
                        const write_only = u.bits & (bit_q | bit_k) == 0 and u.fields.len != 0;
                        try w.uses.append(w.a, .{
                            .local = r.local,
                            .path = try w.o.concat(r.path, u.path),
                            .except = if (write_only) u.fields else &.{},
                            .point = w.point,
                            .frame = w.frame,
                            .ctx = w.ctx,
                            .token = tok,
                            .call = 1,
                            .call_at = r.path,
                            .record_read = true,
                            .grown = u.grown,
                        });
                    }
                    if (noUse(u.bits)) continue;
                    try w.useAt(r.local, try w.o.concat(r.path, u.path), tok, &.{});
                }
            } else if (w.touches(s, pi, eps)) {
                try w.useCaptures(av, tok);
            }
        }
        if (callee_inst) |c| {
            try w.useCallee(c, tok);
            try w.useTemporaries(&.{c.inst}, &.{callee_av}, tok);
        }
        // §23.3: a function parameter handed to a send position takes the
        // fact before anything the callee keeps of it is looked at.
        if (w.frame == 0) for (s.funs) |f| {
            if (f.send == none or f.param >= args.len) continue;
            if (w.fnParamOf(avs[f.param])) |jj| if (w.fn_state.items[jj].send == none) {
                w.fn_state.items[jj].send = f.send;
            };
        };
        // A lambda called here makes its calls of the declaration's function
        // parameters here (§18.9).
        if (callee.closure != none) {
            try w.applyEnvCalls(callee.closure, null, 0, .{ .inst = inst, .s = s, .avs = avs, .depth = 0 });
            try w.dischargeLambdaNeeds(callee.closure, calledParam, avs);
        }
        // 2. What the callbacks escape, before the callee writes (§16.4 item 4),
        // and what they keep of a parameter the callee writes after (#281).
        for (s.funs) |f| {
            if (!hasActual(s, args.len, f.param)) continue;
            try w.callbackEscapes(inst, s, f.param, avs);
            try w.callbackKeeps(inst, callee, s, args, avs, f.param);
        }
        // §18.4 item 3: what the callee relied on, at the arguments; a
        // failure is reported on the call-site demand of the argument it
        // names, or on a line of its own when there is none.
        const xfail = try w.a.alloc(?Rely, args.len);
        @memset(xfail, null);
        try w.relyReqs(s.xreq, .list, .{ .inst = inst, .s = s, .avs = avs, .closure = callee.closure, .depth = 0, .args = &arg_index }, xfail);
        // 3b. §31.7: a record the callee writes is an `update` demand at the
        // call, on the argument's record objects at the path, with the
        // fields it writes; reported, not enforced (R4). An asserted row
        // never states `bit_f`: a `foreign`'s words are a list's, and a
        // record update is the one write of a record (`language.md` §6.3),
        // which only beni code makes (a sibling's rule, `boundary.md` §4, is a
        // list's); core's rows write lists, and `Record.copy` reads. A pessimistic
        // summary writes every record of every parameter, applied where the
        // argument is one.
        // §31.4 item 6: what the callee relied on of records, at the
        // arguments; a failure is reported on the record demand of the
        // argument it names, or on a record line of its own.
        const rxfail = try w.a.alloc(?Rely, args.len);
        @memset(rxfail, null);
        try w.relyReqs(s.rxreq, .record, .{ .inst = inst, .s = s, .avs = avs, .closure = callee.closure, .depth = 0, .args = &arg_index }, rxfail);
        for (s.uses) |u| {
            if (u.bits & bit_f == 0 or u.param >= args.len) continue;
            if (s.limit != .none and !w.isRecordType(w.instType(args[u.param]))) continue;
            try w.callSiteRecordDemandX(inst, args, avs, callee_av, u.param, u.path, u.fields, if (s.limit != .none) .limit else .exact, rxfail[u.param]);
            rxfail[u.param] = null;
        }
        for (rxfail, 0..) |f, i| {
            const r = f orelse continue;
            const detail = try std.fmt.allocPrint(w.o.out.allocator(), "{s} needs the elements of {s} to hold no record at two positions, and they may", .{ callee.name, try w.baseText(args[i]) });
            try w.demands.append(w.a, .{
                .kind = .value,
                .token = tok,
                .op = "update",
                .base = try w.baseText(args[i]),
                .base_local = none,
                .base_path = eps,
                .point = w.point,
                .frame = w.frame,
                .ctx = w.ctx,
                .element = false,
                .accept = .param,
                .holders = &.{},
                .fixed = .{ .verdict = .{ .rejected = if (r == .limit) .limit else .exclusive }, .detail = detail },
                .prelim = .{ .cause = if (r == .limit) .limit else .exclusive, .detail = detail, .approx = r != .exact },
                .fields = &.{},
            });
        }
        // 3. W: the caller's side of a written parameter.
        const saved_uses = w.call_uses;
        w.call_uses = s.uses;
        defer w.call_uses = saved_uses;
        for (s.uses) |u| {
            if (u.bits & bit_w == 0 or u.param >= args.len) continue;
            const saved_use_grown = w.use_grown;
            defer w.use_grown = saved_use_grown;
            w.use_grown = u.grown;
            // A named writer's line keeps its slice-1 form; any other call
            // names the summary that wrote.
            const note = if (w.mode != .report or s.asserted or std.mem.startsWith(u8, callee.op, "List.")) "" else try std.fmt.allocPrint(w.o.out.allocator(), "{s} writes π{d}{s}", .{ callee.name, u.param + 1, try w.o.pathText(u.path) });
            try w.callSiteDemandDeep(inst, callee.op, args, avs, callee_av, u.param, u.path, note, if (s.limit != .none) .limit else if (u.bits & bit_x == 0) .approx else .exact, xfail[u.param], u.bits & bit_d != 0, u.extent);
            xfail[u.param] = null;
        }
        for (xfail, 0..) |f, i| {
            const r = f orelse continue;
            try w.demands.append(w.a, .{
                .kind = .value,
                .token = tok,
                .op = callee.op,
                .base = try w.baseText(args[i]),
                .base_local = none,
                .base_path = eps,
                .point = w.point,
                .frame = w.frame,
                .ctx = w.ctx,
                .element = false,
                .accept = .param,
                .holders = &.{},
                .fixed = .{ .verdict = .{ .rejected = if (r == .limit) .limit else .exclusive }, .detail = try w.exclusiveText(args[i]) },
                .prelim = .{ .cause = if (r == .limit) .limit else .exclusive, .detail = "", .approx = r != .exact },
            });
        }
        // 4. E, and what the summary keeps of a function value.
        for (s.uses) |u| {
            if (u.bits & (bit_e | bit_j) == 0 or u.param >= args.len) continue;
            const saved_use_grown = w.use_grown;
            defer w.use_grown = saved_use_grown;
            w.use_grown = u.grown;
            const at = try w.projPath(avs[u.param], u.path, null);
            try w.sight(at, .{ .pending = if (w.mode != .report) "" else try std.fmt.allocPrint(w.o.out.allocator(), "{s} keeps it", .{callee.name}) }, tok);
            // Kept only by a function value handed to JavaScript (§18.6):
            // the escape says so.
            if (u.bits & bit_e == 0) try w.escapeWhy(at, w.point, inst) else try w.escape(at, w.point);
        }
        // §31.4 item 2: the record objects the callee keeps, after the
        // writes it makes of them: a write after the call sees the escape.
        for (s.uses) |u| {
            if (u.bits & bit_k == 0 or u.param >= args.len) continue;
            const saved_use_grown = w.use_grown;
            defer w.use_grown = saved_use_grown;
            w.use_grown = u.grown;
            try w.escapeObjects(try w.projPath(avs[u.param], u.path, null), w.point);
        }
        // Callbacks.
        for (s.funs) |f| {
            if (!hasActual(s, args.len, f.param)) continue;
            try w.checkCallback(inst, callee, args, avs, f.param);
        }
        // 5. The result.
        if (callee.entry_target) |target| {
            for (args, 0..) |_, i| if (try w.hasEntry(target, @intCast(i))) return w.entryResult(inst);
        }
        const ty = w.instType(inst);
        if (ty) |v| if (!try w.trackedVar(v)) return &.{};
        const res = try w.instRes(s, .{ .inst = inst, .s = s, .avs = avs, .closure = callee.closure, .depth = 0, .merge_fresh = callee.merge_fresh, .arg_types = arg_types, .result_ty = ty, .take = s.asserted, .poly = callee.poly, .args = &arg_index });
        if (res.len == 0 and callee.merge_fresh) if (ty) |v| switch (w.store.resolvedContent(v)) {
            .structure => |st| if (st == .func) {
                const site: CarrySite = .{ .inst = inst.int(), .sum = @intFromPtr(s), .klass = none, .depth = 0, .ns = 0, .merge = true };
                const g = try w.carry_sites.getOrPut(w.a, site);
                if (!g.found_existing) {
                    const bottom = try w.a.create(Summary);
                    bottom.* = .{ .params = @intCast(w.store.vars(st.func.params).len) };
                    g.value_ptr.* = @intCast(w.closures.items.len);
                    try w.closures.append(w.a, .{ .captures = &.{}, .class = bottom, .token = w.token(inst) });
                }
                return w.single(.{ .kind = .closure, .a = g.value_ptr.* });
            },
            else => {},
        };
        // An approximate entry may name an argument the result's type
        // cannot be (§6.1's type filter, thesis §3.8): a `Js` coercion's
        // result is never its argument at another type.
        const rt = ty orelse return res;
        var kept: std.ArrayList(Entry) = .empty;
        for (res) |e| {
            if (e.path == eps and e.approx != 0) {
                if (w.cells.items[e.cell].ty.unwrap()) |ct| if (!try w.o.mayShare(w.store, rt, ct, 0)) continue;
            }
            try kept.append(w.a, e);
        }
        return kept.items;
    }

    /// §18.4 item 3: a callee's requirements (`xreq`, or `rxreq` for a
    /// record's), discharged at the call; each failure joins `xfail` at the
    /// argument it names. An apart that fails is discharged pair by pair,
    /// so that each pair's failure is put where it was before (§16.7,
    /// #693); one that holds holds for every pair.
    fn relyReqs(w: *Walker, reqs: []const XAtom, fl: Fl, ctx: InstCtx, xfail: []?Rely) Allocator.Error!void {
        for (reqs) |x| {
            const r = try w.relyReq(x, fl, ctx);
            if (r == .ok) continue;
            if (!x.isApart()) {
                const i = xreqParam(x) orelse continue;
                if (i < xfail.len) xfail[i] = Rely.worse(xfail[i], r);
                continue;
            }
            var pairs: std.ArrayList(XAtom) = .empty;
            try expandAtom(w.a, x, &pairs);
            for (sortAtoms(pairs.items)) |p| {
                const pr = try w.relyReq(p, fl, ctx);
                if (pr == .ok) continue;
                const i = xreqParam(p) orelse continue;
                if (i < xfail.len) xfail[i] = Rely.worse(xfail[i], pr);
            }
        }
    }

    fn relyReq(w: *Walker, x: XAtom, fl: Fl, ctx: InstCtx) Allocator.Error!Rely {
        return switch (fl) {
            .list => w.rely(try w.instXSum(.{ .atoms = &.{x} }, ctx), w.frame),
            .record => w.rrely(try w.rinstXSum(.{ .atoms = &.{x} }, ctx), w.frame),
        };
    }

    /// The argument an `xreq` atom names first: a parameter's or a callback's.
    fn xreqParam(x: XAtom) ?u32 {
        for ([_]Prov{ x.a, x.b }) |p| switch (p.kind) {
            .param, .cb => return p.a,
            else => {},
        };
        return null;
    }

    /// A rejection's sentence for contents that may share (§18.4).
    fn exclusiveText(w: *Walker, inst: Inst.Index) Allocator.Error![]const u8 {
        return std.fmt.allocPrint(w.o.out.allocator(), "the elements of {s} may share one list", .{try w.baseText(inst)});
    }

    /// The cells the callbacks handed to this call escape (§16.4 item 4),
    /// joined to Esc just before the call's point, so that a write the
    /// callee makes after calling them sees the escape.
    fn callbackEscapes(w: *Walker, inst: Inst.Index, s: *const Summary, j: u32, avs: []const AV) Allocator.Error!void {
        const classes = try w.classesOf((try w.actualOf(s, avs, j)) orelse return);
        for (classes) |cls| {
            const c = (try w.callbackSummary(cls, j, .{ .inst = inst, .s = s, .avs = avs, .depth = 0 })) orelse continue;
            for (c.uses) |u| {
                // §31.4 item 2: the record objects the callback keeps escape,
                // at the path it keeps: a record kept whole (`bit_k`, or a
                // list's `E` at its path) is kept whole, written before or
                // after; a field kept keeps the field's, not the record's.
                if (u.bits & (bit_k | bit_e | bit_j) != 0) for ([_][]const SupplyEntry{ s.supply, s.rsupply }) |entries| for (entries) |e| {
                    if (e.prov.condition_only or e.fun != j or e.k != u.param or !w.o.overlap(e.path, u.path)) continue;
                    const cells = try w.keptCells(e.prov, inst, s, avs);
                    const at = if (try w.o.suffix(e.path, u.path)) |rest| try w.projPath(cells, rest, null) else cells;
                    try w.escapeObjects(at, w.point - 1);
                };
                if (u.bits & (bit_e | bit_j) == 0) continue;
                for (s.supply) |e| {
                    if (e.prov.condition_only or e.fun != j or e.k != u.param or !w.o.overlap(e.path, u.path)) continue;
                    const cells = try w.keptCells(e.prov, inst, s, avs);
                    // A callback that keeps a part below what it is handed
                    // keeps that part, not the whole: a callee's own `E` is
                    // read the same way (§16.4 item 4, amended for #749).
                    const rest = (try w.o.suffix(e.path, u.path)) orelse eps;
                    try w.escape(if (rest == eps) cells else try w.projPath(cells, rest, null), w.point - 1);
                }
            }
            if (cls == .closure) try w.escapeCaptures(cls.closure, w.point - 1);
        }
    }

    /// §16.4's keep edge (amended for #281): the callee hands the actual for
    /// πⱼ its parameter `πᵢ.q″` borrowed — it uses it after the call — and
    /// writes `πᵢ`; an actual that may keep its parameter in its result has
    /// that result hold the list the callee then changes. Rejected, cause
    /// `supply`; an actual with no class may keep anything (approximate);
    /// the caller's own function parameter is asked to return owned, which
    /// no function that keeps a borrowed supply does.
    fn callbackKeeps(w: *Walker, inst: Inst.Index, callee: Callee, s: *const Summary, args: []const Inst.Index, avs: []const AV, j: u32) Allocator.Error!void {
        for (s.supply, 0..) |e, ei| {
            if (e.fun != j or e.owned or e.prov.kind != .param) continue;
            var writers: std.ArrayList(u32) = .empty;
            const written = for (s.uses) |u| {
                if (u.param == e.prov.a and u.bits & bit_w != 0 and w.o.writeOverlap(u.path, e.prov.path, u.extent)) break true;
            } else try w.writtenByCallback(s, avs, e, ei, &writers);
            if (!written and writers.items.len == 0) continue;
            const actual = (try w.actualOf(s, avs, j)) orelse continue;
            if (w.fnParamOf(actual) orelse try w.slotOf(actual)) |jj| {
                if (written) {
                    w.fn_state.items[jj].need = true;
                    w.fn_state.items[jj].need_edit = true;
                } else for (writers.items) |writer| {
                    if (std.mem.indexOfScalar(u32, w.fn_state.items[jj].need_if.items, writer) == null)
                        try w.fn_state.items[jj].need_if.append(w.a, writer);
                }
                continue;
            }
            const classes = try w.classesOf(actual);
            var keeps = classes.len == 0;
            for (classes) |cls| {
                const c = (try w.classSummary(cls)) orelse {
                    keeps = true;
                    break;
                };
                for (c.res) |r| switch (r.prov.kind) {
                    .param => if (r.prov.a == e.k) {
                        keeps = true;
                    },
                    // What it returns of its own callbacks or of JavaScript
                    // may be what it was handed.
                    .cb, .top => keeps = true,
                    else => {},
                };
            }
            if (!keeps) continue;
            const why = try std.fmt.allocPrint(w.o.out.allocator(), "{s} changes what it hands this function ({s}) after the call, itself or through another function, and the function's result may keep it", .{ callee.name, try w.o.provText(e.prov) });
            const arg = if (j < args.len) args[j] else inst;
            try w.demands.append(w.a, .{
                .kind = .value,
                .token = w.token(arg),
                .op = "value",
                .base = try w.baseText(arg),
                .base_local = none,
                .base_path = eps,
                .point = w.point,
                .frame = w.frame,
                .ctx = w.ctx,
                .element = false,
                .accept = .callback_param,
                .holders = &.{},
                .fixed = .{ .verdict = .{ .rejected = .supply }, .detail = why },
                // The summary does not say that the change comes after the
                // call, only that `πᵢ` is used after it: approximate.
                .prelim = .{ .cause = .supply, .detail = why, .approx = true },
            });
            // One line per callback, as the supply edge reports.
            return;
        }
    }

    /// Whether the callee hands `πᵢ` of supply `e` (index `ei`) to another
    /// callback too, whose actual writes it: a class that writes the part
    /// supplied, one with no class, or the caller's own function parameter,
    /// whose writes are decided outside (#281). Those symbolic writers
    /// are collected as guards instead of forcing an unconditional need.
    fn writtenByCallback(w: *Walker, s: *const Summary, avs: []const AV, e: SupplyEntry, ei: usize, writers: *std.ArrayList(u32)) Allocator.Error!bool {
        for (s.supply, 0..) |x, xi| {
            if (xi == ei or x.prov.kind != .param or x.prov.a != e.prov.a or !w.o.overlap(x.prov.path, e.prov.path)) continue;
            const actual = (try w.actualOf(s, avs, x.fun)) orelse continue;
            if (w.fnParamOf(actual) orelse try w.slotOf(actual)) |writer| {
                if (std.mem.indexOfScalar(u32, writers.items, writer) == null) try writers.append(w.a, writer);
                continue;
            }
            const classes = try w.classesOf(actual);
            if (classes.len == 0) return true;
            for (classes) |cls| {
                const c = (try w.classSummary(cls)) orelse return true;
                for (c.uses) |u| {
                    if (u.param != x.k or u.bits & bit_w == 0 or !w.o.writeOverlap(u.path, x.path, u.extent)) continue;
                    // Translate the other callback's write to the callee's
                    // parameter before comparing it with the kept loan.
                    var written = x.prov.path;
                    if (try w.o.suffix(x.path, u.path)) |rest| written = try w.o.concat(written, rest);
                    if (w.o.writeOverlap(written, e.prov.path, u.extent)) return true;
                }
            }
        }
        return false;
    }

    /// A supply's provenance instantiated for the callback it is handed to.
    /// A cell the callee made and also returns keeps its fresh number, and
    /// is the cell the result names: `own` is the context the callee's
    /// result is instantiated in (depth 0 at a call written in the body,
    /// `ctx.depth` for a callee instantiated inside another). Any other new
    /// cell is one of the callback's depth (`deeper`). So a callback that
    /// keeps it keeps the list the caller gets back (#281).
    fn supplyCells(w: *Walker, p: Prov, own: InstCtx, deeper: InstCtx) Allocator.Error!AV {
        if ((p.kind == .fresh or p.kind == .esc) and p.a != 0) return w.instProv(p, own);
        return w.instProv(p, deeper);
    }

    /// What a callback handed to the call at `inst` keeps of a supply, as the
    /// cells the caller holds after the call (`callbackEscapes`). A supply of
    /// what a callback returned before is that callback's result as the
    /// call's own result names it: instantiated at the call's depth, so its
    /// cells are the ones the caller gets back, with the cells it made at
    /// the callback's depth. Instantiated one depth further, its made cells
    /// would be another namespace's, which the caller never holds, and an
    /// escape of a value below its root would be lost (#749).
    fn keptCells(w: *Walker, p: Prov, inst: Inst.Index, s: *const Summary, avs: []const AV) Allocator.Error!AV {
        const own: InstCtx = .{ .inst = inst, .s = s, .avs = avs, .depth = 0 };
        if (p.kind == .cb) return w.instProv(p, own);
        return w.supplyCells(p, own, .{ .inst = inst, .s = s, .avs = avs, .depth = 1 });
    }

    /// What a lambda escaped of the cells it captured, joined to Esc where
    /// the lambda runs.
    fn escapeCaptures(w: *Walker, ci: u32, at: u32) Allocator.Error!void {
        for (w.closures.items[ci].env_escapes) |cap| {
            const held = w.local_av[cap.local] orelse continue;
            try w.escape(try w.projPath(held, cap.path, null), at);
        }
    }

    /// Result, effect and ownership queries must read the same specialised
    /// class. This query does not compose an entry or cross a growing call.
    fn callbackSummary(w: *Walker, cls: Class, j: u32, ctx: InstCtx) Allocator.Error!?*const Summary {
        const original = (try w.classSummary(cls)) orelse return null;
        if (original.cast_signature == none) return original;
        const ty = (try w.callbackType(j, ctx)) orelse return original;
        return try w.castFunctionSummary(original, ty, false);
    }

    fn classSummary(w: *Walker, cls: Class) Allocator.Error!?*const Summary {
        return switch (cls) {
            .closure => |ci| w.closures.items[ci].class,
            .func => |t| w.o.ensureSummary(t.m, t.d),
            .send => &send_class,
        };
    }

    const callback_ns_stride: u32 = 1000;
    /// §31.7: where a summary's record objects are numbered from, below
    /// `callback_ns_stride`, above the lists' fresh numbers a summary uses.
    /// One that met a list's number would only wrap the list's result cell
    /// in its object alone (`instProv`), which no list's fact reads.
    const obj_fresh_base: u32 = 500;
    /// Where a call inside the group being solved numbers a member's
    /// annotations, one per result path (`instResProv`): above every fresh,
    /// object and callback number.
    const annotation_ns: u32 = 1 << 30;

    const InstCtx = struct {
        inst: Inst.Index,
        s: *const Summary,
        avs: []const AV,
        /// A lambda's class: its closure, whose captures `◇` names.
        closure: u32 = none,
        depth: u32,
        /// A callback's result being instantiated, and what it stands for
        /// so far: a fold hands its callback its own previous result.
        self_j: u32 = none,
        self_av: AV = &.{},
        /// The callee is in the recursive group being solved: its fresh
        /// cells are one cell per call, so the numbering stays finite.
        merge_fresh: bool = false,
        /// §20.4: the functions an entry instantiates at one call number
        /// their fresh cells apart.
        fresh_ns: u32 = 0,
        /// §20.4: the fixpoint's rounds compute cells only; the round that
        /// settles lowers their conditions once.
        conds: bool = true,
        /// Condition rounds cannot record speculative escapes or diagnostics.
        effects: bool = true,
        /// At the call itself: the arguments' types and the result's.
        arg_types: []const ?Var = &.{},
        arg_refs: []const TyRef = &.{},
        result_ref: ?TyRef = null,
        result_ty: ?Var = null,
        /// Allocations represented by fresh result provenance while computing
        /// a callback's shape. Supplies and projected arrivals do not add cells.
        callback_fresh: ?*std.ArrayList(u32) = null,
        /// The traversal primitive's own result: a taken element stays
        /// taken (§18.5). Anywhere else a supply or result that names one
        /// instantiates to the element itself.
        take: bool = false,
        /// §16.7 (F3, choice (a)): the callee's declared parameter types, when
        /// it is a member of the group being solved.
        poly: []const ?Var = &.{},
        /// §20.4 (#825): the arguments indexed by first step, when the
        /// instantiation's maker keeps them (`projArg`). Checked against
        /// `avs` before it is used.
        args: ?*ArgIndex = null,
    };

    /// `s.res` instantiated at the call (§16.4 item 6).
    /// §31.7: the number record object `c` takes in this summary: the next
    /// one when it has none yet, kept in `obj_number` for the read-off
    /// `obj_gen` names. §16.6: an object a member of this recursive group made
    /// keeps the number the member gave it, at a call of it, so that the
    /// group's rounds settle; two objects that number may make one are
    /// one, which refuses more and never less.
    fn objectNumber(w: *Walker, next: *u32, c: u32) Allocator.Error!u32 {
        const x = w.cells.items[c];
        if (w.recursive and x.kind == .result and x.b >= obj_fresh_base and x.b < callback_ns_stride) return x.b;
        if (w.obj_number.items.len <= c) try w.obj_number.appendNTimes(w.a, .{ 0, 0 }, c + 1 - w.obj_number.items.len);
        const n = &w.obj_number.items[c];
        if (n[0] == w.obj_gen) return n[1];
        next.* += 1;
        n.* = .{ w.obj_gen, next.* };
        return next.*;
    }

    /// §31.7: cell `c` as a cell no list's fact reads: itself when it is
    /// one, else its copy with `nonlist`, which the cell key tells apart
    /// and which escapes with it (`escKey` does not read the flag).
    fn nonlistOf(w: *Walker, c: u32) Allocator.Error!u32 {
        std.debug.assert(!w.cells.items[c].condition_only);
        const x = w.cells.items[c];
        // An updated record's cell faces its base's lists (`listFacing`):
        // its object alone.
        if (x.kind == .except) return if (w.listFacing(c) == null) c else w.exceptCell(c, &.{}, true);
        if (x.nonlist) return c;
        var y = x;
        y.nonlist = true;
        return w.cell(y);
    }

    fn objectView(w: *Walker, cells: AV) Allocator.Error!AV {
        var own: std.ArrayList(Entry) = .empty;
        for (cells) |e| {
            if (w.cells.items[e.cell].condition_only) continue;
            try own.append(w.a, .{ .path = e.path, .cell = try w.nonlistOf(e.cell), .approx = e.approx, .grown = e.grown });
        }
        return own.items;
    }

    /// Full structural identity, shared by casts and cached summaries. The
    /// dense memo avoids walking a shared type term once per occurrence.
    const CastBindings = std.ArrayList([2]u32);
    const CastCross = struct { path: u32, prov: Prov };
    const CastFoldKey = struct { scope: u32, id: u32 };

    fn castFoldPath(w: *Walker, path: u32) ?u32 {
        return w.cast_fold_paths.get(.{ .scope = w.cast_fold_scope, .id = path });
    }

    /// Fold every type coordinate belonging to an already crossed entry,
    /// including its source and condition paths. The result placement is
    /// left for composeRes, which retains its exact pre-fold path.
    fn foldCastMembers(w: *Walker, comptime T: type, value: T, apply: bool, changed: *bool) Allocator.Error!T {
        switch (@typeInfo(T)) {
            .@"struct" => |s| {
                var out = value;
                inline for (s.field_names, s.field_types) |name, FT| {
                    if (comptime std.mem.eql(u8, name, "path") and FT == u32) {
                        if (w.castFoldPath(@field(value, name))) |path| {
                            changed.* = true;
                            if (apply) @field(out, name) = path;
                        }
                    } else @field(out, name) = try w.foldCastMembers(FT, @field(value, name), apply, changed);
                }
                return out;
            },
            .pointer => |p| {
                if (p.size != .slice) return value;
                if (@typeInfo(p.child) != .@"struct" and @typeInfo(p.child) != .pointer) return value;
                if (!apply) {
                    for (value) |v| _ = try w.foldCastMembers(p.child, v, false, changed);
                    return value;
                }
                const out = try w.a.alloc(p.child, value.len);
                for (value, out) |v, *x| x.* = try w.foldCastMembers(p.child, v, true, changed);
                return out;
            },
            else => return value,
        }
    }

    /// Carried bodies are instantiated by this call too, even when they
    /// will only be invoked later. Their entries record the crossing now;
    /// immediate entries record it when composed into their actual cells.
    fn foldCastRows(w: *Walker, comptime T: type, value: T, deferred: bool) Allocator.Error!T {
        // Uses compose at the call itself, rather than at a returned place.
        if (T == UseEntry) {
            var changed = false;
            var out = try w.foldCastMembers(T, value, gMarked(value.grown), &changed);
            if (changed) {
                out.grown |= 1;
                if (gMarked(value.grown)) out.bits &= ~bit_x;
            }
            return out;
        }

        if (T == ResEntry or T == SupplyEntry) {
            var changed = false;
            var out = try w.foldCastMembers(T, value, gMarked(value.grown), &changed);
            if (!deferred) out.path = value.path;
            if (changed) {
                if (deferred) {
                    out.grown |= 1;
                    if (gMarked(value.grown)) out.approx = true;
                } else try w.cast_crossings.put(w.a, .{ .path = out.path, .prov = out.prov }, {});
            }
            return out;
        }
        switch (@typeInfo(T)) {
            .@"struct" => |s| {
                var out = value;
                inline for (s.field_names, s.field_types) |name, FT| @field(out, name) = try w.foldCastRows(FT, @field(value, name), deferred or T == Carried);
                if (T == Summary) {
                    if (deferred) {
                        if (w.cast_fold_types.get(.{ .scope = w.cast_fold_scope, .id = value.cast_signature })) |ty| {
                            out.cast_grown |= 1;
                            if (gMarked(value.cast_grown)) out.cast_signature = ty;
                        }
                    }
                    for ([_][]const ResEntry{ out.res, out.objs }) |entries| std.mem.sort(ResEntry, @constCast(entries), {}, struct {
                        fn less(_: void, x: ResEntry, y: ResEntry) bool {
                            return x.path < y.path;
                        }
                    }.less);
                }
                return out;
            },
            .pointer => |p| {
                if (p.size == .one and p.child == Summary) {
                    const out = try w.a.create(Summary);
                    out.* = try w.foldCastRows(Summary, value.*, deferred);
                    return out;
                }
                if (p.size != .slice) return value;
                if (@typeInfo(p.child) != .@"struct" and @typeInfo(p.child) != .pointer) return value;
                const out = try w.a.alloc(p.child, value.len);
                for (value, out) |v, *x| x.* = try w.foldCastRows(p.child, v, deferred);
                return out;
            },
            else => return value,
        }
    }

    fn castParts(w: *Walker, key: []const u8) Allocator.Error![]const CastPart {
        return w.o.castParts(try w.o.castId(key));
    }

    const CastField = struct { name: []const u8, key: u32 };

    fn castFields(w: *Walker, key: []const u8) Allocator.Error![]const CastField {
        const parts = try w.castParts(key);
        const fields = try w.a.alloc(CastField, parts.len - 1);
        var at: usize = "record(".len;
        for (fields, parts[0..fields.len]) |*field, part| {
            const colon = std.mem.indexOfScalarPos(u8, key, at, ':').?;
            const len = std.fmt.parseInt(usize, key[at..colon], 10) catch unreachable;
            field.* = .{ .name = key[colon + 1 ..][0..len], .key = part.key };
            at = part.end;
        }
        return fields;
    }

    /// Row substitution has the same canonical form as a solved store row:
    /// all extension fields flattened and all labels in text order.
    fn castRecord(w: *Walker, fields_in: []const CastField, ext_in: u32) Allocator.Error!u32 {
        var fields: std.ArrayList(CastField) = .empty;
        try fields.appendSlice(w.a, fields_in);
        var ext = ext_in;
        while (std.mem.startsWith(u8, w.o.cast_types.items[ext], "record(")) {
            const key = w.o.cast_types.items[ext];
            try fields.appendSlice(w.a, try w.castFields(key));
            const parts = try w.castParts(key);
            ext = parts[parts.len - 1].key;
        }
        if (fields.items.len == 0) return ext;
        std.mem.sort(CastField, fields.items, {}, struct {
            fn less(_: void, x: CastField, y: CastField) bool {
                return std.mem.lessThan(u8, x.name, y.name);
            }
        }.less);
        var b: std.Io.Writer.Allocating = .init(w.a);
        b.writer.writeAll("record(") catch return error.OutOfMemory;
        for (fields.items) |field| {
            b.writer.print("{d}:{s}=", .{ field.name.len, field.name }) catch return error.OutOfMemory;
            writeCastRef(&b.writer, field.key) catch return error.OutOfMemory;
        }
        b.writer.writeByte('|') catch return error.OutOfMemory;
        writeCastRef(&b.writer, ext) catch return error.OutOfMemory;
        b.writer.writeByte(')') catch return error.OutOfMemory;
        return w.o.castId(b.written());
    }

    fn bindCastRecord(w: *Walker, pattern: []const u8, actual: []const u8, bindings: *CastBindings) Allocator.Error!void {
        const pf = try w.castFields(pattern);
        const af = try w.castFields(actual);
        var rest: std.ArrayList(CastField) = .empty;
        for (af) |field| {
            for (pf) |p| {
                if (!std.mem.eql(u8, p.name, field.name)) continue;
                try w.bindCast(p.key, field.key, bindings);
                break;
            } else try rest.append(w.a, field);
        }
        const pp = try w.castParts(pattern);
        const ap = try w.castParts(actual);
        try w.bindCast(pp[pp.len - 1].key, try w.castRecord(rest.items, ap[ap.len - 1].key), bindings);
    }

    fn bindCast(w: *Walker, pattern: u32, actual: u32, bindings: *CastBindings) Allocator.Error!void {
        if (pattern == actual) return;
        const key = w.o.cast_types.items[pattern];
        if (std.mem.startsWith(u8, key, "var(")) {
            for (bindings.items) |*binding| if (binding[0] == pattern) {
                // A merged view may disagree with another occurrence. It
                // cannot regain the caller's exact variable at recursion.
                if (binding[1] != actual) binding[1] = try w.o.castId("⋆");
                return;
            };
            try bindings.append(w.a, .{ pattern, actual });
            return;
        }
        const actual_key = w.o.cast_types.items[actual];
        if (std.mem.startsWith(u8, key, "record(") and std.mem.startsWith(u8, actual_key, "record(")) return w.bindCastRecord(key, actual_key, bindings);
        const ph = std.mem.indexOfScalar(u8, key, '(') orelse return;
        const ah = std.mem.indexOfScalar(u8, actual_key, '(') orelse return;
        if (!std.mem.eql(u8, key[0..ph], actual_key[0..ah])) return;
        const p = try w.castParts(key);
        const a = try w.castParts(w.o.cast_types.items[actual]);
        if (p.len != a.len) return;
        for (p, a) |x, y| try w.bindCast(x.key, y.key, bindings);
    }

    fn substCast(w: *Walker, id: u32, bindings: *const CastBindings) Allocator.Error!u32 {
        if (!w.o.cast_open.items[id]) return id;
        if (id < w.cast_subst_types.items.len and w.cast_subst_types.items[id] != none) return w.cast_subst_types.items[id];
        for (bindings.items) |binding| if (binding[0] == id) {
            if (w.cast_fold_mode and std.mem.indexOfScalar(u32, w.cast_growing, id) != null) return w.o.castId("⋆");
            return binding[1];
        };
        const key = w.o.cast_types.items[id];
        const parts = try w.castParts(key);
        if (parts.len == 0) return id;
        if (std.mem.startsWith(u8, key, "record(")) {
            const fields = try w.a.dupe(CastField, try w.castFields(key));
            for (fields) |*field| field.key = try w.substCast(field.key, bindings);
            const out = try w.castRecord(fields, try w.substCast(parts[parts.len - 1].key, bindings));
            try w.memoCastSubst(&w.cast_subst_types, &w.cast_subst_touched_types, id, out);
            return out;
        }
        var b: std.Io.Writer.Allocating = .init(w.a);
        var at: usize = 0;
        for (parts) |part| {
            b.writer.writeAll(key[at..part.start]) catch return error.OutOfMemory;
            writeCastRef(&b.writer, try w.substCast(part.key, bindings)) catch return error.OutOfMemory;
            at = part.end;
        }
        b.writer.writeAll(key[at..]) catch return error.OutOfMemory;
        const out = try w.o.castId(b.written());
        try w.memoCastSubst(&w.cast_subst_types, &w.cast_subst_touched_types, id, out);
        return out;
    }

    /// Re-key every path-bearing field, including atoms and carried classes.
    /// Only a field literally named path (or a function-slot path) is a path;
    /// provenance numbers and declaration indices are never substituted.
    fn substCastValue(w: *Walker, comptime T: type, value: T, bindings: *const CastBindings) Allocator.Error!T {
        switch (@typeInfo(T)) {
            .@"struct" => |s| {
                var out = value;
                inline for (s.field_names, s.field_types) |name, FT| {
                    if (comptime std.mem.eql(u8, name, "path") and FT == u32) {
                        @field(out, name) = try w.substCastPath(@field(value, name), bindings);
                    } else if (comptime std.mem.eql(u8, name, "cast_signature")) {
                        @field(out, name) = if (@field(value, name) == none) none else try w.substCast(@field(value, name), bindings);
                    } else @field(out, name) = try w.substCastValue(FT, @field(value, name), bindings);
                }
                if (T == Summary) {
                    std.mem.sort(ResEntry, @constCast(out.res), {}, struct {
                        fn less(_: void, x: ResEntry, y: ResEntry) bool {
                            return x.path < y.path;
                        }
                    }.less);
                    std.mem.sort(ResEntry, @constCast(out.objs), {}, struct {
                        fn less(_: void, x: ResEntry, y: ResEntry) bool {
                            return x.path < y.path;
                        }
                    }.less);
                }
                return out;
            },
            .pointer => |p| {
                if (p.size == .one and p.child == Summary) {
                    const out = try w.a.create(Summary);
                    out.* = try w.substCastValue(Summary, value.*, bindings);
                    return out;
                }
                if (p.size != .slice) return value;
                if (T == []const [2]u32) {
                    const out = try w.a.dupe([2]u32, value);
                    for (out) |*slot| slot[1] = try w.substCastPath(slot[1], bindings);
                    return out;
                }
                if (@typeInfo(p.child) != .@"struct" and @typeInfo(p.child) != .pointer) return value;
                const out = try w.a.alloc(p.child, value.len);
                for (value, out) |v, *x| x.* = try w.substCastValue(p.child, v, bindings);
                return out;
            },
            else => return value,
        }
    }

    fn memoCastSubst(w: *Walker, memo: *std.ArrayList(u32), touched: *std.ArrayList(u32), id: u32, out: u32) Allocator.Error!void {
        if (id >= memo.items.len) {
            const start = memo.items.len;
            try memo.resize(w.a, @max(id + 1, 2 * start));
            @memset(memo.items[start..], none);
        }
        memo.items[id] = out;
        try touched.append(w.a, id);
    }

    fn substCastPath(w: *Walker, path: u32, bindings: *const CastBindings) Allocator.Error!u32 {
        if (path == eps) return eps;
        if (path < w.cast_subst_paths.items.len and w.cast_subst_paths.items[path] != none) return w.cast_subst_paths.items[path];
        const kind = w.o.paths.kind.items[path];
        const arg = w.o.paths.arg.items[path];
        const parent = try w.substCastPath(w.o.paths.parent.items[path], bindings);
        const typed = kind == .cast or kind == .cast_level;
        const new_arg = if (typed) try w.substCast(arg, bindings) else arg;
        const out = try w.o.child(parent, kind, new_arg);
        try w.memoCastSubst(&w.cast_subst_paths, &w.cast_subst_touched_paths, path, out);
        return out;
    }

    fn castSummary(w: *Walker, s: *const Summary, args: []const Inst.Index, inst: Inst.Index, group: bool) Allocator.Error!*const Summary {
        if (s.cast_signature == none) return s;
        const parts = try w.castParts(w.o.cast_types.items[s.cast_signature]);
        if (parts.len != args.len + 1) return s;
        var bindings: CastBindings = .empty;
        for (args, parts[0..args.len]) |arg, part| if (w.instType(arg)) |v| try w.bindCast(part.key, try w.castType(v), &bindings);
        if (w.instType(inst)) |v| try w.bindCast(parts[args.len].key, try w.castType(v), &bindings);
        return w.specializeCasts(s, &bindings, group);
    }

    fn castFunctionSummary(w: *Walker, s: *const Summary, ty: TyRef, group: bool) Allocator.Error!*const Summary {
        if (s.cast_signature == none) return s;
        var bindings: CastBindings = .empty;
        try w.bindCast(s.cast_signature, try w.castTypeRef(ty), &bindings);
        return w.specializeCasts(s, &bindings, group);
    }

    fn specializeCasts(w: *Walker, s: *const Summary, bindings: *const CastBindings, group: bool) Allocator.Error!*const Summary {
        if (bindings.items.len == 0) return s;
        var growing: std.ArrayList(u32) = .empty;
        if (group) for (bindings.items) |binding| {
            const key = w.o.cast_types.items[binding[1]];
            if (w.o.cast_open.items[binding[1]] and !std.mem.startsWith(u8, key, "var(")) try growing.append(w.a, binding[0]);
        };
        defer {
            for (w.cast_subst_touched_types.items) |id| w.cast_subst_types.items[id] = none;
            for (w.cast_subst_touched_paths.items) |id| w.cast_subst_paths.items[id] = none;
            w.cast_subst_touched_types.clearRetainingCapacity();
            w.cast_subst_touched_paths.clearRetainingCapacity();
        }
        const out = try w.a.create(Summary);
        out.* = try w.substCastValue(Summary, s.*, bindings);
        if (growing.items.len != 0) {
            const old_types = try w.a.dupe(u32, w.cast_subst_touched_types.items);
            const exact_types = try w.a.alloc(u32, old_types.len);
            for (old_types, exact_types) |ty, *x| x.* = w.cast_subst_types.items[ty];
            const old_paths = try w.a.dupe(u32, w.cast_subst_touched_paths.items);

            const exact = try w.a.alloc(u32, old_paths.len);
            for (old_paths, exact) |path, *x| x.* = w.cast_subst_paths.items[path];
            for (w.cast_subst_touched_types.items) |id| w.cast_subst_types.items[id] = none;
            for (old_paths) |path| w.cast_subst_paths.items[path] = none;
            w.cast_subst_touched_types.clearRetainingCapacity();
            w.cast_subst_touched_paths.clearRetainingCapacity();
            w.cast_fold_mode = true;
            w.cast_growing = growing.items;
            defer w.cast_fold_mode = false;
            defer w.cast_growing = &.{};
            for (old_types, exact_types) |ty, et| {
                const ft = try w.substCast(ty, bindings);
                if (et == ft) continue;
                const gop = try w.cast_fold_types.getOrPut(w.a, .{ .scope = w.cast_fold_scope, .id = et });
                if (!gop.found_existing) gop.value_ptr.* = ft else if (gop.value_ptr.* != ft) gop.value_ptr.* = try w.o.castId("⋆");
            }
            for (old_paths, exact) |path, ep| {
                const fp = try w.substCastPath(path, bindings);
                if (ep == fp) continue;
                const gop = try w.cast_fold_paths.getOrPut(w.a, .{ .scope = w.cast_fold_scope, .id = ep });
                if (!gop.found_existing) gop.value_ptr.* = fp else if (gop.value_ptr.* != fp) gop.value_ptr.* = try w.o.child(eps, .any, 1);
            }
            out.* = try w.foldCastRows(Summary, out.*, false);
        }
        return out;
    }

    fn seedCastVars(w: *Walker) Allocator.Error!void {
        if (w.cast_seeded) return;
        w.cast_seeded = true;
        const scope: [2]u32 = .{ w.m, w.decl_index };
        if (w.o.cast_scopes.get(scope)) |vars| {
            w.cast_ordinals = vars;
            return;
        }
        w.cast_vars = try w.a.alloc(u32, w.store.descriptors.len);
        w.cast_seen = try w.a.alloc(bool, w.store.descriptors.len);
        @memset(w.cast_vars, none);
        @memset(w.cast_seen, false);
        const module = w.o.in.modules[w.m];
        if (w.decl_index < module.decl_display.len) if (module.decl_display[w.decl_index].unwrap()) |v| try w.visitCastVars(v);
        // BIR order supplies stable identities for variables introduced locally.
        for (w.decl.inst_start.int()..w.decl.inst_end.int()) |i| if (i < w.inst_type.len) if (w.inst_type[i].unwrap()) |v| try w.visitCastVars(v);
        for (w.local_type) |t| if (t.unwrap()) |v| try w.visitCastVars(v);
        const vars = try w.o.keep.allocator().alloc(u32, w.cast_next);
        for (w.cast_vars, 0..) |ordinal, root| if (ordinal != none) {
            vars[ordinal] = @intCast(root);
        };
        try w.o.cast_scopes.put(w.o.in.gpa, scope, vars);
        w.cast_ordinals = vars;
    }

    fn visitCastVars(w: *Walker, v: Var) Allocator.Error!void {
        const root = w.store.find(v);
        if (w.cast_seen[root.int()]) return;
        w.cast_seen[root.int()] = true;
        switch (w.store.resolvedContent(root)) {
            .flex, .rigid => {
                w.cast_vars[root.int()] = w.cast_next;
                w.cast_next += 1;
            },
            .structure => |s| switch (s) {
                .app => |app| {
                    for (w.store.vars(app.args)) |arg| try w.visitCastVars(arg);
                },
                .tuple => |range| {
                    for (w.store.vars(range)) |arg| try w.visitCastVars(arg);
                },
                .func => |f| {
                    for (w.store.vars(f.params)) |arg| try w.visitCastVars(arg);
                    try w.visitCastVars(f.result);
                },
                .record => |r| {
                    var all: std.ArrayList(TypeStore.Field) = .empty;
                    try all.appendSlice(w.a, w.store.fields(r.fields));
                    var ext = r.ext;
                    while (true) {
                        const ec = w.store.resolvedContent(ext);
                        if (ec != .structure or ec.structure != .record) break;
                        try all.appendSlice(w.a, w.store.fields(ec.structure.record.fields));
                        ext = ec.structure.record.ext;
                    }
                    const fields = all.items;
                    std.mem.sort(TypeStore.Field, fields, w.o.in.interner, struct {
                        fn less(pool: *const InternPool.Global, x: TypeStore.Field, y: TypeStore.Field) bool {
                            return std.mem.lessThan(u8, pool.slice(x.name), pool.slice(y.name));
                        }
                    }.less);
                    for (fields) |field| try w.visitCastVars(field.value);
                    try w.visitCastVars(ext);
                },
                .unit, .empty_record => {},
            },
            .alias => unreachable,
            .err => {},
        }
    }

    fn openCastPath(w: *Walker, path: u32) bool {
        var at = path;
        while (at != eps) : (at = w.o.paths.parent.items[at]) {
            const kind = w.o.paths.kind.items[at];
            if ((kind == .cast or kind == .cast_level) and w.o.cast_open.items[w.o.paths.arg.items[at]]) return true;
        }
        return false;
    }

    fn hasOpenCast(w: *Walker, comptime T: type, value: T) bool {
        switch (@typeInfo(T)) {
            .@"struct" => |s| {
                inline for (s.field_names, s.field_types) |name, FT| {
                    if (comptime std.mem.eql(u8, name, "path") and FT == u32) {
                        if (w.openCastPath(@field(value, name))) return true;
                    } else if (comptime !std.mem.eql(u8, name, "cast_signature")) {
                        if (w.hasOpenCast(FT, @field(value, name))) return true;
                    }
                }
            },
            .pointer => |p| {
                if (p.size == .one and p.child == Summary) return w.hasOpenCast(Summary, value.*);
                if (p.size != .slice) return false;
                if (T == []const [2]u32) {
                    for (value) |slot| if (w.openCastPath(slot[1])) return true;
                } else if (@typeInfo(p.child) == .@"struct" or @typeInfo(p.child) == .pointer) {
                    for (value) |v| if (w.hasOpenCast(p.child, v)) return true;
                }
            },
            else => {},
        }
        return false;
    }

    /// Local schemes and lambdas need the same call-site specialization as
    /// top-level declarations. Use body/pattern variables so the signature
    /// and the marker keys name exactly the same checked variables; the
    /// function type supplies an unused pattern's complete type as well.
    fn castClosureSignature(w: *Walker, params: []const Inst.Index, body: Inst.Index, fn_ty: ?Var) Allocator.Error!u32 {
        const ty = fn_ty orelse return none;
        const content = w.store.resolvedContent(ty);
        if (content != .structure or content.structure != .func) return none;
        const f = content.structure.func;
        const args = w.store.vars(f.params);
        if (args.len != params.len) return none;
        var b: std.Io.Writer.Allocating = .init(w.a);
        b.writer.writeAll("fn(") catch return error.OutOfMemory;
        for (params, args) |p, arg| try w.castPart(&b.writer, w.patternType(p) orelse arg);
        b.writer.writeAll("→") catch return error.OutOfMemory;
        try w.castPart(&b.writer, w.instType(body) orelse f.result);
        b.writer.writeByte(')') catch return error.OutOfMemory;
        return w.o.castId(b.written());
    }

    fn castDeclSignature(w: *Walker) Allocator.Error!u32 {
        // A cast-free declaration needs no type vocabulary in its summary.
        if (!w.cast_open_used) return none;
        const module = w.o.in.modules[w.m];
        if (w.decl_index >= module.decl_display.len) return none;
        const v = module.decl_display[w.decl_index].unwrap() orelse return none;
        return w.castType(v);
    }

    /// The layer's declared package name distinguishes platform modules
    /// with the same dotted name. Hex keeps arbitrary package bytes out of
    /// the structural key's delimiters; the module name remains readable.
    fn castNamespace(w: *Walker, m: u32, name: []const u8) Allocator.Error![]const u8 {
        if (m >= w.o.in.packages.len or w.o.in.packages[m] != .platform or m >= w.o.in.platform_names.len or w.o.in.platform_names[m].len == 0) return name;
        var b: std.Io.Writer.Allocating = .init(w.a);
        b.writer.writeAll("platform[") catch return error.OutOfMemory;
        for (w.o.in.platform_names[m]) |byte| b.writer.print("{x:0>2}", .{byte}) catch return error.OutOfMemory;
        b.writer.print("]/{s}", .{name}) catch return error.OutOfMemory;
        return b.toOwnedSlice();
    }

    fn castType(w: *Walker, v: Var) Allocator.Error!u32 {
        const root = w.store.find(v);
        if (w.o.cast_closed.len == 0) {
            w.o.cast_closed = try w.o.in.gpa.alloc(?[]u32, w.o.in.modules.len);
            @memset(w.o.cast_closed, null);
        }
        if (w.o.cast_closed[w.m] == null) {
            const memo = try w.o.in.gpa.alloc(u32, w.store.descriptors.len);
            @memset(memo, none);
            w.o.cast_closed[w.m] = memo;
        }
        const closed = w.o.cast_closed[w.m].?;
        if (root.int() < closed.len and closed[root.int()] != none) return closed[root.int()];
        const memo_key: [3]u32 = .{ w.m, w.decl_index, root.int() };
        if (w.o.cast_keys.get(memo_key)) |known| {
            w.cast_open_used = true;
            return known;
        }
        var b: std.Io.Writer.Allocating = .init(w.a);
        const writer = &b.writer;
        const c = w.store.resolvedContent(root);
        switch (c) {
            .flex, .rigid => {
                // All store references come from this declaration's display,
                // instruction or local types. The solved store is read-only;
                // definition views substitute through env without fresh vars.
                // Cached scopes therefore keep the same roots on every walk.
                try w.seedCastVars();
                writer.print("var({d}:{s}:{d}:{d})", .{ @backingInt(w.o.in.packages[w.m]), try w.castNamespace(w.m, w.o.in.module_names[w.m]), w.decl_index, std.mem.indexOfScalar(u32, w.cast_ordinals, root.int()).? }) catch return error.OutOfMemory;
            },
            .err => writer.writeAll("⋆") catch return error.OutOfMemory,
            .alias => unreachable,
            .structure => |s| switch (s) {
                .unit => writer.writeAll("unit") catch return error.OutOfMemory,
                .empty_record => writer.writeAll("{}") catch return error.OutOfMemory,
                .app => |app| {
                    const t = w.o.in.types.entries[app.type.int()];
                    writer.print("{d}:{s}::{s}(", .{ @backingInt(t.package), try w.castNamespace(t.module.int(), w.o.in.interner.slice(t.module_name)), w.o.in.interner.slice(t.name) }) catch return error.OutOfMemory;
                    for (w.store.vars(app.args)) |arg| try w.castPart(writer, arg);
                    writer.writeAll(")") catch return error.OutOfMemory;
                },
                .tuple => |range| {
                    writer.writeAll("tuple(") catch return error.OutOfMemory;
                    for (w.store.vars(range)) |arg| try w.castPart(writer, arg);
                    writer.writeAll(")") catch return error.OutOfMemory;
                },
                .func => |f| {
                    writer.writeAll("fn(") catch return error.OutOfMemory;
                    for (w.store.vars(f.params)) |arg| try w.castPart(writer, arg);
                    writer.writeAll("→") catch return error.OutOfMemory;
                    try w.castPart(writer, f.result);
                    writer.writeAll(")") catch return error.OutOfMemory;
                },
                .record => |r| {
                    // An extension chain is the same record however unification
                    // split it. Sort all its fields by text, never symbol id.
                    var fields: std.ArrayList(TypeStore.Field) = .empty;
                    try fields.appendSlice(w.a, w.store.fields(r.fields));
                    var ext = r.ext;
                    while (true) {
                        const ec = w.store.resolvedContent(ext);
                        if (ec != .structure or ec.structure != .record) break;
                        try fields.appendSlice(w.a, w.store.fields(ec.structure.record.fields));
                        ext = ec.structure.record.ext;
                    }
                    std.mem.sort(TypeStore.Field, fields.items, w.o.in.interner, struct {
                        fn less(pool: *const InternPool.Global, x: TypeStore.Field, y: TypeStore.Field) bool {
                            return std.mem.lessThan(u8, pool.slice(x.name), pool.slice(y.name));
                        }
                    }.less);
                    writer.writeAll("record(") catch return error.OutOfMemory;
                    for (fields.items) |field| {
                        const name = w.o.in.interner.slice(field.name);
                        writer.print("{d}:{s}=", .{ name.len, name }) catch return error.OutOfMemory;
                        try w.castPart(writer, field.value);
                    }
                    writer.writeAll("|") catch return error.OutOfMemory;
                    try w.castPart(writer, ext);
                    writer.writeAll(")") catch return error.OutOfMemory;
                },
            },
        }
        const id = try w.o.castId(b.written());
        if (!w.o.cast_open.items[id] and root.int() < closed.len) {
            closed[root.int()] = id;
        } else {
            w.cast_open_used = true;
            try w.o.cast_keys.put(w.o.in.gpa, memo_key, id);
        }
        return id;
    }

    fn castPart(w: *Walker, writer: *std.Io.Writer, v: Var) Allocator.Error!void {
        writeCastRef(writer, try w.castType(v)) catch return error.OutOfMemory;
    }

    fn opaqueCastType(w: *Walker, v: Var) bool {
        const c = w.store.resolvedContent(v);
        if (c != .structure or c.structure != .app) return false;
        const id = c.structure.app.type;
        return id != w.o.in.types.well_known.list and id != w.o.builderId() and w.o.in.types.entries[id.int()].kind == .foreign;
    }

    fn analysisStep(kind: StepKind) bool {
        return switch (kind) {
            .env, .markup_render, .markup_event, .schema_decoded, .schema_encoded => true,
            else => false,
        };
    }

    fn analysisSlot(w: *Walker, path: u32) bool {
        const first = w.o.firstStep(path) orelse return false;
        return analysisStep(first.kind);
    }

    fn castResult(w: *Walker, av: AV, from: Var, to: Var) Allocator.Error!AV {
        // A polymorphic returned primitive is not itself a cast. The caller
        // that knows both endpoints records the boundary.
        if (isVar(w.store, from) != null or isVar(w.store, to) != null) return av;
        const fi = w.opaqueCastType(from);
        const ti = w.opaqueCastType(to);
        if (fi == ti) return av;
        return w.castBoundary(av, fi, try w.castType(if (fi) to else from));
    }

    fn castResultRef(w: *Walker, av: AV, from: TyRef, to: TyRef) Allocator.Error!AV {
        if (from == .store and to == .store) return w.castResult(av, from.store, to.store);
        const fk = try w.castTypeRef(from);
        const tk = try w.castTypeRef(to);
        if (w.castVariable(fk) or w.castVariable(tk)) return av;
        const fi = try w.opaqueCastKey(fk);
        const ti = try w.opaqueCastKey(tk);
        if (fi == ti) return av;
        return w.castBoundary(av, fi, if (fi) tk else fk);
    }

    fn castBoundary(w: *Walker, av: AV, into_concrete: bool, id: u32) Allocator.Error!AV {
        if (into_concrete) return w.readCast(av, id);

        var out: std.ArrayList(Entry) = .empty;
        var folded = false;
        for (av) |e| {
            var x = e;
            if (e.path != eps and !w.analysisSlot(e.path)) {
                x.path = try w.o.prepend(.{ .kind = .cast, .arg = id }, e.path);
                folded = folded or w.o.paths.depth.items[x.path] != w.o.paths.depth.items[e.path] + 1;
            }
            try out.append(w.a, x);
        }
        if (folded) try w.foldedPairs(av, out.items);
        return w.norm(out.items);
    }

    /// A repeated full type denotes every deeper entry at that type. Keep
    /// symbolic reads folded and scan concrete paths for every matching
    /// boundary, never dropping a holder merely because projection moved it.
    const FixedCastPath = struct { path: u32, unknown: bool };

    /// A type hole is not another physical level. Keep the path through
    /// the common fixed context; only its unresolved remainder is unknown.
    fn fixedCastPath(w: *Walker, path: u32, from: u32, to: u32) Allocator.Error!?FixedCastPath {
        var x: TyRef = .{ .cast = from };
        var y: TyRef = .{ .cast = to };
        var prefix: u32 = eps;
        const steps_ = w.o.steps(path);
        for (steps_, 0..) |step, i| {
            const sx = try w.tyShape(x);
            const sy = try w.tyShape(y);
            if (step.kind == .env and sx == .func and sy == .func) {
                for (steps_[i..]) |rest| prefix = try w.o.child(prefix, rest.kind, rest.arg);
                return .{ .path = prefix, .unknown = false };
            }
            const next: ?[2]TyRef = switch (step.kind) {
                .elem => if (sx == .app and sy == .app and sx.app.id == w.o.in.types.well_known.list and sy.app.id == sx.app.id and sx.app.args.len == 1 and sy.app.args.len == 1) .{ sx.app.args[0], sy.app.args[0] } else null,
                .tuple => if (sx == .tuple and sy == .tuple and sx.tuple.len == sy.tuple.len and step.arg < sx.tuple.len) .{ sx.tuple[step.arg], sy.tuple[step.arg] } else null,
                .field => blk: {
                    var fields: [2]?TyRef = .{ null, null };
                    for ([_]TyShape{ sx, sy }, &fields) |shape, *field| {
                        var rec = shape;
                        while (rec == .record) {
                            for (rec.record.names, rec.record.types) |name, ty| if (name == step.arg) {
                                field.* = ty;
                                break;
                            };
                            if (field.* != null) break;
                            rec = if (rec.record.ext) |ext| try w.tyShape(ext) else break;
                        }
                    }
                    break :blk if (fields[0] != null and fields[1] != null) .{ fields[0].?, fields[1].? } else null;
                },
                .ctor => blk: {
                    if (sx != .app or sy != .app or sx.app.id != sy.app.id) break :blk null;
                    const c = w.o.stepCtor(step.arg);
                    const f = w.o.stepField(step.arg);
                    const a = (try w.ctorFieldTy(sx.app.id, sx.app.args, c, f)) orelse break :blk null;
                    const b = (try w.ctorFieldTy(sy.app.id, sy.app.args, c, f)) orelse break :blk null;
                    break :blk .{ a, b };
                },
                else => null,
            };
            if (next) |refs| {
                prefix = try w.o.child(prefix, step.kind, step.arg);
                x = refs[0];
                y = refs[1];
            } else return if (prefix == eps) null else .{ .path = try w.o.child(prefix, .any, 1), .unknown = true };
        }
        return .{ .path = prefix, .unknown = false };
    }

    fn readCastLevel(w: *Walker, av: AV, id: u32) Allocator.Error!AV {
        return w.readCastView(av, id, true);
    }

    fn readCastView(w: *Walker, av: AV, id: u32, repeated: bool) Allocator.Error!AV {
        var out: std.ArrayList(Entry) = .empty;
        for (av) |e| {
            if (w.analysisSlot(e.path) or (e.path == eps and w.cells.items[e.cell].condition_only)) {
                try out.append(w.a, e);
                continue;
            }
            const ap = if (e.approx != 0) e.approx else approx_place;
            if (e.path == eps) {
                const kind: StepKind = if (repeated) .cast_level else .cast;
                if (try w.projCell(e.cell, .{ .kind = kind, .arg = id }, null)) |c| try out.append(w.a, .{ .path = eps, .cell = c, .approx = ap, .grown = e.grown });
                continue;
            }
            const first = w.o.firstStep(e.path).?;
            if (!repeated and first.kind == .cast) if (try w.fixedCastPath(try w.o.dropFirst(e.path), first.arg, id)) |fixed| {
                try out.append(w.a, .{ .path = fixed.path, .cell = e.cell, .approx = if (fixed.unknown) ap else e.approx, .grown = e.grown });
                continue;
            };
            const before = out.items.len;
            for (w.o.pathNodes(e.path)) |node| {
                const kind = w.o.paths.kind.items[node];
                if (kind == .any) {
                    try out.append(w.a, .{ .path = try w.o.child(eps, .any, 1), .cell = e.cell, .approx = ap, .grown = e.grown });
                    break;
                }
                if ((kind != .cast and kind != .cast_level) or w.o.paths.arg.items[node] != id) continue;
                const rest = (try w.o.suffix(node, e.path)).?;
                try out.append(w.a, .{ .path = rest, .cell = e.cell, .approx = ap, .grown = e.grown });
                if (kind == .cast_level) try out.append(w.a, .{ .path = try w.o.concat(try w.o.child(eps, .cast_level, id), rest), .cell = e.cell, .approx = ap, .grown = e.grown });
            }
            if (out.items.len == before) {
                // An incompatible concrete view still holds its contents.
                // The repeated-type read cannot name their precise place.
                try out.append(w.a, .{ .path = try w.o.child(eps, .any, 1), .cell = e.cell, .approx = ap, .grown = e.grown });
            }
        }
        return w.norm(out.items);
    }

    fn readCast(w: *Walker, av: AV, id: u32) Allocator.Error!AV {
        if (w.o.cast_wild.items[id]) return w.readCastView(av, id, false);
        var out: std.ArrayList(Entry) = .empty;
        for (av) |e| {
            var x = e;
            if (w.analysisSlot(e.path) or (e.path == eps and w.cells.items[e.cell].condition_only)) {
                try out.append(w.a, e);
                continue;
            }
            if (e.path == eps) {
                // A symbolic root can be projected at its new type. A local
                // allocation already names the same physical object.
                const original = w.cells.items[e.cell].ty.unwrap();
                const same = if (original) |ty| try w.castType(ty) == id else false;
                if (!same) {
                    if (try w.projCell(e.cell, .{ .kind = .cast, .arg = id }, null)) |c| x.cell = c;
                }
            } else {
                const first = w.o.firstStep(e.path).?;
                if (first.kind == .cast and first.arg == id) {
                    x.path = try w.o.dropFirst(e.path);
                } else if (first.kind == .cast) {
                    if (try w.fixedCastPath(try w.o.dropFirst(e.path), first.arg, id)) |fixed| {
                        x.path = fixed.path;
                        if (fixed.unknown and x.approx == 0) x.approx = approx_place;
                    } else {
                        x.path = try w.o.child(eps, .any, 1);
                        if (x.approx == 0) x.approx = approx_place;
                    }
                } else {
                    x.path = try w.o.child(eps, .any, 1);
                    if (x.approx == 0) x.approx = approx_place;
                }
            }
            try out.append(w.a, x);
        }
        return w.norm(out.items);
    }

    fn instRes(w: *Walker, s: *const Summary, ctx: InstCtx) Allocator.Error!AV {
        // `several` below reads neighbours: `normalize` sorts `res` by path.
        if (std.debug.runtime_safety and s.res.len > 1) for (s.res[1..], 0..) |r, i| std.debug.assert(s.res[i].path <= r.path);
        var out: std.ArrayList(Entry) = .empty;
        // §31.4 item 6: each record condition of the summary instantiated
        // once per call — a condition over what the call is handed, as it
        // is handed — and read back for each entry that states it.
        var rmemo: std.ArrayList(RMemo) = .empty;
        // §18.3 (#754): an entry's deep condition, instantiated once while
        // nothing it reads has changed (`instXSumOnce`).
        var xmemo: XMemo = .{ .ok = true };
        const saved_inst = w.writes_inst;
        w.writes_inst = ctx.inst.int();
        defer w.writes_inst = saved_inst;
        // An argument that holds a result of this very call (a later round
        // of a fixpoint) would read what this call's entries write.
        for (ctx.avs) |av| for (av) |e| {
            const x = w.cells.items[e.cell];
            if (x.kind == .result and x.a == ctx.inst.int()) xmemo.ok = false;
        };
        var smemo: XMemo = .{ .ok = xmemo.ok };
        const grown = try w.grownArgs(ctx);
        var before: std.ArrayList(Entry) = .empty;
        var cut = false;
        // Asserted storage rows retain the old elements and store new
        // operands beside them. Keep their per-path separation before
        // equal element entries are merged, as a literal construction does.
        const stores_operands = s.asserted and for (s.uses) |u| {
            if (u.param == 0 and u.path == eps and u.bits & bit_w != 0 and u.extent == .storage) break true;
        } else false;
        const callback_result = for (s.res) |r| {
            if (r.prov.kind == .cb) break true;
        } else false;
        var stored_parts: std.ArrayList(AV) = .empty;
        var res_path: u32 = none;
        var res_choices: usize = 0;
        for (s.res, 0..) |r, i| {
            // `res` is sorted by path: another entry at this path is a neighbour.
            if (res_path != r.path) {
                res_path = r.path;
                res_choices = 0;
                for (s.res[i..]) |choice| {
                    if (choice.path != r.path) break;
                    if (!spineAnnotation(choice)) res_choices += 1;
                }
            }
            const several = !spineAnnotation(r) and res_choices > 1;
            // An approximate entry may name an argument the result's type
            // cannot be (§16.4 item 6): such an argument is never the
            // result, whatever its cells are.
            if ((several or r.approx) and r.path == eps and r.prov.kind == .param and r.prov.path == eps and r.prov.a < ctx.arg_types.len) {
                if (ctx.result_ty) |rt| if (ctx.arg_types[r.prov.a]) |at| if (!try w.o.mayShare(w.store, rt, at, 0)) continue;
            }
            var raw_cells = try w.instResProv(r, ctx);
            if (!r.prov.condition_only and r.prov.kind == .param and r.prov.path == eps and r.path == eps) {
                if (w.callArgRef(ctx, r.prov.a)) |at| if (ctx.result_ref orelse (if (ctx.result_ty) |v| TyRef{ .store = v } else null)) |rt| {
                    raw_cells = try w.castResultRef(raw_cells, at, rt);
                };
            }
            const cells = if (r.prov.condition_only) try w.annotationSpines(raw_cells, r.sc, ctx, r.grown, grown, &smemo) else raw_cells;
            // §18.3: a fresh cell starts at the summary's condition, and a
            // parameter's is lowered by it.
            if (ctx.conds) switch (r.prov.kind) {
                .fresh, .esc => {
                    const k = try w.instXSumOnce(r.xc, ctx, &xmemo);
                    for (cells) |e| if (e.path == eps) {
                        try w.initCond(e.cell, k);
                        if (!r.prov.condition_only) try w.initSpine(e.cell, try w.instXSumOnce(r.sc, ctx, &smemo));
                    };
                },
                .param => if (r.xc.no != 0 or r.xc.atoms.len != 0) {
                    const k = try w.instXSum(r.xc, ctx);
                    for (cells) |e| if (e.path == eps) try w.lowerCond(e.cell, k);
                },
                else => {},
            };
            if (ctx.conds and r.prov.kind == .param and !r.prov.condition_only) for (cells) |e| if (e.path == eps) {
                try w.lowerSpine(e.cell, try w.instXSum(r.sc, ctx));
            };
            // §31.4 item 6: and its record condition, as a list's.
            if (ctx.conds) try w.instRecordCond(r, cells, ctx, &rmemo);
            const from = before.items.len;
            var row_placement = r;
            var folded_guard = false;
            if (r.prov.condition_only) if (gGuard(r.grown)) |distance| {
                const expands = for (cells) |e| {
                    if (gGuard(e.grown)) |next| if (next > distance) break true;
                } else false;
                if (expands) {
                    const depth = w.o.paths.depth.items[r.path];
                    std.debug.assert(distance <= depth);
                    row_placement.path = try w.cutAt(r.path, depth - distance);
                    folded_guard = true;
                }
            };
            const composed = try w.composeRes(row_placement, cells, grown, &before, &cut);
            if (folded_guard) for (composed) |*e| {
                e.grown = gGuardAt(e.grown, 1);
            };
            var av: AV = composed;
            if (several or r.approx) {
                av = try w.approxAll(av, ctx.inst);
                for (before.items[from..]) |*b| if (b.approx == 0) {
                    b.approx = ctx.inst.int() + 1;
                };
            }
            try out.appendSlice(w.a, av);
            if (stores_operands and !callback_result) try stored_parts.append(w.a, av);
        }
        // §16.7: places the fold put at one path are judged as two.
        if (cut) try w.foldedPairs(before.items, out.items);
        if (stores_operands and !callback_result) {
            const stored = try w.spineValue(ctx.inst, stored_parts.items);
            out.clearRetainingCapacity();
            try out.appendSlice(w.a, stored);
        }
        // §31.7: the records the result holds, whose cells no list's fact
        // reads (an object alone, a record of numbers).
        for (s.objs) |r| {
            const cells = try w.instProv(r.prov, ctx);
            const own = try w.objectView(cells);
            if (ctx.conds) try w.instRecordCond(r, own, ctx, &rmemo);
            // No list's fact may read what `objs` names.
            if (std.debug.runtime_safety) for (own) |x| std.debug.assert(w.listFacing(x.cell) == null);
            var object_before: std.ArrayList(Entry) = .empty;
            var object_cut = false;
            var av: AV = try w.composeRes(r, own, grown, &object_before, &object_cut);
            if (object_cut) try w.foldedPairs(object_before.items, @constCast(av));

            if (r.approx) av = try w.approxAll(av, ctx.inst);
            try out.appendSlice(w.a, av);
        }
        return w.norm(out.items);
    }

    /// What result entry `r` names at the call (`instProv`). §16.6 as
    /// amended (#754): inside the group being solved, a member's fresh cells
    /// are one cell per call, but its annotations are one per result path.
    /// An annotation's container condition names the arrays at its own place
    /// (#720); taken for one, each place's annotation would carry the
    /// others' conditions and put their guards under itself, a level deeper
    /// every round, until the cut.
    fn instResProv(w: *Walker, r: ResEntry, ctx: InstCtx) Allocator.Error!AV {
        const raw = try w.instProv(r.prov, ctx);
        if (!ctx.merge_fresh or !r.prov.condition_only or r.prov.kind != .fresh or r.path == eps) return raw;
        // Only a container condition names its place; a deep or record
        // condition names cells, wherever the annotation is.
        for (r.sc.atoms) |t| {
            if (t.kind == .sep_root) break;
        } else return raw;
        const out = try w.a.dupe(Entry, raw);
        for (out) |*x| {
            var c = w.cells.items[x.cell];
            if (c.kind != .result) continue;
            // Numbered apart from every fresh and callback number: one per
            // result path, the path's own.
            c.b = annotation_ns + r.path;
            x.cell = try w.cell(c);
        }
        return out;
    }

    /// The conditions an `instRes` instantiated, each with the count of
    /// condition writes it was made at; `ok` false when none may be kept.
    const XMemo = struct {
        ok: bool,
        items: std.ArrayList(struct { x: XSum, k: u32, writes: [3]u64 }) = .empty,
    };

    /// `instXSum(x, ctx)` for a result entry's deep or spine condition, kept within
    /// one `instRes` (#754). Entries that share a fresh number at several
    /// result paths state one condition each, and the instantiation is a
    /// function of the arguments' cells and their conditions: while no
    /// condition of a cell outside this call's own results changed
    /// (`noteWrite`) and no callback was instantiated, it gives the same
    /// atoms again. Only a condition over parameters is kept; one over a
    /// fresh cell reads this call's own results.
    fn instXSumOnce(w: *Walker, x: XSum, ctx: InstCtx, memo: *XMemo) Allocator.Error!u32 {
        if (x.no != 0 or x.atoms.len == 0) return w.instXSum(x, ctx);
        const keepable = memo.ok and for (x.atoms) |t| {
            if (!overParams(t)) break false;
        } else true;
        if (!keepable) return w.instXSum(x, ctx);
        // What the instantiation reads: the deep conditions always, the
        // spines for a spine atom.
        const spines = for (x.atoms) |t| switch (t.kind) {
            .spine, .sep_spine, .sep_root, .apart_spine, .keep_spine => break true,
            .excl, .sep, .apart, .keep => {},
        } else false;
        const now: [3]u64 = .{ w.cond_writes, if (spines) w.spine_writes else 0, w.other_writes };
        for (memo.items.items) |m| {
            if (!std.mem.eql(u64, &m.writes, &now) or m.x.atoms.len != x.atoms.len) continue;
            for (m.x.atoms, x.atoms) |a, b| {
                if (!a.eql(b)) break;
            } else return m.k;
        }
        const k = try w.instXSum(x, ctx);
        try memo.items.append(w.a, .{ .x = x, .k = k, .writes = .{ w.cond_writes, if (spines) w.spine_writes else 0, w.other_writes } });
        return k;
    }

    /// Whether every provenance an atom names is a parameter's, and its
    /// kind one `instXSum` reads off cells alone (no callback's shape).
    fn overParams(t: XAtom) bool {
        switch (t.kind) {
            .excl, .spine => return t.a.kind == .param,
            .sep, .sep_spine, .sep_root => return t.a.kind == .param and t.b.kind == .param,
            .apart, .apart_spine => {
                for (t.groups) |g| for (g) |p| if (p.kind != .param) return false;
                return true;
            },
            .keep, .keep_spine => return false,
        }
    }

    /// §31.4 item 6: a result entry's record condition at a call: a cell
    /// made by the call starts at it, an argument's is lowered by it.
    const RMemo = struct { x: XSum, k: u32 };

    fn instRecordCond(w: *Walker, r: ResEntry, cells: AV, ctx: InstCtx, memo: *std.ArrayList(RMemo)) Allocator.Error!void {
        // A cell that holds no record has no record condition to set.
        for (cells) |e| {
            if (e.path == eps and try w.mayHoldRecord(e.cell)) break;
        } else return;
        switch (r.prov.kind) {
            .fresh, .esc => {
                const k = try w.rinstMemo(r.rxc, ctx, memo);
                for (cells) |e| if (e.path == eps) try w.rinitCond(e.cell, k);
            },
            .param => if (r.rxc.no != 0 or r.rxc.atoms.len != 0) {
                const k = try w.rinstMemo(r.rxc, ctx, memo);
                for (cells) |e| if (e.path == eps) try w.rlowerCond(e.cell, k);
            },
            else => {},
        }
    }

    fn rinstMemo(w: *Walker, x: XSum, ctx: InstCtx, memo: *std.ArrayList(RMemo)) Allocator.Error!u32 {
        if (x.no == 1) return cond_lost;
        if (x.no == 2) return cond_shared;
        if (x.atoms.len == 0) return cond_yes;
        for (memo.items) |m| {
            if (m.x.no != x.no or m.x.atoms.len != x.atoms.len) continue;
            for (m.x.atoms, x.atoms) |a, b| {
                if (!a.eql(b)) break;
            } else return m.k;
        }
        const k = try w.rinstXSum(x, ctx);
        try memo.append(w.a, .{ .x = x, .k = k });
        return k;
    }

    /// `cells`, what summary entry `r` names at the call, placed under its
    /// path (§16.4), with §16.7's composed-path fold (F3, the owner's choice
    /// (a)). Below a variable a call inside the group grows — known from the
    /// call's types, or from the pending boundary on `r` that a symbolic
    /// cell left at such a call — the first composition is exact and marked,
    /// and a later one goes to `⋆`. A symbolic cell at the variable takes
    /// the boundary with it. Appends to `before` each entry uncut, in order,
    /// and sets `cut` when one was cut; the result is not normalized.
    fn composeRes(w: *Walker, r: ResEntry, cells: AV, grown: []const ?[2]TyRef, before: *std.ArrayList(Entry), cut: *bool) Allocator.Error![]Entry {
        const grown_arg: ?[2]TyRef = if (r.prov.kind == .param and r.prov.a < grown.len) grown[r.prov.a] else null;
        const out = try w.a.alloc(Entry, cells.len);
        const pd = w.o.paths.depth.items[r.prov.path];
        for (cells, out) |e, *x| {
            const path = try w.o.concat(r.path, e.path);

            const marked = gMarked(e.grown) or gMarked(r.grown);
            x.* = .{ .path = path, .cell = e.cell, .approx = e.approx, .grown = gMake(marked, gPending(e.grown)) | (@max(e.grown >> grown_guard, r.grown >> grown_guard) << grown_guard) };
            try before.append(w.a, x.*);
            const folded_prefix = w.castFoldPath(r.path);
            const prefix = if (marked) folded_prefix orelse r.path else r.path;
            if (folded_prefix != null or w.cast_crossings.contains(.{ .path = r.path, .prov = r.prov })) {
                x.grown |= 1;
                if (marked) {
                    x.path = try w.o.concat(prefix, e.path);
                    if (x.approx == 0) x.approx = approx_place;
                    cut.* = true;
                }
            }
            const rel: usize = blk: {
                if (grown_arg) |ga| {
                    const full = try w.o.concat(r.prov.path, e.path);
                    if (try w.polyBound(full, ga[0], ga[1])) |b| break :blk if (b > pd) b - pd else 0;
                }
                break :blk gPending(r.grown) orelse continue;
            };
            const d = w.o.paths.depth.items[e.path];
            if (d <= rel) {
                // At or above the variable: a symbolic cell there stands for
                // places below it, which a later instantiation composes.
                if (w.composedLater(e.cell)) x.grown = gJoin(x.grown, gMake(false, rel - d));
                continue;
            }
            if (marked) {
                x.path = try w.o.concat(prefix, try w.cutAt(e.path, rel));
                if (w.cells.items[e.cell].condition_only and gGuard(x.grown) != null) x.grown = gGuardAt(x.grown, 1);
                if (x.approx == 0) x.approx = approx_place;
                cut.* = true;
            }
            x.grown |= 1;
        }
        return out;
    }

    /// Whether a cell stands for a value a later instantiation supplies,
    /// whose places below it are composed then (§16.7, F3 as amended).
    fn composedLater(w: *Walker, c: u32) bool {
        return switch (w.cells.items[c].kind) {
            .param, .env, .cbres, .taken, .except => true,
            else => false,
        };
    }

    /// A supply's cells as a callback's parameter holds them: `sp.path`
    /// composed with what the provenance names (§16.4), folded as a
    /// result's are (§16.7, F3 as amended).
    fn composeSupply(w: *Walker, sp: SupplyEntry, raw_cells: AV, ctx: InstCtx) Allocator.Error!AV {
        const grown = try w.grownArgs(ctx);
        const cells = if (sp.prov.condition_only) try w.annotationSpines(raw_cells, sp.sc, ctx, sp.grown, grown, null) else raw_cells;
        // A supplied annotation is a condition on the value, never a loan
        // of an allocation. Install it only on its annotation cells.
        if (ctx.conds and sp.prov.condition_only) {
            const k = try w.instXSum(sp.xc, ctx);
            const rk = try w.rinstXSum(sp.rxc, ctx);
            for (cells) |e| if (e.path == eps) {
                try w.initCond(e.cell, k);
                try w.rinitCond(e.cell, rk);
            };
        }
        var before: std.ArrayList(Entry) = .empty;
        var cut = false;
        const out = try w.composeRes(.{ .path = sp.path, .prov = sp.prov, .grown = sp.grown }, cells, grown, &before, &cut);
        if (cut) try w.foldedPairs(before.items, out);
        return w.norm(out);
    }

    /// Per argument of a call inside the group being solved, its declared
    /// type and its type at the call when the call grows a variable of the
    /// first at a structure (§16.7, F3 as amended); decided once per call.
    fn grownArgs(w: *Walker, ctx: InstCtx) Allocator.Error![]const ?[2]TyRef {
        var poly = ctx.poly;
        var arg_types = ctx.arg_types;
        if (poly.len == 0) if (w.call_poly) |cp| if (cp.inst == ctx.inst and cp.s == ctx.s) {
            poly = cp.poly;
            arg_types = cp.arg_types;
        };
        if (poly.len == 0) return &.{};
        const out = try w.a.alloc(?[2]TyRef, poly.len);
        for (out, poly, 0..) |*x, gt, i| {
            x.* = null;
            const g = gt orelse continue;
            const a: TyRef = if (i < ctx.arg_refs.len) ctx.arg_refs[i] else if (i < arg_types.len) .{ .store = arg_types[i] orelse continue } else continue;
            const declared: TyRef = .{ .store = g };
            if (try w.grownIn(declared, a, 0)) x.* = .{ declared, a };
        }
        return out;
    }

    fn instProv(w: *Walker, p: Prov, ctx: InstCtx) Allocator.Error!AV {
        if (p.condition_only) {
            var q = p;
            q.condition_only = false;
            var unannotated = ctx;
            unannotated.callback_fresh = null;
            const values = try w.instProv(q, unannotated);
            const out = try w.a.alloc(Entry, values.len);
            for (values, out) |e, *x| {
                var c = w.cells.items[e.cell];
                c.condition_only = true;
                c.nonlist = false;
                x.* = e;
                x.cell = try w.cell(c);
            }
            return out;
        }
        // §31.7: a record's object alone — what the provenance names, its
        // cells at ε made objects, which project nothing below.
        if (p.obj) {
            var q = p;
            q.obj = false;
            var out: std.ArrayList(Entry) = .empty;
            for (try w.instProv(q, ctx)) |e| {
                if (e.path != eps or w.cells.items[e.cell].condition_only) continue;
                try out.append(w.a, .{ .path = eps, .cell = try w.exceptCell(e.cell, &.{}, true), .approx = e.approx, .grown = e.grown });
            }
            return w.norm(out.items);
        }
        switch (p.kind) {
            .param => {
                if (p.a >= ctx.avs.len) return &.{};
                const av = try w.projArg(ctx, p.a, p.path);
                if (!p.taken or !ctx.take) return av;
                // The traversal primitive's element, taken out (§18.5): a
                // cell that arrived from outside stands for it taken.
                const out = try w.a.alloc(Entry, av.len);
                for (av, out) |e, *x| {
                    x.* = e;
                    if (e.path != eps or w.cells.items[e.cell].condition_only) continue;
                    switch (w.cells.items[e.cell].kind) {
                        .param, .result, .env, .cbres => x.cell = try w.cell(.{ .kind = .taken, .a = e.cell, .b = ctx.inst.int() }),
                        .except => if (try w.takeable(e.cell)) |t| {
                            x.cell = try w.cell(.{ .kind = .taken, .a = t, .b = ctx.inst.int() });
                        },
                        .site, .shared, .top, .closure, .func, .taken, .payload => {},
                    }
                }
                return w.norm(out);
            },
            .fresh, .esc => {
                const base_k = if (ctx.merge_fresh) 1 else p.a;
                const k = (if (ctx.depth == 0) base_k else base_k + callback_ns_stride * ctx.depth) + ctx.fresh_ns;
                const ty: Var.Optional = if (ctx.depth == 0) w.instTypeOpt(ctx.inst) else .none;
                const av = try w.single(.{ .kind = .result, .a = ctx.inst.int(), .b = @max(k, 1), .ty = ty });
                if (p.kind == .fresh) if (ctx.callback_fresh) |made| for (av) |e| {
                    if (std.mem.indexOfScalar(u32, made.items, e.cell) == null) try made.append(w.a, e.cell);
                };
                if (p.kind == .esc and ctx.effects) try w.escape(av, w.point);
                return av;
            },
            .shared => return w.single(.{ .kind = .shared, .a = p.a, .b = p.b, .path = p.path }),
            .top => return w.single(.{ .kind = .top, .a = if (ctx.s.limit != .none or p.a == 1) 1 else p.a }),
            .env => {
                if (ctx.closure == none) return w.single(.{ .kind = .top, .a = 0 });
                // A carried lambda's capture: what the callee's binding said
                // it held, as this body holds it (§24.9).
                if (w.closures.items[ctx.closure].carried) return w.carriedEnv(ctx.closure, p);
                // Inside a summary's frame the capture stays symbolic. Looking
                // through it here would substitute the caller's cells into
                // the recursive class and erase captured writes (§29).
                if (p.a >= w.local_av.len) return w.single(.{ .kind = .top, .a = 0 });
                if (w.local_av[p.a] == null or w.local_frame[p.a] != w.frame)
                    return w.single(.{ .kind = .env, .a = p.a, .path = p.path });
                return w.projPath(w.local_av[p.a].?, p.path, null);
            },
            .klass => return w.carry(p, ctx),
            .cb => {
                // A carried lambda's call of the function parameter of the
                // declaration it was written in: of what this body passed
                // there (§24.9).
                if (p.b == 1 and ctx.closure != none and w.closures.items[ctx.closure].carried) {
                    for (w.closures.items[ctx.closure].cb_avs) |cb| if (cb.j == p.a) {
                        if (w.fnParamOf(cb.av) orelse try w.slotOf(cb.av)) |jj| {
                            return w.projPath(try w.single(.{ .kind = .cbres, .a = jj, .b = ctx.inst.int() }), p.path, null);
                        }
                        // §30.9: a function value whose classes the walk
                        // knows returns what they return, handed what the
                        // checker cannot see: `⊤` for each argument.
                        if (ctx.depth >= inst_depth) return w.chainLimit(ctx.depth + 1);
                        if (try w.callThrough(cb.av, ctx)) |av| return w.projPath(av, p.path, null);
                    };
                    return w.single(.{ .kind = .top, .a = 0 });
                }
                // A lambda's class: the enclosing declaration's callback result (§18.9).
                // In a lambda, it stays that callback's result, read off as
                // the enclosing lambda's own call of it (§30.9).
                if (p.b == 1) return w.projPath(try w.single(.{ .kind = .cbres, .a = p.a, .b = ctx.inst.int() }), p.path, null);
                if (!hasActual(ctx.s, ctx.avs.len, p.a)) return w.single(.{ .kind = .top, .a = 0 });
                const whole = if (p.a == ctx.self_j) ctx.self_av else if (ctx.depth >= inst_depth) try w.chainLimit(ctx.depth + 1) else try w.instCb(p.a, ctx);
                return w.projPath(whole, p.path, null);
            },
        }
    }

    /// §16.7's `callbacks` limit: a callback's result instantiated more than
    /// `inst_depth` deep. Its value is `⊤limit`, and the declaration gets
    /// the error: the `⊤` keeps no alias of what the chain was handed, so
    /// it must not decide anything quietly (#271).
    fn chainLimit(w: *Walker, depth: u32) Allocator.Error!AV {
        try w.o.hitLimit(.callbacks, depth);
        return w.single(.{ .kind = .top, .a = 1 });
    }

    /// What the actual for function parameter `j` returns when the callee
    /// calls it (§16.4 item 6). A callee may hand the callback its own
    /// earlier result (a fold's accumulator), so this is a least fixpoint,
    /// iterated from nothing; one that does not settle within §16.7's
    /// `fixpoint` limit adds `⊤limit` and is an error at the declaration.
    fn instCb(w: *Walker, j: u32, ctx: InstCtx) Allocator.Error!AV {
        const actual = (try w.actualOf(ctx.s, ctx.avs, j)) orelse return w.single(.{ .kind = .top, .a = 0 });
        // The declaration's own function parameter or slot: what it returns,
        // in a lambda too, where the read-off names it `cb` of the enclosing
        // declaration (§18.9, §30.9).
        if (w.fnParamOf(actual) orelse try w.slotOf(actual)) |jj| {
            // A lambda's own function parameter is called many times and
            // its calls are not otherwise seen by the declaration.
            if (ctx.effects) if (ctx.s.funOf(j)) |facts| if (facts.calls == .many and !facts.seen) {
                try w.passOn(ctx.inst, ctx.s, ctx.avs, j, facts, jj);
            };
            return w.single(.{ .kind = .cbres, .a = jj, .b = ctx.inst.int() });
        }
        const classes = try w.classesOf(actual);
        if (classes.len == 0) return w.unknownCb(j, ctx);
        if (try w.foldAccumulator(j, classes, ctx) != null) return w.instFold(j, classes, ctx);
        var x: AV = &.{};
        var rounds: u32 = 0;
        // §16.7, the amendment of 2026-10-25 (#955), as in `instFold`.
        const cyclic = try w.cyclicAccumulator(j, ctx);
        while (rounds < round_cap) : (rounds += 1) {
            var inner = ctx;
            inner.self_j = j;
            inner.self_av = x;
            const grew = w.carry_grew;
            const y = try w.instCbOnce(j, classes, inner);
            var next = try w.unionOf(&.{ x, y });
            if (cyclic) next = try w.foldNesting(x, next);
            if (next.len == x.len and w.carry_grew == grew) return x;
            x = next;
        }
        // Its cells are finite (§20.4, amended 2026-10-16): the compiler's
        // limit, an error at the declaration (§16.7).
        try w.o.hitLimit(.fixpoint, round_cap);
        return w.unionOf(&.{ x, try w.single(.{ .kind = .top, .a = 1 }) });
    }

    /// A linear feedback edge: one owned initial parameter and the callback's
    /// previous whole result are supplied at the same accumulator position.
    fn foldAccumulator(w: *Walker, j: u32, classes: []const Class, ctx: InstCtx) Allocator.Error!?u32 {
        const s = ctx.s;
        if (s.limit != .none) return null;
        if (!(s.funOf(j) orelse return null).seen) return null;
        var acc: ?u32 = null;
        for (s.supply) |e| {
            if (e.fun == j and e.prov.kind == .cb and e.prov.a == j and e.path == eps and e.prov.path == eps and e.owned) {
                if (acc != null and acc.? != e.k) return null;
                acc = e.k;
            }
        }
        const k = acc orelse return null;
        var start: ?u32 = null;
        for (s.supply) |e| {
            if (e.fun != j or e.k != k) continue;
            if (!e.owned or e.path != eps or e.prov.path != eps) return null;
            switch (e.prov.kind) {
                .cb => if (e.prov.a != j) return null,
                .param => {
                    if (start != null and start.? != e.prov.a) return null;
                    start = e.prov.a;
                },
                else => return null,
            }
        }
        const initial = start orelse return null;
        for (s.uses) |u| if (u.param == initial and u.bits & (bit_e | bit_j) != 0) return null;
        for (s.res) |r| {
            if ((r.prov.kind == .param and r.prov.a == initial) or (r.prov.kind == .cb and r.prov.a == j)) {
                if (r.path != eps or r.prov.path != eps) return null;
            }
        }
        for (classes) |cls| {
            const c = (try w.classSummary(cls)) orelse return null;
            if (c.limit != .none or k >= c.params) return null;
            for (c.uses) |u| {
                if (u.param != k) continue;
                if (u.bits & (bit_e | bit_j) != 0) return null;
                if (u.bits & bit_w == 0) continue;
                for (c.res) |r| {
                    if (!w.o.isPrefix(r.path, u.path)) continue;
                    switch (r.prov.kind) {
                        .fresh => {},
                        .param => if (r.prov.a != k or r.prov.path != r.path) return null,
                        else => return null,
                    }
                }
            }
        }
        return k;
    }

    /// Cells use the usual least fixpoint; container conditions use the
    /// greatest must-invariant. Initial/shared cells are never reseeded.
    fn instFold(w: *Walker, j: u32, classes: []const Class, ctx: InstCtx) Allocator.Error!AV {
        var shape: AV = &.{};
        var made: std.ArrayList(u32) = .empty;
        var inner = ctx;
        inner.self_j = j;
        inner.conds = ctx.conds;
        inner.effects = ctx.effects;
        inner.callback_fresh = &made;
        var stable = false;
        // §16.7, the amendment of 2026-10-25 (#955): an accumulator of an
        // unnamed cyclic type takes the composed-path fold.
        const cyclic = try w.cyclicAccumulator(j, ctx);
        for (0..round_cap) |_| {
            inner.self_av = shape;
            const grew = w.carry_grew;
            var next = try w.unionOf(&.{ shape, try w.instCbOnce(j, classes, inner) });
            if (cyclic) next = try w.foldNesting(shape, next);
            if (next.len == shape.len and w.carry_grew == grew) {
                stable = true;
                break;
            }
            shape = next;
        }
        if (!stable) {
            try w.o.hitLimit(.fixpoint, round_cap);
            return w.unionOf(&.{ shape, try w.single(.{ .kind = .top, .a = 1 }) });
        }
        if (!ctx.conds) return shape;
        var future: std.ArrayList(u32) = .empty;
        for (made.items) |cell_id| {
            if (try w.isEscaped(cell_id)) continue;
            const in_shape = for (shape) |e| {
                if (e.cell == cell_id) break true;
            } else false;
            if (!in_shape) continue;
            // A supplied cell never receives a seed, even if abstract fresh
            // ids collide or an entry's namespace numbers exceed the stride.
            var initial = false;
            for (ctx.avs) |av| if ((try w.reaches(av, &.{.{ .path = eps, .cell = cell_id }})) != null) {
                initial = true;
                break;
            };
            if (initial) continue;
            try future.append(w.a, cell_id);
            w.spine_writes += 1;
            w.cell_spine.items[cell_id] = cond_yes;
        }
        inner.self_av = shape;
        inner.callback_fresh = null;
        inner.conds = true;
        inner.effects = false;
        var settled = false;
        for (0..round_cap) |_| {
            const before = try w.a.dupe(u32, w.cell_spine.items);
            const grew = w.carry_grew;
            const escapes_before = w.escaped.items.len;
            const uses = w.uses.items.len;
            const demands = w.demands.items.len;
            const reqs = w.reqs.items.len;
            _ = try w.instCbOnce(j, classes, inner);
            if (std.debug.runtime_safety) {
                std.debug.assert(escapes_before == w.escaped.items.len);
                std.debug.assert(uses == w.uses.items.len);
                std.debug.assert(demands == w.demands.items.len);
                std.debug.assert(reqs == w.reqs.items.len);
            }
            if (w.carry_grew == grew and std.mem.eql(u32, before, w.cell_spine.items)) {
                settled = true;
                break;
            }
        }
        // Only future cells received optimistic seeds. Every other condition
        // was only weakened by conjunction, so exhaustion keeps those safe
        // facts; the lost seeds are the compiler's limit, an error (§16.7).
        if (!settled) {
            try w.o.hitLimit(.fixpoint, round_cap);
            for (future.items) |c| try w.lowerSpine(c, cond_limit);
        }
        inner.effects = ctx.effects;
        return w.unionOf(&.{ shape, try w.instCbOnce(j, classes, inner) });
    }

    /// Whether the fold's callback answers a value of an unnamed cyclic
    /// type (§16.7, the amendment of 2026-10-25): `List.intersperse` as
    /// `List.foldr`'s callback answers `List (List …)`, which only
    /// instantiation makes and no type name stands for.
    fn cyclicAccumulator(w: *Walker, j: u32, ctx: InstCtx) Allocator.Error!bool {
        const fn_ref = (try w.callbackType(j, ctx)) orelse return false;
        const parts = switch (try w.tyShape(fn_ref)) {
            .func => |all| all,
            else => return false,
        };
        return switch (parts[parts.len - 1]) {
            .store => |v| cyclicVar(w.a, w.store, v),
            else => false,
        };
    }

    /// One round of an accumulator fixpoint whose type is an unnamed cycle,
    /// folded on the composed path (§16.7, the amendment of 2026-10-25): an
    /// entry new this round whose cell `shape` holds at a proper, nonempty
    /// suffix `X` of its path `r X` is the accumulator nested once more,
    /// and goes to `r⋆`. The first nesting stays exact, as F3's first
    /// composition does; a fold only merges places, and `foldedPairs`
    /// judges the pairs it merges.
    fn foldNesting(w: *Walker, shape: AV, next: AV) Allocator.Error!AV {
        var out: ?[]Entry = null;
        for (next, 0..) |e, i| {
            const known = for (shape) |s| {
                if (s.path == e.path and s.cell == e.cell) break true;
            } else false;
            if (known) continue;
            const st = w.o.steps(e.path);
            const depth_r = for (shape) |s| {
                if (s.cell != e.cell or s.path == eps or s.path == e.path) continue;
                const sx = w.o.steps(s.path);
                if (sx.len >= st.len) continue;
                const tail = st[st.len - sx.len ..];
                const same = for (tail, sx) |x, y| {
                    if (x.kind != y.kind or x.arg != y.arg) break false;
                } else true;
                if (same) break st.len - sx.len;
            } else null;
            const r = depth_r orelse continue;
            const o = out orelse blk: {
                const copy = try w.a.dupe(Entry, next);
                out = copy;
                break :blk copy;
            };
            o[i].path = try w.cutAt(e.path, r);
            if (o[i].approx == 0) o[i].approx = approx_place;
        }
        const folded = out orelse return next;
        try w.foldedPairs(next, folded);
        return w.norm(folded);
    }

    fn instCbOnce(w: *Walker, j: u32, classes: []const Class, ctx: InstCtx) Allocator.Error!AV {
        // A callback's instantiation reads and writes what no table write
        // counts (its arguments, its result's cells): kept conditions go.
        w.other_writes += 1;
        var out: std.ArrayList(Entry) = .empty;
        var deeper = ctx;
        deeper.depth += 1;
        // Merely supplying a cell is not a callback allocation.
        deeper.callback_fresh = null;
        for (classes) |cls| {
            const original = (try w.classSummary(cls)) orelse return w.unknownCb(j, ctx);
            // The callback's parameters are what the callee supplies it.
            const params = try w.a.alloc(AV, original.params);
            for (params, 0..) |*pa, k| {
                var parts: std.ArrayList(AV) = .empty;
                for (ctx.s.supply) |e| {
                    if (e.fun != j or e.k != k) continue;
                    try parts.append(w.a, try w.composeSupply(e, try w.supplyCells(e.prov, ctx, deeper), ctx));
                }
                pa.* = try w.unionOf(parts.items);
            }
            const poly = switch (cls) {
                .func => |t| try w.memberParamTypes(t),
                .closure => |ci| try w.localParamTypes(ci),
                else => &.{},
            };
            const need_type = original.cast_signature != none or poly.len != 0 or for (original.res) |r| {
                if (r.path == eps and r.prov.kind == .param and r.prov.path == eps) break true;
            } else false;
            const fn_ref = if (need_type) try w.callbackType(j, ctx) else null;
            const refs: []const TyRef = if (fn_ref) |ty| switch (try w.tyShape(ty)) {
                .func => |all| all,
                else => &.{},
            } else &.{};
            const saved_paths = w.cast_fold_scope;
            const saved_crossings = w.cast_crossings;
            defer w.cast_fold_scope = saved_paths;
            defer w.cast_crossings = saved_crossings;
            w.cast_fold_next += 1;
            w.cast_fold_scope = w.cast_fold_next;
            w.cast_crossings = .empty;
            const c = if (fn_ref) |ty| try w.castFunctionSummary(original, ty, poly.len != 0) else original;
            const sub: InstCtx = .{ .inst = ctx.inst, .s = c, .avs = params, .closure = if (cls == .closure) cls.closure else none, .depth = ctx.depth + 1, .conds = ctx.conds, .effects = ctx.effects, .callback_fresh = ctx.callback_fresh, .poly = poly, .arg_refs = if (refs.len == c.params + 1) refs[0..c.params] else &.{}, .result_ref = if (refs.len == c.params + 1) refs[c.params] else null };
            try out.appendSlice(w.a, try w.instRes(c, sub));
        }
        return w.norm(out.items);
    }

    /// A callback with no class: §6.1's conservative result over what the
    /// callee supplies it and what it holds. Its own cell is `⊤call`: the
    /// function may return a list something else holds (§30.11).
    fn unknownCb(w: *Walker, j: u32, ctx: InstCtx) Allocator.Error!AV {
        var out: std.ArrayList(Entry) = .empty;
        try out.append(w.a, .{ .path = eps, .cell = try w.cell(.{ .kind = .top, .a = top_call }) });
        const any = try w.o.child(eps, .any, 0);
        var from: std.ArrayList(AV) = .empty;
        for (ctx.s.supply) |e| {
            if (e.fun != j) continue;
            try from.append(w.a, try w.supplyCells(e.prov, ctx, .{ .inst = ctx.inst, .s = ctx.s, .avs = ctx.avs, .closure = ctx.closure, .depth = ctx.depth + 1, .effects = ctx.effects }));
        }
        if (try w.actualOf(ctx.s, ctx.avs, j)) |actual| try from.append(w.a, actual);
        for (from.items) |av| for (try w.expand(av)) |e| {
            const c = w.cells.items[e.cell];
            if (c.kind == .closure or c.kind == .func) continue;
            try out.append(w.a, .{ .path = any, .cell = e.cell, .approx = ctx.inst.int() + 1, .grown = e.grown });
        };
        return w.norm(out.items);
    }

    /// A call-site demand (§16.4 item 3): argument `i`'s cells at `q`,
    /// Disjoint against every other argument and every other path of `i`.
    fn callSiteDemand(w: *Walker, inst: Inst.Index, op: []const u8, args: []const Inst.Index, avs: []const AV, i: u32, q: u32, note: []const u8, origin: Origin, xfail: ?Rely) Allocator.Error!void {
        return w.callSiteDemandDeep(inst, op, args, avs, &.{}, i, q, note, origin, xfail, false, .deep);
    }

    /// `deep`: a send's demand (§23.2), on every cell at or below `q`; one
    /// on no cell gives nothing up and is no line.
    fn callSiteDemandDeep(w: *Walker, inst: Inst.Index, op: []const u8, args: []const Inst.Index, avs: []const AV, callee_av: AV, i: u32, q: u32, note: []const u8, origin: Origin, xfail_in: ?Rely, deep: bool, extent: WriteExtent) Allocator.Error!void {
        const at = try w.projPath(avs[i], q, null);
        // §16.7: a written place under a marker is the lists of every level
        // it stands for, written one by one; they are distinct lists only
        // if the argument is exclusive where the marker's region begins.
        var xfail = xfail_in;
        if (try w.markerAnchor(q)) |anchor| {
            const r = try w.rely(try w.deepCond(try w.projPath(avs[i], anchor, null)), w.frame);
            if (r != .ok) xfail = Rely.worse(xfail, r);
        }
        // §31.2: a send gives up its payload's record objects to the record
        // demand; a list's reads the rest (`listView`).
        const base = if (deep) try w.listView(try w.flat(at)) else at;
        if (deep and base.len == 0) return;
        var others: std.ArrayList(AV) = .empty;
        try others.append(w.a, callee_av);
        for (avs, 0..) |av, x| if (x != i) try others.append(w.a, av);
        var rest: std.ArrayList(Entry) = .empty;
        // The entries that do overlap `q`: what the callee's other places
        // can reach that `rest` does not.
        var over: std.ArrayList(Entry) = .empty;
        for (avs[i]) |e| {
            if (w.o.overlap(e.path, q)) {
                try over.append(w.a, e);
                continue;
            }
            // Another path of the argument is an operand only where the callee
            // uses it: a place it never reads, keeps or writes it cannot see
            // the write at (§16.7; a call with no summary's uses keeps every
            // path, as before).
            if (w.call_uses.len > 0) {
                const used = for (w.call_uses) |u| {
                    if (u.param != i or noUse(u.bits) or !w.o.overlap(u.path, e.path)) continue;
                    // A read of a place above `e` reads that place, not what is
                    // below it: only a use that keeps, returns or writes it
                    // reaches `e` from above.
                    if (u.bits & ~bit_r != 0 or !w.o.isPrefix(u.path, e.path) or u.path == e.path) break true;
                } else false;
                if (!used) continue;
            }
            try rest.append(w.a, e);
        }
        try others.append(w.a, rest.items);
        // §16.7: the callee's other places of this argument, which it took
        // for places apart from `q`. One that is the written cell here is a
        // cell that stands for several (a level's, an element's): they are
        // apart only if the argument is exclusive where that cell begins to
        // stand for several, and the demand relies on it; any other is
        // another holder of the cell, approximately.
        // core Dict's tree keeps the merged fold, its levels trusted apart
        // (§20.9): its places are not compared so.
        const in_dict = try w.o.dictTreePath(q);
        for (w.call_uses) |u| {
            if (in_dict or over.items.len == 0 or u.param != i or noUse(u.bits) or w.o.overlap(u.path, q)) continue;
            if (try w.o.dictTreePath(u.path)) continue;
            var there: std.ArrayList(Entry) = .empty;
            for (try w.projPath(over.items, u.path, null)) |e| {
                const same = for (base) |b| {
                    if ((try w.covers(e.cell, b.cell)) != null) break true;
                } else false;
                if (same and try w.reliesApart(e.cell)) continue;
                // §16.7 (e): a cell that stands for several levels of a region
                // is another level, which the checker cannot tell apart.
                const levels = w.o.levelMarked(w.cells.items[e.cell].path) or w.o.levelMarked(u.path);
                try there.append(w.a, .{ .path = e.path, .cell = e.cell, .approx = if (e.approx != 0) e.approx else if (levels) approx_level else approx_place, .grown = e.grown });
            }
            try others.append(w.a, there.items);
        }
        const arena = w.o.out.allocator();
        const text = if (w.mode == .report) try w.baseText(args[i]) else "";
        const base_text = if (q == eps or w.mode != .report) text else try std.fmt.allocPrint(arena, "{s}{s}", .{ text, try w.o.pathText(q) });
        const ref = try w.refPath(args[i]);
        try w.demandOn(.{
            .kind = .callsite,
            .token = w.token(inst),
            .op = op,
            .base_text = base_text,
            .base_ref = if (ref) |r| .{ .local = r.local, .path = try w.o.concat(r.path, q) } else null,
            .base_ty = if (q == eps and !deep) w.instType(args[i]) else null,
            .base = base,
            .others = others.items,
            .note = note,
            .origin = origin,
            .xfail = xfail,
            .deep = deep,
            .extent = extent,
            .base_inst = if (q == eps) args[i] else null,
        });
    }

    /// The prefix of `p` before its first marker, when it has one.
    fn markerAnchor(w: *Walker, p: u32) Allocator.Error!?u32 {
        if (!w.o.paths.any.items[p]) return null;
        const ns = w.o.pathNodes(p);
        for (ns, 0..) |n, k| if (w.o.paths.kind.items[n] == .level) return if (k == 0) eps else ns[k - 1];
        return null;
    }

    /// §16.7 (e): whether `c` is a symbolic cell that stands for the lists of
    /// several levels of one region of a recursive value (its path goes
    /// through the level marker): two bindings of it may be two levels.
    fn standsForLevels(w: *const Walker, c: u32) bool {
        const x = w.cells.items[c];
        return switch (x.kind) {
            .param, .env, .cbres, .result => w.o.levelMarked(x.path),
            else => false,
        };
    }

    /// §16.7: a symbolic cell that stands for several places — under `[*]`
    /// or a marker — names two of a callee's places apart when the argument
    /// is exclusive at the place before the step that makes it stand for
    /// several; true when this frame can rely on that (§18.4).
    fn reliesApart(w: *Walker, c: u32) Allocator.Error!bool {
        const k = (try w.apartCond(c)) orelse return false;
        return try w.rely(k, w.frame) == .ok;
    }

    /// The condition under which the places a symbolic cell stands for
    /// (under `[*]` or a marker) hold distinct lists: the cell before the
    /// step that makes it stand for several is exclusive. Null for a cell
    /// that is not symbolic or stands for one place.
    fn apartCond(w: *Walker, c: u32) Allocator.Error!?u32 {
        const x = w.cells.items[c];
        switch (x.kind) {
            .param, .env, .cbres => {},
            else => return null,
        }
        const ns = w.o.pathNodes(x.path);
        const cut = for (ns, 0..) |n, k| {
            switch (w.o.paths.kind.items[n]) {
                .elem, .level, .cast_level => break k,
                else => {},
            }
        } else return null;
        var y = x;
        y.path = if (cut == 0) eps else ns[cut - 1];
        y.ty = .none;
        return try w.atomCond(.{ .kind = .excl, .a = try w.cell(y) });
    }

    /// §31.7: the caller's side of a callee's record write: a demand on the
    /// record objects argument `i` holds at path `q`, writing `fields` (all of
    /// them when a block could not say which).
    fn callSiteRecordDemand(w: *Walker, inst: Inst.Index, args: []const Inst.Index, avs: []const AV, callee_av: AV, i: u32, q: u32, fields: []const u32, origin: Origin) Allocator.Error!void {
        return w.callSiteRecordDemandX(inst, args, avs, callee_av, i, q, fields, origin, null);
    }

    /// `callSiteRecordDemand`, with what the callee relied on of the
    /// argument's records and may not have (`rxreq`, §31.4 item 6).
    fn callSiteRecordDemandX(w: *Walker, inst: Inst.Index, args: []const Inst.Index, avs: []const AV, callee_av: AV, i: u32, q: u32, fields: []const u32, origin: Origin, xfail: ?Rely) Allocator.Error!void {
        const base = try w.projPath(avs[i], q, null);
        var others: std.ArrayList(AV) = .empty;
        try others.append(w.a, callee_av);
        for (avs, 0..) |av, x| if (x != i) try others.append(w.a, av);
        var rest: std.ArrayList(Entry) = .empty;
        for (avs[i]) |e| if (!w.o.overlap(e.path, q)) try rest.append(w.a, e);
        try others.append(w.a, rest.items);
        const arena = w.o.out.allocator();
        const report = w.mode == .report;
        const text = if (report) try w.baseText(args[i]) else "";
        const ref = try w.refPath(args[i]);
        const written: []const u32 = if (fields.len != 0) fields else try w.allFields(base);
        try w.demandOn(.{
            .kind = .callsite,
            .inst = inst.int(),
            .token = w.token(inst),
            .op = "update",
            .base_text = if (!report or q == eps) text else try std.fmt.allocPrint(arena, "{s}{s}", .{ text, try w.o.pathText(q) }),
            .base_ref = if (ref) |r| .{ .local = r.local, .path = try w.o.concat(r.path, q) } else null,
            .base_ty = if (q == eps) w.instType(args[i]) else null,
            .base = base,
            .others = others.items,
            .note = if (report) try std.fmt.allocPrint(arena, "{s} writes it", .{try w.callName(inst)}) else "",
            .origin = origin,
            .base_inst = if (q == eps) args[i] else null,
            .fields = written,
            .xfail = xfail,
        });
    }

    /// Every field the records of `av` may have, for a write that names none:
    /// the fields of a closed record type at ε, else the empty set, which is
    /// every field (`unionFields`, `recordUse`).
    fn allFields(w: *Walker, av: AV) Allocator.Error![]const u32 {
        for (av) |e| if (e.path == eps) if (w.cells.items[e.cell].ty.unwrap()) |v| if (w.recordFields(v)) |fs| {
            const out = try w.a.alloc(u32, fs.len);
            for (fs, out) |f, *x| x.* = @backingInt(f.name);
            std.mem.sort(u32, out, {}, std.sort.asc(u32));
            return out;
        };
        return &.{};
    }

    /// A probe (§16.4 item 4): whether `av`'s cells pass the four conditions
    /// at this point; resolved with the demands, printed by none.
    /// §18.8: a demand a once closure makes — its creation on the captures
    /// it writes (`creation`), or a call on its own cell (`probe`) — resolved
    /// with the probes, and read back where its writes are decided.
    fn onceDemand(w: *Walker, kind: DemandKind, tok: u32, base: AV, base_ref: ?Capture, ci: u32) Allocator.Error!u32 {
        return w.onceDemandDeep(kind, tok, base, base_ref, ci, false);
    }

    fn onceDemandDeep(w: *Walker, kind: DemandKind, tok: u32, base: AV, base_ref: ?Capture, ci: u32, deep: bool) Allocator.Error!u32 {
        return w.onceDemandFields(kind, tok, base, base_ref, ci, deep, .deep, null);
    }

    /// `onceDemandDeep` with a record write's fields: a record demand.
    fn onceDemandFields(w: *Walker, kind: DemandKind, tok: u32, base: AV, base_ref: ?Capture, ci: u32, deep: bool, extent: WriteExtent, fields: ?[]const u32) Allocator.Error!u32 {
        // `deep` is a send's, which gives up a list's cells (§23.2); no record
        // demand is one, so a capture written with fields is never deep.
        std.debug.assert(!(deep and fields != null));
        const idx: u32 = @intCast(w.probe_ok.items.len);
        try w.probe_ok.append(w.a, false);
        try w.probe_record.append(w.a, fields != null);
        try w.probe_approx.append(w.a, false);
        try w.probe_info.append(w.a, null);
        try w.demandOn(.{
            .kind = kind,
            .token = tok,
            .op = "",
            .base_text = "",
            .base_ref = base_ref,
            .base_ty = null,
            .base = base,
            .others = &.{},
            .probe = idx,
            .closures = true,
            .creation_ci = if (kind == .creation) ci else none,
            .deep = deep,
            .extent = extent,
            .fields = fields,
        });
        return idx;
    }

    /// Every cell `av` holds, closures expanded, at ε: what a send gives up
    /// (§23.2), as a probe's base is (§16.4 item 4).
    fn flat(w: *Walker, av: AV) Allocator.Error!AV {
        var base: std.ArrayList(Entry) = .empty;
        for (try w.expand(av)) |e| {
            const k = w.cells.items[e.cell].kind;
            if (k == .closure or k == .func) continue;
            // A send value is the runtime's function, never a list, and it
            // holds nothing of the program's (§23.3, §30.9).
            if (w.isSend(w.cells.items[e.cell])) continue;
            try base.append(w.a, .{ .path = eps, .cell = e.cell, .approx = e.approx, .grown = e.grown });
        }
        return w.norm(base.items);
    }

    fn probeDemand(w: *Walker, inst: Inst.Index, av: AV, others: []const AV) Allocator.Error!u32 {
        const idx: u32 = @intCast(w.probe_ok.items.len);
        try w.probe_ok.append(w.a, false);
        try w.probe_record.append(w.a, false);
        try w.probe_approx.append(w.a, false);
        try w.probe_info.append(w.a, null);
        var base: std.ArrayList(Entry) = .empty;
        for (try w.expand(av)) |e| {
            const k = w.cells.items[e.cell].kind;
            if (k == .closure or k == .func) continue;
            if (w.isSend(w.cells.items[e.cell])) continue;
            try base.append(w.a, .{ .path = eps, .cell = e.cell, .approx = e.approx, .grown = e.grown });
        }
        try w.demandOn(.{
            .kind = .probe,
            .token = w.token(inst),
            .op = "",
            .base_text = "",
            .base_ref = null,
            .base_ty = null,
            .base = base.items,
            .others = others,
            .probe = idx,
        });
        return idx;
    }

    /// A function value's line (§16.5, §16.11).
    fn valueLine(w: *Walker, tok: u32, name: []const u8, verdict: Verdict, detail: []const u8, note: []const u8, assumed: bool) Allocator.Error!void {
        try w.demands.append(w.a, .{
            .kind = .value,
            .token = tok,
            .op = "value",
            .base = name,
            .base_local = none,
            .base_path = eps,
            .point = w.point,
            .frame = w.frame,
            .ctx = w.ctx,
            .element = false,
            .accept = .callback_param,
            .holders = &.{},
            .fixed = .{ .verdict = verdict, .detail = detail, .assumed = assumed },
            .note = note,
        });
    }

    /// Where class `cls` is written, when it is a lambda or local function
    /// of this module.
    fn classToken(w: *const Walker, cls: ?Class) u32 {
        const c = cls orelse return none;
        return switch (c) {
            .closure => |ci| w.closures.items[ci].token,
            else => none,
        };
    }

    /// A `need` rejection (§16.2, §23.5) of a function value `name`: exact
    /// when an exact provenance of what it returns fails, approximate when
    /// only an approximate step or a list from JavaScript does (§28.5, §30.9).
    /// `cls` is the function that fails, when one does: a lambda or local
    /// function written here is a place of the message (§28.6).
    fn needLine(w: *Walker, tok: u32, name: []const u8, detail: []const u8, approx: bool, assumed: bool, cls: ?Class) Allocator.Error!void {
        try w.demands.append(w.a, .{
            .kind = .value,
            .token = tok,
            .via = w.classToken(cls),
            .op = "value",
            .base = name,
            .base_local = none,
            .base_path = eps,
            .point = w.point,
            .frame = w.frame,
            .ctx = w.ctx,
            .element = false,
            .accept = .callback_param,
            .holders = &.{},
            .fixed = .{ .verdict = .{ .rejected = if (w.limit_callee) .limit else .need }, .detail = detail, .assumed = assumed },
            .prelim = .{ .cause = if (w.limit_callee) .limit else .need, .detail = detail, .approx = approx or w.limit_callee },
        });
    }

    /// Whether `returnsOwned` fails only through approximate entries: it
    /// holds once they are left out (`ro_exact`).
    fn ownedButApprox(w: *Walker, c: *const Summary, s: *const Summary, avs: []const AV, ictx: InstCtx, j: u32) Allocator.Error!bool {
        const previous = w.ro_exact;
        w.ro_exact = true;
        defer w.ro_exact = previous;
        return w.returnsOwned(c, s, avs, ictx, j, 0, none, .deep);
    }

    /// §30.3, §30.9: a function the runtime calls with crossing arguments
    /// and sends what it returns — `onUrlRequest`, `onUrlChange` — must
    /// return owned: what it makes, or what it is handed, which crosses.
    fn entryTagger(w: *Walker, inst: Inst.Index, field: []const u8, av: AV) Allocator.Error!void {
        if (av.len == 0) return;
        const tok = w.token(inst);
        const arena = w.o.out.allocator();
        const name = try std.fmt.allocPrint(arena, "<{s}>", .{field});
        const unknown = try std.fmt.allocPrint(arena, "the runtime sends what {s} returns, and the checker does not know which function it is, so not that it returns a list it owns", .{field});
        const classes = try w.classesOf(av);
        if (classes.len == 0) return w.needLine(tok, name, unknown, true, false, null);
        for (classes) |cls| {
            const c = (try w.classSummary(cls)) orelse return w.needLine(tok, name, unknown, true, false, null);
            const ictx: InstCtx = .{ .inst = inst, .s = &runtime_row, .avs = &.{}, .closure = if (cls == .closure) cls.closure else none, .depth = 0 };
            if (try w.returnsOwned(c, &runtime_row, &.{}, ictx, 0, 0, none, .deep)) continue;
            const approx = try w.ownedButApprox(c, &runtime_row, &.{}, ictx, 0);
            const shown = switch (cls) {
                .closure => "<lambda>",
                .func => |t| try w.qualified(t),
                .send => "send",
            };
            return w.needLine(tok, shown, try std.fmt.allocPrint(arena, "the runtime sends what {s} returns, which may be a list it does not own (§30.3)", .{field}), approx, false, cls);
        }
    }

    fn recordHasField(w: *Walker, ty: ?Var, name: u32) bool {
        const fields = w.recordFields(ty) orelse return false;
        for (fields) |f| if (@backingInt(f.name) == name) return true;
        return false;
    }

    fn firstUnseen(w: *Walker, t: Target) Allocator.Error!bool {
        const gop = try w.unseen_funcs.getOrPut(w.a, (@as(u64, t.m) << 32) | t.d);
        return !gop.found_existing;
    }

    const Sight = union(enum) {
        /// The value leaves the walk's sight (§16.5).
        pending: []const u8,
        /// It is handed to a callee with no summary (§15 decision 2).
        no_summary: []const u8,
    };

    /// Every writing function value in `av` that goes where the walk cannot
    /// see its calls, and every function parameter that does (§16.5).
    fn sight(w: *Walker, av: AV, why: Sight, tok: u32) Allocator.Error!void {
        try w.sightAt(av, why, tok, 0);
    }

    fn sightAt(w: *Walker, av: AV, why: Sight, tok: u32, depth: u32) Allocator.Error!void {
        // Each `◇` hop goes to a local of a strictly enclosing frame, so the
        // chain ends within the frames; the bound only guards that.
        if (depth > w.frames.items.len) return;
        for (av) |e| {
            const c = w.cells.items[e.cell];
            switch (c.kind) {
                .closure => {
                    // Its calls of the declaration's function parameters go
                    // out of sight with it (§18.9).
                    for (w.env_calls.items) |ec| if (ec.closure == c.a) {
                        w.fn_state.items[ec.j].seen = false;
                    };
                    const cl = &w.closures.items[c.a];
                    const cls = cl.class orelse continue;
                    if (!cls.writesAny() and !cls.writesRecord()) continue;
                    try cl.consumed.append(w.a, switch (why) {
                        .pending => |t| .{ .kind = .pending, .why = t, .limit = w.limit_callee },
                        .no_summary => |n| .{ .kind = .no_summary, .name = n },
                    });
                },
                .func => {
                    const t: Target = .{ .m = c.a, .d = c.b };
                    const s = (try w.o.ensureSummary(t.m, t.d)) orelse continue;
                    if (!s.writesAny()) continue;
                    switch (why) {
                        // A sight that follows from a limit does not count as
                        // the function's report: a later one of its own still
                        // prints (#272).
                        .pending => |t2| if (w.limit_callee) {
                            if (!w.unseen_funcs.contains((@as(u64, t.m) << 32) | t.d)) try w.valueLine(tok, try w.qualified(t), .{ .rejected = .limit }, t2, "", false);
                        } else if (try w.firstUnseen(t)) try w.valueLine(tok, try w.qualified(t), .pending, t2, "", false),
                        .no_summary => |n| try w.valueLine(tok, try w.qualified(t), .{ .accepted = .callback_param }, "", try std.fmt.allocPrint(w.o.out.allocator(), "no summary: {s}", .{n}), true),
                    }
                },
                .param => {
                    if (c.b != 0 or c.path != eps) continue;
                    // One handed to a send position is kept by the value the
                    // position makes, and its row says what the runtime does
                    // with it there (§23.3).
                    for (w.params, 0..) |p, i| if (p.int() == c.a and w.fn_state.items[i].is_fn and w.fn_state.items[i].send == none) {
                        w.fn_state.items[i].seen = false;
                    };
                },
                .env => {
                    const held = w.local_av[c.a] orelse continue;
                    try w.sightAt(try w.projPath(held, c.path, null), why, tok, depth + 1);
                },
                .site, .result, .shared, .top, .cbres, .taken, .payload, .except => {},
            }
        }
    }

    // ---- function slots and carried lambdas (§24.9) ----------------------

    /// Whether callee `s`'s function parameter or slot `j` has an actual
    /// among `n` arguments.
    fn hasActual(s: *const Summary, n: usize, j: u32) bool {
        if (j < s.params) return j < n;
        const k = j - s.params;
        return k < s.slots.len and s.slots[k][0] < n;
    }

    /// The value callee `s` calls as its function parameter or slot `j`:
    /// the argument, or the function stored in it at the slot's path.
    fn actualOf(w: *Walker, s: *const Summary, avs: []const AV, j: u32) Allocator.Error!?AV {
        if (!hasActual(s, avs.len, j)) return null;
        if (j < s.params) return avs[j];
        const slot = s.slots[j - s.params];
        return try w.projPath(avs[slot[0]], slot[1], null);
    }

    /// The declaration's function slot a value is (§24.9): a function stored
    /// at a path of one of its own parameters, numbered after them on first
    /// sight. Not in a recursive group, whose rounds would number the slots
    /// apart. Inside a lambda (§30.9) it is a capture of the parameter, at
    /// the path: the slot is the declaration's, called or handed on wherever
    /// the lambda runs.
    fn slotOf(w: *Walker, av: AV) Allocator.Error!?u32 {
        var found: ?Cell = null;
        for (av) |e| {
            if (w.cells.items[e.cell].condition_only) continue;
            if (w.o.firstStep(e.path)) |s| if (s.kind == .env) continue;
            if (e.path != eps or found != null) return null;
            found = w.cells.items[try w.takenBase(e.cell)];
        }
        var c = found orelse return null;
        if (w.frame != 0) {
            // A capture of a local of the declaration's own frame that holds
            // exactly one of its parameters.
            if (c.kind != .env or c.a >= w.local_frame.len or w.local_frame[c.a] != 0) return null;
            const held = w.local_av[c.a] orelse return null;
            const value_held = w.onlyValue(held) orelse return null;
            if (value_held.path != eps) return null;
            const hc = w.cells.items[try w.takenBase(value_held.cell)];
            if (hc.kind != .param or hc.b != 0) return null;
            const path = try w.o.concat(hc.path, c.path);
            c = hc;
            c.path = path;
        }
        if (c.kind != .param or c.b != 0 or c.path == eps) return null;
        const pi = w.paramIndex(c, 0, w.params) orelse return null;
        for (w.slot_keys.items, 0..) |key, k| if (key[0] == pi and key[1] == c.path) return @intCast(w.params.len + k);
        try w.slot_keys.append(w.a, .{ pi, c.path });
        try w.fn_state.append(w.a, .{ .is_fn = true });
        return @intCast(w.fn_state.items.len - 1);
    }

    /// A lambda a callee's result carries (`ctx.s.klasses[p.a]`, §24.9), as a
    /// closure of this body: its captures hold what the callee's bindings
    /// say, instantiated at this call, and the function values its calls of
    /// the callee's parameters go to leave sight here — the checker does not
    /// see what the lambda hands them.
    fn carry(w: *Walker, p: Prov, ctx: InstCtx) Allocator.Error!AV {
        if (p.a == none) {
            const site: CarrySite = .{ .inst = ctx.inst.int(), .sum = @intFromPtr(ctx.s), .klass = none, .depth = ctx.depth, .ns = ctx.fresh_ns, .merge = false };
            const g = try w.carry_sites.getOrPut(w.a, site);
            if (!g.found_existing) {
                g.value_ptr.* = @intCast(w.closures.items.len);
                try w.closures.append(w.a, .{ .captures = &.{}, .token = w.token(ctx.inst) });
            }
            return w.single(.{ .kind = .closure, .a = g.value_ptr.* });
        }
        if (p.a >= ctx.s.klasses.len) return w.single(.{ .kind = .top, .a = 0 });
        const k = ctx.s.klasses[p.a];
        var inner = ctx;
        inner.closure = none;
        const binds = try w.a.alloc(Closure.SynBind, k.binds.len);
        const grown = try w.grownArgs(inner);
        for (binds, k.binds) |*b, kb| {
            var before: std.ArrayList(Entry) = .empty;
            var after: std.ArrayList(Entry) = .empty;
            var cut = false;
            for (kb.provs) |r| {
                const raw_cells = try w.instProv(r.prov, inner);
                const cells = if (r.prov.condition_only) try w.annotationSpines(raw_cells, r.sc, inner, r.grown, grown, null) else raw_cells;
                if (r.prov.condition_only) for (cells) |e| if (e.path == eps) {
                    try w.initCond(e.cell, try w.instXSum(r.xc, inner));
                    try w.rinitCond(e.cell, try w.rinstXSum(r.rxc, inner));
                };
                var av: AV = try w.composeRes(r, cells, grown, &before, &cut);
                if (r.approx) av = try w.approxAll(av, ctx.inst);
                try after.appendSlice(w.a, av);
            }
            if (cut) try w.foldedPairs(before.items, after.items);
            b.* = .{ .local = kb.local, .path = kb.path, .av = try w.norm(after.items) };
        }
        const cbs = try w.a.alloc(Closure.SynCall, k.cb_js.len);
        for (cbs, k.cb_js) |*c, j| {
            // A function slot (§30.9): the function at its path of the argument.
            const av = if (j >= ctx.s.params) blk: {
                const k_slot = j - ctx.s.params;
                if (k_slot >= ctx.s.slots.len or ctx.s.slots[k_slot][0] >= ctx.avs.len) break :blk try w.single(.{ .kind = .top, .a = 0 });
                break :blk try w.projPath(ctx.avs[ctx.s.slots[k_slot][0]], ctx.s.slots[k_slot][1], null);
            } else try w.instProv(.{ .kind = .param, .a = j }, inner);
            c.* = .{ .j = j, .av = av };
            if (ctx.effects) try w.sight(c.av, .{ .pending = "a function value a callee returned calls it" }, w.token(ctx.inst));
        }
        // One closure per place it is made (§20.4, amended 2026-10-16): a
        // fixpoint's rounds instantiate the same call again, and a closure
        // per round would be a new cell each round, so no round could ever
        // equal the one before (#229). Its captures are the union of every
        // instantiation's, as `result(call, k)` stands for every round's
        // new list: aliasing only grows.
        const site: CarrySite = .{ .inst = ctx.inst.int(), .sum = @intFromPtr(ctx.s), .klass = p.a, .depth = ctx.depth, .ns = ctx.fresh_ns, .merge = ctx.merge_fresh };
        const gop = try w.carry_sites.getOrPut(w.a, site);
        // The site fixes the lambda, so its captures and calls are the same
        // list in every instantiation; were they not, the lambda is made
        // anew, as before #229 — a fixpoint then ends on its loud limit.
        const same = gop.found_existing and w.closures.items[gop.value_ptr.*].binds.len == binds.len and
            w.closures.items[gop.value_ptr.*].cb_avs.len == cbs.len;
        if (same) {
            const cl = &w.closures.items[gop.value_ptr.*];
            var grew = false;
            for (binds, cl.binds) |*b, old| {
                const u = try w.unionOf(&.{ old.av, b.av });
                if (u.len != old.av.len) {
                    grew = true;
                } else for (u, old.av) |next, previous| {
                    if (!std.meta.eql(next, previous)) {
                        grew = true;
                        break;
                    }
                }
                b.av = u;
            }
            for (cbs, cl.cb_avs) |*c, old| {
                const u = try w.unionOf(&.{ old.av, c.av });
                if (u.len != old.av.len) {
                    grew = true;
                } else for (u, old.av) |next, previous| {
                    if (!std.meta.eql(next, previous)) {
                        grew = true;
                        break;
                    }
                }
                c.av = u;
            }
            if (grew) {
                cl.binds = binds;
                cl.cb_avs = cbs;
                w.carry_grew += 1;
            }
            return w.single(.{ .kind = .closure, .a = gop.value_ptr.* });
        }
        gop.value_ptr.* = @intCast(w.closures.items.len);
        // Its place is where the callee's result or the value that carries it
        // is used here (§28.6). `ctx.inst` is an instruction of this walk's
        // module, whose BIR numbers every declaration's instructions; only a
        // test's instruction is out of range.
        const tok = if (ctx.inst.int() < w.bir.insts.len) w.token(ctx.inst) else none;
        try w.closures.append(w.a, .{ .captures = &.{}, .class = k.sum, .binds = binds, .cb_avs = cbs, .carried = true, .token = tok });
        return w.single(.{ .kind = .closure, .a = gop.value_ptr.* });
    }

    /// The lambda `ci` as the declaration's result may carry it (§24.9): its
    /// class, and its captures in the declaration's vocabulary. Null when a
    /// caller would need more than its result and its reads — it writes,
    /// escapes, relies on exclusive contents, or runs once — or when one of
    /// its captures holds a function value, which has no provenance.
    fn carried(w: *Walker, ci: u32, params: []const Inst.Index, fresh: Fresh) Allocator.Error!?Carried {
        const cl = w.closures.items[ci];
        // §30.9: a lambda a callee's result carried here is carried on, its
        // bindings read off in this declaration's vocabulary, when it calls
        // nothing the caller passed.
        if (cl.carried) {
            if (cl.cb_avs.len != 0) return null;
            const ckeep = w.o.keep.allocator();
            var cbinds: std.ArrayList(Carried.Bind) = .empty;
            for (cl.binds) |b| {
                var provs: std.ArrayList(ResEntry) = .empty;
                for (try w.listView(try w.expand(b.av))) |e| {
                    const kind = w.cells.items[e.cell].kind;
                    if (kind == .closure or kind == .func) return null;
                    var prov = (try w.provOf(e.cell, 0, params, fresh)) orelse return null;
                    prov.taken = false;
                    try provs.append(ckeep, .{ .path = e.path, .prov = prov, .approx = e.approx != 0, .grown = e.grown, .xc = if (prov.condition_only) try w.xsumOf(try w.cellCond(e.cell), 0, params, none) else .{}, .sc = if (prov.condition_only) try w.xsumOf(try w.cellSpine(e.cell), 0, params, none) else .{}, .rxc = if (prov.condition_only) try w.rxsumOf(try w.rcellCond(e.cell), 0, params, none) else .{} });
                }
                try cbinds.append(ckeep, .{ .local = b.local, .path = b.path, .provs = provs.items });
            }
            const csum = cl.class orelse return null;
            // Its class may be a block's, read for one walk: the summary
            // that carries it on keeps a copy of its own.
            return .{ .sum = try w.o.cloneSummary(csum), .binds = cbinds.items };
        }
        const cls = cl.class orelse return null;
        // §30.9: what a callee relies on of its parameters is decided where
        // it is handed on or called, which a caller of the result is not.
        for (w.lambda_needs.items) |n| if (n.closure == ci) return null;
        if (cls.limit != .none or cls.once or cls.writesAny() or cls.xreq.len != 0 or cl.env_escapes.len != 0 or cl.env_writes.len != 0) return null;
        for (cls.uses) |u| if (u.bits & (bit_e | bit_j | bit_w) != 0) return null;
        const keep = w.o.keep.allocator();
        var binds: std.ArrayList(Carried.Bind) = .empty;
        for (cl.captures) |cap| {
            const held = w.local_av[cap.local] orelse continue;
            var provs: std.ArrayList(ResEntry) = .empty;
            for (try w.listView(try w.expand(try w.projPath(held, cap.path, null)))) |e| {
                const kind = w.cells.items[e.cell].kind;
                if (kind == .closure or kind == .func) return null;
                var prov = (try w.provOf(e.cell, 0, params, fresh)) orelse return null;
                prov.taken = false;
                try provs.append(keep, .{ .path = e.path, .prov = prov, .approx = e.approx != 0, .grown = e.grown, .xc = if (prov.condition_only) try w.xsumOf(try w.cellCond(e.cell), 0, params, none) else .{}, .sc = if (prov.condition_only) try w.xsumOf(try w.cellSpine(e.cell), 0, params, none) else .{}, .rxc = if (prov.condition_only) try w.rxsumOf(try w.rcellCond(e.cell), 0, params, none) else .{} });
            }
            try binds.append(keep, .{ .local = cap.local, .path = cap.path, .provs = provs.items });
        }
        var cb_js: std.ArrayList(u32) = .empty;
        for (w.env_calls.items) |ec| {
            if (ec.closure != ci or ec.j >= params.len + w.slot_keys.items.len) continue;
            if (std.mem.indexOfScalar(u32, cb_js.items, ec.j) == null) try cb_js.append(keep, ec.j);
        }
        for (w.env_passes.items) |ep| {
            if (ep[0] != ci or ep[1] >= params.len + w.slot_keys.items.len) continue;
            if (std.mem.indexOfScalar(u32, cb_js.items, ep[1]) == null) try cb_js.append(keep, ep[1]);
        }
        const sum = try keep.create(Summary);
        sum.* = cls.*;
        return .{ .sum = sum, .binds = binds.items, .cb_js = cb_js.items };
    }

    /// §30.9: what calling the function value `f` returns when what it is
    /// handed is not known — each of its classes' `res`, every parameter
    /// `⊤` — or null when a part of `f` has no class.
    fn callThrough(w: *Walker, f: AV, ctx: InstCtx) Allocator.Error!?AV {
        const classes = try w.classesOf(f);
        if (classes.len == 0) return null;
        var parts: std.ArrayList(AV) = .empty;
        for (classes) |cls| {
            const c = (try w.classSummary(cls)) orelse return null;
            if (c.limit != .none) return null;
            const args = try w.a.alloc(AV, c.params);
            for (args) |*x| x.* = try w.single(.{ .kind = .top, .a = 0 });
            try parts.append(w.a, try w.instRes(c, .{ .inst = ctx.inst, .s = c, .avs = args, .closure = if (cls == .closure) cls.closure else none, .depth = ctx.depth + 1, .conds = false, .effects = ctx.effects }));
        }
        return try w.unionOf(parts.items);
    }

    /// What a carried lambda's capture `p` holds (§24.9).
    fn carriedEnv(w: *Walker, ci: u32, p: Prov) Allocator.Error!AV {
        for (w.closures.items[ci].binds) |b| {
            if (b.local != p.a or !w.o.isPrefix(b.path, p.path)) continue;
            const rest = (try w.o.suffix(b.path, p.path)) orelse eps;
            return w.projPath(b.av, rest, null);
        }
        return w.single(.{ .kind = .top, .a = 0 });
    }

    /// The actual for function parameter `j` of a callee with a summary,
    /// checked against what the callee supplies it (§16.4 item 4).
    fn checkCallback(w: *Walker, inst: Inst.Index, callee: Callee, args: []const Inst.Index, avs: []const AV, j: u32) Allocator.Error!void {
        const s = callee.sum;
        const ff = s.funOf(j) orelse return;
        const actual = (try w.actualOf(s, avs, j)) orelse return;
        // A function slot (§24.9) has no argument of its own: what the
        // checks below read off an argument's text or type, they skip.
        if (j >= args.len or j >= s.params) return w.checkSlot(inst, callee, args, avs, j, ff, actual);
        // The caller's own function parameter or slot, passed on — inside a
        // lambda too, where the callee's facts are the declaration's
        // wherever the lambda runs (§30.9).
        if (w.fnParamOf(actual) orelse try w.slotOf(actual)) |jj| return w.passOn(inst, s, avs, j, ff, jj);
        const ictx: InstCtx = .{ .inst = inst, .s = s, .avs = avs, .closure = callee.closure, .depth = 0 };
        const classes = try w.classesOf(actual);
        try w.checkClasses(inst, callee, args, avs, j, try w.resolveNeed(s, avs, ff), actual, ictx, classes);
    }

    /// §24.9: a callee's function slot — a function it calls that is stored
    /// at a path of an argument. The caller's own parameter or slot there is
    /// passed on; a function value the caller wrote went through `sight`
    /// where it was stored, so what remains is what the callee does with
    /// what it returns (`need`).
    fn checkSlot(w: *Walker, inst: Inst.Index, slot_callee: Callee, args: []const Inst.Index, avs: []const AV, j: u32, facts: FunFacts, actual: AV) Allocator.Error!void {
        const s = slot_callee.sum;
        const callee = slot_callee.name;
        if (w.fnParamOf(actual) orelse try w.slotOf(actual)) |jj| return w.passOn(inst, s, avs, j, facts, jj);
        const ff = try w.resolveNeed(s, avs, facts);
        if (!ff.need) return;
        const ictx: InstCtx = .{ .inst = inst, .s = s, .avs = avs, .depth = 0 };
        const classes = try w.classesOf(actual);
        // A slot has no argument of its own to name: the line's base is the
        // function value at the slot's path.
        if (classes.len == 0) return w.needUnknown(inst, "<function value>", callee, ff.sends);
        var reported = false;
        for (classes) |cls| {
            const c = (try w.callbackSummary(cls, j, ictx)) orelse {
                // One line per call, however many classes it cannot place.
                if (!reported) try w.needUnknown(inst, "<function value>", callee, ff.sends);
                reported = true;
                continue;
            };
            if (try w.returnsOwned(c, s, avs, ictx, j, 0, none, .deep)) {
                try w.returnedParamDemands(inst, slot_callee, args, avs, c, j, eps, true, .deep, 0);
                continue;
            }
            const name: []const u8 = switch (cls) {
                .closure => "<lambda>",
                .func => |t| try w.qualified(t),
                .send => "send",
            };
            try w.needLine(w.token(inst), name, try w.needWhy(callee, ff.sends), try w.ownedButApprox(c, s, avs, ictx, j), false, cls);
        }
    }

    /// What callee `callee` does with what a function value returns, for a
    /// `need` line: sends it, when its `need` comes only from a send (§23.5,
    /// amended), or edits it.
    fn needWhy(w: *Walker, callee: []const u8, sends: bool) Allocator.Error![]const u8 {
        const arena = w.o.out.allocator();
        return if (sends)
            std.fmt.allocPrint(arena, "{s} sends what it returns, which may be a list it does not own (§23.5)", .{callee})
        else
            std.fmt.allocPrint(arena, "{s} edits what it returns, which may be a list it does not own", .{callee});
    }

    /// A callee that edits what a function it is handed returns (`need`),
    /// handed a function whose class the checker does not know — read out of
    /// a `Ref`, from JavaScript, out of a structure: nothing shows it returns
    /// a list it owns, so the edit is rejected, approximately — the limit is
    /// the checker's, not sharing the text shows.
    fn needUnknown(w: *Walker, inst: Inst.Index, base: []const u8, callee: []const u8, sends: bool) Allocator.Error!void {
        const why = try std.fmt.allocPrint(w.o.out.allocator(), "{s} {s} what it returns, and the checker does not know which function it is, so not that it returns a list it owns", .{ callee, if (sends) "sends" else "edits" });
        try w.demands.append(w.a, .{
            .kind = .value,
            .token = w.token(inst),
            .op = "value",
            .base = base,
            .base_local = none,
            .base_path = eps,
            .point = w.point,
            .frame = w.frame,
            .ctx = w.ctx,
            .element = false,
            .accept = .callback_param,
            .holders = &.{},
            .fixed = .{ .verdict = .{ .rejected = .need }, .detail = why },
            .prelim = .{ .cause = .need, .detail = why, .approx = true },
        });
    }

    /// A callback with no list write cannot be the writer of a keep edge.
    /// Unknown classes and callbacks called through its own parameters keep
    /// the conservative requirement.
    fn mayWrite(w: *Walker, actual: AV) Allocator.Error!bool {
        if (w.fnParamOf(actual) orelse try w.slotOf(actual)) |_| return true;
        const classes = try w.classesOf(actual);
        if (classes.len == 0) return true;
        for (classes) |cls| {
            const c = (try w.classSummary(cls)) orelse return true;
            if (c.limit != .none or c.writesAny()) return true;
            for (c.funs) |f| if (f.calls != .zero or !f.seen) return true;
        }
        return false;
    }

    fn resolveNeed(w: *Walker, s: *const Summary, avs: []const AV, facts: FunFacts) Allocator.Error!FunFacts {
        var ff = facts;
        for (facts.need_if) |writer| {
            const actual = (try w.actualOf(s, avs, writer)) orelse {
                ff.need = true;
                break;
            };
            if (try w.mayWrite(actual)) {
                ff.need = true;
                break;
            }
        }
        return ff;
    }

    /// Forward a supply after composing it, with the same crossing mark and
    /// occurrence check as a direct callback instantiation. Probes still name
    /// the original supplied cells, before any fold merges their places.
    fn forwardSupply(w: *Walker, sr: SupplyRec, entry: SupplyEntry, ctx: InstCtx) Allocator.Error!void {
        const crossing = w.cast_crossings.contains(.{ .path = entry.path, .prov = entry.prov });
        const marked = entry.grown != 0 or for (sr.av) |e| {
            if (e.grown != 0) break true;
        } else false;
        // §16.7 (c): a call that grows the variable of the supply's parameter
        // composes it too (F3 on every route): without the path cut, its
        // paths would grow by a step in every round of the group.
        const grown = try w.grownArgs(ctx);
        const grows = entry.prov.kind == .param and entry.prov.a < grown.len and grown[entry.prov.a] != null;
        // With no growth information the existing deferred placement is
        // already exact; do not install its annotations a second time.
        if (!crossing and !marked and !grows) return w.supplies.append(w.a, sr);
        var out = sr;
        out.av = try w.composeSupply(entry, sr.av, ctx);
        out.path = eps;
        try w.supplies.append(w.a, out);
    }

    /// The caller's own function parameter or slot `jj`, handed to the
    /// callee's function parameter or slot `j`: it takes the callee's facts
    /// (§16.4 item 4).
    fn passOn(w: *Walker, inst: Inst.Index, s: *const Summary, avs: []const AV, j: u32, facts: FunFacts, jj: u32) Allocator.Error!void {
        var ff = facts;
        var deps: std.ArrayList(u32) = .empty;
        for (facts.need_if) |writer| {
            const actual = (try w.actualOf(s, avs, writer)) orelse {
                ff.need = true;
                continue;
            };
            if (w.fnParamOf(actual) orelse try w.slotOf(actual)) |mapped| {
                if (std.mem.indexOfScalar(u32, deps.items, mapped) == null) try deps.append(w.a, mapped);
            } else if (try w.mayWrite(actual)) ff.need = true;
        }
        {
            const st = &w.fn_state.items[jj];
            // §23.3: a function parameter handed on to a send position.
            if (ff.send != none and st.send == none) st.send = ff.send;
            st.calls = @fromBackingInt(@min(2, @as(u8, @backingInt(st.calls)) + @as(u8, @backingInt(ff.calls))));
            // In a lambda, the callee calls it each time the lambda runs.
            if ((w.recursive or w.frame != 0) and ff.calls != .zero) st.calls = .many;
            // Each lambda the pass is inside calls it, through the callee.
            if (ff.calls != .zero) {
                var f = w.frame;
                while (f != 0 and f != none) : (f = w.frames.items[f].parent) {
                    if (w.frameClosure(f)) |ci| try w.env_passes.append(w.a, .{ ci, jj });
                }
            }
            st.need = st.need or ff.need;
            for (deps.items) |writer| if (std.mem.indexOfScalar(u32, st.need_if.items, writer) == null) try st.need_if.append(w.a, writer);
            st.rneed = st.rneed or ff.rneed;
            if (ff.need and !ff.sends) st.need_edit = true;
            st.seen = st.seen and ff.seen;
            const ictx: InstCtx = .{ .inst = inst, .s = s, .avs = avs, .depth = 0 };
            // §31.5: what the callee hands it of records, handed on as the
            // callee hands it — owned only where the records are this
            // body's to give at the call (`recordProbe`).
            for (s.rsupply) |e| {
                if (e.fun != j) continue;
                const raw = try w.instProv(e.prov, ictx);
                const cells = try w.objectView(raw);
                const from: u32 = if (e.prov.kind == .param) e.prov.a else none;
                var others: std.ArrayList(AV) = .empty;
                for (avs, 0..) |x, i| if (i != j and i != from) try others.append(w.a, x);
                const rprobe = if (e.owned and cells.len > 0) try w.recordProbe(inst, cells, others.items) else none;
                try w.forwardSupply(.{ .fun = jj, .k = e.k, .path = e.path, .av = cells, .probe = none, .owned = e.owned, .approx = e.approx, .rcond = try w.rinstXSum(e.rxc, ictx), .taken = e.prov.taken, .rprobe = rprobe }, e, ictx);
            }
            for (s.supply) |e| {
                if (e.fun != j) continue;
                // In a lambda, a capture of the declaration's own frame is
                // what that frame holds (§30.9), so its parameters stay its
                // own — borrowed: when the lambda runs, the declaration may
                // still read them, which a probe here cannot see.
                var own: std.ArrayList(Entry) = .empty;
                var captured: std.ArrayList(Entry) = .empty;
                // §31.5: the records a row or summary hands, handed on to the
                // record supply: not a list's.
                var rcells: std.ArrayList(Entry) = .empty;
                var rcaptured = false;
                for (try w.instProv(e.prov, ictx)) |x_in| {
                    if (w.cells.items[x_in.cell].condition_only) {
                        const annotation = try w.a.dupe(Entry, &.{x_in});
                        try w.forwardSupply(.{ .fun = jj, .k = e.k, .path = e.path, .av = annotation, .probe = none, .owned = true, .approx = e.approx, .cond = try w.cellCond(x_in.cell), .rcond = try w.rcellCond(x_in.cell) }, e, ictx);
                        continue;
                    }
                    const facing = w.listFacing(x_in.cell) orelse {
                        const rc = w.cells.items[x_in.cell];
                        if (w.frame != 0 and rc.kind == .env and rc.a < w.local_frame.len and w.local_frame[rc.a] == 0 and w.local_av[rc.a] != null) rcaptured = true;
                        try rcells.append(w.a, .{ .path = x_in.path, .cell = x_in.cell, .approx = x_in.approx, .grown = x_in.grown });
                        continue;
                    };
                    const x = Entry{ .path = x_in.path, .cell = facing, .approx = x_in.approx, .grown = x_in.grown };
                    const xc = w.cells.items[x.cell];
                    const of_decl = w.frame != 0 and xc.kind == .env and xc.a < w.local_frame.len and w.local_frame[xc.a] == 0 and w.local_av[xc.a] != null;
                    try (if (of_decl) &captured else &own).append(w.a, x);
                }
                if (rcells.items.len != 0) {
                    const from: u32 = if (e.prov.kind == .param) e.prov.a else none;
                    var rothers: std.ArrayList(AV) = .empty;
                    for (avs, 0..) |x, i| if (i != j and i != from) try rothers.append(w.a, x);
                    const rowned = e.owned and !rcaptured;
                    const rprobe = if (rowned) try w.recordProbe(inst, rcells.items, rothers.items) else none;
                    try w.forwardSupply(.{ .fun = jj, .k = e.k, .path = e.path, .av = rcells.items, .probe = none, .owned = rowned, .approx = e.approx or rcaptured, .rcond = try w.rinstXSum(e.rxc, ictx), .taken = e.prov.taken, .rprobe = rprobe }, e, ictx);
                }
                if (captured.items.len != 0) {
                    const named = try w.declView(captured.items);
                    try w.forwardSupply(.{ .fun = jj, .k = e.k, .path = e.path, .av = named, .probe = none, .owned = false, .approx = true, .cond = try w.instXSum(e.xc, ictx), .rcond = try w.rinstXSum(e.rxc, ictx), .taken = e.prov.taken }, e, ictx);
                }
                const cells: AV = own.items;
                // Disjoint against every argument but the function and the
                // one the supplied cells come from.
                const from: u32 = if (e.prov.kind == .param) e.prov.a else none;
                var others: std.ArrayList(AV) = .empty;
                for (avs, 0..) |x, i| if (i != j and i != from) try others.append(w.a, x);
                const cond = try w.instXSum(e.xc, ictx);
                const rcond = try w.rinstXSum(e.rxc, ictx);
                // §30.9: each cell supplied is owned or not on its own, so a
                // cell made during the call is not borrowed because another
                // supplied beside it is.
                if (cells.len > 1 and cells.len <= split_cap) {
                    for (cells) |x| {
                        const one = try w.a.dupe(Entry, &.{x});
                        const probe = if (e.owned) try w.probeDemand(inst, one, others.items) else none;
                        try w.forwardSupply(.{ .fun = jj, .k = e.k, .path = e.path, .av = one, .probe = probe, .owned = e.owned, .approx = e.approx, .cond = cond, .rcond = rcond, .taken = e.prov.taken }, e, ictx);
                    }
                    continue;
                }
                const probe = if (e.owned and cells.len > 0) try w.probeDemand(inst, cells, others.items) else none;
                try w.forwardSupply(.{ .fun = jj, .k = e.k, .path = e.path, .av = cells, .probe = probe, .owned = e.owned, .approx = e.approx, .cond = cond, .rcond = rcond, .taken = e.prov.taken }, e, ictx);
            }
        }
    }

    /// The actual for the callee's function parameter `j`, a value whose
    /// classes are `classes`, checked against what the callee supplies it
    /// (§16.4 item 4).
    fn checkClasses(w: *Walker, inst: Inst.Index, callee: Callee, args: []const Inst.Index, avs: []const AV, j: u32, facts: FunFacts, actual: AV, ictx: InstCtx, classes: []const Class) Allocator.Error!void {
        var ff = facts;
        if (w.instType(args[j])) |ft| switch (w.store.resolvedContent(ft)) {
            .structure => |st| if (st == .func) {
                ff.need = ff.need and try w.o.listTracked(w.store, st.func.result, 0);
            },
            else => {},
        };
        const s = callee.sum;
        const tok = w.token(inst);
        const arena = w.o.out.allocator();
        // §23.4: what is handed a send must be seen to send only what it owns.
        if (ff.send != none) try w.checkSender(inst, callee, args[j], classes, ff.send);
        // §23.5: a constructor handed as a tagger returns what it is given.
        if (ff.need) if (try w.ctorClass(args[j])) |c| {
            if (!try w.returnsOwned(c, s, avs, ictx, j, 0, none, .deep)) {
                // Approximate when only an approximate step made it so: a
                // value from JavaScript, a conservative call's result.
                const approx = blk: {
                    const previous = w.ro_exact;
                    w.ro_exact = true;
                    defer w.ro_exact = previous;
                    break :blk try w.returnsOwned(c, s, avs, ictx, j, 0, none, .deep);
                };
                const why = if (approx)
                    try std.fmt.allocPrint(arena, "{s} sends what it returns, and it returns what {s} hands it, which may hold a list the checker cannot place — from JavaScript, or through a call it does not see into (§23.5)", .{ callee.name, callee.name })
                else
                    try std.fmt.allocPrint(arena, "{s} sends what it returns, and it returns what {s} hands it, which may be a list the sender still holds (§23.5)", .{ callee.name, callee.name });
                try w.demands.append(w.a, .{
                    .kind = .value,
                    .token = tok,
                    .op = "value",
                    .base = try w.baseText(args[j]),
                    .base_local = none,
                    .base_path = eps,
                    .point = w.point,
                    .frame = w.frame,
                    .ctx = w.ctx,
                    .element = false,
                    .accept = .callback_param,
                    .holders = &.{},
                    .fixed = .{ .verdict = .{ .rejected = .need }, .detail = why },
                    .prelim = .{ .cause = .need, .detail = why, .approx = approx },
                });
            } else try w.returnedParamDemands(inst, callee, args, avs, c, j, eps, true, .deep, 0);
            return;
        } else if (classes.len == 0) try w.needUnknown(inst, try w.baseText(args[j]), callee.name, ff.sends);
        // §31.5: a callee that writes a record πⱼ returns needs one it may
        // write; a value the checker cannot place may return any.
        const record_unknown = try std.fmt.allocPrint(arena, "{s} writes a record that {s} returns, and the checker cannot see which function it is, so not that the record is one it owns", .{ callee.name, try w.baseText(args[j]) });
        if (ff.rneed and classes.len == 0) try w.recordNeedLine(tok, try w.baseText(args[j]), record_unknown, true, null);
        var reported = false;
        var rreported = false;
        for (classes) |cls| {
            const c = (try w.callbackSummary(cls, j, ictx)) orelse {
                // One line per call, however many classes it cannot place.
                if (ff.need and !reported) try w.needUnknown(inst, try w.baseText(args[j]), callee.name, ff.sends);
                reported = true;
                if (ff.rneed and !rreported) try w.recordNeedLine(tok, try w.baseText(args[j]), record_unknown, true, cls);
                rreported = true;
                continue;
            };
            if (ff.rneed) {
                if (try w.returnsOwnedRecord(c, s, avs, ictx, j, 0, null)) {
                    try w.recordLoanDemands(inst, callee, args, avs, c, j, 0);
                } else {
                    const why = try std.fmt.allocPrint(arena, "{s} writes a record that {s} returns, and it may return one it does not own", .{ callee.name, try w.baseText(args[j]) });
                    try w.recordNeedLine(tok, try w.baseText(args[j]), why, false, cls);
                }
            }
            const name: []const u8 = switch (cls) {
                .closure => "<lambda>",
                .func => |t| try w.qualified(t),
                .send => "send",
            };
            // A `need` line names the function value as the call writes it:
            // `f`, `r.load`, `Fixed.parse` — `<lambda>` only for a lambda
            // written there (§28.6).
            const need_name = if (cls == .closure and ff.need) try w.baseText(args[j]) else name;
            if (cls == .closure) {
                try w.applyEnvCalls(cls.closure, s, j, ictx);
                try w.dischargeLambdaNeeds(cls.closure, suppliedParam, SupplyCtx{ .s = s, .j = j, .ictx = ictx });
            }
            // §18.8: a once closure goes only where it runs at most once, and
            // handing it on is a call of it.
            if (cls == .closure and c.once and ff.seen) {
                const cl = &w.closures.items[cls.closure];
                if (ff.calls == .many) {
                    if (cl.once_bad == null) cl.once_bad = try std.fmt.allocPrint(arena, "it is handed to {s}, which may call it more than once", .{callee.name});
                } else try w.onceCall(cls.closure, actual, tok);
            }
            const writes = c.writesAny();
            if (!ff.seen) {
                // Need does not depend on seen: retained captures must be
                // empty at callers, and all other results must be owned.
                if (ff.need) {
                    if (!try w.taggerReturnsOwned(c, s, avs, j, cls, ictx))
                        try w.needLine(tok, need_name, try w.needWhy(callee.name, ff.sends), try w.ownedButApprox(c, s, avs, ictx, j), w.frame != 0, cls)
                    else
                        try w.returnedParamDemands(inst, callee, args, avs, c, j, eps, true, .deep, 0);
                }
                // §31.5: a closure that writes only a record is decided by its
                // consumers too; a function value's line is a list's.
                if (!writes and c.writesRecord()) switch (cls) {
                    .closure => |ci| try w.closures.items[ci].consumed.append(w.a, .{ .kind = .pending, .why = try std.fmt.allocPrint(arena, "{s} loses sight of what calls it", .{callee.name}), .limit = w.limit_callee }),
                    else => {},
                };
                if (writes) switch (cls) {
                    .closure => |ci| try w.closures.items[ci].consumed.append(w.a, .{ .kind = .pending, .why = try std.fmt.allocPrint(arena, "{s} loses sight of what calls it", .{callee.name}), .limit = w.limit_callee }),
                    .func => try w.valueLine(tok, name, if (w.limit_callee) .{ .rejected = .limit } else .pending, try std.fmt.allocPrint(arena, "{s} loses sight of what calls it", .{callee.name}), "", false),
                    // §23.4: a send handed where its calls are not seen
                    // sends what the checker cannot see, when what it sends
                    // may hold a list.
                    .send => if (w.instType(args[j])) |sty| if (funcParam(w.store, sty, 0)) |mty| if (try w.o.holdsList(w.store, mty, 0)) {
                        const why = try std.fmt.allocPrint(arena, "{s} loses sight of the send it is handed, so the checker cannot see what is sent", .{callee.name});
                        try w.demands.append(w.a, .{
                            .kind = .value,
                            .token = tok,
                            .op = "send",
                            .base = callee.name,
                            .base_local = none,
                            .base_path = eps,
                            .point = w.point,
                            .frame = w.frame,
                            .ctx = w.ctx,
                            .element = false,
                            .accept = .callback_param,
                            .holders = &.{},
                            .fixed = .{ .verdict = .{ .rejected = if (w.limit_callee) .limit else .supply }, .detail = why },
                            .prelim = .{ .cause = if (w.limit_callee) .limit else .supply, .detail = why, .approx = true },
                        });
                    },
                };
                continue;
            }
            // The supply edge, per parameter of the callback.
            const bad = try w.a.alloc(?[]const u8, c.params);
            @memset(bad, null);
            const bad_approx = try w.a.alloc(bool, c.params);
            @memset(bad_approx, false);
            const bad_cause = try w.a.alloc(Cause, c.params);
            @memset(bad_cause, .supply);
            // §31.5: a record the callback writes (`bit_f`) needs what the
            // callee supplies there owned. Its reasons are its own, so that
            // no list's demand on the same parameter reads them.
            const rbad = try w.a.alloc(?[]const u8, c.params);
            @memset(rbad, null);
            const rbad_approx = try w.a.alloc(bool, c.params);
            @memset(rbad_approx, false);
            const rbad_cause = try w.a.alloc(Cause, c.params);
            @memset(rbad_cause, .supply);
            for (c.uses) |u| {
                if (u.bits & bit_f == 0 or u.param >= c.params or rbad[u.param] != null) continue;
                var found = false;
                // The first borrowed supply refuses the parameter; a call-site
                // demand an owned one before it raised stays, which refuses
                // more, never less.
                supplies: for ([_][]const SupplyEntry{ s.supply, s.rsupply }) |entries| for (entries) |e| {
                    if (e.prov.condition_only or e.fun != j or e.k != u.param or !w.o.overlap(e.path, u.path)) continue;
                    found = true;
                    // The answer's object the callback writes: at the path
                    // below the supply it writes; none of it when the write
                    // is above the supply; any when the two only overlap.
                    const written: ?u32 = if (try w.o.suffix(e.path, u.path)) |rest| rest else if (try w.o.suffix(u.path, e.path) != null) none else null;
                    if (!e.owned or !try w.recordProvOwned(e.prov, s, avs, ictx, none, 0, written)) {
                        rbad[u.param] = try std.fmt.allocPrint(arena, "{s} supplies its parameter {d} borrowed ({s})", .{ callee.name, u.param + 1, try w.o.provText(e.prov) });
                        rbad_approx[u.param] = !e.owned and e.approx;
                        break :supplies;
                    }
                    // §29 for records: what the callback returned before, a
                    // loan of the record its callee handed it.
                    if (e.prov.kind == .cb) if (try w.actualOf(s, avs, e.prov.a)) |prev| {
                        for (try w.classesOf(prev)) |pcls| {
                            const pc = (try w.classSummary(pcls)) orelse continue;
                            try w.recordLoanDemands(inst, callee, args, avs, pc, e.prov.a, 0);
                        }
                    };
                    // §31.4 item 6: a record a destructive read hands out is
                    // its container's position, so the container's contents
                    // must be exclusive: no record object at two positions.
                    // The supply's record condition says so, relied on here.
                    if (e.prov.taken) switch (try w.rrely(try w.rinstXSum(e.rxc, ictx), w.frame)) {
                        .ok => {},
                        else => |r| {
                            rbad[u.param] = try std.fmt.allocPrint(arena, "{s} hands its parameter {d} a position of a list that may hold one record at two positions", .{ callee.name, u.param + 1 });
                            rbad_approx[u.param] = r != .exact;
                            rbad_cause[u.param] = if (r == .limit) .limit else .exclusive;
                            break :supplies;
                        },
                    };
                    // An owned supply of the callee's own parameter: the
                    // caller's argument is written, at the call (§31.7). A taken
                    // supply's path is the element's, `π1[*]`, the position it
                    // hands out: the demand is on the caller's elements.
                    if (e.prov.kind == .param and e.prov.a < args.len) {
                        var path = e.prov.path;
                        if (try w.o.suffix(e.path, u.path)) |rest| path = try w.o.concat(path, rest);
                        try w.callSiteRecordDemand(inst, args, avs, if (callee.closure != none) try w.single(.{ .kind = .closure, .a = callee.closure }) else &.{}, e.prov.a, path, u.fields, if (s.limit != .none or c.limit != .none) .limit else .exact);
                    }
                };
                // A record the callback writes that the callee is not seen
                // to hand it: the checker cannot say it is owned.
                if (!found and ff.calls != .zero) {
                    rbad[u.param] = try std.fmt.allocPrint(arena, "{s} calls it, and the checker does not see what it hands its parameter {d}", .{ callee.name, u.param + 1 });
                    rbad_approx[u.param] = true;
                }
            }
            for (c.uses) |u| {
                if (u.bits & bit_w == 0 or u.param >= c.params) continue;
                for (s.supply) |e| {
                    if (e.prov.condition_only or e.fun != j or e.k != u.param or !w.o.writeOverlap(u.path, e.path, u.extent)) continue;
                    // The path the callback writes, within what the supply holds.
                    const written = (try w.o.suffix(e.path, u.path)) orelse eps;
                    // A returned destructive loan must also be dead in the
                    // caller for the lifetime of the feedback result (§29).
                    if (e.owned and e.prov.kind == .cb) {
                        try w.callbackLoanDemands(inst, callee, args, avs, e.prov.a, written, u.bits & bit_d != 0, u.extent, 0);
                    }
                    const owned = e.owned and try w.provOwned(e.prov, s, avs, ictx, none, 0, written, if (u.bits & bit_d != 0) .deep else u.extent);
                    if (!owned) {
                        // The first reason, unless a later one is exact and
                        // it was not: an exact reason labels the rejection.
                        if (bad[u.param] == null or (bad_approx[u.param] and !(!e.owned and e.approx))) {
                            bad[u.param] = if (cls == .send)
                                try std.fmt.allocPrint(arena, "{s} sends what it may still hold ({s}), and a send gives its payload up (§23.2)", .{ callee.name, try w.o.provText(e.prov) })
                            else if (e.prov.kind == .cb and e.owned)
                                try std.fmt.allocPrint(arena, "{s} hands its parameter {d} what the callback returned before, which may be a list the callback does not own", .{ callee.name, u.param + 1 })
                            else
                                try std.fmt.allocPrint(arena, "{s} supplies its parameter {d} borrowed ({s})", .{ callee.name, u.param + 1, try w.o.provText(e.prov) });
                            // An element's borrowed supply is the checker's
                            // limit (§16.8); a parameter's or a callback's
                            // result is what the text shows.
                            bad_approx[u.param] = !e.owned and e.approx;
                            // What the callback returned before may be a
                            // `⊤` — a list from JavaScript, or what a
                            // function the checker cannot identify returned:
                            // a limit, as a `need` through one is (§30.9
                            // rule 11, §30.11).
                            if (e.owned and e.prov.kind == .cb) {
                                for (try w.expand(try w.instProv(e.prov, ictx))) |x| {
                                    if (w.cells.items[x.cell].kind == .top) bad_approx[u.param] = true;
                                }
                            }
                            bad_cause[u.param] = if (w.limit_callee) .limit else .supply;
                        }
                        continue;
                    }
                    // A destructive supply written: its container must be
                    // exclusive, so that no other position sees the write
                    // (§18.5).
                    var supply_cond = try w.instXSum(e.xc, ictx);
                    // A focus may require only the written array's
                    // own exclusivity. This does not authorise a deep write.
                    if (s.limit == .none and c.limit == .none and e.prov.taken and u.bits & bit_d == 0 and e.prov.kind == .param and ((u.extent == .storage and w.o.isPrefix(e.path, u.path)) or try w.o.dictTreePath(e.prov.path))) {
                        const tail = (try w.o.suffix(e.path, u.path)) orelse eps;
                        var p = e.prov;
                        p.path = try w.o.concat(p.path, tail);
                        const scoped = try w.spineCond(try w.instProv(p, ictx));
                        if (scoped != cond_lost and scoped != cond_limit and scoped != cond_shared) {
                            const usable = for (w.conds.items[scoped].atoms) |atom| {
                                if (!w.ownedBy(atom, w.frame)) break false;
                            } else true;
                            if (usable) supply_cond = scoped;
                        }
                    }
                    if (e.prov.taken) switch (try w.rely(supply_cond, w.frame)) {
                        .ok => {},
                        else => |r| if (bad[u.param] == null) {
                            bad[u.param] = try w.sharesText(callee.name, u.param, e, args);
                            bad_approx[u.param] = r != .exact;
                            bad_cause[u.param] = if (r == .limit) .limit else .exclusive;
                        },
                    };
                    // An owned supply of the callee's own parameter: the
                    // caller's argument is written, at the call.
                    if (e.prov.kind == .param and e.prov.a < args.len) {
                        var path = e.prov.path;
                        if (try w.o.suffix(e.path, u.path)) |rest| path = try w.o.concat(path, rest);
                        const note = if (w.mode != .report) "" else try std.fmt.allocPrint(arena, "{s} writes what {s} supplies it", .{ name, callee.name });
                        try w.callSiteDemandDeep(inst, callee.op, args, avs, if (callee.closure != none) try w.single(.{ .kind = .closure, .a = callee.closure }) else &.{}, e.prov.a, path, note, if (s.limit != .none or c.limit != .none) .limit else if (u.bits & bit_x == 0) .approx else .exact, null, u.bits & bit_d != 0, u.extent);
                    }
                }
            }
            // What the callback relied on (§18.4 item 2), against what the
            // callee supplies it and what it captured.
            // Pair by pair: the first failure in atom order is reported (§16.7, #693).
            for (try expandAtoms(w.a, c.xreq)) |x| {
                const r = try w.rely(try w.classReq(x, s, j, cls, ictx), w.frame);
                if (r == .ok) continue;
                const k = xreqParam(x) orelse 0;
                if (k >= c.params or bad[k] != null) continue;
                bad[k] = try std.fmt.allocPrint(arena, "it needs what {s} supplies it not to share, and it may", .{callee.name});
                bad_approx[k] = r != .exact;
                bad_cause[k] = if (r == .limit) .limit else .exclusive;
            }
            // The callee edits what the callback returns (§16.2's need).
            var need_bad = false;
            if (ff.need) {
                if (!(if (ff.sends) try w.taggerReturnsOwned(c, s, avs, j, cls, ictx) else try w.returnsOwned(c, s, avs, ictx, j, 0, none, .deep)))
                    need_bad = true
                else
                    try w.returnedParamDemands(inst, callee, args, avs, c, j, eps, true, .deep, 0);
            }
            switch (cls) {
                .send => if (bad[0]) |why| try w.demands.append(w.a, .{
                    .kind = .value,
                    .token = tok,
                    .op = "send",
                    .base = callee.name,
                    .base_local = none,
                    .base_path = eps,
                    .point = w.point,
                    .frame = w.frame,
                    .ctx = w.ctx,
                    .element = false,
                    .accept = .callback_param,
                    .holders = &.{},
                    .fixed = .{ .verdict = .{ .rejected = bad_cause[0] }, .detail = why },
                    .prelim = .{ .cause = bad_cause[0], .detail = why, .approx = bad_approx[0] },
                }),
                .closure => |ci| {
                    try w.closures.items[ci].consumed.append(w.a, .{ .kind = .supply, .bad = bad, .bad_approx = bad_approx, .bad_cause = bad_cause, .rbad = rbad, .rbad_approx = rbad_approx, .rbad_cause = rbad_cause, .name = callee.name });
                    if (need_bad) try w.needLine(tok, need_name, try w.needWhy(callee.name, ff.sends), try w.ownedButApprox(c, s, avs, ictx, j), false, cls);
                },
                .func => {
                    if (need_bad) {
                        try w.needLine(tok, need_name, try w.needWhy(callee.name, ff.sends), try w.ownedButApprox(c, s, avs, ictx, j), false, cls);
                    } else if (writes) {
                        var first: ?usize = null;
                        for (bad, 0..) |x, k| if (x != null and first == null) {
                            first = k;
                        };
                        if (first) |k| {
                            try w.demands.append(w.a, .{
                                .kind = .value,
                                .token = tok,
                                .op = "value",
                                .base = name,
                                .base_local = none,
                                .base_path = eps,
                                .point = w.point,
                                .frame = w.frame,
                                .ctx = w.ctx,
                                .element = false,
                                .accept = .callback_param,
                                .holders = &.{},
                                .fixed = .{ .verdict = .{ .rejected = bad_cause[k] }, .detail = bad[k].? },
                                .prelim = .{ .cause = bad_cause[k], .detail = bad[k].?, .approx = bad_approx[k] },
                            });
                        } else {
                            try w.valueLine(tok, name, .{ .accepted = .callback_param }, "", try std.fmt.allocPrint(arena, "{s} supplies it owned", .{callee.name}), false);
                        }
                    }
                    // §31.5: a function that writes a record it is handed,
                    // where the callee hands one it does not own: a record
                    // line of its own, beside the list's.
                    if (c.writesRecord()) {
                        for (rbad, 0..) |x, k| if (x) |why| {
                            try w.demands.append(w.a, .{
                                .kind = .value,
                                .token = tok,
                                .op = "update",
                                .base = name,
                                .base_local = none,
                                .base_path = eps,
                                .point = w.point,
                                .frame = w.frame,
                                .ctx = w.ctx,
                                .element = false,
                                .accept = .callback_param,
                                .holders = &.{},
                                .fixed = .{ .verdict = .{ .rejected = rbad_cause[k] }, .detail = why },
                                .prelim = .{ .cause = rbad_cause[k], .detail = why, .approx = rbad_approx[k] },
                                .fields = &.{},
                            });
                            break;
                        };
                    }
                },
            }
        }
    }

    /// §23.4: the function value `arg`, handed to a position where the
    /// runtime gives it a send as its parameter `k`, must be seen to send
    /// only what it owns. A lambda written there has its sends checked where
    /// they are made; a top-level function's are its summary's supplies to
    /// that parameter; anything else is not followed.
    fn checkSender(w: *Walker, inst: Inst.Index, callee: Callee, arg: Inst.Index, classes: []const Class, k: u32) Allocator.Error!void {
        const arena = w.o.out.allocator();
        // A message type that holds no cell has nothing to give up.
        const fty = w.instType(arg) orelse return;
        const sty = funcParam(w.store, fty, k) orelse return;
        const mty = funcParam(w.store, sty, 0) orelse return;
        if (!try w.o.holdsList(w.store, mty, 0)) return;
        const tok = w.token(inst);
        var why: ?[]const u8 = null;
        var approx = true;
        if (classes.len == 0) why = try std.fmt.allocPrint(arena, "the checker does not know which function {s} is handed here, so it cannot see what it sends", .{callee.name});
        for (classes) |cls| switch (cls) {
            .send => {},
            .closure => |ci| {
                const ps = w.closures.items[ci].params;
                if (k < ps.len and w.instCol(bool, w.send_params, ps[k].int(), false)) continue;
                if (why == null) why = "a function value written apart from where it is handed a send: the checker follows the sends of a lambda written at the send position, or of a top-level function";
            },
            .func => |t| {
                const s = (try w.o.ensureSummary(t.m, t.d)) orelse continue;
                const f = s.funOf(k) orelse continue;
                if (!f.seen) {
                    if (why == null) why = try std.fmt.allocPrint(arena, "{s} hands its send where the checker cannot see its calls", .{try w.qualified(t)});
                    continue;
                }
                for (s.supply) |e| {
                    if (e.fun != k) continue;
                    if (e.owned and e.prov.kind != .param and e.prov.kind != .cb) continue;
                    if (why != null and !approx) continue;
                    why = if (e.owned)
                        try std.fmt.allocPrint(arena, "{s} sends what it was handed ({s}), which {s} does not supply it owned", .{ try w.qualified(t), try w.o.provText(e.prov), callee.name })
                    else
                        try std.fmt.allocPrint(arena, "{s} sends what it may still hold ({s}), and a send gives its payload up (§23.2)", .{ try w.qualified(t), try w.o.provText(e.prov) });
                    approx = e.owned or e.approx;
                }
            },
        };
        const reason = why orelse return;
        try w.demands.append(w.a, .{
            .kind = .value,
            .token = tok,
            .op = "send",
            .base = try w.baseText(arg),
            .base_local = none,
            .base_path = eps,
            .point = w.point,
            .frame = w.frame,
            .ctx = w.ctx,
            .element = false,
            .accept = .callback_param,
            .holders = &.{},
            .fixed = .{ .verdict = .{ .rejected = .supply }, .detail = reason },
            .prelim = .{ .cause = .supply, .detail = reason, .approx = approx },
        });
    }

    /// §23.5: a constructor handed as a function: it returns its arguments,
    /// each at its own field.
    fn ctorClass(w: *Walker, arg: Inst.Index) Allocator.Error!?*const Summary {
        switch (w.bir.instTag(arg)) {
            .ctor, .ext_ctor, .schema_ctor_top, .ext_schema_ctor => {},
            else => return null,
        }
        const ty = w.instType(arg) orelse return null;
        const ps = switch (w.store.resolvedContent(ty)) {
            .structure => |st| switch (st) {
                .func => |fun| w.store.vars(fun.params),
                else => return null,
            },
            else => return null,
        };
        const c = try w.ctorOf(arg);
        const keep = w.o.keep.allocator();
        var uses: std.ArrayList(UseEntry) = .empty;
        var res: std.ArrayList(ResEntry) = .empty;
        // A field that can hold no list `update` could write carries nothing.
        for (ps, 0..) |pt, i| {
            if (!try w.o.holdsList(w.store, pt, 0)) continue;
            try uses.append(keep, .{ .param = @intCast(i), .path = eps, .bits = bit_a });
            try res.append(keep, .{ .path = try w.o.child(eps, .ctor, try w.o.ctorStep(c, @intCast(i))), .prov = .{ .kind = .param, .a = @intCast(i), .path = eps } });
        }
        // Its operands pairwise apart (§16.7, #693), as a construction's.
        var separation: std.ArrayList(XAtom) = .empty;
        {
            const gs = try keep.alloc([]Prov, res.items.len);
            for (gs, res.items) |*g, r| g.* = try keep.dupe(Prov, &.{r.prov});
            try apartAtoms(keep, .apart, gs, &separation);
        }
        if (separation.items.len != 0) try res.append(keep, .{ .path = eps, .prov = .{ .kind = .fresh, .a = 1, .condition_only = true }, .xc = .{ .atoms = separation.items }, .rxc = .{ .atoms = separation.items } });
        const out = try w.a.create(Summary);
        // A constructor has exactly this primitive row, so unseen callback
        // calls cannot bypass its need check (including a variable-held one).
        out.* = try w.o.normalize(.{ .params = @intCast(ps.len), .uses = uses.items, .res = res.items, .asserted = true });
        return out;
    }

    fn sharesText(w: *Walker, name: []const u8, k: u32, e: SupplyEntry, args: []const Inst.Index) Allocator.Error![]const u8 {
        const arena = w.o.out.allocator();
        if (e.prov.kind == .param and e.prov.a < args.len) {
            return std.fmt.allocPrint(arena, "{s} hands its parameter {d} an element of {s}, whose elements may share one list", .{ name, k + 1, try w.baseText(args[e.prov.a]) });
        }
        return std.fmt.allocPrint(arena, "{s} hands its parameter {d} an element of a list whose elements may share one list", .{ name, k + 1 });
    }

    /// A callback's `xreq` atom, made of what callee `s` supplies it and
    /// what it captured (§18.4 item 2).
    fn classReq(w: *Walker, x: XAtom, s: *const Summary, j: u32, cls: Class, ctx: InstCtx) Allocator.Error!u32 {
        return switch (x.kind) {
            .excl => w.deepCond(try w.classSide(x.a, s, j, cls, ctx)),
            .spine => w.spineCond(try w.classSide(x.a, s, j, cls, ctx)),
            .sep_spine => w.sepSpineValues(try w.classSide(x.a, s, j, cls, ctx), try w.classSide(x.b, s, j, cls, ctx)),
            .sep_root => w.sepRootValues(try w.classSide(x.a, s, j, cls, ctx), try w.classSide(x.b, s, j, cls, ctx)),
            .sep => w.sepValues(try w.classSide(x.a, s, j, cls, ctx), try w.classSide(x.b, s, j, cls, ctx)),
            .keep, .keep_spine => cond_lost,
            // Read through its expansion (the caller).
            .apart, .apart_spine => unreachable,
        };
    }

    /// One side of a callback's atom: its parameter, as the callee supplies
    /// it; its capture, as held here.
    fn classSide(w: *Walker, p: Prov, s: *const Summary, j: u32, cls: Class, ctx: InstCtx) Allocator.Error!AV {
        switch (p.kind) {
            .param => {
                var parts: std.ArrayList(AV) = .empty;
                for (s.supply) |e| {
                    if (e.fun != j or e.k != p.a or !w.o.overlap(e.path, p.path)) continue;
                    const at = try w.composeSupply(e, try w.instProv(e.prov, ctx), ctx);
                    try parts.append(w.a, try w.projPath(at, p.path, null));
                }
                return w.unionOf(parts.items);
            },
            .env => {
                if (cls != .closure) return w.single(.{ .kind = .top, .a = 0 });
                // A capture this walk has not bound: unknown, not empty.
                const held = w.local_av[p.a] orelse return w.single(.{ .kind = .top, .a = 0 });
                return w.projPath(held, p.path, null);
            },
            else => return w.single(.{ .kind = .top, .a = 0 }),
        }
    }

    /// §16.4 item 5 as amended 2026-10-15 (CK-233): the callee writes what
    /// the actual for its function parameter `j` returns, at `written` of
    /// that result (and below it when `deep`), relying on it being owned. A
    /// returned parameter is the cell the callee supplied there, and a supply
    /// of the callee's own parameter was owned only in the callee's frame:
    /// the caller's argument is what is written, so it gets a call-site
    /// demand. A supply of another callback's result asks the same of that
    /// callback's actual. §29's taken-item loans are the case it began with.
    fn callbackLoanDemands(w: *Walker, inst: Inst.Index, callee: Callee, args: []const Inst.Index, avs: []const AV, j: u32, written: u32, deep: bool, extent: WriteExtent, depth: u32) Allocator.Error!void {
        // Past the limit a demand would be dropped: an error instead (§16.7).
        if (depth >= inst_depth) return w.o.hitLimit(.callbacks, depth + 1);
        const actual = (try w.actualOf(callee.sum, avs, j)) orelse return;
        for (try w.classesOf(actual)) |cls| {
            const c = (try w.callbackSummary(cls, j, .{ .inst = inst, .s = callee.sum, .avs = avs, .depth = depth })) orelse continue;
            try w.returnedParamDemands(inst, callee, args, avs, c, j, written, deep, extent, depth);
        }
    }

    /// `callbackLoanDemands` for one class `c` of the actual for `j` — also a
    /// constructor's row (§23.5) or an unseen tagger's.
    fn returnedParamDemands(w: *Walker, inst: Inst.Index, callee: Callee, args: []const Inst.Index, avs: []const AV, c: *const Summary, j: u32, written: u32, deep: bool, extent: WriteExtent, depth: u32) Allocator.Error!void {
        if (depth >= inst_depth) return w.o.hitLimit(.callbacks, depth + 1);
        const s = callee.sum;
        for (c.res) |r| {
            if (r.prov.kind != .param) continue;
            const above = w.o.isPrefix(r.path, written);
            if (!above and !(deep and w.o.isPrefix(written, r.path))) continue;
            // The path of the callback's parameter that is written.
            var at = r.prov.path;
            if (above) if (try w.o.suffix(r.path, written)) |rest| {
                at = try w.o.concat(at, rest);
            };
            for (s.supply) |supply| {
                if (supply.fun != j or supply.k != r.prov.a or !w.o.overlap(supply.path, at)) continue;
                const p = supply.prov;
                // A borrowed supply is rejected by `returnsOwned` already;
                // a taken item's loan is demanded either way (§29).
                if (!supply.owned and !p.taken) continue;
                var path = p.path;
                if (try w.o.suffix(supply.path, at)) |rest| path = try w.o.concat(path, rest);
                switch (p.kind) {
                    .cb => if (p.a != j) try w.callbackLoanDemands(inst, callee, args, avs, p.a, path, deep, extent, depth + 1),
                    .param => if (p.a < args.len) {
                        const origin: Origin = if (s.limit != .none or c.limit != .none) .limit else if (supply.approx or r.approx) .approx else .exact;
                        const note = if (w.mode != .report) "" else if (p.taken) "a returned item is transferred to a later written callback result" else try std.fmt.allocPrint(w.o.out.allocator(), "{s} writes what its callback returns, and the callback returns this argument", .{callee.name});
                        try w.callSiteDemandDeep(inst, callee.op, args, avs, if (callee.closure != none) try w.single(.{ .kind = .closure, .a = callee.closure }) else &.{}, p.a, path, note, origin, null, deep, extent);
                    },
                    else => {},
                }
            }
        }
    }

    /// Whether a supply of provenance `p` is owned once its guard is
    /// decided: a `cb_j′` supply needs the actual for πⱼ′ to return owned,
    /// except while that is the guard being established (`guard`).
    fn provOwned(w: *Walker, p: Prov, s: *const Summary, avs: []const AV, ictx: InstCtx, guard: u32, depth: u32, written: u32, extent: WriteExtent) Allocator.Error!bool {
        if (p.kind != .cb) return true;
        if (p.a == guard) return true;
        // Past §16.7's `callbacks` limit: an error at the declaration, as
        // `callbackLoanDemands` is; the answer is `ro_exact`, as for a
        // function the checker cannot place (not owned in the exact pass).
        if (depth >= inst_depth) {
            try w.o.hitLimit(.callbacks, depth + 1);
            return w.ro_exact;
        }
        const actual = (try w.actualOf(s, avs, p.a)) orelse return w.ro_exact;
        // §30.9: the declaration's own function parameter or slot: what it
        // returns is relied on, so its callers must hand one that returns
        // owned (`need`).
        if (w.fnParamOf(actual) orelse try w.slotOf(actual)) |jj| {
            if (!w.ro_exact) {
                w.fn_state.items[jj].need = true;
                w.fn_state.items[jj].need_edit = true;
            }
            return true;
        }
        // The enclosing lambda's own parameter: decided where it is handed
        // on or called.
        if (try w.deferLambdaNeed(actual, s, p.a, avs, ictx.inst)) return true;
        const classes = try w.classesOf(actual);
        if (classes.len == 0) return w.ro_exact;
        // `written` is relative to what the supply hands, `cb_j` at `p.path`;
        // the callback's result names it at `p.path` extended (#749).
        const at = if (written == none) none else try w.o.concat(p.path, written);
        for (classes) |cls| {
            const c = (try w.callbackSummary(cls, p.a, ictx)) orelse return w.ro_exact;
            const saved = w.ro_closure;
            const saved_within = w.ro_within;
            w.ro_closure = if (cls == .closure) cls.closure else none;
            w.ro_within = p.path;
            defer {
                w.ro_closure = saved;
                w.ro_within = saved_within;
            }
            if (!try w.returnsOwned(c, s, avs, ictx, p.a, depth + 1, at, extent)) return false;
        }
        return true;
    }

    /// §30.9: when `actual` is, at a path, a parameter of a lambda whose body
    /// the walk is in, record that callee `s` relies on what it returns as
    /// its function parameter or slot `j`, and say so.
    fn deferLambdaNeed(w: *Walker, actual: AV, s: *const Summary, j: u32, avs: []const AV, inst: Inst.Index) Allocator.Error!bool {
        if (actual.len != 1 or actual[0].path != eps) return false;
        const c = w.cells.items[try w.takenBase(actual[0].cell)];
        const lp = w.lambdaParam(.{ .kind = .param, .a = c.a, .b = c.b }) orelse return false;
        if (c.kind != .param or c.b != 1) return false;
        if (!w.inFrameOf(w.closures.items[lp[0]].frame)) return false;
        if (w.ro_exact) return true;
        for (w.lambda_needs.items) |n| {
            if (n.closure == lp[0] and n.k == lp[1] and n.path == c.path and n.inst == inst and n.j == j) return true;
        }
        try w.lambda_needs.append(w.a, .{
            .closure = lp[0],
            .k = lp[1],
            .path = c.path,
            .s = s,
            .j = j,
            .avs = avs,
            .inst = inst,
            .callee = if (w.mode == .report) try w.callName(inst) else "",
            .point = w.point,
            .frame = w.frame,
            .ctx = w.ctx,
        });
        return true;
    }

    /// §30.9: lambda `ci`, handed on or called, where its parameter `k` is
    /// `param(k)`: every obligation on it is decided — the function there
    /// returns owned, or it is the declaration's own, which takes the
    /// callee's `need`, or another enclosing lambda's, which waits again.
    fn dischargeLambdaNeeds(w: *Walker, ci: u32, comptime param: anytype, ctx: anytype) Allocator.Error!void {
        var i: usize = 0;
        while (i < w.lambda_needs.items.len) : (i += 1) {
            const n = w.lambda_needs.items[i];
            if (n.closure != ci or n.failed) continue;
            w.lambda_needs.items[i].discharges += 1;
            const actual = try w.projPath(try param(w, n.k, ctx), n.path, null);
            if (w.fnParamOf(actual) orelse try w.slotOf(actual)) |jj| {
                w.fn_state.items[jj].need = true;
                w.fn_state.items[jj].need_edit = true;
                w.fn_state.items[jj].seen = false;
                continue;
            }
            if (try w.deferLambdaNeed(actual, n.s, n.j, n.avs, n.inst)) continue;
            const ictx: InstCtx = .{ .inst = n.inst, .s = n.s, .avs = n.avs, .depth = 0 };
            const classes = try w.classesOf(actual);
            var ok = classes.len != 0;
            var approx = true;
            var failed: ?Class = null;
            for (classes) |cls| {
                const c = (try w.callbackSummary(cls, n.j, ictx)) orelse {
                    ok = false;
                    break;
                };
                const saved = w.ro_closure;
                w.ro_closure = if (cls == .closure) cls.closure else none;
                defer w.ro_closure = saved;
                if (try w.returnsOwned(c, n.s, n.avs, ictx, n.j, 0, none, .deep)) continue;
                ok = false;
                approx = try w.ownedButApprox(c, n.s, n.avs, ictx, n.j);
                failed = cls;
                break;
            }
            if (ok) continue;
            w.lambda_needs.items[i].failed = true;
            try w.needAt(n, approx, failed);
        }
    }

    /// The line of a lambda's obligation that failed (§30.9), where the
    /// callee relied on it; `failed` is the function there that does not
    /// return owned, when one is known.
    fn needAt(w: *Walker, n: LambdaNeed, approx: bool, failed: ?Class) Allocator.Error!void {
        const detail = try std.fmt.allocPrint(w.o.out.allocator(), "{s} relies on what the function it is handed returns, and the function this lambda is handed may return a list it does not own (§30.9)", .{n.callee});
        // The lambda's parameter as the call writes it (`work`).
        const args = if (w.bir.instTag(n.inst) == .call) w.callArgs(n.inst) else &.{};
        const base = if (n.j < args.len) try w.baseText(args[n.j]) else "<function value>";
        try w.demands.append(w.a, .{
            .kind = .value,
            .token = w.token(n.inst),
            .via = w.classToken(failed),
            .op = "value",
            .base = base,
            .base_local = none,
            .base_path = eps,
            .point = n.point,
            .frame = n.frame,
            .ctx = n.ctx,
            .element = false,
            .accept = .callback_param,
            .holders = &.{},
            .fixed = .{ .verdict = .{ .rejected = .need }, .detail = detail },
            .prelim = .{ .cause = .need, .detail = detail, .approx = approx },
        });
    }

    /// §30.9: what a callee supplies its function parameter `j`'s parameter
    /// `k`, instantiated at the call.
    const SupplyCtx = struct { s: *const Summary, j: u32, ictx: InstCtx };

    fn suppliedParam(w: *Walker, k: u32, ctx: SupplyCtx) Allocator.Error!AV {
        var parts: std.ArrayList(AV) = .empty;
        for (ctx.s.supply) |e| {
            if (e.fun != ctx.j or e.k != k) continue;
            try parts.append(w.a, try w.composeSupply(e, try w.instProv(e.prov, ctx.ictx), ctx.ictx));
        }
        return w.unionOf(parts.items);
    }

    /// §30.9: what a lambda called here is handed as its parameter `k`.
    fn calledParam(w: *Walker, k: u32, avs: []const AV) Allocator.Error!AV {
        _ = w;
        return if (k < avs.len) avs[k] else &.{};
    }

    /// §30.9: the obligations left on lambdas handed where the checker does
    /// not see what they are handed — kept by JavaScript, stored, returned:
    /// nothing shows the function their parameter holds returns owned.
    fn undischargedNeeds(w: *Walker) Allocator.Error!void {
        for (w.lambda_needs.items) |*n| {
            if (n.failed) continue;
            // Every consumer must have decided it: one that cannot (a
            // runtime's entry, a callee with no summary, a place out of
            // sight) leaves it undecided, and so does a lambda never handed
            // on or called where the walk sees it.
            var decided: u32 = 0;
            var bad = n.discharges == 0;
            for (w.closures.items[n.closure].consumed.items) |c| switch (c.kind) {
                .pending, .no_summary => bad = true,
                .supply, .local => decided += 1,
            };
            if (decided > n.discharges) bad = true;
            if (!bad) continue;
            n.failed = true;
            // No consumer decided it, so no function there is known to fail.
            try w.needAt(n.*, true, null);
        }
    }

    /// §30.9: whether what a carried lambda's call returns, at this call, is
    /// all made during it: cells nothing else holds, or none.
    fn carriedCallOwned(w: *Walker, p: Prov, ictx: InstCtx) Allocator.Error!bool {
        const ci = w.ro_closure;
        if (ci == none or !w.closures.items[ci].carried) return false;
        var inner = ictx;
        inner.closure = ci;
        if (debug_own) {
            std.debug.print("CCO cb_avs:", .{});
            for (w.closures.items[ci].cb_avs) |cb| std.debug.print(" j={d} len={d}", .{ cb.j, cb.av.len });
            std.debug.print("\n", .{});
        }
        for (try w.expand(try w.instProv(p, inner))) |e| {
            const c = w.cells.items[e.cell];
            if (debug_own) std.debug.print("CCO cell kind={s} b={d}\n", .{ @tagName(c.kind), c.b });
            if (c.kind == .closure or c.kind == .func) continue;
            if (c.kind != .result or c.b == 0 or try w.isEscaped(e.cell)) return false;
        }
        return true;
    }

    /// A retained tagger capture is never owned. Symbolic captures may be
    /// required to contain no cell at callers (sep p p); cb self-separation
    /// instead means fresh across calls, so cannot encode that requirement.
    fn taggerReturnsOwned(w: *Walker, c: *const Summary, s: *const Summary, avs: []const AV, j: u32, cls: Class, ictx: InstCtx) Allocator.Error!bool {
        if (try w.returnsOwned(c, s, avs, ictx, j, 0, none, .deep)) return true;
        var res: std.ArrayList(ResEntry) = .empty;
        for (c.res) |r| {
            if (r.prov.kind == .cb and r.prov.b == 1) {
                if (r.prov.a >= w.fn_state.items.len) return false;
                // §18.9: retain the actual supplies even when the enclosing
                // tagger calls were unseen (and so formerly counted zero).
                if (cls != .closure or w.frame != 0) return false;
                const params = try w.a.alloc(AV, c.params);
                for (params, 0..) |*pa, k| {
                    var parts: std.ArrayList(AV) = .empty;
                    for (s.supply) |e| {
                        if (e.fun != j or e.k != k) continue;
                        try parts.append(w.a, try w.under(try w.instProv(e.prov, ictx), e.path));
                    }
                    pa.* = try w.unionOf(parts.items);
                }
                try w.applyEnvCalls(cls.closure, null, 0, .{ .inst = ictx.inst, .s = c, .avs = params, .closure = cls.closure, .depth = 0 });
                w.fn_state.items[r.prov.a].need = true;
                w.fn_state.items[r.prov.a].need_edit = true;
                // Deferred tagger calls cannot inherit a locally seen
                // call's supply/loan proof; keep the combined protocol unseen.
                w.fn_state.items[r.prov.a].seen = false;
                w.fn_state.items[r.prov.a].calls = .many;
                continue;
            }
            if (r.prov.kind != .env) {
                try res.append(w.a, r);
                continue;
            }
            if (cls != .closure) return false;
            const cl = w.closures.items[cls.closure];
            const captured = if (cl.carried)
                try w.carriedEnv(cls.closure, r.prov)
            else if (w.local_av[r.prov.a]) |held|
                try w.projPath(held, r.prov.path, null)
            else
                return false;
            for (try w.expand(captured)) |e| {
                const cell_kind = w.cells.items[e.cell].kind;
                // expand has already added captured descendants; code itself
                // holds no mutable cell. Each descendant is checked below.
                if (cell_kind == .closure or cell_kind == .func) continue;
                if (cell_kind != .param and cell_kind != .env) return false;
                if (try w.rely(try w.sepCond(e.cell, e.cell), w.frame) != .ok) return false;
            }
        }
        var conditional = c.*;
        conditional.res = res.items;
        return w.returnsOwned(&conditional, s, avs, ictx, j, 0, none, .deep);
    }

    /// §31.5: whether what class `c` returns of records is owned by the
    /// call that gets it — `returnsOwned` over `objs`, where a record's
    /// object is: one it made, or the record a callee handed it at `j`,
    /// supplied owned (a loan, `recordLoanDemands`). `written` is the
    /// answer's path whose object is written, null when any may be.
    fn returnsOwnedRecord(w: *Walker, c: *const Summary, s: *const Summary, avs: []const AV, ictx: InstCtx, j: u32, depth: u32, written: ?u32) Allocator.Error!bool {
        if (c.limit != .none or s.limit != .none) return false;
        // Every record object of the answer, and a record that may hold
        // lists (an open row, a type parameter), named whole in `res` at ε,
        // its object with it.
        var at_root: std.ArrayList(ResEntry) = .empty;
        for (c.res) |r| if (r.path == eps and !r.prov.condition_only) try at_root.append(w.a, r);
        for ([_][]const ResEntry{ c.objs, at_root.items }) |entries| for (entries) |r| {
            // The objects the caller writes: the answer's own, at ε, and the
            // one at the path written. A record below the one written is
            // not written, wherever it came from (an accumulator's update,
            // whose state holds what the host keeps).
            if (r.path != eps) if (written) |p| if (p != r.path) continue;
            switch (r.prov.kind) {
                .fresh => {},
                .param => {
                    // Kept, the record is not the caller's to write: kept at
                    // its own path or above it. A field kept below it (a
                    // scope a runtime holds) keeps the field, not the object,
                    // whose fields the caller still writes.
                    for (c.uses) |u| if (u.param == r.prov.a and u.bits & (bit_e | bit_j | bit_k) != 0 and w.o.isPrefix(u.path, r.prov.path)) return false;
                    var found = false;
                    for ([_][]const SupplyEntry{ s.supply, s.rsupply }) |sup| for (sup) |e| {
                        if (e.fun != j or e.k != r.prov.a or !w.o.overlap(e.path, r.prov.path)) continue;
                        found = true;
                        if (!e.owned) return false;
                        // A position a destructive read hands out waits for
                        // §31.4 item 6.
                        if (e.prov.taken) return false;
                        if (!try w.recordProvOwned(e.prov, s, avs, ictx, j, depth, null)) return false;
                    };
                    if (!found) return false;
                },
                else => return false,
            }
            // One record at two of the result's paths is not owned.
            for (c.objs) |x| if (x.path != r.path and x.prov.eql(r.prov)) return false;
        };
        return true;
    }

    /// `provOwned` for a record supply: a callback's earlier answer is owned
    /// when every class of the actual returns owned records.
    fn recordProvOwned(w: *Walker, p: Prov, s: *const Summary, avs: []const AV, ictx: InstCtx, guard: u32, depth: u32, written: ?u32) Allocator.Error!bool {
        if (p.kind != .cb) return true;
        if (p.a == guard) return true;
        if (depth >= inst_depth) {
            try w.o.hitLimit(.callbacks, depth + 1);
            return false;
        }
        const actual = (try w.actualOf(s, avs, p.a)) orelse return false;
        // The declaration's own function parameter: its callers decide.
        if (w.fnParamOf(actual) orelse try w.slotOf(actual)) |jj| {
            w.fn_state.items[jj].rneed = true;
            return true;
        }
        const classes = try w.classesOf(actual);
        if (classes.len == 0) return false;
        for (classes) |cls| {
            const c = (try w.callbackSummary(cls, p.a, ictx)) orelse return false;
            if (!try w.returnsOwnedRecord(c, s, avs, ictx, p.a, depth + 1, written)) return false;
        }
        return true;
    }

    /// §29 for records: a callback that returns the record a callee handed
    /// it from the callee's own parameter hands that loan back, so the
    /// caller's argument is written at the call, every field of it.
    fn recordLoanDemands(w: *Walker, inst: Inst.Index, callee: Callee, args: []const Inst.Index, avs: []const AV, c: *const Summary, j: u32, depth: u32) Allocator.Error!void {
        if (depth >= inst_depth) return w.o.hitLimit(.callbacks, depth + 1);
        const s = callee.sum;
        // As `returnsOwnedRecord` reads them: `objs`, and `res` at ε.
        var at_root: std.ArrayList(ResEntry) = .empty;
        for (c.res) |r| if (r.path == eps) try at_root.append(w.a, r);
        for ([_][]const ResEntry{ c.objs, at_root.items }) |answers| for (answers) |r| {
            if (r.prov.kind != .param) continue;
            for ([_][]const SupplyEntry{ s.supply, s.rsupply }) |entries| for (entries) |e| {
                if (e.fun != j or e.k != r.prov.a or !w.o.overlap(e.path, r.prov.path)) continue;
                if (!e.owned) continue;
                switch (e.prov.kind) {
                    .cb => if (e.prov.a != j) if (try w.actualOf(s, avs, e.prov.a)) |actual| {
                        for (try w.classesOf(actual)) |cls| {
                            const cc = (try w.classSummary(cls)) orelse continue;
                            try w.recordLoanDemands(inst, callee, args, avs, cc, e.prov.a, depth + 1);
                        }
                    },
                    .param => if (e.prov.a < args.len) {
                        const origin: Origin = if (s.limit != .none or c.limit != .none) .limit else if (e.approx or r.approx) .approx else .exact;
                        try w.callSiteRecordDemand(inst, args, avs, if (callee.closure != none) try w.single(.{ .kind = .closure, .a = callee.closure }) else &.{}, e.prov.a, e.prov.path, &.{}, origin);
                    },
                    else => {},
                }
            };
        };
    }

    /// §31.5: a callee writes what a function value returns, and the value
    /// may return a record it does not own. A record line.
    fn recordNeedLine(w: *Walker, tok: u32, name: []const u8, detail: []const u8, approx: bool, cls: ?Class) Allocator.Error!void {
        try w.demands.append(w.a, .{
            .kind = .value,
            .token = tok,
            .via = w.classToken(cls),
            .op = "update",
            .base = name,
            .base_local = none,
            .base_path = eps,
            .point = w.point,
            .frame = w.frame,
            .ctx = w.ctx,
            .element = false,
            .accept = .callback_param,
            .holders = &.{},
            .fixed = .{ .verdict = .{ .rejected = if (w.limit_callee) .limit else .need }, .detail = detail },
            .prelim = .{ .cause = if (w.limit_callee) .limit else .need, .detail = detail, .approx = approx or w.limit_callee },
            .fields = &.{},
        });
    }

    /// §31.5: whether the records of `av` are the caller's to hand over at
    /// this point — a probe on their objects, every field written.
    fn recordProbe(w: *Walker, inst: Inst.Index, av: AV, others: []const AV) Allocator.Error!u32 {
        const idx: u32 = @intCast(w.probe_ok.items.len);
        try w.probe_ok.append(w.a, false);
        try w.probe_record.append(w.a, true);
        try w.probe_approx.append(w.a, false);
        try w.probe_info.append(w.a, null);
        var base: std.ArrayList(Entry) = .empty;
        for (try w.expand(av)) |e| {
            if (e.path != eps) continue;
            const k = w.cells.items[e.cell].kind;
            if (k == .closure or k == .func) continue;
            if (w.isSend(w.cells.items[e.cell])) continue;
            try base.append(w.a, .{ .path = eps, .cell = e.cell, .approx = e.approx, .grown = e.grown });
        }
        try w.demandOn(.{
            .kind = .probe,
            .token = w.token(inst),
            .op = "",
            .base_text = "",
            .base_ref = null,
            .base_ty = null,
            .base = base.items,
            .others = others,
            .probe = idx,
            .fields = &.{},
        });
        return idx;
    }

    /// §16.4 item 5: whether class `c`, called by `s` as its parameter `j`,
    /// returns owned.
    /// Ownership is required at the written roots, not at their contents
    /// (`none`: every path). Aliases of those roots at any result path count.
    fn returnsOwned(w: *Walker, c: *const Summary, s: *const Summary, avs: []const AV, ictx: InstCtx, j: u32, depth: u32, written: u32, extent: WriteExtent) Allocator.Error!bool {
        if (c.limit != .none) return false;
        // A pessimistic callee's supply rows no longer say
        // where each parameter is supplied: nothing it hands back is owned.
        if (s.limit != .none) return false;
        // Read once: a nested `provOwned` sets its own.
        const within = w.ro_within;
        w.ro_within = eps;
        defer w.ro_within = within;
        if (debug_own) {
            std.debug.print("RO depth={d} j={d} within={s} closure={d} res:\n", .{ depth, j, try w.o.pathText(within), w.ro_closure });
            for (c.res) |r| std.debug.print("   {s} {s}\n", .{ try w.o.pathText(r.path), try w.o.provText(r.prov) });
        }
        for (c.res) |r| {
            // A condition annotation is not an allocation whose spine is returned.
            if (r.prov.condition_only or r.prov.kind == .klass) continue;
            if (written != none and !w.o.isPrefix(r.path, written)) continue;
            if (within != eps and !w.o.overlap(r.path, within)) continue;
            // A list from JavaScript is a limit of the analysis, not sharing
            // the text shows (§8.3, `unknown`).
            // Nor is what another function returns, which the checker does
            // not follow (§30.9: a limit, approximate).
            if (w.ro_exact and (r.approx or r.prov.kind == .top or r.prov.kind == .cb)) continue;
            switch (r.prov.kind) {
                .fresh => {},
                .param => {
                    // What the callback keeps of the parameter it returns.
                    // Under a storage write (#670), only a kept place at or
                    // above the written collection observes the write: a
                    // value kept strictly below it does not (#749).
                    const kept_place = if (written != none and extent == .storage)
                        try w.o.concat(r.prov.path, (try w.o.suffix(r.path, written)) orelse eps)
                    else
                        none;
                    for (c.uses) |u| if (u.param == r.prov.a and u.bits & (bit_e | bit_j) != 0 and
                        (if (kept_place != none) w.o.writeOverlap(kept_place, u.path, .storage) else w.o.overlap(u.path, r.prov.path))) return false;
                    for (s.supply) |e| {
                        if (e.fun != j or e.k != r.prov.a or !w.o.overlap(e.path, r.prov.path)) continue;
                        // §28.5: an approximate supply is a limit, not proven sharing.
                        if (w.ro_exact and e.approx) continue;
                        // §30.9: a borrowed supply of the callee's parameter
                        // that holds nothing at this call hands nothing.
                        if (!e.owned) {
                            if (e.prov.kind == .param and (try w.instProv(e.prov, ictx)).len == 0) continue;
                            return false;
                        }
                        // A taken item is a conditional loan. Returning it
                        // onto a feedback edge retains its source condition.
                        if (e.prov.taken) switch (try w.rely(try w.instXSum(e.xc, ictx), w.frame)) {
                            .ok => {},
                            .exact => return false,
                            .approx, .limit => if (!w.ro_exact) return false,
                        };
                        if (!try w.provOwned(e.prov, s, avs, ictx, j, depth, none, .deep)) return false;
                    }
                },
                // §30.9: a carried lambda's call of a function the caller
                // passed, judged by what it returns at this call.
                .cb => if (r.prov.b == 1) {
                    if (!try w.carriedCallOwned(r.prov, ictx)) return false;
                } else {
                    const supplied = try w.a.alloc(AV, c.params);
                    for (supplied, 0..) |*arg, k| arg.* = try w.suppliedParam(@intCast(k), .{ .s = s, .j = j, .ictx = ictx });
                    const inner: InstCtx = .{ .inst = ictx.inst, .s = c, .avs = supplied, .closure = w.ro_closure, .depth = ictx.depth + 1 };
                    if (!try w.provOwned(r.prov, c, supplied, inner, none, depth, none, .deep)) return false;
                },
                else => return false,
            }
            // One provenance at two distinct result paths is not owned.
            for (c.res) |x| {
                if (x.path != r.path and x.prov.eql(r.prov)) return false;
            }
        }
        return true;
    }

    const Item = struct { inst: Inst.Index, spread: bool };

    /// A list literal with a spread, read back as one construction (§3.2).
    fn construction(w: *Walker, top: Inst.Index) Allocator.Error!AV {
        var items: std.ArrayList(Item) = .empty;
        var cur = top;
        while (true) {
            const args = w.callArgs(cur);
            try items.append(w.a, .{ .inst = args[0], .spread = w.isSpreadAppend(cur) });
            const next = args[1];
            if (w.isSpreadCall(next) and w.balanced(w.token(cur), w.token(next))) {
                cur = next;
                continue;
            }
            if (w.bir.instTag(next) == .list and w.token(next) < w.token(cur)) {
                for (w.bir.extraSlice(Bir.inlineRange(w.bir.instData(next)), Inst.Index)) |el| {
                    try items.append(w.a, .{ .inst = el, .spread = false });
                }
            } else {
                try items.append(w.a, .{ .inst = next, .spread = true });
            }
            break;
        }
        return w.build(top, "construction", items.items);
    }

    /// A `++` chain on lists: one construction whose base is its leftmost
    /// operand (§3.2).
    fn appendChain(w: *Walker, top: Inst.Index) Allocator.Error!AV {
        var items: std.ArrayList(Item) = .empty;
        var cur = top;
        while (true) {
            const args = w.callArgs(cur);
            try items.append(w.a, .{ .inst = args[0], .spread = true });
            if (w.isListAppend(args[1])) {
                cur = args[1];
                continue;
            }
            try items.append(w.a, .{ .inst = args[1], .spread = true });
            break;
        }
        return w.build(top, "++", items.items);
    }

    fn build(w: *Walker, top: Inst.Index, op: []const u8, items: []const Item) Allocator.Error!AV {
        const insts = try w.a.alloc(Inst.Index, items.len);
        for (items, insts) |it, *x| x.* = it.inst;
        const avs = try w.evalOperands(insts, false);
        w.popPending(avs.len);
        try w.consume(insts, w.token(top));
        try w.useTemporaries(insts, avs, w.token(top));
        for (items, avs) |it, av| {
            if (it.spread) continue;
            try w.sight(av, .{ .pending = "it is stored in a list" }, w.token(top));
        }
        var base_at: ?usize = null;
        for (items, 0..) |it, i| if (it.spread) {
            base_at = i;
            break;
        };
        const bi = base_at orelse return w.single(.{ .kind = .site, .a = top.int(), .ty = w.instTypeOpt(top) });
        // A list re-built in the shape a pattern just matched is that list
        // (thesis §3.8): an alias, not a demand.
        if (w.reconsed(items)) return avs[bi];
        // A prepend — items, then the one spread, last — copies its base
        // and writes nothing (§3.2 as amended for slice 3f).
        if (bi > 0 and bi == items.len - 1) return w.prepended(top, insts, avs, bi);
        const others = try w.a.alloc(AV, avs.len - 1);
        var k: usize = 0;
        for (avs, 0..) |av, i| if (i != bi) {
            others[k] = av;
            k += 1;
        };
        const ref = try w.refPath(items[bi].inst);
        try w.demandOn(.{
            .kind = .report,
            .token = w.token(top),
            .op = op,
            .base_text = try w.baseText(items[bi].inst),
            .base_ref = ref,
            .base_ty = w.instType(items[bi].inst),
            .base = avs[bi],
            .others = others,
            .base_inst = items[bi].inst,
        });
        // §18.2: the base's condition, lowered by what is stored in it — a
        // later spread element by element when it is a temporary, and lost
        // when it is a list that lives on.
        var stored: std.ArrayList(AV) = .empty;
        // A record's: a spread list that lives on is a holder of its
        // elements, which a record demand's Dead reads (#420), so it is
        // stored element by element as a temporary is.
        var rstored: std.ArrayList(AV) = .empty;
        var spread_k = cond_yes;
        var rspread_k = cond_yes;
        for (items, avs, 0..) |it, av, i| {
            if (i == bi) continue;
            if (!it.spread) {
                try stored.append(w.a, av);
                try rstored.append(w.a, av);
            } else {
                const elems = try w.elementsOf(av);
                if ((try w.refPath(it.inst)) != null) {
                    spread_k = cond_lost;
                } else {
                    try stored.append(w.a, elems);
                    spread_k = try w.condAnd(spread_k, try w.deepCond(av));
                }
                try rstored.append(w.a, elems);
                rspread_k = try w.rcondAnd(rspread_k, try w.rdeepCond(av));
            }
        }
        const stored_k = try w.condAnd(spread_k, try w.storedCond(stored.items, try w.elementsOf(avs[bi])));
        for (avs[bi]) |e| if (e.path == eps) try w.lowerCond(e.cell, stored_k);
        // §31.4 item 6: a record stored twice, or one the list holds.
        const rstored_k = try w.rcondAnd(rspread_k, try w.rstoredCond(rstored.items, try w.elementsOf(avs[bi])));
        for (avs[bi]) |e| if (e.path == eps) try w.rlowerCond(e.cell, rstored_k);
        var parts: std.ArrayList(AV) = .empty;
        try parts.append(w.a, avs[bi]);
        for (items, avs, 0..) |it, av, i| {
            if (i == bi) continue;
            if (it.spread) {
                try parts.append(w.a, try w.shift(try w.elementsOf(av), .{ .kind = .elem, .arg = 0 }));
            } else {
                try parts.append(w.a, try w.shift(av, .{ .kind = .elem, .arg = 0 }));
            }
        }
        return w.spineValue(top, parts.items);
    }

    /// A prepend, `[ x, …xs ]` (§3.2 as amended for slice 3f): a new array
    /// holding the items and then a copy of the base's elements, so the base
    /// is only read. The result is that new array, or — when the runtime
    /// re-conses onto a view (`backend.md` §4) — a header over the base's
    /// own array: it aliases the base, whose condition it does not lower.
    /// Sound only while the backend never writes a prepend's base in place
    /// (§25.2, *The backend agrees*): `emit/PrependShapes` pins every shape,
    /// and slice 5's in-place lowering must leave prepends as copies.
    fn prepended(w: *Walker, top: Inst.Index, insts: []const Inst.Index, avs: []const AV, bi: usize) Allocator.Error!AV {
        const site = try w.single(.{ .kind = .site, .a = top.int(), .ty = w.instTypeOpt(top) });
        var stored: std.ArrayList(AV) = .empty;
        for (avs[0..bi]) |av| try stored.append(w.a, av);
        const k = try w.condAnd(try w.storedCond(stored.items, try w.elementsOf(avs[bi])), try w.deepCond(avs[bi]));
        try w.initCond(site[0].cell, k);
        try w.rinitCond(site[0].cell, try w.rcondAnd(try w.rstoredCond(stored.items, try w.elementsOf(avs[bi])), try w.rdeepCond(avs[bi])));
        var parts: std.ArrayList(AV) = .empty;
        try parts.append(w.a, site);
        // The array may be the base's — only a re-cons makes it so, which
        // the text does not show (§8.4) — while the elements are the base's.
        // Not when the item put in front of the base is a list made after
        // it (§26.3): a re-cons needs that item to be already stored before
        // the base's view, and a new array the base cannot reach is not.
        if (!try w.madeAfter(insts[bi - 1], avs[bi - 1], avs[bi])) try parts.append(w.a, try w.approxAll(avs[bi], top));
        try parts.append(w.a, try w.shift(try w.proj(avs[bi], .{ .kind = .elem, .arg = 0 }, w.listElement(top)), .{ .kind = .elem, .arg = 0 }));
        for (stored.items) |av| try parts.append(w.a, try w.shift(av, .{ .kind = .elem, .arg = 0 }));
        return w.spineValue(top, parts.items);
    }

    /// §26.3: whether `item`, put in front of a prepend's base, is a list
    /// made after the base — so that no re-cons can answer the base's
    /// array. Core's `cons` re-conses only when the item is `Js.same` as the
    /// element stored before the base's view (or in a trie head's slack),
    /// an element of a list whose array the base shares: one the domain
    /// names at the base's cells (a view is its scrutinee's cells, §5). A
    /// list is compared by identity, and a new array — a literal's, or a
    /// callee's fresh result, exact, never handed to JavaScript — is that
    /// element only if the base reaches it. Anything else may be.
    fn madeAfter(w: *Walker, item: Inst.Index, item_av: AV, base: AV) Allocator.Error!bool {
        if (w.listElement(item) == null) return false;
        var cells: std.ArrayList(Entry) = .empty;
        for (item_av) |e| {
            if (e.path != eps) continue;
            if (e.approx != 0) return false;
            const c = w.cells.items[e.cell];
            switch (c.kind) {
                // A list literal's new array.
                .site => {},
                // A call's result: `b` is the callee's fresh number, made
                // from its summary's `fresh` (`instProv`). `b == 0` is §6.1's
                // assumed fresh cell of a callee with no summary, which may
                // be any argument or a top-level list: not known to be new.
                .result => if (c.b == 0) return false,
                .param, .env, .shared, .top, .closure, .func, .cbres, .taken, .payload, .except => return false,
            }
            // Exact (above) and never handed to JavaScript (here), which
            // could store it anywhere, the base's array included.
            if (try w.isEscaped(e.cell)) return false;
            try cells.append(w.a, e);
        }
        if (cells.items.len == 0) return false;
        return (try w.reaches(base, cells.items)) == null;
    }

    /// The element type of a list-typed instruction, when the checker solved it.
    fn listElement(w: *Walker, inst: Inst.Index) ?Var {
        const v = w.instType(inst) orelse return null;
        switch (w.store.resolvedContent(v)) {
            .structure => |s| switch (s) {
                .app => |a| {
                    if (a.type != w.o.in.types.well_known.list) return null;
                    const args = w.store.vars(a.args);
                    return if (args.len == 1) args[0] else null;
                },
                else => return null,
            },
            else => return null,
        }
    }

    /// A symbolic value can reveal new array paths when it is projected.
    fn symbolicSpine(w: *const Walker, c: u32) bool {
        return switch (w.cells.items[c].kind) {
            .param, .env, .cbres, .taken, .except, .top, .payload => true,
            .site, .result, .shared, .closure, .func => false,
        };
    }

    /// A folded Dict tree's arrival names separate positions under the
    /// existing trusted no-duplication obligation (§20.8–§20.9). Keep the
    /// selected position's container requirement: expanding two structural
    /// paths can name the same incoming value as alternatives, which is not
    /// a value retained twice. Caller construction guards still establish
    /// that requirement; distinct arrivals still require separation.
    fn rootSeparation(w: *Walker, x: u32, y: u32) Allocator.Error!u32 {
        const a = w.cells.items[x];
        const b = w.cells.items[y];
        if (w.inCoreDict() and a.kind == b.kind and a.scope == b.scope and a.a == b.a and a.b == b.b) switch (a.kind) {
            .param, .env, .cbres => if (try w.o.dictTreePath(a.path) and try w.o.dictTreePath(b.path)) return w.atomCond(.{ .kind = .spine, .a = x }),
            else => {},
        };
        return w.atomCond(.{ .kind = .sep_root, .a = x, .b = y });
    }

    /// The array at x's root versus everything y holds. An unresolved
    /// right operand keeps this asymmetric requirement for its caller.
    fn sepRootValues(w: *Walker, x: AV, y: AV) Allocator.Error!u32 {
        var acc: CondAcc = .{};
        const other = try w.expand(y);
        const any = try w.o.child(eps, .any, 0);
        const runtime = try w.o.child(eps, .any, 1);
        for (x) |e| {
            if ((e.path != eps and e.path != any and e.path != runtime) or w.cells.items[e.cell].condition_only or w.listFacing(e.cell) == null) continue;
            for (other) |f| {
                if (w.cells.items[f.cell].condition_only or w.listFacing(f.cell) == null) continue;
                const k = try w.sepSpines(e.cell, f.cell, e.approx == 0 and f.approx == 0);
                try acc.add(w, if (k > cond_fixed_last) try w.rootSeparation(e.cell, f.cell) else k);
            }
        }
        return w.condAndAll(&acc);
    }

    /// A guard at a symbolic result path is a projection rule, not a
    /// whole-element condition. Only its selected side follows the read.
    fn projectSpineGuard(w: *Walker, c: u32, step: Step, ty: ?Var) Allocator.Error!?u32 {
        const k = try w.cellSpine(c);
        if (k <= cond_fixed_last) return null;
        var atoms: std.ArrayList(WAtom) = .empty;
        for (w.conds.items[k].atoms) |t| {
            if (t.kind != .sep_root) continue;
            const selected = (try w.projCell(t.a, step, ty)) orelse continue;
            const separation = try w.rootSeparation(selected, t.b);
            try atoms.appendSlice(w.a, w.conds.items[separation].atoms);
        }
        if (atoms.items.len == 0) return null;
        var guard_cell = w.cells.items[c];
        guard_cell.path = try w.o.child(guard_cell.path, step.kind, step.arg);
        const guard = try w.cell(guard_cell);
        try w.initCond(guard, cond_yes);
        try w.rinitCond(guard, cond_yes);
        try w.initSpine(guard, try w.mkCond(atoms.items));
        return guard;
    }

    /// Distribute an annotation over actual target paths before the
    /// result is normalised. A parameter remains projectable; a concrete
    /// tuple supplies independent guards at .0 and .1.
    /// `grown_in` is `grownArgs(ctx)` when the caller has it; null, and it
    /// is computed here once, when an atom needs it.
    fn annotationSpines(w: *Walker, cells: AV, sc: XSum, ctx: InstCtx, mark: Grown, grown_in: ?[]const ?[2]TyRef, memo: ?*XMemo) Allocator.Error!AV {
        var fixed: std.ArrayList(XAtom) = .empty;
        for (sc.atoms) |t| if (t.kind != .sep_root) try fixed.append(w.a, t);
        const base = if (memo) |m| try w.instXSumOnce(.{ .no = sc.no, .atoms = fixed.items }, ctx, m) else try w.instXSum(.{ .no = sc.no, .atoms = fixed.items }, ctx);
        for (cells) |e| if (e.path == eps) try w.initSpine(e.cell, base);
        var out: std.ArrayList(Entry) = .empty;
        try out.appendSlice(w.a, cells);
        var grown_known = grown_in;
        // These guards are annotations on this call's own results. With
        // no such result among the arguments, parameter-only separation
        // cannot read them until the completed result is returned. A
        // callback can run speculative walks, so keep its original update
        // order and never retain condition ids across those walks.
        // Conjoin each guard's atoms once instead of copying every prefix.
        const batch = (if (memo) |m| m.ok else false) and for (sc.atoms) |t| {
            if (t.kind == .sep_root and !overParams(t)) break false;
        } else true;
        var conditions: std.ArrayList(CondAcc) = .empty;
        var touched: std.ArrayList(u32) = .empty;
        var seen_conditions: std.AutoHashMapUnmanaged([2]u32, void) = .empty;
        for (sc.atoms) |t| {
            if (t.kind != .sep_root) continue;
            const raw_selected = try w.instProv(t.a, ctx);
            var before: std.ArrayList(Entry) = .empty;
            var cut = false;
            if (grown_known == null) grown_known = try w.grownArgs(ctx);
            const grown = grown_known.?;
            const selected = try w.composeRes(.{ .path = eps, .prov = t.a }, raw_selected, grown, &before, &cut);
            if (cut) try w.foldedPairs(before.items, selected);
            const other = try w.expand(try w.instProv(t.b, ctx));
            // A path does not affect its cell's separation condition. Reuse
            // adjacent identical comparisons without allocating a table, and
            // keep every path's guard and the last approximation as before.
            const Comparison = struct { cell: u32, approx: u32, condition: u32, cause: u32 };
            var previous: ?Comparison = null;
            for (selected) |e| {
                if (w.cells.items[e.cell].condition_only or w.listFacing(e.cell) == null) continue;
                const comparison = blk: {
                    if (previous) |p| if (p.cell == e.cell and p.approx == e.approx) break :blk p;
                    var acc: CondAcc = .{};
                    var approximate = e.approx;
                    var last_operand: ?Entry = null;
                    for (other) |f| {
                        if (w.cells.items[f.cell].condition_only or w.listFacing(f.cell) == null) continue;
                        if (f.approx != 0) approximate = f.approx;
                        if (last_operand) |p| if (p.cell == f.cell and p.approx == f.approx) continue;
                        last_operand = f;
                        const separation = try w.sepSpines(e.cell, f.cell, e.approx == 0 and f.approx == 0);
                        if (separation == cond_yes) continue;
                        try acc.add(w, if (w.symbolicSpine(e.cell)) try w.rootSeparation(e.cell, f.cell) else separation);
                    }
                    break :blk Comparison{ .cell = e.cell, .approx = e.approx, .condition = try w.condAndAll(&acc), .cause = approximate };
                };
                previous = comparison;
                const k = comparison.condition;
                const approximate = comparison.cause;
                if (k == cond_yes) continue;
                for (cells) |root| {
                    if (root.path != eps) continue;
                    var guard_cell = w.cells.items[root.cell];
                    guard_cell.path = try w.o.concat(guard_cell.path, e.path);
                    const guard = try w.cell(guard_cell);
                    try w.initCond(guard, cond_yes);
                    try w.rinitCond(guard, cond_yes);
                    if (batch and guard_cell.condition_only) {
                        if (guard >= conditions.items.len) try conditions.appendNTimes(w.a, .{}, guard + 1 - conditions.items.len);
                        if (!(try seen_conditions.getOrPut(w.a, .{ guard, k })).found_existing) {
                            const acc = &conditions.items[guard];
                            if (acc.last == none) try touched.append(w.a, guard);
                            try acc.add(w, k);
                        }
                    } else try w.initSpine(guard, k);
                    var growth = gJoin(e.grown, root.grown);
                    if (gGuard(mark)) |distance| {
                        growth = gGuardAt(growth, distance + w.o.paths.depth.items[e.path]);
                    } else if (gMarked(e.grown)) {
                        if (t.a.kind == .param and t.a.a < grown.len) if (grown[t.a.a]) |types| {
                            const full = try w.o.concat(t.a.path, e.path);
                            if (try w.polyBound(full, types[0], types[1])) |boundary| {
                                const pd = w.o.paths.depth.items[t.a.path];
                                const relative = if (boundary > pd) boundary - pd else 0;
                                const depth = w.o.paths.depth.items[e.path];
                                if (depth > relative) growth = gGuardAt(growth, @intCast(depth - relative));
                            }
                        };
                    }
                    try out.append(w.a, .{ .path = e.path, .cell = guard, .approx = approximate, .grown = growth });
                }
            }
        }
        for (touched.items) |guard| try w.initSpine(guard, try w.condAndAll(&conditions.items[guard]));
        return w.norm(out.items);
    }

    /// What another operand's entry `f` holds at `e`'s place, for a
    /// construction's separation per path: `f`'s own cell, or, when `f`
    /// stands above `e` (an element of a parameter's list, beside a tuple
    /// pushed with a list at its `.0`), `f`'s cell projected to `e`'s
    /// place, since what it holds there is stored beside `e` (#474). Null
    /// when the pair needs no separation at `e`'s place.
    fn besideCell(w: *Walker, e: Entry, f: Entry) Allocator.Error!?u32 {
        if (e.path == f.path or !try w.nested(e, f)) return f.cell;
        if (e.cell == f.cell or !w.o.startsWith(e.path, f.path)) return null;
        var c = f.cell;
        const rest = w.o.steps((try w.o.suffix(f.path, e.path)).?);
        // The place's type is `e`'s, which the last step reaches.
        for (rest, 0..) |s, i| c = (try w.projCell(c, s, if (i + 1 == rest.len) w.cells.items[e.cell].ty.unwrap() else null)) orelse return null;
        if (w.cells.items[c].condition_only or w.listFacing(c) == null) return null;
        // `e` itself, which `f` holds at its place (a row that names a
        // parameter and its elements): one position, not two.
        var x = w.cells.items[c];
        var y = w.cells.items[e.cell];
        x.ty = .none;
        y.ty = .none;
        if (std.meta.eql(x, y)) return null;
        return c;
    }

    /// A construction's container conditions, one guard per result path.
    /// The guard belongs to the containing value, never to an allocation:
    /// sharing keys at one path must not poison fresh values at another.
    /// Compare before `norm` merges repeated entries at `[*]`.
    fn spineValue(w: *Walker, inst: Inst.Index, parts: []const AV) Allocator.Error!AV {
        var out: std.ArrayList(Entry) = .empty;
        for (parts) |part| try out.appendSlice(w.a, part);
        for (parts, 0..) |part, i| for (part) |e| {
            if (w.cells.items[e.cell].condition_only or w.listFacing(e.cell) == null) continue;
            var acc: CondAcc = .{};
            var approximate = e.approx;
            for (parts, 0..) |other, j| {
                if (i == j) continue;
                for (other) |f| {
                    if (w.cells.items[f.cell].condition_only or w.listFacing(f.cell) == null) continue;
                    if (f.approx != 0) approximate = f.approx;
                    const g = (try w.besideCell(e, f)) orelse continue;
                    const separation = try w.sepSpines(e.cell, g, e.approx == 0 and f.approx == 0);
                    if (separation == cond_yes) continue;
                    try acc.add(w, if (w.symbolicSpine(e.cell)) try w.rootSeparation(e.cell, g) else separation);
                }
            }
            const k = try w.condAndAll(&acc);
            if (k == cond_yes) continue;
            const guard = try w.cell(.{ .kind = .site, .a = inst.int(), .b = 1, .path = e.path, .condition_only = true });
            try w.initCond(guard, cond_yes);
            try w.initSpine(guard, k);
            try out.append(w.a, .{ .path = e.path, .cell = guard, .approx = approximate, .grown = e.grown });
        };
        return w.norm(out.items);
    }

    /// §16.7: conditions on operands that coexist in this construction.
    /// The annotation follows the containing value, not either allocation.
    fn containingCondition(w: *Walker, inst: Inst.Index, avs: []const AV) Allocator.Error!AV {
        // Each operand's cells once, not once per pair (#684), and each made
        // when the pairwise reading first needed it, so that every cell is
        // interned in the order it always was. The operands are pairwise
        // apart: one pass, not one per pair (§16.7, #693).
        const cells = try w.a.alloc(?AV, avs.len);
        const rcells = try w.a.alloc(?AV, avs.len);
        @memset(cells, null);
        @memset(rcells, null);
        // The pairs' order, in which the first nonempty operand meets every
        // later one, each in turn, and every operand before it is empty.
        var first: ?usize = null;
        for (avs, 0..) |av, j| {
            if (av.len == 0) continue;
            const i = first orelse {
                first = j;
                continue;
            };
            if (cells[i] == null) cells[i] = try w.sepCellList(avs[i]);
            cells[j] = try w.sepCellList(av);
            if (rcells[i] == null) rcells[i] = try w.rsepCellList(avs[i]);
            rcells[j] = try w.rsepCellList(av);
        }
        const groups = try w.a.alloc(AV, avs.len);
        const rgroups = try w.a.alloc(AV, avs.len);
        for (groups, rgroups, cells, rcells) |*g, *r, c, rc| {
            g.* = c orelse &.{};
            r.* = rc orelse &.{};
        }
        const k = try w.pairwiseApart(groups, .list);
        const rk = try w.pairwiseApart(rgroups, .record);
        if (k == cond_yes and rk == cond_yes) return &.{};
        const guard = try w.single(.{ .kind = .site, .a = inst.int(), .ty = w.instTypeOpt(inst), .condition_only = true });
        try w.initCond(guard[0].cell, k);
        try w.rinitCond(guard[0].cell, rk);
        return guard;
    }

    /// §20.8: cells two constructor operands place at one folded path
    /// retain the separation condition that the fold would otherwise hide.
    fn storedBeside(w: *Walker, parts: []const AV) Allocator.Error!void {
        var filled: usize = 0;
        for (parts) |p| if (p.len > 0) {
            filled += 1;
        };
        if (filled < 2) return;
        // Every part came from shift/norm (the annotation is a singleton).
        // Only equal destination paths can hide a coexisting occurrence.
        for (parts) |p| if (std.debug.runtime_safety and p.len > 1) {
            for (p[1..], 0..) |e, i| std.debug.assert(p[i].path <= e.path);
        };
        for (parts, 0..) |p, i| for (parts[i + 1 ..]) |q| {
            var from: usize = 0;
            var to: usize = 0;
            var last: u32 = none;
            for (p) |e| {
                if (e.path != last) {
                    while (from < q.len and q[from].path < e.path) : (from += 1) {}
                    to = from;
                    while (to < q.len and q[to].path == e.path) : (to += 1) {}
                    last = e.path;
                }
                for (q[from..to]) |f| try w.storedPair(e, f);
            }
        };
    }

    fn storedPair(w: *Walker, e: Entry, f: Entry) Allocator.Error!void {
        if (e.cell == f.cell) return;
        const ke = w.cells.items[e.cell].kind;
        const kf = w.cells.items[f.cell].kind;
        if (ke == .closure or ke == .func or kf == .closure or kf == .func) return;
        const k = try w.sepCells(e.cell, f.cell, e.approx == 0 and f.approx == 0);
        try w.lowerCond(e.cell, k);
        try w.lowerCond(f.cell, k);
        const rk = try w.rsepCells(e.cell, f.cell, e.approx == 0 and f.approx == 0);
        try w.rlowerCond(e.cell, rk);
        try w.rlowerCond(f.cell, rk);
        const sk = try w.sepSpines(e.cell, f.cell, e.approx == 0 and f.approx == 0);
        try w.lowerSpine(e.cell, sk);
        try w.lowerSpine(f.cell, sk);
    }

    /// The entries of a list value at its elements, re-rooted.
    fn elementsOf(w: *Walker, av: AV) Allocator.Error!AV {
        return w.proj(av, .{ .kind = .elem, .arg = 0 }, null);
    }

    fn reconsed(w: *Walker, items: []const Item) bool {
        var list: ?Inst.Index = null;
        for (items, 0..) |it, i| {
            if (w.bir.instTag(it.inst) != .local) return false;
            const l = w.bir.instData(it.inst).lhs;
            if (l >= w.pat_site.len) return false;
            const site = w.pat_site[l] orelse return false;
            if (site.index != i or site.spread != it.spread) return false;
            if (list) |x| {
                if (x != site.list) return false;
            } else list = site.list;
        }
        const pl = list orelse return false;
        return w.bir.extraSlice(Bir.inlineRange(w.bir.instData(pl)), Inst.Index).len == items.len;
    }

    // ---- the check (§8) --------------------------------------------------

    /// When a value holding `outer` also holds `inner`, the path from the
    /// one to the other: a symbolic cell stands for every cell under it
    /// (§4.3), so `param(x, ε)` holds `param(x, .items)` at `.items`.
    fn covers(w: *Walker, outer: u32, inner: u32) Allocator.Error!?u32 {
        const c = (try w.coversAt(outer, inner)) orelse return null;
        return c.rest;
    }

    const Cover = struct { rest: u32, approx: bool = false };

    /// `covers`, saying whether the hold is approximate: one of the places
    /// a region's marker stands for (§16.7).
    fn coversAt(w: *Walker, outer: u32, inner: u32) Allocator.Error!?Cover {
        if (outer == inner) return if (w.cells.items[outer].condition_only) null else .{ .rest = eps };
        const oc = w.cells.items[outer];
        const ic = w.cells.items[inner];
        if (oc.condition_only or ic.condition_only) return null;
        if (oc.kind != .except and (oc.kind != ic.kind or oc.a != ic.a or oc.b != ic.b or oc.scope != ic.scope)) return null;
        const key: [2]u32 = .{ outer, inner };
        if (w.cover_memo.get(key)) |cached| return cached;
        const answer = try w.coversAtRaw(outer, inner);
        try w.cover_memo.put(w.a, key, answer);
        return answer;
    }

    fn coversAtRaw(w: *Walker, outer: u32, inner: u32) Allocator.Error!?Cover {
        if (w.cells.items[outer].condition_only or w.cells.items[inner].condition_only) return null;
        if (outer == inner) return .{ .rest = eps };
        const o = w.cells.items[outer];
        const i = w.cells.items[inner];
        // §31.2: the record object written over `o.a`, and the fields it did
        // not write.
        if (o.kind == .except) {
            if (inner == o.a) return .{ .rest = eps };
            if (o.b == except_all) return null;
            const c = (try w.coversAt(o.a, inner)) orelse return null;
            if (w.o.firstStep(c.rest)) |first| {
                if (first.kind == .field and std.mem.indexOfScalar(u32, w.exsets.items[o.b], first.arg) != null) return null;
            }
            return c;
        }
        switch (o.kind) {
            .param, .result, .env, .shared, .cbres, .taken, .payload => {},
            .site, .top, .closure, .func, .except => return null,
        }
        if (o.kind != i.kind or o.a != i.a or o.b != i.b or o.scope != i.scope) return null;
        // One place named twice (a definition's made cell, and the same value
        // through another's summary) is one cell.
        if (w.o.physicalPath(o.path) == w.o.physicalPath(i.path)) return .{ .rest = eps };
        const so = w.o.steps(o.path);
        const si = w.o.steps(i.path);
        if (so.len < si.len) exact: {
            for (so, si[0..so.len]) |x, y| if (x.kind != y.kind or x.arg != y.arg) break :exact;
            var at: u32 = eps;
            for (si[so.len..]) |s| at = try w.o.child(at, s.kind, s.arg);
            return .{ .rest = at };
        }
        // §16.7: one of the places a region's marker stands for may be
        // held, somewhere below it.
        if (w.o.levelHoldsPaths(o.path, i.path)) return .{ .rest = try w.o.child(eps, .any, 0), .approx = true };
        return null;
    }

    /// Where `av`, closures expanded, holds one of `cells`: the first such
    /// entry, with its path extended to the cell, or null.
    fn reaches(w: *Walker, av: AV, cells: []const Entry) Allocator.Error!?Entry {
        // An exact entry first: an approximate one is reported only when no
        // exact one reaches the cell.
        var found: ?Entry = null;
        for (try w.expand(av)) |e| {
            // This holder cannot produce an exact hit, and its own mark
            // takes precedence over every inner mark or approximate cover.
            if (e.approx != 0) if (found) |f| if (f.approx <= e.approx) continue;
            for (cells) |c| {
                if (e.approx == 0 and c.approx != 0) if (found) |f| if (f.approx <= c.approx) continue;
                const cv = (try w.coversAt(e.cell, c.cell)) orelse
                    (if (try w.splitBase(c.cell, none)) |b| (try w.coversAt(e.cell, b)) orelse continue else continue);
                const hit: Entry = .{ .path = try w.o.concat(e.path, cv.rest), .cell = c.cell, .approx = if (e.approx != 0) e.approx else if (c.approx != 0) c.approx else if (cv.approx) approx_place else 0, .grown = gJoin(e.grown, c.grown) };
                if (hit.approx == 0) return hit;
                if (found == null or hit.approx < found.?.approx) found = hit;
                if (e.approx != 0) break;
            }
        }
        return found;
    }

    /// A value with no closure, its entries by the cell a cover needs: the
    /// kind, `a` and `b` of the cell, or of the one an `except` cell was
    /// written over. `coversAt(outer, inner)` is null, and touches nothing,
    /// unless `outer`'s key is `inner`'s (#716).
    const ReachIndex = struct {
        av: AV,
        by: std.AutoHashMapUnmanaged([3]u32, std.ArrayList(u32)) = .empty,
    };

    fn coverKey(w: *const Walker, c: u32) [3]u32 {
        var x = w.cells.items[c];
        if (x.kind == .except) x = w.cells.items[x.a];
        return .{ @backingInt(x.kind), x.a, x.b };
    }

    /// Whether an entry of `av` covers `c` (`covers`), asked of `av`'s
    /// entries in order until one does, as a scan of all of them asks: the
    /// entries whose key (`by`) is not `c`'s answer null and touch nothing.
    fn coveredBy(w: *Walker, av: AV, by: *const std.AutoHashMapUnmanaged([3]u32, std.ArrayList(u32)), c: u32) Allocator.Error!bool {
        const got = if (by.get(w.coverKey(c))) |l| for (l.items) |k| {
            if ((try w.covers(av[k].cell, c)) != null) break true;
        } else false else false;
        if (std.debug.runtime_safety and @import("ownership_options").full_cross_check) {
            const want = for (av) |i| {
                if ((try w.covers(i.cell, c)) != null) break true;
            } else false;
            std.debug.assert(got == want);
        }
        return got;
    }

    /// The index of `av`, or null when it holds a closure (`expand` would
    /// change it).
    fn reachIndex(w: *Walker, av: AV) Allocator.Error!?*ReachIndex {
        for (av) |e| if (w.cells.items[e.cell].kind == .closure) return null;
        const idx = try w.a.create(ReachIndex);
        idx.* = .{ .av = av };
        for (av, 0..) |e, i| {
            const g = try idx.by.getOrPut(w.a, w.coverKey(e.cell));
            if (!g.found_existing) g.value_ptr.* = .empty;
            try g.value_ptr.append(w.a, @intCast(i));
        }
        return idx;
    }

    /// `reaches(rest, cells)`, `rest` the entries of the index's value that
    /// do not overlap `except` (all of them when it is `none`): the same
    /// answer through the same calls, in the same order, but for the
    /// entries no cell's key names, which reach nothing and, once each
    /// cell's `splitBase` has been asked for, change nothing (#716).
    fn reachesIndexed(w: *Walker, idx: *const ReachIndex, except: u32, cells: []const Entry) Allocator.Error!?Entry {
        const got = try w.reachesIndexedRaw(idx, except, cells);
        if (std.debug.runtime_safety and @import("ownership_options").full_cross_check) {
            var rest: std.ArrayList(Entry) = .empty;
            for (idx.av) |e| if (except == none or !w.o.overlap(e.path, except)) try rest.append(w.a, e);
            const want = try w.reaches(rest.items, cells);
            std.debug.assert((got == null) == (want == null));
            if (got) |g| std.debug.assert(std.meta.eql(g, want.?));
        }
        return got;
    }

    fn reachesIndexedRaw(w: *Walker, idx: *const ReachIndex, except: u32, cells: []const Entry) Allocator.Error!?Entry {
        const av = idx.av;
        var found: ?Entry = null;
        // Whether `splitBase` was asked for each cell yet: the first ask
        // may make its cell, as the scan of every entry would.
        const asked = try w.a.alloc(bool, cells.len);
        @memset(asked, false);
        var left = cells.len;
        var i: usize = 0;
        // Until every cell's split base is asked for, entry by entry.
        while (i < av.len and left > 0) : (i += 1) {
            const e = av[i];
            if (except != none and w.o.overlap(e.path, except)) continue;
            for (cells, 0..) |c, ci| {
                const cv = (try w.coversAt(e.cell, c.cell)) orelse blk: {
                    if (!asked[ci]) {
                        asked[ci] = true;
                        left -= 1;
                    }
                    const b = (try w.splitBase(c.cell, none)) orelse continue;
                    break :blk (try w.coversAt(e.cell, b)) orelse continue;
                };
                const hit: Entry = .{ .path = try w.o.concat(e.path, cv.rest), .cell = c.cell, .approx = if (e.approx != 0) e.approx else if (c.approx != 0) c.approx else if (cv.approx) approx_place else 0, .grown = gJoin(e.grown, c.grown) };
                if (hit.approx == 0) return hit;
                if (found == null or hit.approx < found.?.approx) found = hit;
            }
        }
        if (i >= av.len) return found;
        // Then only the entries a cell, or its split base, names.
        var cand: std.ArrayList(u32) = .empty;
        for (cells) |c| {
            if (idx.by.get(w.coverKey(c.cell))) |l| try cand.appendSlice(w.a, l.items);
            if (try w.splitBase(c.cell, none)) |b| if (idx.by.get(w.coverKey(b))) |l| try cand.appendSlice(w.a, l.items);
        }
        std.mem.sort(u32, cand.items, {}, std.sort.asc(u32));
        var last: u32 = none;
        for (cand.items) |ei| {
            if (ei < i or ei == last) continue;
            last = ei;
            const e = av[ei];
            if (except != none and w.o.overlap(e.path, except)) continue;
            for (cells) |c| {
                const cv = (try w.coversAt(e.cell, c.cell)) orelse
                    (if (try w.splitBase(c.cell, none)) |b| (try w.coversAt(e.cell, b)) orelse continue else continue);
                const hit: Entry = .{ .path = try w.o.concat(e.path, cv.rest), .cell = c.cell, .approx = if (e.approx != 0) e.approx else if (c.approx != 0) c.approx else if (cv.approx) approx_place else 0, .grown = gJoin(e.grown, c.grown) };
                if (hit.approx == 0) return hit;
                if (found == null or hit.approx < found.?.approx) found = hit;
            }
        }
        return found;
    }

    const DemandSpec = struct {
        inst: u32 = none,
        kind: DemandKind,
        token: u32,
        op: []const u8,
        base_text: []const u8,
        base_ref: ?Capture,
        base_ty: ?Var,
        base: AV,
        others: []const AV,
        note: []const u8 = "",
        probe: u32 = none,
        origin: Origin = .exact,
        /// §18.4 item 3: the callee relied on this argument's contents being
        /// exclusive, and they may not be.
        xfail: ?Rely = null,
        /// §18.8: a closure's own cell is demanded (a once closure's call).
        closures: bool = false,
        creation_ci: u32 = none,
        /// §20.6: an entry demand, by its row.
        entry: bool = false,
        /// §20.5: the messages a view builds, which may hold the cell: a
        /// payload, not an operand.
        payload_from: AV = &.{},
        /// §23.2: a send's demand, its base already flattened.
        deep: bool = false,
        extent: WriteExtent = .deep,
        /// §28.6: the base's instruction, when the source writes it.
        base_inst: ?Inst.Index = null,
        /// §31.3: a record update's demand on its base's object, and the
        /// fields it writes.
        fields: ?[]const u32 = null,
        /// An operand before `others`: the indexed value's entries that do
        /// not overlap `rest_except` (the model's other paths, §20.6).
        rest_index: ?*const ReachIndex = null,
        rest_except: u32 = none,
        /// `payload_from`, indexed.
        payload_index: ?*const ReachIndex = null,
    };

    fn demandOn(w: *Walker, spec: DemandSpec) Allocator.Error!void {
        const out = w.o.out.allocator();
        // The base's cells: at ε, and every `⋆` entry that may be the base.
        var cells: std.ArrayList(Entry) = .empty;
        const any = try w.o.child(eps, .any, 0);
        for (spec.base) |e_in| {
            if (w.cells.items[e_in.cell].condition_only) continue;
            // §31.2: a record's object is no list's; the record demand of
            // §31.3 is the one that reads it.
            const e = Entry{ .path = e_in.path, .cell = (if (spec.fields != null) w.recordObject(e_in.cell) else w.listFacing(e_in.cell)) orelse continue, .approx = e_in.approx, .grown = gJoin(e_in.grown, w.use_grown) };
            const k = w.cells.items[e.cell].kind;
            if ((k == .closure and !spec.closures) or k == .func) continue;
            if (e.path == eps) {
                try cells.append(w.a, e);
                continue;
            }
            if (e.path != any and !(w.o.paths.parent.items[e.path] == eps and w.o.paths.kind.items[e.path] == .any)) continue;
            const c = w.cells.items[e.cell];
            // An incompatible host view retains its contents at ⋆₁. Their
            // original static type cannot disprove physical sharing after
            // the cast, including a wildcard type from recursive growth.
            const erased = w.o.paths.kind.items[e.path] == .any and w.o.paths.arg.items[e.path] == 1;
            if (!erased) if (spec.base_ty) |bt| if (c.ty.unwrap()) |ct| if (!try w.o.mayShare(w.store, bt, ct, 0)) continue;
            try cells.append(w.a, e);
        }
        var rec: DemandRec = .{
            .inst = spec.inst,
            .kind = spec.kind,
            .token = spec.token,
            .op = spec.op,
            .base = spec.base_text,
            .base_local = if (spec.base_ref) |r| r.local else none,
            .base_path = if (spec.base_ref) |r| r.path else eps,
            .point = w.point,
            .frame = w.frame,
            .ctx = w.ctx,
            .element = false,
            .accept = .fresh,
            .holders = &.{},
            .cells = cells.items,
            .note = spec.note,
            .probe = spec.probe,
            .creation_ci = spec.creation_ci,
            .origin = spec.origin,
            .entry = spec.entry,
            .deep = spec.deep,
            .extent = spec.extent,
            .fields = spec.fields,
            .use_mark = @intCast(w.uses.items.len),
        };
        if (w.mode == .report) {
            rec.span = w.span;
            if (spec.base_inst) |bi| if (w.spanOf(bi)) |s| {
                rec.base_span = s;
            };
        }
        // A probe on nothing passes: nothing is supplied.
        // Known, Unescaped, Captured, in that order across the cells.
        var worst: ?Cause = null;
        var worst_detail: []const u8 = "";
        var worst_approx: ?bool = null;
        var worst_top: ?[3]u32 = null;
        for (cells.items) |e| {
            // A taken element is classified as the element it stands for
            // (§18.5); writing it relies on its container being exclusive.
            const base = try w.takenBase(e.cell);
            const c = w.cells.items[base];
            // A record demand relies on its container without stating it: what a
            // summary requires of its callers for records is §31.7's (R2c).
            if (base != e.cell and spec.kind != .probe) switch (try w.relyAs(if (spec.fields == null and spec.extent == .storage and w.instCol(?AV, w.split_scrut, w.cells.items[e.cell].b, null) == null) try w.spineCond(spec.base) else try w.cellCond(e.cell), w.frame, spec.fields == null)) {
                .ok => {},
                else => |r| rec.xfail = Rely.worse(rec.xfail, r),
            };
            // A taken element is one position, not the list's elements at large.
            if (base == e.cell and try w.o.representative(c.path)) rec.element = true;
            const rank: Accept = switch (c.kind) {
                .param => if (c.b == 1) .callback_param else .param,
                .result, .cbres => .call,
                .site, .env, .shared, .top, .closure, .func, .taken, .payload, .except => .fresh,
            };
            if (@backingInt(rank) > @backingInt(rec.accept)) rec.accept = rank;
            if (c.kind == .result and c.b == 0 and rec.assumed.len == 0) rec.assumed = try w.callName(@fromBackingInt(c.a));
            var cause: ?Cause = null;
            var detail: []const u8 = "";
            switch (c.kind) {
                .top => if (c.a == 1) {
                    cause = .limit;
                    detail = "it came from a callee whose summary is past the checker's limits";
                } else if (c.a == 2) {
                    // §30.10: a schema's run answered part of its input, at
                    // a call the checker did not see as a run.
                    cause = .unknown;
                    detail = "it may be part of the value a schema was run on";
                } else if (c.a == unfollowed) {
                    cause = .unknown;
                    detail = "a schema answered it whose functions the checker does not follow — one built at run time, or a conversion it cannot place";
                } else if (c.a == top_call) {
                    cause = .unknown;
                    detail = "it came from a call of a function the checker cannot identify, which may return a list something else holds";
                } else if (c.a == top_several) {
                    cause = .unknown;
                    detail = "it came from a call of a function value that may be one of several functions, and the checker does not join what each returns";
                } else if (c.a == twice_named) {
                    cause = .unknown;
                    detail = "a schema answered it whose conversion returns one list at two places, so two parts of the answer may be one list";
                } else {
                    cause = .unknown;
                    detail = if (spec.fields != null) "the record came from JavaScript" else "the list came from JavaScript";
                },
                .shared => {
                    cause = .top_level;
                    const b = w.o.in.birs[c.a];
                    detail = try std.fmt.allocPrint(out, "{s}.{s} is a top-level value", .{ w.o.in.module_names[c.a], w.o.in.interner.slice(b.symbol(b.decls[c.b].name)) });
                },
                // §23.6: a message's payload is owned — every send gave it
                // up where it was made (§23.2) — so the cell `msg` is no
                // cause; what a view event builds is `payload_from`'s.
                .payload => if (spec.payload_from.len > 0) {
                    cause = .payload;
                    detail = view_event_detail;
                },
                // A write of a capture: the closure is once, and its creation
                // and calls decide the write (§18.8).
                // A record's too (§31.4 item 4).
                .env => if (spec.kind != .probe and w.frameClosure(w.frame) != null) {
                    rec.once_ci = w.frameClosure(w.frame).?;
                } else {
                    cause = .captured_edit;
                    detail = try std.fmt.allocPrint(out, "{s} is captured, and how often the closure runs is not known", .{w.localName(c.a)});
                },
                .cbres => if (w.callbackFrame(c) != 0) {
                    cause = .unknown;
                    detail = "it came from a call of a function the checker cannot identify, which may return a list something else holds";
                },
                .site, .param, .result, .closure, .func, .taken, .except => {},
            }
            // A real escape names itself before §18.6's conservative one.
            var esc = try w.escapeBefore(e.cell);
            // §31.2: a record demand on a whole record's cell is a demand on
            // its object, which escapes on its own (the object alone, an
            // `except` cell over it) where a capture or a result keeps it.
            if (spec.fields != null) {
                const k = w.cells.items[base].kind;
                if (k != .site and k != .top and k != .closure and k != .func and k != .except) {
                    const obj = try w.escapeBefore(try w.exceptCell(base, &.{}, true));
                    esc.gen = @min(esc.gen, obj.gen);
                    if (obj.js < esc.js) {
                        esc.js = obj.js;
                        esc.why = obj.why;
                    }
                }
            }
            if (esc.gen < w.point or esc.js < w.point) if (cause == null or @backingInt(Cause.escaped) < @backingInt(cause.?)) {
                cause = .escaped;
                detail = if (spec.entry and esc.gen >= w.point)
                    "a function the runtime calls hands a function value that captured it to JavaScript, which is taken to keep it (§18.6, §20.4)"
                else if (spec.entry)
                    "at some message the runtime keeps it: a command or a subscription holds it, or update escapes it (§20.4)"
                else if (esc.gen < w.point)
                    "it was given to JavaScript, or kept by a callee"
                else
                    try std.fmt.allocPrint(out, "a function value that {s} hands to JavaScript captured it, and JavaScript is taken to keep it (§18.6)", .{try w.callName(@fromBackingInt(esc.why - 1))});
            };
            if (cause) |cs| if (worst == null or @backingInt(cs) < @backingInt(worst.?)) {
                worst = cs;
                worst_detail = detail;
                worst_approx = null;
                worst_top = if (cs == .top_level) .{ c.a, c.b, @intFromBool(c.path == eps) } else null;
            };
        }
        rec.top = worst_top;
        if (spec.xfail) |r| {
            rec.xfail = r;
            rec.xdetail = if (spec.fields != null) "the callee needs the list's elements to hold no record at two positions, and they may" else "the callee needs the list's elements not to share, and they may";
        }
        if (worst) |cs| {
            rec.prelim = .{ .cause = cs, .detail = worst_detail, .approx = worst_approx };
            try w.demands.append(w.a, rec);
            return;
        }
        // A walk for a summary needs a line's cells, not its verdict, unless
        // the split may rely on its scrutinee (§18.4 item 4, §18.11).
        if (w.mode != .report and spec.kind != .probe and spec.kind != .creation and
            (rec.base_local == none or rec.base_local >= w.pat_site.len or w.pat_site[rec.base_local] == null))
        {
            try w.demands.append(w.a, rec);
            return;
        }
        // §20.5: a message a view builds from the model may hold the cell.
        if (spec.payload_from.len > 0 and (if (spec.payload_index) |pi| try w.reachesIndexed(pi, none, cells.items) else try w.reaches(spec.payload_from, cells.items)) != null) {
            rec.prelim = .{ .cause = .payload, .detail = view_event_detail, .approx = true };
            try w.demands.append(w.a, rec);
            return;
        }
        // Disjoint: another operand of the demand reaches the cell.
        var approx_hit: u32 = 0;
        const n_others = spec.others.len + @intFromBool(spec.rest_index != null);
        for (0..n_others) |oi| {
            if (comptime record_mutation == .no_disjoint) if (spec.fields != null) break;
            const hit = (if (spec.rest_index) |ri|
                (if (oi == 0) try w.reachesIndexed(ri, spec.rest_except, cells.items) else try w.reaches(spec.others[oi - 1], cells.items))
            else
                try w.reaches(spec.others[oi], cells.items)) orelse continue;
            if (hit.approx != 0) {
                if (approx_hit == 0 or hit.approx < approx_hit) approx_hit = hit.approx;
                continue;
            }
            rec.prelim = .{ .cause = .disjoint, .detail = "another operand of the same operation reaches it" };
            try w.demands.append(w.a, rec);
            return;
        }
        if (approx_hit != 0 and spec.entry) {
            // At an entry the other operands are the model's other paths,
            // as update's joined arms leave them (§20.4, §16.4 item 7).
            rec.prelim = .{ .cause = .disjoint, .detail = "another path of the model may hold it after some message: update's arms are joined, so the entry cannot tell them apart (§20.4)", .approx = true };
            try w.demands.append(w.a, rec);
            return;
        }
        if (approx_hit != 0 and debug_own) {
            std.debug.print("DEBUG demand cells:\n", .{});
            for (cells.items) |e| {
                const c = w.cells.items[e.cell];
                std.debug.print("  cell {d} kind={s} a={d} b={d} path={s} approx={d}\n", .{ e.cell, @tagName(c.kind), c.a, c.b, try w.o.pathText(c.path), e.approx });
            }
            for (spec.others, 0..) |av, oi| {
                std.debug.print(" other {d}:\n", .{oi});
                for (av) |e| {
                    const c = w.cells.items[e.cell];
                    std.debug.print("  at {s}: cell {d} kind={s} a={d} b={d} path={s} approx={d}\n", .{ try w.o.pathText(e.path), e.cell, @tagName(c.kind), c.a, c.b, try w.o.pathText(c.path), e.approx });
                }
            }
        }
        if (approx_hit == approx_level) {
            rec.prelim = .{ .cause = .level, .detail = "another operand may hold it at another level: the checker keeps one place for the levels of a recursive value" };
            try w.demands.append(w.a, rec);
            return;
        }
        if (approx_hit == approx_place) {
            rec.prelim = .{ .cause = .element, .detail = "another operand may hold it: one place of it stands for several: the levels of a recursive value, or the environments of closures inside closures" };
            try w.demands.append(w.a, rec);
            return;
        }
        if (approx_hit != 0) {
            rec.via = w.token(@fromBackingInt(@intCast(approx_hit - 1)));
            const cp = w.pos(rec.via);
            rec.prelim = .{ .cause = .call, .detail = try std.fmt.allocPrint(out, "another operand may be it, through the call at {d}:{d}", .{ cp.line, cp.col }) };
            try w.demands.append(w.a, rec);
            return;
        }
        // A temporary already evaluated for an enclosing consumer holds it.
        const base_pending = w.frames.items[w.frame].pending_base;
        for (w.pending.items[base_pending..]) |p| {
            if (comptime record_mutation == .no_held_operand) if (spec.fields != null) break;
            if (p.frame != w.frame or p.is_ref) continue;
            const phit = (try w.reaches(p.av, cells.items)) orelse continue;
            // Waiting for a call with a summary, it holds the cell only
            // where that call touches it (§16.4 item 2).
            if (p.consumer) |s| if (!w.touches(s, p.arg, phit.path)) continue;
            const ppos = w.pos(p.token);
            rec.via = p.token;
            // Held for a call with no summary, the temporary is a holder only
            // because the call is assumed to read it (§6.1): a limit.
            rec.prelim = if (phit.approx != 0 or (p.by_call and p.consumer == null))
                .{ .cause = .call, .detail = try std.fmt.allocPrint(out, "the argument at {d}:{d}, evaluated before it, holds it, and the call it waits for may read it", .{ ppos.line, ppos.col }) }
            else
                .{ .cause = .held_operand, .detail = try std.fmt.allocPrint(out, "the value at {d}:{d}, evaluated before it, holds it until its consumer runs", .{ ppos.line, ppos.col }) };
            try w.demands.append(w.a, rec);
            return;
        }
        // The holders, resolved against later uses once the walk is done.
        var holders: std.ArrayList(Holder) = .empty;
        for (try w.holderLocals()) |l| {
            const av = w.local_av[l].?;
            for (try w.expand(av)) |e| {
                // §16.4's keep edge, in the callee (#281): a callback's
                // result may keep what the call handed it. A list made here
                // and handed on is written after while that result lives;
                // no caller sees the write, so it is a holder here,
                // approximately. A parameter's cells are the caller's
                // question (`callbackKeeps`).
                const ec = w.cells.items[e.cell];
                if (ec.kind == .cbres) if (w.instCol(?AV, w.cb_args, ec.b, null)) |handed| {
                    for (cells.items) |c| {
                        const cc = w.cells.items[c.cell];
                        if (cc.kind == .param and cc.b == 0) continue;
                        if ((try w.reaches(handed, &.{.{ .path = eps, .cell = c.cell }})) == null) continue;
                        try holders.append(w.a, .{ .local = @intCast(l), .path = e.path, .approx = ec.b + 1 });
                        break;
                    }
                };
                for (cells.items) |c| {
                    var split = false;
                    const cv = (try w.coversAt(e.cell, c.cell)) orelse blk: {
                        const b = (try w.splitBase(c.cell, @intCast(l))) orelse continue;
                        split = true;
                        break :blk (try w.coversAt(e.cell, b)) orelse continue;
                    };
                    try holders.append(w.a, .{
                        .local = @intCast(l),
                        .path = try w.o.concat(e.path, cv.rest),
                        .approx = if (e.approx != 0) e.approx else if (c.approx != 0) c.approx else if (cv.approx) approx_place else 0,
                        .split = split,
                        .level = !split and e.cell == c.cell and w.standsForLevels(c.cell),
                    });
                }
            }
        }
        // A capture: the captured local itself, read again in this frame
        // after the demand (§18.8: the closure's own later reads of what it
        // gave up, as a send's payload, §23.7).
        for (cells.items) |e| {
            const x = w.cells.items[try w.takenBase(e.cell)];
            if (x.kind != .env or x.a >= w.local_frame.len or w.local_frame[x.a] == w.frame) continue;
            try holders.append(w.a, .{ .local = x.a, .path = x.path, .approx = e.approx });
        }
        rec.holders = try holders.toOwnedSlice(w.a);
        try w.demands.append(w.a, rec);
    }

    /// The locals a demand here may find a holder among: bound, in this
    /// frame, in a compatible branch, in index order. Read off `bound_log`,
    /// which leaves out the earlier arms of the cases the walk is in, so a
    /// `case` over a wide model costs each arm its own locals (#716).
    fn holderLocals(w: *Walker) Allocator.Error![]const u32 {
        // One buffer for every demand: nothing the holders' loop calls asks
        // for them again.
        const out = &w.holder_buf;
        out.clearRetainingCapacity();
        if (!w.logs_bindings) {
            for (w.local_av, 0..) |maybe, l| {
                if (maybe == null or w.local_frame[l] != w.frame or !w.compatible(w.local_ctx[l], w.ctx)) continue;
                try out.append(w.a, @intCast(l));
            }
            return out.items;
        }
        for (w.bound_log.items) |l| {
            if (w.local_av[l] == null or w.local_frame[l] != w.frame) continue;
            if (!w.compatible(w.local_ctx[l], w.ctx)) continue;
            try out.append(w.a, l);
        }
        // Binding order is mostly index order already.
        if (!std.sort.isSorted(u32, out.items, {}, std.sort.asc(u32))) std.mem.sort(u32, out.items, {}, std.sort.asc(u32));
        var n: usize = 0;
        for (out.items) |l| {
            if (n > 0 and out.items[n - 1] == l) continue;
            out.items[n] = l;
            n += 1;
        }
        const got = out.items[0..n];
        if (std.debug.runtime_safety and @import("ownership_options").full_cross_check) {
            var k: usize = 0;
            for (w.local_av, 0..) |maybe, l| {
                if (maybe == null or w.local_frame[l] != w.frame or !w.compatible(w.local_ctx[l], w.ctx)) continue;
                std.debug.assert(k < got.len and got[k] == l);
                k += 1;
            }
            std.debug.assert(k == got.len);
        }
        return got;
    }

    /// For an element a list pattern split off (§18.4 item 4), the element
    /// cell it stands for, which every holder but the pattern's own other
    /// bindings (`l` one of them: none) still holds.
    fn splitBase(w: *Walker, c: u32, l: u32) Allocator.Error!?u32 {
        const x = w.cells.items[c];
        if (x.kind != .taken) return null;
        const list = w.instCol(u32, w.split_list, x.b, none);
        if (list == none) return null;
        if (l != none and l < w.pat_site.len) if (w.pat_site[l]) |s| if (s.list.int() == list) return null;
        return try w.takenBase(c);
    }

    /// The callee of the call at `inst`, as written.
    fn callName(w: *Walker, inst: Inst.Index) Allocator.Error![]const u8 {
        const tag = w.bir.instTag(inst);
        if (tag == .call) {
            const callee: Inst.Index = @fromBackingInt(@intCast(w.bir.instData(inst).lhs));
            if (w.valueTarget(callee)) |t| return w.qualified(t);
            return "a function value";
        }
        if (tag == .method_call) {
            if (w.methodTarget(inst)) |t| return w.qualified(t);
            return "a method";
        }
        return "an operation";
    }

    fn localName(w: *const Walker, l: u32) []const u8 {
        const at = w.decl.locals_start + l;
        if (at >= w.bir.locals.len) return "_";
        const name = w.bir.locals[at].name.unwrap() orelse return "_";
        return w.o.in.interner.slice(w.bir.symbols[name]);
    }

    /// Where local `l` is bound: the token of the instruction that binds it
    /// (§28.6), `none` for a compiler-made local.
    fn localToken(w: *const Walker, l: u32) u32 {
        const at = w.decl.locals_start + l;
        if (at >= w.bir.locals.len) return none;
        const local = w.bir.locals[at];
        if (local.name.unwrap() == null) return none;
        if (w.bir.instTag(local.inst) != .let_def) {
            // A record pattern's binding carries the pattern's `{`: the
            // name is one of the identifiers after it.
            const tok = w.token(local.inst);
            const name = w.localName(l);
            const src = if (w.m < w.o.in.sources.len) w.o.in.sources[w.m] else return tok;
            const sp = w.o.in.spans[w.m];
            var k = tok;
            while (k < sp.tags.len and k < tok + 64) : (k += 1) {
                if (sp.tags[k] != .lower_ident) continue;
                const from = sp.starts[k];
                if (from + name.len > src.len or !std.mem.eql(u8, src[from..][0..name.len], name)) continue;
                const after = from + name.len;
                if (after < src.len and (std.ascii.isAlphanumeric(src[after]) or src[after] == '_')) continue;
                return k;
            }
            return tok;
        }
        // A `let_def` carries whatever token lowering met last; in a block
        // its name begins the line its `=` is on, before the value.
        const value: Inst.Index = @fromBackingInt(@intCast(w.bir.instData(local.inst).rhs));
        const lo = if (w.spanOf(value)) |s| s[0] else w.token(value);
        const tags = w.o.in.spans[w.m].tags;
        var k = lo;
        var guard: u32 = 0;
        while (k > 0 and tags[k - 1] != .equal and guard < 256) : (guard += 1) k -= 1;
        if (k == 0 or tags[k - 1] != .equal) return none;
        const line = w.pos(k - 1).line;
        var first = k - 1;
        while (first > 0 and w.pos(first - 1).line == line) first -= 1;
        return first;
    }

    fn baseText(w: *Walker, inst: Inst.Index) Allocator.Error![]const u8 {
        const out = w.o.out.allocator();
        var buf: std.Io.Writer.Allocating = .init(out);
        if (try w.writeExpr(&buf.writer, inst)) return buf.toOwnedSlice();
        buf.deinit();
        switch (w.bir.instTag(inst)) {
            .list => return "<literal>",
            .lambda => return "<lambda>",
            .record, .record_update => return "<record>",
            .tuple => return "<tuple>",
            .call => {
                if (w.isSpreadCall(inst)) return "<construction>";
                if (w.isListAppend(inst)) return "<++>";
                const callee: Inst.Index = @fromBackingInt(@intCast(w.bir.instData(inst).lhs));
                if (w.ctorName(callee)) |n| return std.fmt.allocPrint(out, "<{s} …>", .{n});
                if (w.valueTarget(callee)) |t| {
                    return std.fmt.allocPrint(out, "<call {s}.{s}>", .{ w.o.in.module_names[t.m], w.targetName(t) });
                }
                return "<call>";
            },
            .method_call => return "<call>",
            else => return w.ctorName(inst) orelse "<expression>",
        }
    }

    /// A constructor's name, as written.
    fn ctorName(w: *const Walker, inst: Inst.Index) ?[]const u8 {
        const data = w.bir.instData(inst);
        const m: u32, const i: u32 = switch (w.bir.instTag(inst)) {
            .ctor => .{ w.m, data.lhs },
            .ext_ctor => .{ data.lhs, if (data.lhs < w.o.in.provenance.len) w.o.in.provenance[data.lhs].ctorIndex(data.rhs) orelse return null else return null },
            else => return null,
        };
        if (m >= w.o.in.birs.len) return null;
        const bir = w.o.in.birs[m];
        if (i >= bir.ctors.len) return null;
        return w.o.in.interner.slice(bir.symbol(bir.ctors[i].name));
    }

    /// A variable or top-level value with a field path, as written.
    fn writeExpr(w: *Walker, wr: *std.Io.Writer, inst: Inst.Index) Allocator.Error!bool {
        const data = w.bir.instData(inst);
        switch (w.bir.instTag(inst)) {
            .local => wr.writeAll(w.localName(data.lhs)) catch return error.OutOfMemory,
            .top, .ext_value => {
                const t = w.valueTarget(inst) orelse return false;
                wr.print("{s}.{s}", .{ w.o.in.module_names[t.m], w.targetName(t) }) catch return error.OutOfMemory;
            },
            .field_access => {
                if (!try w.writeExpr(wr, @fromBackingInt(@intCast(data.lhs)))) return false;
                wr.print(".{s}", .{w.o.in.interner.slice(w.bir.symbol(@fromBackingInt(@intCast(data.rhs))))}) catch return error.OutOfMemory;
            },
            .tuple_index => {
                if (!try w.writeExpr(wr, @fromBackingInt(@intCast(data.lhs)))) return false;
                wr.print(".{d}", .{data.rhs}) catch return error.OutOfMemory;
            },
            // A schema's member as the source writes it (`Fixed.parse`).
            .schema_member_top, .ext_schema_member => {
                const r = w.schemaMemberOf(inst) orelse return false;
                const member: []const u8 = switch (r.kind) {
                    .parse => "parse",
                    .print => "print",
                    .parse_with => "parseWith",
                    .print_with => "printWith",
                    .schema => "schema",
                    .type, .encoded => return false,
                };
                const b = w.o.in.birs[r.m];
                wr.print("{s}.{s}.{s}", .{ w.o.in.module_names[r.m], w.o.in.interner.slice(b.symbol(b.decls[r.decl].name)), member }) catch return error.OutOfMemory;
            },
            else => return false,
        }
        return true;
    }

    /// The closure and position of a lambda's parameter cell.
    fn lambdaParam(w: *const Walker, c: Cell) ?[2]u32 {
        if (c.kind != .param or c.b != 1) return null;
        const at = c.a -% w.decl.inst_start.int();
        if (at >= w.pat_closure.len or w.pat_closure[at][0] == none) return null;
        return w.pat_closure[at];
    }

    /// Liveness, once every use is known (§7, §8.3); and the lambdas'
    /// demands on their own parameters, once every lambda's consumers are
    /// known (§16.5).
    fn resolve(w: *Walker, out_list: *std.ArrayList(Demand)) Allocator.Error!void {
        const out = w.o.out.allocator();
        try w.undischargedNeeds();
        // The uses by local, so that a holder's later uses are found
        // without a scan of every use (§18.11).
        const n = w.local_av.len;
        const start = try w.a.alloc(u32, n + 2);
        @memset(start, 0);
        for (w.uses.items) |u| if (u.local < n) {
            start[u.local + 2] += 1;
        };
        for (2..n + 2) |i| start[i] += start[i - 1];
        const order = try w.a.alloc(u32, start[n + 1]);
        for (w.uses.items, 0..) |u, ui| if (u.local < n) {
            order[start[u.local + 1]] = @intCast(ui);
            start[u.local + 1] += 1;
        };
        w.use_start = start[0 .. n + 1];
        w.use_order = order;
        // Made when a demand first needs it (`callRunEnd`).
        w.use_run_end = &.{};
        // Probes and creations first: a once closure's writes read them —
        // last made first, so that a creation inside a once lambda reads the
        // probes of the lambda's own creation and calls, made after it.
        var i = w.demands.items.len;
        while (i > 0) {
            i -= 1;
            const rec = w.demands.items[i];
            if (rec.kind != .probe and rec.kind != .creation) continue;
            const verdict = try w.resolveOne(rec);
            w.probe_ok.items[rec.probe] = verdict.verdict != .rejected and verdict.verdict != .pending;
            w.probe_approx.items[rec.probe] = verdict.verdict != .rejected or verdict.approx;
            w.probe_info.items[rec.probe] = verdict;
        }
        for (w.demands.items) |rec| {
            if (rec.kind == .probe or rec.kind == .creation) continue;
            // A walk for a summary prints nothing: a line's verdict matters
            // only where the split may rely on an exclusive scrutinee
            // (§18.4 item 4), which a summary records (§18.11).
            if (w.mode != .report and (rec.base_local == none or rec.base_local >= w.pat_site.len or w.pat_site[rec.base_local] == null)) continue;
            const verdict = try w.resolveOne(rec);
            if (w.mode != .report) continue;
            try out_list.append(out, verdict);
            if (rec.fields != null and rec.inst != none and verdict.verdict == .accepted) try w.publishDemand(rec);
        }
    }

    /// Where the run of uses at position `k` of `use_order` ends: the
    /// local's uses before `to` after it at its point, of one call, with
    /// its token. Each run is walked once per resolve.
    fn callRunEnd(w: *Walker, to: u32, k: u32) Allocator.Error!u32 {
        if (w.use_run_end.len == 0) {
            w.use_run_end = try w.a.alloc(u32, w.use_order.len);
            @memset(w.use_run_end, 0);
        }
        if (w.use_run_end[k] != 0) return w.use_run_end[k];
        const u = w.uses.items[w.use_order[k]];
        var e = k + 1;
        while (e < to) : (e += 1) {
            const v = w.uses.items[w.use_order[e]];
            if (v.call == 0 or v.point != u.point or v.token != u.token) break;
        }
        for (k..e) |i| w.use_run_end[i] = e;
        return e;
    }

    fn hoistName(w: *Walker, symbol: u32) Allocator.Error!u32 {
        const start: u32 = @intCast(w.hoist_table.names.items.len);
        try w.hoist_table.names.appendSlice(w.a, w.o.in.interner.slice(@fromBackingInt(symbol)));
        try w.hoist_table.names.append(w.a, 0);
        return start;
    }

    fn parentOf(w: *const Walker, inst: u32) u32 {
        const i = inst -% w.decl.inst_start.int();
        return if (i < w.inst_parent.len) w.inst_parent[i] else none;
    }

    /// A read in the same or a nested branch is dominated by the write.
    /// Otherwise lift it to the statement containing the divergent branch.
    fn placement(w: *const Walker, rec: DemandRec, u: Use) u32 {
        var ctx = u.ctx;
        while (ctx != none) : (ctx = w.ctx_nodes.items[ctx].parent) {
            if (ctx == rec.ctx) return rec.inst;
        }
        const read = if (u.capture != none) u.capture else u.read_inst;
        var d = rec.inst;
        while (d != none) : (d = w.parentOf(d)) {
            const parent = w.parentOf(d);
            var r = read;
            while (r != none) : (r = w.parentOf(r)) if (r == parent) return d;
        }
        unreachable; // both accesses are in one frame (§31.14)
    }

    fn publishDemand(w: *Walker, rec: DemandRec) Allocator.Error!void {
        const fields = try w.a.dupe(u32, rec.fields.?);
        std.mem.sort(u32, fields, w.o.in.interner, struct {
            fn less(pool: *const InternPool.Global, x: u32, y: u32) bool {
                return std.mem.lessThan(u8, pool.slice(@fromBackingInt(x)), pool.slice(@fromBackingInt(y)));
            }
        }.less);
        const start: u32 = @intCast(w.hoist_table.fields.items.len);
        for (fields) |f| try w.hoist_table.fields.append(w.a, try w.hoistName(f));
        try w.hoist_table.demands.append(w.a, .{ .decl = w.decl_index, .inst = rec.inst, .fields_start = start, .fields_len = @intCast(fields.len) });
        for (w.hoist_uses.items) |h| {
            // These controls invent hoists for whole uses, which have no
            // source field read to publish. Their verdicts still change.
            if (comptime record_mutation == .hoist_whole or record_mutation == .call_as_hoist) {
                if (h.use.read_inst == none) continue;
            }
            const at = if (comptime record_mutation == .wrong_placement) h.use.read_inst else w.placement(rec, h.use);
            const phase: u32 = if (at == rec.inst and w.bir.instTag(@fromBackingInt(rec.inst)) == .record_update) 1 else 0;
            try w.publishRead(h.use, rec.inst, at, phase, h.prefix);
        }
    }

    /// Copy the exact source path, independently of ownership's path domain.
    fn publishRead(w: *Walker, u: Use, demand: u32, at: u32, phase: u32, prefix: u32) Allocator.Error!void {
        if (u.read_inst == none) unreachable;
        var path: std.ArrayList(Hoists.Step) = .empty;
        if (u.pattern_field != none) try path.append(w.a, .{ .kind = 0, .arg = try w.hoistName(u.pattern_field) });
        var inst: Inst.Index = @fromBackingInt(u.read_inst);
        while (true) {
            const d = w.bir.instData(inst);
            switch (w.bir.instTag(inst)) {
                .field_access, .tuple_index => |tag| {
                    try path.append(w.a, .{ .kind = if (tag == .field_access) 0 else 1, .arg = if (tag == .field_access) try w.hoistName(@backingInt(w.bir.symbols[d.rhs])) else d.rhs });
                    inst = @fromBackingInt(@intCast(d.lhs));
                },
                .local => break,
                else => unreachable, // recordRead only records a variable path
            }
        }
        std.mem.reverse(Hoists.Step, path.items);
        const n: u32 = @intCast(path.items.len);
        const pre = if (prefix == none) n else prefix;
        std.debug.assert(pre > 0 and pre <= n);
        // One source read invalidated twice keeps the first write's placement.
        const entry = try w.hoist_read_index.getOrPut(w.a, .{ u.read_inst, u.binding, u.capture, pre });
        if (entry.found_existing) {
            const r = &w.hoist_table.reads.items[entry.value_ptr.*];
            if (r.demand == none and demand != none) {
                r.demand = demand;
                r.placement = at;
                r.phase = phase;
                r.prefix_len = pre;
            }
            return;
        }
        entry.value_ptr.* = @intCast(w.hoist_table.reads.items.len);
        const start: u32 = @intCast(w.hoist_table.paths.items.len);
        try w.hoist_table.paths.appendSlice(w.a, path.items);
        try w.hoist_table.reads.append(w.a, .{ .decl = w.decl_index, .demand = demand, .inst = u.read_inst, .holder = u.local, .binding = u.binding, .path_start = start, .path_len = n, .prefix_len = pre, .placement = at, .phase = phase, .capture = u.capture });
    }

    fn resolveOne(w: *Walker, rec: DemandRec) Allocator.Error!Demand {
        w.hoist_uses.clearRetainingCapacity();
        var d = try w.resolveRaw(rec);
        // §31.12: a record rejection's fix — a top-level base is made a
        // function, anything else copies.
        if (d.record and d.verdict == .rejected) d.fix = if (d.verdict.rejected == .top_level) .restructure else .copy;
        // A record base with no cell at all is one no provenance names: not
        // a verdict.
        if (d.record and d.verdict == .accepted and rec.cells.len == 0) {
            d.verdict = .pending;
            d.detail = "no provenance names where its base's object comes from";
            d.note = "";
        }
        if (d.verdict == .rejected) d.hoists = 0;
        if (d.verdict == .rejected) switch (rec.origin) {
            .exact => {},
            // A write only a pessimistic summary claims (§16.7).
            .limit => {
                d.detail = try std.fmt.allocPrint(w.o.out.allocator(), "{s}; the callee's summary is past the checker's limits, so it is taken to write and keep its arguments", .{d.detail});
                d.verdict = .{ .rejected = .limit };
                d.approx = true;
            },
            // A write the callee makes only through an approximate step.
            .approx => if (!d.verdict.rejected.approximate()) {
                d.detail = try std.fmt.allocPrint(w.o.out.allocator(), "{s}; the callee writes it only through an approximate step", .{d.detail});
                d.verdict = .{ .rejected = .call };
                d.approx = true;
            },
        };
        // §20.6: the entry's acceptance is its row's.
        if (rec.entry and d.verdict == .accepted and rec.accept != .param) {
            d.verdict = .{ .accepted = .entry };
        }
        return d;
    }

    fn resolveRaw(w: *Walker, rec: DemandRec) Allocator.Error!Demand {
        const out = w.o.out.allocator();
        const position = w.pos(rec.token);
        var d: Demand = .{
            .position = position,
            .op = rec.op,
            .base = rec.base,
            .verdict = .{ .accepted = rec.accept },
            .detail = "",
            .note = rec.note,
            .token = rec.token,
            .span = rec.span,
            .base_span = rec.base_span,
            .top = rec.top,
            .via_token = rec.via,
            .record = rec.fields != null,
        };
        if (rec.accept == .call and rec.assumed.len > 0) {
            d.assumed = true;
            d.note = try std.fmt.allocPrint(out, "no summary: {s}", .{rec.assumed});
        }
        if (rec.fixed) |f| {
            d.verdict = f.verdict;
            d.detail = f.detail;
            d.assumed = f.assumed;
            if (f.verdict == .rejected) d.approx = if (rec.prelim) |p| (p.approx orelse f.verdict.rejected.approximate()) else f.verdict.rejected.approximate();
            return d;
        }
        if (rec.prelim) |p| {
            d.verdict = .{ .rejected = p.cause };
            d.detail = p.detail;
            d.approx = p.approx orelse p.cause.approximate();
            d.assumed = false;
            return d;
        }
        // Each holder's first later use in a compatible branch.
        // §31.14: the hoists, one per use, whatever number of the uses'
        // holders reach it (a local holding the object at two paths).
        var hoisted: std.ArrayList(u32) = .empty;
        var best: ?struct { cause: Cause, holder: Holder, use: Use } = null;
        for (rec.holders) |h| {
            var first: ?Use = null;
            const range = if (h.local < w.use_start.len - 1) w.use_order[w.use_start[h.local]..w.use_start[h.local + 1]] else &[_]u32{};
            // The uses are in the order they were recorded, so by point:
            // those before the demand's are skipped by a search, and a run
            // in the other arms of a case the demand is in, by one more
            // (#716). Both are uses the filters below drop.
            var ri: usize = firstAtLeast(range, w.uses.items, rec.point);
            while (ri < range.len) : (ri += 1) {
                const ui = range[ri];
                const u = w.uses.items[ui];
                if (ui >= rec.use_mark) if (w.divergentCase(u.ctx, rec.ctx)) |k| if (k < w.case_end.items.len and w.case_end.items[k] != none) {
                    const end = w.case_end.items[k];
                    if (std.debug.runtime_safety and @import("ownership_options").full_cross_check) {
                        for (range[ri..]) |vi| {
                            if (vi >= end) break;
                            std.debug.assert(!w.compatible(w.uses.items[vi].ctx, rec.ctx));
                        }
                    }
                    ri += std.sort.partitionPoint(u32, range[ri..], end, struct {
                        fn before(e: u32, x: u32) bool {
                            return x < e;
                        }
                    }.before);
                    ri -= 1;
                    continue;
                };
                // A call's own uses, one per path its callee reads, are one
                // run: at this call, none is a later use (below).
                if (rec.kind == .callsite and rec.fields != null and u.point == rec.point and u.call != 0 and u.token == rec.token) {
                    ri = try w.callRunEnd(w.use_start[h.local + 1], w.use_start[h.local] + @as(u32, @intCast(ri))) - w.use_start[h.local] - 1;
                    continue;
                }
                // A field read is recorded where it is evaluated, at no point of
                // its own: one at the demand's point comes after the demand, whose
                // own operands were read before it.
                if (u.local != h.local or u.frame != rec.frame or u.point < rec.point or (u.point == rec.point and !u.record_read)) continue;
                if (rec.creation_ci != none and u.via == rec.creation_ci) continue;
                if (!w.compatible(u.ctx, rec.ctx)) continue;
                if (u.record_read and rec.fields == null) continue;
                // §31.7: a callee's write at a call is ordered against its own
                // reads in its own body, by its own demand; at the call they
                // are one point, and not a later use. Only this call's own
                // uses: the same point and the same token. A nested call, as
                // `g r` in `f (g r) r`, is a point of its own, before. Two
                // arguments that hold one record are the call's Disjoint
                // (`others`), which the callee cannot order: it does not
                // know its parameters alias.
                if (rec.kind == .callsite and rec.fields != null and u.point == rec.point and u.call != 0 and u.token == rec.token) continue;
                if (rec.fields) |fs| switch (w.recordUse(u, h.path, fs)) {
                    .none => continue,
                    // §31.14: a read of a written field, which the lowering
                    // reads before the write.
                    // §31.4 item 4: after a once closure's creation, the write
                    // happens at a call the lowering cannot place before the
                    // read, so a read of a written field is a whole use.
                    .hoist => if (rec.kind != .creation) {
                        try hoisted.append(w.a, ui);
                        const prefix: u32 = @intCast(w.o.steps(h.path).len + 1);
                        try w.hoist_uses.append(w.a, .{ .use = u, .prefix = prefix });
                        continue;
                    },
                    .whole => {},
                } else if (!w.useOverlaps(u, h.path)) continue;
                if (first == null or u.point < first.?.point) first = u;
            }
            const u = first orelse continue;
            // §18.4 item 4, the split: another binding of the same list
            // pattern holds another position, apart when the scrutinee's
            // contents are exclusive.
            if (try w.splitSibling(rec, h)) continue;
            // §31.4 item 5: a call with no summary reads the record whole,
            // which is a limit of the checker.
            const cause: Cause = if (h.approx == approx_place)
                .element
            else if (h.approx == approx_level)
                .level
            else if (h.approx != 0 or (rec.fields != null and u.call == 2))
                .call
            else if (h.local == rec.base_local and w.o.overlap(h.path, rec.base_path) and !w.o.hasStep(h.path, .env))
                .later_use
            else if (h.level)
                .level
            else if (h.split)
                .alias
            else if (rec.element and try w.o.representative(h.path))
                .element
            else if (w.o.hasStep(h.path, .env))
                .captured
            else if (h.local == rec.base_local and w.o.overlap(h.path, rec.base_path))
                .later_use
            else
                .alias;
            if (best) |bst| {
                const better_kind = cause.approximate() != bst.cause.approximate() and !cause.approximate();
                const same_kind = cause.approximate() == bst.cause.approximate();
                if (!(better_kind or (same_kind and (u.point < bst.use.point or (u.point == bst.use.point and w.holderBefore(h, bst.holder)))))) continue;
            }
            best = .{ .cause = cause, .holder = h, .use = u };
        }
        std.mem.sort(u32, hoisted.items, {}, std.sort.asc(u32));
        for (hoisted.items, 0..) |ui, i| {
            if (i == 0 or hoisted.items[i - 1] != ui) d.hoists += 1;
        }
        if (best) |bst| {
            const up = w.pos(bst.use.token);
            var buf: std.Io.Writer.Allocating = .init(out);
            const wr = &buf.writer;
            wr.writeAll(w.localName(bst.holder.local)) catch return error.OutOfMemory;
            if (bst.cause != .captured) w.o.writePath(wr, bst.holder.path) catch return error.OutOfMemory;
            // §28.6: the holder, where it was bound, and the read.
            d.holder = try out.dupe(u8, buf.written());
            d.keep_token = w.localToken(bst.holder.local);
            d.read_span = if (bst.use.at[0] != none) bst.use.at else .{ bst.use.token, bst.use.token };
            // §31.4 item 5: a record handed whole to a call with no summary is
            // held through no call: the read is the call's own.
            const whole_call = bst.cause == .call and bst.holder.approx == 0;
            if (bst.cause == .call) d.via_token = if (whole_call) bst.use.token else w.token(@fromBackingInt(@intCast(bst.holder.approx - 1)));
            switch (bst.cause) {
                .later_use => wr.print(" is read again at {d}:{d}", .{ up.line, up.col }) catch return error.OutOfMemory,
                .captured => wr.print(", a closure holding it, is used at {d}:{d}", .{ up.line, up.col }) catch return error.OutOfMemory,
                .level => wr.print(" may hold it at another level, and is read at {d}:{d}", .{ up.line, up.col }) catch return error.OutOfMemory,
                .call => if (whole_call) {
                    wr.print(" is handed whole at {d}:{d} to a call the checker cannot see into, which may read any field", .{ up.line, up.col }) catch return error.OutOfMemory;
                } else {
                    const call_inst: Inst.Index = @fromBackingInt(@intCast(bst.holder.approx - 1));
                    const cp = w.pos(w.token(call_inst));
                    wr.print(" may hold it through the call at {d}:{d}, and is read at {d}:{d}", .{ cp.line, cp.col, up.line, up.col }) catch return error.OutOfMemory;
                },
                else => wr.print(" holds it and is read at {d}:{d}", .{ up.line, up.col }) catch return error.OutOfMemory,
            }
            d.verdict = .{ .rejected = bst.cause };
            d.detail = try buf.toOwnedSlice();
            d.approx = bst.cause.approximate();
            d.assumed = false;
            return d;
        }
        // §18.4: exclusive contents the write needs and may not have.
        if (rec.xfail) |r| {
            // What a limit lowered follows from the limit (#233).
            d.verdict = .{ .rejected = if (r == .limit) .limit else .exclusive };
            d.detail = rec.xdetail;
            d.approx = r != .exact;
            d.assumed = false;
            return d;
        }
        // A write of a capture: what the once closure's creation and calls
        // decide (§18.8).
        if (rec.once_ci != none) return w.decideOnce(rec, d);
        // A lambda's demand on its own parameter: what its consumers decide.
        if (rec.accept == .callback_param) try w.decideCallback(rec, &d);
        return d;
    }

    fn decideOnce(w: *Walker, rec: DemandRec, d_in: Demand) Allocator.Error!Demand {
        var d = d_in;
        const cl = &w.closures.items[rec.once_ci];
        d.assumed = false;
        d.note = "";
        // Its creation fails exactly — a live holder of what it captured, the
        // model still holding a list a body sends (§23.7) — which names the
        // holder; then a place known to call it more than once rejects it,
        // wherever else it goes (a command's body, which may run again).
        for (cl.once_probes.items) |p| {
            // A record capture's creation decides a record's write alone.
            if (rec.fields == null and w.probe_record.items[p]) continue;
            const info = w.probe_info.items[p] orelse continue;
            if (info.verdict != .rejected or info.approx) continue;
            d.verdict = info.verdict;
            d.detail = info.detail;
            d.approx = false;
            return d;
        }
        if (cl.once_bad) |why| {
            d.verdict = .{ .rejected = .once };
            d.detail = why;
            d.approx = cl.once_bad_approx;
            return d;
        }
        // A pending consumption of its own goes before one that follows
        // from a limit, which would hide it (#272).
        for (cl.consumed.items) |c| if (c.kind == .pending and !c.limit) {
            d.verdict = .pending;
            d.detail = c.why;
            return d;
        };
        for (cl.consumed.items) |c| if (c.kind == .pending) {
            d.verdict = .{ .rejected = .limit };
            d.detail = c.why;
            d.approx = true;
            return d;
        };
        for (cl.consumed.items) |c| if (c.kind == .no_summary) {
            d.verdict = .{ .rejected = .once };
            d.detail = try std.fmt.allocPrint(w.o.out.allocator(), "it is handed to {s}, which has no summary and may call it more than once", .{c.name});
            d.approx = true;
            return d;
        };
        for (cl.once_probes.items) |p| {
            // A record capture's creation decides a record's write alone.
            if (rec.fields == null and w.probe_record.items[p]) continue;
            const info = w.probe_info.items[p] orelse continue;
            if (info.verdict == .accepted) continue;
            d.verdict = info.verdict;
            d.detail = info.detail;
            d.approx = info.approx;
            return d;
        }
        // A call of it is a demand on its own cell: a holder read after a
        // call is a second call (§18.8).
        for (cl.call_probes.items) |p| {
            const info = w.probe_info.items[p] orelse continue;
            if (info.verdict == .accepted) continue;
            d.verdict = .{ .rejected = .once };
            d.detail = try std.fmt.allocPrint(w.o.out.allocator(), "it may run more than once: {s}", .{info.detail});
            d.approx = info.approx;
            return d;
        }
        d.verdict = .{ .accepted = .once };
        return d;
    }

    fn decideCallback(w: *Walker, rec: DemandRec, d: *Demand) Allocator.Error!void {
        const out = w.o.out.allocator();
        var lp: ?[2]u32 = null;
        for (rec.cells) |e| {
            if (w.lambdaParam(w.cells.items[try w.takenBase(e.cell)])) |x| {
                lp = x;
                break;
            }
        }
        const x = lp orelse return;
        const cl = &w.closures.items[x[0]];
        // The worst consumer decides: pending, then rejected, then one that
        // follows from a limit, then a callee with no summary, then accepted.
        // A line of its own goes before a limit's, which would hide it (#272).
        var rank: u8 = 0;
        for (cl.consumed.items) |c| switch (c.kind) {
            .pending => if (rank < @as(u8, if (c.limit) 2 else 4)) {
                rank = if (c.limit) 2 else 4;
                d.verdict = if (c.limit) .{ .rejected = .limit } else .pending;
                d.detail = c.why;
                d.approx = c.limit;
                d.note = "";
                d.assumed = false;
            },
            .supply => if (d.record) {
                if (x[1] < c.rbad.len) if (c.rbad[x[1]]) |why| {
                    const cause: Cause = if (x[1] < c.rbad_cause.len) c.rbad_cause[x[1]] else .supply;
                    const r: u8 = if (cause == .limit) 2 else 3;
                    if (rank >= r) continue;
                    rank = r;
                    d.verdict = .{ .rejected = cause };
                    d.detail = why;
                    d.approx = c.rbad_approx[x[1]];
                    d.note = "";
                    d.assumed = false;
                    continue;
                };
                if (rank == 0) d.note = try std.fmt.allocPrint(out, "{s} supplies it owned", .{c.name});
            } else if (x[1] < c.bad.len) {
                if (c.bad[x[1]]) |why| {
                    const cause: Cause = if (x[1] < c.bad_cause.len) c.bad_cause[x[1]] else .supply;
                    const r: u8 = if (cause == .limit) 2 else 3;
                    if (rank >= r) continue;
                    rank = r;
                    d.verdict = .{ .rejected = cause };
                    d.detail = why;
                    d.approx = c.bad_approx[x[1]];
                    d.note = "";
                    d.assumed = false;
                } else if (rank == 0) {
                    d.note = try std.fmt.allocPrint(out, "{s} supplies it owned", .{c.name});
                }
            },
            .no_summary => if (rank < 1) {
                rank = 1;
                d.assumed = true;
                d.note = try std.fmt.allocPrint(out, "no summary: {s}", .{c.name});
            },
            .local => if (rank == 0 and d.note.len == 0) {
                d.note = "decided at its calls";
            },
        };
    }

    fn splitSibling(w: *Walker, rec: DemandRec, h: Holder) Allocator.Error!bool {
        if (rec.base_local == none or rec.base_local >= w.pat_site.len or h.local >= w.pat_site.len) return false;
        const b = w.pat_site[rec.base_local] orelse return false;
        const s = w.pat_site[h.local] orelse return false;
        if (b.list != s.list or b.index == s.index or b.spread) return false;
        return try w.rely(try w.deepCond(s.scrut), rec.frame) == .ok;
    }

    /// A tie-break between two holders read at one point that depends on the
    /// text alone — the local, then the path as written, then the call —
    /// never on an id, which other declarations' walks move.
    fn holderBefore(w: *const Walker, a: Holder, b: Holder) bool {
        if (a.local != b.local) return a.local < b.local;
        var ba: [256]u8 = undefined;
        var bb: [256]u8 = undefined;
        var wa: std.Io.Writer = .fixed(&ba);
        var wb: std.Io.Writer = .fixed(&bb);
        w.o.writePath(&wa, a.path) catch {};
        w.o.writePath(&wb, b.path) catch {};
        const o = std.mem.order(u8, wa.buffered(), wb.buffered());
        if (o != .eq) return o == .lt;
        return a.approx < b.approx;
    }

    const RecordUse = enum { none, hoist, whole };

    /// §31.4 item 5: what a later use `u` of a holder that holds the record
    /// object at `q` is to an update writing `fields`. A use at or above
    /// `q` uses the record whole — but an update's base use, which reads
    /// every field but its own, of a field it replaces. A use below `q`
    /// through a field the update did not write is untouched; through a
    /// written one it is the lowering's read of the old value, unless a
    /// callee makes it in its own body, where no temporary stands in.
    fn recordUse(w: *const Walker, u: Use, q: u32, fields: []const u32) RecordUse {
        if (u.destructure or u.reads_none) return .none;
        if (comptime record_mutation == .hoist_whole) {
            if (w.o.isPrefix(u.path, q)) return .hoist;
        }
        if (w.o.isPrefix(u.path, q)) {
            if (u.except.len != 0) {
                const su = w.o.steps(u.path);
                const sq = w.o.steps(q);
                if (sq.len > su.len) {
                    const next = sq[su.len];
                    if (next.kind == .field and std.mem.indexOfScalar(u32, u.except, next.arg) != null) return .none;
                }
            }
            return .whole;
        }
        if (!w.o.isPrefix(q, u.path)) return .none;
        const su = w.o.steps(u.path);
        const sq = w.o.steps(q);
        const next = su[sq.len];
        if (next.kind != .field) return .whole;
        // No field named is every field: a write a block could not name, an
        // open type's `allFields`, a probe of the record whole.
        if (fields.len != 0 and std.mem.indexOfScalar(u32, fields, next.arg) == null) return .none;
        // The step into the written field is the caller's own read when it is
        // part of the argument's path: `List.length r.items` reads `r.items`
        // here, a read its evaluation recorded (`recordRead`), and hands the
        // callee the list.
        if (u.call != 0) {
            if (comptime record_mutation == .call_as_hoist) return .hoist;
            return if (w.o.paths.depth.items[u.call_at] <= sq.len) .whole else .none;
        }
        // A consumer's use of a field path is the read its evaluation
        // recorded (`recordRead`): one hoist, counted once.
        return if (u.record_read) .hoist else .none;
    }

    fn useOverlaps(w: *const Walker, u: Use, path: u32) bool {
        if (u.except.len != 0 and u.path == eps) {
            const first = w.o.firstStep(path) orelse return true;
            if (first.kind == .field and std.mem.indexOfScalar(u32, u.except, first.arg) != null) return false;
            return true;
        }
        return w.o.overlap(u.path, path);
    }

    // ---- reading off (§16.3) -----------------------------------------------

    /// The declaration's summary, once the walk is resolved.
    fn readOff(w: *Walker) Allocator.Error!Summary {
        return w.readOffFrame(0, w.params, w.result_av);
    }

    /// The parameter index a cell is of, in frame `frame` whose parameters
    /// are `params`.
    fn paramIndex(_: *const Walker, c: Cell, frame: u32, params: []const Inst.Index) ?u32 {
        if (c.kind != .param) return null;
        if (frame == 0 and c.b != 0) return null;
        if (frame != 0 and c.b != 1) return null;
        for (params, 0..) |p, i| if (p.int() == c.a) return @intCast(i);
        return null;
    }

    fn readOffFrame(w: *Walker, frame: u32, params: []const Inst.Index, result: AV) Allocator.Error!Summary {
        const keep = w.o.keep.allocator();
        var uses: std.ArrayList(UseEntry) = .empty;
        // The fields of a record update's base not yet read off, by
        // parameter, path, kind of read and record type.
        var split_left: std.AutoHashMapUnmanaged([5]u64, []u32) = .empty;
        var read_shapes: std.HashMapUnmanaged([5]u32, void, WordsKey(5), std.hash_map.default_max_load_percentage) = .empty;
        // R: a use of a local whose value holds a parameter cell.
        for (w.uses.items) |u| {
            if (u.frame != frame) continue;
            // §31.4 item 5: a read only a record demand reads — a field path's
            // evaluation, a closure's use of a captured record object (which
            // crossed before §31.2), a use of a record's object alone — is
            // `bit_q`, the record demand's R, which no list's fact reads.
            var rec_use = u.record_read;
            if (u.via != none) if (w.cell_map.get(.{ @backingInt(CellKind.env), u.local, 0, u.path, 0 })) |ec| {
                if (w.cells.items[ec].nonlist) rec_use = true;
            };
            const held = w.local_av[u.local] orelse continue;
            if (u.except.len == 0) {
                const key: [5]u32 = .{ u.local, u.path, @intFromBool(rec_use), @truncate(u.grown), @truncate(u.grown >> 32) };
                if ((try read_shapes.getOrPut(w.a, key)).found_existing) continue;
            }
            for (held) |e| {
                const rec_only = rec_use or w.listFacing(e.cell) == null;
                const read_bit: u16 = if (rec_only) bit_q else bit_r;
                const c = w.cells.items[try w.takenBase(if (rec_only) (w.recordObject(e.cell) orelse e.cell) else e.cell)];
                const pi = w.paramIndex(c, frame, params) orelse continue;
                if (u.except.len != 0 and u.path == eps) {
                    if (w.o.firstStep(e.path)) |first| {
                        if (first.kind == .field and std.mem.indexOfScalar(u32, u.except, first.arg) != null) continue;
                    } else if (w.recordFields(w.localType(u.local))) |fields| {
                        // A record update reads every field but the ones it
                        // replaces (§5's split, §16.4 item 1). One field's
                        // entry is the same at every update of the same base,
                        // and normalizing merges the copies: each is read off
                        // once, at the first update that reads it, so a wide
                        // model's arms cost its width once (#716).
                        if (fields.len <= split_memo_min) {
                            for (fields) |fl| {
                                if (std.mem.indexOfScalar(u32, u.except, @backingInt(fl.name)) != null) continue;
                                if (!try w.trackedVar(fl.value)) continue;
                                const bit: u16 = if (rec_only or !try w.listTrackedVar(fl.value)) bit_q else bit_r;
                                try uses.append(keep, .{ .param = pi, .path = try w.o.child(c.path, .field, @backingInt(fl.name)), .bits = bit, .grown = gJoin(u.grown, e.grown) });
                            }
                            continue;
                        }
                        const gop = try split_left.getOrPut(w.a, .{ @as(u64, pi) | (@as(u64, @intFromBool(rec_only)) << 32), c.path, @intFromPtr(fields.ptr), fields.len, u.grown });
                        if (!gop.found_existing) {
                            const all = try w.a.alloc(u32, fields.len);
                            for (all, 0..) |*x, k| x.* = @intCast(k);
                            gop.value_ptr.* = all;
                        }
                        const left = gop.value_ptr.*;
                        var kept: usize = 0;
                        for (left) |k| {
                            const fl = fields[k];
                            if (std.mem.indexOfScalar(u32, u.except, @backingInt(fl.name)) != null) {
                                left[kept] = k;
                                kept += 1;
                                continue;
                            }
                            if (!try w.trackedVar(fl.value)) continue;
                            const bit: u16 = if (rec_only or !try w.listTrackedVar(fl.value)) bit_q else bit_r;
                            try uses.append(keep, .{ .param = pi, .path = try w.o.child(c.path, .field, @backingInt(fl.name)), .bits = bit, .grown = gJoin(u.grown, e.grown) });
                        }
                        gop.value_ptr.* = left[0..kept];
                        continue;
                    }
                } else if (!w.o.overlap(e.path, u.path)) continue;
                var path = c.path;
                if (try w.o.suffix(e.path, u.path)) |rest| path = try w.o.concat(path, rest);
                try uses.append(keep, .{ .param = pi, .path = path, .bits = read_bit, .grown = gJoin(u.grown, e.grown) });
            }
        }
        // W: a demand's cells, in this frame or, through a capture, inside
        // a lambda of it.
        for (w.demands.items) |rec| {
            if (rec.kind == .probe or rec.kind == .value) continue;
            // §31.7: a record demand's W carries the fields it writes.
            // Kept past the walk, whose arena owns the demand's.
            const fields: []const u32 = if (rec.fields) |fs| try keep.dupe(u32, fs) else &.{};
            const wbit: u16 = if (rec.fields != null) bit_f else bit_w;
            for (rec.cells) |e| {
                const c = w.cells.items[try w.takenBase(e.cell)];
                const deep: u16 = if (rec.deep) bit_d else 0;
                if (rec.frame == frame) {
                    if (w.paramIndex(c, frame, params)) |pi| try uses.append(keep, .{ .param = pi, .path = c.path, .bits = wbit | deep | (if (rec.fields == null and e.approx == 0 and rec.origin == .exact) bit_x else 0), .fields = fields, .extent = rec.extent, .grown = e.grown });
                }
                if (c.kind == .env and rec.frame != frame) {
                    const held = w.local_av[c.a] orelse continue;
                    if (c.a >= w.local_frame.len or w.local_frame[c.a] != frame) continue;
                    for (try w.projPath(held, c.path, null)) |h| {
                        if (h.path != eps) continue;
                        const hc = w.cells.items[h.cell];
                        if (w.paramIndex(hc, frame, params)) |pi| try uses.append(keep, .{ .param = pi, .path = hc.path, .bits = wbit | deep | (if (rec.fields == null and e.approx == 0 and h.approx == 0 and rec.origin == .exact) bit_x else 0), .fields = fields, .extent = rec.extent, .grown = e.grown });
                    }
                }
            }
        }
        // E: a parameter cell in Esc.
        for (w.escaped.items) |x| {
            // §31.4 item 2: a record object's escape is `bit_k`, the record
            // demand's E.
            const rec_only = w.listFacing(x.cell) == null;
            const c = w.cells.items[try w.takenBase(if (rec_only) (w.recordObject(x.cell) orelse x.cell) else x.cell)];
            if (w.paramIndex(c, frame, params)) |pi| try uses.append(keep, .{ .param = pi, .path = c.path, .bits = if (rec_only) bit_k else if (x.why != 0) bit_j else bit_e, .grown = x.grown });
        }
        // A and the result.
        const expanded = try w.listView(try w.expand(result));
        // The cells made here, each with the result paths it is at: the
        // pairs `(cell, key)` sorted, one run per cell, so the read-off
        // stays near-linear in the result (§16.3). A cell's runs keep the
        // order of its first entry, which breaks the ties of the order below.
        var made: std.ArrayList([3]u32) = .empty;
        for (expanded, 0..) |e, i| {
            const k = w.cells.items[e.cell].kind;
            if (k != .site and k != .result) continue;
            try made.append(w.a, .{ e.cell, e.path *% 2 +% @intFromBool(e.approx != 0), @intCast(i) });
        }
        std.mem.sort([3]u32, made.items, {}, struct {
            fn less(_: void, x: [3]u32, y: [3]u32) bool {
                if (x[0] != y[0]) return x[0] < y[0];
                return x[1] < y[1];
            }
        }.less);
        // Per fresh cell: its first entry and its run of keys.
        const Run = struct { cell: u32, first: u32, from: u32, to: u32 };
        var runs: std.ArrayList(Run) = .empty;
        for (made.items, 0..) |p, i| {
            if (i == 0 or made.items[i - 1][0] != p[0]) {
                try runs.append(w.a, .{ .cell = p[0], .first = p[2], .from = @intCast(i), .to = @intCast(i + 1) });
                continue;
            }
            const r = &runs.items[runs.items.len - 1];
            r.first = @min(r.first, p[2]);
            r.to = @intCast(i + 1);
        }
        std.mem.sort(Run, runs.items, w, struct {
            fn less(ww: *Walker, x: Run, y: Run) bool {
                const cx = ww.cells.items[x.cell];
                const cy = ww.cells.items[y.cell];
                if (cx.a != cy.a) return cx.a < cy.a;
                if (cx.b != cy.b) return cx.b < cy.b;
                if (cx.path != cy.path) return cx.path < cy.path;
                return x.first < y.first;
            }
        }.less);
        const fresh_cells = try w.a.alloc(u32, runs.items.len);
        const by_cell = try w.a.alloc([2]u32, runs.items.len);
        for (runs.items, fresh_cells, by_cell, 0..) |r, *fc, *bc, i| {
            fc.* = r.cell;
            bc.* = .{ r.cell, @intCast(i) };
        }
        std.mem.sort([2]u32, by_cell, {}, lessPair);
        const fresh: Fresh = .{ .cells = fresh_cells, .by_cell = by_cell };
        // A fresh number only says which result paths may hold one new
        // cell (thesis §3.7, §4.6: `k ≤ |Q|`), so cells that appear at the
        // same paths share a number; the numbering stays a function of the
        // result's shape, not of how many literals the body has.
        const renum = try w.a.alloc(u32, runs.items.len);
        var groups: std.HashMapUnmanaged([]const u32, u32, U32SliceContext, std.hash_map.default_max_load_percentage) = .empty;
        for (runs.items, renum) |r, *num| {
            var ps: std.ArrayList(u32) = .empty;
            for (made.items[r.from..r.to]) |p| {
                if (ps.items.len > 0 and ps.items[ps.items.len - 1] == p[1]) continue;
                try ps.append(w.a, p[1]);
            }
            const esc_bit: u32 = if (try w.isEscaped(r.cell)) 1 else 0;
            try ps.append(w.a, esc_bit);
            if (frame == 0 and w.recursive) {
                // §16.7 (d): a recursive member's number names its result
                // paths in every round, so the rounds' join never puts two
                // allocations that different rounds numbered alike at one
                // number (a root's list and its subtrees').
                num.* = try w.o.freshKey(w.m, w.decl_index, ps.items);
                continue;
            }
            const g = try groups.getOrPut(w.a, ps.items);
            if (!g.found_existing) g.value_ptr.* = @intCast(groups.count());
            num.* = g.value_ptr.*;
        }
        const spines = try w.spineIndex(expanded);
        var res: std.ArrayList(ResEntry) = .empty;
        var klasses: std.ArrayList(Carried) = .empty;
        for (expanded) |e| {
            // §24.9: a lambda the result holds keeps its class, when it is
            // one a caller can call with nothing but its result and reads.
            if (frame == 0 and w.cells.items[e.cell].kind == .closure and !w.o.hasStep(e.path, .env)) {
                if (try w.carried(w.cells.items[e.cell].a, params, fresh)) |k| {
                    try klasses.append(keep, k);
                    try res.append(keep, .{ .path = e.path, .prov = .{ .kind = .klass, .a = @intCast(klasses.items.len - 1) }, .approx = e.approx != 0, .grown = e.grown });
                } else {
                    // An unavailable class is unknown, never recursive bottom.
                    try res.append(keep, .{ .path = e.path, .prov = .{ .kind = .klass, .a = none }, .approx = e.approx != 0, .grown = e.grown });
                }
                continue;
            }
            if (!w.o.hasStep(e.path, .env) and (w.cells.items[e.cell].kind == .closure or w.cells.items[e.cell].kind == .func)) {
                try res.append(keep, .{ .path = e.path, .prov = .{ .kind = .klass, .a = none }, .approx = e.approx != 0, .grown = e.grown });
                continue;
            }
            const c = w.cells.items[try w.takenBase(e.cell)];
            const own = w.paramIndex(c, frame, params) != null;
            if (w.paramIndex(c, frame, params)) |pi| try uses.append(keep, .{ .param = pi, .path = c.path, .bits = bit_a, .grown = e.grown });
            var prov = (try w.provOf(e.cell, frame, params, fresh)) orelse continue;
            if ((prov.kind == .fresh or prov.kind == .esc) and prov.a > 0) prov.a = renum[prov.a - 1];
            prov.taken = false;
            // §18.3: the cell's condition, a parameter's own `excl` left to
            // instantiation.
            const xc = try w.xsumOf(try w.cellCond(e.cell), frame, params, if (own and w.cells.items[e.cell].kind != .taken) e.cell else none);
            const sc = try w.xsumOf(try w.spineAt(&spines, e), frame, params, if (own and w.cells.items[e.cell].kind != .taken) e.cell else none);
            // §31.4 item 6: its record condition, in the record table.
            const rxc = try w.rxsumOf(try w.rcellCond(e.cell), frame, params, if (own and w.cells.items[e.cell].kind != .taken) e.cell else none);
            try res.append(keep, .{ .path = e.path, .prov = prov, .approx = e.approx != 0, .xc = xc, .sc = sc, .rxc = rxc, .grown = e.grown });
        }
        // §31.7: what the result holds of records, apart from `res`, which
        // every list's fact reads.
        var objs: std.ArrayList(ResEntry) = .empty;
        // §31.7: the result's record objects, which no list's fact reads:
        // a record literal's or a call's object, numbered from a base of its
        // own (`obj_fresh_base`), one number per object in the order the walk
        // first meets it, so that one object at two paths, `( r, r )`, is
        // one; an update's or a parameter's, as the provenance of the record
        // it was written over. The supplies' records share the numbering. Not
        // after `renum`, whose largest number moves while a recursive group's
        // rounds settle: there one object took a new number each round, and
        // the join never settled.
        var obj_next: u32 = obj_fresh_base;
        w.obj_gen += 1;
        {
            for (try w.expand(result)) |e| {
                if (w.listFacing(e.cell) != null) continue;
                const x = w.cells.items[e.cell];
                const base_cell = if (x.kind == .except) x.a else e.cell;
                const bx = w.cells.items[base_cell];
                var prov: Prov = switch (bx.kind) {
                    .site, .result => .{ .kind = if (try w.isEscaped(base_cell)) .esc else .fresh, .a = try w.objectNumber(&obj_next, base_cell) },
                    .closure, .func => continue,
                    .param, .env, .shared, .top, .cbres, .taken, .payload, .except => (try w.provOf(base_cell, frame, params, fresh)) orelse continue,
                };
                prov.taken = false;
                // The object alone where the result's fields are entries of
                // their own: an update's, a literal's, a call's; a record of
                // numbers held whole is its provenance, whole.
                prov.obj = x.kind == .except or bx.kind == .site or bx.kind == .result;
                const rown = w.paramIndex(w.cells.items[try w.takenBase(base_cell)], frame, params) != null and bx.kind != .taken;
                const rxc = try w.rxsumOf(try w.rcellCond(base_cell), frame, params, if (rown) base_cell else none);
                try objs.append(keep, .{ .path = e.path, .prov = prov, .approx = e.approx != 0, .rxc = rxc, .grown = e.grown });
            }
        }
        // Function parameters.
        var funs: std.ArrayList(FunFacts) = .empty;
        var supply: std.ArrayList(SupplyEntry) = .empty;
        var rsupply: std.ArrayList(SupplyEntry) = .empty;
        // The `returns owned` atoms the owned bits rest on (§16.7).
        var atoms: std.ArrayList([2]u32) = .empty;
        if (frame == 0) {
            for (w.fn_state.items, 0..) |st, j| {
                if (!st.is_fn) continue;
                var need = st.need;
                var edit = st.need_edit;
                var rneed = st.rneed;
                for (w.demands.items) |rec| {
                    if (rec.kind == .probe or rec.kind == .value) continue;
                    // §31.5: a record written that πⱼ returned must be one
                    // the caller owns, as a list must (`need`).
                    if (rec.fields != null) {
                        for (rec.cells) |e| {
                            const c = w.cells.items[try w.takenBase(e.cell)];
                            if (c.kind == .cbres and w.callbackFrame(c) == 0 and c.a == j) rneed = true;
                        }
                        continue;
                    }
                    for (rec.cells) |e| {
                        // A taken element stands for the cell it was taken
                        // from (§18.5), which may be what πⱼ returned.
                        const c = w.cells.items[try w.takenBase(e.cell)];
                        if (c.kind == .cbres and w.callbackFrame(c) == 0 and c.a == j) {
                            need = true;
                            if (!rec.deep) edit = true;
                        }
                    }
                }
                try funs.append(keep, .{ .param = @intCast(j), .calls = st.calls, .need_if = try keep.dupe(u32, st.need_if.items), .need = need, .rneed = rneed, .seen = st.seen, .send = st.send, .sends = need and !edit });
            }
        } else {
            // A lambda's own function parameters: its class does not follow
            // them (§16.5).
            for (params, 0..) |p, k| {
                const v = w.patternType(p) orelse continue;
                if (isFunc(w.store, v)) try funs.append(keep, .{ .param = @intCast(k), .calls = .many, .seen = false });
            }
        }
        for (w.supplies.items) |sr| {
            if (sr.frame != frame) continue;
            var more_ok = true;
            var more_approx = true;
            for (sr.more) |p| if (p != none) {
                more_ok = more_ok and w.probe_ok.items[p];
                more_approx = more_approx and w.probe_approx.items[p];
            };
            const owned_probe = sr.owned and more_ok and (sr.probe == none or w.probe_ok.items[sr.probe]) and (sr.probe2 == none or w.probe_ok.items[sr.probe2]);
            const probe_approx = if (!sr.owned) sr.approx else (sr.probe != none or sr.probe2 != none or sr.more.len != 0) and more_approx and (sr.probe == none or w.probe_approx.items[sr.probe]) and (sr.probe2 == none or w.probe_approx.items[sr.probe2]);
            const xc = try w.xsumOf(sr.cond, frame, params, none);
            const rxc = try w.rxsumOf(sr.rcond, frame, params, none);
            for (try w.listView(try w.expand(sr.av))) |e| {
                // A cell made here keeps the number the result gives it,
                // renumbered as the result's entries are (0 when the
                // result does not hold it): a callback that keeps it then
                // keeps the list the result returns (#281).
                var prov = (try w.provOf(e.cell, frame, params, fresh)) orelse continue;
                if ((prov.kind == .fresh or prov.kind == .esc) and prov.a > 0) prov.a = renum[prov.a - 1];
                if (sr.taken and prov.kind == .param) prov.taken = true;
                const owned = owned_probe and prov.kind != .shared and prov.kind != .top and prov.kind != .esc and prov.kind != .env;
                if (prov.kind == .cb and owned) {
                    const atom: [2]u32 = .{ prov.a, prov.path };
                    for (atoms.items) |x| {
                        if (x[0] == atom[0] and x[1] == atom[1]) break;
                    } else try atoms.append(w.a, atom);
                }
                // Shared is the position rule, exact; ⊤, an escape and a
                // capture are limits, as is a probe that failed only
                // through one.
                const approx = !owned and switch (prov.kind) {
                    .shared => false,
                    .top, .esc, .env => true,
                    else => probe_approx or e.approx != 0,
                };
                try supply.append(keep, .{ .fun = sr.fun, .k = sr.k, .path = try w.o.concat(sr.path, e.path), .prov = prov, .owned = if (prov.condition_only) true else owned, .approx = approx, .xc = if (prov.condition_only) try w.xsumOf(try w.cellCond(e.cell), frame, params, none) else xc, .sc = if (prov.condition_only) try w.xsumOf(try w.cellSpine(e.cell), frame, params, none) else .{}, .rxc = if (prov.condition_only) try w.rxsumOf(try w.rcellCond(e.cell), frame, params, none) else rxc, .grown = e.grown });
            }
            // §31.5: the records it supplies, which no list's fact reads:
            // as `objs` names a result's, by the provenance of the record
            // each object was written over, owned where the record probe
            // held.
            const rowned_probe = sr.owned and more_ok and sr.rprobe != none and w.probe_ok.items[sr.rprobe];
            for (try w.expand(sr.av)) |e| {
                if (w.listFacing(e.cell) != null) continue;
                const x = w.cells.items[e.cell];
                const base_cell = if (x.kind == .except) x.a else e.cell;
                const bx = w.cells.items[base_cell];
                switch (bx.kind) {
                    .closure, .func => continue,
                    else => {},
                }
                var prov: Prov = switch (bx.kind) {
                    .site, .result => .{ .kind = if (try w.isEscaped(base_cell)) .esc else .fresh, .a = try w.objectNumber(&obj_next, base_cell) },
                    else => (try w.provOf(base_cell, frame, params, fresh)) orelse continue,
                };
                if (sr.taken and prov.kind == .param) prov.taken = true;
                prov.obj = x.kind == .except or bx.kind == .site or bx.kind == .result;
                const owned = rowned_probe and prov.kind != .shared and prov.kind != .top and prov.kind != .esc and prov.kind != .env;
                const approx = !owned and switch (prov.kind) {
                    .shared => false,
                    .top, .esc, .env => true,
                    else => (sr.rprobe != none and w.probe_approx.items[sr.rprobe]) or e.approx != 0,
                };
                try rsupply.append(keep, .{ .fun = sr.fun, .k = sr.k, .path = try w.o.concat(sr.path, e.path), .prov = prov, .owned = owned, .approx = approx, .rxc = rxc, .grown = e.grown });
            }
        }
        // §18.4: what the frame relied on.
        var xreq: std.ArrayList(XAtom) = .empty;
        for (w.reqs.items) |r| {
            if (r.frame != frame) continue;
            _ = try w.xatomsOf(r.atom, frame, params, true, &xreq);
        }
        // §31.4 item 6: what it relied on of records.
        var rxreq: std.ArrayList(XAtom) = .empty;
        for (w.rreqs.items) |r| {
            if (r.frame != frame) continue;
            _ = try w.xatomsOf(r.atom, frame, params, true, &rxreq);
        }
        if (atoms.items.len > atom_cap) return w.o.pessimistic(.{ .params = @intCast(params.len), .funs = funs.items }, .owned_atoms, @intCast(atoms.items.len));
        const signature = if (frame == 0 and w.cast_open_used and (w.hasOpenCast([]const UseEntry, uses.items) or w.hasOpenCast([]const ResEntry, res.items) or w.hasOpenCast([]const ResEntry, objs.items) or w.hasOpenCast([]const SupplyEntry, supply.items) or w.hasOpenCast([]const SupplyEntry, rsupply.items) or w.hasOpenCast([]const XAtom, xreq.items) or w.hasOpenCast([]const XAtom, rxreq.items) or w.hasOpenCast([]const Carried, klasses.items))) try w.castDeclSignature() else none;
        return w.o.normalize(.{
            .params = @intCast(params.len),
            .cast_signature = signature,
            .uses = uses.items,
            .res = res.items,
            .objs = objs.items,
            .supply = supply.items,
            .rsupply = rsupply.items,
            .funs = funs.items,
            .xreq = xreq.items,
            .rxreq = rxreq.items,
            .slots = if (frame == 0) try keep.dupe([2]u32, w.slot_keys.items) else &.{},
            .klasses = klasses.items,
        });
    }

    /// The provenance a cell is read off as (thesis §4.4).
    fn provOf(w: *Walker, cell_id: u32, frame: u32, params: []const Inst.Index, fresh: Fresh) Allocator.Error!?Prov {
        var p = (try w.provOfRaw(cell_id, frame, params, fresh)) orelse return null;
        p.condition_only = w.cells.items[cell_id].condition_only;
        return p;
    }

    fn provOfRaw(w: *Walker, cell_id: u32, frame: u32, params: []const Inst.Index, fresh: Fresh) Allocator.Error!?Prov {
        const c = w.cells.items[cell_id];
        switch (c.kind) {
            .param => {
                if (w.paramIndex(c, frame, params)) |pi| return .{ .kind = .param, .a = pi, .path = c.path };
                return .{ .kind = .top };
            },
            .site, .result => {
                const k: u32 = if (fresh.indexOf(cell_id)) |i| @intCast(i + 1) else 0;
                return .{ .kind = if (try w.isEscaped(cell_id)) .esc else .fresh, .a = k };
            },
            .env => {
                if (frame == 0) return .{ .kind = .top };
                return .{ .kind = .env, .a = c.a, .path = c.path };
            },
            .shared => return .{ .kind = .shared, .a = c.a, .b = c.b, .path = c.path },
            // `a` 1: a ⊤ a pessimistic summary made (§16.7).
            .top => return .{ .kind = .top, .a = c.a },
            // A message, which only the entry computation names (§20.5).
            .payload => return .{ .kind = .top },
            .cbres => {
                const owner = w.callbackFrame(c);
                if (owner == frame) return .{ .kind = .cb, .a = c.a, .path = c.path };
                // A declaration callback called inside a lambda (§18.9).
                if (owner == 0) return .{ .kind = .cb, .a = c.a, .b = 1, .path = c.path };
                return .{ .kind = .top, .a = top_call };
            },
            // The element it stands for, taken (§18.5).
            .taken => {
                var p = (try w.provOf(try w.takenBase(cell_id), frame, params, fresh)) orelse return null;
                if (p.kind == .param) p.taken = true;
                return p;
            },
            // §31.2: the record cell it was written over; the object alone
            // reaches no summary until §31.7's.
            .except => return if (c.b == except_all) null else try w.provOf(c.a, frame, params, fresh),
            .closure, .func => return null,
        }
    }
};

test "write extents preserve unknown loans and join deep over storage" {
    const gpa = std.testing.allocator;
    var o: Ownership = .init(.{
        .gpa = gpa,
        .graph = undefined,
        .birs = &.{},
        .provenance = &.{},
        .dispatch = &.{},
        .modules = &.{},
        .types = undefined,
        .interner = undefined,
        .module_names = &.{},
        .packages = &.{},
        .spans = &.{},
        .positions = undefined,
        .canonical = false,
    });
    defer o.deinit();
    try o.seedPaths();
    const elem = try o.child(eps, .elem, 0);
    const any = try o.child(eps, .any, 0);
    try std.testing.expect(!o.writeOverlap(eps, elem, .storage));
    try std.testing.expect(o.writeOverlap(eps, elem, .deep));
    try std.testing.expect(o.writeOverlap(eps, any, .storage));
    try std.testing.expect(o.writeOverlap(elem, eps, .storage));
    try std.testing.expect(o.writeOverlap(elem, elem, .storage));
    const storage: UseEntry = .{ .param = 0, .path = eps, .bits = bit_w | bit_x, .extent = .storage };
    const deep: UseEntry = .{ .param = 0, .path = eps, .bits = bit_w | bit_x };
    const read: UseEntry = .{ .param = 0, .path = eps, .bits = bit_r };
    const joined = try o.normalize(.{ .params = 1, .uses = &.{ storage, read, deep } });
    try std.testing.expectEqualDeep(&[_]UseEntry{.{ .param = 0, .path = eps, .bits = bit_w | bit_x | bit_r, .extent = .deep }}, joined.uses);
    const read_storage = try o.normalize(.{ .params = 1, .uses = &.{ read, storage } });
    try std.testing.expectEqualDeep(&[_]UseEntry{.{ .param = 0, .path = eps, .bits = bit_w | bit_x | bit_r, .extent = .storage }}, read_storage.uses);
}

test "full cast type keys validate complete child terms" {
    const a = std.testing.allocator;
    for ([_][]const u8{
        "1:List::List(15:1:Basics::Int())",
        "1:List::List(18:1:String::String())",
        "fn(15:1:Basics::Int()→4:unit)",
        "record(1:x=15:1:Basics::Int()|2:{})",
        "var(0:Main:2:0)",
    }) |key| try validateCastKey(a, key);
    for ([_][]const u8{
        "",                                           "List",               "1:List::List(99:unit)",
        "tuple(999999999999999999999999999999:unit)", "tuple(4:nope)",      "var(9:Main:2:0)",
        "var(0:Main:2)",                              "record(1:x=4:unit)", "fn(4:unit)",
        "fn(→4:unit4:unit)",
        "error",
    }) |key| try std.testing.expectError(error.Bad, validateCastKey(a, key));
}

test "full cast DAG keys preserve portable variables and shared type structure" {
    const a = std.testing.allocator;
    var o = Ownership.init(.{
        .gpa = a,
        .graph = undefined,
        .birs = &.{},
        .provenance = &.{},
        .dispatch = &.{},
        .modules = &.{},
        .types = undefined,
        .interner = undefined,
        .module_names = &.{},
        .packages = &.{},
        .spans = &.{},
        .positions = undefined,
    });
    defer o.deinit();
    const schema_member = try o.readCastId("0:Foo::Bar.Type()", &.{});
    const nested_module = try o.readCastId("0:Foo.Bar::Type()", &.{});
    try std.testing.expect(schema_member != nested_module);
    const v = try o.readCastId("var(0:M:0:0)", &.{});
    const u = try o.readCastId("var(0:M:0:1)", &.{});
    const tuple = try o.readCastId("tuple(2:@02:@0)", &.{v});
    try std.testing.expectEqual(tuple, try o.readCastId("tuple(2:@12:@1)", &.{ u, v }));
    try std.testing.expect(tuple != try o.readCastId("tuple(2:@02:@0)", &.{u}));
    try std.testing.expectEqualStrings("tuple(12:var(0:M:0:0)12:var(0:M:0:0))", try o.castText(tuple));
    try std.testing.expectError(error.Bad, o.readCastId("tuple(2:@1)", &.{v}));
    try std.testing.expectError(error.Bad, o.readCastId("tuple(3:@-1)", &.{v}));
    try std.testing.expectError(error.Bad, o.readCastId("tuple(4:unit)", &.{}));
    try std.testing.expectError(error.Bad, o.readCastId("@0", &.{v}));
    // Uncertain substitutions cannot become the caller's exact variable,
    // including when that variable is also the callee's at recursion.
    var w: Walker = undefined;
    w.o = &o;
    w.a = o.keep.allocator();
    const closed = try o.castId("0:Basics::Int()");
    const wild = try o.castId("⋆");
    var bindings: Walker.CastBindings = .empty;
    try w.bindCast(v, wild, &bindings);
    try w.bindCast(v, closed, &bindings);
    try std.testing.expectEqual(wild, bindings.items[0][1]);
    try w.bindCast(v, v, &bindings);
    try std.testing.expectEqual(wild, bindings.items[0][1]);
    bindings.clearRetainingCapacity();
    try w.bindCast(v, closed, &bindings);
    try w.bindCast(v, wild, &bindings);
    try std.testing.expectEqual(wild, bindings.items[0][1]);
    const unit = try o.castId("unit");
    const sig = try o.readCastId("fn(2:@0→2:@1)", &.{ v, unit });
    const folded_sig = try o.readCastId("fn(2:@0→2:@1)", &.{ wild, unit });
    w.cast_fold_scope = 1;
    w.cast_fold_paths = .empty;
    w.cast_fold_types = .empty;
    try w.cast_fold_types.put(w.a, .{ .scope = 1, .id = sig }, folded_sig);
    const prototype: Summary = .{ .params = 1, .cast_signature = sig, .res = &.{.{ .path = eps, .prov = .{ .kind = .param }, .grown = 1 }} };
    const first = try w.foldCastRows(Summary, prototype, true);
    try std.testing.expectEqual(sig, first.cast_signature);
    try std.testing.expect(gMarked(first.cast_grown));
    const later = try w.foldCastRows(Summary, first, true);
    try std.testing.expectEqual(folded_sig, later.cast_signature);
    // A linear DAG describes an exponentially expanded tree. Interning it
    // never needs that expansion; both children retain their complete type.
    var last = v;
    for (0..64) |_| last = try o.readCastId("tuple(2:@02:@0)", &.{last});
    try std.testing.expect(last != tuple);
    try std.testing.expect(o.cast_open.items[last]);
}

test "a folded cast read retains an incompatible concrete holder" {
    const gpa = std.testing.allocator;
    var arena: std.heap.ArenaAllocator = .init(gpa);
    defer arena.deinit();
    var o = Ownership.init(.{
        .gpa = gpa,
        .graph = undefined,
        .birs = &.{},
        .provenance = &.{},
        .dispatch = &.{},
        .modules = &.{},
        .types = undefined,
        .interner = undefined,
        .module_names = &.{},
        .packages = &.{},
        .spans = &.{},
        .positions = undefined,
    });
    defer o.deinit();
    try o.seedPaths();
    var w: Walker = .{ .o = &o, .m = 0, .bir = undefined, .decl = std.mem.zeroes(Bir.Decl), .decl_index = 0, .store = undefined, .inst_type = &.{}, .local_type = &.{}, .a = arena.allocator(), .mode = .summary };
    try w.cells.append(w.a, .{ .kind = .site, .a = 0 });
    const target = try o.castId("unit");
    const other = try o.castId("{}");
    const path = try o.child(try o.child(eps, .cast, other), .tuple, 0);
    const result = try w.readCastLevel(&.{.{ .path = path, .cell = 0 }}, target);
    try std.testing.expectEqual(@as(usize, 1), result.len);
    try std.testing.expectEqual(@as(u32, 0), result[0].cell);
    try std.testing.expect(result[0].approx != 0);
    try std.testing.expectEqual(try o.child(eps, .any, 1), result[0].path);
}

test "repeated wide projections retain every cast holder" {
    const gpa = std.testing.allocator;
    var arena: std.heap.ArenaAllocator = .init(gpa);
    defer arena.deinit();
    var o = Ownership.init(.{
        .gpa = gpa,
        .graph = undefined,
        .birs = &.{},
        .provenance = &.{},
        .dispatch = &.{},
        .modules = &.{},
        .types = undefined,
        .interner = undefined,
        .module_names = &.{},
        .packages = &.{},
        .spans = &.{},
        .positions = undefined,
    });
    defer o.deinit();
    try o.seedPaths();
    var w: Walker = .{ .o = &o, .m = 0, .bir = undefined, .decl = std.mem.zeroes(Bir.Decl), .decl_index = 0, .store = undefined, .inst_type = &.{}, .local_type = &.{}, .a = arena.allocator(), .mode = .summary };
    try w.cells.append(w.a, .{ .kind = .site, .a = 0 });
    const id = try o.castId("unit");
    const entries = try w.a.alloc(Entry, wide_index);
    for (entries, 0..) |*e, i| e.* = .{ .path = try o.child(eps, .cast, id), .cell = @intCast(i) };
    for (1..wide_index) |i| try w.cells.append(w.a, .{ .kind = .site, .a = @intCast(i) });
    const step: Step = .{ .kind = .tuple, .arg = 0 };
    const first = try w.projFirst(entries, step);
    const second = try w.projFirst(entries, step);
    try std.testing.expectEqual(wide_index, first.len);
    try std.testing.expectEqualDeep(first, second);
}
test "a repeated cast read includes a nested boundary behind another full type" {
    const gpa = std.testing.allocator;
    var arena: std.heap.ArenaAllocator = .init(gpa);
    defer arena.deinit();
    var o = Ownership.init(.{
        .gpa = gpa,
        .graph = undefined,
        .birs = &.{},
        .provenance = &.{},
        .dispatch = &.{},
        .modules = &.{},
        .types = undefined,
        .interner = undefined,
        .module_names = &.{},
        .packages = &.{},
        .spans = &.{},
        .positions = undefined,
    });
    defer o.deinit();
    try o.seedPaths();
    var w: Walker = .{ .o = &o, .m = 0, .bir = undefined, .decl = std.mem.zeroes(Bir.Decl), .decl_index = 0, .store = undefined, .inst_type = &.{}, .local_type = &.{}, .a = arena.allocator(), .mode = .summary };
    try w.cells.append(w.a, .{ .kind = .site, .a = 0 });
    const unit = try o.castId("unit");
    const empty = try o.castId("{}");
    const outer_type = try o.readCastId("tuple(2:@02:@0)", &.{unit});
    const target = try o.readCastId("tuple(2:@02:@1)", &.{ unit, empty });
    const outer = try o.child(eps, .cast, outer_type);
    const path = try o.child(try o.child(outer, .tuple, 0), .cast, target);
    const result = try w.readCastLevel(&.{.{ .path = path, .cell = 0 }}, target);
    const nested = eps;
    for (result) |entry| {
        try std.testing.expect(entry.approx != 0);
        if (entry.path == nested) return;
    }
    return error.MissingNestedCastHolder;
}
